INSERT INTO texts VALUES(483,'平行瞬移',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了超能族怪獸以外不能特殊召喚。\u000a①：將我方場上1隻持有等級的超能族怪獸解放可以發動。從牌組、額外牌組將1隻等級7以下的超能族怪獸特殊召喚。解放的怪獸和此效果特殊召喚的怪獸的原等級不同的場合，隨後我方失去那個差額×1000生命值。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511,'拉比麗斯的狂時鐘',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。這個回合，我方場上有「拉比麗斯」怪獸存在的場合，我方可以將1張通常陷阱卡在覆蓋的回合發動。此效果在對手回合也能發動。\u000a②：此卡在墓地存在的狀態，我方為了發動「拉比麗斯的狂時鐘」以外的「拉比麗斯」卡片的效果或通常陷阱卡，而讓手牌的卡被送去墓地的場合可以發動。此卡加入手牌或特殊召喚。\u000a\u000a※白銀之城的狂時鐘'),'效果1','效果2','適用「拉比麗斯的狂時鐘」的效果來發動','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000,'萬物創世龍',unistr('此卡不能通常召喚。只能解放攻擊力的總和以及守備力的總和相加為10000以上的我方場上的怪獸來特殊召喚。\u000a①：這個方法特殊召喚的此卡的攻擊力、守備力變成10000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27551,'限制再生','選擇我方墓地的1隻攻擊力1000以下的怪獸，表側攻擊表示特殊召喚。那隻怪獸變成守備表示時，那隻怪獸和此卡破壞。此卡從場上離開時，那隻怪獸破壞。那隻怪獸被破壞時，此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32864,'第13位埋葬者','從無人的13號墳墓突然出現的殭屍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35699,'SPYRAL-龍捲風',unistr('此卡不能通常召喚。只能將我方墓地的3張「SPYRAL」卡片除外來特殊召喚。\u000a①：1回合1次，以我方場上1張「SPYRAL」卡片和對手場上最多2張卡為對象可以發動。那些卡破壞。此效果在對手回合也能發動。\u000a②：場上的此卡被戰鬥、效果破壞送去墓地的場合發動。我方場上的卡全部破壞，從我方的手牌、牌組、墓地選1隻「SPYRAL-花花公子」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39015,'爆裂狙擊手',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：解放此卡可以發動。從手牌、牌組將「爆裂狙擊手」以外的1隻記載「爆裂模式」的卡名的怪獸特殊召喚。此效果發動過的回合，我方除了同步怪獸以外不能從額外牌組特殊召喚。\u000a②：以我方場上1隻表側表示怪獸為對象可以發動。向對手展示額外牌組的1隻同步怪獸，對象怪獸的種族、屬性直到回合結束時變成和展示的怪獸相同。'),'特殊召喚','改變種族、屬性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41546,'DD魔導賢者 湯瑪斯',unistr('【靈擺效果】\u000a「DD魔導賢者 湯瑪斯」的靈擺效果1回合只能使用1次。\u000a①：我方主要階段可以發動。從我方的額外牌組將1隻表側表示的「DD」靈擺怪獸加入手牌。\u000a【怪獸效果】\u000a「DD魔導賢者 湯瑪斯」的怪獸效果1回合只能使用1次。\u000a①：以我方的靈擺區域1張「DD」卡片為對象可以發動。那張卡破壞，從牌組將1隻等級8的「DDD」怪獸守備表示特殊召喚。這個回合，此效果特殊召喚的怪獸的效果無效化，對手受到的戰鬥傷害變成一半。'),'從額外牌組加入手牌','從牌組特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41777,'寶石強化','解放我方場上的1隻「寶石騎士」怪獸，選擇我方墓地的1隻「寶石騎士」怪獸可以發動。選擇的怪獸從墓地特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43227,'後援者 馬格南',unistr('從額外牌組特殊召喚的怪獸+手牌的怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地1張「融合」魔法卡或「結合」魔法卡為對象可以發動。那張卡回到牌組最下方。那之後，我方抽1張卡。\u000a②：其他卡的效果發動時，從我方墓地將1張「融合」魔法卡或「結合」魔法卡除外，以場上1張卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44818,'聖夜騎士團 奧比泰爾',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻光屬性怪獸為對象可以發動。那隻怪獸解放，從牌組選1張「聖夜騎士團」魔法、陷阱卡在我方場上覆蓋。此效果在對手回合也能發動。\u000a②：此卡在墓地存在，我方場上的表側表示的龍族、光屬性、等級7怪獸回到手牌的場合可以發動。此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50755,'魔法師之圓','①：我方或對手的魔法使族怪獸的攻擊宣言時可以發動。雙方玩家各自從自身牌組將1隻攻擊力2000以下的魔法使族怪獸攻擊表示特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56889,'競鬥-交叉次元',unistr('①：以我方場上1隻「古代機械齒輪」怪獸為對象可以發動。那隻怪獸除外。此效果除外的怪獸在下個準備階段回到場上，其攻擊力直到那個回合結束時變成原攻擊力的2倍。\u000a②：我方場上的「古代機械齒輪巨人」或「古代機械齒輪巨人-究極重拳」被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59080,'聖魔 裁決之雷',unistr('這個卡名在規則上也當作「偉魔」卡片、「安迪米翁」卡片。\u000a①：可以將我方場上的1張其他的表側表示的「偉魔」卡片送去墓地，或是2個魔力計數器去除，從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●從我方的手牌、額外牌組（表側）、墓地將1隻魔法使族怪獸特殊召喚。\u000a●場上1張其他卡除外。'),'效果1','去除魔力計數器來發動','其他卡送去墓地來發動','●特殊召喚','●場上的卡除外','','','','','','','','','','','');
INSERT INTO texts VALUES(62121,'闇晦之城',unistr('反轉：場上的全部不死族怪獸的攻擊力、守備力上升200。\u000a此卡在場上表側表示存在期間，每次我方準備階段，那些攻擊力和守備力再上升200。此效果持續到第4次的我方準備階段。'),'反轉效果','攻守上升200','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64865,'電子界代碼魔術師',unistr('藉由「電腦網儀式」降臨\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上的連結怪獸作為電子界族連結怪獸的連結素材的場合，手牌的此卡也能作為連結素材。\u000a②：此卡從手牌、場上送去墓地的場合可以發動。從牌組將1隻電子界族怪獸送去墓地。儀式召喚的此卡被送去墓地的場合，也能不從牌組送去墓地而是特殊召喚。這個回合，我方除了電子界族怪獸以外不能特殊召喚。'),'','效果2','儀式召喚的此卡被送去墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64866,'電子界代碼魔術師',unistr('藉由「電腦網儀式」降臨\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上的連結怪獸作為電子界族連結怪獸的連結素材的場合，手牌的此卡也能作為連結素材。\u000a②：此卡從手牌、場上送去墓地的場合可以發動。從牌組將1隻電子界族怪獸送去墓地。儀式召喚的此卡被送去墓地的場合，也能不從牌組送去墓地而是特殊召喚。這個回合，我方除了電子界族怪獸以外不能特殊召喚。'),'','效果2','儀式召喚的此卡被送去墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96540,'下拍',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻表側表示怪獸解放可以發動。從牌組將1隻和解放的怪獸原本的種族、屬性相同且原等級低1級的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98905,'光波分光','①：我方場上的持有超量素材的「光波」超量怪獸被戰鬥或對手的效果破壞送去我方墓地的場合，以那1隻怪獸為對象可以發動。那隻怪獸從墓地特殊召喚，將1隻和那隻怪獸同名的超量怪獸從額外牌組特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(102380,'溶岩魔神 岩漿石魔',unistr('此卡不能通常召喚。將對手場上2隻怪獸解放可以在對手場上特殊召喚。將此卡特殊召喚的整回合中，我方不能通常召喚。\u000a①：我方準備階段發動。我方受到1000傷害。'),'在對手場上特殊召喚','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(109401,'闇次元的兵士',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：將1張手牌除外，以被除外的1隻我方的闇屬性怪獸為對象可以發動。那隻怪獸表側守備表示或裡側守備表示特殊召喚。\u000a②：我方、對手的結束階段發動。給予對手相當於場上覆蓋的卡片數量×100傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(111280,'黑之魔導強化',unistr('①：依照雙方的場上、墓地的「黑魔導」「黑魔導女孩」的數量適用以下效果。\u000a●1隻以上：選場上1隻魔法使族、闇屬性怪獸，那個攻擊力直到回合結束時上升1000。\u000a●2隻以上：這個回合，應對我方的魔法、陷阱卡的效果的發動，對手不能發動魔法、陷阱、怪獸的效果，我方場上的魔法、陷阱卡不會被對手的效果破壞。\u000a●3隻以上：我方場上的魔法使族、闇屬性怪獸直到回合結束時不受對手的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(114932,'粉碎劍士','將我方場上1張表側表示的永續魔法或永續陷阱卡送去墓地可以發動。給予對手500傷害。這個效果1回合可以使用最多2次。','給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(122520,'娛樂夥伴 天空徒弟',unistr('「娛樂夥伴 天空徒弟」的①效果1回合只能使用1次。\u000a①：讓我方場上1隻等級5以上的「娛樂夥伴」怪獸回到持有者的手牌可以發動。此卡從手牌特殊召喚。此效果在對手回合也能發動。\u000a②：此卡和對手怪獸進行戰鬥的場合，直到傷害步驟結束時那隻怪獸的效果無效化。\u000a③：我方場上有其他「娛樂夥伴」怪獸存在的場合，此卡向對手怪獸攻擊的傷害計算前可以發動。那隻對手怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(123709,'熔岩槍杖手',unistr('此卡可以不用解放來召喚。\u000a結束階段時，這個方法召喚的此卡送去墓地。\u000a場上的此卡被破壞送去墓地時，可以選擇被除外的1隻我方的炎屬性怪獸加入手牌。'),'不解放的召喚','此卡送去墓地','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(126218,'魔鬼的骰子','①：擲1次骰子。對手場上的怪獸的攻擊力、守備力直到回合結束時下降擲出點數×100。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(128454,'娛樂夥伴 彈簧鵝',unistr('「娛樂夥伴 彈簧鵝」的效果1回合只能使用1次。\u000a①：我方主要階段將墓地的此卡除外，以我方的靈擺區域的「魔術師」卡片、「娛樂夥伴」卡片和我方場上的靈擺怪獸其中2張卡為對象可以發動。那2張卡回到持有者的手牌。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(131182,'奇蹟翻轉師',unistr('我方場上有「奇蹟翻轉師」存在的場合，此卡不能召喚、反轉召喚、特殊召喚。\u000a只要此卡在場上表側表示存在，對手不能選擇其他的表側表示怪獸作為攻擊對象。\u000a此卡被戰鬥破壞的戰鬥階段結束時，此卡在對手場上特殊召喚。\u000a此卡被魔法、陷阱的效果破壞的場合，選擇對手場上的1隻怪獸破壞。\u000a[按照判例修正]'),'特殊召喚','對方場上1隻怪獸破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(132308,'六花的白姬',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。此卡從手牌特殊召喚。只要此效果特殊召喚的此卡在怪獸區域表側表示存在，我方除了植物族怪獸以外不能特殊召喚。\u000a②：我方場上有「六花」怪獸存在，對手發動怪獸的效果時，讓手牌、墓地的此卡回到牌組，將我方場上1隻植物族解放可以發動。那個發動的效果無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(135598,'鑰匙鼠','此卡被戰鬥破壞送去墓地時，可以從我方牌組將1隻等級3以下的獸族怪獸加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(146746,'機關重連 憤怒鈎舌',unistr('機械族怪獸2隻\u000a這個卡名的①②效果1回合只有1次能使用其中1個。此卡不能作為連結素材。\u000a①：我方、對手的主要階段，將我方的手牌、場上1隻怪獸送去墓地，以我方墓地1隻機械族、等級10怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。\u000a②：此卡在墓地存在的場合，將我方的手牌、場上1張卡送去墓地可以發動。此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(164710,'小人的惡作劇',unistr('①：這個回合，雙方的手牌的怪獸的等級下降1。\u000a②：將墓地的此卡除外可以發動。這個回合，雙方的手牌的怪獸的等級下降1。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(168917,'大日神械錯合體','1回合1次，可以選擇我方場上1隻當作裝備卡的「大日神械」怪獸卡表側守備表示特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(176392,'核成實驗台',unistr('場上表側表示存在的「核成」怪獸在結束階段被破壞的場合，可以將此卡破壞作為代替。\u000a場上表側表示存在的「核成」怪獸在結束階段被破壞時，可以在我方場上將1隻「核成衍生物」（岩石族、地、等級4、攻/守1800）特殊召喚。'),'N/A','特殊召喚衍生物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(176393,'核成衍生物','由「核成實驗台」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(191749,'英雄閃光！！','將我方墓地的「H-火熱之心」「E-緊急呼叫」「R-公平正義」「O-超越靈魂」除外可以發動。從我方牌組將1隻「E.HERO」通常怪獸特殊召喚。這個回合，我方場上的「E.HERO」通常怪獸可以直接攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(197042,'驅魔修女連禱',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的怪獸只有「驅魔修女」怪獸的場合，支付800生命值，以對手的場上、墓地1張卡為對象可以發動。那張卡除外。那之後，可以從以下效果挑選1個適用。\u000a●進行1隻「驅魔修女」超量怪獸的超量召喚。\u000a●如果這個回合我方已將怪獸超量召喚，將對手場上1張卡除外。'),'●超量召喚','●對手場上1張卡除外','都不選擇','','','','','','','','','','','','','');
INSERT INTO texts VALUES(209710,'滑屏小丑',unistr('這個卡名的效果1回合只能使用1次。\u000a①：我方場上有此卡以外的2隻以上電子界族怪獸存在，我方的手牌是0張的場合，支付1000生命值可以發動。我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(212652,'毒蠍的陷阱','①：對手怪獸的直接攻擊宣言時可以發動。那隻怪獸破壞。那之後，給予對手300傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(213326,'E-緊急呼叫','①：從牌組將1隻「E.HERO」怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(218704,'芬里爾',unistr('此卡不能通常召喚。將我方墓地的2隻水屬性怪獸除外可以特殊召喚。\u000a此卡戰鬥破壞對手怪獸的場合，跳過下個對手回合的抽牌階段。'),'跳過抽牌階段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(220414,'娛樂夥伴 掉頭跑騎兵',unistr('①：我方戰鬥階段開始時可以發動。給此卡放置1個計數器（最多2個）。\u000a②：依照此卡的計數器數量，此卡得到以下效果。\u000a●1個：1回合1次，對手怪獸的攻擊宣言時可以發動。那次攻擊無效。\u000a●2個：解放此卡可以發動。場上的全部怪獸直到發動後第2次的對手結束階段除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(242146,'破壞城壁的大槍','裝備怪獸攻擊裡側守備表示怪獸的場合，裝備怪獸的攻擊力只在傷害計算時上升1500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(255998,'迅速戰士','只能在主要階段1發動。這個回合此卡可以直接攻擊對手玩家。此效果發動的整回合中，此卡以外的怪獸不能攻擊。','直接攻擊','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(259314,'甲蟲裝機的手甲','發動後此卡當作守備力上升1000的裝備卡給我方場上的1隻「甲蟲裝機」怪獸裝備。裝備怪獸不會被對手的效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(263926,'獨法師',unistr('我方場上有怪獸存在的場合，此卡不能召喚、特殊召喚。\u000a①：此卡可以從手牌攻擊表示特殊召喚。\u000a②：此卡已在怪獸區域存在的狀態，我方場上有此卡以外的怪獸召喚、反轉召喚、特殊召喚的場合發動。此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(269012,'縛神塚',unistr('①：場上的等級10以上的怪獸不會成為效果的對象，不會被效果破壞。\u000a②：我方或對手的等級10以上的怪獸戰鬥破壞怪獸送去墓地的場合發動。破壞的怪獸的控制者受到1000傷害。\u000a③：場上的此卡被效果破壞送去墓地時可以發動。從牌組將1隻神屬性怪獸加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(269510,'天火的牢獄',unistr('①：場上的龍族怪獸的守備力上升300。\u000a②：雙方不能將連結標記數量比場上的連結怪獸少的連結怪獸連結召喚，連結怪獸以外的怪獸不能攻擊。\u000a③：場上有2隻以上電子界族連結怪獸存在的場合，適用以下效果。\u000a●電子界族怪獸發動的效果無效化。\u000a●場上的電子界族怪獸不能攻擊，不會成為攻擊對象，也不會成為效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(276357,'靈魂鳥之圓環',unistr('「靈魂鳥之圓環」的①②效果1回合各能使用1次。\u000a①：此卡在魔法與陷阱區域存在，我方場上的表側表示的靈魂怪獸回到我方的手牌的場合，以對手場上1張卡為對象可以發動。那張卡破壞。\u000a②：對手怪獸的攻擊宣言時，將我方墓地1隻靈魂怪獸除外可以發動。那次攻擊無效，那之後戰鬥階段結束。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(282886,'水精鱗-邃淵象鼻魚兵','此卡戰鬥破壞對手怪獸送去墓地時，將手牌的1隻水屬性怪獸捨棄到墓地可以發動。從牌組將1隻「水精鱗」怪獸表側守備表示特殊召喚。「水精鱗-邃淵象鼻魚兵」的效果1回合只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(284224,'雙天將 密跡',unistr('「雙天腳的鴻鵠」+「雙天」怪獸×2\u000a這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方的「雙天」融合怪獸在1回合各有1次不會被戰鬥破壞。\u000a②：1回合1次，我方主要階段可以發動。對手場上的魔法、陷阱卡全部回到持有者的手牌。\u000a③：我方場上有融合怪獸2隻以上存在，對手場上的怪獸的效果發動時可以發動。那隻怪獸破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(286392,'噴射戰士',unistr('「噴射同步者」+協調以外的怪獸1隻以上\u000a「噴射戰士」的①②效果1回合各能使用1次。\u000a①：此卡同步召喚成功的場合，以對手場上的1張卡為對象可以發動。那張卡回到持有者的手牌。\u000a②：此卡在墓地存在的場合，解放我方場上1隻等級2以下的怪獸可以發動。此卡從墓地表側守備表示特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(291414,'聚集思念之龍',unistr('我方1回合只能特殊召喚1次「聚集思念之龍」，將此卡作為同步素材的場合，除了「救世」怪獸的同步召喚以外不能使用。\u000a①：只要此卡在場上、墓地存在，卡名當作「救世龍」。\u000a②：此卡被抽到時，向對手展示此卡可以發動。此卡從手牌特殊召喚。我方場上有等級8以上的龍族同步怪獸存在的場合，隨後可以從牌組將1隻龍族、等級1怪獸特殊召喚。'),'效果2','是否從牌組特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(293542,'T.G. 狼人',unistr('①：等級4以下的怪獸特殊召喚時可以發動。此卡從手牌特殊召喚。\u000a②：場上的此卡被破壞送去墓地的回合的結束階段可以發動。從牌組將「T.G. 狼人」以外的1隻「T.G.」怪獸加入手牌。'),'特殊召喚','檢索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(295517,'傳說之都 亞特蘭提斯',unistr('這個卡名在規則上當作「海」。\u000a①：場上的水屬性怪獸的攻擊力、守備力上升200。\u000a②：只要此卡在場地區域存在，雙方的手牌、場上的水屬性怪獸的等級下降1。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(296499,'一族之規',unistr('此卡的控制者在每次我方準備階段解放1隻怪獸，或不解放讓此卡破壞。\u000a宣言1個種族可以發動此卡。那個種族的怪獸不能攻擊宣言。'),'是否解放怪獸來維持此卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(298846,'花樣明星 秋水仙',unistr('連結怪獸以外的「花樣明星」怪獸1隻\u000a我方1回合只能特殊召喚1次「花樣明星 秋水仙」，那個效果1回合只能使用1次。\u000a①：此卡在墓地存在的狀態，我方的「花樣明星」怪獸的戰鬥讓怪獸被破壞時，將此卡除外，以那1隻被破壞的怪獸為對象可以發動。給予對手那隻怪獸的攻擊力數值的傷害。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(303660,'電腦增幅器',unistr('只能給「人造人-念力震懾者」裝備。此卡的發動和效果不會被無效化。\u000a①：裝備怪獸持有的「雙方不能發動場上的陷阱卡的效果，場上的陷阱卡的效果無效化」效果當作「對手不能發動場上的陷阱卡的效果，對手場上的陷阱卡的效果無效化」適用。\u000a②：此卡從場上離開時裝備怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(313513,'魔法的齒輪','①：將我方場上3張表側表示的「古代機械齒輪」卡片送去墓地可以發動。從手牌和牌組各選最多1隻「古代機械齒輪巨人」無視召喚條件特殊召喚。那之後，我方場上有「古代機械齒輪巨人」以外的怪獸存在的場合，那些怪獸全部破壞。此效果的發動後，以我方回合計算的2回合內，我方不能通常召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(324483,'極炎之劍士',unistr('「炎之劍士」+「鬥氣炎斬龍」\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：以對手場上1隻怪獸為對象可以發動（此卡已裝備裝備卡的場合，此效果在對手回合也能發動）。那隻怪獸破壞，給予對手500傷害。\u000a②：此卡進行戰鬥的傷害步驟開始時可以發動。此卡的攻擊力直到回合結束時變成2倍。這個回合的結束階段，此卡破壞。'),'破壞對手怪獸','攻擊力變成2倍','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(327051,'偉魔祆現',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地1隻等級4以下的「偉魔」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方的魔法與陷阱區域的「偉魔」卡片被對手的效果破壞的場合，可以將墓地的此卡除外作為代替。\u000a\u000a※絕火的祆現'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(336369,'薰風松鼠','此卡被效果破壞時，可以從我方牌組將1隻等級5以上的「薰風」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(336601,'月之守衛者',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：對手場上有2隻以上怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合，如果對手場上有怪獸存在，以「月之守衛者」以外的我方墓地1隻光屬性、等級4怪獸為對象可以發動。那隻怪獸加入手牌。'),'從手牌特殊召喚','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(340002,'娛樂夥伴 槌子巨象',unistr('①：我方場上有2張以上「娛樂夥伴」卡片存在的場合，此卡可以不用解放來召喚。\u000a②：我方場上沒有其他的「娛樂夥伴」卡片存在的場合，此卡不能攻擊。\u000a③：此卡的攻擊宣言時可以發動。對手場上的魔法、陷阱卡全部回到持有者的手牌。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(342673,'黑色魔術師-黑魔導',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：場上有「光之黃金櫃」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡只要在怪獸區域存在，卡名當作「黑魔導」。\u000a③：此卡被效果破壞的場合，如果場上有等級5以上的怪獸存在可以發動。此卡特殊召喚。那之後，可以從牌組將1張記載「黑魔導」的卡名的魔法、陷阱卡在我方場上覆蓋。'),'效果1','效果3','是否從牌組覆蓋1張卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(359563,'入魔夢魘',unistr('闇屬性等級4怪獸×2\u000a①：對手將怪獸特殊召喚時，去除此卡的1個超量素材可以發動。那些怪獸變成裡側守備表示。'),'變成裡側守備表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(365213,'光來的奇蹟',unistr('①：作為此卡的發動時的效果處理，從手牌、牌組選1隻龍族、等級1怪獸放置在牌組最上方。\u000a②：雙方不能讓場上的「星塵龍」以及記載那個卡名的同步怪獸回到額外牌組。\u000a③：同步怪獸特殊召喚的場合可以發動。從以下效果挑選1個適用。這個回合，我方的「光來的奇蹟」的效果不能適用相同效果。\u000a●我方從牌組抽1張卡。\u000a●從手牌將1隻協調特殊召喚。'),'N/A','●我方從牌組抽1張卡','●從手牌將1隻協調特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(368382,'機動霧龍 腕龍',unistr('【靈擺效果】\u000a①：此卡在靈擺區域期間只有1次，可以讓以此卡以外的我方場上的「機動霧龍」卡片為對象發動的效果無效。那之後，此卡破壞。\u000a【怪獸效果】\u000a①：我方的怪獸區域沒有「機動霧龍 腕龍」存在，場上的攻擊力最高的怪獸在對手場上存在的場合，此卡可以從手牌特殊召喚。'),'是否用「機動霧龍 腕龍」的靈擺效果將其無效？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(373085,'讚美火',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚時可以發動。依照對手場上的卡片數量，將對手牌組上方的卡送去墓地。\u000a②：此卡特殊召喚的場合可以發動。依照對手場上的卡片數量，將我方牌組上方的卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(387282,'我我我妹妹',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚成功時可以發動。從牌組將1張「我我我」魔法、陷阱卡加入手牌。\u000a②：以此卡以外的我方場上1隻「我我我」怪獸為對象可以發動。那隻怪獸和此卡直到回合結束時變成那2隻的等級合計的等級。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(402416,'魔神火焰砲-艾格佐德之焰',unistr('①：原卡名包含「艾克佐迪亞」的場上1隻等級10以上的怪獸得到以下效果。\u000a●支付一半生命值可以發動。雙方的魔法與陷阱區域的卡全部破壞。那之後，從手牌、牌組將5隻「被封印」怪獸各自當作攻擊力上升2000的裝備魔法卡給此卡裝備。此效果的發動後，直到回合結束時我方不能發動此卡以外的卡的效果。\u000a●此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'「魔神火焰砲-艾格佐德之焰」的效果1適用中','●破壞魔法與陷阱區域的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(402568,'電力長頸鹿',unistr('①：此卡可以直接攻擊。\u000a②：此卡直接攻擊給予對手戰鬥傷害的場合發動。這個回合，對手不能發動魔法、陷阱、怪獸的效果。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(403847,'同盟軍','我方場上的戰士族怪獸的攻擊力上升我方場上的戰士族、魔法使族怪獸數量×200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(410904,'憑依覺醒-螺旋龍',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：此卡可以將我方場上的表側表示的1隻魔法使族怪獸和1隻等級4以下的風屬性怪獸送去墓地，從手牌、牌組特殊召喚。\u000a②：此卡的①方法特殊召喚時可以發動。對手場上1張卡回到手牌。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將1張「風靈術」卡片或「憑依」魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423585,'召喚僧',unistr('①：此卡召喚、反轉召喚的場合發動。此卡變成守備表示。\u000a②：只要此卡在怪獸區域存在，此卡不能解放。\u000a③：1回合1次，從手牌捨棄1張魔法卡可以發動。從牌組將1隻等級4怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。'),'變成守備表示','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423705,'鐵騎士 機亞弗里德','①：此卡被裝備裝備卡的場合發動。那些裝備卡破壞。','裝備卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423706,'鐵騎士 機亞弗里德','①：此卡被裝備裝備卡的場合發動。那些裝備卡破壞。','裝備卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(425934,'強欲哥布林','只要此卡在我方場上表側表示存在，雙方不能發動「藉由捨棄手牌來發動」的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(433377,'雷盟-先導雲步',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方的「雷盟」卡片的效果將卡破壞的場合，以我方墓地1隻雷族怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：我方主要階段可以發動。從手牌將1隻雷族怪獸特殊召喚。那之後，此卡破壞。\u000a③：此卡在墓地存在的狀態，我方的「雷盟」卡片的效果將卡破壞的場合可以發動。此卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(440556,'龍神鯊',unistr('水屬性等級4怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材可以發動。從額外牌組將1隻階級3以下的水屬性超量怪獸特殊召喚。此效果的發動後，直到回合結束時此卡不能攻擊。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(458748,'法之聖典',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻「召喚獸」怪獸解放可以發動。從額外牌組將1隻和解放的怪獸原屬性不同的「召喚獸」怪獸當作融合召喚特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(464362,'魔玩具 剪刀虎',unistr('「鋒利小鬼 剪刀」+「絨毛動物」怪獸1隻以上\u000a①：「魔玩具 剪刀虎」在我方場上只能有1隻表側表示存在。\u000a②：此卡融合召喚成功時，最多到作為此卡的融合素材的怪獸數量，以場上的卡為對象可以發動。那些卡破壞。\u000a③：只要此卡在怪獸區域存在，我方場上的「魔玩具」怪獸的攻擊力上升我方場上的「絨毛動物」怪獸以及「魔玩具」怪獸數量×300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(473469,'猛吹雪','對手控制的卡片效果將我方場上的陷阱卡破壞並從場上送去墓地時可以發動。選擇場上的1張魔法、陷阱卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(487395,'水靈','在古代南極大陸的永凍土中生活的冰水精靈。能夠滲透進各種物質。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(494922,'超重荒神 須佐之男-O',unistr('機械族協調+協調以外的「超重武者」怪獸1隻以上\u000a此卡在規則上也當作「超重武者」卡片。\u000a①：此卡可以在表側守備表示的狀態攻擊。那個場合，此卡用守備力當作攻擊力進行傷害計算。\u000a②：1回合1次，我方墓地沒有魔法、陷阱卡存在的場合，以對手墓地1張魔法、陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡從場上離開的場合被除外。此效果在對手回合也能發動。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(525110,'小小番茄','此卡被戰鬥破壞送去墓地時，可以從我方牌組將最多2隻「小番茄」怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能作為同步素材。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(545781,'妖龍 摩訶摩',unistr('①：對手回合，我方或對手受到戰鬥傷害時可以發動。此卡從手牌特殊召喚。那之後，從以下效果挑選1個適用。\u000a●我方的生命值回復那次戰鬥傷害數值。\u000a●給予對手那次戰鬥傷害數值的傷害。'),'●我方回復生命值','●給予對手傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(549481,'硬毛鼠','毛像硬皮一樣聚集在一起，守備力非常的高。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(561300,'猛毒蝮蛇',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。此卡特殊召喚。對手場上沒有怪獸存在的場合，改成在對手場上守備表示特殊召喚。\u000a②：我方準備階段發動。我方受到500傷害。\u000a③：此卡被除外的場合，或被效果送去墓地的場合，以對手場上1張裡側表示的魔法、陷阱卡為對象可以發動（應對這個發動，不能發動對象卡片）。那張卡破壞。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(564541,'民藝龍',unistr('龍族怪獸上級召喚的場合，此卡可以當作2隻解放。\u000a我方的準備階段，此卡在墓地存在，我方場上沒有怪獸存在的場合，可以將此卡攻擊表示特殊召喚。此效果在我方墓地有龍族以外的怪獸存在的場合不能發動。此效果特殊召喚的此卡從場上離開的場合被除外。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(572850,'珠淚哀歌 雪蓮',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。此卡從手牌特殊召喚，從我方的手牌選1隻怪獸送去墓地。那之後，從我方牌組上方將3張卡送去墓地。\u000a②：此卡被效果送去墓地的場合可以發動。融合怪獸卡決定的包含墓地的此卡的融合素材怪獸從我方的手牌、場上、墓地以喜歡的順序回到持有者的牌組下方，從額外牌組融合召喚那1隻融合怪獸。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(575512,'PSY骨架迴路',unistr('①：我方場上有「PSY骨架」怪獸特殊召喚的場合可以發動。只用我方場上的「PSY骨架」怪獸為同步素材同步召喚。\u000a②：我方的「PSY骨架」怪獸和對手怪獸進行戰鬥的傷害步驟開始時，將手牌1隻「PSY骨架」怪獸捨棄可以發動。那隻進行戰鬥的我方怪獸的攻擊力直到回合結束時上升為了發動此效果而捨棄的怪獸的攻擊力數值。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(581014,'大薰風翠玉',unistr('等級4怪獸×2\u000a①：1回合1次，可以去除此卡的1個超量素材，從以下效果選擇1個發動。\u000a●以我方墓地3隻怪獸為對象可以發動。那3隻怪獸加入牌組洗牌。那之後，我方從牌組抽1張卡。\u000a●以效果怪獸以外的我方墓地1隻怪獸為對象可以發動。那隻怪獸特殊召喚。'),'N/A','●加入牌組洗牌','●特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(595626,'安卡栗子球',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時將此卡從手牌捨棄，以此卡以外的我方或對手的墓地1隻怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸在結束階段送去墓地。\u000a②：此卡被戰鬥、效果破壞送去墓地的場合可以發動。這個回合的結束階段，從我方的牌組、墓地選1張「死者蘇生」加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(596051,'毒蛇之牙','選擇場上表側表示存在的1隻怪獸可以發動。選擇的怪獸的守備力直到回合結束時下降500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(598988,'Sin 彩虹龍',unistr('此卡不能通常召喚。只能從手牌、牌組將1隻「究極寶玉神 彩虹龍」除外來特殊召喚。\u000a①：「Sin」怪獸在場上只能有1隻表側表示存在。\u000a②：只要此卡在怪獸區域存在，其他的我方怪獸不能攻擊宣言。\u000a③：沒有場地魔法卡表側表示存在的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(601193,'彼岸的詩人 維吉爾',unistr('協調+協調以外的怪獸1隻以上\u000a「彼岸的詩人 維吉爾」的③效果1回合只能使用1次。\u000a①：「彼岸的詩人 維吉爾」在我方場上只能有1隻表側表示存在。\u000a②：1回合1次，從手牌捨棄1張「彼岸」卡片，以對手的場上、墓地的1張卡為對象可以發動。那張卡回到持有者的牌組。\u000a③：場上的此卡被戰鬥、效果破壞送去墓地的場合可以發動。我方從牌組抽1張卡。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(612115,'劍鬥獸 戰網鬥士',unistr('此卡被「劍鬥獸」怪獸的效果特殊召喚成功的場合，可以選擇對手墓地的1張卡除外。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到牌組，從牌組將「劍鬥獸 戰網鬥士」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'除外','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(613013,'白煞鯊',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合，將我方場上1隻魚族怪獸解放可以發動。從牌組將1隻魚族的「鯊」怪獸特殊召喚。這個回合，我方除了水屬性怪獸以外不能特殊召喚。\u000a②：持有此卡作為素材的「鯊龍獸」超量怪獸得到以下效果。\u000a●1回合1次，魔法、陷阱卡的效果發動時，去除此卡的2個超量素材可以發動。那個效果無效並破壞。'),'效果1','●效果無效並破壞（白煞鯊）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(613496,'過剩調和',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有協調存在的場合可以發動。從我方的手牌、牌組、墓地將1隻協調特殊召喚。此卡的發動後，直到回合結束時我方除了同步怪獸以外不能從額外牌組特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(637216,'怪獸快車',unistr('這個卡名的效果1回合只能使用1次。\u000a①：以我方場上1隻表側表示怪獸為對象可以發動。從我方的額外牌組將1隻和那隻表側表示怪獸原種族相同的怪獸送去墓地。這個回合，我方除了此效果送去墓地的怪獸以及和那隻怪獸原種族相同的怪獸以外，不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645087,'電子界小工具',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚成功時，以我方墓地1隻等級2以下的怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。\u000a②：此卡從場上送去墓地的場合可以發動。在我方場上將1隻「小工具衍生物」（電子界族、光、等級2、攻/守0）特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645088,'小工具衍生物','由「電子界小工具」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645794,'威風妖怪 蛤蟆',unistr('【靈擺效果】\u000a【怪獸效果】\u000a「威風妖怪 蛤蟆」的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功時可以發動。從牌組選1張「威風妖怪」魔法、陷阱卡在我方場上覆蓋。此效果覆蓋的卡在這個回合不能發動。\u000a②：此卡只要在怪獸區域存在，不會成為對手的效果的對象，不會被對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(652362,'菊石外星人','①：此卡召喚成功時，以我方墓地1隻等級4以下的「外星人」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(653675,'同步破頂',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地任意數量的等級7、8的龍族同步怪獸為對象可以發動。那些怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的等級變成1，效果無效化。這個回合，我方除了同步怪獸以外不能從額外牌組特殊召喚。\u000a②：我方的同步怪獸被戰鬥破壞時，將墓地的此卡除外可以發動。從額外牌組將1隻「赤龍」特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(674561,'黑暗爆裂','①：以我方墓地1隻攻擊力1500以下的闇屬性怪獸為對象可以發動。那隻闇屬性怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(675319,'十二陣 生肖',unistr('①：我方場上的「十二獸」怪獸的攻擊力、守備力上升300。\u000a②：只要此卡在場地區域存在，對手不能選擇我方場上的攻擊力最高的獸戰士族怪獸以外的我方的獸戰士族怪獸作為攻擊對象。\u000a③：1回合1次，我方場上的「十二獸」怪獸被效果破壞的場合，可以將我方的手牌、場上1隻怪獸破壞，作為其中1隻「十二獸」怪獸的代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(691925,'太陽能交換','①：從手牌捨棄1隻「光道」怪獸可以發動。我方抽2張卡。那之後，從我方牌組上方將2張卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(698785,'雷霆終結龍',unistr('等級8通常怪獸×2\u000a1回合1次，去除此卡的1個超量素材可以發動。此卡以外的場上的怪獸全部破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(703897,'自鳴天琴漸強高潮',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有「自鳴天琴」連結怪獸存在，怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並除外。\u000a②：將墓地的此卡除外可以發動（此效果發動的整回合中，我方除了機械族、闇屬性怪獸以外不能特殊召喚）。我方的牌組、除外狀態的1隻機械族、闇屬性怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(706925,'海皇的狙擊兵',unistr('此卡給予對手戰鬥傷害時，可以從牌組將「海皇的狙擊兵」以外的1隻等級4以下的海龍族的「海皇」怪獸特殊召喚。\u000a此外，此卡為了發動水屬性怪獸的效果而被送去墓地時，選擇對手場上覆蓋的1張卡破壞。'),'特殊召喚','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(712559,'亞馬遜之里',unistr('①：場上的「亞馬遜」怪獸的攻擊力上升200。\u000a②：1回合1次，「亞馬遜」怪獸被戰鬥、效果破壞送去墓地時可以發動。我方從牌組將1隻等級在那隻「亞馬遜」怪獸的原等級以下的「亞馬遜」怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(720147,'王戰的憤激',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：解放我方場上任意數量的「王戰」怪獸，以我方場上1隻超量怪獸為對象可以發動。依照解放的數量，從我方的手牌、場上、墓地挑選解放的怪獸以外的「王戰」怪獸重疊在對象怪獸下方作為超量素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(732302,'骷髏的寺院','除了骷髏和骨頭別無二物，令人毛骨悚然的寺廟。會將靠近者吸進去。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(734741,'彼岸的惡鬼 魯比坎特',unistr('「彼岸的惡鬼 魯比坎特」的①效果1回合只能使用1次，將此卡作為同步素材的場合，除了「彼岸」怪獸的同步召喚以外不能使用。\u000a①：我方場上沒有魔法、陷阱卡存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方場上有「彼岸」怪獸以外的怪獸存在的場合，此卡破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(739444,'彈鼓龍',unistr('龍族、闇屬性怪獸3隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。我方從牌組抽1張卡。\u000a②：此卡的①效果適用的回合，只要此卡在怪獸區域存在，此卡指向的沒有使用的怪獸區域不能使用。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(744887,'虛界王戰 烏特加德王',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：「虛界王戰 烏特加德王」在我方場上只能有1隻表側表示存在。\u000a②：將我方場上的「王戰」怪獸或岩石族怪獸合計2隻解放，以場上1張卡為對象可以發動。那張卡除外。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(756652,'多隆','分身夾擊的怪獸，要小心！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759393,'火靈使 希塔','①：此卡反轉的場合，以對手場上1隻炎屬性怪獸為對象發動。這隻怪獸表側表示存在期間，得到對象怪獸的控制權。','獲得控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759394,'火靈使 希塔','①：此卡反轉的場合，以對手場上1隻炎屬性怪獸為對象發動。這隻怪獸表側表示存在期間，得到對象怪獸的控制權。','獲得控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759395,'火靈使 希塔','①：此卡反轉的場合，以對手場上1隻炎屬性怪獸為對象發動。這隻怪獸表側表示存在期間，得到對象怪獸的控制權。','獲得控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(770365,'魔導皇聖 忒莉絲',unistr('魔法使族等級5怪獸×2\u000a此卡的攻擊力上升我方場上的超量素材數量×300。\u000a此外，1回合1次，去除此卡的1個超量素材可以發動。我方牌組洗牌。那之後，從我方牌組上方翻開5張卡。最多到其中的「魔導書」卡片數量，選場上的怪獸破壞。那之後，翻開的卡以喜歡的順序回到牌組上方。'),'翻開5張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(786906,'逢魔之刻','①：以我方或對手的墓地1隻不能通常召喚的怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(799183,'超戰士之盾',unistr('①：我方場上有「混沌士兵」怪獸存在，以場上的怪獸為對象的怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並破壞。\u000a②：此卡在墓地存在的場合，去除我方場上的1個魔力計數器可以發動。墓地的此卡在我方場上覆蓋。這個效果覆蓋的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(811734,'DDD的契約變更',unistr('①：對手怪獸的攻擊宣言時，可以從以下效果選擇1個發動。\u000a●選我方墓地的1隻「DDD」怪獸除外。攻擊怪獸的攻擊力下降此效果除外的怪獸的攻擊力數值。\u000a●從牌組將1隻等級4以下的「DD」靈擺怪獸加入手牌。'),'●除外墓地的怪獸','●從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(816427,'新炎獄女郎',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1隻炎屬性怪獸送去墓地，以對手墓地1張卡為對象可以發動。那張卡除外。此效果在對手回合也能發動。\u000a②：此卡已在怪獸區域存在的狀態，卡片從對手墓地被除外的場合可以發動。從牌組將「新炎獄女郎」以外的1隻守備力200以下的炎屬性怪獸送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(821049,'維薩斯-阿密哩多羅',unistr('協調1隻以上+光屬性怪獸1隻\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，卡名當作「維薩斯-星霜」。\u000a②：此卡同步召喚的場合可以發動。從牌組將1張記載「維薩斯-星霜」的卡名的魔法、陷阱卡加入手牌。\u000a③：我方主要階段可以發動。我方場上1隻怪獸破壞。這個回合中我方場上的同步怪獸的攻擊力上升800。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(844056,'紅色箭矢',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以額外怪獸區域的最多2隻表側表示怪獸為對象可以發動。那些怪獸直到結束階段除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(847217,'奧雷卡爾克斯的魔封劍',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：裝備怪獸的效果無效化。\u000a②：我方的場地區域有卡存在的場合，以我方場上1隻效果怪獸為對象可以發動。那隻效果怪獸直到對手回合結束時得到以下效果。\u000a●我方、對手回合1次，將1張手牌送去墓地，以場上1張表側表示卡為對象可以發動。那張表側表示卡破壞。'),'效果2','「奧雷卡爾克斯的魔封劍」的效果2適用中','●破壞表側表示卡（奧雷卡爾克斯的魔封劍）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(847915,'編號之壁',unistr('我方場上有「No.」怪獸存在的場合可以發動此卡。\u000a只要此卡在場上存在，雙方場上的「No.」怪獸不會被效果破壞，也不會被「No.」怪獸以外的怪獸戰鬥破壞。\u000a我方場上的「No.」怪獸被破壞的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(856784,'命定的抽牌',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的生命值低於對手，場上的攻擊力最高的怪獸在對手場上存在的場合可以發動。從牌組將3張卡名不同的卡向對手展示，那3張洗牌放到牌組上方。那之後，我方從牌組抽1張卡。此卡的發動後，直到回合結束時我方不能覆蓋魔法、陷阱卡，只能發動1次魔法、陷阱、怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(863795,'銀河召喚師',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，以「銀河召喚師」以外的我方墓地1隻「光子」怪獸或「銀河」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a②：以我方場上1隻其他的光屬性怪獸為對象可以發動。那隻怪獸的等級直到回合結束時變成4。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(875572,'天賦之偉魔導士 克勞利',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用抽牌以外的方法加入手牌的場合可以發動。此卡特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「偉魔」融合怪獸或「召喚獸」融合怪獸融合召喚。\u000a③：場上的表側表示的此卡作為融合素材的場合，卡名可以當作「召喚師 阿萊斯特」。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(876330,'龍盟兵器-銀槲之劍',unistr('①：此卡可以將我方場上1隻表側表示的「龍盟」怪獸送去墓地，從手牌特殊召喚。\u000a②：此卡從手牌召喚、特殊召喚時，以我方墓地1隻龍族的「龍盟」怪獸為對象可以發動。那隻龍族怪獸當作裝備魔法卡給此卡裝備。'),'裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(879958,'並列埠裝甲',unistr('①：以我方場上1隻連結怪獸為對象可以發動此卡。此卡當作裝備卡給那隻怪獸裝備。裝備怪獸不會成為對手的效果的對象，不會被戰鬥破壞。\u000a②：從我方墓地將此卡和2隻連結怪獸除外，以我方場上1隻連結怪獸為對象可以發動。這個回合，那隻怪獸在1次戰鬥階段中可以攻擊2次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(885016,'多元宇宙',unistr('我方的場地區域沒有表側表示卡存在的場合可以發動此卡。這個卡名的①效果1回合只能使用1次。\u000a①：以我方或對手的墓地、除外狀態的1張場地魔法卡為對象可以發動。此卡破壞，對象卡片在我方的場地區域表側表示放置。\u000a②：場地區域的卡被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(897409,'銀河百式',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1張「光子」卡片或「銀河」卡片送去墓地。\u000a②：我方場上有「銀河眼光子龍」特殊召喚的場合可以發動。確認對手的額外牌組。那之後，可以從以下效果挑選1個適用。\u000a●其中1隻怪獸除外。\u000a●其中1隻「No.」怪獸在我方場上特殊召喚。'),'是否從牌組將1張卡送去墓地？','●除外','●在我方場上特殊召喚','都不選擇','','','','','','','','','','','','');
INSERT INTO texts VALUES(899287,'怪鳥格萊弗',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：將此卡從手牌捨棄可以發動。從牌組將1張「斯特朗堡的黃金城」加入手牌。\u000a②：此卡召喚、特殊召喚成功的場合，以對手的魔法與陷阱區域的1張卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(900787,'龍盟騎士-魔翔之槍',unistr('龍族協調+協調以外的鳥獸族怪獸1隻以上\u000a①：此卡進行戰鬥的從傷害步驟開始時到傷害計算前1次，將我方墓地1隻鳥獸族怪獸除外可以發動。此卡的攻擊力直到回合結束時上升除外的那隻怪獸的原攻擊力數值。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(904185,'垂直著陸','將衍生物以外的我方場上任意數量的風屬性怪獸解放可以發動。解放的怪獸數量的「幻獸機衍生物」（機械族、風、等級3、攻/守0）在我方場上特殊召喚。「垂直著陸」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(904186,'幻獸機衍生物','由「垂直著陸」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(911883,'預想GUY','①：我方場上沒有怪獸存在的場合可以發動。從牌組將1隻等級4以下的通常怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(917796,'我我我搭檔','我方場上的全部「我我我」怪獸的攻擊力直到下個我方準備階段時上升我方場上的「我我我」怪獸數量×500。「我我我搭檔」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(923596,'齒輪齒輪裝甲',unistr('此卡1回合1次可以變成裡側守備表示。\u000a此卡反轉時，可以從牌組將「齒輪齒輪裝甲」以外的1隻「齒輪齒輪」怪獸加入手牌。'),'裡側守備','設置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(938717,'起動兵長 指揮左輪',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方的場上、墓地最多2隻機械族的「小工具」怪獸為對象可以發動（同名卡最多1張）。此卡從手牌特殊召喚。那之後，作為對象的我方的「小工具」怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸數量×1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(952523,'庫拉莉亞的蟲惑魔',unistr('昆蟲族、植物族怪獸2隻\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：連結召喚的此卡不受陷阱卡的效果影響。\u000a②：只要此卡在怪獸區域存在，我方發動的「空洞」通常陷阱卡以及「落穴」通常陷阱卡在發動後可以不送去墓地而是直接覆蓋。\u000a③：我方結束階段，以我方墓地1隻「蟲惑魔」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'效果3','是否不送去墓地改成覆蓋？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(967928,'懲罰遊戲！',unistr('對手的手牌是4張的場合，可以從以下效果選擇1個發動。\u000a●對手在下個抽牌階段不能抽牌。\u000a●這個回合對手不能發動魔法、陷阱卡。'),'●下個抽牌階段不能抽牌','●這個回合不能發動魔法、陷阱卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(975299,'巨大要塞 澤洛斯',unistr('①：作為此卡的發動時的效果處理，可以從牌組將1張「頭目連環戰」加入手牌。\u000a②：我方場上的「巨大戰艦」怪獸的攻擊力、守備力上升500，不會成為對手的效果破壞，對手不能將其作為效果的對象。\u000a③：1回合1次，我方主要階段可以發動。從手牌將1隻「巨大戰艦」怪獸特殊召喚。\u000a④：我方場上有「巨大戰艦」怪獸召喚、特殊召喚的場合發動。給那些怪獸放置1個自身的效果使用的計數器。'),'是否將「頭目連環戰」加入手牌？','效果3','效果4','','','','','','','','','','','','','');
INSERT INTO texts VALUES(980973,'武裝龍 LV3','①：我方準備階段，將場上的此卡送去墓地可以發動。從手牌、牌組將1隻「武裝龍 LV5」特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(980974,'武裝龍 LV3','①：我方準備階段，將場上的此卡送去墓地可以發動。從手牌、牌組將1隻「武裝龍 LV5」特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(981540,'減半不破','選擇場上的1隻怪獸可以發動。這個回合，對象怪獸不會被戰鬥破壞，那隻怪獸的戰鬥產生給我方的戰鬥傷害變成一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(983995,'籃板球',unistr('對手發動要讓場上的卡回到手牌的怪獸的效果、魔法、陷阱卡時可以發動。那個效果無效，從對手的手牌、場上選1張卡送去墓地。\u000a此外，覆蓋的此卡被對手破壞送去墓地時，從牌組抽1張卡。'),'牌組','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(984114,'電車機人','①：此卡召喚、反轉召喚、特殊召喚成功時，以「電車機人」以外的我方墓地2隻「機人」怪獸為對象可以發動。那些怪獸加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(987311,'DDD疾風王 亞歷山大',unistr('「DD」協調+協調以外的怪獸1隻以上\u000a「DDD疾風王 亞歷山大」的效果1回合只能使用1次。\u000a①：此卡在怪獸區域存在，我方場上有此卡以外的「DD」怪獸召喚、特殊召喚的場合，以我方墓地1隻等級4以下的「DD」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1003028,'老虎狗潛水員',unistr('對手場上有怪獸存在，我方場上表側表示存在的怪獸只有等級4怪獸的場合，此卡可以從手牌特殊召喚。「老虎狗潛水員」的這個方法的特殊召喚1回合只能有1次。\u000a將此卡作為超量召喚的素材的場合，除了戰士族怪獸的超量召喚以外不能使用。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1003840,'星光廢品交流道',unistr('「星光廢品交流道」的①②效果1回合各能使用1次。\u000a①：將我方場上的1隻協調解放可以發動此效果。從牌組將1隻和解放的怪獸等級不同的「同步者」怪獸特殊召喚。\u000a②：對手回合中我方從額外牌組將同步怪獸特殊召喚的場合，以場上1張卡為對象發動。那張卡回到持有者的牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1005587,'煉獄的落穴','①：對手將攻擊力2000以上的怪獸特殊召喚時可以發動。選其中1隻攻擊力2000以上的怪獸，將效果無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1006081,'廢品變身者',unistr('「廢品變身者」的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，可以選擇場上的1隻「廢品」怪獸為對象，從以下效果選擇1個發動。\u000a●對象怪獸的等級上升1。\u000a●對象怪獸的等級下降1。'),'等級上升或下降','●等級上升1','●等級下降1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1033312,'苦澀的決斷',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻等級4以下的通常怪獸送去墓地，從牌組將1隻其同名怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1035143,'黑暗栗子球',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的惡魔族怪獸或融合怪獸成為攻擊、效果的對象時，將此卡從手牌捨棄，以其中1隻為對象可以發動。這個回合，那隻怪獸不會被戰鬥、效果破壞，那隻怪獸在場上發動的效果不會被無效化。\u000a②：此卡被效果從手牌送去墓地的場合可以發動。從我方的牌組、墓地將1張「融合」加入手牌。'),'效果1','效果2','「黑暗栗子球」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1036974,'不幸','選擇對手場上1隻表側表示怪獸可以發動。給予對手選擇的怪獸原攻擊力數值一半的傷害。此卡發動的整回合中，我方的怪獸不能攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1041278,'分離的烙印',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻融合怪獸解放，除了融合怪獸以外，以我方或對手的墓地、除外狀態的怪獸合計2隻為對象可以發動。那些怪獸在雙方場上各選1隻特殊召喚。將需以「阿不思的落胤」為融合素材的融合怪獸解放來發動此卡的場合，可以改成將2隻對象怪獸在我方場上守備表示特殊召喚。'),'是否將2隻怪獸在我方場上守備表示特殊召喚？','請選擇要在我方場上特殊召喚的怪獸','請選擇要在對手場上特殊召喚的怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1045143,'齒輪齒輪人 Mk-II','此卡召喚、反轉召喚成功時，可以從我方的手牌、墓地選1隻「齒輪齒輪」怪獸表側守備表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1047075,'鬥炎之劍士',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張記載「炎之劍士」的卡名的魔法、陷阱卡加入手牌。\u000a②：此卡被送去墓地的場合可以發動。除了「鬥炎之劍士」以外，從牌組、額外牌組將1隻「炎之劍士」或記載那個卡名的怪獸送去墓地。'),'檢索','送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050186,'衛星騎士 天市右垣七',unistr('「衛星騎士 天市右垣七」的效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚成功的場合可以發動。從牌組將「衛星騎士 天市右垣七」以外的1張「星騎士」卡片送去墓地。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050355,'闇黑的夢魔鏡',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要我方場上有闇屬性的「夢魔鏡」怪獸存在，每次對手將怪獸特殊召喚成功，給予對手300傷害。\u000a②：我方、對手的結束階段，將我方的場地區域的此卡除外可以發動。從手牌、牌組發動1張「聖光的夢魔鏡」。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050684,'廢鐵地帶','①：從牌組將1隻「廢鐵」協調加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1061200,'F.A. 城市大獎賽',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在場地區域存在，場上的「F.A.」怪獸的等級在主要階段以及戰鬥階段期間上升2。\u000a②：我方場上的「F.A.」怪獸不會成為對手的效果的對象。\u000a③：場上的表側表示的此卡被效果破壞的場合可以發動。從牌組將「F.A. 城市大獎賽」以外的1張「F.A.」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1073952,'魔法盆栽','①：將我方場上1張表側表示的永續陷阱卡送去墓地可以發動。我方抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1082946,'命運的火時計','1張卡的回合計數前進1回合。','請選擇讓回合計數前進的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1102515,'暗黑的模仿箱 LV3','此卡被戰鬥破壞送去墓地的場合，此卡的控制者從牌組抽1張卡。此卡是被「暗黑的模仿箱 LV1」的效果特殊召喚的場合，改成抽2張卡。','抽卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1118137,'守護者之力',unistr('①：裝備怪獸進行戰鬥的攻擊宣言時發動。給此卡放置1個魔力計數器。\u000a②：裝備怪獸的攻擊力、守備力上升此卡的魔力計數器的數量×500。\u000a③：裝備怪獸被戰鬥、效果破壞的場合，可以去除我方場上的1個魔力計數器作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1122030,'神藝破壞－襲擊－',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻「無垢者 梅迪烏斯」加入手牌。\u000a②：以我方場上1隻表側表示怪獸為對象可以發動。這個回合，那隻表側表示怪獸作為融合素材的場合，可以當作「神藝」怪獸。\u000a③：我方場上的「神藝學都 阿爾特梅基亞」被效果破壞的場合，可以將場上的此卡送去墓地作為代替。'),'效果2','是否把怪獸加入手牌？','「神藝破壞－襲擊－」的效果2適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1127737,'異次元的古戰場-死域海',unistr('超量召喚成功時，那個玩家受到500傷害。\u000a此外，場上有超量怪獸的玩家在每次自己的結束階段受到500傷害。'),'受到傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1142880,'電子龍次代星',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「電子龍」。\u000a②：從手牌將1隻其他怪獸捨棄可以發動。此卡從手牌特殊召喚。\u000a③：此卡召喚、特殊召喚的場合，以我方墓地1隻攻擊力或守備力是2100的機械族怪獸為對象可以發動。那隻怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了機械族怪獸以外不能特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1149109,'牌組封鎖',unistr('此卡發動後，在第2次的我方準備階段破壞。\u000a①：只要此卡在魔法與陷阱區域存在，雙方不能用抽牌以外的方法從牌組將卡加入手牌，也不能從牌組將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1151281,'地中族邪界獸 愛奧磷冰精',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上的表側表示怪獸變成裡側表示時，我方場上沒有表側表示怪獸存在的場合可以發動。此卡從手牌守備表示特殊召喚。\u000a②：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a③：此卡反轉的場合可以發動。從牌組選1張卡送去墓地。'),'效果3','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1154611,'伯吉斯異獸 林喬利蟲',unistr('①：以被除外的1張我方或對手的卡為對象可以發動。那張卡回到墓地。\u000a②：陷阱卡發動時，連鎖那個發動可以在墓地發動此效果。此卡變成通常怪獸（水族、水、等級2、攻1200/守0）在怪獸區域特殊召喚（不當作陷阱卡）。此效果特殊召喚的此卡不受怪獸的效果影響，從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1157683,'電子黑暗侵略',unistr('①：1回合1次，可以從以下效果選擇1個發動。「電子黑暗侵略」的以下效果1回合各能選擇1次。\u000a●以我方場上1隻「電子暗黑」效果怪獸為對象可以發動。從我方、對手的墓地選1隻龍族、機械族怪獸，當作攻擊力上升1000的裝備卡給對象怪獸裝備。\u000a●將給機械族怪獸裝備的我方場上1張裝備卡送去墓地可以發動。選對手場上1張卡破壞。'),'●從墓地裝備1隻怪獸','●選擇對手場上的1張卡破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1164211,'仟年王朝之盾',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合可以發動。此卡當作永續魔法卡在我方的魔法與陷阱區域表側表示放置。\u000a②：此卡當作永續魔法卡的場合，支付2000生命值或向對手展示手牌的1張「仟年的十字」可以發動。此卡特殊召喚。那之後，可以從牌組將1張「仟年的十字」加入手牌。\u000a③：此卡只要在怪獸區域存在，不會被魔法、陷阱卡的效果破壞。'),'效果1','效果2','是否展示「仟年的十字」？','是否從牌組加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(1174075,'龍輝巧-扶筐增二μβ''',unistr('等級1怪獸×2隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡超量召喚的場合可以發動。從牌組將1張「龍輝巧」卡片送去墓地。\u000a②：我方進行儀式召喚的場合，也能將那些解放的怪獸從此卡的超量素材去除。\u000a③：我方場上有機械族儀式怪獸存在，對手發動魔法、陷阱卡時，去除此卡的1個超量素材可以發動。那個發動無效並破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1184620,'魔物的獵人','獵殺人類的獵人，具有連岩石都能擊碎的力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1186447,'星讀的魔術師-天宮圖魔術士',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：對手發動的魔法卡的效果的處理時，我方場上有「魔術師」靈擺怪獸或「異色眼」怪獸存在的場合，可以將那個發動的效果無效。那之後，此卡破壞。\u000a【怪獸效果】\u000a這個卡名的①②③怪獸效果1回合各能使用1次。\u000a①：從手牌捨棄1隻其他的「魔術師」靈擺怪獸、「娛樂夥伴」怪獸、「異色眼」怪獸可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合可以發動。從牌組將1隻攻擊力2500的靈擺怪獸加入手牌。\u000a③：以我方場上1張靈擺怪獸卡為對象可以發動。那張卡破壞。那之後，可以從我方的額外牌組（表側）將1隻靈擺怪獸加入手牌。'),'效果1','效果2','效果3','是否加入手牌？','是否將這個效果無效？','','','','','','','','','','','');
INSERT INTO texts VALUES(1186448,'星讀的魔術師-天宮圖魔術士',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：對手發動的魔法卡的效果的處理時，我方場上有「魔術師」靈擺怪獸或「異色眼」怪獸存在的場合，可以將那個發動的效果無效。那之後，此卡破壞。\u000a【怪獸效果】\u000a這個卡名的①②③怪獸效果1回合各能使用1次。\u000a①：從手牌捨棄1隻其他的「魔術師」靈擺怪獸、「娛樂夥伴」怪獸、「異色眼」怪獸可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合可以發動。從牌組將1隻攻擊力2500的靈擺怪獸加入手牌。\u000a③：以我方場上1張靈擺怪獸卡為對象可以發動。那張卡破壞。那之後，可以從我方的額外牌組（表側）將1隻靈擺怪獸加入手牌。'),'效果1','效果2','效果3','是否加入手牌？','是否將這個效果無效？','','','','','','','','','','','');
INSERT INTO texts VALUES(1187243,'對薰風的追風',unistr('只能給「薰風」怪獸裝備。這個卡名的②③效果1回合各能使用1次。\u000a①：裝備怪獸不會被對手的效果破壞。\u000a②：可以依照裝備怪獸的等級、階級發動以下效果。\u000a●4以下：從牌組將1隻和裝備怪獸種族不同的「薰風」怪獸特殊召喚。\u000a●5以上：從牌組將1隻等級1協調特殊召喚。\u000a③：將墓地的此卡除外，從手牌捨棄1隻風屬性怪獸可以發動。從牌組將1張「薰風」魔法、陷阱卡加入手牌。'),'●4以下','●5以上','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1197847,'幻煌龍的螺旋波',unistr('只能給通常怪獸裝備。「幻煌龍的螺旋波」的②效果1回合只能使用1次。\u000a①：裝備怪獸1回合只有1次不會被戰鬥破壞。\u000a②：裝備怪獸進行戰鬥的戰鬥階段結束時可以發動。從我方的手牌、牌組、墓地選1隻「幻煌龍 螺旋」特殊召喚，此卡給那隻怪獸裝備。那之後，對手有手牌的場合，對手選1張手牌捨棄。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1200843,'八汰鏡',unistr('只能給靈魂怪獸裝備。\u000a裝備怪獸在結束階段回到手牌的效果可以不發動。\u000a裝備怪獸被戰鬥破壞的場合，將此卡破壞作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1218214,'方界法',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將1張「方界」卡片送去墓地，我方從牌組抽1張卡。\u000a②：只要此卡在魔法與陷阱區域存在，我方的「方界」怪獸的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：將墓地的此卡除外，以我方墓地1隻「方界」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1224927,'邪神的大災害','①：對手怪獸的攻擊宣言時可以發動。場上的魔法、陷阱卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1225009,'拉比麗斯的僕從 亞莉安娜',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將「拉比麗斯的僕從 亞莉安娜」以外的1張「拉比麗斯」卡片加入手牌。\u000a②：我方的通常陷阱卡的效果讓怪獸從場上離開的場合可以發動。我方從牌組抽1張卡。那之後，可以適用以下效果。\u000a●從手牌將1隻惡魔族怪獸特殊召喚或將1張魔法、陷阱卡覆蓋。\u000a\u000a※白銀之城的僕從 亞莉安娜'),'效果1','效果2','●從手牌特殊召喚','●從手牌覆蓋','都不選擇','','','','','','','','','','','');
INSERT INTO texts VALUES(1248895,'連鎖破壞','①：攻擊力2000以下的怪獸召喚、反轉召喚、特殊召喚時，以那1隻表側表示怪獸為對象可以發動。從那隻表側表示怪獸的控制者的手牌、牌組將對象怪獸的同名卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1249315,'聖光的宣告者',unistr('等級2怪獸×2\u000a這個卡名的效果1回合只能使用1次。\u000a①：去除此卡的1個超量素材，以我方墓地1隻怪獸為對象可以發動。那隻怪獸加入手牌。那之後，選1張手牌回到牌組。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1259814,'千六百七十七萬工房','①：1回合1次，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的種族變成機械族，那個屬性也當作「光」「闇」「地」「水」「炎」「風」。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1259915,'三幻魔的霹靂',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從我方的手牌、牌組、墓地將2張「三幻魔的霹靂」在我方場上表側表示放置。那之後，可以向對手展示手牌的1隻等級10的「三幻魔」怪獸。展示的場合，隨後從牌組將1張「三幻魔的失樂園」在我方的場地區域表側表示放置。\u000a②：此卡在墓地存在的場合，對手結束階段可以發動。此卡加入手牌。'),'效果1','效果2','是否向對手展示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1264319,'寶石騎士結合',unistr('①：我方的手牌、場上的怪獸作為融合素材，將1隻「寶石騎士」融合怪獸融合召喚。\u000a②：此卡在墓地存在的場合，從我方墓地將1隻「寶石騎士」怪獸除外可以發動。此卡加入手牌。\u000a\u000a※寶石騎士融合'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1264320,'寶石騎士結合',unistr('①：我方的手牌、場上的怪獸作為融合素材，將1隻「寶石騎士」融合怪獸融合召喚。\u000a②：此卡在墓地存在的場合，從我方墓地將1隻「寶石騎士」怪獸除外可以發動。此卡加入手牌。\u000a\u000a※寶石騎士融合'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1269512,'全裝甲-霍普鰭條槍兵',unistr('等級4怪獸×3\u000a「全裝甲-霍普鰭條槍兵」1回合1次也能將手牌的1張魔法、陷阱卡捨棄，重疊在我方場上的階級4以下的超量怪獸上方來超量召喚。\u000a①：對手場上的怪獸的攻擊力下降500。\u000a②：我方、對手的戰鬥階段開始時可以發動。對手場上的全部攻擊表示怪獸的效果無效化。\u000a③：此卡的攻擊破壞對手怪獸時，去除此卡的1個超量素材可以發動。此卡只有1次可以繼續攻擊。'),'是否在階級4以下的超量怪獸上方重疊來超量召喚？','','效果2','效果3','','','','','','','','','','','','');
INSERT INTO texts VALUES(1274455,'Kozmo-飛猴隊',unistr('「Kozmo-飛猴隊」的①效果1回合只能使用1次。\u000a①：將場上的此卡除外可以發動。從手牌將1隻等級4以上的「Kozmo」怪獸特殊召喚。此效果在對手回合也能發動。\u000a②：1回合1次，支付1000生命值，以我方墓地1隻超能族的「Kozmo」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1278431,'古代機械齒輪素體',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：捨棄1張手牌可以發動。從牌組將1隻「古代機械齒輪巨人」或1張記載那個卡名的魔法、陷阱卡加入手牌。\u000a②：此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a③：表側表示的此卡因對手的效果從場上離開的場合可以發動。從手牌將「古代機械齒輪巨人」「古代機械齒輪巨人-究極重拳」合計最多3隻無視召喚條件特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1281505,'大日神械四面體',unistr('此卡從怪獸區域送去墓地的場合，可以藉由支付500生命值，將此卡當作裝備卡給我方場上的1隻怪獸裝備。\u000a裝備此卡的怪獸被破壞的場合，可以將此卡破壞作為代替。'),'當作裝備卡裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1287123,'物質獵鷹','持有「將場上的魔法、陷阱卡破壞」的怪獸的效果發動時，可以藉由將1張手牌送去墓地，那個發動無效並破壞。','無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1295111,'轉生炎獸的聖域',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：只要此卡在場地區域存在，我方將「轉生炎獸」連結怪獸連結召喚的場合，可以只用我方場上1隻同名的「轉生炎獸」連結怪獸為素材連結召喚。\u000a②：我方怪獸進行戰鬥的傷害計算時，支付1000生命值，以我方場上1隻連結怪獸為對象可以發動。那隻怪獸的攻擊力變成0，我方的生命值回復那隻怪獸的原攻擊力數值。'),'連結召喚（轉生炎獸的聖域）','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1295442,'冰水艇 霓石海神盔蝦',unistr('這個卡名的①③效果1回合只有1次能使用其中1個。\u000a①：我方、對手回合，此卡在手牌、墓地存在的場合，以我方場上1隻「冰水」怪獸為對象可以發動。此卡當作裝備魔法卡給那隻我方怪獸裝備。\u000a②：已裝備此卡的怪獸的攻擊力、守備力上升除外狀態的怪獸數量×400。\u000a③：此卡裝備中的場合可以發動。此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1315120,'T.G. 突擊兵',unistr('①：只有對手場上有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：場上的此卡被破壞送去墓地的回合的結束階段可以發動。從牌組將「T.G. 突擊兵」以外的1隻「T.G.」怪獸加入手牌。'),'檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1322368,'SPYRAL-雙螺旋特工',unistr('「SPYRAL」怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「SPYRAL-花花公子」。\u000a②：宣言卡的種類（怪獸、魔法、陷阱）可以發動。對手牌組最上方的卡給雙方確認，如果是宣言的種類的卡，從我方的牌組、墓地選1隻「SPYRAL」怪獸加入手牌或在此卡指向的我方場上特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1329620,'珠淚哀歌的殘響',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有「珠淚哀歌」怪獸或「維薩斯-星霜」存在，怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效，那張卡回到持有者的牌組。那之後，從我方的手牌選1隻怪獸送去墓地。\u000a②：此卡被效果送去墓地的場合，以被除外的1隻我方的「珠淚哀歌」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1340142,'異響鳴琴的神奏-星光天魔',unistr('包含「異響鳴琴」連結怪獸的怪獸2隻\u000a①：只要我方場上有6個以上響鳴計數器存在，場上的此卡不受「異響鳴琴」卡片以外的卡的效果影響。\u000a②：除了通常攻擊以外，此卡在1次戰鬥階段中可以攻擊的次數為我方場上的等級4的「異響鳴琴」怪獸數量。\u000a③：1回合1次，對手將怪獸特殊召喚之際可以發動。那次特殊召喚無效，那些怪獸破壞。那之後，去除我方場上的3個響鳴計數器。'),'N/A','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1344018,'時光的靈擺讀陣',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在魔法與陷阱區域存在，對手不能將我方場上的魔法使族怪獸作為陷阱卡的效果的對象。\u000a②：以我方的怪獸區域、靈擺區域1張「魔術師」靈擺怪獸卡和對手場上1張卡為對象可以發動。那些卡破壞。此效果沒有將2張卡破壞的場合，可以將場上1張卡送去墓地。\u000a\u000a※時空的靈擺讀陣'),'破壞2張卡','是否將場上1張卡送去墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1347977,'神聖保衛者',unistr('①：此卡反轉的場合，從以下效果選擇1個發動。\u000a●以場上1隻表側表示怪獸為對象發動。那隻表側表示怪獸回到持有者的牌組最上方。\u000a●我方場上有戰士族怪獸存在的場合，以場上2隻表側表示怪獸為對象發動。其中1隻表側表示怪獸回到持有者的牌組最上方。那之後，我方場上有戰士族怪獸存在的場合，另1隻表側表示怪獸回到持有者的手牌。'),'是否選擇1隻怪獸回到手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1353770,'神的居城-瓦爾哈拉','①：1回合1次，我方主要階段可以發動此效果。從手牌將1隻天使族怪獸特殊召喚。此效果在我方場上沒有怪獸存在的場合可以發動和處理。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1357146,'精粹蛙',unistr('此卡不能作為同步素材。\u000a①：只要此卡在怪獸區域存在，卡名當作「死亡青蛙」。\u000a②：此卡在墓地存在的場合，從我方墓地將1隻「青蛙」怪獸除外可以發動。此卡特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1362589,'光子粉碎者','①：此卡攻擊的場合，在傷害步驟結束時變成守備表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1371589,'吸血無尾熊','此卡和怪獸戰鬥給予對手戰鬥傷害時，我方的生命值回復那個戰鬥傷害的數值。','回復','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1372887,'共乘',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：這個回合，每次對手用抽牌以外的方法從牌組、墓地將卡加入手牌，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1409474,'陽炎獸 史芬克斯',unistr('只要此卡在場上表側表示存在，對手不能將此卡作為效果的對象。\u000a1回合1次，我方的主要階段時，宣言卡的種類（怪獸、魔法、陷阱）可以發動。我方牌組最上方的卡送去墓地，如果是宣言的種類，那之後可以從我方的手牌、墓地選1隻炎屬性怪獸特殊召喚。「陽炎獸 史芬克斯」的這個效果1回合只能使用1次。'),'特殊召喚','是否從手牌、墓地特殊召喚1隻炎屬性怪獸？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1410324,'花樣明星 烏頭',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「花樣明星」融合、連結怪獸其中任何種類存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡作為「花樣明星」連結怪獸的連結素材送去墓地的場合可以發動。從牌組將1張「花樣明星結合」或「花樣明星擴散結合」加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1412158,'稀有金屬騎士',unistr('「稀有金屬士兵」+「稀有金屬女士」\u000a此卡和怪獸進行戰鬥的傷害步驟中，此卡的攻擊力上升1000。\u000a場上的此卡可以和融合牌組的「稀有金屬女武神」交換。（在此卡特殊召喚的回合不能發動。）'),'攻擊力上升','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1426714,'No.48 暗影巫妖',unistr('等級3怪獸×2\u000a①：對手回合1次，去除此卡的1個超量素材可以發動。在我方場上將1隻「幻影衍生物」（惡魔族、闇、等級1、攻/守500）特殊召喚。\u000a②：此卡的攻擊力上升我方場上的「幻影衍生物」的數量×500。\u000a③：只要我方場上有「幻影衍生物」存在，對手不能選擇此卡作為攻擊對象。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1426715,'幻影衍生物','由「No.48 暗影巫妖」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1434352,'混沌死靈師','此卡的攻擊力變成我方墓地的怪獸數量×300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1435851,'龍的秘寶',unistr('只能給龍族怪獸裝備。\u000a裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1463589,'A-GMX最終驗證',unistr('我方場上有「GMX」怪獸存在的場合可以發動此卡。\u000a①：1回合1次，對手發動場上的怪獸的效果時可以發動。從我方牌組上方翻開5張卡，其中有「GMX」卡片的場合，那個發動的效果無效。翻開的卡以喜歡的順序回到牌組上方或下方。'),'效果1','回到牌組上方','回到牌組下方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1474910,'小蜜蜂','將此卡和「小蜜蜂」以外的我方場上表側表示存在的1隻昆蟲族怪獸解放可以發動。從我方牌組抽2張卡。','抽2張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1475311,'闇之誘惑','①：我方抽2張卡。那之後，手牌有闇屬性怪獸存在的場合，選其中1隻除外。不存在的場合，我方的手牌全部送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1482001,'副話術士 克拉拉&洛希卡',unistr('通常召喚的怪獸1隻\u000a除了在主要階段2以外，此卡不能連結召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1487805,'宇宙鋏 澤羅奧爾',unistr('爬蟲類族怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。從牌組將持有放置A計數器效果的1張卡加入手牌。\u000a②：去除我方、對手場上的2個A計數器可以發動。將1隻爬蟲類族怪獸召喚。\u000a③：只要此卡在怪獸區域存在，已放置A計數器的對手怪獸變成守備表示，不能發動效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1490690,'卡諾匹斯的保衛者',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：對手發動效果時可以發動（同一連鎖上最多1次）。從我方的手牌、墓地將1隻「荷魯斯」怪獸特殊召喚。這個回合，我方不能將原卡名和此效果特殊召喚的怪獸相同的怪獸用「卡諾匹斯的保衛者」的效果特殊召喚。\u000a②：此卡從手牌、場上送去墓地的場合可以發動。此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1498130,'六武眾的影武者','我方場上表側表示存在的1隻「六武眾」怪獸成為魔法、陷阱、效果怪獸的效果的對象時，可以將那個效果的對象轉移到場上表側表示存在的此卡。','對象轉移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1498449,'星宿砲手 法魅那',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，將此卡從手牌捨棄可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻龍族、魔法使族的融合怪獸融合召喚。\u000a②：此卡作為融合召喚的素材送去墓地的場合可以發動。從牌組將1張「星宿」魔法、陷阱卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1508649,'幻變騷靈 十六進赫斯提亞',unistr('「幻變騷靈」怪獸2隻\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡的攻擊力上升此卡指向的「幻變騷靈」怪獸的原攻擊力數值。\u000a②：魔法、陷阱卡的效果發動時，將此卡指向的1隻「幻變騷靈」怪獸解放可以發動。那個發動無效並破壞。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將1張「幻變騷靈」卡片加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1516510,'符文眼靈擺龍',unistr('「異色眼靈擺龍」+魔法使族怪獸\u000a①：此卡依照「異色眼靈擺龍」以外的作為融合素材的怪獸的原等級得到以下效果。\u000a●等級4以下：此卡在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a●等級5以上：此卡在1次戰鬥階段中可以向怪獸攻擊最多3次。\u000a②：用場上的靈擺召喚的怪獸作為素材將此卡融合召喚成功的回合，此卡不受對手的效果影響。'),'●等級4以下','●等級5以上','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1525329,'擁有7種武器的獵人',unistr('此卡召喚成功時，宣言1個種族發動。\u000a此卡和宣言的種族的怪獸進行戰鬥的傷害計算時，此卡的攻擊力只在傷害計算時上升1000。'),'宣言1個種族','攻擊力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1527418,'空牙團的睿智 薇茲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。我方回復「空牙團的睿智 薇茲」以外的我方場上的「空牙團」怪獸的種類×500生命值。\u000a②：對手發動魔法、陷阱卡的效果時，從手牌捨棄1張「空牙團」卡片可以發動。那個發動無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1528054,'影法師 大禮帽野兔',unistr('效果怪獸2隻\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組將1張持有將自身作為怪獸特殊召喚效果的永續陷阱卡在我方場上覆蓋。此卡在這個回合不能作為連結素材。\u000a②：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a③：魔法與陷阱區域的卡在怪獸區域特殊召喚的場合，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1533292,'真次世代蒸汽機','①：此卡召喚時可以發動。從牌組將1隻等級2的「真次世代」怪獸加入手牌。','從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1539051,'空間之禮','我方場上每有1種表側表示的「新空間俠」怪獸，就從我方的牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1546123,'電子終結龍',unistr('「電子龍」+「電子龍」+「電子龍」\u000a此卡的融合召喚只能使用上述卡進行。\u000a①：此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1546124,'電子終結龍',unistr('「電子龍」+「電子龍」+「電子龍」\u000a此卡的融合召喚只能使用上述卡進行。\u000a①：此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1557341,'復仇的女戰士 蘿絲','①：此卡給予對手戰鬥傷害的場合發動。給予對手300傷害。','300傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1557499,'銀色弓箭',unistr('只能給天使族怪獸裝備。\u000a裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1561110,'ABC-神龍殲滅者',unistr('「A-突擊核」+「B-毀滅龍獸」+「C-粉碎翼龍」\u000a只能將我方的場上、墓地的上述卡除外，從額外牌組特殊召喚。\u000a①：我方、對手回合1次，捨棄1張手牌，以場上1張卡為對象可以發動。那張卡除外。\u000a②：對手回合，將此卡解放，以我方的除外狀態的3隻機械族、光屬性聯合怪獸為對象可以發動（同名卡最多1張）。那些怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1566817,'網球邱比特',unistr('這個卡名的②效果1回合只能有1次。\u000a①：只要此卡在怪獸區域存在，除了等級在此卡的等級以下的怪獸以外，此卡不受怪獸發動的效果影響。\u000a②：將我方墓地最多3張卡除外可以發動。直到回合結束時，此卡的等級上升除外數量的數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1571945,'白色忍者','反轉：選擇場上1隻守備表示怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1580833,'機動霧龍 劍龍',unistr('【靈擺效果】\u000a①：此卡以外的我方場上的「機動霧龍」卡片被戰鬥或對手的效果破壞的場合，可以將此卡破壞作為代替。\u000a【怪獸效果】\u000a①：此卡以外的我方的靈擺怪獸和對手怪獸進行戰鬥的傷害計算後可以發動。那些進行戰鬥的雙方怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1586457,'深空巡洋艦九號','此卡可以從手牌將1隻此卡以外的機械族怪獸送去墓地來從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1595137,'曉世龍 達尼安',unistr('「新世龍 達尼安」+恐龍族怪獸\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從牌組將1張「GMX」卡片加入手牌。\u000a②：我方用「GMX」卡片的效果將牌組的卡翻開的場合，可以依照此卡在何處存在發動以下效果（這個卡名的以下效果1回合各能使用1次）。\u000a●場上：我方回復1500生命值。\u000a●墓地：此卡特殊召喚。'),'檢索','選擇效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1596508,'次元要塞兵器','只要此卡在場上表側表示存在，雙方不能從牌組將卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1607603,'想定GUYS',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：可以從以下效果選擇1個發動。\u000a●我方場上沒有怪獸存在的場合可以發動。從牌組將1隻戰士族、等級4怪獸特殊召喚。\u000a●以我方場上1隻戰士族怪獸為對象可以發動。從我方的牌組、墓地將1隻等級在那隻怪獸的等級以下的戰士族、地屬性怪獸特殊召喚。'),'●從牌組特殊召喚','●以我方場上1隻戰士族怪獸為對象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1621413,'黑暗鎮魂超量龍',unistr('等級5怪獸×3\u000a①：此卡有「黑暗反叛超量龍」作為超量素材的場合，得到以下效果。\u000a●1回合1次，去除此卡的1個超量素材，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力變成0，此卡的攻擊力上升那個原攻擊力數值。\u000a●對手發動怪獸的效果時，去除此卡的1個超量素材可以發動。那個發動無效並破壞。那之後，可以從我方墓地將1隻超量怪獸特殊召喚。'),'●攻擊力變成0','●發動無效','是否將我方墓地的1隻超量怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1637760,'昇天的剛角笛','①：對手主要階段中，對手將怪獸特殊召喚之際可以發動。那次特殊召喚無效，那些怪獸破壞。那之後，對手從牌組抽1張卡，對手主要階段結束。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1639384,'神龍騎士 費爾格蘭',unistr('等級8怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以場上1隻表側表示怪獸為對象可以發動。這個回合，對象怪獸的效果無效，不受此卡以外的效果影響。此效果在對手回合也能發動。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1641882,'結融體','「小天使」+「催眠羊」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1644289,'大日神械斷片',unistr('只能給「大日神械」怪獸裝備。\u000a裝備怪獸不會成為對手的陷阱、效果怪獸的效果的對象。\u000a場上表側表示存在的此卡被送去墓地的場合，可以從我方牌組將1張「大日神械」魔法卡加入手牌。'),'從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1662004,'炎星師-張天',unistr('這個卡名的效果1回合只能使用1次。將此卡作為同步素材的場合，除了獸戰士族怪獸的同步召喚以外不能使用。\u000a①：此卡召喚成功時，以我方墓地1隻守備力200以下的炎屬性、等級3怪獸為對象可以發動。那隻炎屬性怪獸守備表示特殊召喚。此效果特殊召喚成功的回合，獸戰士族以外的我方怪獸不能攻擊。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1665819,'複製龍 LAD',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，從手牌將1隻其他的等級7以上的怪獸除外可以發動。此卡從手牌特殊召喚。\u000a②：以我方場上1隻表側表示怪獸為對象可以發動。從牌組將1隻和那隻怪獸卡名不同且等級、攻擊力、守備力之中有2個以上相同的怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能發動效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1669772,'魔力淨化','捨棄1張手牌可以發動。場上的表側表示的永續魔法卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1683982,'毒蛇的怨念',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在魔法與陷阱區域存在，爬蟲類族以外的我方怪獸不能攻擊，不能發動效果。\u000a②：我方場上的表側表示的爬蟲類族怪獸被戰鬥破壞的場合，或被送去墓地的場合可以發動。從牌組將1隻等級4以下的爬蟲類族怪獸特殊召喚。\u000a③：魔法與陷阱區域的此卡被破壞的場合可以發動。除外的我方的爬蟲類族怪獸全部回到墓地。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1686814,'奧特瑪雅・卓爾金',unistr('規則上此卡的等級當作12。此卡不能同步召喚，只能將我方場上的表側表示的等級5以上且相同等級的協調和協調以外的怪獸各1隻送去墓地來特殊召喚。\u000a①：1回合1次，我方場上有魔法、陷阱卡覆蓋時可以發動。從額外牌組將1隻「動力工具」同步怪獸或等級7、8的龍族同步怪獸特殊召喚。\u000a②：只要場上有其他的我方的同步怪獸存在，場上的此卡不會成為攻擊對象以及效果對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1688285,'西托莉絲的蟲惑魔',unistr('等級4怪獸×2\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：持有超量素材的此卡，不受和此卡作為超量素材持有的怪獸相同種族的怪獸（除了此卡以外）發動的效果以及陷阱卡的效果影響。\u000a②：去除此卡的1個超量素材可以發動。從牌組將1隻「蟲惑魔」怪獸加入手牌。\u000a③：原持有者是對手的怪獸因效果被送去墓地的場合或被表側除外的場合可以發動。將其中1隻作為此卡的超量素材。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1689516,'百獸的大遊行','我方場上表側表示存在的獸族怪獸的攻擊力直到回合結束時上升我方場上的獸族怪獸數量×200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1697104,'PSY骨架裝備ε',unistr('此卡不能通常召喚，只能用卡的效果特殊召喚。\u000a①：我方場上沒有怪獸存在，對手的陷阱卡發動時可以發動。選手牌的此卡和我方的手牌、牌組、墓地1隻「PSY骨架驅動者」特殊召喚，那個發動無效並破壞。此效果特殊召喚的怪獸在結束階段被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1710476,'Sin 電子終結龍',unistr('此卡不能通常召喚。只能從額外牌組將1隻「電子終結龍」除外來特殊召喚。\u000a①：「Sin」怪獸在場上只能有1隻表側表示存在。\u000a②：只要此卡在怪獸區域存在，其他的我方怪獸不能攻擊宣言。\u000a③：沒有場地魔法卡表側表示存在的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1712616,'騎甲蟲空殺舞隊',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有「騎甲蟲」怪獸存在，對手發動怪獸的效果時可以發動。那個發動無效並破壞。\u000a②：此卡在墓地存在，我方場上有攻擊力3000以上的昆蟲族怪獸存在的場合，我方結束階段從我方墓地將1隻昆蟲族怪獸除外可以發動。此卡在我方場上覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1735088,'發條修補 發條微機',unistr('「發條」怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。從牌組將1張「發條」卡片加入手牌。\u000a②：將我方場上1隻表側表示的「發條」怪獸裡側表示除外可以發動。從牌組將1隻和那隻同名的怪獸特殊召喚。\u000a③：此卡被破壞送去墓地的場合，以我方場上1隻「發條」超量怪獸為對象可以發動。此卡重疊在那隻怪獸下方作為超量素材。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1759808,'幻魔的肖像',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以對手場上1隻表側表示怪獸為對象可以發動。從我方的牌組、額外牌組將1隻那隻怪獸的同名怪獸特殊召喚。此效果特殊召喚的怪獸在下個回合的結束階段回到持有者的牌組。此卡的發動後，直到回合結束時我方不能從牌組、額外牌組將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1761063,'小貓妖精','貓精靈。與可愛的身姿相反、敏捷的攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1764972,'死亡凱撒龍/爆裂',unistr('此卡不能通常召喚。只能用「爆裂模式」的效果特殊召喚。\u000a此卡特殊召喚成功時，從我方、對手的墓地選擇任意數量的不死族怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸的效果無效化，在這個回合的結束階段時破壞。\u000a此外，場上的此卡被破壞時，可以選擇我方墓地的1隻「死亡凱撒龍」特殊召喚。'),'特殊召喚','特殊召喚「死亡凱撒龍」','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1769875,'幻獸王 客邁拉',unistr('獸族怪獸+惡魔族怪獸\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「有翼幻獸 客邁拉」。\u000a②：此卡融合召喚的場合可以發動。這個回合的結束階段將對手的手牌隨機選1張送去墓地。\u000a③：對手回合，將墓地的此卡除外，以我方墓地1隻獸族、惡魔族、幻想魔族怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1781310,'風林火山',unistr('①：風、水、炎、地屬性怪獸在場上全部存在的場合可以發動。從以下效果挑選1個適用。\u000a●對手場上的怪獸全部破壞。\u000a●對手場上的魔法、陷阱卡全部破壞。\u000a●對手的手牌隨機選2張捨棄。\u000a●我方從牌組抽2張卡。'),'●破壞對手的怪獸','●破壞對手的魔法陷阱卡','●隨機捨棄2張對手的手牌','●抽2張牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(1784619,'荒野盜龍','擅長奔跑的恐龍，利用尖銳的爪子進行攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1784686,'迪馬歐斯之眼',unistr('這個卡名在規則上也當作「傳說之龍 迪馬歐斯」。這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻「黑魔導」怪獸為對象可以發動。只用那1隻怪獸作為融合素材，將1隻那個卡名作為融合素材記載的融合怪獸融合召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1799464,'脫殼蟬',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。在我方場上將1隻「蟬蛻衍生物」（昆蟲族、地、等級3、攻/守0）特殊召喚。只要此效果特殊召喚的衍生物在怪獸區域存在，我方除了昆蟲族怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1799465,'蟬蛻衍生物','由「脫殼蟬」的效果特殊召喚。只要此效果特殊召喚的衍生物在怪獸區域存在，我方除了昆蟲族怪獸以外不能從額外牌組特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1801154,'遠心分離場地','融合怪獸被效果破壞送去墓地的場合，那個原持有者選擇在那隻融合怪獸有記載卡名的自身墓地1隻融合素材怪獸發動。那隻怪獸在自身場上特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1802450,'木遁封印式','1回合1次，可以藉由將我方場上表側表示存在的1隻地屬性怪獸解放，選擇對手墓地的最多2張卡除外。','N/A','對手墓地的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1804528,'被詛咒的棺材',unistr('覆蓋的此卡被破壞送去墓地時，對手從以下效果挑選1個適用。\u000a●自己的手牌隨機選1張捨棄。\u000a●自己場上的1隻怪獸破壞。'),'效果選擇','●自己的手牌隨機選1張捨棄','●自己場上的1隻怪獸破壞','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1825445,'超級量子合神-宏偉合體',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在魔法與陷阱區域存在，我方主要階段1期間，對手不能將場上的「超級量子」卡片作為效果的對象。\u000a②：以我方場上1隻「超級量子」超量怪獸為對象可以發動。選對象怪獸以外的我方場上1隻表側表示怪獸重疊在對象怪獸下方作為超量素材。'),'效果2','請選擇要作為超量素材的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1826676,'玩具騎士',unistr('此卡不能從牌組特殊召喚。\u000a對手場上的怪獸數量比我方場上的怪獸多的場合，此卡可以從手牌特殊召喚。\u000a此卡召喚、特殊召喚成功時，可以從手牌將1隻「玩具騎士」特殊召喚。'),'從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1828513,'六武眾之影-紫炎',unistr('等級4「六武眾」怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以我方場上1隻攻擊力未滿2000的「六武眾」怪獸為對象可以發動。那隻怪獸的原攻擊力直到回合結束時變成2000。此效果在對手回合也能發動。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1833916,'英豪挑戰者 千刃',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，從手牌捨棄1張「英豪」卡片可以發動。從牌組將1隻「英豪」怪獸特殊召喚，此卡變成守備表示。此效果的發動後，直到回合結束時我方除了「英豪」怪獸以外不能特殊召喚。\u000a②：此卡在墓地存在，戰鬥、效果使我方受到傷害時可以發動。此卡攻擊表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1834107,'電力治療','我方場上的雷族怪獸給予對手戰鬥傷害時，依照給予的戰鬥傷害數值回復我方的生命值。','回復LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1834753,'極限瞬動者',unistr('此卡不能特殊召喚。\u000a藉由支付2000生命值，從牌組將2隻等級3的超能族怪獸在我方場上特殊召喚。這個效果於此卡在場上表側表示存在期間只能使用1次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1845204,'簡易結合',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：支付1000生命值可以發動。從額外牌組將1隻等級5以下的融合怪獸當作融合召喚特殊召喚。此效果特殊召喚的怪獸不能攻擊，在結束階段破壞。\u000a\u000a※簡易融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1855886,'傷痕仇屍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡被送去墓地的場合可以發動。從牌組將1張「仇屍」魔法、陷阱卡加入手牌。\u000a②：此卡在墓地存在的狀態，場上的怪獸被解放的場合，從我方墓地將此卡以外的1隻不死族怪獸除外可以發動。此卡特殊召喚。只要此效果特殊召喚的此卡在怪獸區域表側表示存在，我方除了「仇屍」怪獸以外不能特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1855932,'武尊神帝-迦具土',unistr('獸戰士族等級4怪獸×2\u000a此卡超量召喚成功時，從我方牌組上方將5張卡送去墓地。此卡的攻擊力上升這個效果送去墓地的「武尊神」卡片數量×100。\u000a此外，我方場上的獸戰士族的「武尊神」怪獸被戰鬥或效果破壞的場合，可以去除此卡的1個超量素材，作為其中1隻被破壞的怪獸的代替。\u000a「武尊神帝-迦具土」在我方場上只能有1隻表側表示存在。'),'牌組的卡送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861629,'解碼語者',unistr('效果怪獸2隻以上\u000a①：此卡的攻擊力上升此卡指向的怪獸數量×500。\u000a②：對手發動以我方場上的卡為對象的魔法、陷阱、怪獸的效果時，將此卡指向的1隻我方怪獸解放可以發動。那個發動無效並破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861630,'解碼語者',unistr('效果怪獸2隻以上\u000a①：此卡的攻擊力上升此卡指向的怪獸數量×500。\u000a②：對手發動以我方場上的卡為對象的魔法、陷阱、怪獸的效果時，將此卡指向的1隻我方怪獸解放可以發動。那個發動無效並破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861631,'解碼語者',unistr('效果怪獸2隻以上\u000a①：此卡的攻擊力上升此卡指向的怪獸數量×500。\u000a②：對手發動以我方場上的卡為對象的魔法、陷阱、怪獸的效果時，將此卡指向的1隻我方怪獸解放可以發動。那個發動無效並破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1872843,'夢魔鏡的白騎士-盧甫斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用「夢魔鏡」怪獸的效果特殊召喚成功的場合可以發動。這個回合，此卡不會被戰鬥、效果破壞。\u000a②：場地區域有「闇黑的夢魔鏡」存在的場合，我方、對手主要階段和戰鬥階段，解放此卡可以發動。從牌組將1隻「夢魔鏡的黑騎士-盧甫斯」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1876841,'變形鬥士 掃描機',unistr('此卡不能通常召喚。從手牌將1隻「變形鬥士」怪獸除外可以特殊召喚。\u000a①：此卡依照表示形式得到以下效果。\u000a●攻擊表示：1回合1次，我方主要階段可以發動。從牌組將1張「變形鬥士」魔法、陷阱卡加入手牌。那之後，選1張手牌回到牌組最上方。\u000a●守備表示：1回合1次，我方主要階段可以發動。從我方墓地選1隻等級4以下的「變形鬥士」怪獸加入手牌。那之後，選1張手牌回到牌組最上方。'),'●攻擊表示：','●守備表示：','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1896112,'次元誘爆','讓我方場上表側表示存在的1隻融合怪獸回到融合牌組可以發動。雙方各選擇被除外的最多2隻自身的怪獸，在各自的場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1906812,'鐵驅龍 迅妖',unistr('「阿不思的落胤」+這個回合特殊召喚的效果怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。我方場上的此卡的位置向其他的我方的主要怪獸區域移動。那之後，可以將和已移動的此卡相同縱列的其他的表側表示卡全部破壞。\u000a②：此卡被送去墓地的回合的結束階段可以發動。從牌組選1隻「守寶妖精」怪獸或「阿不思的落胤」加入手牌或特殊召喚。'),'效果1','效果2','是否將同縱列表側表示的卡全部破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1918087,'哥布林的小官','對手的生命值是3000以下的場合可以發動。對手的準備階段時，給予對手500傷害。','給予對方500傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1929294,'鑰匙梅思','非常細小的天使。無論是誰都會被那可愛的魅力折服而敞開心扉。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1942635,'王戰的報酬',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要我方場上有衍生物存在，對手不能選擇「王戰」效果怪獸作為攻擊對象。\u000a②：「王戰」效果怪獸被戰鬥破壞的場合發動。對手從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1945387,'E.HERO 新星主宰者',unistr('「E.HERO」怪獸+炎屬性怪獸\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡戰鬥破壞對手怪獸的場合發動。我方從牌組抽1張卡。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1948619,'X.HERO 神奇驅動者',unistr('「HERO」怪獸2隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡指向的我方場上有「HERO」怪獸召喚、特殊召喚的場合，以我方墓地的「融合」魔法卡、「結合」魔法卡、「變身」速攻魔法卡其中任何1張為對象發動。那張卡在我方場上覆蓋。\u000a②：此卡被戰鬥或對手的效果破壞送去墓地的場合可以發動。從手牌將1隻「HERO」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1953925,'古代機械齒輪工兵',unistr('①：只要此卡在怪獸區域存在，以此卡為對象的陷阱卡的效果無效化並破壞。\u000a②：此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a③：此卡攻擊的傷害步驟結束時，以對手場上1張魔法、陷阱卡為對象發動。那張對手的魔法、陷阱卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1965724,'憤怒的毛毛','我方的怪獸區域有「毛毛」存在的狀態，我方場上的其他的天使族怪獸被破壞時適用。這個回合，只要此卡在魔法與陷阱區域存在，我方場上的「毛毛」的攻擊力變成3000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1966438,'雙極的破械神',unistr('我方1回合只能特殊召喚1次「雙極的破械神」。\u000a①：我方場上的卡被戰鬥、效果破壞的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合，捨棄1張手牌可以發動。場上1張卡破壞。\u000a③：場上的此卡被破壞送去墓地的回合的結束階段可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合回到牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1969506,'傀儡儀式-人偶邪儀','我方的生命值比對手少2000以上的場合可以發動。從我方墓地選擇2隻等級8的「奇巧人偶」怪獸特殊召喚。「傀儡儀式-人偶邪儀」在1回合只能發動1張，此卡發動的整回合中，我方不能進行戰鬥階段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1980574,'躍空垂耳兔飛行隊',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡在手牌存在的場合，對手主要階段，以我方場上1隻表側表示怪獸為對象可以發動。此卡從手牌特殊召喚。那之後，只用此卡和對象怪獸為素材進行同步召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1984618,'天底的使徒',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從額外牌組將1隻怪獸送去墓地。那之後，將攻擊力在送去墓地的怪獸的攻擊力以下的1隻「教導」怪獸或「阿不思的落胤」從我方的牌組、墓地加入手牌。此卡的發動後，直到回合結束時我方不能從額外牌組將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1992816,'No.9 天蓋星 戴森球',unistr('等級9怪獸×2\u000a①：對手場上有攻擊力高於此卡的怪獸存在的場合，我方主要階段1去除此卡的1個超量素材可以發動。這個回合，此卡可以直接攻擊。\u000a②：持有超量素材的此卡被攻擊的戰鬥步驟可以發動1次。那次攻擊無效。\u000a③：此卡在沒有超量素材的狀態被選擇作為攻擊對象時，以我方墓地2隻怪獸為對象可以發動。那些怪獸重疊在此卡下方作為超量素材。'),'效果2','效果3','效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1995985,'沉默劍士 LV3',unistr('①：只要此卡在怪獸區域存在，以此卡為對象的對手的魔法卡的效果無效化。\u000a②：我方準備階段將場上的此卡送去墓地可以發動。從手牌、牌組將1隻「沉默劍士 LV5」特殊召喚。此效果在此卡召喚、特殊召喚、反轉的回合不能發動。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2006591,'覺醒的罪寶',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有等級5以上的幻想魔族怪獸存在，對手場上有3隻以上怪獸存在的場合，以對手場上最多3張卡為對象可以發動。那些卡回到手牌。\u000a②：此卡在墓地存在，我方場上有等級5以上的幻想魔族怪獸存在的場合可以發動。此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2009101,'BF-疾風之葛爾',unistr('①：我方場上有「BF-疾風之葛爾」以外的「BF」怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。那隻對手怪獸的攻擊力、守備力變成一半。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2047519,'伏兵','對手將怪獸召喚、反轉召喚時可以發動。從手牌將1隻等級4以下的闇屬性怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2055403,'時光的落穴',unistr('①：對手從手牌、額外牌組將怪獸特殊召喚時可以發動。那些從手牌、額外牌組特殊召喚的怪獸回到持有者的牌組。那之後，我方失去回去的怪獸數量×1000生命值。\u000a\u000a※時空的落穴'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2061963,'No.104 假面魔蹈士 閃光',unistr('等級4怪獸×3\u000a①：1回合1次，我方主要階段可以發動。對手牌組最上方的卡送去墓地。\u000a②：我方、對手的戰鬥階段中對手發動怪獸的效果時，去除此卡的1個超量素材可以發動。那個發動無效，給予對手800傷害。'),'效果2','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2067935,'劍鬥獸 訓練師',unistr('此卡被「劍鬥獸」怪獸的效果特殊召喚成功時，選擇我方墓地的1隻「劍鬥獸」怪獸可以發動。那隻怪獸除外，直到結束階段時，此卡和那隻怪獸當作同名卡。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到牌組，從牌組將「劍鬥獸 訓練師」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'除外','特殊召喚','解除複製效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2084239,'溼地草原','全部的水族、水屬性、等級2以下的怪獸的攻擊力上升1200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2088870,'蠕蟲 勝利',unistr('反轉：爬蟲類族的「蠕蟲」怪獸以外的場上表側表示存在的怪獸全部破壞。\u000a此外，只要此卡在場上表側表示存在，此卡的攻擊力上升我方墓地的爬蟲類族的「蠕蟲」怪獸數量×500。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2089016,'先史遺產 圖什帕火箭',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，從牌組、額外牌組將1隻「先史遺產」怪獸送去墓地，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時下降送去墓地的怪獸的等級或階級×200。\u000a②：用場上的此卡為素材超量召喚的「No.」怪獸得到以下效果。\u000a●此卡在1次戰鬥階段中可以向怪獸攻擊2次。'),'效果1','「先史遺產 圖什帕火箭」的效果2適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2091298,'鬼宿星聖',unistr('等級4「星聖」怪獸×2\u000a①：1回合1次，我方場上的「星聖」怪獸進行戰鬥的從傷害步驟開始時到傷害計算前為止，去除此卡的1個超量素材可以發動。那隻怪獸的攻擊力直到回合結束時上升1000。此效果在對手回合也能發動。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2095764,'水龍星-贔屭',unistr('「水龍星-贔屭」的①效果1回合只能使用1次。\u000a①：我方場上的此卡被戰鬥、效果破壞送去墓地時可以發動。從牌組將「水龍星-贔屭」以外的1隻「龍星」怪獸攻擊表示特殊召喚。\u000a②：1回合1次，對手的主要階段以及戰鬥階段可以發動。只用我方場上的「龍星」怪獸為同步素材同步召喚。\u000a③：用此卡為同步素材的同步怪獸不受陷阱卡的效果影響。'),'特殊召喚','不受陷阱影響','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2099841,'微笑世界','①：場上的全部怪獸的攻擊力直到回合結束時上升場上的怪獸數量×100。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2102065,'海底冰柱水馬',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，以我方墓地1隻水屬性怪獸為對象可以發動。此卡的攻擊力直到回合結束時上升對象怪獸的攻擊力數值。\u000a②：此卡被送去墓地的場合，以我方場上1隻水屬性怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2106266,'奔馳的蓋亞',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要我方的怪獸區域有「龍騎士蓋亞」存在，對手在戰鬥階段中不能發動效果。\u000a②：可以從以下效果選擇1個發動。\u000a●向對手展示手牌的1隻「暗黑騎士蓋亞」怪獸可以發動。從牌組將1隻龍族、等級5怪獸加入手牌。\u000a●向對手展示手牌的1隻龍族、等級5怪獸可以發動。從牌組將1隻「暗黑騎士蓋亞」怪獸加入手牌。'),'●龍族、等級5怪獸加入手牌','●「暗黑騎士蓋亞」怪獸加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2111707,'XY-神龍加農砲',unistr('「X-首領加農」+「Y-龍形首領」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。此卡不能從墓地特殊召喚。\u000a①：捨棄1張手牌，以對手場上1張表側表示的魔法、陷阱卡為對象可以發動。那張對手的表側表示的卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2116237,'世壞輪迴',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻表側表示的「維薩斯-星霜」直到結束階段除外可以發動。從額外牌組將1隻攻擊力3000的「哈特」怪獸無視召喚條件特殊召喚。此效果特殊召喚的怪獸只能發動1次效果，在結束階段裡側除外。\u000a②：此卡在墓地存在的狀態，對手從額外牌組將怪獸特殊召喚的場合可以發動。此卡加入手牌。'),'效果1','效果2','回到場上','結束階段裡側除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(2118022,'河童','河童的首領，攻擊力意外的高，守備力偏低。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2122975,'陷阱捕獲','我方陷阱卡發動時，捨棄1張手牌連鎖發動。連鎖發動的陷阱卡送去墓地時，那張卡回到手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2129638,'青眼雙爆裂龍',unistr('「青眼白龍」+「青眼白龍」\u000a此卡只能用融合召喚或以下方法特殊召喚。\u000a●將我方的怪獸區域的上述卡送去墓地，從額外牌組特殊召喚。\u000a①：此卡不會被戰鬥破壞。\u000a②：此卡在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a③：此卡的攻擊沒有破壞對手怪獸的傷害步驟結束時可以發動。那隻對手怪獸除外。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2130625,'白衣的天使','我方因戰鬥或效果受到傷害時可以發動。我方回復1000生命值。我方墓地有「白衣的天使」存在的場合，我方回復那個數量×500生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2133971,'聯合控制器',unistr('機械族、光屬性怪獸+「Y-敏捷龍首」或「Z-無盡履帶」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。這個卡名的①效果1回合只能使用1次。\u000a①：此卡從額外牌組特殊召喚的場合可以發動。從牌組將1張效果文本記載「聯合怪獸」的魔法、陷阱卡加入手牌。\u000a②：1回合1次，我方主要階段可以發動。從手牌將1隻機械族、光屬性的，通常怪獸或聯合怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2134346,'阿修羅',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡可以向對手場上的全部怪獸各進行1次攻擊。'),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2137678,'機皇兵 神陸一型',unistr('此卡的攻擊力上升此卡以外的場上表側表示存在的「機皇」怪獸數量×100。\u000a此卡召喚成功時，可以選擇對手場上的1隻表側表示怪獸，那隻怪獸的攻擊力直到回合結束時變成一半。'),'攻擊力變成一半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2139640,'阿瑪比埃小姐','①：我方主要階段1開始時，向對手展示手牌的此卡可以發動。雙方玩家回復300生命值。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2144946,'F.A. 越野大獎賽',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在場地區域存在，場上的「F.A.」怪獸的等級在主要階段期間上升2。\u000a②：我方的「F.A.」怪獸被戰鬥破壞時可以發動。對手的手牌隨機選1張捨棄。\u000a③：場上的表側表示的此卡被效果破壞的場合可以發動。從牌組將「F.A. 越野大獎賽」以外的1張「F.A.」卡片加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2148918,'機甲忍法 銹蝕之霧','我方場上有「忍者」怪獸存在，對手場上有怪獸特殊召喚時，那些特殊召喚的怪獸的攻擊力變成一半。','攻擊力變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2158562,'電子女首席','①：此卡上級召喚的場合發動。場上的表側表示的魔法卡全部破壞。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2191144,'夜蝶刺客',unistr('等級4怪獸×3\u000a1回合1次，去除此卡的1個超量素材可以發動。此卡的攻擊力上升場上的超量素材數量×300的數值。'),'攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2196767,'傳說的賭博師','投擲3次硬幣。3次都是正面的場合，對手場上的怪獸全部破壞。2次正面的場合，對手的手牌隨機選1張捨棄。1次正面的場合，我方場上的1張卡破壞。3次都是反面的場合，我方的手牌全部捨棄。這個效果1回合只能在我方的主要階段中使用1次。','擲硬幣','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2203790,'XX-軍刀 迅雷',unistr('協調+協調以外的「X-軍刀」怪獸1隻以上\u000a①：此卡同步召喚時，以場上最多3張魔法、陷阱卡為對象可以發動。那些卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204038,'華爾裘蓮 布倫希爾德',unistr('①：此卡的攻擊力上升對手場上的怪獸數量×500。\u000a②：此卡不受對手的魔法卡的效果影響。\u000a③：對手怪獸的攻擊宣言時可以發動。此卡的守備力下降1000，這個回合，我方的「華爾裘蓮」怪獸不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204140,'生者之書－禁斷的咒術－','①：以我方墓地1隻不死族怪獸和對手墓地1隻怪獸為對象可以發動。那隻我方的不死族怪獸特殊召喚。那隻對手怪獸除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2220237,'安全守衛者',unistr('電子界族連結怪獸1隻\u000a此卡不能作為連結素材。\u000a①：「安全守衛者」在我方場上只能有1隻表側表示存在。\u000a②：此卡特殊召喚成功的回合，我方受到的效果傷害變成0。\u000a③：我方因戰鬥、效果受到傷害的場合，1回合只有1次讓那次傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2250266,'變形鬥士 釘書機',unistr('此卡依照表示形式得到以下效果。\u000a●攻擊表示：只要此卡在場上表側表示存在，對手不能選擇其他怪獸作為攻擊對象。此卡被戰鬥破壞的場合，破壞此卡的怪獸的攻擊力下降300。\u000a●守備表示：此卡不會被戰鬥破壞。此卡被攻擊的那次傷害計算後，選擇對手場上的1隻表側攻擊表示怪獸變成守備表示，此卡的表示形式變成攻擊表示。'),'●攻擊表示：','●守備表示：','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2254222,'疾行機人 飛翼同步者',unistr('【靈擺效果】\u000a①：1回合1次，可以發動。我方的靈擺區域1張風屬性、等級2的靈擺怪獸卡和此卡破壞，從額外牌組將1隻「清透翼同步龍」當作同步召喚特殊召喚。這個回合，我方的靈擺區域的卡不會被效果破壞，我方除了風屬性怪獸以外不能特殊召喚。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：此卡表側加入額外牌組的場合，如果我方場上的風屬性同步怪獸的種族是2種以上可以發動。從牌組將1張「疾行機人」魔法、陷阱卡送去墓地。'),'靈擺效果1','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263869,'月女神之鏃',unistr('應對此卡的發動，對手不能發動怪獸的效果。\u000a①：從額外牌組將1隻怪獸送去墓地，以對手場上1隻和那隻怪獸相同種類（融合、同步、超量、靈擺、連結）的怪獸為對象可以發動。那隻怪獸回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263870,'月女神之鏃',unistr('應對此卡的發動，對手不能發動怪獸的效果。\u000a①：從額外牌組將1隻怪獸送去墓地，以對手場上1隻和那隻怪獸相同種類（融合、同步、超量、靈擺、連結）的怪獸為對象可以發動。那隻怪獸回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2266498,'仇屍復合','①：向對手展示要儀式召喚的1隻手牌的「仇屍」儀式怪獸。直到等級合計和展示的儀式怪獸的等級相同為止，選被除外的任意數量我方的「仇屍」怪獸裡側守備表示特殊召喚（同名卡最多1張）。那之後，將那些裡側守備表示怪獸全部解放，從手牌儀式召喚那隻儀式怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2273734,'衛星騎士 河鼓二',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚的場合，以「衛星騎士 河鼓二」以外的我方墓地1隻「星騎士」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果的發動後，直到回合結束時「星騎士」怪獸以外的我方場上的怪獸不能攻擊。'),'從墓地特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2287848,'仇屍復醒',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：捨棄1張手牌，以我方墓地1隻「仇屍」怪獸和1張儀式魔法卡為對象可以發動。那隻怪獸守備表示特殊召喚，那張儀式魔法卡加入手牌。\u000a②：將墓地的此卡除外，以被除外的5隻我方的不死族怪獸為對象可以發動。那些怪獸加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295440,'一換一','①：從手牌將1隻怪獸送去墓地可以發動。從手牌、牌組將1隻等級1怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295441,'一換一','①：從手牌將1隻怪獸送去墓地可以發動。從手牌、牌組將1隻等級1怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295831,'和平之輪','①：對手場上有3隻以上怪獸存在，我方場上沒有卡存在的場合，在我方抽牌階段藉由將通常抽牌抽到的此卡持續公開，那個回合的主要階段1可以發動。我方從牌組選1張卡，給雙方確認並加入手牌。','是否持續公開「和平之輪」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311090,'衛星閃靈 胡蘿蔔精靈',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上有等級2或連結2的怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：對手發動魔法、陷阱卡的效果時，將我方場上1隻其他的等級2、階級2、連結2的怪獸解放可以發動。那個效果無效。將階級2或連結2的怪獸解放發動的場合，隨後可以將那張無效的卡破壞。'),'效果1','效果2','是否將那張卡破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311603,'機砲裝甲車','裝備著重型機槍的裝甲車，怎樣惡劣的地形都能逾越。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2314238,'黑、魔、導','①：我方場上有「黑魔導」存在的場合可以發動。對手場上的魔法、陷阱卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2316186,'魔法之國的公主-古蘭',unistr('此卡不能通常召喚。只能用「王女的試煉」的效果特殊召喚。\u000a我方的準備階段時，給予對手相當於對手場上的怪獸數量×600傷害。'),'給予對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2322421,'皇道戰士',unistr('「皇道同步者」+協調以外的怪獸2隻以上\u000a①：1回合1次，我方主要階段可以發動。從牌組將1隻等級2以下的戰士族、機械族怪獸特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2326738,'死亡駱駝',unistr('①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉召喚成功的場合發動。我方從牌組抽1張卡。'),'變成裡側守備表示','抽1張卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333365,'極星將 提爾',unistr('場上沒有此卡以外的「極星」怪獸表側表示存在的場合，此卡破壞。\u000a只要此卡在場上表側表示存在，對手不能選擇「極星將 提爾」以外的「極星」怪獸作為攻擊對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333466,'破壞龍 鋼多拉G',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上有「光之黃金櫃」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡的攻擊力上升除外狀態的卡片數量×300。\u000a③：將生命值支付一半可以發動。場上的其他卡全部破壞並除外。那之後，從牌組將1隻記載「光之黃金櫃」的卡名的等級7以下的怪獸特殊召喚。此效果特殊召喚的怪獸的等級上升此效果破壞的卡片數量。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2339825,'T.G.-封鎖',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有機械族的「T.G.」怪獸存在，怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並破壞。\u000a②：此卡在墓地存在的狀態，同步怪獸被除外的場合可以發動。此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2344618,'月光舞會',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡發動的回合的我方主要階段可以發動。從牌組將1隻「月光」怪獸送去墓地。\u000a②：我方將「月光」怪獸融合召喚的場合可以發動。我方的墓地、除外狀態的1張「融合」加入手牌。那之後，可以選1張我方的手牌捨棄。那個場合，這個回合，我方將「月光」怪獸融合召喚的場合只有1次，也能將我方墓地的怪獸除外作為融合素材。'),'效果1','效果2','是否捨棄1張手牌？','墓地的怪獸除外作為融合素材（月光舞會）','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347477,'微碼編碼員',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上的電子界族怪獸作為「碼語者」怪獸的連結素材的場合，手牌的此卡也能作為連結素材。\u000a②：此卡作為「碼語者」怪獸的連結素材從手牌、場上送去墓地的場合可以發動。從牌組將1張「電腦網」魔法、陷阱卡加入手牌。場上的此卡作為素材的場合，可以將那1張卡改成1隻電子界族、等級4怪獸。'),'效果2','從場上送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347656,'白銀之城的拉比麗斯',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：應對我方的通常陷阱卡的發動，對手不能發動怪獸的效果。\u000a②：以我方墓地1張通常陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡在我方場上沒有惡魔族怪獸存在的場合不能發動。\u000a③：我方的通常陷阱卡的效果讓怪獸從場上離開的場合可以發動。對手的手牌、場上1張卡破壞（從手牌是隨機選）。'),'效果2','效果3','「白銀之城的拉比麗斯」的效果2適用中','隨機選對手的手牌','選對手場上的卡','','','','','','','','','','','');
INSERT INTO texts VALUES(2347657,'白銀之城的拉比麗斯',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：應對我方的通常陷阱卡的發動，對手不能發動怪獸的效果。\u000a②：以我方墓地1張通常陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡在我方場上沒有惡魔族怪獸存在的場合不能發動。\u000a③：我方的通常陷阱卡的效果讓怪獸從場上離開的場合可以發動。對手的手牌、場上1張卡破壞（從手牌是隨機選）。'),'效果2','效果3','「白銀之城的拉比麗斯」的效果2適用中','隨機選對手的手牌','選對手場上的卡','','','','','','','','','','','');
INSERT INTO texts VALUES(2347658,'白銀之城的拉比麗斯',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：應對我方的通常陷阱卡的發動，對手不能發動怪獸的效果。\u000a②：以我方墓地1張通常陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡在我方場上沒有惡魔族怪獸存在的場合不能發動。\u000a③：我方的通常陷阱卡的效果讓怪獸從場上離開的場合可以發動。對手的手牌、場上1張卡破壞（從手牌是隨機選）。'),'效果2','效果3','「白銀之城的拉比麗斯」的效果2適用中','隨機選對手的手牌','選對手場上的卡','','','','','','','','','','','');
INSERT INTO texts VALUES(2356994,'偉大天狗',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡給予對手戰鬥傷害的場合，跳過下個對手戰鬥階段。'),'回到手牌','跳過戰鬥階段','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2359348,'靈擺領域','①：我方場上的怪獸只有靈擺怪獸的場合，以我方的靈擺區域2張卡為對象可以發動。那2張卡破壞，這個回合雙方不能進行靈擺召喚以外的特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2362787,'救援光','①：支付800生命值，以被除外的1隻我方的光屬性怪獸為對象可以發動。那隻怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2364438,'魔妖迴天',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組選「魔妖迴天」以外的1張「魔妖」卡片加入手牌或送去墓地。'),'是否加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2368215,'魔界劇團-高超導演',unistr('「魔界劇團」靈擺怪獸1隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：以我方的靈擺區域1張卡為對象可以發動。那張卡特殊召喚。那之後，從牌組的怪獸以及我方的額外牌組的表側表示的靈擺怪獸之中選1隻和特殊召喚的怪獸卡名不同的「魔界劇團」靈擺怪獸在我方的靈擺區域放置。此效果的發動後，直到回合結束時我方除了「魔界劇團」怪獸以外不能召喚、特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2370081,'鋼之甲羅',unistr('只能給水屬性怪獸裝備。\u000a裝備怪獸的攻擊力上升400，守備力下降200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2371506,'超量反射','以場上的超量怪獸為對象的效果怪獸的效果、魔法、陷阱卡的發動無效並破壞。那之後，給予對手800傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2372506,'混沌禮帽','①：對手發動怪獸的效果、通常魔法、通常陷阱卡時可以發動。從牌組將卡名不同的3張魔法、陷阱卡當作卡名是「混沌禮帽」的通常怪獸（魔法使族、闇、等級8、攻/守0），和1隻記載「光與闇的儀式」的卡名的我方的主要怪獸區域的怪獸混合洗牌並裡側守備表示覆蓋。那之後，那個對手發動的效果變成「對手場上1隻裡側守備表示怪獸破壞」。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2376209,'伯吉斯異獸 依爾東缽',unistr('①：以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到回合結束時上升500。\u000a②：陷阱卡發動時，連鎖那個發動可以在墓地發動此效果。此卡變成通常怪獸（水族、水、等級2、攻1200/守0）在怪獸區域特殊召喚（不當作陷阱卡）。此效果特殊召喚的此卡不受怪獸的效果影響，從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2377034,'新炎獄刺蝟',unistr('此卡被戰鬥破壞的場合，選擇對手墓地的1張卡除外。\u000a場上的此卡被效果破壞的場合，選擇「新炎獄刺蝟」以外的我方墓地1隻守備力200以下的炎屬性怪獸加入手牌。'),'除外','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2390019,'搗蛋魔改造',unistr('①：向對手展示額外牌組的1隻機械族、光屬性的融合怪獸，將我方的手牌、場上、墓地任意數量的「搗蛋」怪獸除外可以發動。依照除外的數量，從我方的手牌、牌組、墓地挑選在展示的怪獸有記載卡名的融合素材怪獸特殊召喚（同名卡最多1張）。\u000a②：將墓地的此卡除外，以被除外的3隻我方的「搗蛋」怪獸為對象可以發動。那些怪獸加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'是否繼續除外「搗蛋」怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2396042,'迪隆的鋼鐵騎兵',unistr('【靈擺效果】\u000a【怪獸效果】\u000a①：此卡和靈擺怪獸進行戰鬥的傷害步驟開始時發動。此卡的攻擊力、守備力直到傷害步驟結束時變成一半。'),'攻守減半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2403771,'動力工具龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：1回合1次，我方主要階段可以發動。從牌組將3張裝備魔法卡向對手展示，對手從其中隨機選1張。那1張卡加入我方的手牌，其餘回到牌組。\u000a②：此卡被破壞的場合，可以將此卡裝備的1張裝備魔法卡送去墓地作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2405631,'游魊之死棘 果格里姆',unistr('魚族協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡和對手怪獸進行戰鬥的傷害步驟開始時可以發動。那隻對手怪獸除外。\u000a②：對手準備階段可以發動。此卡除外。那之後，如果作為此卡的同步召喚的素材的整組怪獸都在我方墓地，可以將那整組特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'對手怪獸除外','此卡除外','是否將整組同步素材怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407147,'熔岩炎火山的侍女','①：此卡被送去墓地時，我方墓地有「熔岩炎火山的侍女」以外的「熔岩」怪獸存在的場合可以發動。從牌組將1隻「熔岩」怪獸送去墓地。','送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407234,'No.69 徽章神 盾徽',unistr('等級4怪獸×3\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡特殊召喚的場合發動。此卡以外的場上的全部超量怪獸的效果無效化。\u000a②：以場上1隻其他的超量怪獸為對象可以發動。此卡直到結束階段得到和那隻怪獸的原本的卡名、效果相同的卡名、效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2411269,'龍絕蘭',unistr('衍生物以外的怪獸2隻以上\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。依照雙方墓地的怪獸的種族和那個數量適用以下效果。\u000a●龍族：給予對手那個數量×100傷害。\u000a●恐龍族：此卡的攻擊力上升那個數量×200。\u000a●海龍族：對手場上的全部怪獸的攻擊力下降那個數量×300。\u000a●幻龍族：我方回復那個數量×400生命值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2414168,'中斷反抗軍',unistr('①：我方受到戰鬥傷害時可以發動。此卡從手牌特殊召喚。此效果特殊召喚的此卡的攻擊力上升受到的傷害的數值。\u000a②：1回合1次，此卡以外的我方守備表示怪獸被對手怪獸攻擊的傷害計算時可以發動。那隻我方怪獸在那次傷害計算時變成和此卡具有相同守備力，不會被那次戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2420921,'光道精靈 雪兒',unistr('此卡的攻擊力上升我方墓地的「光道」怪獸種類×300。\u000a我方結束階段發動。從我方牌組上方將2張卡送去墓地。'),'從牌組上方送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2434862,'方界降世',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。從牌組將1隻「方界胤 毗濕奴」特殊召喚，攻擊對象轉移到那隻怪獸進行傷害計算。\u000a②：我方的生命值比對手少2000以上的場合，將墓地的此卡除外可以發動。從我方的手牌、牌組、墓地選1隻「方界胤 毗濕奴」特殊召喚。只有對手場上有怪獸存在的狀態發動的場合，隨後可以選最多2隻「方界胤 毗濕奴」特殊召喚。'),'效果1','效果2','是否繼續特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2460565,'衝鋒陷陣的隊長',unistr('①：此卡召喚成功時可以發動。從手牌將1隻等級4以下的怪獸特殊召喚。\u000a②：只要此卡在怪獸區域存在，對手不能選擇其他的戰士族怪獸作為攻擊對象。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2461031,'甲蟲裝機 瓢蟲',unistr('1回合1次，可以從我方的手牌、墓地將1隻「甲蟲裝機」怪獸當作裝備卡給此卡裝備。\u000a此卡已當作裝備卡裝備的場合，裝備怪獸的等級上升2，攻擊力、守備力上升此卡的對應數值。\u000a藉由將當作裝備卡裝備的此卡送去墓地，選擇我方場上1隻怪獸，等級上升最多2。'),'裝備','選擇要上升等級的怪獸','等級上升1','等級上升2','','','','','','','','','','','','');
INSERT INTO texts VALUES(2463794,'刻魔的鎮魂棺',unistr('惡魔族、光屬性怪獸1隻\u000a我方1回合只能特殊召喚1次「刻魔的鎮魂棺」，那個②效果1回合只能使用1次。\u000a①：我方、對手的主要階段，將此卡解放可以發動。從手牌、牌組將1隻「刻魔」怪獸特殊召喚。\u000a②：以連結怪獸以外的我方場上1隻惡魔族、光屬性怪獸為對象可以發動。從我方的場上、墓地將此卡當作攻擊力上升600的裝備魔法卡給那隻我方怪獸裝備。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2468169,'封印師 明晴','少數會使用封印符咒的人物。其來歷至今還都是個謎團。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2483611,'水之舞女','從瓶中不斷流淌的水，變成龍的形狀發動攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2501624,'魔術師的弟子-黑魔導女孩',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：此卡可以捨棄1張手牌，從手牌特殊召喚。這個方法特殊召喚的此卡的卡名當作「黑魔導女孩」。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「光之黃金櫃」加入手牌。\u000a③：此卡的攻擊力上升記載「光之黃金櫃」的卡名的雙方墓地的怪獸數量×300。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2504891,'骷髏主教','「魔鬼的智慧」+「魔天老」。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2507443,'女首席之光',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：可以從以下效果選擇1個發動。\u000a●將我方場上1隻戰士族、地屬性怪獸解放，從手牌、牌組將1隻戰士族、光屬性怪獸特殊召喚。\u000a●我方、對手的主要階段可以發動。進行手牌的1隻戰士族怪獸的召喚。\u000a②：我方主要階段將墓地的此卡除外可以發動。從牌組將1隻戰士族、天使族的「電子」怪獸加入手牌。'),'效果1','效果2','●解放並特殊召喚','●進行召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511717,'真六武眾-影鬼',unistr('①：此卡召喚成功時可以發動。從手牌將1隻等級4以下的「六武眾」怪獸特殊召喚。\u000a②：我方場上有「真六武眾-影鬼」以外的「六武眾」怪獸存在的場合，此卡的攻擊力上升1500。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2519690,'天翔的龍騎士蓋亞',unistr('「暗黑騎士蓋亞」怪獸+龍族怪獸\u000a①：只要此卡在怪獸區域存在，卡名當作「龍騎士蓋亞」。\u000a②：此卡特殊召喚成功的場合可以發動。從我方的牌組、墓地選1張「螺旋槍殺」加入手牌。\u000a③：此卡向對手怪獸攻擊宣言時可以發動。那隻對手怪獸的表示形式變更。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2521011,'威炎星-呼燕灼',unistr('此卡可以將我方場上3張表側表示的「炎舞」魔法、陷阱卡送去墓地，從手牌特殊召喚。\u000a此卡召喚、特殊召喚成功時，可以從牌組選1張「炎舞」陷阱卡在我方場上覆蓋。「威炎星-呼燕灼」的這個效果1回合只能使用1次。\u000a只要此卡在場上表側表示存在，我方場上的獸戰士族怪獸不會成為對手的效果的對象。'),'從手牌特殊召喚（威炎星-呼燕灼）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2525268,'魔導騎士 防禦者',unistr('①：此卡召喚的場合發動。給此卡放置1個魔力計數器（最多1個）。\u000a②：1回合1次，場上的魔法使族怪獸被破壞的場合，可以去除那個數量的我方場上的魔力計數器作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2526224,'炎王神獸 麒麟',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，我方、對手的主要階段可以發動。此卡以外的我方的手牌、場上（表側表示）1隻炎屬性怪獸破壞，此卡特殊召喚。\u000a②：此卡被破壞送去墓地的場合可以發動。從我方的手牌、墓地將「炎王神獸 麒麟」以外的1隻「炎王」怪獸特殊召喚。那之後，可以將場上1張卡破壞。'),'效果1','效果2','是否將場上的1張卡破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2530830,'銀河眼光波刃龍',unistr('等級9怪獸×3\u000a此卡也能重疊在我方場上的階級8的「銀河眼」超量怪獸上方來超量召喚。此卡不能作為超量召喚的素材。\u000a①：1回合1次，去除此卡的1個超量素材，以場上1張卡為對象可以發動。那張卡破壞。\u000a②：超量召喚的此卡被對手怪獸的攻擊或對手的效果破壞送去墓地的場合，以我方墓地1隻「銀河眼光波龍」為對象可以發動。那隻怪獸特殊召喚。'),'是否重疊在「銀河眼」超量怪獸上方來超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2542230,'緋暗紅之繭',unistr('①：以我方場上1隻龍族同步怪獸為對象可以發動此卡。此卡當作裝備卡給那隻怪獸裝備。\u000a②：用此卡的效果裝備此卡的怪獸和對手怪獸進行戰鬥的場合，直到那次傷害步驟結束時對手場上的全部表側表示怪獸的效果無效化。\u000a③：此卡被送去墓地的回合的結束階段，以我方墓地1隻「暗紅惡魔龍」為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2547033,'幻變騷靈鬧鬼死鎖',unistr('這個卡名的①②效果1回合各能使用1次。「幻變騷靈」卡片的效果覆蓋的此卡在覆蓋的回合也能發動。\u000a①：作為此卡的發動時的效果處理，從手牌將1隻「幻變騷靈」怪獸送去墓地。\u000a②：對手發動陷阱卡時，從手牌將1隻「幻變騷靈」怪獸送去墓地可以發動。那個效果無效並破壞。'),'','適用「幻變騷靈鬧鬼死鎖」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2561846,'侵食細胞「A」','給對手場上的1隻表側表示怪獸放置1個A計數器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2563463,'流離的獅鷲騎手',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，我方場上沒有怪獸存在的場合或有「勇者衍生物」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方場上有「勇者衍生物」存在，魔法、陷阱、怪獸的效果發動時可以發動。場上的此卡回到牌組，那個發動無效並破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2572890,'威風妖怪大暴風',unistr('①：解放我方場上1隻魔法使族、風屬性怪獸可以發動以下效果。\u000a●怪獸的效果發動時可以發動。那個發動無效並破壞。\u000a●我方或對手將怪獸特殊召喚之際可以發動。那次特殊召喚無效，那些怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2584136,'鮫章魚',unistr('此卡被對手怪獸戰鬥破壞送去墓地時，可以將此卡當作裝備卡給那隻對手怪獸裝備。\u000a用此效果裝備此卡的怪獸的攻擊力變成0，不能變更表示形式。'),'裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2602411,'破壞劍-巫師爆裂劍',unistr('①：我方主要階段以我方場上1隻「爆裂劍士」為對象可以發動。從我方的手牌、場上將這隻怪獸當作裝備卡給那隻我方怪獸裝備。\u000a②：此卡裝備中的場合，對手不能發動墓地的怪獸的效果。\u000a③：將裝備的此卡送去墓地，以「破壞劍-巫師爆裂劍」以外的我方墓地1隻「破壞劍」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2609443,'先史遺產 維摩那',unistr('等級5怪獸×2\u000a①：我方、對手回合1次，以場上1隻表側表示怪獸，和我方墓地1隻「先史遺產」怪獸或超量怪獸為對象可以發動。那隻場上的怪獸的攻擊力直到回合結束時上升作為對象的墓地的怪獸的攻擊力的一半數值。那之後，作為對象的墓地的怪獸作為此卡的超量素材。\u000a②：1回合1次，對手發動怪獸的效果時，去除此卡的2個超量素材可以發動。那個發動無效。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618045,'光子充能者','1回合1次，在我方的主要階段時可以發動。此卡的攻擊力直到下個我方準備階段時變成原攻擊力的2倍。此效果發動的整回合中，此卡不能攻擊。','改變攻擊力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618725,'GMX同絆者 瑟蘭迪亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡可以發動。從手牌將1隻「GMX」怪獸或恐龍族怪獸特殊召喚。這個回合，我方只能用「GMX」怪獸直接攻擊。\u000a②：此卡被怪獸的效果特殊召喚的場合可以發動。我方的手牌、墓地、除外狀態的等級4以下的1隻「GMX」怪獸或恐龍族怪獸守備表示特殊召喚。'),'從手牌特殊召喚','守備表示特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2619149,'劍鬥獸 盾戰鬥士',unistr('如果此卡已被「劍鬥獸」怪獸的效果特殊召喚，此卡戰鬥破壞對手怪獸送去墓地時，可以從我方牌組將1張「劍鬥獸」卡片加入手牌。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到牌組，從牌組將「劍鬥獸 盾戰鬥士」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'檢索牌組','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625939,'排存代碼','①：如果我方墓地的電子界族怪獸有3隻以上，對手怪獸的直接攻擊宣言時可以發動。那次攻擊無效。那之後，可以在我方場上將最多3隻「排存衍生物」（電子界族、光、等級1、攻/守0）守備表示特殊召喚。這個衍生物不能為了上級召喚而解放。','是否特殊召喚衍生物？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625940,'排存衍生物','由「排存代碼」的效果特殊召喚。這個衍生物不能為了上級召喚而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2645637,'零冰之魔妖-雪女',unistr('不死族怪獸2隻以上\u000a這個卡名的③效果1回合可以使用最多2次。\u000a①：「零冰之魔妖-雪女」在我方場上只能有1隻表側表示存在。\u000a②：只要此卡在怪獸區域存在，被除外的狀態發動的對手怪獸的效果無效化。\u000a③：怪獸從墓地特殊召喚的場合，或墓地的怪獸的效果發動的場合，以此卡以外的場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力變成0，那個效果無效。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2648201,'ZW-極天神馬聖鎧',unistr('①：「ZW-極天神馬聖鎧」在我方場上只能有1張表側表示存在。\u000a②：以我方場上1隻「希望皇霍普」怪獸為對象可以發動。從我方的手牌、場上將此卡當作攻擊力上升1000的裝備卡給那隻我方的「希望皇霍普」怪獸裝備。\u000a③：裝備怪獸被對手破壞讓此卡被送去墓地時，以我方墓地1隻「希望皇霍普」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a\u000a※ZW-極星神馬聖鎧'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2656842,'騎甲蟲 瓢蟲偵察兵',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從我方的手牌、牌組、墓地選1隻「騎甲蟲 瓢蟲偵察兵」特殊召喚。\u000a②：只要此卡在怪獸區域存在，我方除了昆蟲族怪獸以外不能特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2665273,'永界王戰 歐姆剛德王',unistr('等級9怪獸×2隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：「永界王戰 歐姆剛德王」在我方場上只能有1隻表側表示存在。\u000a②：此卡的原本的攻擊力、守備力變成此卡的超量素材數量×1000。\u000a③：去除此卡的1個超量素材可以發動。雙方各自從牌組抽1張卡。那之後，抽牌的玩家選自身的手牌、場上1張卡重疊在此卡下方作為超量素材。此效果在對手回合也能發動。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2671330,'高能錘頭龍','此卡和怪獸進行戰鬥的傷害步驟結束時，與此卡進行戰鬥且沒有被破壞的對手怪獸回到持有者的手牌。','回到持有者的手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2674965,'阿爾戈☆群星-主陣競技場',unistr('①：1回合1次，支付1000生命值可以發動。我方的墓地、除外狀態的1張「阿爾戈☆群星」卡片加入手牌。\u000a②：每次永續陷阱卡從魔法與陷阱區域往我方場上特殊召喚，給予對手500傷害。\u000a③：我方的「阿爾戈☆群星」怪獸已被除外的狀態，我方的永續陷阱卡在怪獸區域發動效果的場合，以對手場上1張表側表示卡為對象可以發動（同一連鎖上最多1次）。那張卡的效果直到回合結束時無效。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2694423,'梅杜莎蠕蟲',unistr('我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a此卡反轉召喚成功時，選擇對手場上的1隻怪獸破壞。'),'變成裡側守備表示','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2725599,'R-ACE 裁焰者',unistr('炎屬性怪獸2隻以上\u000a我方1回合只能特殊召喚1次「R-ACE 裁焰者」，那個②效果1回合可以使用最多2次。\u000a①：此卡連結召喚的場合可以發動。從我方的牌組、墓地將1隻「R-ACE 消防栓」或1張「R-ACE總部」加入手牌。\u000a②：我方發動「R-ACE」速攻魔法、通常陷阱卡的場合，以對手場上1張卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729285,'絨毛動物貓',unistr('「絨毛動物貓」的效果1回合只能使用1次。\u000a①：此卡作為融合素材送去墓地的場合，以我方墓地的1張「融合」為對象可以發動。那張卡加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2732323,'誘餌龍','①：此卡被選擇作為攻擊對象的場合，以我方墓地1隻等級7以上的龍族怪獸為對象發動。那隻怪獸特殊召喚，攻擊對象轉移到那隻怪獸進行傷害計算。','從墓地特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2743001,'水晶機巧-軸子鳳凰',unistr('同步怪獸協調+協調以外的同步怪獸1隻以上\u000a①：此卡同步召喚成功的場合可以發動。對手的場上、墓地的魔法、陷阱卡全部除外。\u000a②：同步召喚的此卡被戰鬥、效果破壞的場合，以此卡以外的我方墓地1隻怪獸為對象可以發動。那隻怪獸特殊召喚。'),'魔法、陷阱卡除外','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2752099,'薔薇占術師',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：將此卡解放可以發動。我方從牌組抽1張卡。\u000a②：將墓地的此卡除外，以我方墓地1隻植物族怪獸為對象可以發動。那隻怪獸加入手牌。此效果將原等級是7以上的植物族怪獸加入手牌的場合，隨後可以從牌組將1隻植物族怪獸送去墓地。'),'效果1','效果2','是否再從牌組將1隻植物族怪獸送去墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2759860,'灰籃衝擊',unistr('「灰籃衝擊」的①②效果1回合只有1次能使用其中1個。\u000a①：以此卡以外的我方場上1張「灰籃」卡片和對手場上1張卡為對象可以發動此效果。那些卡破壞。\u000a②：我方結束階段可以發動此效果。從牌組將1張「灰籃」卡片加入手牌。'),'場上的卡破壞','從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2766877,'大薰風鳳凰',unistr('等級2怪獸×2\u000a1回合1次，去除此卡的1個超量素材，選擇我方場上的1隻風屬性怪獸可以發動。這個回合，選擇的怪獸在1次戰鬥階段中可以攻擊2次。'),'攻擊2次','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772236,'電力客邁拉',unistr('「電力」協調+協調以外的雷族怪獸1隻以上\u000a此卡可以直接攻擊對手玩家。\u000a此卡直接攻擊給予對手戰鬥傷害時，對手的手牌隨機選1張放到牌組最上方。'),'放到牌組最上方','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772337,'賜炎的咎姬',unistr('效果怪獸2隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，我方除了炎屬性怪獸以外不能特殊召喚。\u000a②：我方主要階段可以發動。從我方墓地將1隻炎屬性怪獸特殊召喚。\u000a③：此卡在墓地存在的狀態，對手場上有怪獸特殊召喚的場合，以我方場上1隻炎屬性怪獸和對手場上1隻怪獸為對象可以發動。那些怪獸破壞，此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772338,'賜炎的咎姬',unistr('效果怪獸2隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，我方除了炎屬性怪獸以外不能特殊召喚。\u000a②：我方主要階段可以發動。從我方墓地將1隻炎屬性怪獸特殊召喚。\u000a③：此卡在墓地存在的狀態，對手場上有怪獸特殊召喚的場合，以我方場上1隻炎屬性怪獸和對手場上1隻怪獸為對象可以發動。那些怪獸破壞，此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2779999,'棘之壁','我方場上的植物族怪獸被選擇作為攻擊對象時可以發動。對手場上攻擊表示存在的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2783661,'青之眼的威光',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌、牌組將1隻「青眼」怪獸送去墓地，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸只要在場上表側表示存在就不能攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2792265,'異形的從者','此卡可以直接攻擊對手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2801664,'戰華之雄-張德',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上有2隻以上「戰華」怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡的攻擊力在我方回合中上升對手場上的怪獸數量×300。\u000a③：對手場上的怪獸數量比我方場上的怪獸多的場合可以發動。這個回合，此卡在1次戰鬥階段中可以向怪獸攻擊2次。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2810642,'PSY骨架裝備β',unistr('此卡不能通常召喚，只能用卡的效果特殊召喚。\u000a①：我方場上沒有怪獸存在，對手怪獸的攻擊宣言時可以發動。選手牌的此卡和我方的手牌、牌組、墓地1隻「PSY骨架驅動者」特殊召喚，那隻攻擊怪獸破壞。那之後，戰鬥階段結束。此效果特殊召喚的怪獸在結束階段被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2815176,'異響鳴琴的神異-風暴魔鬼',unistr('效果怪獸1隻\u000a除了我方的靈擺區域的惡魔族怪獸卡的響鳴計數器是3個以上的場合以外，此卡不能連結召喚，我方1回合只能特殊召喚1次「異響鳴琴的神異-風暴魔鬼」。\u000a①：我方場上的卡被戰鬥、效果破壞的場合，可以去除我方的靈擺區域的3個響鳴計數器作為代替。\u000a②：對手回合1次，以我方的墓地、除外狀態的1張「異響鳴琴」通常魔法、通常陷阱卡為對象可以發動。那張魔法、陷阱卡發動時的效果適用。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819435,'幻煌之都 帕西菲斯',unistr('此卡的卡名在規則上當作「海」。此卡的效果發動的整回合中，我方不能將效果怪獸召喚、特殊召喚。\u000a①：1回合1次，我方將1隻通常怪獸召喚、特殊召喚成功的場合發動。從牌組將1張「幻煌龍」卡片加入手牌。\u000a②：我方場上沒有衍生物存在，對手發動魔法、陷阱、怪獸的效果的場合可以發動。在我方場上將1隻「幻煌龍衍生物」（幻龍族、水、等級8、攻/守2000）特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819436,'幻煌龍衍生物','由「幻煌之都 帕西菲斯」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830619,'火焰毒蛇','敏捷的行動、從口中吐出火焰的蛇。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830693,'彩虹栗子球',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時，以那1隻攻擊怪獸為對象可以發動。此卡從手牌當作裝備卡給那隻怪獸裝備。裝備怪獸不能攻擊。\u000a②：此卡在墓地存在的場合，對手怪獸的直接攻擊宣言時可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'裝備','此卡特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2833249,'龍的血族','我方場上的全部怪獸直到回合結束時變成龍族。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2834264,'騎甲蟲 獨角仙裝甲兵',unistr('昆蟲族怪獸2隻\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，我方除了昆蟲族怪獸以外不能特殊召喚。\u000a②：我方主要階段可以發動。進行1隻昆蟲族怪獸的召喚。\u000a③：此卡在墓地存在的場合，從我方墓地將3隻其他的昆蟲族怪獸除外可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2843014,'迅捷曼波魚','此卡被戰鬥破壞送去墓地時，從我方牌組將1隻魚族怪獸送去墓地。那之後，可以從我方牌組將1隻「迅捷曼波魚」特殊召喚。','特殊召喚','是否從牌組把1隻「迅捷曼波魚」特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2851070,'魔鏡導士 反射限界者',unistr('場上表側攻擊表示的此卡被對手怪獸攻擊的傷害計算前，給予對手攻擊怪獸的攻擊力數值的傷害。\u000a那次傷害計算後，此卡破壞。'),'給予對手傷害','此卡破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2857636,'夢魘曲 鳳凰',unistr('卡名不同的怪獸2隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚的場合，捨棄1張手牌，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。此效果的發動時此卡是互相連結狀態的場合，隨後我方可以抽1張卡。\u000a②：只要此卡在怪獸區域存在，互相連結狀態的我方怪獸不會被戰鬥破壞。'),'效果1','是否抽1張卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2863439,'幻鏡鳥','能夠從手裡的鏡子中召喚出同伴的鳥怪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2881864,'炎界王戰 納吉爾法王',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：「炎界王戰 納吉爾法王」在我方場上只能有1隻表側表示存在。\u000a②：我方場上的卡被戰鬥、效果破壞的場合，可以將我方場上1隻「王戰」怪獸或獸戰士族怪獸破壞作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2896663,'ZW-弩級兵裝龍王戟',unistr('等級5怪獸×2\u000a①：此卡不能直接攻擊。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。從牌組將1張「ZEXAL」魔法、陷阱卡加入手牌。\u000a③：以我方場上1隻「希望皇霍普」怪獸為對象可以發動。我方場上的此卡當作攻擊力上升3000的裝備卡給那隻怪獸裝備。\u000a④：裝備怪獸戰鬥破壞怪獸時可以發動。選裝備怪獸已裝備的任意數量「ZW」怪獸卡特殊召喚。'),'效果2','效果3','效果4','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2903036,'祭品玩偶','解放我方場上1隻怪獸可以發動。從手牌將1隻可以通常召喚的等級7怪獸特殊召喚。那隻怪獸在這個回合不能攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906250,'捕獵蛇','奸詐狡猾的蛇。注意他用粗長的身體束縛攻擊！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2924048,'借機偶整備藏','我方場上有「機偶」怪獸表側守備表示存在的場合可以發動。對手發動的魔法、陷阱卡的發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2926176,'王家的詛咒','①：只以場上的1張魔法、陷阱卡為對象且要讓那張卡被破壞的魔法、陷阱卡發動時可以發動。那個發動無效並破壞。','發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2930675,'通往星遺物的鑰匙',unistr('①：此卡發動時，可以從被除外的我方的卡之中以1隻「機界騎士」怪獸或1張「星遺物」卡片為對象。那個場合，那張卡加入手牌。\u000a②：只要我方場上有「機界騎士」怪獸存在，和那些怪獸相同縱列發動的對手的陷阱卡的效果無效化。'),'是否把除外的卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2948263,'隆隆隆石魔-黃金形態',unistr('此卡不能通常召喚。只能解放我方場上的1隻「隆隆隆」怪獸來特殊召喚。\u000a此卡的攻擊力變成解放的那隻怪獸的原攻擊力數值的2倍。\u000a此卡的戰鬥產生給對手的戰鬥傷害變成一半。\u000a1回合1次，對手場上的怪獸的效果發動時發動。此卡的攻擊力下降1500，那個效果無效。'),'怪獸效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2956282,'大植然龍',unistr('地屬性協調+協調以外的地屬性怪獸1隻以上\u000a①：陷阱卡發動時，將我方墓地2張卡除外可以發動。此卡在場上表側表示存在的場合，那個發動無效並破壞。'),'發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2957055,'魔頭邪龍','多一個頭的龍。用兩張嘴咬碎敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2964201,'龍蛋','被蛋殼包圍的龍。如果認為只是小孩子會吃苦頭的！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971090,'戰鬥之神 歐利翁','被譽為戰神的天使。不過誰也沒見過那場戰事。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971446,'廣告標語',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手的效果讓對手用抽牌以外的方法從牌組將卡加入手牌的場合可以發動。我方從牌組選1張卡，給雙方確認加入手牌。這個回合，我方不能發動此效果加入手牌的卡以及那些同名卡的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2978414,'No.46 神影龍 膠子龍',unistr('龍族等級8怪獸×2\u000a①：1回合1次，我方場上沒有其他怪獸存在的場合，可以去除此卡的1個超量素材，從以下效果選擇1個發動。\u000a●從手牌將1隻龍族怪獸特殊召喚。\u000a●以對手場上1隻龍族怪獸為對象可以發動。得到那隻龍族怪獸的控制權。\u000a●直到對手回合結束時，對手場上的龍族怪獸不能發動效果。'),'●特殊召喚','●得到龍族怪獸的控制權','●龍族怪獸不能發動效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2980764,'神聖之燈',unistr('此卡不會被闇屬性怪獸戰鬥戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。\u000a只要此卡在場上表側表示存在，闇屬性怪獸不能攻擊宣言，雙方不能將闇屬性怪獸召喚、特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2986553,'夜薔薇騎士',unistr('①：此卡召喚成功時可以發動。從手牌將1隻等級4以下的植物族怪獸特殊召喚。\u000a②：只要此卡在怪獸區域存在，對手不能選擇植物族怪獸作為攻擊對象。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992036,'根絕的機皇神',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地3隻「機皇」怪獸為對象可以發動（同名卡最多1張）。那些怪獸加入手牌或無視召喚條件特殊召喚。此卡的發動後，直到下個我方回合結束時我方除了機械族怪獸以外不能特殊召喚。\u000a②：我方場上有「機皇神」怪獸存在的場合，將墓地的此卡除外可以發動。選對手場上1隻同步怪獸破壞，給予對手那個原攻擊力數值的傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992467,'滴答&回聲',unistr('此卡不能作為融合、同步、超量召喚的素材。這個卡名的②效果1回合可以使用最多2次。\u000a①：只要此卡在怪獸區域存在，此卡不能解放。\u000a②：此卡作為連結素材送去墓地的場合發動。此卡在那個連結召喚的玩家所見的對手場上守備表示特殊召喚。\u000a③：只要此卡的②效果特殊召喚的此卡在怪獸區域存在，我方將手牌持續公開。'),'效果2','效果3適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2994495,'風魔的波動','①：以場上1隻表側表示怪獸為對象可以發動。選場上1隻和那隻怪獸卡名不同且屬性相同的怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3019642,'電子暗黑骨',unistr('①：此卡召喚成功的場合，以我方墓地1隻等級3以下的龍族怪獸為對象發動。那隻龍族怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力數值。\u000a③：此卡戰鬥破壞對手怪獸的場合發動。給予對手300傷害。\u000a④：此卡被戰鬥破壞的場合，將此卡的效果裝備的怪獸破壞作為代替。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3026686,'華爾裘蓮 三女',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將「華爾裘蓮 三女」以外的1張「華爾裘蓮」卡片加入手牌。\u000a②：此卡的攻擊力上升被除外的對手怪獸數量×200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3027001,'偽陷阱','對手發動要讓我方場上的陷阱卡破壞的魔法、陷阱、效果怪獸的效果時可以發動。將此卡破壞作為代替，其他的我方的陷阱卡不會被破壞。覆蓋的卡被破壞的場合，那些卡全部翻開來確認。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3030892,'奴隸猿','此卡被戰鬥破壞送去墓地時，可以從牌組將1隻等級4以下的「劍鬥獸」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3040496,'混沌魔龍 混沌支配者',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚成功的場合可以發動。從我方牌組上方翻開5張卡。可以從其中選1隻光、闇屬性怪獸加入手牌。剩下的卡送去墓地。\u000a②：將此卡以外的光、闇屬性怪獸各1隻從我方的手牌、墓地除外可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','是否選1張卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3048768,'天使之聲 異響鳴琴',unistr('【靈擺效果】\u000a①：只要另一邊的我方的靈擺區域有惡魔族怪獸卡存在，每次我方的生命值回復，給此卡放置1個響鳴計數器。\u000a②：1回合1次，對手怪獸的攻擊宣言時可以發動。進行1隻「異響鳴琴」連結怪獸的連結召喚。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，從手牌捨棄1張其他卡可以發動。從牌組選1隻「魔鬼之聲 異響鳴琴」，此卡和那張卡在我方的靈擺區域放置。\u000a②：此卡召喚、特殊召喚的回合的我方主要階段，從我方墓地將1張「異響鳴琴」通常魔法、通常陷阱卡除外可以發動。那張魔法、陷阱卡發動時的回復生命值那方的效果適用。'),'靈擺效果2','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055018,'灰滅之都 黑曜',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：我方回合中，對手場上的特殊召喚的表側表示怪獸變成炎族。\u000a②：我方結束階段，以我方墓地1張「灰滅之都 黑曜」為對象可以發動。那張卡回到牌組最下方。那之後，我方抽1張卡。\u000a③：場地區域的此卡被破壞的場合或被除外的場合可以發動。從牌組將1隻「灰滅」怪獸特殊召喚。'),'抽1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055837,'黑板擦的陷阱','給予我方傷害的怪獸的效果、魔法、陷阱卡發動時可以發動。我方受到的那次效果傷害變成0，對手選1張手牌捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3056267,'王座侵略者','反轉：選擇對手場上的1隻怪獸，那隻怪獸與此卡的控制權交換。此效果不能在戰鬥階段發動。','交換控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064425,'超重武者裝留 爆炎',unistr('①：我方主要階段以我方場上1隻「超重武者」怪獸為對象可以發動。我方的手牌、場上的這隻怪獸當作守備力上升1000的裝備卡給那隻怪獸裝備。\u000a②：我方場上有守備表示的「超重武者」怪獸存在，對手在戰鬥階段發動魔法、陷阱、怪獸的效果時，將墓地的此卡除外可以發動。那個發動無效並破壞。那之後，場上的怪獸全部破壞，雙方玩家受到1000傷害。'),'變成裝備卡','發動無效並破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3070049,'雪龍','此卡被戰鬥或卡片效果破壞送去墓地時，給場上表側表示存在的全部怪獸各放置1個冰計數器。','放置計數器','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072077,'返回殭屍','此卡在墓地存在的場合，我方準備階段，支付500生命值可以發動。此卡加入手牌。此效果在我方的手牌是0張的場合可以發動和處理。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072808,'BF-天狗風之希連','此卡在墓地存在，對手怪獸的直接攻擊使我方受到2000以上的戰鬥傷害時，選擇我方墓地的1隻等級3以下的「BF」怪獸可以發動。選擇的怪獸和此卡從墓地特殊召喚。此效果特殊召喚的怪獸的效果無效化。「BF-天狗風之希連」的效果在決鬥中只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078380,'合體龍 迪馬歐斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，從我方的手牌、場上（表側表示）將1隻魔法使族怪獸或1張記載「黑魔導」的卡名的魔法、陷阱卡送去墓地可以發動。此卡特殊召喚。\u000a②：我方主要階段可以發動。包含魔法使族怪獸的我方的手牌、場上的怪獸作為融合素材，將1隻融合怪獸融合召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078576,'八汰烏',unistr('此卡不能特殊召喚。\u000a①：此卡給予對手戰鬥傷害的場合發動。跳過下個對手抽牌階段。\u000a②：此卡召喚、反轉的回合的結束階段發動。此卡回到手牌。'),'回到手牌','跳過抽牌階段','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3084730,'昆蟲機甲鎧',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在，我方場上沒有「昆蟲機甲鎧」存在的場合，以我方場上1隻昆蟲族怪獸為對象可以發動。此卡當作裝備卡給那隻怪獸裝備。此卡以及用此效果裝備此卡的怪獸從場上離開的場合被除外。\u000a②：已裝備此卡的怪獸在雙方的戰鬥階段以及主要階段2期間攻擊力上升1500，守備力上升2000。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3096468,'屍龍子',unistr('通常召喚的此卡作為素材同步召喚的場合，手牌的1隻怪獸也能作為同步素材。此時同步素材怪獸不去墓地而是除外。\u000a①：只要此卡在怪獸區域存在，我方除了不死族怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3103067,'攻擊誘導裝甲',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方或對手的怪獸的攻擊宣言時，可以從以下效果選擇1個發動。\u000a●那隻攻擊怪獸破壞。\u000a●以那隻攻擊怪獸以外的我方或對手場上1隻怪獸為對象可以發動。攻擊對象轉移到那隻怪獸進行傷害計算。'),'●攻擊怪獸破壞','●攻擊對象轉移','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3105404,'明亮火花',unistr('「明亮火花」在1回合只能發動1張。\u000a①：我方場上的「寶石騎士」怪獸被對手怪獸的攻擊或對手的效果破壞的場合，以被破壞的1隻怪獸為對象可以發動。給予對手那隻怪獸的原攻擊力數值的傷害。\u000a②：此卡在墓地存在的場合，將手牌1張「寶石騎士」卡片送去墓地可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3111207,'彩寶龍',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡從牌組加入手牌的場合，向對手展示此卡可以發動。此卡特殊召喚。\u000a②：此卡因效果從我方墓地加入手牌的場合，向對手展示此卡可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113667,'鋼鐵襲擊者',unistr('①：只要此卡在場地區域存在，我方的機械族、闇屬性怪獸1回合各有1次不會被戰鬥破壞。那次戰鬥讓我方受到戰鬥傷害的場合，攻擊力上升那個數值。\u000a②：1回合1次，我方場上的原本的種族、屬性是機械族、闇屬性的怪獸用戰鬥或自身的效果將場上的卡破壞的場合可以發動。從手牌將1隻機械族、闇屬性怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113836,'寶石騎士 綠龍晶',unistr('「寶石騎士」怪獸+光屬性怪獸\u000a此卡只能用以上述卡為融合素材的融合召喚從額外牌組特殊召喚。\u000a①：只要此卡在怪獸區域存在，我方在通常召喚之外只有1次，在我方主要階段可以通常召喚1隻怪獸。'),'通常召喚（寶石騎士 綠龍晶）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3117804,'超重武者 大弁慶-K',unistr('①：此卡召喚、特殊召喚成功時可以發動。此卡的表示形式變更。\u000a②：只要此卡在怪獸區域存在，我方的「超重武者」怪獸可以在表側守備表示的狀態攻擊。那個場合，那隻怪獸用守備力當作攻擊力進行傷害計算。'),'表示形式變更','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3121655,'廢品插座龍',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上有同步怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：我方的同步怪獸的攻擊宣言時，將墓地的此卡除外可以發動。那隻我方怪獸的攻擊力直到回合結束時上升800。'),'從手牌特殊召喚','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129133,'誘惑之Δ',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②③效果1回合各能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻等級5以上的不死族怪獸送去墓地。\u000a②：場上有不死族怪獸存在的場合可以發動。在我方場上將1隻「Δ衍生物」（不死族、闇、等級5、攻/守0）特殊召喚。\u000a③：此卡在墓地存在的狀態，怪獸從墓地加入手牌的場合可以發動。此卡加入手牌。'),'效果1','效果2','效果3','是否將1張卡送去墓地？','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129134,'Δ衍生物','由「誘惑之Δ」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129635,'詛咒的雕像',unistr('此卡發動後變成怪獸卡（岩石族、闇、等級4、攻1800/守1000）在我方的怪獸區域特殊召喚。此卡也當作陷阱卡。\u000a此卡在場上當作怪獸存在，此卡以外的當作怪獸的陷阱卡和對手怪獸進行戰鬥的場合，在傷害計算後，那隻對手怪獸破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134241,'飛天螳螂','擁有飛行能力的螳螂，非常喜歡吃昆蟲。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134857,'自鳴天琴 奧開斯特里翁',unistr('包含「自鳴天琴」怪獸的效果怪獸2隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：連結狀態的此卡不會被戰鬥、效果破壞。\u000a②：以被除外的3隻我方的機械族怪獸為對象可以發動。那些怪獸回到牌組。對手場上有連結狀態的表側表示怪獸存在的場合，那些怪獸的攻擊力、守備力變成0，效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3136426,'等級限制B地區','場上的等級4以上的怪獸變成守備表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3137279,'游魊之兆 伊克西普',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：魚族怪獸被除外的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡被除外的下個回合的準備階段，以我方的墓地、除外狀態的1張「游魊」陷阱卡為對象可以發動。那張卡在我方場上覆蓋。'),'從手牌特殊召喚','陷阱卡在場上覆蓋','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3146695,'念力反應機','我方場上有超能族怪獸表側表示存在的場合可以發動。我方場上表側表示存在的超能族怪獸在這個回合和對手怪獸進行戰鬥時，那些超能族怪獸和對手怪獸除外。','●進行戰鬥的怪獸除外（念力反應機）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149401,'驕傲與靈魂的究極龍',unistr('原攻擊力和原守備力是2500的怪獸×3\u000a①：只要融合召喚的此卡在怪獸區域存在，此卡不會被對手的效果破壞，對手不能將此卡作為效果的對象。\u000a②：只要我方墓地有25張以上卡存在，融合召喚的此卡的攻擊力、守備力上升4500。\u000a③：1回合1次，對手墓地有25張以上卡存在的場合可以發動。對手場上的卡全部破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149764,'圖坦假面','以場上表側表示存在的1隻不死族怪獸為對象的魔法、陷阱卡的發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3160805,'明與宵的逆轉',unistr('可以從以下效果選擇1個發動。「明與宵的逆轉」的效果1回合只能使用1次。\u000a●從手牌將1隻戰士族、光屬性怪獸送去墓地。那之後，從牌組將1隻和那隻怪獸的等級相同的戰士族、闇屬性怪獸加入手牌。\u000a●從手牌將1隻戰士族、闇屬性怪獸送去墓地。那之後，從牌組將1隻和那隻怪獸的等級相同的戰士族、光屬性怪獸加入手牌。'),'檢索','是否現在發動此卡的效果？','光屬性送入墓地','闇屬性送入墓地','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167439,'暗黑界的懲罰',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方或對手將怪獸召喚、特殊召喚之際可以發動。使其無效，那些怪獸破壞。那之後，從手牌選1隻惡魔族怪獸捨棄。\u000a②：我方場上的「暗黑界」怪獸被戰鬥或對手的效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167573,'人偶國王',unistr('①：對手用抽牌以外的方法從牌組將怪獸加入手牌時可以發動。此卡從手牌特殊召喚。\u000a②：此卡的①效果特殊召喚成功的場合，下個我方回合的結束階段發動。此卡破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3170832,'橐蜚','這鳥出現時，就是什麼不幸之事發生前的徵兆。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3171055,'連鎖解咒','①：魔法、陷阱卡發動時可以發動。從發動的那張魔法、陷阱卡的控制者的牌組將同名卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3204467,'蠕蟲 固體',unistr('此卡的守備力上升我方墓地的爬蟲類族的「蠕蟲」怪獸數量×100。\u000a此卡被攻擊使對手受到戰鬥傷害的場合，在那個傷害步驟結束時，選擇對手場上的1張魔法、陷阱卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3211439,'禁斷的異本','①：宣言1個怪獸卡的種類（融合、同步、超量）可以發動。場上有2隻以上宣言種類的怪獸表側表示存在的場合，雙方玩家必須將場上的那個種類的怪獸全部送去墓地。','融合','同步','超量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3233859,'念力使用者',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上有「念力使用者」以外的等級3怪獸存在的場合，此卡可以從手牌守備表示特殊召喚。\u000a②：此卡作為同步怪獸的同步素材送去墓地的場合，以場上1隻攻擊力低於那隻同步怪獸的怪獸為對象可以發動。那隻怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3244563,'盾槍','①：以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到回合結束時上升400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3248469,'陷阱蜜蜂！',unistr('這個卡名的效果1回合只能使用1次。\u000a①：我方、對手的結束階段，將手牌、場上的此卡送去墓地可以發動。依照沒有使用的對手的魔法與陷阱區域數量，從我方牌組上方翻開卡片。可以從其中選1張陷阱卡在我方場上覆蓋。剩下的卡以喜歡的順序回到牌組下方。此效果覆蓋的卡在下個結束階段送去墓地。'),'效果1','是否選1張陷阱卡在我方場上覆蓋？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3259760,'咒縛眾','①：對手場上的全部表側表示怪獸直到回合結束時不能解放，也不能作為融合、同步、超量、連結召喚的素材。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3280747,'第六感','我方宣言1～6的數字其中2個。對手擲1次骰子，如果出現了其中1個宣言的數字，我方抽那個數量的卡。如果都沒有出現，依照擲出的點數將牌組上方的卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3283679,'進化蟲 兔鱷',unistr('此卡召喚成功時，可以從牌組將1隻「進化龍」怪獸送去墓地。\u000a此外，此卡反轉時，可以從牌組將1隻「進化蟲」怪獸特殊召喚。'),'從牌組送去墓地','從牌組特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285551,'阿拉彌賽亞之儀',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方不能發動特殊召喚的怪獸以外的場上的怪獸的效果。\u000a①：我方場上沒有「勇者衍生物」存在的場合可以發動。在我方場上將1隻「勇者衍生物」（天使族、地、等級4、攻/守2000）特殊召喚。我方場上沒有「命運的旅途」存在的場合，隨後可以從牌組將1張「命運的旅途」在我方的魔法與陷阱區域表側表示放置。'),'是否從牌組選1張「命運的旅途」放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285552,'勇者衍生物','勇者 LV. 4','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3287359,'魔彈魔鬼 卡斯帕',unistr('包含光屬性、惡魔族怪獸的怪獸2隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚的場合可以發動。從我方的手牌、牌組挑選包含怪獸的2張「魔彈」卡片，其中1隻怪獸在我方場上特殊召喚，另1張在對手場上覆蓋。\u000a②：只要此卡在怪獸區域存在，我方、對手回合我方可以從手牌發動「魔彈」魔法、陷阱卡。'),'效果1','適用「魔彈魔鬼 卡斯帕」的效果2來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3289027,'暗黑界的隱者 珀爾',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡被效果從手牌捨棄到墓地的場合，以「暗黑界的隱者 珀爾」以外的我方墓地1隻「暗黑界」怪獸為對象可以發動。那隻怪獸在我方或對手場上特殊召喚。被對手的效果捨棄的場合，隨後可以從我方的手牌、墓地的怪獸以及被除外的我方怪獸之中，選1隻惡魔族怪獸在我方或對手場上特殊召喚。'),'效果1','是否再選1隻怪獸特殊召喚？','在我方場上特殊召喚','在對手場上特殊召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(3292267,'聖刻天龍-九柱神',unistr('等級8怪獸×2\u000a①：1回合1次，對手發動以我方的場上、墓地的卡或被除外的我方的卡為對象的魔法、陷阱、怪獸的效果時，去除此卡的1個超量素材可以發動。那個發動無效並破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3294539,'深紅劍龍',unistr('「共鳴體」協調+協調以外的怪獸1隻以上\u000a這個卡名在規則上當作「深紅劍士」。這個卡名的①效果1回合只能使用1次。\u000a①：此卡同步召喚的場合可以發動。從我方的牌組、墓地選1隻等級8以上的不能通常召喚的怪獸加入手牌或效果無效特殊召喚。\u000a②：此卡和等級5以上的對手怪獸進行戰鬥的傷害步驟開始時可以發動。那隻怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3298689,'升階魔法-魅影騎士團出擊',unistr('①：我方、對手的主要階段，以我方場上1隻沒有超量素材的闇屬性超量怪獸為對象可以發動。將1隻階級比那隻我方怪獸高1階的闇屬性超量怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚，將此卡重疊在下方作為超量素材。\u000a②：我方主要階段將墓地的此卡除外，以我方場上1隻闇屬性超量怪獸為對象可以發動。將手牌的1隻「魅影騎士團」怪獸重疊在那隻怪獸下方作為超量素材。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3300267,'聖刻龍-舒龍',unistr('①：此卡可以將我方場上1隻「聖刻」怪獸解放從手牌特殊召喚。\u000a②：1回合1次，將此卡以外的我方的手牌、場上1隻「聖刻」怪獸解放，以對手場上1張魔法、陷阱卡為對象可以發動。那張對手的卡破壞。\u000a③：此卡被解放的場合發動。從我方的手牌、牌組、墓地選1隻龍族通常怪獸，攻擊力、守備力變成0特殊召喚。'),'效果2','特殊召喚','效果1特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3322931,'星風狼 沃爾夫拉葉',unistr('協調+協調以外的怪獸1隻以上\u000a①：「星風狼 沃爾夫拉葉」在我方場上只能有1隻表側表示存在。\u000a②：只要攻擊力未滿4000的此卡在怪獸區域存在，每次此卡以外的怪獸的效果發動，此卡的攻擊力上升300。\u000a③：1回合1次，此卡的攻擊力是4000以上的場合可以發動。此卡和對手場上的怪獸全部回到持有者的牌組。此效果在對手回合也能發動。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3355732,'冰水帝 鈉鉻輝石精',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：場地區域有表側表示卡存在的場合，此卡可以從手牌特殊召喚。\u000a②：只要場上有「冰水底 離子搖籃」存在，除了這個回合召喚、反轉召喚、特殊召喚的怪獸以外，對手不能發動場上的怪獸的效果。\u000a③：只在我方的「冰水」怪獸和對手怪獸進行戰鬥的傷害計算時，那隻對手怪獸的攻擊力下降1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3356494,'銀河眼煌星龍',unistr('包含攻擊力2000以上的怪獸的光屬性怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合，以我方墓地1隻「光子」怪獸或「銀河」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：對手主要階段，將「光子」卡片和「銀河」卡片共2張或「銀河眼光子龍」1隻從手牌捨棄，以對手場上1隻特殊召喚的怪獸為對象可以發動。那隻怪獸破壞。'),'效果1','效果2','是否捨棄「銀河眼光子龍」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3361010,'愉怪之磷的狐火搖',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，場上的表側表示怪獸變成炎屬性。\u000a②：此卡在墓地存在，對手的場上或墓地有炎屬性怪獸存在的場合可以發動。此卡特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3366982,'乘龍的飛龍',unistr('「寶貝龍」+「飛龍戰士」\u000a①：對手場上的表側表示怪獸只有地、水、炎屬性怪獸的場合，此卡可以直接攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3370104,'電子鳳凰',unistr('①：只要此卡在怪獸區域以攻擊表示存在，只以我方場上的1隻機械族怪獸為對象的魔法、陷阱卡的效果無效化。\u000a②：此卡被戰鬥破壞送去墓地時可以發動。我方從牌組抽1張卡。'),'抽卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3376703,'大秘儀之力V-教皇',unistr('①：將此卡從手牌捨棄可以發動。這個回合，在我方場上有「大秘儀之力」怪獸召喚、反轉召喚、特殊召喚時，對手不能發動效果。\u000a②：此卡召喚、反轉召喚、特殊召喚的場合發動。投擲1次硬幣，依照那個正反面適用以下效果。\u000a●正：從牌組將同名怪獸不在我方的場上、墓地存在的1隻等級4以下的「大秘儀之力」怪獸特殊召喚。\u000a●反：從牌組將1隻「大秘儀之力」怪獸在對手場上特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3381441,'守墓的巫女',unistr('只要此卡在場上表側表示存在，場地變成「王家長眠之谷-死亡谷」。場地魔法卡表側表示存在的場合，這個效果不適用。\u000a只要此卡在場上表側表示存在，場上的「守墓」怪獸的攻擊力、守備力上升200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3395226,'幻奏的音姬 奇才莫札特',unistr('此卡的效果發動的整回合中，我方不能將光屬性以外的怪獸特殊召喚。\u000a①：1回合1次，我方主要階段可以發動。從手牌將1隻天使族、光屬性怪獸特殊召喚。'),'從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3405259,'C-粉碎翼龍',unistr('①：1回合1次，可以發動1個以下效果。\u000a●以我方場上1隻機械族、光屬性怪獸為對象，將此卡當作裝備魔法卡裝備。裝備怪獸將被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備狀態的此卡特殊召喚。\u000a②：裝備怪獸不受對手的陷阱卡的效果影響。\u000a③：此卡從場上送去墓地的場合可以發動。從手牌將1隻聯合怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3410461,'深淵龍 阿爾白・雷納圖斯',unistr('「阿不思的落胤」+龍族怪獸1隻以上\u000a此卡不能作為融合素材。\u000a此卡只能用融合召喚或以下方法特殊召喚。\u000a●將我方、對手的怪獸區域的上述卡送去墓地，可以從額外牌組特殊召喚。\u000a①：此卡在1次戰鬥階段中可以向怪獸攻擊多次，次數上限為作為此卡的融合素材的怪獸數量。\u000a②：此卡被送去墓地的回合的結束階段可以發動。從牌組將1張「融合」通常魔法卡或「結合」通常魔法卡加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3422200,'水晶機巧-檸晶龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌、墓地存在的場合，從手牌將「水晶機巧-檸晶龍」以外的1張「水晶機巧」卡片捨棄可以發動。此卡守備表示特殊召喚。那之後，將我方場上1張卡破壞。\u000a②：場上的此卡被戰鬥、效果破壞的場合可以發動。從牌組將1隻「水晶機巧」怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3428069,'破壞劍的操控者-爆裂劍士',unistr('①：只要此卡在場上、墓地存在，卡名當作「爆裂劍士」。\u000a②：對手場上的怪獸被戰鬥、效果破壞送去墓地的場合，以破壞的其中1隻怪獸為對象可以發動。那隻怪獸當作裝備卡給此卡裝備。\u000a③：1回合1次，將此卡裝備的1張怪獸卡送去墓地可以發動。對手場上的與送去墓地的那張怪獸卡相同種族的怪獸全部破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3429238,'鑽頭戰士',unistr('「鑽頭同步者」+協調以外的怪獸1隻以上\u000a1回合1次，在我方的主要階段時可以發動。此卡的攻擊力變成一半，這個回合此卡可以直接攻擊對手玩家。\u000a此外，1回合1次，我方的主要階段時可以發動。捨棄1張手牌，此卡除外。\u000a下個我方準備階段，此效果除外的此卡在我方場上特殊召喚。那之後，選我方墓地的1隻怪獸加入手牌。'),'攻擊力減半','捨棄手牌並除外','特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3431737,'爆裂獸','①：將此卡從手牌捨棄到墓地可以發動。從牌組將1張「爆裂模式」加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3434362,'鏽蝕猛獁象',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，從額外牌組將連結標記合計是5的機械族連結怪獸除外可以發動。此卡特殊召喚。\u000a②：以我方以及對手場上的卡各1張為對象可以發動（此卡和連結3以上的機械族連結怪獸是連結狀態的場合，此效果在對手回合也能發動）。那些卡回到手牌。'),'特殊召喚','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3461403,'不死武士的哀悼',unistr('①：我方墓地的怪獸變成戰士族。\u000a②：我方、對手的結束階段可以發動。我方場上的怪獸全部破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3486020,'麗之魔妖-妖狐',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：「麗之魔妖-妖狐」在我方場上只能有1隻表側表示存在。\u000a②：此卡在墓地存在，原等級是11的我方的同步怪獸被戰鬥或對手的效果破壞的場合可以發動。從我方墓地將1隻其他的不死族怪獸除外，此卡特殊召喚。\u000a③：此卡從墓地特殊召喚成功的場合可以發動。選對手場上1隻怪獸破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3492538,'附火器的機甲鎧',unistr('只能給昆蟲族怪獸裝備。\u000a①：裝備怪獸的攻擊力上升700。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493058,'骰子旋風',unistr('①：擲1次骰子，依照擲出點數適用以下效果。\u000a●2、3、4：選場上1張魔法、陷阱卡破壞。\u000a●5：選場上2張魔法、陷阱卡破壞。\u000a●1、6：我方受到1000傷害。'),'投擲骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493978,'首領龜','此卡召喚、反轉召喚成功時，可以從我方的手牌將任意數量的「首領龜」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3496543,'白森林的罪寶',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有惡魔族、幻想魔族、魔法使族怪獸其中任何種類存在的場合，可以從以下效果選擇1個發動。\u000a●從手牌將1隻惡魔族、幻想魔族、魔法使族怪獸特殊召喚。\u000a●我方的手牌、場上的怪獸作為融合素材，將1隻融合怪獸融合召喚。\u000a②：此卡為了發動怪獸的效果而被送去墓地的場合可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','●從手牌特殊召喚','●融合召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(3507053,'乾燥機塊 烘乾龍獸',unistr('「機塊」怪獸1隻\u000a此卡在連結召喚的回合不能作為連結素材。\u000a①：連結狀態的此卡的攻擊力上升1000。\u000a②：我方戰鬥階段1次，此卡是互相連結狀態的場合可以發動。選包含此卡的我方的主要怪獸區域2隻「機塊」怪獸，那些位置交換。這個回合，另1隻怪獸在1次戰鬥階段中可以攻擊2次。\u000a③：1回合1次，不是互相連結狀態的此卡成為攻擊對象時可以發動。那次攻擊無效。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3510565,'隱身鳥',unistr('①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉召喚成功的場合發動。給予對手1000傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3519195,'邪心強襲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：捨棄1張手牌可以發動。從牌組選1隻等級4以下的「E-HERO」怪獸加入手牌或特殊召喚。此卡的發動後，直到回合結束時我方除了「HERO」怪獸以外不能從額外牌組特殊召喚。\u000a②：將不是在這個回合送去墓地的此卡從墓地除外可以發動。從我方墓地將1張「黑暗結合」加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3534077,'熱血獸士 狼嚎',unistr('這個卡名的效果1回合只能使用1次。\u000a①：以我方墓地1隻獸戰士族、炎屬性、等級4的怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3536537,'入魔三邪龍','①：場上的表側表示的此卡被對手破壞送去墓地的場合，以場上1隻特殊召喚的等級5以上的怪獸為對象發動。那隻等級5以上的怪獸破壞。','怪獸破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3544583,'無之畢竟 終歸虛空','通常怪獸×2','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3549275,'骰子壺','反轉：雙方各擲1次骰子。擲出的點數低於對手的玩家，依照對手擲出的點數受到以下傷害。如果對手擲出的點數是2～5，受到對手擲出的點數×500傷害。如果對手擲出的點數是6，受到6000傷害。如果雙方的點數平手，重新擲骰子。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3557275,'白塵妖','塵妖一族的白色傢伙。對身上連自身也感到驚訝的潔白好像灰常漬豪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3560069,'延遲天使',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡因效果從我方墓地加入手牌的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡的①效果特殊召喚的此卡作為連結素材送去墓地的場合可以發動。我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3567660,'連結後退',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以額外怪獸區域1隻我方的連結怪獸為對象可以發動。那隻我方怪獸的位置向其指向的我方的主要怪獸區域移動。那之後，可以將那隻怪獸的連結標記數量的卡從我方牌組上方送去墓地。'),'移動位置','請選擇要移動位置的卡','是否從牌組把卡送去墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3573512,'地星劍士','雖然劍術不太成熟，但卻有不可思議力量的妖精劍士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3574681,'金科玉條',unistr('這個卡名在規則上也當作「寶玉」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：從牌組選2隻「寶玉獸」怪獸當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。那之後，從我方的手牌、墓地選1隻卡名和放置的卡不同的「寶玉獸」怪獸特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3576031,'水晶陣 潛能',unistr('①：我方場上的「水晶機巧」怪獸的攻擊力、守備力上升300。\u000a②：我方、對手的結束階段可以發動。我方從牌組抽這個回合我方同步召喚的「水晶機巧」同步怪獸數量的卡。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3580032,'傳說的預言者 梅林',unistr('「傳說的預言者 梅林」的①②③效果1回合各能使用1次。\u000a①：解放此卡可以發動。從牌組將1隻「聖騎士」怪獸特殊召喚。此效果發動的整回合中，我方除了「聖騎士」怪獸以外不能特殊召喚。\u000a②：將墓地的此卡除外可以發動。將1隻「聖騎士」同步怪獸同步召喚。此效果在對手回合也能發動。\u000a③：將墓地的此卡除外可以發動。將1隻「聖騎士」超量怪獸超量召喚。此效果在對手回合也能發動。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3594985,'威風妖怪 龍',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：另一邊的我方的靈擺區域有「威風妖怪」卡片或「龍劍士」卡片存在的場合可以發動。從牌組將1張「威風妖怪」卡片加入手牌。那之後，可以將我方的靈擺區域1張卡破壞。\u000a【怪獸效果】\u000a等級4怪獸×2\u000a等級4可以靈擺召喚的場合，在額外牌組的表側的此卡可以靈擺召喚。這個卡名的①怪獸效果1回合可以使用最多2次。\u000a①：此卡在怪獸區域存在的狀態，怪獸被解放的場合，去除此卡的1個超量素材可以發動。從牌組將1隻等級6以下的魔法使族、風屬性怪獸特殊召喚。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合，或被解放的場合可以發動。此卡在我方的靈擺區域放置。'),'','','','是否將我方的靈擺區域1張卡破壞？','','','','','','','','','','','','');
INSERT INTO texts VALUES(3598351,'E-HERO 毒瘴泡沫',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：此卡可以從手牌特殊召喚。這個方法特殊召喚過的回合，我方除了「HERO」怪獸以外不能特殊召喚。\u000a②：此卡特殊召喚的場合，如果只能用「黑暗結合」的效果特殊召喚的融合怪獸在我方場上存在可以發動。我方抽2張卡。'),'','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3603242,'粉碎機','1回合1次，從手牌將1隻機械族怪獸送去墓地可以發動。選擇對手場上1隻等級在送去墓地的怪獸的等級以下的怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606209,'魂魄狩獵者','據說被其用劍斬殺之人的靈魂會離體而去。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606728,'我我我女孩',unistr('①：以我方場上1隻「我我我魔術師」為對象可以發動。此卡的等級變成和那隻怪獸相同。\u000a②：只用包含此卡的場上的「我我我」怪獸為素材超量召喚的怪獸得到以下效果。\u000a●此卡超量召喚成功時，以對手場上1隻特殊召喚的怪獸為對象可以發動。那隻怪獸的攻擊力變成0。'),'等級變化','●攻擊力變成0（我我我女孩）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606729,'我我我女孩',unistr('①：以我方場上1隻「我我我魔術師」為對象可以發動。此卡的等級變成和那隻怪獸相同。\u000a②：只用包含此卡的場上的「我我我」怪獸為素材超量召喚的怪獸得到以下效果。\u000a●此卡超量召喚成功時，以對手場上1隻特殊召喚的怪獸為對象可以發動。那隻怪獸的攻擊力變成0。'),'等級變化','●攻擊力變成0（我我我女孩）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3611830,'創聖魔導王 安迪米翁',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：去除我方場上的6個魔力計數器可以發動。靈擺區域的此卡特殊召喚。那之後，最多到我方場上的可以放置魔力計數器的卡片數量，選場上的卡破壞，給此卡放置破壞數量的魔力計數器。\u000a【怪獸效果】\u000a①：1回合1次，魔法、陷阱卡的效果發動時可以發動。選我方場上1張已放置魔力計數器的卡回到持有者的手牌，那個發動無效並破壞。那之後，可以給此卡放置相當於回到手牌的那張卡放置數量的魔力計數器。\u000a②：已放置魔力計數器的此卡不會成為對手的效果的對象，不會被對手的效果破壞。\u000a③：已放置魔力計數器的此卡被戰鬥破壞時可以發動。從牌組將1張通常魔法卡加入手牌。'),'靈擺效果1','效果1','是否給此卡放置魔力計數器？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3627449,'法律守護者','藉由「法律的祈禱」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3629090,'電子天使－韋馱天－',unistr('藉由「機械天使的儀式」降臨。\u000a①：此卡儀式召喚成功的場合可以發動。從我方的牌組、墓地選1張儀式魔法卡加入手牌。\u000a②：此卡被解放的場合可以發動。我方場上的全部儀式怪獸的攻擊力、守備力上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3642509,'E.HERO 大龍捲',unistr('「E.HERO」怪獸+風屬性怪獸\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡融合召喚成功的場合發動。對手場上的全部怪獸的攻擊力、守備力變成一半。'),'攻守變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3643300,'傳說的漁夫',unistr('①：只要場上有「海」存在，場上的此卡不受魔法卡的效果影響。\u000a②：只要場上有「海」存在，此卡不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3648368,'正義盟軍 調查者','1回合1次，捨棄1張手牌可以發動。選擇對手場上的1隻裡側守備表示怪獸變成表側攻擊表示。此時，反轉怪獸的效果不發動。','改變表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3657444,'電子變形龍',unistr('①：可以從以下效果選擇1個發動。\u000a●此卡被選擇作為攻擊對象時，將此卡除外可以發動。我方從牌組抽1張卡，那之後戰鬥階段結束。\u000a●以我方場上1隻表側表示怪獸和此卡為對象可以發動。那隻我方的表側表示怪獸和此卡除外，那之後我方從牌組抽2張卡。\u000a●以我方墓地1張卡為對象可以發動。場上的此卡和1張手牌除外，那之後對象卡片回到牌組最上方。'),'●此卡被選擇作為攻擊對象時','●抽2張卡','●墓地的卡回到牌組最上方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3659803,'超載結合',unistr('①：我方的場上、墓地的怪獸作為融合素材除外，將1隻機械族、闇屬性的融合怪獸融合召喚。\u000a\u000a※超載融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3679218,'夢魘曲 人魚',unistr('「夢魘曲 人魚」以外的「夢魘曲」怪獸1隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚成功的場合，捨棄1張手牌可以發動。從牌組將1隻「夢魘曲」怪獸特殊召喚。此效果的發動時此卡是互相連結狀態的場合，隨後我方可以從牌組抽1張卡。\u000a②：只要此卡在怪獸區域存在，場上的不是互相連結狀態的怪獸的攻擊力、守備力下降1000。'),'效果1','是否抽1張卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3682106,'雙重陷阱','選擇場上表側表示存在的1張持有「陷阱卡的效果無效」的卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3685372,'混沌超量 奇巧人偶-狂熱降神',unistr('等級9怪獸×3\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從牌組將1張「人偶」陷阱卡加入手牌。\u000a②：去除此卡的1個超量素材可以發動。從我方或對手墓地將1隻怪獸在對手場上守備表示特殊召喚。\u000a③：對手場上有怪獸特殊召喚的場合，以其中1隻為對象可以發動。那隻怪獸破壞，給予對手那個原攻擊力一半數值的傷害。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3693034,'借機偶旅籠藏',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻「機偶」怪獸和對手場上1隻效果怪獸為對象可以發動。那隻我方怪獸的表示形式變更，那隻對手怪獸的效果直到回合結束時無效。\u000a②：我方場上有「機偶」怪獸存在的場合，將墓地的此卡除外，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的表示形式變更。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3701074,'黑暗治療','對手將怪獸召喚、反轉召喚、特殊召喚成功時，對手的生命值回復那隻怪獸的攻擊力一半數值。','回復','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3715284,'機皇兵廠 助奏',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。此卡破壞，從牌組將「機皇兵廠 助奏」以外的2隻「機皇兵」怪獸守備表示特殊召喚。此效果的發動後，直到回合結束時我方除了機械族怪獸以外不能特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。這個回合的結束階段，給予對手我方場上的「機皇」怪獸數量×100傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3717252,'影依野獸',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡反轉的場合可以發動。我方抽2張卡。那之後，選1張我方的手牌捨棄。\u000a②：此卡被效果送去墓地的場合可以發動。我方抽1張卡。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3723262,'男巫@伊格尼斯者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從額外牌組特殊召喚的電子界族怪獸在我方場上存在的場合，以我方墓地1隻電子界族、闇屬性怪獸為對象可以發動。那隻怪獸和手牌的此卡守備表示特殊召喚。此效果的發動後，直到回合結束時我方除了電子界族怪獸以外不能特殊召喚。\u000a②：將場上、墓地的此卡除外，以對手場上1隻怪獸為對象可以發動。那隻怪獸的表示形式變更。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3732747,'水元素','住在水裡的精靈。將四周用霧包圍妨礙敵人的視線。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3734202,'大植然的神星樹',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：將我方場上1隻昆蟲族、地屬性怪獸解放可以發動。從牌組將1隻等級4以下的植物族、地屬性怪獸特殊召喚。\u000a②：將我方場上1隻植物族、地屬性怪獸解放可以發動。從牌組將1隻等級4以下的昆蟲族、地屬性怪獸特殊召喚。\u000a③：此卡被送去墓地的場合發動。從牌組將「大植然的神星樹」以外的1張「大植然」卡片加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3739500,'世界終滅支配者',unistr('藉由「世界終滅」卡片降臨\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在手牌、場上存在，卡名當作「終焉之王 帝滅斯」。\u000a②：向對手展示手牌的此卡，支付2000生命值，從牌組將1張儀式魔法卡除外可以發動。那張儀式魔法卡發動時的儀式召喚的效果適用。\u000a③：支付2000生命值可以發動。場上的其他卡全部破壞。那之後，此卡的攻擊力上升2900。\u000a\u000a※破滅與終焉的支配者'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3743515,'怒髮天衝 軍刀角龍',unistr('等級4怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材可以發動。我方的手牌、場上（表側表示）1隻恐龍族怪獸破壞。那之後，可以將場上1隻怪獸的表示形式變更。\u000a②：其他的我方的恐龍族怪獸進行戰鬥的傷害步驟開始時可以發動。此卡破壞，那隻恐龍族怪獸的攻擊力直到戰鬥階段結束時上升2000。'),'效果1','效果2','是否改變表示形式？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3752422,'娛樂夥伴 等級鳴鐘者',unistr('【靈擺效果】\u000a①：1回合1次，我方主要階段可以發動。我方場上的靈擺召喚的全部怪獸的等級上升1。\u000a【怪獸效果】\u000a①：1回合1次，宣言1～5的任意等級，以此卡以外的我方場上1隻「娛樂夥伴」怪獸為對象可以發動。直到回合結束時，此卡的等級下降宣言的等級數值，對象怪獸的等級上升宣言的等級數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3758046,'DDD怒濤王 凱撒',unistr('惡魔族等級4怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，去除此卡的1個超量素材可以發動。這個回合的戰鬥階段結束時，這個回合被破壞的怪獸從我方墓地盡可能特殊召喚。下個回合的準備階段，我方受到此效果特殊召喚的怪獸數量×1000傷害。\u000a②：此卡從場上送去墓地的場合可以發動。從牌組將1張「契約書」卡片加入手牌。'),'效果1','效果2','受到特殊召喚的怪獸數量×1000傷害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3773196,'異次元的偵察機','①：此卡被除外的回合的結束階段發動。被除外的此卡攻擊表示特殊召喚（1回合只有1次）。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3775068,'方界超帝 死雷因陀羅',unistr('此卡不能通常召喚。只能將我方場上3隻「方界」怪獸送去墓地來特殊召喚。\u000a①：這個方法特殊召喚的此卡的攻擊力上升2400。\u000a②：此卡從手牌的特殊召喚成功的場合發動。給予對手800傷害。\u000a③：此卡被對手送去墓地的場合，以我方墓地最多3隻「方界」怪獸為對象可以發動。那些怪獸特殊召喚。那之後，可以從我方的牌組、墓地選1張「方界」卡片加入手牌。'),'效果傷害','從墓地特殊召喚','是否選1張「方界」卡片加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779493,'夜末管理者',unistr('「夜末巫師」+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合，或我方場上有此卡以外的魔法使族怪獸特殊召喚的場合，以對手墓地1張卡為對象可以發動。那張卡除外。\u000a②：怪獸區域的此卡被戰鬥或對手的效果破壞的場合，以我方墓地1隻等級4以下的魔法使族怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779662,'劍鬥獸 盲戰鬥士',unistr('「劍鬥獸 奧古斯都」+「劍鬥獸」怪獸×2\u000a只能讓我方場上的上述卡回到牌組，從額外牌組特殊召喚（不需要「融合」）。\u000a①：此卡用上述方法特殊召喚成功的場合可以發動。從額外牌組將1隻等級7以下的「劍鬥獸」融合怪獸無視召喚條件特殊召喚。\u000a②：此卡進行戰鬥的戰鬥階段結束時，讓此卡回到持有者的額外牌組可以發動。從牌組將2隻「劍鬥獸」怪獸特殊召喚。'),'','特殊召喚','請選擇「劍鬥獸 奧古斯都」','請選擇「劍鬥獸」怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(3784434,'突擊犀牛',unistr('1回合1次，指定相鄰且沒有使用的怪獸區域可以發動。我方場上的此卡向那個怪獸區域移動。\u000a向此卡的正前方的對手怪獸攻擊的場合，傷害步驟期間此卡的攻擊力上升500。'),'移動到相鄰區域','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3790062,'No.65 裁斷魔人 裁決破壞者',unistr('闇屬性等級2怪獸×2\u000a①：對手發動怪獸的效果時，去除此卡的2個超量素材可以發動。那個發動無效，給予對手500傷害。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3792766,'花樣明星 魔鬼翠雀',unistr('「花樣明星」怪獸2隻以上\u000a①：此卡指向的區域有「花樣明星」怪獸存在的場合，此卡的攻擊宣言時，最多到對手場上的連結怪獸數量，以被除外的我方的「花樣明星」卡片為對象可以發動。那些卡加入手牌。此卡的攻擊力直到回合結束時上升此效果加入手牌的卡片數量×1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3797883,'角子老虎機AM-7','據說根據插槽湊齊的數量能力會發生變化的機器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3806388,'混沌核',unistr('此卡不能通常召喚，只能用卡的效果特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、墓地將1隻闇屬性怪獸除外可以發動。此卡從手牌特殊召喚。這個回合，我方除了光、闇屬性的同步怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡特殊召喚成功的場合，以被除外的1隻我方的「混沌殼」為對象可以發動。那隻怪獸特殊召喚。\u000a③：表側表示的此卡從場上離開的場合被除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3810071,'僧侶鬥士','此卡的戰鬥使此卡的控制者受到的戰鬥傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3814632,'超巨大空中宮殿 鋼戈莉迪亞',unistr('等級10怪獸×2\u000a這個卡名的效果1回合只能使用1次，此效果發動的整回合中，此卡不能攻擊。\u000a①：去除此卡的1個超量素材，以對手場上1張卡為對象可以發動。那張對手的卡破壞，給予對手1000傷害。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3819470,'盜賊的七道具','①：陷阱卡發動時，支付1000生命值可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3825890,'守墓的大神官',unistr('此卡可以解放1隻「守墓」怪獸來召喚。\u000a此卡的攻擊力上升我方墓地的「守墓」怪獸數量×200。\u000a場上表側表示存在的此卡被破壞的場合，可以從手牌將1隻「守墓」怪獸捨棄作為代替。'),'解放1隻「守墓」怪獸召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3828844,'六花聖 新年花圈',unistr('等級4怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材，以我方墓地1隻植物族怪獸或1張「六花」卡片為對象可以發動。那張卡加入手牌。\u000a②：持有超量素材的此卡被解放的場合可以發動。從我方的額外牌組、墓地選1隻階級5以上的植物族超量怪獸特殊召喚。那之後，可以將此卡重疊在那隻怪獸下方作為超量素材。'),'效果1','效果2','是否把此卡重疊作為超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3837261,'締結契約的龍戰士',unistr('這個卡名的效果1回合只能使用1次。\u000a①：捨棄1張手牌可以發動。除了「締結契約的龍戰士」以外，從手牌、牌組將1隻等級4以下的龍族怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3841833,'絨毛動物熊',unistr('「絨毛動物熊」的①②效果1回合只有1次能使用其中1個。\u000a①：將手牌的此卡送去墓地可以發動。從牌組選1張「玩具罐」在我方的魔法與陷阱區域覆蓋。\u000a②：解放此卡，以我方墓地的1張「融合」為對象可以發動。那張卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3846170,'機偶兵 二三六',unistr('此卡可以攻擊的場合必須攻擊。\u000a場上表側攻擊表示存在的此卡被選擇作為攻擊對象時，此卡的表示形式變成守備表示。\u000a此卡被戰鬥破壞送去墓地時，可以從我方牌組將1隻等級4以下的「機偶」怪獸攻擊表示特殊召喚。'),'變成守備表示','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3859859,'娛樂夥伴 天空魔導女孩',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡在手牌存在，我方場上有永續魔法卡存在的場合可以發動。此卡特殊召喚。\u000a②：此卡從手牌特殊召喚的場合可以發動。從牌組將1隻等級4以下的魔法使族、光屬性怪獸送去墓地。\u000a③：表側表示的此卡從場上離開的場合，以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3868277,'TGX3-DX2','選擇我方墓地的3隻「T.G.」怪獸可以發動。選擇的怪獸加入牌組洗牌。那之後，從我方牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3875465,'家電機塊世界',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，可以從牌組將場地魔法卡以外的1張「機塊」卡片加入手牌。\u000a②：1回合1次，我方將「機塊」連結怪獸連結召喚成功的場合可以發動。從我方墓地選1隻「機塊」怪獸加入手牌。\u000a③：1回合1次，我方或對手的怪獸的攻擊宣言時可以發動。選我方場上1隻「機塊」怪獸，那個位置向其他的我方的主要怪獸區域移動。'),'是否從牌組把1張「機塊」卡片加入手牌？','效果2','效果3','請選擇要移動位置的怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(3891471,'念力調整',unistr('選擇我方墓地的1隻超能族怪獸，攻擊表示特殊召喚。此效果特殊召喚的怪獸當作協調。此卡不在場上存在時，那隻怪獸破壞。那隻怪獸從場上離開時，此卡破壞。\u000a此卡被送去墓地時，我方受到此卡的效果特殊召喚的怪獸的等級×400傷害。'),'受到傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3897065,'超級交通機人-匿蹤聯合',unistr('「貨車機人」+「電車機人」+「鑽頭機人」+「匿蹤機人」\u000a1回合1次，我方的主要階段時，可以選擇場上的1隻機械族以外的怪獸當作裝備卡給此卡裝備。\u000a已用此效果將怪獸裝備的場合，此卡可以向對手場上的全部怪獸各攻擊1次。\u000a此卡攻擊的場合，此卡的原攻擊力變成一半。\u000a此卡攻擊守備表示怪獸時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3900605,'吸收壺','反轉：場上覆蓋的魔法、陷阱卡全部破壞。被破壞的卡的控制者依照被破壞的數量從牌組抽牌。這個回合，我方不能覆蓋卡片。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3909436,'仇屍 骸骨戰將',unistr('藉由「仇屍」儀式魔法卡降臨。這個卡名的①②效果1回合各能使用1次。\u000a①：從我方墓地將1張「仇屍」卡片除外，宣言卡的種類（怪獸、魔法、陷阱）可以發動。這個回合，對手不能發動宣言種類的卡的效果。\u000a②：儀式召喚的此卡被送去墓地的場合可以發動。從牌組將1隻儀式怪獸加入手牌，從牌組將1隻「仇屍」怪獸送去墓地。'),'效果1','效果2','不能發動怪獸的效果','不能發動魔法的效果','不能發動陷阱的效果','','','','','','','','','','','');
INSERT INTO texts VALUES(3912064,'輕盈水星',unistr('①：此卡上級召喚成功時可以發動。場上的怪獸全部變成表側攻擊表示。\u000a②：此卡可以解放3隻怪獸來召喚。\u000a③：只要此卡的②方法召喚的此卡在怪獸區域存在，對手場上的怪獸的攻擊力下降那隻怪獸的原攻擊力數值。\u000a④：此卡在1次戰鬥階段中可以攻擊2次。'),'解放3隻怪獸召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3918345,'魔法史萊姆',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●此卡的戰鬥產生給控制者的戰鬥傷害由對手承受。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3954901,'費爾格蘭巨龍',unistr('此卡不能從墓地以外特殊召喚，必須從場上送去墓地才能從墓地特殊召喚。\u000a①：此卡從墓地特殊召喚成功的場合，以我方墓地1隻怪獸為對象發動。此卡的攻擊力上升對象怪獸的等級×200。'),'此卡的攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3957130,'三聯槍管龍',unistr('包含「槍彈」怪獸的龍族、闇屬性怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組將「速射扳機」「重型扳機」「雙重扳機」其中任何1張加入手牌。\u000a②：以我方場上1張表側表示卡和我方墓地1隻龍族、闇屬性怪獸為對象可以發動。作為對象的場上的卡破壞，作為對象的墓地的怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3966653,'花札衛－豬鹿蝶－',unistr('協調+協調以外的怪獸2隻\u000a①：只要此卡在怪獸區域存在，我方的「花札衛」怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：1回合1次，將我方墓地1隻「花札衛」怪獸除外可以發動。直到下個對手回合結束時，對手不能發動墓地的卡的效果，不能從墓地將怪獸特殊召喚。'),'不能發動效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3972721,'貪婪指數','我方將對手場上的表側表示的同步怪獸以戰鬥或卡片效果破壞的回合可以發動。我方從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3985011,'神聖之力','左右搖晃，被神聖的力量守護著。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3987233,'金毛貴婦',unistr('地屬性怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：場上的地屬性怪獸的攻擊力、守備力上升500，風屬性怪獸的攻擊力、守備力下降400。\u000a②：此卡被戰鬥、效果破壞的場合，以我方墓地1隻地屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3989465,'熔岩谷火神',unistr('等級3怪獸×2\u000a此卡進行戰鬥的傷害步驟時1次，去除此卡的1個超量素材可以發動。此卡的攻擊力直到回合結束時上升500。'),'攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4008212,'打破命運',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上1隻「龍騎兵 D-END」或等級8以上的「D-HERO」怪獸為對象可以發動。那隻怪獸破壞，跳過下個對手主要階段1。\u000a②：將墓地的此卡除外可以發動。從牌組將「打破命運」以外的1張記載「龍騎兵 D-END」的卡名或「D-HERO」怪獸的卡名的魔法、陷阱卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4017398,'ZEXAL託付',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地的「希望皇霍普」、「ZW」、「ZS」怪獸之中任何1隻為對象可以發動。那隻怪獸加入手牌或特殊召喚。\u000a②：我方的生命值比對手少2000以上的場合，將墓地的此卡除外，以「ZEXAL託付」以外的我方墓地1張「ZEXAL」魔法、陷阱卡為對象可以發動。那張卡加入手牌。此效果在此卡送去墓地的回合不能發動。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4019153,'No.4 源數之門-肆',unistr('等級1怪獸×3\u000a①：此卡不會被戰鬥破壞。\u000a②：此卡和對手怪獸進行戰鬥的傷害步驟結束時，去除此卡的1個超量素材可以發動。我方場上的全部「源數」怪獸的攻擊力直到回合結束時變成2倍。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4022819,'聖刻龍-阿賽特龍',unistr('此卡可以不用解放來召喚。這個方法召喚的此卡的原攻擊力變成1000。\u000a1回合1次，選擇場上的1隻龍族通常怪獸可以發動。場上的全部「聖刻」怪獸的等級直到回合結束時變成和選擇的怪獸相同。\u000a此外，此卡被解放時，從我方的手牌、牌組、墓地選1隻龍族通常怪獸，攻擊力、守備力變成0特殊召喚。'),'不解放的召喚','等級變更','特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4026187,'講述妖精傳姬之人',unistr('光屬性的「妖精傳姬」怪獸+魔法使族怪獸\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡用「妖精的王子大人」為素材融合召喚的場合可以發動。對手場上的卡全部破壞，給予對手破壞數量×500傷害。\u000a②：我方的「妖精傳姬」怪獸不會被戰鬥破壞。\u000a③：對手發動魔法、陷阱、怪獸的效果時，從我方的手牌、墓地將1張「妖精傳姬」卡片除外可以發動。那個發動無效並破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4031928,'心變','①：以對手場上1隻怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4035199,'形體抓取者','具有令人驚訝的力量的蝶形領帶，能夠套上敵人的身體，對它進行襲擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4041838,'忍者大師 佐助','此卡向表側守備怪獸攻擊的場合，不進行傷害計算，那隻怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4042268,'島龜','小島般大的海龜，從不潛入海中，在其龜殼上棲息著樹木與動物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4055337,'自鳴天琴 夢魘曲',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡不會被連結怪獸戰鬥破壞。\u000a②：將墓地的此卡除外，以場上1隻表側表示怪獸為對象可以發動。從牌組將「自鳴天琴 夢魘曲」以外的1隻機械族、闇屬性怪獸送去墓地，對象怪獸的攻擊力直到回合結束時上升送去墓地的怪獸的等級×100。此效果的發動後，直到回合結束時我方除了闇屬性怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4058065,'入魔沙羅曼龍','①：從我方墓地將1隻怪獸除外可以發動。此卡的攻擊力直到對手的回合結束時上升300。這個效果1回合可以使用最多2次。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4059313,'神威烈焰加農砲',unistr('①：選我方場上1隻「拉的翼神龍」。那隻怪獸直到回合結束時得到以下效果。此卡的發動和效果不會被無效化。\u000a●此卡不受對手的效果影響。\u000a●此卡進行戰鬥的攻擊宣言時，解放我方場上任意數量的這個回合沒有攻擊宣言的其他怪獸可以發動。此卡的攻擊力直到回合結束時上升解放的怪獸的原攻擊力的合計數值。\u000a●此卡攻擊的傷害計算後可以發動。對手場上的怪獸全部送去墓地。'),'「神威烈焰加農砲」的效果適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4064256,'不死世界',unistr('①：場上的表側表示怪獸以及墓地的怪獸變成不死族。\u000a②：雙方除了不死族怪獸以外不能上級召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4064925,'古代機械齒輪進軍',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方不能覆蓋卡片。\u000a①：作為此卡的發動時的效果處理，從牌組將「古代機械齒輪進軍」以外的1張「古代機械齒輪」魔法、陷阱卡加入手牌。\u000a②：1回合1次，將我方場上1隻怪獸解放可以發動。我方抽1張卡，這個回合中，適用以下效果。\u000a●我方將「古代機械齒輪巨人」或記載那個卡名的等級5以上的怪獸召喚的場合可以不用解放。'),'效果1','效果2','不解放的召喚（古代機械齒輪進軍）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4068622,'BF-極光之奧羅拉',unistr('此卡不能通常召喚。只能將我方場上表側表示存在的1隻「BF」協調和1隻協調以外的怪獸除外來特殊召喚。\u000a1回合1次，可以從我方的額外牌組將1隻「BF」同步怪獸除外，直到結束階段時此卡和那隻怪獸當作同名卡，得到相同的攻擊力和效果。'),'當作同名卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4072687,'難以接受的結果','①：我方場上有魔法使族怪獸存在的場合可以發動。從手牌將1隻「占卜魔女」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4079728,'全力衝鋒！守寶妖精！',unistr('等級4「守寶妖精」怪獸×2隻以上\u000a這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡超量召喚的場合或被送去墓地的場合可以發動。從我方的牌組、墓地將1隻「守寶妖精船長 颯嘉斯」特殊召喚。\u000a②：去除此卡的2個超量素材可以發動。從牌組選以下怪獸其中1隻加入手牌或特殊召喚。\u000a●「守寶妖精」怪獸\u000a●「獸帶鬥神」怪獸\u000a●「阿不思的落胤」或記載那個卡名的怪獸'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081094,'第二之棺','此卡只能用「第一之棺」的效果出到場上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081665,'娛樂法師 高蹺射手',unistr('「娛樂法師 高蹺射手」的②效果1回合只能使用1次。\u000a①：場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。這個方法特殊召喚過的回合，我方不能通常召喚。\u000a②：我方墓地有此卡以外的「娛樂法師」怪獸存在，給予對手傷害的魔法、陷阱、怪獸的效果發動時，將墓地的此卡除外可以發動。給予對手2000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081825,'混沌無限','①：場上的守備表示怪獸全部變成表側攻擊表示。那之後，從我方的牌組、墓地選1隻「機皇」怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化，在結束階段破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4103668,'翼之魔妖-天狗',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：「翼之魔妖-天狗」在我方場上只能有1隻表側表示存在。\u000a②：此卡在墓地存在，原等級是9的我方的同步怪獸被戰鬥或對手的效果破壞的場合可以發動。從我方墓地將1隻其他的不死族怪獸除外，此卡特殊召喚。\u000a③：此卡從墓地特殊召喚成功的場合可以發動。選對手場上1張魔法、陷阱卡破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4130270,'GB獵人','只要此卡在場上表側表示存在，雙方玩家不能讓場上的卡回到牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4141820,'儀式魔人 預知者',unistr('進行儀式召喚的場合，可以將墓地的此卡除外，作為那次儀式召喚所需等級數值的1隻怪獸。\u000a如果使用此卡儀式召喚的儀式怪獸給予對手戰鬥傷害，對手選1張手牌捨棄。'),'捨棄手牌（儀式魔人 預知者）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4145852,'十二獸 羊衝',unistr('①：此卡被戰鬥、效果破壞的場合，以「十二獸 羊衝」以外的我方墓地1隻「十二獸」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：持有此卡作為素材的原種族是獸戰士族的超量怪獸得到以下效果。\u000a●以此卡為對象的對手的陷阱卡的效果發動時，去除此卡的1個超量素材可以發動。那個發動無效。'),'效果1','●陷阱卡的效果發動無效（十二獸 羊衝）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4145915,'奇巧人偶-殺手騎士',unistr('這個卡名的①②效果1回合各能使用1次，這些效果發動的整回合中，我方除了「奇巧人偶」怪獸以外不能從額外牌組特殊召喚。\u000a①：此卡在手牌存在的場合，以我方墓地1隻「奇巧人偶」怪獸或對手墓地1隻怪獸為對象可以發動。那隻怪獸在持有者的場上效果無效守備表示特殊召喚。那之後，此卡特殊召喚。\u000a②：此卡從手牌以外送去墓地的場合可以發動。此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4148264,'G戰隊 黑亮',unistr('身穿黑亮戰衣並遊走戰場的“黑之閃光”......\u000a哪裡有暗影哪裡就有G戰隊！牠們還會運用自己暗藏的飛行能力來對付巨大怪獸呢！！'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4149689,'天狗的團扇','①：只要此卡在魔法與陷阱區域存在，等級2以下的怪獸在反轉召喚成功時破壞。此時那隻怪獸不能發動在場上發動的效果。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4160316,'百夫長騎士的牽絆',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、墓地將1隻「百夫長」怪獸當作永續陷阱卡在我方的魔法與陷阱區域表側表示放置。\u000a②：此卡在墓地存在的狀態，我方場上有「百夫長」同步怪獸特殊召喚的場合，將此卡除外，以我方墓地1隻「百夫長」怪獸為對象可以發動。那隻怪獸當作永續陷阱卡在我方的魔法與陷阱區域表側表示放置。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4162088,'電子雷射龍',unistr('此卡不能通常召喚。只能用「光子產生裝置」的效果特殊召喚。\u000a可以選擇1隻攻擊力或守備力在此卡的攻擊力以上的怪獸破壞。這個效果1回合只能使用1次。'),'場上的怪獸破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4167084,'黎明的墮天使 路西菲爾',unistr('天使族、闇屬性怪獸×3\u000a這個卡名的①③效果1回合只有1次能使用其中1個。\u000a①：「墮天使 路西菲爾」作為素材將此卡融合召喚成功的場合可以發動。對手場上的卡全部破壞。\u000a②：只要此卡在怪獸區域存在，我方場上的天使族怪獸不會成為對手的效果的對象。\u000a③：我方、對手的主要階段，支付1000生命值可以發動。從我方的手牌、墓地選1隻天使族怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4168871,'黑羽的寶牌','將手牌1隻「BF」怪獸從遊戲中除外可以發動。從我方牌組抽2張卡。此卡發動的整回合中，我方不能將怪獸特殊召喚。「黑羽的寶牌」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4178474,'雷電破碎','①：捨棄1張手牌，以場上1張卡為對象可以發動。那張卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4179255,'妖精龍 上古',unistr('協調+協調以外的怪獸1隻以上\u000a我方回合有場地魔法卡發動的場合，從牌組抽1張卡。「妖精龍 上古」的這個效果1回合只能使用1次。\u000a此外，1回合1次，場地魔法卡表側表示存在的場合，可以選擇場上表側攻擊表示存在的1隻怪獸破壞。'),'抽1張卡','破壞攻擊表示怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4179849,'紅葉的女王','生活在被紅葉圍繞的地方，綠樹的靈王的妃子。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4192696,'森之聖靈 厄科','對手的卡片效果讓我方受到傷害時可以發動。此卡從手牌特殊召喚，給予對手和受到的傷害相同數值的傷害。那之後，這個回合雙方受到的效果傷害變成0。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4206964,'落穴','①：對手將攻擊力1000以上的怪獸召喚、反轉召喚時，以那1隻怪獸為對象可以發動。那隻攻擊力1000以上的怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4215180,'棒棒喵☆黯蜜',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：連結1怪獸或等級2的同步怪獸在我方場上存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合，以對手墓地1張卡為對象可以發動。那張卡回到牌組。用同步怪獸的效果特殊召喚的場合，也能改成將對象卡片除外。'),'從手牌特殊召喚','效果2','是否改成除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4215636,'霞之谷的祭壇','1回合1次，風屬性怪獸被效果破壞送去我方墓地時，可以從我方的手牌或牌組將1隻風屬性、等級3以下的怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4227096,'誤捕','①：此卡的發動後，直到下個我方回合結束時，雙方不能用抽牌以外的方法從牌組將卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4230620,'超能破碎','超能族怪獸召喚成功時，可以藉由支付500生命值，那隻怪獸的等級上升1，攻擊力上升300。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4239451,'娛樂夥伴 顛倒蛙',unistr('【靈擺效果】\u000a①：1回合1次，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到回合結束時交換。\u000a【怪獸效果】\u000a①：我方戰鬥階段1次，以我方場上1隻怪獸為對象可以發動。那隻怪獸的表示形式變更，其攻擊力、守備力直到回合結束時交換。'),'攻守交換','表示形式變更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4252828,'海洋弓箭手',unistr('1回合1次，可以選擇我方場上1隻等級3以下的怪獸，當作只能有1張的裝備卡給此卡裝備。\u000a已用此效果將怪獸裝備的場合，此卡的攻擊力上升800。\u000a場上的此卡被破壞的場合，可以將此卡的效果裝備的怪獸破壞作為代替。'),'當成裝備卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4253484,'劍鬥獸 重裝鬥士',unistr('此卡已被「劍鬥獸」怪獸的效果特殊召喚的場合，此卡的原守備力變成2400。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到牌組，從牌組將「劍鬥獸 重裝鬥士」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4259068,'魔力儉約術','我方不用為了發動魔法卡而支付生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4266839,'精神寄生體',unistr('場上裡側守備表示的此卡被對手怪獸攻擊的傷害計算前，此卡變成攻擊怪獸的裝備卡。\u000a每次對手的準備階段，我方的生命值回復此卡的裝備怪獸的攻擊力一半數值。'),'變成裝備卡','回復生命值','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4271596,'灰滅城之王',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：場地區域有「灰滅之都 黑曜」存在的場合，此卡可以從手牌特殊召喚。\u000a②：我方主要階段可以發動。從手牌將「灰滅城之王」以外的1隻「灰滅」怪獸特殊召喚。對手場上有攻擊力2800以上的怪獸存在的場合，也能改成從牌組挑選。'),'','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4280258,'召命的神弓-阿波羅薩',unistr('衍生物以外的卡名不同的怪獸2隻以上\u000a①：「召命的神弓-阿波羅薩」在我方場上只能有1張表側表示存在。\u000a②：此卡的原攻擊力變成作為此卡的連結素材的怪獸數量×800。\u000a③：對手發動怪獸的效果時可以發動（同一連鎖上最多1次）。此卡的攻擊力下降800，那個發動無效。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4280259,'召命的神弓-阿波羅薩',unistr('衍生物以外的卡名不同的怪獸2隻以上\u000a①：「召命的神弓-阿波羅薩」在我方場上只能有1張表側表示存在。\u000a②：此卡的原攻擊力變成作為此卡的連結素材的怪獸數量×800。\u000a③：對手發動怪獸的效果時可以發動（同一連鎖上最多1次）。此卡的攻擊力下降800，那個發動無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4290468,'華麗薔薇',unistr('協調+協調以外的怪獸1隻以上\u000a1回合1次，將我方墓地的1隻植物族怪獸除外可以發動。選擇對手場上的1隻怪獸，那個攻擊力直到回合結束時變成一半。\u000a此外，在此卡攻擊過的戰鬥階段中，將我方墓地的1隻植物族怪獸除外可以發動。此卡的攻擊力直到回合結束時變成一半，在這次戰鬥階段中，此卡只有1次可以再度攻擊。'),'攻擊力下降','再次攻擊','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4333086,'不知火流 燕之太刀',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻不死族怪獸解放，以場上2張卡為對象可以發動。那些卡破壞。那之後，從牌組將1隻「不知火」怪獸除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4334811,'廢鐵回收機',unistr('①：此卡召喚、特殊召喚成功時可以發動。從牌組將1隻機械族怪獸送去墓地。\u000a②：1回合1次，讓我方墓地2隻機械族、地屬性、等級4怪獸回到牌組可以發動。我方從牌組抽1張卡。'),'選擇1隻機械族怪獸送去墓地','抽卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4335427,'創星神 蘇菲亞',unistr('此卡不能通常召喚。只能將我方、對手場上表側表示存在的儀式、融合、同步、超量怪獸各1隻除外來特殊召喚。\u000a此卡的特殊召喚不會被無效化。\u000a此卡特殊召喚成功時，此卡以外的雙方的手牌、場上、墓地的卡全部除外。應對此效果的發動，不能發動魔法、陷阱、效果怪獸的效果。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4335645,'紐特安','①：此卡被戰鬥破壞送去墓地的場合，以場上1隻怪獸為對象發動。那隻怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4341721,'Trick or treat！','①：從我方的牌組、墓地將1隻「惡作劇的大精靈 哈囉」或「糖果的大精靈 維恩」加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4357063,'先史遺產都市 巴比倫','1回合1次，將我方墓地1隻「先史遺產」怪獸除外，從我方墓地選擇1隻和除外的怪獸等級相同的「先史遺產」怪獸可以發動。選擇的怪獸特殊召喚。','從墓地特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4367330,'十二獸 兔銃',unistr('①：此卡被戰鬥、效果破壞的場合，以「十二獸 兔銃」以外的我方墓地1張「十二獸」卡片為對象可以發動。那張卡加入手牌。\u000a②：持有此卡作為素材的原種族是獸戰士族的超量怪獸得到以下效果。\u000a●以此卡為對象的對手的魔法卡的效果發動時，去除此卡的1個超量素材可以發動。那個發動無效。'),'效果1','●魔法卡的效果發動無效（十二獸 兔銃）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4376658,'憑依裝著-希塔',unistr('①：此卡可以將我方場上的表側表示的1隻「火靈使 希塔」和1隻炎屬性怪獸送去墓地，從手牌、牌組特殊召喚。\u000a②：此卡的①方法特殊召喚的此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4376659,'憑依裝著-希塔',unistr('①：此卡可以將我方場上的表側表示的1隻「火靈使 希塔」和1隻炎屬性怪獸送去墓地，從手牌、牌組特殊召喚。\u000a②：此卡的①方法特殊召喚的此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4388680,'復仇屍者 屠戮者',unistr('藉由「仇屍」儀式魔法卡降臨。這個卡名的②效果1回合只能使用1次。\u000a①：此卡和對手怪獸進行戰鬥的傷害計算時1次，從我方墓地將1隻不死族怪獸除外可以發動。此卡的攻擊力上升300。\u000a②：儀式召喚的此卡被送去墓地的場合可以發動。從牌組將1張儀式魔法卡加入手牌，從牌組將1隻「仇屍」怪獸送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4392470,'獅子男巫','披著黑披風的魔術師。其正體是隻能說話的獅子。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4398189,'白森林的魔女',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的③效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻「白森林」怪獸加入手牌。那個場合，這個回合，我方不能將闇屬性怪獸從額外牌組特殊召喚。\u000a②：我方的「白森林」怪獸1回合各有1次不會被戰鬥破壞。\u000a③：以我方場上1隻「白森林」怪獸為對象可以發動。這個回合，那隻怪獸當作協調。'),'','','效果3','是否從牌組加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(4404099,'潛藏海底的深海龍',unistr('每次雙方的準備階段，給此卡放置1個海洋計數器。\u000a此卡從場上離開時，我方場上的魚族、海龍族怪獸的攻擊力直到回合結束時上升此卡放置的海洋計數器的數量×200。'),'放置計數器','攻擊力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4408198,'驅魔修女阿們武裝',unistr('這個卡名的卡在1回合只能發動1張，對手場上沒有從墓地特殊召喚的怪獸存在的場合，只能在對手回合發動。\u000a①：支付800生命值，以我方場上1隻「驅魔修女」怪獸為對象可以發動。同名卡不在我方場上存在的1隻「驅魔修女」超量怪獸重疊在作為對象的我方怪獸上方當作超量召喚從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4417407,'幻獸機 黑獵鷹',unistr('此卡的攻擊宣言時，將1隻「幻獸機衍生物」（機械族、風、等級3、攻/守0）特殊召喚。\u000a此卡的等級上升我方場上的「幻獸機衍生物」的等級的合計數值。\u000a只要我方場上有衍生物存在，此卡不會被戰鬥、效果破壞。\u000a此外，1回合1次，將1隻衍生物解放可以發動。選擇對手場上的1隻怪獸變成表側守備表示。此效果在對手回合也能發動。'),'特殊召喚衍生物','變成表側守備表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4417408,'幻獸機衍生物','由「幻獸機」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4423206,'M.X-軍刀 招來者',unistr('等級3怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材可以發動。從牌組將1隻戰士族或獸戰士族的地屬性、等級4怪獸守備表示特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4433488,'電腦網級聯','①：我方將連結怪獸連結召喚成功的場合，以其中1隻作為連結素材的我方墓地的怪獸為對象可以發動。那隻怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4440873,'強烈的打落','①：對手從牌組將卡加入手牌時可以發動。對手將加入手牌的其中1張卡捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4446672,'古代機械齒輪爆彈','選擇我方場上表側表示存在的1隻「古代機械齒輪」怪獸可以發動。對象怪獸破壞，給予對手那隻怪獸的原攻擊力一半數值的傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4450854,'隱藏的機殼',unistr('「隱藏的機殼」在1回合只能發動1張。\u000a①：從我方的額外牌組將最多3張表側表示的「機殼」靈擺怪獸加入手牌。'),'從額外牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4466015,'毒液飛濺','選擇1隻放置毒液計數器的怪獸可以發動。去除那張卡的毒液計數器，給予對手去除的毒液計數器的數量×700傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4472318,'岩龍 裸岩甲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的手牌、場上的怪獸被戰鬥、效果破壞的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡被對手破壞的場合，以此卡以外的我方墓地最多2隻恐龍族或岩石族的怪獸為對象可以發動（相同種族最多1隻）。那些怪獸特殊召喚。'),'從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4474060,'SPYRAL GEAR-無人機',unistr('①：此卡召喚、特殊召喚成功的場合可以發動。從對手牌組上方確認3張卡，以喜歡的順序回到牌組上方。\u000a②：將此卡解放，以我方場上1隻「SPYRAL」怪獸為對象可以發動。那隻怪獸的攻擊力上升對手場上的卡片數量×500。此效果在對手回合也能發動。\u000a③：從我方墓地將此卡和1張「SPYRAL」卡片除外，以我方墓地1隻「SPYRAL-花花公子」為對象可以發動。那張卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4478086,'時脈龍牙兵',unistr('電子界族怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。從牌組將1張「電腦網結合」加入手牌。\u000a②：此卡指向的區域有怪獸特殊召喚的場合，以我方墓地1隻等級4以下的電子界族怪獸為對象可以發動。那隻怪獸效果無效特殊召喚。此效果的發動後，直到回合結束時我方除了融合怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4483598,'全主動雙工暴龍',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：從我方墓地將2隻連結怪獸除外可以發動。此卡從手牌特殊召喚。\u000a②：連結狀態的我方怪獸在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a③：此卡被送去墓地的場合，以我方場上1隻電子界族怪獸為對象可以發動。那隻怪獸的攻擊力上升1000。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4483989,'反擊準備','對手向表側守備表示怪獸攻擊宣言時，投擲1次硬幣並猜正反面。如果猜對，成為攻擊對象的表側守備表示怪獸變成攻擊表示。如果猜錯，此卡的控制者受到攻擊怪獸的攻擊力超過攻擊對象怪獸的守備力數值的傷害。','猜硬幣','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4538826,'終焉龍 混沌帝',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：支付1000生命值，以被除外的1隻我方的龍族怪獸為對象可以發動。此卡破壞，那隻怪獸加入手牌。\u000a【怪獸效果】\u000a此卡不能通常召喚。「終焉龍 混沌帝」1回合1次，只能將我方墓地的光屬性和闇屬性怪獸各1隻除外，從手牌、額外牌組特殊召喚。\u000a①：1回合1次，支付一半生命值可以發動。額外怪獸區域以外的我方場上的卡全部送去墓地，最多到送去墓地的數量，選對手場上的卡送去墓地。那之後，給予對手送去對手墓地的數量×300傷害。\u000a②：特殊召喚的表側表示的此卡從場上離開的場合回到牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4542651,'混沌光罩','我方場上的全部怪獸的守備力上升300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4545683,'機皇帝 神陸∞',unistr('此卡不能通常召喚，只能用自身的效果特殊召喚。\u000a①：我方場上的表側表示怪獸被效果破壞送去墓地時可以發動。手牌的此卡特殊召喚。\u000a②：1回合1次，以對手場上1隻同步怪獸為對象可以發動。那隻對手同步怪獸給此卡裝備。\u000a③：這個攻擊力、守備力上升我方的生命值一半的數值，攻擊力上升自身的效果裝備的怪獸的攻擊力數值。\u000a④：以自身的效果裝備的1隻怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'效果1','效果2','效果4','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4545854,'超量領域','超量怪獸和怪獸進行戰鬥的傷害計算時，那隻超量怪獸的攻擊力和守備力上升其階級×200。場上的此卡被效果破壞的場合，可以去除我方場上的1個超量素材作為代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4549095,'燃燒拳手 反擊拳','我方場上的「燃燒拳手」怪獸進行戰鬥的傷害步驟時，將手牌或墓地的此卡除外可以發動。那隻怪獸的攻擊力直到回合結束時上升1000。「燃燒拳手 反擊拳」的效果1回合只能使用1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4550066,'重建鹿','①：此卡戰鬥破壞對手怪獸時，以我方墓地1隻攻擊力1500以下的電子界族怪獸為對象可以發動。那隻怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4575541,'超龍災禍',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方的手牌、墓地、除外狀態的1隻「征龍」怪獸特殊召喚。那之後，可以只用我方場上的「征龍」怪獸為素材進行1隻「征龍」超量怪獸的超量召喚。\u000a②：我方主要階段將墓地的此卡除外，以我方的除外狀態的任意數量「征龍」怪獸為對象可以發動（相同屬性最多1隻）。那些怪獸回到墓地。'),'效果1','效果2','是否進行超量召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4582942,'律導的異響鳴琴',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「異響鳴琴」怪獸卡存在的場合，從以下效果挑選1個適用。我方場上有「異響鳴琴」連結怪獸存在的場合，可以兩者都適用。\u000a●我方回復500生命值。那之後，可以將場上1張魔法、陷阱卡破壞。\u000a●我方受到500傷害。那之後，可以讓場上1隻怪獸回到手牌。'),'效果1','●回復','●傷害','兩者都選','是否將場上的1張卡破壞？','是否讓場上1隻怪獸回到手牌？','','','','','','','','','','');
INSERT INTO texts VALUES(4587638,'咆哮的大地','我方場上的獸族怪獸向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。適用這個效果給予對手的生命值戰鬥傷害時，對手場上的1隻表側表示怪獸的攻擊力、守備力下降500。','攻守下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4591250,'亞馬遜女帝',unistr('「亞馬遜女王」+「亞馬遜」怪獸\u000a①：只要此卡在怪獸區域存在，此卡以外的我方場上的「亞馬遜」卡片不會被戰鬥、效果破壞。\u000a②：我方的「亞馬遜」怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a③：融合召喚的表側表示的此卡因對手的效果從場上離開的場合，或被戰鬥破壞的場合可以發動。從我方的手牌、牌組、墓地選1隻「亞馬遜女王」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4599182,'歸來的死神',unistr('這個卡名在規則上也當作「無限地獄」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、墓地的怪獸以及被除外的我方怪獸之中，選1隻「無限地獄」怪獸特殊召喚。\u000a②：此卡在墓地存在的狀態，我方場上的表側表示的「無限地獄」怪獸因對手的效果從場上離開的場合，或被戰鬥破壞的場合可以發動。此卡在我方場上覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4606229,'最後的希望編號',unistr('這個卡名在規則上也當作「銀河眼」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：支付一半生命值，以我方墓地2隻怪獸為對象可以發動。那2隻怪獸效果無效特殊召喚，只用那2隻為素材將1隻「No.」超量怪獸超量召喚。此卡的發動後，直到回合結束時我方除了這個效果的超量召喚以外只能有1次從額外牌組將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4611269,'獅面短吻鱷','我方場上有此卡以外的爬蟲類族怪獸存在的場合，我方場上存在的爬蟲類族怪獸向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4611341,'S-Force 亂名者',unistr('包含「S-Force」怪獸的怪獸2隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡的正前方有對手怪獸存在，對手不能將此卡作為效果的對象，不能用怪獸發動的效果將怪獸特殊召喚。\u000a②：我方、對手回合，以場上1隻怪獸為對象可以發動。那隻怪獸的位置向那個控制者的其他的主要怪獸區域移動。'),'效果2','請選擇移動位置的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4614116,'闇能量',unistr('只能給惡魔族怪獸裝備。\u000a①：裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4628897,'超電導戰機 皇神磁砲王',unistr('「磁石勇士 電磁武神」+「電磁石勇士 電磁狂神」\u000a此卡只能用以上述卡為融合素材的融合召喚來特殊召喚。\u000a①：1回合1次，對手發動怪獸的效果、魔法、陷阱卡時可以發動。那個發動無效並破壞。\u000a②：表側表示的此卡因對手的效果從場上離開的場合可以發動。「磁石勇士 電磁武神」「電磁石勇士 電磁狂神」各1隻從手牌、牌組無視召喚條件特殊召喚。'),'發動無效','無視條件特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4632019,'八章大蛇',unistr('①：將場上的此卡作為同步素材的場合，可以將此卡的等級當作8。\u000a②：用此卡作為同步素材的同步怪獸依照其原等級得到以下效果。\u000a●8以下：此卡的攻擊力、守備力上升800。\u000a●9以上：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'「八章大蛇」的效果2適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4638410,'暴君的威壓',unistr('將我方場上的1隻怪獸解放可以發動。\u000a只要此卡在場上存在，場上表側表示存在的原持有者是我方的怪獸不受此卡以外的陷阱卡的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4647954,'ZS-昇華賢者',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上沒有卡存在的場合，此卡可以從手牌特殊召喚。\u000a②：用場上的此卡為素材超量召喚的「希望皇霍普」怪獸得到以下效果。\u000a●這次超量召喚的場合可以發動。從牌組將1張「升階魔法」通常魔法卡加入手牌。'),'效果1','●檢索「升階魔法」通常魔法卡（ZS-昇華賢者）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4682617,'魔界劇團的謝幕',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：「魔界台本」魔法卡的效果發動的回合可以發動。最多到我方墓地的「魔界台本」魔法卡數量，從我方的額外牌組將表側表示的「魔界劇團」靈擺怪獸加入手牌。那之後，可以選最多到此效果加入手牌的怪獸數量，從手牌將「魔界劇團」靈擺怪獸特殊召喚（同名卡最多1張）。此卡的發動後，直到回合結束時我方除了「魔界劇團」靈擺怪獸以外不能特殊召喚。'),'是否從手牌特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4688231,'鍊裝 秘銀天使',unistr('「鍊裝」怪獸+靈擺怪獸\u000a「鍊裝 秘銀天使」的①效果1回合只能使用1次。\u000a①：以我方墓地2張「鍊裝」卡片和場上1張卡為對象可以發動。墓地的對象卡片回到牌組，場上的對象卡片回到持有者的手牌。\u000a②：此卡從場上送去墓地的場合可以發動。選1隻我方的額外牌組的表側表示的「鍊裝」靈擺怪獸或我方墓地的「鍊裝」靈擺怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4694209,'卡片守衛',unistr('此卡召喚、特殊召喚成功時，給此卡放置1個守衛計數器。\u000a此卡的攻擊力上升此卡放置的守衛計數器的數量×300。\u000a1回合1次，藉由去除此卡放置的1個守衛計數器，在此卡以外的我方場上1張表側表示的卡放置1個守衛計數器。選擇的卡被破壞的場合，去除1個守衛計數器作為代替。'),'放置計數器','轉移計數器','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4709881,'星杯劍士 奧拉姆',unistr('「星杯」怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡的攻擊力上升我方墓地的「星遺物」怪獸種類×300。\u000a②：將此卡指向的1隻我方的「星杯」怪獸解放，以那隻怪獸以外的我方墓地1隻怪獸為對象可以發動。那隻怪獸在此卡指向的我方場上特殊召喚。\u000a③：此卡從場上送去墓地的場合可以發動。從手牌將1隻「星杯」怪獸特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4722253,'光芒使者 機亞弗里德',unistr('此卡不能通常召喚。只能在我方墓地的光屬性怪獸是5種以上的場合特殊召喚。\u000a我方場上表側表示存在的怪獸只有戰士族的場合，可以藉由將我方墓地的1隻戰士族怪獸除外，魔法、陷阱卡的發動無效並破壞。這個效果1回合只能使用1次。'),'發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4729591,'計量機塊 天平河童',unistr('「機塊」怪獸1隻\u000a這個卡名的①②效果1回合各能使用1次。此卡在連結召喚的回合不能作為連結素材。\u000a①：解放互相連結狀態的此卡可以發動。從我方墓地選「計量機塊 天平河童」以外的1隻「機塊」連結怪獸特殊召喚。\u000a②：解放不是互相連結狀態的此卡可以發動。從我方墓地選1隻等級4以下的「機塊」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4731783,'無光之影 阿寶阿庫',unistr('包含惡魔族怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，可以捨棄1張手牌，從以下效果選擇1個發動。\u000a●場上1張卡破壞。\u000a●此卡直到結束階段除外，從我方墓地將1隻光、闇屬性怪獸特殊召喚。\u000a②：我方準備階段可以發動。依照我方墓地的怪獸的種族種類的數量，我方抽牌。那之後，挑選抽牌數量的我方的手牌以喜歡的順序回到牌組下方。'),'效果1','效果2','●場上1張卡破壞','●此卡直到結束階段除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(4731784,'無光之影 阿寶阿庫',unistr('包含惡魔族怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，可以捨棄1張手牌，從以下效果選擇1個發動。\u000a●場上1張卡破壞。\u000a●此卡直到結束階段除外，從我方墓地將1隻光、闇屬性怪獸特殊召喚。\u000a②：我方準備階段可以發動。依照我方墓地的怪獸的種族種類的數量，我方抽牌。那之後，挑選抽牌數量的我方的手牌以喜歡的順序回到牌組下方。'),'效果1','效果2','●場上1張卡破壞','●此卡直到結束階段除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(4732017,'灼熱殭屍','此卡從墓地裡特殊召喚時，我方從牌組抽1張卡。','抽1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4740489,'磁石場地',unistr('「磁石場地」的①效果1回合只能使用1次。\u000a①：我方場上有等級4以下的岩石族、地屬性怪獸存在的場合，以我方墓地1隻等級4以下的「磁石戰士」怪獸為對象可以發動此效果。那隻怪獸特殊召喚。\u000a②：1回合1次，我方的岩石族、地屬性怪獸的戰鬥沒有將對手怪獸破壞的傷害步驟結束時可以發動。那隻對手怪獸回到持有者的手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4754691,'水陸兩用戰鬥艇 Mk-11',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：場上沒有「海」存在的場合，此卡的攻擊力上升700，此卡不能直接攻擊。\u000a②：場上有「海」存在的場合，以1隻水屬性以外的表側表示怪獸為對象可以發動。那隻怪獸破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4756629,'入魔雙蛇杖使',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：將我方墓地1隻「入魔」怪獸除外，以我方墓地1隻「入魔」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：此卡的①效果適用的回合的主要階段可以發動。將1隻「入魔」怪獸召喚。\u000a③：此卡被送去墓地的回合，「入魔」怪獸召喚的場合需要的解放可以減少1隻。'),'加入手牌','召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4779091,'尤貝爾-被厭惡的騎士',unistr('此卡不能通常召喚。只能用「尤貝爾」的效果特殊召喚。\u000a①：此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a②：攻擊表示的此卡被選擇作為攻擊對象的場合，那次傷害計算前發動。給予對手攻擊怪獸的攻擊力數值的傷害。\u000a③：我方結束階段發動。場上的其他怪獸全部破壞。\u000a④：表側表示的此卡從場上離開時可以發動。從我方的手牌、牌組、墓地將1隻「尤貝爾-極度悲傷的魔龍」特殊召喚。'),'傷害','破壞','特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4779823,'光道天使長 米迦勒',unistr('協調+協調以外的光屬性怪獸1隻以上\u000a①：1回合1次，支付1000生命值，以場上1張卡為對象可以發動。那張卡除外。\u000a②：此卡被破壞時，以此卡以外的我方墓地任意數量的「光道」怪獸為對象可以發動。那些怪獸回到牌組，我方回復回去數量×300生命值。\u000a③：我方結束階段發動。從我方牌組上方將3張卡送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4786063,'超重武者裝留 火焰鎧',unistr('①：我方主要階段以我方場上1隻「超重武者」怪獸為對象可以發動。從我方的手牌、場上將這隻怪獸當作裝備卡給那隻我方怪獸裝備。裝備怪獸的等級變成5。\u000a②：將此卡從手牌捨棄，以我方場上1隻守備表示的「超重武者」怪獸為對象可以發動。直到回合結束時，那隻怪獸的守備力下降800，不會被戰鬥、效果破壞。此效果在對手回合也能發動。'),'變成裝備卡','守備力下降800','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4796100,'有翼幻獸 客邁拉',unistr('「幻獸王 加賽爾」+「巴風特」\u000a①：此卡被破壞時，以我方墓地1隻「幻獸王 加賽爾」或「巴風特」為對象可以發動。那隻怪獸特殊召喚。'),'從墓地特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4807253,'娛樂法師 火焰吞食者',unistr('①：給予我方傷害的魔法、陷阱、怪獸的效果發動時可以發動。此卡從手牌特殊召喚，那個效果使我方受到的傷害變成0。這個回合我方除了「娛樂法師」怪獸以外不能特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：此卡召喚、特殊召喚成功的場合發動。雙方玩家受到500傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4810585,'戰華史略-長坂之雄',unistr('這個卡名的②③效果1回合只有1次能使用其中1個。\u000a①：我方的「戰華」怪獸進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a②：對手戰鬥階段開始時，將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。這個回合，對手不能選擇「戰華」怪獸作為攻擊對象。\u000a③：對手怪獸的攻擊宣言時，將墓地的此卡除外可以發動。從牌組將1隻「戰華」怪獸特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4810828,'古聖戴 薩拉維思',unistr('藉由「精靈的祝福」降臨。\u000a①：對手發動以我方場上的怪獸為對象的魔法、陷阱、怪獸的效果時，將此卡從手牌捨棄可以發動。那個發動無效。\u000a②：對手將怪獸特殊召喚之際，讓場上的此卡回到手牌可以發動。那次特殊召喚無效，那些怪獸除外。'),'發動無效','特殊召喚無效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4820694,'星聖暴風',unistr('「星聖暴風」的①效果在決鬥中只能使用1次。\u000a①：我方結束階段，以我方場上2隻持有超量素材的「星聖」超量怪獸為對象可以發動。那2隻超量怪獸的超量素材全部去除，對手的生命值變成一半。\u000a②：我方準備階段，以我方場上1隻「星聖」超量怪獸和我方墓地1隻「星聖」怪獸為對象可以發動。那隻墓地的怪獸重疊在那隻超量怪獸下方作為超量素材。'),'對手的生命值變成一半','增加超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4825390,'典當的魔物帳簿','①：以對手場上最多2隻怪獸為對象可以發動。那些怪獸直到結束階段除外。那之後，對手回復因此效果從場上離開的怪獸數量×1000生命值。','效果1','請選擇回到場上的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4836680,'娛樂夥伴 異色眼祭司',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：以我方墓地1張「娛樂夥伴」卡片或「異色眼」卡片為對象可以發動。那張卡加入手牌。那之後，此卡破壞。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：靈擺召喚的此卡依照表示形式，在我方主要階段可以發動以下效果。\u000a●攻擊表示：將此卡除外，以我方墓地1隻「娛樂夥伴」怪獸或「異色眼」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a●守備表示：從牌組選1隻「娛樂夥伴」靈擺怪獸或「異色眼」靈擺怪獸表側表示加入我方的額外牌組或送去墓地。'),'加入我方的額外牌組','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4837861,'機皇神龍 三曲枝',unistr('此卡不能通常召喚。從我方墓地將3種「機皇」怪獸各1隻除外可以特殊召喚。\u000a①：1回合1次，此卡的攻擊宣言時可以發動。確認對手的額外牌組，選其中1隻怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力數值。\u000a③：已裝備同步怪獸的此卡在1次戰鬥階段中可以向怪獸攻擊3次。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4841383,'蕾禍繚亂狂咲',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：場上的昆蟲族、植物族、爬蟲類族怪獸的攻擊力、守備力上升300，那以外的場上的怪獸的攻擊力、守備力下降300。\u000a②：可以從以下效果選擇1個發動。\u000a●從牌組將1隻「蕾禍」怪獸加入手牌。那之後，選1張我方的手牌捨棄。\u000a●我方的手牌、墓地、除外狀態的1隻「蕾禍」怪獸守備表示特殊召喚。'),'','效果2','●從牌組加入手牌','●特殊召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(4848423,'衛生兵 肌肉壯漢','①：此卡的戰鬥讓我方或對手受到戰鬥傷害的場合，改成讓生命值回復那個數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4849037,'舞蹈士兵','藉由「舞蹈的誘發」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4857085,'Ω眼鏡',unistr('只能給我方場上的怪獸裝備。\u000a1回合1次，隨機確認對手的1張手牌。此效果發動的整回合中，裝備怪獸不能攻擊。'),'確認','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4861205,'木乃伊的呼聲','①：1回合1次，我方主要階段可以發動。從手牌將1隻不死族怪獸特殊召喚。此效果在我方場上沒有怪獸存在的場合可以發動和處理。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4869446,'沙漠的裁決','場上的表側表示怪獸不能變更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4891376,'鎖縛龍 鎖鐮',unistr('協調+同步怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：將我方場上的此卡作為同步素材的場合，可以將此卡當作協調以外的怪獸。\u000a②：連鎖卡的效果的發動，來發動魔法、陷阱、怪獸的效果時，可以從以下效果選擇1個發動。\u000a●那個效果無效並破壞。\u000a●那個效果連鎖的卡的效果無效並破壞。'),'','效果2','●那個效果無效並破壞','●前一個效果無效並破壞','','','','','','','','','','','','');
INSERT INTO texts VALUES(4896788,'強欲之壺的精靈','①：「強欲之壺」發動的場合發動。那個發動「強欲之壺」的玩家可以從牌組抽1張卡。此效果在此卡在怪獸區域表側攻擊表示存在的場合發動和處理。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4904633,'影依的原核',unistr('①：此卡發動後變成效果怪獸（魔法使族、闇、等級9、攻1450/守1950）在怪獸區域特殊召喚。將此效果特殊召喚的此卡作為「影依」融合怪獸的融合素材的場合，可以代替那張卡記載屬性的融合素材怪獸。此卡也當作陷阱卡。\u000a②：此卡被效果送去墓地的場合，以「影依的原核」以外的我方墓地1張「影依」魔法、陷阱卡為對象可以發動。那張卡加入手牌。'),'從墓地加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4904812,'次世代領航員','①：此卡召喚時，從牌組將1隻水屬性怪獸送去墓地可以發動。從牌組將1隻「次世代控制者」加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4906301,'死靈守衛者','①：在對手回合將墓地的此卡除外可以發動。這個回合，對手怪獸的攻擊只有1次無效。','攻擊無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4909946,'頭目大遊行',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，從牌組將1隻「巨大戰艦」怪獸加入手牌。\u000a②：1回合1次，我方主要階段可以發動。我方的手牌、場上1隻怪獸破壞，從牌組將1隻攻擊力1200且守備力1000以下的機械族、光屬性怪獸在我方或對手場上特殊召喚。\u000a③：將墓地的此卡除外可以發動。從我方的牌組、墓地將1張「頭目連環戰」在我方場上表側表示放置。'),'效果1','效果2','效果3','是否在對手場上特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(4914353,'空隙絕緣者',unistr('怪獸2隻\u000a①：此卡指向的怪獸的攻擊力、守備力下降800。\u000a②：此卡在墓地存在，我方場上有電子界族連結怪獸連結召喚時可以發動。此卡在那隻怪獸指向的我方場上特殊召喚。此效果特殊召喚的此卡不能作為連結素材，從場上離開的場合被除外。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4918855,'龍血公 吸血鬼',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡召喚成功的場合，以對手墓地最多2隻怪獸為對象可以發動。那些怪獸效果無效在我方場上守備表示特殊召喚。\u000a②：怪獸的效果發動時，那些同名怪獸在我方、對手的墓地存在的場合可以發動。那個發動無效。\u000a③：怪獸從對手墓地特殊召喚的場合，將我方場上2隻怪獸解放可以發動。此卡從墓地特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4920010,'怨念集合體','懷恨而死的人的意識集成的惡靈，襲擊人的意識在不斷的變大。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4923662,'混沌擊發','①：對手怪獸的攻擊宣言時，將我方場上1隻怪獸解放，以那1隻攻擊怪獸為對象可以發動。那隻攻擊怪獸破壞。那之後，給予對手1000傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4928565,'珠淚哀歌 剎帝利怒威',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方、對手的主要階段可以發動。此卡從手牌特殊召喚，從我方的手牌、墓地選1張「剎帝利怒威」卡片或「珠淚哀歌」卡片除外。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從我方或對手的牌組上方將3張卡送去墓地。\u000a③：此卡被效果送去墓地的場合可以發動。從我方牌組上方將2張卡送去墓地。'),'N/A','從我方牌組上方','從對手牌組上方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4929256,'冰帝 梅比烏斯','①：此卡上級召喚成功時，以場上最多2張魔法、陷阱卡為對象可以發動。那些卡破壞。','選擇場上的最多2張魔法陷阱卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4931121,'影之牌組破壞病毒','①：解放我方場上1隻守備力2000以上的闇屬性怪獸可以發動。確認對手場上的怪獸，對手的手牌，用對手回合計算的3回合中對手抽到的卡，其中守備力1500以下的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4931562,'山戰士','在處於不利的情況下也可以隨意活動的強健戰士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4939890,'影依刺蝟',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡反轉的場合可以發動。從牌組將1張「影依」魔法、陷阱卡加入手牌。\u000a②：此卡被效果送去墓地的場合可以發動。從牌組將「影依刺蝟」以外的1隻「影依」怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4941482,'密告蜘蛛','場上的此卡被效果送去墓地時，得到對手場上1隻守備表示怪獸的控制權。','得到控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4965193,'極征龍-極光',unistr('龍族等級7怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，從牌組將1隻等級7的「征龍」怪獸送去墓地，去除此卡的1個超量素材可以發動。此效果變成和從牌組被送去墓地的那隻怪獸的將自身從手牌捨棄發動的效果相同。\u000a②：此卡被戰鬥或對手的效果破壞的場合可以發動。我方的墓地、除外狀態的1隻等級7的「征龍」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4991081,'神鷹寵物龍-聖火千兆',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上有等級6以下的風屬性怪獸存在的場合可以發動。此卡從手牌守備表示特殊召喚。\u000a②：只要此卡在怪獸區域存在，雙方怪獸不能選擇等級6以下的「神鷹」怪獸作為攻擊對象。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將1隻鳥獸族、風屬性怪獸送去墓地。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4993187,'W：P變幻舞夜',unistr('效果怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：對手發動場上、墓地的怪獸的效果時，將這個回合特殊召喚的此卡直到結束階段除外可以發動。那個效果無效並除外。\u000a②：對手的主要階段可以發動（應對這個發動，雙方不能發動連結怪獸的效果）。進行1隻連結怪獸的連結召喚。我方場上的此卡作為連結素材的場合，對手場上1隻連結2以下的連結怪獸也能作為連結素材。'),'效果1','效果2','直到結束階段除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4997565,'No.3 地獄蟬王',unistr('等級3怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡的表示形式變更的場合可以發動。從我方的手牌、墓地將1隻昆蟲族怪獸守備表示特殊召喚。\u000a②：場上的怪獸的效果發動時，去除此卡的1個超量素材，以那1隻怪獸為對象可以發動。那隻怪獸的效果無效。那之後，選場上1隻昆蟲族怪獸，守備力上升500或表示形式變更。'),'效果1','效果2','守備力上升500','表示形式變更','','','','','','','','','','','','');
INSERT INTO texts VALUES(4998619,'方界超獸 爆裂乾闥爾',unistr('此卡不能通常召喚。只能將我方場上3隻「方界」怪獸送去墓地來特殊召喚。\u000a①：這個方法特殊召喚的此卡的攻擊力上升3000。\u000a②：此卡在1次戰鬥階段中可以攻擊3次。\u000a③：此卡被對手送去墓地的場合，以我方墓地最多3隻「方界」怪獸為對象可以發動。那些怪獸特殊召喚。那之後，可以從我方的牌組、墓地選1張「方界」卡片加入手牌。'),'是否把1張「方界」卡片加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5008836,'守護神 艾克佐迪亞',unistr('此卡不能特殊召喚。此卡的①方法召喚的此卡戰鬥破壞原持有者是對手的惡魔族、闇屬性怪獸時，我方獲得決鬥勝利。\u000a①：此卡可以解放5隻怪獸來召喚。\u000a②：此卡的攻擊力、守備力變成為了召喚此卡而解放的怪獸的原本的攻擊力、守備力各自的合計數值。'),'解放5隻怪獸召喚','特殊勝利','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5010422,'占術姬 通靈板摩莉甘','①：此卡反轉的場合發動。那個回合的結束階段，將對手場上的守備表示怪獸全部破壞，給予對手破壞的怪獸數量×500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5014629,'潛航母艦 航空鯊',unistr('等級3怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材可以發動。給予對手相當於我方的除外狀態的怪獸數量×100傷害。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5026221,'神星的波動','①：1回合1次，我方主要階段以及對手戰鬥階段可以發動此效果。從手牌將1隻「星騎士」怪獸特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5037726,'光靈術-「聖」','①：將我方場上1隻光屬性怪獸解放，以被除外的1隻我方或對手的怪獸為對象可以發動。對手可以從手牌展示1張陷阱卡讓此效果無效。不展示的場合，對象怪獸在我方場上特殊召喚。','是否從手牌展示1張陷阱卡讓此效果無效？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5041348,'天威的龍鬼神',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：對手發動怪獸的效果時可以發動。那隻怪獸除外。\u000a②：此卡的攻擊破壞效果怪獸送去墓地的場合發動。此卡的攻擊力上升破壞的怪獸的原攻擊力數值。這次戰鬥階段中，此卡只有1次可以向怪獸再度攻擊。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043010,'防火牆龍',unistr('怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在場上表側表示存在期間只有1次，我方、對手回合，最多到與此卡互相連結的怪獸數量，以我方、對手的場上、墓地的怪獸為對象可以發動。那些怪獸回到手牌。\u000a②：此卡指向的怪獸被戰鬥破壞的場合或被送去墓地的場合可以發動。從手牌將1隻電子界族怪獸特殊召喚。'),'效果1','效果2','已發動效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043011,'防火牆龍',unistr('怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在場上表側表示存在期間只有1次，我方、對手回合，最多到與此卡互相連結的怪獸數量，以我方、對手的場上、墓地的怪獸為對象可以發動。那些怪獸回到手牌。\u000a②：此卡指向的怪獸被戰鬥破壞的場合或被送去墓地的場合可以發動。從手牌將1隻電子界族怪獸特殊召喚。'),'效果1','效果2','已發動效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043012,'防火牆龍',unistr('怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在場上表側表示存在期間只有1次，我方、對手回合，最多到與此卡互相連結的怪獸數量，以我方、對手的場上、墓地的怪獸為對象可以發動。那些怪獸回到手牌。\u000a②：此卡指向的怪獸被戰鬥破壞的場合或被送去墓地的場合可以發動。從手牌將1隻電子界族怪獸特殊召喚。'),'效果1','效果2','已發動效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043013,'防火牆龍',unistr('怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在場上表側表示存在期間只有1次，我方、對手回合，最多到與此卡互相連結的怪獸數量，以我方、對手的場上、墓地的怪獸為對象可以發動。那些怪獸回到手牌。\u000a②：此卡指向的怪獸被戰鬥破壞的場合或被送去墓地的場合可以發動。從手牌將1隻電子界族怪獸特殊召喚。'),'效果1','效果2','已發動效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5050644,'芬芳花園',unistr('①：1回合1次，我方場上有「芬芳」怪獸存在的場合可以發動。我方回復500生命值。此效果的發動後，直到下個對手回合結束時我方場上的怪獸的攻擊力、守備力上升500。\u000a②：我方場上的「芬芳」怪獸被戰鬥、效果破壞送去墓地的場合發動。我方回復1000生命值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5052212,'簡易調和','①：從我方墓地將1隻協調除外，以我方場上1隻表側表示怪獸為對象可以發動。那隻我方怪獸的攻擊力上升為了發動此卡而除外的協調的攻擊力數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5053103,'牛頭人','有著強大力量的牛怪，斧頭一揮能砍倒一切東西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5063379,'劍鬥獸的鬥技場-弗拉維競技場',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：捨棄1張手牌可以發動。從牌組將1隻「劍鬥獸」怪獸加入手牌。\u000a②：對手怪獸的攻擊宣言時可以發動。從牌組將1隻「劍鬥獸」怪獸特殊召喚。此效果特殊召喚的怪獸不會被戰鬥破壞。\u000a③：這個回合已有「劍鬥獸」怪獸從我方牌組特殊召喚的場合，結束階段可以發動。從牌組將1張「劍鬥」陷阱卡在我方場上覆蓋。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5067884,'機動霧龍 棘龍',unistr('【靈擺效果】\u000a①：此卡以外的我方場上的「機動霧龍」卡片被戰鬥或對手的效果破壞的場合，可以將此卡破壞作為代替。\u000a【怪獸效果】\u000a①：可以解放此卡以外的我方場上1隻「機動霧龍」怪獸，從以下效果選擇1個發動。\u000a●這個回合，此卡可以直接攻擊。\u000a●這個回合，此卡在1次戰鬥階段中可以攻擊2次。'),'N/A','●直接攻擊','●攻擊2次','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5068132,'夢蟬 睡鳴鳴蟬',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上有攻擊表示的昆蟲族怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合，以場上1隻怪獸為對象可以發動。那隻怪獸的表示形式變更。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5087128,'霰彈槍彈龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以場上的此卡為對象的連結怪獸的效果發動時可以發動。此卡破壞。那之後，選和此卡存在過的區域相同縱列的1隻怪獸破壞，那個相鄰區域有怪獸存在的場合，那些怪獸也破壞。\u000a②：場上的此卡被戰鬥、效果破壞送去墓地的回合的結束階段可以發動。從牌組將「霰彈槍彈龍」以外的1隻「槍彈」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5088741,'代碼點火員',unistr('等級4怪獸×2\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡超量召喚的場合可以發動。從牌組將1隻電子界族儀式怪獸加入手牌。\u000a②：去除此卡的1個超量素材可以發動。解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻儀式怪獸。\u000a③：此卡作為連結素材送去墓地的場合可以發動。從牌組將1張「A.i.」陷阱卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5109321,'R.B.搖擺節奏',unistr('此卡發動的整回合中，我方除了原攻擊力1500以下的機械族怪獸以外不能從額外牌組特殊召喚。\u000a①：從牌組、額外牌組將同名卡不在我方場上存在的1隻「R.B.」怪獸特殊召喚。\u000a②：我方場上的「R.B.」怪獸被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5121528,'巨大戰艦 德林加核心',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌1隻其他的「巨大戰艦」怪獸可以發動。此卡從手牌特殊召喚。那之後，給此卡放置3個計數器。\u000a②：我方、對手的主要階段，可以去除此卡的1個計數器，從以下效果選擇1個發動。\u000a●從牌組將1張「頭目連環戰」或記載那個卡名的魔法、陷阱卡加入手牌。\u000a●從我方墓地將1隻等級9以下的「巨大戰艦」怪獸特殊召喚。'),'效果1','效果2','●從牌組加入手牌','●從墓地特殊召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(5125629,'Sin Paradigm Shift',unistr('這個卡名的卡在1回合只能發動1張。此卡也能支付一半生命值從手牌發動。\u000a①：從我方的牌組、墓地選1張「Sin World」加入手牌或在我方的場地區域表側表示放置。那之後，從牌組、額外牌組將1隻「Sin」怪獸無視召喚條件守備表示特殊召喚。那之後，對手場上有攻擊力2500以上的怪獸存在的場合，對手場上的全部怪獸的攻擊力直到回合結束時下降2500。'),'效果1','表側表示放置','適用「Sin Paradigm Shift」的效果來發動','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5126490,'新宇賢者',unistr('此卡不能通常召喚。只能將我方的怪獸區域的表側表示的「E.HERO 新宇俠」和「尤貝爾」各1隻送去墓地來特殊召喚。\u000a①：場上的此卡不會被效果破壞。\u000a②：此卡和對手怪獸進行戰鬥的傷害步驟結束時發動。給予對手那隻對手怪獸的攻擊力數值的傷害。我方的生命值回復那隻對手怪獸的守備力數值。'),'給予對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5128859,'E.HERO 海洋新宇俠',unistr('「E.HERO 新宇俠」+「新空間俠 海洋海豚」\u000a只能讓我方場上的上述卡回到牌組，從額外牌組特殊召喚。\u000a①：1回合1次，我方主要階段可以發動。對手的手牌隨機選1張破壞。'),'隨機破壞手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5130393,'千年的血族',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方因戰鬥、效果受到1000以上的傷害時可以發動。此卡從手牌特殊召喚。\u000a②：以對手墓地1隻攻擊力不是?的怪獸為對象可以發動。對手可以從牌組挑選1隻攻擊力不是?的怪獸。沒有挑選的場合，或對象怪獸的攻擊力較高的場合，對象怪獸在我方場上特殊召喚。挑選的怪獸回到牌組。其他情況的場合，對手將挑選的怪獸加入手牌。'),'效果1','效果2','請選擇1隻攻擊力不是?的怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5133471,'銀河氣旋',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以場上1張裡側表示的魔法、陷阱卡為對象可以發動。那張卡破壞。\u000a②：將不是在這個回合送去墓地的此卡從墓地除外，以場上1張表側表示的魔法、陷阱卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5141117,'深淵的相劍龍',unistr('此卡不能通常召喚，只能用幻龍族怪獸的效果特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：卡的效果讓怪獸被表側除外的場合可以發動。此卡從手牌、墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：此卡特殊召喚的場合，以場地區域1張卡和對手的場上、墓地1隻怪獸為對象可以發動。那些卡除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5148778,'霸王暴龍 飢餓毒液翼龍',unistr('【靈擺效果】\u000a①：只要此卡在靈擺區域存在，每次對手場上有怪獸特殊召喚，給那隻怪獸放置1個捕食計數器。已放置捕食計數器的等級2以上的怪獸的等級變成1。\u000a【怪獸效果】\u000a融合怪獸+「清透翼」怪獸\u000a①：1回合1次，對手將怪獸表側表示特殊召喚的場合，以其中1隻為對象可以發動。直到回合結束時，此卡的攻擊力上升那隻怪獸的攻擊力數值，那隻怪獸的效果無效化。\u000a②：1回合1次，此卡以外的卡的效果在場上發動時可以發動。場上1張卡破壞。\u000a③：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'','效果1','效果2','效果3','','','','','','','','','','','','');
INSERT INTO texts VALUES(5153769,'威風妖怪突風','①：以我方的靈擺區域1張「威風妖怪」卡片為對象可以發動。那張卡特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5168381,'惡魔之技','①：我方場上有惡魔族怪獸存在的場合，以場上1張卡為對象可以發動。那張卡破壞。那之後，可以從牌組將1隻惡魔族怪獸送去墓地。','是否從牌組將1隻惡魔族怪獸送去墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5177985,'不知火的師範',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在墓地存在，我方場上有2種以上「不知火」怪獸存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：此卡被除外的場合，以我方場上1隻不死族怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升600。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5182107,'超重武者 同心C-N',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從我方的額外牌組（表側）將1隻機械族靈擺怪獸加入手牌。\u000a②：我方墓地沒有魔法、陷阱卡存在的場合，將此卡解放可以發動。除了「超重武者 同心C-N」以外，從我方的手牌、墓地將1隻攻擊力1500以下的機械族、地屬性怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5183693,'下克上的首飾',unistr('只能給通常怪獸裝備。\u000a裝備怪獸和等級更高的怪獸進行戰鬥的場合，裝備怪獸的攻擊力只在傷害計算時上升雙方等級差額×500。\u000a此卡被送去墓地時，可以讓此卡回到牌組最上方。'),'回到牌組最上方','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5186893,'真紅眼不死龍',unistr('此卡可以解放1隻不死族怪獸以攻擊表示上級召喚。\u000a①：此卡戰鬥破壞不死族怪獸送去墓地時可以發動。那隻不死族怪獸在我方場上特殊召喚。'),'解放1隻不死族怪獸召喚','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5205146,'無限起動 壓路機',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在，機械族、地屬性怪獸被解放的場合，或被表側表示除外的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：持有此卡作為素材的原種族是機械族的超量怪獸得到以下效果。\u000a●只要此卡在怪獸區域存在，對手場上的表側表示怪獸變成守備表示，守備力下降1000。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5206415,'天雷震龍-雷龍',unistr('此卡不能通常召喚。雷族怪獸的效果在手牌發動的回合，從手牌以及我方場上的表側表示怪獸之中將1隻等級8以下的雷族怪獸除外可以特殊召喚。\u000a①：對手回合1次，從我方墓地將包含雷族怪獸的2張卡除外，以我方場上1隻雷族怪獸為對象可以發動。這個回合，那隻怪獸不會成為對手的效果的對象。\u000a②：我方結束階段可以發動。從牌組將1張「雷龍」卡片送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5208118,'靈擺動點P',unistr('①：我方、對手的準備階段發動。給此卡放置1個T計數器。\u000a②：1回合1次，以我方的主要怪獸區域1隻靈擺怪獸為對象可以發動。依照此卡的T計數器的數量，重複「作為對象的靈擺怪獸的位置向與其相鄰的怪獸區域移動」的處理。那之後，和對象怪獸相同縱列的對手場上，有等級、階級在對象怪獸的靈擺刻度數值以下的融合、超量怪獸存在的場合，將其全部破壞，給予對手其攻擊力合計數值的傷害。'),'效果2','請選擇移動位置的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5220687,'迅捷的大倉鼠','反轉：可以從我方牌組將1隻等級3以下的獸族怪獸裡側守備表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5230799,'魔彈射手 比利小子',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方、對手回合我方可以從手牌發動「魔彈」魔法、陷阱卡。\u000a②：和此卡相同縱列有魔法、陷阱卡發動的場合，從手牌捨棄1張「魔彈」卡片可以發動。我方抽2張卡。'),'效果2','適用「魔彈射手 比利小子」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5237827,'大日神械歐姆','此卡召喚成功時，選擇我方墓地的1張裝備魔法卡除外。那張卡在下個我方準備階段加入手牌。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5244497,'獨家攝手','此卡向守備力高於此卡的攻擊力的場上表側表示存在的怪獸攻擊的場合，不進行傷害計算，那隻怪獸破壞。','怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5253985,'交錯之魂',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方、對手的主要階段可以發動。進行1隻幻神獸族怪獸的上級召喚。那個時候，也能將對手場上的怪獸解放來代替我方場上的怪獸。將對手場上的怪獸解放來上級召喚的場合，適用以下效果。\u000a●此卡的發動後，直到下個回合結束時我方1回合只能發動1次幻神獸族怪獸以外的魔法、陷阱、怪獸的效果。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5255013,'神數的輝跡',unistr('①：我方的靈擺區域有2張「神數」卡片存在，已適用靈擺刻度1和7的場合可以發動此卡。我方場上有「神數」怪獸以外的怪獸存在的場合，那些怪獸回到持有者的牌組。\u000a②：只要此卡在魔法與陷阱區域存在，雙方不能從手牌、額外牌組以外將怪獸特殊召喚。\u000a③：只要我方的靈擺區域有卡存在，此卡不會成為效果的對象，我方的靈擺區域的卡被破壞的場合此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5257687,'XENO','反轉：選擇對手場上的1隻怪獸，直到結束階段時得到其控制權。以此效果得到控制權的怪獸在這個回合可以直接攻擊對手玩家。','得到控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5259518,'捕食植物 太陽瓶子草喙嘴龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手場上的怪獸已放置捕食計數器的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡被對手破壞的場合，以「捕食植物 太陽瓶子草喙嘴龍」以外的我方墓地1隻龍族、植物族的闇屬性怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5265750,'海賊船 血骸骨號','船頭有著紅色骸骨的海賊船，在各種海域神出鬼沒，襲擊客船和貨船。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5267507,'地縛神 緋暗紅新星',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：「地縛神」怪獸在場上只能有1隻表側表示存在。\u000a②：我方、對手的主要階段，將手牌、墓地的此卡除外可以發動。從我方的手牌、場上（表側表示）將1隻「地縛神」怪獸或「暗紅惡魔龍」送去墓地。那之後，可以從以下效果適用1個。\u000a●從牌組、額外牌組將1隻「地縛」怪獸特殊召喚。\u000a●從額外牌組將1隻「緋暗紅新星龍」當作同步召喚特殊召喚。'),'效果2','是否特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5284653,'入魔鬼火','和此卡進行戰鬥的效果怪獸的效果在傷害計算後無效化。','傷害計算後無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5285665,'E.HERO 新生泡沫人',unistr('此卡不能通常召喚。只能將我方場上的「E.HERO 泡沫人」和手牌的「突然變異」送去墓地來特殊召喚。\u000a只要此卡在場上表側表示存在，卡名當作「E.HERO 泡沫人」。\u000a此卡進行戰鬥的傷害步驟結束時，與此卡進行戰鬥的對手怪獸破壞。'),'進行戰鬥的怪獸破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5288597,'升級轉變',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻表側表示怪獸送去墓地可以發動。從牌組將1隻和墓地的那隻怪獸種族、屬性相同且等級高1級的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5291803,'先史遺產 圖拉守護者',unistr('場地魔法卡表側表示存在的場合，此卡可以從手牌特殊召喚。\u000a「先史遺產 圖拉守護者」在我方場上只能有1隻表側表示存在。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5298175,'占卜魔女 小水',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：抽到此卡時，向對手展示此卡可以發動。此卡從手牌特殊召喚。\u000a②：此卡從手牌特殊召喚成功的場合，以此卡以外的場上1隻表側表示怪獸為對象可以發動。那隻怪獸直到下個我方回合的準備階段除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5309481,'甦醒的魔王 哈帝斯',unistr('「殭屍帶菌者」+協調以外的不死族怪獸1隻以上\u000a只要此卡在場上表側表示存在，我方場上的不死族怪獸戰鬥破壞的效果怪獸的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5318639,'氣旋','①：以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5318640,'氣旋','①：以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5325155,'毒之魔妖-束脛',unistr('①：「毒之魔妖-束脛」在我方場上只能有1隻表側表示存在。\u000a②：此卡在墓地存在，「毒之魔妖-束脛」以外的我方的「魔妖」怪獸被戰鬥或對手的效果破壞的場合可以發動。此卡特殊召喚。此效果發動的整回合中，我方除了「魔妖」怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5325424,'牙龍轉生','選擇被除外的1隻我方的龍族怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5329790,'協議守衛者',unistr('電子界族怪獸2隻\u000a①：對手不能選擇此卡指向的怪獸作為攻擊對象。\u000a②：此卡1回合只有1次不會被戰鬥破壞。那時我方受到的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5338223,'強制進化','將我方場上1隻「進化蟲」怪獸解放可以發動。從牌組將1隻「進化龍」怪獸特殊召喚。此效果特殊召喚的怪獸當作用「進化蟲」怪獸的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5352328,'驅魔修女 索菲亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有其他的「驅魔修女」怪獸存在的場合可以發動。我方抽1張卡。我方場上有「驅魔修女 伊雷娜」存在的場合，隨後我方回復800生命值。\u000a②：對手讓我方或對手的卡從墓地離開的場合可以發動。將1隻「驅魔修女」超量怪獸重疊在我方場上的此卡上方當作超量召喚從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5361647,'燃燒拳手 玻璃下巴',unistr('①：此卡被選擇作為攻擊對象的場合發動。此卡破壞。\u000a②：此卡被效果送去墓地時，以「燃燒拳手 玻璃下巴」以外的我方墓地1隻「燃燒拳手」怪獸為對象可以發動。那隻怪獸加入手牌。'),'此卡破壞','從墓地加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5361816,'聖騎士 佩里諾爾',unistr('這個卡名的效果1回合只能使用1次。\u000a①：以此卡裝備的1張「聖劍」裝備魔法卡和對手場上1隻表側表示怪獸為對象可以發動。那些卡破壞。那之後，我方從牌組抽1張卡。此效果的發動後，直到回合結束時此卡不能攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5368615,'火車螺旋機人','「螺旋機人」+「火車機人」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5370235,'電子暗黑奇美拉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌捨棄1張魔法、陷阱卡可以發動。從牌組將1張「力量焊接」加入手牌。這個回合，我方只能用龍族、機械族的「電子」怪獸作為融合素材，我方將怪獸融合召喚的場合只有1次，也能將我方墓地的怪獸除外作為融合素材。\u000a②：此卡被送去墓地的場合可以發動。從牌組將同名卡不在我方墓地存在的1隻「電子暗黑」怪獸送去墓地。'),'效果1','效果2','是否使用「電子暗黑奇美拉」的效果？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5371656,'食魂的魔刀',unistr('只能給我方場上的等級3以下的通常怪獸裝備。\u000a將裝備怪獸以及衍生物以外的我方場上的通常怪獸全部解放可以發動此卡。裝備怪獸的攻擊力上升解放的通常怪獸數量×1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5373478,'電子龍二型',unistr('①：只要此卡在墓地存在，卡名當作「電子龍」。\u000a②：1回合1次，向對手展示手牌的1張魔法卡可以發動。此卡的卡名直到結束階段當作「電子龍」。\u000a③：此卡向對手怪獸攻擊的傷害步驟期間，此卡的攻擊力上升300。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5376159,'緋暗紅星雨',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上有等級8以上的同步怪獸存在的場合可以發動。場上的怪獸之中，等級最高的怪獸以外的怪獸全部除外。場上的全部表側表示怪獸直到回合結束時不受自身以外的卡的效果影響。\u000a②：此卡在墓地存在的狀態，我方場上有龍族、闇屬性同步怪獸同步召喚的場合可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5380979,'歡迎光臨拉比麗斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻「拉比麗斯」怪獸特殊召喚。此卡的發動後，直到下個回合結束時我方除了惡魔族怪獸以外不能從牌組、額外牌組特殊召喚。\u000a②：不是在這個回合送去墓地的此卡在墓地存在的狀態，我方的通常陷阱卡的效果讓怪獸從場上離開的場合可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5388481,'燃燒的士兵','熱烈燃燒的特種部隊工作者，火藥專家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5399521,'音響戰士 麥克風',unistr('【靈擺效果】\u000a①：另一邊的我方的靈擺區域沒有「音響戰士」卡片存在的場合，此卡的靈擺刻度變成4。\u000a②：我方結束階段，以被除外的1隻我方的「音響戰士」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a【怪獸效果】\u000a①：此卡可以去除我方場上的3個音響計數器，從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻怪獸。'),'召喚（音響戰士 麥克風）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5402805,'天威的鬼神','包含連結怪獸的怪獸2隻以上','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405694,'混沌士兵','藉由「混沌的儀式」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405695,'混沌士兵','擁有與B・W・D同等能力的最強戰士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405696,'混沌士兵','藉由「混沌的儀式」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5414777,'精靈的世界',unistr('這個卡名的卡在1回合只能發動1張。這個卡名的②③效果只能在我方場上有等級7以上的龍族、光屬性同步怪獸存在的場合發動。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻記載「上古妖精龍」的卡名的怪獸加入手牌。\u000a②：每次怪獸攻擊表示特殊召喚發動。那些怪獸變成守備表示。\u000a③：我方、對手的結束階段發動。回合玩家場上的攻擊表示怪獸全部破壞。'),'效果1','效果2','效果3','是否將1張卡加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(5431722,'星宿之吼炎',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以場上1張表側表示的魔法卡為對象可以發動。那張卡的效果直到回合結束時無效。那之後，可以適用以下效果。\u000a●「星宿之吼炎」以外的我方的墓地、除外狀態的1張「星宿」卡片回到牌組最下方。那之後，我方抽1張卡。'),'','是否抽1張卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5434080,'無頭騎士','被判決為反賊遭處刑的騎士的亡靈，為尋找失去的東西，無論遇到誰都會受到他的攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5438492,'荒野的女戰士','①：此卡被戰鬥破壞送去墓地時可以發動。從牌組將1隻攻擊力1500以下的戰士族、地屬性怪獸攻擊表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5439384,'炎雄爆誕',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方墓地的守備力200的炎屬性怪獸之中以1隻協調和1隻協調以外的怪獸為對象可以發動。那2隻怪獸除外，從額外牌組將1隻等級和那個等級合計相同的炎屬性同步怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5464695,'火炎木人18','全身被灼熱火焰吞沒的巨木化身。火焰攻擊雖然強力，但由於自身著火所以時日不多了。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5466615,'突變魔連鎖應動',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：此卡發動時，可以選擇對手場上1隻效果怪獸為對象。那個場合，從我方墓地將1隻「突變魔」怪獸除外，對象怪獸的效果直到回合結束時無效。\u000a②：我方的等級8以上的「突變魔」怪獸戰鬥破壞對手怪獸時可以發動。我方從牌組抽1張卡。'),'使用效果1','發動但不使用效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5479217,'朱羅紀衝擊','①：我方場上有攻擊力2500以上的恐龍族怪獸存在的場合可以發動。場上的卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5489987,'花札衛－櫻上幕簾－',unistr('此卡不能通常召喚。以此卡的①效果可以特殊召喚。\u000a①：向對手展示手牌的此卡可以發動。我方從牌組抽1張卡，給雙方確認。那是「花札衛」怪獸的場合，此卡特殊召喚。不是的場合，那張卡和此卡送去墓地。\u000a②：我方的「花札衛」怪獸和對手怪獸進行戰鬥的從傷害步驟開始時到傷害計算前，將此卡從手牌捨棄可以發動。那隻進行戰鬥的我方怪獸的攻擊力直到回合結束時上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5494820,'氣旋雷射槍',unistr('只能給「超時界戰鬥機 V形蛇」裝備。\u000a裝備怪獸的攻擊力上升300。裝備怪獸向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5498296,'暗黑界的斥候 斯卡','①：此卡被戰鬥破壞送去墓地的場合發動。從牌組將1隻等級4以下的「暗黑界」怪獸加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5506791,'威風妖怪 貓',unistr('【靈擺效果】\u000a【怪獸效果】\u000a「威風妖怪 貓」的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功時可以發動。這個回合的結束階段，從牌組將1張「威風妖怪」卡片加入手牌。\u000a②：此卡只要在怪獸區域存在，不會成為對手的效果的對象，也不會被對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5519829,'心靈諮詢師 莉莉','此卡被同步怪獸的同步召喚使用送去墓地的場合，可以藉由支付500生命值，用此卡為同步素材的同步怪獸的攻擊力直到回合結束時上升1000。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5524387,'海晶少女 石狗公',unistr('水屬性怪獸2隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：以「海晶少女 石狗公」以外的我方墓地1張「海晶少女」卡片為對象可以發動。那張卡加入手牌。\u000a②：對手怪獸的攻擊宣言時，從手牌將1隻「海晶少女」怪獸送去墓地可以發動。怪獸不會被那次戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5530780,'驅魔修女 吉卜利娜',unistr('等級4怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡用「驅魔修女」怪獸為素材超量召喚的我方、對手回合，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。\u000a②：場上的此卡不會被從墓地特殊召喚的怪獸發動的效果破壞。\u000a③：去除此卡的1個超量素材可以發動。這個回合中，我方場上的超量怪獸的攻擊力上升800。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5554990,'電力金目鯛','此卡直接攻擊給予對手戰鬥傷害時，對手的手牌隨機選1張捨棄。','捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5556499,'機甲部隊要塞',unistr('①：此卡可以將手牌的機械族怪獸捨棄直到等級合計為8以上為止，從手牌、墓地特殊召喚（捨棄自身的場合，從墓地特殊召喚）。\u000a②：只要此卡在怪獸區域存在，以此卡為對象發動的對手怪獸的效果適用之際，確認對手的手牌，從其中選1張捨棄。\u000a③：此卡被戰鬥破壞送去墓地時，以對手場上1張卡為對象發動。那張對手的卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5556668,'手牌交換','雙方玩家將手牌公開，各自選1張對手的卡加入自己的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5559570,'榮耀聖潔之詩-妖精頌歌',unistr('協調+協調以外的魔法使族怪獸1隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在中央的主要怪獸區域存在，雙方除了用中央的主要怪獸區域的怪獸以外不能攻擊宣言。\u000a②：此卡在中央的主要怪獸區域存在的場合，我方、對手的主要階段可以發動。此卡回到額外牌組，從我方的手牌、牌組、墓地各將最多1隻「耀聖」怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5560911,'亡龍的戰慄-死亡驅力',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在的場合，支付一半生命值，以我方場上1隻等級6以下的怪獸為對象可以發動。此卡特殊召喚。此效果特殊召喚的此卡等級下降對象怪獸的等級數值，從場上離開的場合回到持有者的牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5562461,'闇之幻象','以場上的闇屬性怪獸為對象的怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5574510,'射敵',unistr('①：捨棄1張手牌，以對手場上1隻持有等級的怪獸為對象可以發動。擲1次骰子，依照擲出點數適用以下效果。\u000a●大於對象怪獸的等級的場合：對象怪獸破壞。那之後，可以從牌組將1隻和對象怪獸原等級相同的怪獸加入手牌。這個回合，我方不能發動「射敵」的①效果。\u000a●對象怪獸的等級以下的場合：對象怪獸的等級下降1。'),'效果1','是否將1隻怪獸加入手牌？','不能發動「射敵」的效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5577149,'野蠻人0號',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「蠻族的狂宴 LV5」加入手牌。\u000a②：只要此卡在怪獸區域存在，我方場上的「野蠻人」怪獸的攻擊力上升500。\u000a③：將此卡解放可以發動。從手牌將1隻戰士族、等級8怪獸特殊召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5577649,'廢鐵粉碎','我方場上的「廢鐵」怪獸被戰鬥以外破壞送去墓地時可以發動。場上的表側表示的魔法、陷阱卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5592689,'納祭蓮花',unistr('我方結束階段時，此卡在墓地存在，我方場上沒有魔法、陷阱卡存在的場合，可以將此卡攻擊表示特殊召喚。\u000a此卡在場上表側表示存在的場合，我方準備階段，我方受到1000傷害。'),'從墓地特殊召喚','受到1000傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5600127,'擬人多雷克','「多雷克蠕蟲」+「擬人史萊姆」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5605529,'異響鳴琴選擇',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從以下效果挑選1個適用。我方的靈擺區域沒有「異響鳴琴」卡片存在的場合，適用的效果由對手挑選。\u000a●我方回復500生命值。那之後，可以選1張我方的手牌回到牌組最下方。那個場合，我方抽2張卡。\u000a●我方受到500傷害。那之後，可以從牌組將1張「異響鳴琴選擇」以外的「異響鳴琴」魔法、陷阱卡加入手牌。'),'效果1','●回復','●傷害','是否選1張我方的手牌回到牌組最下方？','是否從牌組加入手牌？','','','','','','','','','','','');
INSERT INTO texts VALUES(5606466,'異次元的落穴','對手將1隻怪獸守備表示覆蓋時可以發動。選擇覆蓋的那1隻怪獸和我方場上的1隻怪獸破壞並除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5609226,'協調防護罩','選擇我方場上表側表示存在的1隻協調可以發動。直到下個回合結束時，選擇的協調不會被戰鬥、效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5611760,'拯救的橋梁',unistr('這個卡名的①②效果在決鬥中各能適用1次。\u000a①：場上的等級10以上的怪獸的種族是2種以上的場合可以發動。此卡以外的雙方的手牌、場上、墓地的卡全部回到持有者的牌組。那之後，雙方從牌組抽5張卡。\u000a②：將墓地的此卡除外可以發動。從牌組將1隻「寶玉獸」怪獸和1張場地魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5614808,'白鬥氣白鯨',unistr('水屬性協調+協調以外的水屬性怪獸1隻以上\u000a①：此卡同步召喚時可以發動。對手場上的攻擊表示怪獸全部破壞。\u000a②：此卡在1次戰鬥階段中可以向怪獸攻擊2次。\u000a③：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a④：此卡被對手破壞送去墓地的場合，從我方墓地將1隻其他的水屬性怪獸除外可以發動。此卡當作協調特殊召喚。'),'效果1','效果4','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5616412,'反擊拳','場上的守備表示怪獸被對手怪獸攻擊，那個守備力超過攻擊怪獸的攻擊力的場合，在傷害計算時可以發動。那隻攻擊怪獸在傷害步驟結束時破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5628232,'耳翼企鵝','像耳朵一樣長在頭上的羽毛，能夠飛天，很珍稀的企鵝。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5640330,'漢尼拔死靈師',unistr('①：此卡召喚成功的場合發動。給此卡放置1個魔力計數器（最多1個）。\u000a②：去除此卡的1個魔力計數器，以場上1張表側表示的陷阱卡為對象可以發動。那張表側表示的陷阱卡破壞。'),'放置魔力計數器','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5641251,'F.A. 白熱化',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：對手怪獸的直接攻擊宣言時可以發動。從牌組將1隻「F.A.」怪獸特殊召喚。\u000a②：我方的「F.A.」怪獸和對手怪獸進行戰鬥的傷害計算前可以發動1次。雙方各擲1次骰子。如果我方擲出的點數比對手大，那隻進行戰鬥的我方怪獸的等級直到回合結束時上升4。如果我方擲出的點數比對手小，那隻我方怪獸破壞。如果擲出的點數相同，重新擲骰子。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5645210,'華麗金星','①：只要此卡在怪獸區域存在，天使族以外的場上的怪獸的攻擊力、守備力下降500，我方場上的魔法、陷阱卡的效果的發動以及那些發動的效果不會被無效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5650082,'神風防護罩 －大氣之力－','①：對手怪獸的攻擊宣言時可以發動。對手場上的攻擊表示怪獸全部回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5672432,'娛樂夥伴復活','①：我方場上的怪獸被戰鬥、效果破壞送去墓地的場合可以發動。從我方的手牌、墓地選1隻「娛樂夥伴」怪獸特殊召喚。','從手牌、墓地特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5697558,'地中界 香巴拉',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻「地中族」怪獸加入手牌。\u000a②：1回合1次，我方主要階段可以發動。選我方1隻裡側守備表示的「地中族」怪獸變成表側攻擊表示或表側守備表示。\u000a③：1回合1次，對手怪獸的攻擊宣言時可以發動。選我方1隻裡側守備表示的「地中族」怪獸變成表側攻擊表示或表側守備表示。那之後，可以讓那次攻擊無效。'),'是否從牌組把1隻「地中族」怪獸加入手牌？','效果2','是否讓這次攻擊無效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5703682,'千之能量','我方場上表側表示存在的等級2的通常怪獸（除了衍生物以外）的原本的攻擊力、守備力上升1000。結束階段時，我方場上的等級2的通常怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5728014,'對手登場！','選擇對手場上表側表示存在的1隻怪獸可以發動。從我方的手牌將1隻和選擇的怪獸等級相同的怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5758500,'魂之解放','①：以我方、對手的墓地的卡合計最多5張為對象可以發動。那些卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5763020,'泣神的石像','將我方墓地的1隻協調除外可以發動。此卡從手牌特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5772618,'高速疾行機人 風箏龍獸',unistr('機械族、風屬性協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚成功的場合，可以從以下效果選擇1個發動。\u000a●此卡以外的場上的卡全部破壞。\u000a●對手場上的全部表側表示的卡的效果無效。\u000a②：此卡被對手送去墓地的場合可以發動。從牌組將1隻「疾行機人」怪獸加入手牌。'),'效果1','●此卡以外場上的卡全部破壞','●對手場上的卡效果無效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5779502,'形勢反轉','①：只要此卡在魔法與陷阱區域存在，我方回合中，對手場上的表側表示怪獸的效果無效化，對手回合中，我方場上的表側表示怪獸的效果無效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5780210,'創造共鳴體','①：我方場上有等級8以上的同步怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5786513,'時間沉默-回合靜默',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸的等級上升等級3。我方場上有「光之黃金櫃」以及記載那個卡名的怪獸存在的狀態，連鎖對手怪獸的效果的發動來發動此卡的場合，那個對手的效果無效。\u000a②：記載「光之黃金櫃」的卡名的我方怪獸進行戰鬥的傷害計算時，將墓地的此卡除外可以發動。那次戰鬥階段結束。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5795882,'吸血鬼的領域',unistr('①：1回合1次，支付500生命值可以發動。這個回合我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻「吸血鬼」怪獸。\u000a②：只要此卡在魔法與陷阱區域存在，我方的「吸血鬼」怪獸給予對手戰鬥傷害的場合發動。我方的生命值回復那個數值。'),'效果1','效果2','召喚（吸血鬼的領域）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5795980,'帝王的轟毅',unistr('①：將我方場上1隻等級5以上的通常召喚的表側表示怪獸解放，以場上1張表側表示的卡為對象可以發動。那張卡的效果直到回合結束時無效。那之後，我方從牌組抽1張卡。\u000a②：我方主要階段將墓地的此卡除外，宣言1個屬性可以發動。場上的全部表側表示怪獸直到回合結束時變成宣言的屬性。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5800323,'白森林的幻妖',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方墓地2隻「白森林」怪獸為對象可以發動。那些怪獸當作永續魔法卡在原持有者的魔法與陷阱區域表側表示放置。\u000a②：對手主要階段可以發動。用包含此卡的我方場上的怪獸為素材進行同步召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5817857,'核成食屍奴',unistr('此卡的控制者在每次我方結束階段，從手牌將1張「核成的鋼核」送去墓地，或向對手展示手牌的1隻不死族怪獸，或都不做讓此卡破壞。\u000a我方場上的1隻「核成」怪獸被戰鬥或效果破壞的場合，可以將我方墓地的1隻「核成」怪獸除外作為代替。'),'「核成的鋼核」送去墓地','展示不死族怪獸','破壞','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5818294,'武尊神器-邊津','①：以我方場上的「武尊神」怪獸為對象的魔法、陷阱、怪獸的效果發動時，將墓地的此卡除外可以發動。那個效果無效。','效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5818798,'幻獸王 加賽爾','奔跑的速度太快，身姿猶如幻影一般的野獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5821478,'拓撲邏輯轟炸龍',unistr('效果怪獸2隻以上\u000a①：此卡已在怪獸區域存在的狀態，此卡以外的怪獸在連結怪獸指向的區域特殊召喚的場合發動。雙方的主要怪獸區域的怪獸全部破壞。這個回合，此卡以外的我方怪獸不能攻擊。\u000a②：此卡向對手怪獸攻擊的傷害計算後發動。給予對手那隻對手怪獸的原攻擊力數值的傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5829717,'龍魔導騎士 黑魔導',unistr('「黑魔導」+等級7以上的龍族、戰士族怪獸\u000a①：我方的怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：1回合1次，我方的怪獸戰鬥破壞對手怪獸時可以發動。給予對手那隻被破壞的怪獸的原攻擊力數值的傷害。\u000a③：此卡被破壞的場合可以發動。從我方的手牌、牌組、額外牌組、墓地選「黑魔導」「龍騎士蓋亞」各1隻特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5832914,'卡通手提箱','①：我方場上有卡通怪獸存在，對手將怪獸召喚、反轉召喚、特殊召喚時可以發動。那些召喚、反轉召喚、特殊召喚的怪獸回到牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5833312,'決鬥學院',unistr('①：依照場上的怪獸的種族得到以下效果。\u000a●戰士族、獸族、炎族：1回合1次，我方發動陷阱卡的場合，以對手場上1張卡為對象可以發動。那張卡破壞。\u000a●恐龍族、海龍族、雷族：1回合1次，我方發動魔法卡的場合可以發動。給予對手1000傷害。\u000a●機械族、天使族、惡魔族：1回合1次，我方發動怪獸的效果的場合，以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力上升1000。'),'●發動陷阱卡','●發動魔法卡','●發動怪獸的效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5833929,'童話動物教母 媽咪',unistr('獸族等級2怪獸×3隻以上\u000a「童話動物教母 媽咪」1回合1次也能重疊在我方場上的「童話動物 媽咪」上方來超量召喚。\u000a①：此卡特殊召喚的場合可以發動。從我方的牌組、墓地將1張「童話動物」魔法、陷阱卡加入手牌。\u000a②：此卡的攻擊力上升作為此卡作為超量素材持有的「童話動物」怪獸的攻擊力、守備力的合計數值。\u000a③：去除此卡的5個超量素材可以發動。對手場上的卡全部回到手牌。'),'是否重疊在「童話動物 媽咪」上方來超量召喚？','效果1','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5846183,'斷路機塊 斷路紅玉獸',unistr('①：我方的「機塊」怪獸和對手怪獸進行戰鬥的傷害計算時，將此卡從手牌捨棄可以發動。那隻我方怪獸不會被那次戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。\u000a②：我方場上的「機塊」怪獸被效果破壞的場合，可以將場上、墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5848934,'靜寂的念力女術士',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合，支付1000生命值可以發動。我方的牌組、墓地、除外狀態的1張「瞬移」通常、速攻魔法卡在我方場上覆蓋。\u000a②：同步召喚的此卡被送去墓地的場合，以對手場上1張卡為對象可以發動（超能族的融合、同步怪獸其中任何種類在我方場上存在的場合，此效果的對象可以變成2張）。那些卡回到手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5851097,'虛無空間',unistr('①：只要此卡在魔法與陷阱區域存在，雙方不能將怪獸特殊召喚。\u000a②：卡片從牌組或場上送去我方墓地的場合發動。此卡破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5852388,'異界厄兆隕龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：卡片被戰鬥、效果破壞的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方主要階段可以發動。選我方的手牌、場上1隻恐龍族怪獸破壞。那之後，從手牌、牌組將1隻恐龍族通常怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了龍族、恐龍族、海龍族、幻龍族怪獸以外不能從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5861892,'大秘儀之力EX-光之支配者',unistr('此卡不能通常召喚。只能將我方場上的3隻怪獸送去墓地來特殊召喚。\u000a①：此卡特殊召喚的場合發動。投擲1次硬幣，依照那個正反面讓此卡得到以下效果。\u000a●正：此卡戰鬥破壞對手怪獸送去墓地時，以我方墓地1張卡為對象可以發動。那張卡加入手牌。\u000a●反：以此卡為對象的怪獸的效果、魔法、陷阱卡發動時發動。此卡的攻擊力下降1000，那個發動無效並破壞。'),'投擲硬幣','●正','●反','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5901497,'女王的影武者','此卡可以直接攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5908650,'幻奏的音姬 殊榮法蘭索瓦',unistr('此卡的效果發動的整回合中，我方不能發動光屬性以外的怪獸的效果。\u000a①：1回合1次，以我方墓地1隻天使族、光屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'從墓地加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5914184,'雙倍奉還',unistr('對手的效果使我方受到1000以上的傷害時可以發動。受到的傷害每有1000就給此卡放置1個倍倍計數器。\u000a下個對手回合的結束階段時，此卡破壞，給予對手此卡放置過的倍倍計數器×2000傷害。'),'此卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5914858,'調獄神 朱諾拉',unistr('協調+協調以外的怪獸2隻\u000a此卡同步召喚的場合，可以將我方的中央的主要怪獸區域1隻怪獸當作協調。\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡同步召喚的場合可以發動。對手場上的全部表側表示卡的效果無效化。\u000a②：我方、對手回合可以發動。和我方場上的「耀聖」怪獸相同縱列的對手場上的全部怪獸直到回合結束時不能作為融合、同步、超量、連結召喚的素材。'),'效果1','效果2','「調獄神 朱諾拉」的效果2適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5915629,'強欲的贈禮','對手從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5916510,'天翔的騎士',unistr('等級4怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材可以發動。從手牌將1隻光屬性怪獸特殊召喚。\u000a②：此卡在墓地存在的場合，以我方場上1隻天使族、光屬性、等級4怪獸為對象可以發動。此卡特殊召喚，將對象怪獸重疊在此卡下方作為超量素材。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5929801,'RR-朦朧伯勞',unistr('「RR-朦朧伯勞」的①②效果1回合各能使用1次，此卡的效果發動的整回合中，我方除了「RR-」怪獸以外不能特殊召喚。\u000a①：我方場上有「RR-朦朧伯勞」以外的「RR-」怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1隻「RR-朦朧伯勞」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5941982,'恐懼爪牙的繼承',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：將我方場上3隻「恐懼爪牙」怪獸解放可以發動。這個回合，對手只能用守備表示將怪獸特殊召喚。\u000a②：我方回合，將墓地的此卡除外可以發動。給予對手相當於場上的守備表示怪獸數量×100傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5969957,'槍彈填充者',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：從額外牌組特殊召喚的我方場上的表側表示的闇屬性怪獸被戰鬥、效果破壞的場合，將手牌、場上的此卡送去墓地，以那些被破壞的怪獸其中1隻為對象可以發動。從我方墓地將1隻原卡名和那隻怪獸不同的闇屬性怪獸特殊召喚。\u000a②：只要我方場上有從額外牌組特殊召喚的闇屬性怪獸存在，對手不能選擇此卡作為攻擊對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5972394,'模仿黏土',unistr('「模仿黏土」在1回合只能發動1張。\u000a①：對手場上有怪獸存在的場合，以我方場上1隻等級2以下的表側守備表示怪獸為對象可以發動。從牌組將1隻其同名怪獸守備表示特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'從牌組特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5973663,'世界樹',unistr('每次場上的植物族破壞，給此卡放置1個花計數器。\u000a此外，可以去除此卡的任意數量的花計數器，發動以下效果。\u000a●1個：選擇場上的1隻植物族怪獸，攻擊力、守備力直到回合結束時上升400。\u000a●2個：選擇場上的1張卡破壞。\u000a●3個：選擇我方墓地的1隻植物族怪獸特殊召喚。'),'●1個','●2個','●3個','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5975022,'劍鬥獸 海魚鬥士',unistr('此卡被「劍鬥獸」怪獸的效果特殊召喚成功的場合，選擇場上表側表示存在的1隻怪獸破壞。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到牌組，從牌組將「劍鬥獸 海魚鬥士」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'破壞','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5990062,'大逆轉猜謎','將我方的手牌和場上的卡全部送去墓地可以發動。猜我方牌組最上方的卡的種類（魔法、陷阱、怪獸）。如果猜對，對手和我方的生命值交換。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5993144,'燕貝',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方的手牌、場上（表側表示）1隻鳥獸族怪獸解放可以發動。從牌組將1隻等級和解放的怪獸相同的鳥獸族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5997110,'DD計數測量師',unistr('【靈擺效果】\u000a①：1回合1次，我方將「DDD」怪獸靈擺召喚的場合，以對手場上的種族相同的3隻怪獸或屬性相同的3隻怪獸為對象可以發動。那3隻表側表示怪獸之中的2隻解放。剩下的1隻的攻擊力、守備力上升解放的怪獸的對應數值的總和。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：從手牌捨棄1隻其他的「DD」怪獸可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻攻擊力或守備力是0的「DD」怪獸加入手牌。'),'靈擺效果1','效果1','效果2','請選擇留在場上的怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(5998840,'XX-軍刀 波加特騎士',unistr('將此卡作為同步素材的場合，除了「X-軍刀」怪獸的同步召喚以外不能使用。\u000a①：此卡召喚時可以發動。從手牌將1隻等級4以下的「X-軍刀」怪獸特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6004133,'魔界劇團的總彩排','①：我方主要階段1開始時可以發動。從牌組將1張「魔界劇團」卡片和1張「魔界台本」魔法卡加入手牌。此卡的發動後，直到回合結束時我方除了「魔界劇團」怪獸以外不能靈擺召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6007213,'神炎皇 烏利亞',unistr('此卡不能通常召喚。只能將我方場上3張表側表示的陷阱卡送去墓地來特殊召喚。\u000a①：此卡的攻擊力上升我方墓地的永續陷阱卡的數量×1000。\u000a②：1回合1次，以對手場上1張裡側表示的魔法、陷阱卡為對象可以發動（應對這個發動，不能發動魔法、陷阱卡）。那張裡側表示卡破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6007214,'神炎皇 烏利亞',unistr('此卡不能通常召喚。只能將我方場上3張表側表示的陷阱卡送去墓地來特殊召喚。\u000a①：此卡的攻擊力上升我方墓地的永續陷阱卡的數量×1000。\u000a②：1回合1次，以對手場上1張裡側表示的魔法、陷阱卡為對象可以發動（應對這個發動，不能發動魔法、陷阱卡）。那張裡側表示卡破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6021033,'死亡凱撒龍',unistr('「殭屍帶菌者」+協調以外的不死族怪獸1隻以上\u000a①：此卡特殊召喚成功時，以對手墓地1隻不死族怪獸為對象可以發動。那隻不死族怪獸在我方場上攻擊表示特殊召喚。此卡從場上離開時那隻怪獸破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6022371,'水魔龍-團簇',unistr('此卡不能通常召喚。只能用「鍵結」魔法、陷阱卡的效果特殊召喚。\u000a①：此卡特殊召喚成功的場合可以發動。對手場上的效果怪獸直到回合結束時攻擊力變成0，不能發動效果。\u000a②：解放此卡可以發動。從手牌、牌組將2隻「水魔龍」無視召喚條件守備表示特殊召喚。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6039967,'吸血鬼千金',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：怪獸的攻擊宣言時可以發動。此卡從手牌守備表示特殊召喚。\u000a②：我方的不死族怪獸和對手怪獸進行戰鬥的傷害計算時1次，支付100的倍數的生命值可以發動（最多3000）。那隻我方怪獸的攻擊力、守備力只在那次傷害計算時上升支付的數值。\u000a③：此卡戰鬥破壞怪獸的戰鬥階段結束時可以發動。那些怪獸從墓地盡可能在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6043161,'R.B.鋼天鑽機',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上的表側表示怪獸，不存在的場合或只有「R.B.」怪獸的場合，此卡可以從手牌特殊召喚。\u000a②：我方、對手的主要階段，此卡是與「R.B.」連結怪獸連結狀態的場合，支付500生命值，以對手場上1隻怪獸為對象可以發動。那隻怪獸和此卡破壞。'),'','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6061630,'魔力操控者',unistr('①：只要此卡在怪獸區域存在，每次我方或對手發動魔法卡，給此卡放置2個魔力計數器。\u000a②：1回合1次，去除此卡的任意數量的魔力計數器可以發動。從我方的手牌、墓地將1隻等級和去除數量相同的魔法使族怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6071005,'魔女工坊 書籍女巫瑪爾卡',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌、場上的此卡解放可以發動。從牌組將1張「魔女工坊」場地、永續魔法卡加入手牌。\u000a②：此卡在墓地存在的狀態，我方場上的表側表示的「魔女工坊」怪獸因對手的效果從場上離開的場合可以發動。此卡特殊召喚，將對手場上1隻怪獸解放。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6075533,'三叉龍的鼓動',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：依照我方場上的「冰結界」同步怪獸種類適用以下效果。\u000a●1種以上：對手場上1張卡除外。\u000a●2種以上：對手墓地1張卡除外。\u000a●3種以上：對手的手牌隨機選1張除外。\u000a②：對手發動以我方場上的「冰結界」同步怪獸為對象的魔法、陷阱、怪獸的效果時，將墓地的此卡除外可以發動。那個效果無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6075801,'巨龍的聖武士',unistr('①：此卡召喚、特殊召喚成功的場合可以發動。從我方的手牌、牌組將1隻等級7、8的龍族怪獸當作裝備卡給此卡裝備。\u000a②：已裝備裝備卡的此卡不受其他怪獸的效果影響。\u000a③：解放我方場上1隻怪獸和此卡，以我方墓地1隻等級7、8的龍族怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6077601,'魔玩具結合',unistr('「魔玩具結合」在1回合只能發動1張。\u000a①：從我方的場上、墓地將「魔玩具」融合怪獸卡決定的融合素材怪獸除外，從額外牌組融合召喚那1隻融合怪獸。\u000a\u000a※魔玩具融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6083904,'妖光之迪亞布羅肯',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方、對手回合，從我方的場上（表側表示）、墓地將1隻炎屬性怪獸除外可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合，以場上1張表側表示卡為對象可以發動。那張卡的效果直到回合結束時無效。\u000a③：此卡作為連結素材送去墓地的場合可以發動。從墓地將1張這個回合被送去我方墓地的速攻魔法、通常陷阱卡在我方場上覆蓋。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6089145,'潔淨壁',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：場上有「潔淨世界」存在的場合可以發動。從牌組將1隻記載「潔淨世界」的卡名的怪獸加入手牌。\u000a②：記載「潔淨世界」的卡名的怪獸不會被戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。\u000a③：只要記載「潔淨世界」的卡名的等級7以上怪獸在我方場上存在，「潔淨世界」的效果不論屬性全部適用於對手。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6103114,'鳥嘴蛇','用長長的身體將對手纏起來，用大嘴進行攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6103294,'綠洲的使者',unistr('只要我方場上有等級3以下的通常怪獸表側表示存在，對手不能選擇此卡為攻擊對象。\u000a只要此卡在場上表側表示存在，等級3以下的通常怪獸的戰鬥產生給此卡的控制者的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6104968,'死亡倉鼠','①：此卡反轉的場合可以發動。從牌組將1隻「死亡倉鼠」裡側守備表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6112401,'身劍一體',unistr('我方場上的怪獸只有「X-軍刀」怪獸1隻的場合可以發動。發動後此卡當作攻擊力上升800的裝備卡給那1隻怪獸裝備。\u000a裝備怪獸戰鬥破壞對手怪獸的場合，從牌組抽1張卡。'),'抽卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6116731,'蜈蚣的進軍',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉的場合，以場上1隻其他怪獸為對象可以發動。那隻怪獸變成表側攻擊表示或裡側守備表示。'),'改變表示形式','此卡變成裡側守備','是否把那隻怪獸變成裡側守備表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6128460,'白骨烤王',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在墓地存在，卡名當作「白骨」。\u000a②：我方場上的等級3以下的不死族怪獸被戰鬥、效果破壞的場合，可以將手牌的此卡捨棄作為代替。\u000a③：此卡被送去墓地的場合可以發動。從牌組將以下怪獸合計2隻加入手牌（同名卡最多1張）。那之後，選1張手牌捨棄。\u000a●「白骨」\u000a●「白骨烤王」以外的記載「白骨」的卡名的怪獸'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6133894,'魔鬼 馬傑拉',unistr('此卡不能通常召喚。只能在場上有「萬魔殿 －魔鬼的巢窟－」的場合，解放我方場上表側表示存在的1隻「傑拉的戰士」來特殊召喚。\u000a此卡特殊召喚成功的場合，對手隨機選3張手牌捨棄。此效果只在我方場上有「萬魔殿 －魔鬼的巢窟－」存在的場合適用。'),'捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6137095,'誤啟動','支付500生命值可以發動。陷阱卡的發動無效，那張卡回復原狀。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6142213,'一擊火箭',unistr('此卡攻擊的場合，此卡不會被那次戰鬥破壞。\u000a此卡攻擊的傷害計算後，給予對手攻擊對象怪獸的攻擊力一半的傷害。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6142488,'絨毛動物老鼠',unistr('此卡效果發動的整回合中，我方除了「魔玩具」怪獸以外不能從額外牌組特殊召喚。\u000a①：此卡在場上表側表示存在期間只有1次，我方主要階段可以發動。從牌組將最多2隻「絨毛動物老鼠」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6148016,'齒輪齒輪齒輪','從牌組將2隻「齒輪齒輪人」怪獸特殊召喚。此效果特殊召喚的怪獸的等級上升1。「齒輪齒輪齒輪」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6150044,'天位騎士小丑',unistr('「皇后騎士」+「傑克騎士」+「國王騎士」\u000a此卡的融合召喚只能使用上述卡進行。\u000a①：1回合1次，以場上的此卡為對象的怪獸的效果、魔法、陷阱卡發動時，將和那張卡相同種類（怪獸、魔法、陷阱）的1張手牌捨棄可以發動。那個效果無效。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6150045,'天位騎士小丑',unistr('「皇后騎士」+「傑克騎士」+「國王騎士」\u000a此卡的融合召喚只能使用上述卡進行。\u000a①：1回合1次，以場上的此卡為對象的怪獸的效果、魔法、陷阱卡發動時，將和那張卡相同種類（怪獸、魔法、陷阱）的1張手牌捨棄可以發動。那個效果無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6153210,'計都星宿',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻「星宿」怪獸加入手牌。對手場上有怪獸存在的場合，隨後可以適用以下效果。\u000a●我方的手牌、場上的怪獸作為融合素材，將1隻龍族、魔法使族的融合怪獸融合召喚。'),'','是否進行融合召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6165656,'CNo.88 奇巧人偶-災厄獅子',unistr('等級9怪獸×4\u000a此卡只能用以「No.88 奇巧人偶-命運獅子」為對象的「升階魔法」魔法卡的效果特殊召喚。我方結束階段，對手的生命值是2000以下且此卡沒有超量素材的場合，我方獲得決鬥勝利。\u000a①：場上的此卡不會成為效果的對象。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。給予對手1000傷害。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6172122,'真紅眼結合',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方不能用此卡的效果以外將怪獸召喚、特殊召喚。\u000a①：我方的手牌、牌組、場上的怪獸作為融合素材，將1隻需以「真紅眼」怪獸為融合素材的融合怪獸融合召喚。此效果特殊召喚的怪獸的卡名當作「真紅眼黑龍」。\u000a\u000a※真紅眼融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6178850,'格鬥精神',unistr('裝備怪獸的攻擊力上升對手場上的怪獸數量×300。\u000a裝備怪獸被戰鬥破壞的場合，可以將此卡破壞作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6180710,'夢鯊',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上的怪獸，不存在的場合或只有水屬性怪獸的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡1回合只有1次不會被戰鬥破壞。\u000a③：此卡在墓地存在，給予我方傷害的效果發動時可以發動。此卡特殊召喚，那個效果讓我方受到的傷害變成0。此效果特殊召喚的此卡守備力下降1000，從場上離開的場合被除外。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6182103,'究極體突變魔獸',unistr('等級8以上的「突變魔」怪獸×3\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：卡的效果發動時，從我方的手牌、墓地以及我方場上的表側表示的卡之中，將1張和那張卡相同種類（怪獸、魔法、陷阱）的「突變魔」卡片除外可以發動。那個發動無效並除外。\u000a②：融合召喚的此卡被對手破壞的場合可以發動。被除外的我方的「突變魔」卡片3種（怪獸、魔法、陷阱）各選最多1張加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6186304,'D-力量',unistr('①：作為此卡的發動時的效果處理，可以從我方的牌組、墓地選1隻「D-HERO 血魔」加入手牌。\u000a②：只要我方場上有「D-HERO 血魔」存在，適用以下效果。\u000a●我方在抽牌階段不能抽牌。\u000a●對手不能將我方場上的卡作為效果的對象。\u000a●我方的怪獸區域的「D-HERO 血魔」的攻擊力上升雙方墓地的怪獸數量×100，不會被對手的效果破壞，在1次戰鬥階段中可以攻擊2次。'),'是否從牌組、墓地選1隻「D-HERO 血魔」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6195332,'超神輝星騎士 星聖 托勒密Ω7',unistr('等級7怪獸×3\u000a「超神輝星騎士 星聖 托勒密Ω7」在我方主要階段2有1次，也能重疊在我方場上的「星聖」、「星騎士」超量怪獸上方來超量召喚。\u000a①：此卡只要我方的墓地、除外狀態的「星騎士」怪獸有7種以上存在，攻擊力、守備力上升2700，不受對手發動的效果影響。\u000a②：我方、對手回合1次，去除此卡的任意數量的超量素材，以那個數量的對手場上的怪獸為對象可以發動。那些怪獸回到牌組。'),'是否在超量怪獸上方重疊來超量召喚？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6203182,'一惜二跳',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以對手墓地1隻怪獸為對象可以發動此卡。那隻怪獸在對手場上效果無效特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸破壞。\u000a②：裝備怪獸不能攻擊，不會成為攻擊對象。\u000a③：裝備怪獸成為融合、同步、超量、連結召喚的素材讓此卡被送去墓地的場合可以發動。得到融合、同步、超量、連結召喚的那隻怪獸的控制權。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6205579,'寄生結融者',unistr('此卡只能在此卡的①效果適用的場合作為融合素材。\u000a①：此卡可以代替在融合怪獸卡有記載卡名的1隻融合素材怪獸。此時其他的融合素材怪獸必須是正規的卡。\u000a②：此卡特殊召喚成功的場合可以發動。融合怪獸卡決定的包含此卡的融合素材怪獸從我方場上送去墓地，從額外牌組融合召喚那1隻融合怪獸。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6214163,'雙重提鉤',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：捨棄1張手牌，以我方墓地最多2隻怪獸為對象可以發動此卡。那些怪獸特殊召喚。對象怪獸從場上離開時此卡破壞。此卡從場上離開時對象怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6214884,'暗黑界的狂王 布隆','①：此卡給予對手戰鬥傷害時可以發動。選1張我方的手牌捨棄。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6218704,'霸王天龍 異色眼弧光龍',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方的靈擺區域有2張卡存在的場合可以發動。此卡特殊召喚。那之後，以下可以適用。\u000a●我方的靈擺區域1張卡回到牌組。回到我方的額外牌組的場合，隨後可以將那隻怪獸無視召喚條件特殊召喚。\u000a【怪獸效果】\u000a龍族的融合、同步、超量、靈擺怪獸各1隻合計4隻\u000a這個卡名在規則上當作「霸王龍 札克」。額外牌組的裡側的此卡只能用融合召喚或以下方法特殊召喚。\u000a●將我方場上1隻闇屬性、等級12的「霸王龍 札克」解放，可以特殊召喚。\u000a①：此卡從額外牌組特殊召喚的場合可以發動。從牌組將1隻靈擺怪獸在我方的靈擺區域放置。\u000a②：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','是否選我方的靈擺區域1張卡回到牌組？','是否將那隻怪獸無視召喚條件特殊召喚？','效果1','效果2','','','','','','','','','','','');
INSERT INTO texts VALUES(6218705,'霸王天龍 異色眼弧光龍',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方的靈擺區域有2張卡存在的場合可以發動。此卡特殊召喚。那之後，以下可以適用。\u000a●我方的靈擺區域1張卡回到牌組。回到我方的額外牌組的場合，隨後可以將那隻怪獸無視召喚條件特殊召喚。\u000a【怪獸效果】\u000a龍族的融合、同步、超量、靈擺怪獸各1隻合計4隻\u000a這個卡名在規則上當作「霸王龍 札克」。額外牌組的裡側的此卡只能用融合召喚或以下方法特殊召喚。\u000a●將我方場上1隻闇屬性、等級12的「霸王龍 札克」解放，可以特殊召喚。\u000a①：此卡從額外牌組特殊召喚的場合可以發動。從牌組將1隻靈擺怪獸在我方的靈擺區域放置。\u000a②：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','是否選我方的靈擺區域1張卡回到牌組？','是否將那隻怪獸無視召喚條件特殊召喚？','效果1','效果2','','','','','','','','','','','');
INSERT INTO texts VALUES(6247535,'槍管上膛超充龍',unistr('龍族、闇屬性等級4怪獸×2\u000a①：超量召喚的此卡不會成為其他怪獸的效果的對象。\u000a②：1回合1次，去除此卡的1個超量素材，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力、守備力下降600。那之後，可以從我方墓地選1隻「槍管」怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段除外。此效果的發動後，直到回合結束時我方不能將怪獸特殊召喚，不能直接攻擊。'),'效果2','是否特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6256844,'真次世代渦輪','①：此卡召喚時可以發動。從牌組將1隻等級1的「次世代」怪獸加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6260554,'彈幕迴避','將我方場上的「幻獸機衍生物」全部解放可以發動。效果怪獸的效果、魔法、陷阱卡的發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6260560,'炎魔刃 雷瓦汀',unistr('炎屬性怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，將我方場上1隻其他的炎屬性怪獸解放，以我方墓地1隻原等級低於那隻怪獸且原種族相同的炎屬性怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a②：我方的魔法與陷阱區域的裡側表示卡被對手的效果破壞的場合，可以將場上的此卡除外作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6276588,'機偶忍者 九一九',unistr('此卡可以攻擊的場合必須攻擊。\u000a場上表側表示存在的此卡被選擇作為攻擊對象時，此卡的表示形式變更。\u000a此卡戰鬥破壞對手怪獸送去墓地時，選擇我方墓地的1隻等級4以下的「機偶」怪獸表側守備表示特殊召喚。'),'表示形式變更','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6278008,'星宵龍轉',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以場上1隻融合、同步、超量、連結怪獸為對象可以發動。那隻表側表示怪獸回到額外牌組。那之後，可以依照回去的怪獸種類（融合、同步、超量、連結）將1隻以下怪獸從我方、對手的墓地往我方場上特殊召喚。\u000a●融合：和回去的怪獸相同屬性的怪獸\u000a●同步：等級低於回去的怪獸的怪獸\u000a●超量：等級數值和回去的怪獸的階級相同的怪獸\u000a●連結：和回去的怪獸相同種族的怪獸'),'效果1','是否特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6283472,'無形噬菌體 傲慢',unistr('【靈擺效果】\u000a此卡的控制者在每次我方準備階段解放我方場上的1隻怪獸，或不解放讓此卡破壞。\u000a①：只要我方場上有「無形噬菌體」怪獸存在，雙方受到的效果傷害變成0。\u000a【怪獸效果】\u000a①：只要靈擺召喚、反轉過的此卡在怪獸區域存在，雙方除了「無形噬菌體」怪獸以外不能從額外牌組特殊召喚。'),'是否解放怪獸維持此卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6284176,'六花聖 花簪劍菊',unistr('等級6怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：怪獸被解放的場合，去除此卡的1個超量素材，以我方或對手的墓地1隻怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸效果無效化，變成植物族。\u000a②：我方場上的植物族怪獸被效果破壞的場合，可以將我方的手牌、場上1隻植物族怪獸解放作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6285791,'邪惡寄生蠕蟲','①：我方結束階段發動。場上的表側表示的此卡回到持有者的手牌。','回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6297941,'強盜鼠','奸詐狡猾的老鼠。使用左手的大鉤爪進行攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6309986,'閃爍五星',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的怪獸只有等級5怪獸1隻的場合，將那隻怪獸解放可以發動。從我方的手牌、牌組、墓地選「栗子巴」「栗子比」「栗子卜」「栗子貝」「栗子球」各1隻特殊召喚。此效果特殊召喚的怪獸不能為了上級召喚而解放。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6311717,'占卜魔女 小光',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：抽到此卡時，向對手展示此卡可以發動。此卡從手牌特殊召喚。\u000a②：此卡從手牌特殊召喚成功的場合，以我方場上1隻怪獸為對象可以發動。那隻怪獸送去墓地，從牌組將1隻魔法使族、等級1怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6320631,'核成岩石','此卡被戰鬥破壞送去墓地時，可以從牌組將1張「核成的鋼核」或1隻等級4以下的「核成」怪獸加入手牌。','從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6325660,'霆主王的閃光',unistr('這個卡名的卡在1回合只能發動1張。對手已發動手牌、墓地的怪獸的效果的回合，此卡也能從手牌發動。\u000a①：以對手場上1隻怪獸為對象可以發動。那隻怪獸除外。我方墓地沒有陷阱卡存在的場合，隨後對手可以從自身的手牌將1隻怪獸特殊召喚。此卡從手牌發動的場合，發動後，這次決鬥中我方不能發動地、水、炎、風屬性怪獸的效果。\u000a\u000a※霆王的閃光'),'效果1','適用「霆主王的閃光」的效果從手牌發動','是否從自身手牌特殊召喚？','「霆主王的閃光」的效果1適用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(6327734,'珠之御巫 狐理',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：此卡沒有裝備裝備卡的場合，此卡的戰鬥產生給我方的戰鬥傷害變成0，已裝備的場合，此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害由對手代為承受。\u000a②：只要我方場上有裝備卡存在，對手不能將我方場上的「御巫」卡片作為效果的對象。\u000a③：此卡被裝備裝備卡的場合可以發動。從牌組將1張「御巫」陷阱卡加入手牌。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6327735,'珠之御巫 狐理',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：此卡沒有裝備裝備卡的場合，此卡的戰鬥產生給我方的戰鬥傷害變成0，已裝備的場合，此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害由對手代為承受。\u000a②：只要我方場上有裝備卡存在，對手不能將我方場上的「御巫」卡片作為效果的對象。\u000a③：此卡被裝備裝備卡的場合可以發動。從牌組將1張「御巫」陷阱卡加入手牌。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6330307,'DZW-魔裝鵺妖衣',unistr('我方的主要階段，手牌或我方場上的這隻怪獸可以當作裝備卡，選擇我方場上的1隻「CNo.39」怪獸裝備。\u000a此卡當作裝備卡裝備中的場合，裝備怪獸不會被戰鬥破壞。\u000a裝備怪獸的攻擊沒有破壞對手怪獸的傷害步驟結束時，可以將那隻對手怪獸的攻擊力變成0且只有1次可以繼續攻擊相同的怪獸。'),'當作裝備卡','繼續攻擊','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6337436,'連彈的魔術師','只要此卡在場上表側表示存在，每次我方發動通常魔法卡，給予對手400傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6343408,'奇蹟的發掘','①：被除外的我方怪獸有5隻以上存在的場合，以其中3隻為對象可以發動。那些怪獸回到墓地。','回到墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6351147,'交易回滾',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：支付一半生命值，以「交易回滾」以外的對手墓地1張通常陷阱卡為對象可以發動。此效果變成和那張通常陷阱卡發動時的效果相同。\u000a②：將墓地的此卡除外，支付一半生命值，以「交易回滾」以外的我方墓地1張通常陷阱卡為對象可以發動。此效果變成和那張通常陷阱卡發動時的效果相同。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6351548,'曙光的騎士',unistr('場上的此卡被送去墓地的場合，可以從牌組將1隻光屬性怪獸送去墓地。\u000a此卡從牌組送去墓地的場合，選擇我方墓地1隻光屬性怪獸放置在牌組最上方。\u000a「曙光的騎士」的效果1回合只能使用1次。'),'從牌組送去墓地','回到牌組最上方','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6353603,'暗炎星-熊志',unistr('1回合1次，此卡給予對手戰鬥傷害時，可以從牌組選1張「炎舞」魔法卡在我方場上覆蓋。\u000a此外，1回合1次，將我方場上表側表示存在的1張「炎舞」魔法、陷阱卡送去墓地可以發動。選擇場上的1隻怪獸破壞。'),'從牌組覆蓋','破壞怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6355563,'Y-敏捷龍首',unistr('①：此卡特殊召喚的場合可以發動。從我方的手牌、墓地將1隻機械族、光屬性、等級4怪獸當作裝備魔法卡給此卡裝備。這個回合，我方除了光屬性怪獸以外不能從額外牌組特殊召喚。\u000a②：1回合1次，可以發動1個以下效果。\u000a●以我方場上1隻機械族怪獸為對象，將此卡當作裝備魔法卡裝備。裝備怪獸將被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備狀態的此卡特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6357341,'忍之六武','①：我方場上有6隻「六武眾」怪獸存在，且那些屬性全部不同的場合可以發動。跳過下個對手回合。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6361316,'威咖杯！玉露',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡可以發動。從牌組將「威咖杯！玉露」以外的1隻風屬性反轉怪獸加入手牌。那之後，選1張我方的手牌捨棄。\u000a②：此卡反轉的場合，以場上1隻其他的表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。\u000a③：我方、對手回合，以場上1隻裡側守備表示怪獸為對象可以發動。那隻怪獸變成表側攻擊表示。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6367785,'艾爾丁','用手中的杖，使出各種魔法攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368038,'暗黑騎士蓋亞','騎著速度比風還快的馬的騎士。要注意突進攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368039,'暗黑騎士蓋亞','騎著速度比風還快的馬的騎士。要注意突進攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368040,'暗黑騎士蓋亞','騎著速度比風還快的馬的騎士。要注意突進攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6374519,'驚樂園特別秀','①：對手發動以我方場上的「驚樂園」怪獸為對象的魔法、陷阱、怪獸的效果時，以其中1隻我方的「驚樂園」怪獸為對象可以發動。那隻怪獸回到持有者的手牌。那之後，可以從手牌將1隻「驚樂園」怪獸特殊召喚。','效果1','是否從手牌特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6387204,'CNo.6 先史遺產 混沌大西洲巨人',unistr('等級7怪獸×3\u000a①：此卡的效果發動過的回合，對手受到的全部傷害變成0。\u000a②：1回合1次，以對手場上1隻怪獸為對象可以發動。那隻對手怪獸當作攻擊力上升1000的裝備卡給此卡裝備。\u000a③：此卡有「No.6 先史遺產 大西洲巨人」作為超量素材的場合，得到以下效果。\u000a●去除此卡的3個超量素材，將此卡的效果裝備的「No.」怪獸卡全部送去墓地可以發動。對手的生命值變成100。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6390406,'龍破壞之證','①：從我方的牌組、墓地選1隻「爆裂劍士」加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6400512,'司令官','裝備火箭發射器與反坦克火箭的實戰部隊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6417578,'神影依結合',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的手牌、場上的怪獸作為融合素材，將1隻「影依」融合怪獸融合召喚。\u000a\u000a※與神之假身的接觸'),'融合召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6430659,'病毒郵件','1回合1次，以我方場上1隻等級4以下的怪獸可以發動此效果。這個回合，那隻怪獸可以向對手玩家直接攻擊。那隻怪獸在戰鬥階段結束時送去墓地。','直接攻擊','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6438003,'戰華之詭-賈文',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1張永續魔法、永續陷阱卡為對象可以發動。那張卡送去墓地，選場上2隻表側表示怪獸，那些攻擊力直到回合結束時變成一半。\u000a②：對手場上的卡被戰鬥、效果破壞的場合，以「戰華之詭-賈文」以外的我方墓地1張「戰華」卡片為對象可以發動。那張卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6442944,'皇帝海蛇',unistr('「皇帝海蛇」的①方法的特殊召喚1回合只能有1次。\u000a①：對手場上有怪獸存在，我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡用此卡的①方法特殊召喚成功時可以發動。從我方的手牌、墓地選1隻海龍族、等級8怪獸特殊召喚。此效果特殊召喚的怪獸的攻擊力、守備力變成0。\u000a③：特殊召喚的此卡的等級變成4，原攻擊力變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6459419,'亞馬遜轉生術','我方場上表側表示存在的「亞馬遜」怪獸全部破壞。那之後，最多到破壞的數量，可以將我方墓地的等級4以下的「亞馬遜」怪獸表側守備表示特殊召喚。','是否要特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6471156,'演奏人偶',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方墓地將1隻「奇巧人偶」怪獸除外可以發動。我方場上的全部怪獸的等級直到回合結束時變成和除外的怪獸相同等級。\u000a②：我方場上的表側表示的「奇巧人偶」怪獸被戰鬥或對手的效果破壞送去墓地的場合，以被除外的1隻我方的「奇巧人偶」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6480253,'友善犬','此卡被戰鬥破壞送去墓地時，從我方墓地將1張「E.HERO」卡片和1張「融合」加入手牌。','從墓地加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6483224,'半月龍 拉蒂烏斯','對手場上有超量怪獸存在的場合，此卡可以從手牌特殊召喚。用這個方法特殊召喚的此卡的等級變成8。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6494106,'妒絕的咒眼',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「咒眼」怪獸存在的場合，以場上1隻怪獸為對象可以發動。那隻怪獸回到持有者的手牌。我方的魔法與陷阱區域有「塞勒涅的咒眼」存在的場合，此效果的對象可以變成2隻。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6498706,'融合派兵',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a①：向對手展示額外牌組的1隻融合怪獸，從手牌、牌組選1隻在那隻怪獸有記載卡名的融合素材怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6498707,'融合派兵',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a①：向對手展示額外牌組的1隻融合怪獸，從手牌、牌組選1隻在那隻怪獸有記載卡名的融合素材怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6500778,'煉金釜-混沌蒸餾釜',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在魔法與陷阱區域存在，送去我方墓地的卡不去墓地而是除外。\u000a②：可以從以下效果選擇1個發動。\u000a●除了「煉金釜-混沌蒸餾釜」以外，從牌組將1張「宏觀宇宙」或記載那個卡名的卡加入手牌。\u000a●場上有「宏觀宇宙」存在的場合，將魔法與陷阱區域的表側表示的此卡除外可以發動。從牌組將1隻攻擊力?的光屬性怪獸加入手牌。'),'●檢索「宏觀宇宙」','●檢索攻擊力?的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6511113,'芙蕾西亞的蟲惑魔',unistr('等級4怪獸×2\u000a①：持有超量素材的此卡不受陷阱卡的效果影響。\u000a②：只要此卡在怪獸區域存在，「芙蕾西亞的蟲惑魔」以外的我方場上的「蟲惑魔」怪獸不會被戰鬥、效果破壞，對手不能將其作為效果的對象。\u000a③：我方、對手回合1次，去除此卡的1個超量素材，從牌組將1張「空洞」通常陷阱卡或「落穴」通常陷阱卡送去墓地可以發動。此效果變成和那張陷阱卡發動時的效果相同。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6540606,'水靈術-「葵」','①：將我方場上1隻水屬性怪獸解放可以發動。確認對手的手牌，選其中1張卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6544078,'伊弉凪',unistr('此卡可以將手牌的1隻靈魂怪獸除外，從手牌特殊召喚。\u000a只要此卡在場上表側表示存在，我方場上的靈魂怪獸在結束階段回到手牌的效果可以不發動。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6547248,'小丑戲幫『新加入』',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方、對手的準備階段可以發動。我方的墓地、除外狀態的3張「小丑戲幫」卡片回到牌組。那之後，我方抽1張卡。\u000a②：我方將怪獸上級召喚的場合，最多到為了那次上級召喚而解放的怪獸數量，以場上的其他的魔法、陷阱卡為對象可以發動。那些卡破壞。\u000a③：此卡從場上以外送去墓地的場合可以發動。此卡在我方場上表側表示放置。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6552938,'RR-方向舵林鴞',unistr('①：此卡召喚成功的場合，或用「RR-」卡片的效果從手牌特殊召喚成功的場合可以發動。給予對手600傷害。\u000a②：以此卡為攻擊對象的對手怪獸的攻擊宣言時可以發動。從手牌將最多2隻「RR-」怪獸特殊召喚。這個回合，對手不能選擇此效果特殊召喚的怪獸作為攻擊對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6552971,'邂逅－A.i.－',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：向對手展示手牌、額外牌組的1隻攻擊力2300的電子界族怪獸，從牌組將1隻和那隻怪獸屬性相同的「@伊格尼斯者」怪獸加入手牌。發動後，這個回合中我方沒有將此效果展示的怪獸或那些同名怪獸特殊召喚成功的場合，在結束階段我方受到2300傷害。此卡的發動後，直到回合結束時我方不能發動電子界族以外的怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6556178,'槍管再上膛',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地1隻「槍彈」怪獸為對象可以發動此卡。那隻怪獸特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸除外。\u000a②：裝備怪獸被破壞讓此卡被送去墓地的場合可以發動。我方抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6556909,'真紅眼之魂',unistr('這個卡名的②效果1回合只能使用1次，③效果在決鬥中只能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「真紅眼黑龍」。\u000a②：對手將怪獸特殊召喚的場合，將手牌、場上的此卡送去墓地可以發動。從手牌、牌組將「真紅眼之魂」以外的1隻「真紅眼」怪獸特殊召喚。\u000a③：我方、對手回合，以我方場上1隻「真紅眼黑龍」為對象可以發動。給予對手那隻怪獸的原攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6560411,'黑破滅薔薇龍',unistr('植物族協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：每次對手發動怪獸的效果，給予對手600傷害，對手場上的全部怪獸的攻擊力下降600。\u000a②：我方、對手的主要階段，將此卡解放可以發動。從額外牌組將1隻「黑薔薇龍」當作同步召喚特殊召喚。\u000a③：將墓地的此卡除外可以發動。從我方墓地將1隻等級4以下的植物族協調特殊召喚。'),'','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6568731,'極冰獸 冰山一角鯨',unistr('協調+協調以外的水屬性怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：每次我方場上的其他怪獸被對手怪獸的攻擊或對手的效果破壞發動。給予對手600傷害。\u000a②：我方場上有其他怪獸存在，我方、對手的戰鬥階段中，對手發動魔法、陷阱、怪獸的效果時可以發動。那個效果無效並破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6579928,'影六武眾-木猿',unistr('①：此卡特殊召喚成功時可以發動。從牌組選1隻我方場上存在的屬性以外的「六武眾」怪獸加入手牌。\u000a②：只有我方場上的1隻「六武眾」怪獸被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6588580,'炎熱次世代',unistr('「次世代控制者」+協調以外的炎屬性怪獸1隻以上\u000a①：此卡的攻擊力上升我方墓地的炎屬性怪獸數量×200。\u000a②：此卡戰鬥破壞對手怪獸的場合發動。給予對手相當於我方墓地的「次世代」怪獸數量×200傷害。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6589707,'地中界的災厄',unistr('①：我方場上的裡側守備表示怪獸不會成為對手的效果的對象。\u000a②：只要此卡在魔法與陷阱區域存在，此卡表側表示存在期間反轉過的我方場上的怪獸的攻擊力、守備力上升1500。\u000a③：魔法與陷阱區域的表側表示的此卡被對手的效果破壞的場合，以我方墓地1隻怪獸為對象可以發動。那隻怪獸裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6595475,'擬聲連攜',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將1張手牌送去墓地可以發動。從牌組將以下怪獸之中各1隻，合計最多2隻加入手牌。\u000a●「刷啦啦」怪獸\u000a●「我我我」怪獸\u000a●「隆隆隆」怪獸\u000a●「怒怒怒」怪獸'),'是否將第2種怪獸加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6602300,'重爆擊禽 炸彈不死魔鳥',unistr('機械族怪獸+炎族怪獸\u000a我方的主要階段時，可以給予對手相當於場上的卡片數量×300傷害。此效果發動的整回合中，此卡不能攻擊。這個效果1回合只能使用1次。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6609736,'能龐克 鹿角仙音',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的1隻其他的「龐克」怪獸可以發動。手牌的此卡和展示的怪獸之中，其中1隻特殊召喚，另1隻送去墓地。\u000a②：此卡從場上送去墓地的場合，以等級5怪獸以外的我方墓地1隻「龐克」怪獸為對象可以發動。那隻怪獸特殊召喚。這個回合，我方不能將「能龐克 鹿角仙音」特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6614221,'霧之王',unistr('此卡召喚的場合，可以解放1隻怪獸或不用解放。\u000a此卡的攻擊力變成上級召喚時解放的怪獸的原攻擊力合計數值。\u000a只要此卡在場上表側表示存在，雙方不能將卡解放。'),'解放1隻怪獸召喚','不解放的召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6616912,'時械神 加百利恩',unistr('此卡不能從牌組特殊召喚。\u000a①：我方場上沒有怪獸存在的場合，此卡可以不用解放來召喚。\u000a②：此卡不會被戰鬥、效果破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：此卡進行戰鬥的戰鬥階段結束時發動。對手場上的卡全部回到持有者的牌組。那之後，對手依照回到自身牌組的數量抽牌。\u000a④：我方準備階段發動。此卡回到持有者的牌組。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6622715,'編碼語者',unistr('電子界族怪獸2隻以上\u000a①：1回合1次，此卡指向的我方怪獸和攻擊力高於那隻怪獸的對手怪獸進行戰鬥的傷害計算前可以發動。那隻我方怪獸不會被那次戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。那次傷害計算後，選此卡或此卡指向的1隻我方怪獸，那個攻擊力直到回合結束時上升那隻進行戰鬥的對手怪獸的攻擊力數值。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6625096,'鰤子姬',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功時，將此卡除外可以發動。從牌組將「鰤子姬」以外的1隻等級4以下的魚族怪獸特殊召喚。'),'從牌組特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6628343,'開闢的騎士',unistr('「開闢的騎士」的①②效果1回合各能使用1次。\u000a①：使用此卡儀式召喚的「混沌士兵」怪獸得到以下效果。\u000a●1回合1次，以對手場上1隻怪獸為對象可以發動。那隻怪獸除外。\u000a●此卡戰鬥破壞對手怪獸送去墓地時可以發動。此卡只有1次可以繼續攻擊。\u000a②：墓地的此卡被除外的場合可以發動。從牌組將1張儀式魔法卡加入手牌。'),'●對手場上的怪獸除外（開闢的騎士）','●繼續攻擊1次（開闢的騎士）','「開闢的騎士」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6631034,'冰霜龍','托遲鈍的神經和感性的福，雖然被冰雪覆蓋卻擁有冰河期也能熬過的威脅性生命力，耐寒能力異常強大。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6636319,'Evil★Twin 姬絲吉爾・成交',unistr('「姬絲吉爾」怪獸1隻\u000a我方1回合只能連結召喚1次「Evil★Twin 姬絲吉爾・成交」。\u000a這個卡名的效果1回合只能使用1次。\u000a①：從牌組、額外牌組將1隻「璃拉」怪獸送去墓地可以發動。這個回合中，適用以下效果。\u000a●每次對手連鎖我方的「姬絲吉爾」怪獸或「璃拉」怪獸的效果的發動來發動效果，我方抽1張卡。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6637331,'淵獸 德魯伊亞龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方或對手的墓地1隻光、闇屬性怪獸為對象可以發動（對手場上有怪獸存在的場合，此效果在對手回合也能發動）。那隻怪獸除外，此卡從手牌特殊召喚。\u000a②：此卡從場上送去墓地的場合，以對手場上1隻特殊召喚的怪獸為對象可以發動。那隻怪獸送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6659193,'娛樂法師 鞦韆大魔術師',unistr('魔法使族等級5怪獸×2\u000a①：持有超量素材的此卡不會被戰鬥、效果破壞。\u000a②：只要此卡在怪獸區域存在，我方受到的效果傷害由對手代為承受（此效果在1回合可以適用的次數最多到此卡的超量素材數量）。\u000a③：此卡有「娛樂法師 鞦韆魔術師」作為超量素材的場合，得到以下效果。\u000a●去除此卡的1個超量素材可以發動。這個回合，此卡在1次戰鬥階段中可以攻擊3次。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6691855,'帶鎖鏈的尖盾','發動後此卡當作攻擊力上升500的裝備卡給場上的1隻怪獸裝備。裝備怪獸以守備表示進行戰鬥的場合，裝備怪獸的守備力只在傷害計算時上升那個攻擊力數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6696168,'慶典氣球',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a②：只要此卡在怪獸區域存在，每次我方或對手的怪獸攻擊宣言，此卡的攻擊力上升1000。\u000a③：我方主要階段可以發動。此卡的攻擊力下降5000，場上的其他卡全部破壞。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6713443,'極炎舞-「星斗」','將我方墓地7張「炎舞」魔法、陷阱卡除外可以發動。從我方墓地盡可能特殊召喚「炎星」怪獸。那之後，最多到此效果特殊召喚的怪獸數量，可以從牌組將「極炎舞-「星斗」」以外的「炎舞」魔法、陷阱卡在我方場上覆蓋。','是否從牌組選擇「炎舞」魔法、陷阱卡覆蓋在我方場上？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6728559,'大星義初始龍',unistr('此卡不能通常召喚。從我方的場上（表側表示）、墓地將3隻屬性不同的怪獸除外可以特殊召喚。這個卡名的②效果1回合只能使用1次。\u000a①：場上的此卡不會被效果破壞。\u000a②：宣言1個場上的怪獸的屬性可以發動。場上的宣言屬性的怪獸全部破壞。直到下個回合結束時，雙方不能將宣言屬性的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6733059,'死靈的巢穴','可以藉由將我方墓地任意數量的怪獸除外，選場上1隻等級和那個數量相同的怪獸破壞。','是否現在發動此卡的效果？','破壞','請選擇要除外的怪獸數量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6740720,'聖夜龍','以神聖的火焰燒盡惡人，有著神聖力量的龍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6763530,'烙印追放',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻「死獄鄉」怪獸或等級8以上的融合怪獸為對象可以發動。那隻怪獸特殊召喚。那之後，可以適用以下效果。\u000a●我方、對手場上的怪獸作為融合素材除外，將1隻等級8以上的融合怪獸融合召喚。'),'是否適用以下效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6764709,'F.A. 暗冥大師',unistr('此卡不能通常召喚。場上有等級7以上的「F.A.」怪獸存在，我方的怪獸區域沒有「F.A. 暗冥大師」存在的場合可以特殊召喚。\u000a①：此卡的攻擊力上升此卡的等級×300。\u000a②：「F.A.」魔法、陷阱卡的效果發動的場合可以發動（傷害步驟也能發動）。此卡的等級上升1。\u000a③：1回合1次，以場上1張卡為對象可以發動。此卡的等級下降3，那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6766208,'DDD疾風大王 決策亞歷山大',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：場上有3隻以上「DDD」怪獸存在的場合，此卡的攻擊力上升3000。\u000a②：此卡在怪獸區域存在，我方場上有此卡以外的「DD」怪獸召喚、特殊召喚的場合，以我方墓地1隻「DD」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6767771,'珠淚哀歌的弦聲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：場上有怪獸召喚、特殊召喚的場合，如果我方場上有「珠淚哀歌」怪獸或「維薩斯-星霜」存在可以發動。從我方牌組上方將3張卡送去墓地。這個回合，對手場上的怪獸的攻擊力下降500。\u000a②：此卡被效果送去墓地的場合可以發動。從牌組將1張「珠淚哀歌」陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6772168,'召喚獸 俄刻阿諾斯',unistr('「阿萊斯特」怪獸+闇、水屬性怪獸\u000a這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在主要怪獸區域存在，對手怪獸不能選擇其他怪獸作為攻擊對象。\u000a②：只要此卡在額外怪獸區域存在，送去對手墓地的怪獸不去墓地而是除外。\u000a③：將墓地的此卡除外，以我方場上1隻融合怪獸為對象可以發動。這個回合，那隻怪獸可以直接攻擊。'),'','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6783559,'自爆蟻',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡反轉的場合發動。雙方受到1000傷害。\u000a②：此卡被戰鬥、效果破壞送去墓地的場合發動。給予對手1000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6795211,'顯形','①：1回合1次，只有對手場上有怪獸存在的場合，支付800生命值可以發動。從手牌將1隻超能族怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6798031,'雷熱渦爐 交錯',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方不能超量召喚同名卡在我方場上存在的怪獸。\u000a②：以「雷熱渦爐 交錯」以外的我方墓地2張「雷熱渦爐」卡片為對象可以發動。那些卡以喜歡的順序回到牌組下方。那之後，我方抽1張卡。\u000a③：1回合1次，對手發動的怪獸的效果的處理時，我方可以去除我方場上的「雷熱渦爐」超量怪獸的1個超量素材。那個場合，那個效果無效化。'),'N/A','效果2','效果3','是否使用「雷熱渦爐 交錯」的效果3無效？','已使用效果3','','','','','','','','','','','');
INSERT INTO texts VALUES(6799227,'半反擊','我方場上的怪獸被攻擊時，在那次傷害計算時可以發動。選擇那隻成為攻擊對象的我方怪獸，其攻擊力直到回合結束時上升攻擊怪獸的原攻擊力的一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6812770,'娛樂法師 杯子戲法師',unistr('【靈擺效果】\u000a這個卡名的①②靈擺效果1回合各能使用1次。\u000a①：以我方場上1隻「娛樂法師」超量怪獸為對象可以發動。此卡作為那隻怪獸的超量素材。\u000a②：我方的額外牌組有卡加入的場合可以發動。從我方的額外牌組（表側）將1隻「娛樂法師」靈擺怪獸加入手牌。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，以場上1隻超量怪獸為對象可以發動。去除那隻怪獸的1個超量素材，此卡特殊召喚。那之後，場上1隻超量怪獸的攻擊力下降600。\u000a②：超量素材的此卡為了發動超量怪獸的效果而被去除送去墓地的場合，以我方場上2隻超量怪獸為對象可以發動。其中1隻的1個超量素材作為另1隻的超量素材。'),'靈擺效果1','靈擺效果2','效果1','效果2','請選擇去除超量素材的怪獸','','','','','','','','','','','');
INSERT INTO texts VALUES(6821579,'R.B.沃肯推進器',unistr('機械族怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組將1張「R.B.」魔法卡加入手牌。\u000a②：此卡在額外怪獸區域存在的場合可以發動。從我方的手牌、墓地將1隻「R.B.」怪獸守備表示特殊召喚。那之後，可以將此卡向其他的我方的主要怪獸區域移動。這個回合，我方除了攻擊力1500以下的機械族怪獸以外不能從額外牌組特殊召喚。'),'從牌組加入手牌','特殊召喚','是否移動？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6830480,'黃昏的忍者-下弦',unistr('【靈擺效果】\u000a①：我方除了「忍者」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a②：1回合1次，我方的「忍者」怪獸的攻擊宣言時可以發動。那隻怪獸的攻擊力直到傷害步驟結束時上升1000。\u000a【怪獸效果】\u000a①：解放此卡，以我方場上1隻「忍者」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升800。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6836211,'大皇帝企鵝','①：將此卡解放可以發動。從牌組將「大皇帝企鵝」以外的最多2隻「企鵝」怪獸特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6840573,'巴洛克斯','「殺手貓熊」+「石像鬼」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6849042,'超古代恐獸',unistr('此卡可以解放1隻恐龍族怪獸以表側攻擊表示上級召喚。\u000a①：此卡在怪獸區域存在，恐龍族怪獸從我方墓地特殊召喚時可以發動。我方從牌組抽1張卡。'),'解放1隻恐龍族怪獸召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6850209,'與惡魔的交涉','我方場上的等級8以上的怪獸被送去墓地的回合可以發動。從我方的手牌或牌組將1隻「狂戰死屍龍」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6853254,'復活的福音',unistr('①：以我方墓地1隻等級7、8的龍族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方場上的龍族怪獸被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6855503,'赫灼龍 偽裝',unistr('「死獄鄉」怪獸+光、闇屬性怪獸\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要融合召喚的此卡在怪獸區域存在，對手必須支付600生命值，才能發動卡的效果。\u000a②：我方、對手回合，此卡在墓地存在，對手場上有儀式、融合、同步、超量、連結怪獸其中任何種類存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6859683,'成功機率0%','從對手的融合牌組隨機選2隻融合怪獸送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6890729,'鍵結-DHO',unistr('①：從我方的手牌、墓地讓「氘魔獸」「氫魔獸」「氧魔獸」各1隻回到牌組可以發動。從我方的手牌、墓地選1隻「水魔龍-團簇」特殊召喚。\u000a②：將墓地的此卡除外可以發動。從我方的牌組、墓地選1隻「水魔龍」或「水魔龍-團簇」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6901008,'幻影王 氫騎','①：將我方場上的此卡作為同步素材的場合，可以將此卡當作協調以外的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6903857,'強力破壞者','此卡被對手怪獸的攻擊或卡片效果破壞送去墓地時，選擇對手場上表側表示存在的1張魔法、陷阱卡破壞。此卡攻擊的場合，在傷害步驟結束時變成守備表示。','破壞','變為守備表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6906306,'至鋼之玉 紅青玉',unistr('等級9怪獸×2隻以上\u000a①：依照此卡作為超量素材持有的怪獸的屬性，此卡得到以下效果。\u000a●炎：此卡向攻擊力高於此卡的怪獸攻擊的攻擊宣言時可以發動。此卡的攻擊力直到那個傷害步驟結束時變成2倍。\u000a●水：對手回合1次，以我方場上1張卡為對象可以發動。這個回合，對手發動的以那張卡為對象的效果無效化。\u000a②：此卡被破壞的場合，可以去除此卡的1個超量素材作為代替。'),'●炎：','●水：','「至鋼之玉 紅青玉」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6908161,'蕾禍之鎖蛇巳',unistr('包含昆蟲族、植物族、爬蟲類族怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：對手發動怪獸效果的場合可以發動。這個回合，雙方不能發動手牌的怪獸的效果。\u000a②：此卡在墓地存在的場合，以我方場上1隻昆蟲族、植物族、爬蟲類族怪獸為對象可以發動。那隻怪獸回到牌組最下方，此卡特殊召喚。這個回合，我方除了昆蟲族、植物族、爬蟲類族怪獸以外不能特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6909330,'魂縛門',unistr('我方場上覆蓋的魔法、陷阱卡被效果破壞的回合，我方場上沒有怪獸存在的場合可以發動此卡。\u000a①：我方、對手的主要階段，我方墓地有「Z-ONE」存在，只將1隻攻擊力低於我方的生命值數值的怪獸召喚、反轉召喚、特殊召喚的場合發動。那隻怪獸破壞，我方受到800傷害。那之後，給予對手800傷害。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6917479,'吸血鬼 紅男爵',unistr('①：1回合1次，支付1000生命值，以對手場上1隻怪獸和此卡以外的我方場上1隻「吸血鬼」怪獸為對象可以發動。交換那2隻怪獸的控制權。\u000a②：此卡戰鬥破壞怪獸的戰鬥階段結束時可以發動。那些怪獸從墓地盡可能在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6924874,'神鷹寵物幼龍',unistr('此卡依照「神鷹寵物幼龍」以外的我方場上的「神鷹」怪獸數量得到以下效果。\u000a●1隻以上：只要此卡在場上表側表示存在，對手不能選擇「神鷹寵物幼龍」以外的我方場上的「神鷹」怪獸作為攻擊對象。\u000a●2隻以上：此卡的原本的攻擊力、守備力變成2倍。\u000a●3隻以上：1回合1次，可以選擇對手場上的1張卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6930746,'限界龍 史瓦西','①：對手場上有攻擊力2000以上的怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6958551,'影子卡通',unistr('「影子卡通」在1回合只能發動1張。\u000a①：我方場上有「卡通世界」存在的場合，以對手場上1隻表側表示怪獸為對象可以發動。給予對手那隻表側表示怪獸的攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6958567,'魔女工坊的慶典',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：可以從以下效果選擇1個發動。\u000a●我方場上1隻「魔女工坊」怪獸和對手場上1張卡破壞。\u000a●我方的墓地、除外狀態的魔法使族怪獸作為融合素材回到牌組，將1隻「魔女工坊」融合怪獸融合召喚。\u000a②：我方結束階段，此卡在墓地存在，我方場上有「魔女工坊」怪獸存在的場合可以發動。此卡加入手牌。'),'效果1','效果2','●破壞效果','●融合召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(6967870,'黑蠍-拆除陷阱的克利夫',unistr('①：此卡給予對手戰鬥傷害時，可以從以下效果選擇1個發動。\u000a●以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。\u000a●從對手的牌組上方將2張卡送去墓地。'),'效果1','●破壞場上的魔法、陷阱卡','●對手牌組上方的2張卡送去墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6979239,'樹葉妖精','將此卡裝備的1張裝備卡送去墓地可以發動。給予對手500傷害。','生命值傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6983839,'龍捲龍',unistr('等級4怪獸×2\u000a①：我方、對手回合1次，去除此卡的1個超量素材，以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6990577,'守護龍 安德雷克',unistr('此卡不能通常召喚，只能用卡片效果特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡從手牌、牌組特殊召喚成功的場合可以發動。此卡的原本的攻擊力、守備力直到下個回合結束時變成2倍。\u000a②：此卡從墓地特殊召喚成功的場合，或被除外的此卡特殊召喚成功的場合，以對手場上1隻怪獸為對象可以發動。那隻怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6992184,'靈擺安可',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手主要階段，捨棄1張手牌可以發動。將靈擺怪獸靈擺召喚。這個回合，我方的靈擺區域的卡不能發動效果，不會被我方的卡的效果破壞，在結束階段回到持有者的牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7019529,'空之昆蟲兵','此卡向風屬性怪獸攻擊的場合，傷害步驟期間此卡的攻擊力上升1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7020743,'憤怒小兒',unistr('等級1怪獸×2\u000a①：卡的效果的發動無效的場合可以發動（同一連鎖上最多1次）。將我方以及對手的墓地的卡各最多1張作為此卡的超量素材。\u000a②：依照此卡持有的超量素材數量，此卡得到以下效果。\u000a●1個以上：此卡的攻擊力、守備力上升此卡的超量素材數量×700。\u000a●4個以上：此卡不會被戰鬥、效果破壞。\u000a●8個以上：我方、對手回合，去除此卡的4個超量素材可以發動。場上的卡全部破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7021574,'栗子卜',unistr('這個卡名在規則上也當作「栗子球」卡片。\u000a①：對手怪獸的攻擊宣言時，將此卡從手牌捨棄可以發動。從牌組將「栗子卜」以外的1隻「栗子球」怪獸加入手牌。\u000a②：1回合1次，從手牌捨棄1張陷阱卡，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時下降1500。此效果在對手回合也能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7025445,'強力巨人',unistr('此卡可以從手牌將1隻等級4以下的怪獸送去墓地，從手牌特殊召喚。這個方法特殊召喚的場合，此卡的等級下降從手牌送去墓地的怪獸的等級數值。\u000a此外，此卡進行戰鬥的場合，直到那次傷害步驟結束時我方受到的效果傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7030340,'百機夜工','我方墓地的「變形鬥士」怪獸全部除外。選擇我方場上1隻表側表示的機械族怪獸的攻擊力直到回合結束時上升這個效果除外的數量×200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7044562,'魂之卡',unistr('「魂之卡」在1回合只能發動1張。\u000a①：確認我方牌組。可以從其中將1隻攻擊力、守備力的總和與我方的生命值相同的怪獸加入手牌。'),'是否將1隻怪獸加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7076131,'後繼無人','選擇我方場上表側表示存在的1隻怪獸可以發動。從我方牌組將1張選擇的卡的同名卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7080743,'豪腕特急 礦車洛克',unistr('①：用場上的此卡為素材超量召喚的怪獸得到以下效果。\u000a●這次超量召喚成功的場合發動。此卡的攻擊力上升800。'),'●攻擊力上升800（豪腕特急 礦車洛克）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7084129,'魔術師之杖',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚時可以發動。從牌組將1張記載「黑魔導」的卡名的魔法、陷阱卡加入手牌。\u000a②：此卡在墓地存在的狀態，我方在對手回合發動魔法、陷阱卡的效果的場合，將我方場上1隻魔法使族怪獸解放可以發動。此卡加入手牌。'),'從牌組加入手牌','墓地的此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7089711,'哈尼哈尼','①：此卡反轉的場合，以場上1隻怪獸為對象發動。那隻怪獸回到持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7092142,'激流蘇生',unistr('「激流蘇生」在1回合只能發動1張。\u000a我方場上的水屬性怪獸被戰鬥或效果破壞送去墓地時可以發動。那時被破壞且從場上送去我方墓地的怪獸特殊召喚，給予對手相當於特殊召喚的怪獸數量×500傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7093411,'寶玉獸 青玉天馬',unistr('①：此卡召喚、反轉召喚、特殊召喚成功時可以發動。從我方的手牌、牌組、墓地選1隻「寶玉獸」怪獸當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。\u000a②：表側表示的此卡在怪獸區域被破壞的場合，可以不送去墓地當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。'),'N/A','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7102732,'潔淨憤怒石魔',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。這個回合中，記載「潔淨世界」的卡名的我方怪獸可以直接攻擊。\u000a②：只要此卡在怪獸區域存在，「潔淨世界」的效果對我方不適用。\u000a③：此卡給予對手戰鬥傷害時可以發動。給予對手相當於對手的手牌數量×300傷害。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7127502,'龍魔王 至霸主載靈擺',unistr('【靈擺效果】\u000a①：只要此卡在靈擺區域存在，對手場上的表側表示的靈擺怪獸的效果無效化。\u000a【怪獸效果】\u000a①：此卡和靈擺怪獸進行戰鬥的傷害步驟開始時發動。那隻怪獸和此卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7133305,'生命之水',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上沒有怪獸存在的場合，以我方墓地1隻怪獸為對象可以發動。那隻怪獸攻擊表示特殊召喚。此卡的發動後，直到回合結束時我方不能將此效果特殊召喚的場上的怪獸以外的怪獸的效果發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7142724,'冰水底 離子搖籃',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，可以將我方的墓地、除外狀態的1隻「冰水」怪獸加入手牌。\u000a②：1回合1次，怪獸召喚、特殊召喚的場合，以我方場上1隻水屬性怪獸為對象可以發動。對象怪獸以及對手場上的全部表側表示怪獸的攻擊力直到回合結束時下降對象怪獸的原攻擊力數值。'),'是否選1隻「冰水」怪獸加入手牌？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7150545,'切割鯊',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方場上1隻水屬性怪獸為對象可以發動。從牌組將1隻和那隻怪獸卡名不同且等級相同的魚族怪獸守備表示特殊召喚。此效果特殊召喚的怪獸在這個回合不能發動效果。此效果的發動後，直到回合結束時我方除了超量怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡在水屬性怪獸的超量召喚使用的場合，可以將此卡的等級當作3或5。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7152333,'黑影食屍鬼','1回合1次，在我方的主要階段時可以發動。此卡的攻擊力變成0，從手牌將1隻攻擊力0的「黑影」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7153114,'場地防護罩',unistr('只要此卡在場上存在，雙方不能將場地魔法卡破壞，也不能發動場地魔法卡。\u000a「場地防護罩」在我方場上只能有1張表側表示存在。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7161742,'捕食植物 冬蟲夏草','①：我方準備階段，將墓地的此卡除外，以我方墓地2隻等級4以下的「捕食植物」怪獸為對象可以發動。那些怪獸特殊召喚。此效果的發動後，直到回合結束時我方不能通常召喚，除了融合怪獸以外不能特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7165085,'誘餌人形','選擇魔法與陷阱區域覆蓋的1張卡可以發動。翻開選擇的卡確認，如果那張卡是陷阱卡，將其強制發動。如果發動時機錯誤，那個效果無效並破壞。如果那張卡不是陷阱卡，將其回復原狀。此卡發動後不送去墓地而是回到牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7166709,'鐵絃的犧打職人',unistr('①：向對手展示手牌的1隻等級5以上的怪獸，可以從以下效果選擇1個發動（這個卡名以下的效果1回合各能選擇1次）。此效果的發動後，這個回合中只要我方沒有將展示的怪獸或原卡名和那隻怪獸相同的怪獸召喚成功，這個回合的結束階段我方失去1000生命值。\u000a●此卡從手牌特殊召喚。\u000a●墓地的此卡加入手牌。\u000a●墓地的此卡除外，從我方墓地將1隻等級5以上的怪獸加入手牌。'),'效果1','●從手牌特殊召喚','●加入手牌','●此卡除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(7171149,'卡通古代機械齒輪巨人',unistr('①：此卡在召喚、反轉召喚、特殊召喚的回合不能攻擊。\u000a②：我方場上有「卡通世界」存在，對手場上沒有卡通怪獸存在的場合，此卡可以直接攻擊。\u000a③：此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a④：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7180418,'魔導鎧甲 艾古賽',unistr('此卡的控制者在每次雙方的準備階段去除我方場上的1個魔力計數器，或不去除讓此卡破壞。\u000a此卡在召喚、反轉召喚、特殊召喚的回合不能攻擊。'),'是否去除1個魔力計數器維持此卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7183277,'光道德魯伊 奧庫斯',unistr('只要此卡在場上表側表示存在，雙方玩家不能將「光道」怪獸作為魔法、陷阱、效果怪獸的效果的對象。\u000a我方結束階段發動。從我方牌組上方將2張卡送去墓地。'),'牌組上方送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7194917,'No.52 鑽石蟹王',unistr('等級4怪獸×2\u000a①：「No.52 鑽石蟹王」在我方場上只能有1隻表側表示存在。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。直到回合結束時，此卡的守備力變成0，攻擊力變成3000。\u000a③：此卡攻擊的場合，戰鬥階段結束時變成守備表示。\u000a④：沒有超量素材的此卡被攻擊的傷害步驟結束時，此卡變成攻擊表示。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7198399,'巧克力魔導女孩',unistr('①：1回合1次，從手牌捨棄1隻魔法使族怪獸可以發動。我方從牌組抽1張卡。\u000a②：1回合1次，此卡被選擇作為攻擊對象的場合，以「巧克力魔導女孩」以外的我方墓地1隻魔法使族怪獸為對象可以發動。那隻怪獸特殊召喚。那之後，攻擊對象轉移到那隻怪獸，攻擊怪獸的攻擊力變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7200041,'金屬砲擊者','此卡召喚成功時，給此卡放置2個計數器。這個效果給此卡放置的計數器每有1個，此卡的攻擊力就上升800。此卡被其他卡的效果破壞的場合，去除此卡的1個計數器作為代替。','放置計數器','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7206349,'春化精的花盛',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有5隻以上地屬性怪獸存在，我方場上的怪獸的攻擊力上升1000。\u000a②：從我方的手牌、墓地將1張「春化精與花蕾」除外可以發動。從牌組將1隻「春化精的女神 薇拉」特殊召喚。\u000a③：從我方墓地有「春化精」怪獸特殊召喚的場合，以我方或對手的場上、墓地1隻怪獸為對象可以發動。那隻怪獸回到持有者的手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7225792,'蒙拉瓦斯','進化過的野獸。力量有相當的提高。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7236721,'恐懼爪牙 界放的肆世壞',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上的「恐懼爪牙」連結怪獸和「維薩斯-星霜」不會成為對手的效果對象，不會被對手的效果破壞。\u000a②：我方的「恐懼爪牙」連結怪獸或「維薩斯-星霜」戰鬥破壞的怪獸不去墓地而是除外。\u000a③：將我方的場上、墓地1隻「恐懼爪牙」連結怪獸除外，以對手場上1張卡為對象可以發動。該卡破壞。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7241272,'獄炎的詛咒之龍',unistr('①：此卡召喚、特殊召喚成功的場合，以場上的1張場地魔法卡為對象可以發動。那張卡破壞。\u000a②：1回合1次，我方主要階段可以發動。融合怪獸卡決定的包含此卡的融合素材怪獸從我方場上送去墓地，從額外牌組融合召喚那1隻融合怪獸。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7243511,'無尾熊海獺無尾熊',unistr('「無尾熊海獺」+「海獺無尾熊」\u000a從手牌將1隻獸族怪獸送去墓地，選擇對手場上的1隻怪獸可以發動。選擇的怪獸破壞。'),'破壞怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7264861,'無限地獄猛獸','我方的手牌是0張的場合，此卡得到以下效果。此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7268133,'娛樂夥伴 生命劍士',unistr('①：對手的生命值回復時可以發動。此卡從手牌特殊召喚。此效果特殊召喚的此卡的攻擊力變成此時對手回復的數值。\u000a②：將此卡解放，以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升1000。'),'此卡特殊召喚','攻擊力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7279373,'魔界劇團-閃爍小明星',unistr('【靈擺效果】\u000a①：我方除了「魔界劇團」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a②：1回合1次，以我方場上1隻「魔界劇團」怪獸為對象可以發動。這個回合，那隻怪獸在1次戰鬥階段中可以向怪獸攻擊最多3次，對象怪獸以外的我方怪獸不能攻擊。\u000a【怪獸效果】\u000a①：此卡在我方回合不會被戰鬥破壞，在1次戰鬥階段中可以向怪獸攻擊最多3次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7291576,'影六武眾-玄蕃',unistr('①：此卡召喚成功時，以被除外的1隻我方的「六武眾」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：只有我方場上的1隻「六武眾」怪獸被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'除外怪獸加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7293697,'完美卡通世界',unistr('這個卡名的②效果1回合可以使用最多3次。\u000a①：此卡只要在場地區域存在，卡名當作「卡通世界」。\u000a②：1回合1次，我方主要階段可以發動。從牌組將1張「卡通」卡片或記載那個卡名的卡加入手牌。\u000a③：其他卡發動的效果適用之際，可以將我方場上1隻卡通怪獸直到那個效果處理後除外（這個回合，這個卡名的這個效果不能將原卡名相同的怪獸除外）。'),'','效果2','','是否將1隻怪獸直到效果處理後除外？','','','','','','','','','','','','');
INSERT INTO texts VALUES(7304544,'大植然鳳梨',unistr('只要此卡在場上表側表示存在，我方場上的表側表示怪獸全部變成植物族。\u000a我方準備階段，此卡在墓地存在，我方場上沒有魔法、陷阱卡存在的場合，此卡可以從墓地特殊召喚。此效果只能在我方場上沒有「大植然鳳梨」表側表示存在，且我方墓地沒有植物族、獸族以外的怪獸存在的場合發動。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7305060,'無形噬菌體 貪婪',unistr('【靈擺效果】\u000a此卡的控制者在每次我方準備階段解放我方場上的1隻怪獸，或不解放讓此卡破壞。\u000a①：只要我方場上有「無形噬菌體」怪獸存在，雙方不能發動「無形噬菌體」卡片以外的陷阱卡的效果。\u000a【怪獸效果】\u000a①：只要靈擺召喚、反轉過的此卡在怪獸區域存在，雙方除了「無形噬菌體」怪獸以外不能從額外牌組特殊召喚。'),'是否解放怪獸維持此卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7320132,'極星寶 至高王座',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從牌組將1隻「極星」怪獸特殊召喚。只要此效果特殊召喚的怪獸表側表示存在，我方除了「極神」怪獸以外不能從額外牌組特殊召喚。\u000a②：將墓地的此卡除外可以發動。從牌組將1隻「極星」怪獸加入手牌。那之後，選1張手牌回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7336745,'恐啡肽狂龍無傷',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「恐啡肽狂龍」卡片存在，怪獸的效果發動時，支付一半生命值可以發動。那個發動無效並破壞。這個回合，我方受到的戰鬥傷害變成那時我方的生命值的一半的數值。\u000a②：我方的生命值是2000以下，我方將要受到戰鬥傷害的傷害計算時，將墓地的此卡除外可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7337976,'煉獄的災天',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：捨棄1張手牌可以發動。從牌組將1隻惡魔族怪獸送去墓地。\u000a②：將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。最多到從額外牌組特殊召喚的對手場上的怪獸數量，從手牌、牌組將「獄火機」怪獸送去墓地（同名卡最多1張）。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7359741,'機械獵人','聽從機械王的命令，在抓住目標前都會緊追不捨的獵捕。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7369217,'金屬化寄生生物-月之衣',unistr('1回合1次，在我方的主要階段，場上的此卡可以當作裝備卡給我方場上的表側表示怪獸裝備，或解除裝備表側攻擊表示特殊召喚。\u000a裝備怪獸不受對手的魔法卡的效果影響。（1隻怪獸最多可以裝備1張聯合。裝備怪獸被戰鬥破壞的場合，將此卡破壞作為代替。）'),'裝備','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7373632,'神的進化',unistr('此卡的發動和效果不會被無效化。\u000a①：選我方場上1隻原種族是幻神獸族的怪獸或原卡名是「邪神 阿巴塔」「邪神 恐懼根源」「邪神 伊雷薩」的怪獸（不能選已經適用「神的進化」的效果的怪獸）。那隻怪獸的攻擊力、守備力上升1000，自身的效果的發動以及那些發動的效果不會被無效化，得到以下效果。\u000a●此卡的攻擊宣言時可以發動。對手必須將自身場上1隻怪獸送去墓地。'),'「神的進化」的效果適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7375867,'星宿龍 姆露露',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「星宿」融合怪獸融合召喚。這個回合，我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡成為融合召喚的素材送去墓地的場合可以發動。從牌組將1張「星宿」魔法、陷阱卡在我方場上覆蓋。那之後，可以將對手場上1隻表側表示怪獸的效果無效。'),'效果1','效果2','是否將1隻怪獸的效果無效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7382007,'剛鬼 酋長食人魔',unistr('「剛鬼」怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：「剛鬼」怪獸用抽牌以外的方法從牌組加入我方的手牌的場合可以發動。從手牌將任意數量的「剛鬼」怪獸特殊召喚（相同等級最多1隻）。只要此效果特殊召喚的怪獸在我方場上表側表示存在，我方除了「剛鬼」怪獸以外不能特殊召喚。\u000a②：我方主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「剛鬼」融合怪獸融合召喚。'),'效果1','效果2','「剛鬼 酋長食人魔」的效果1特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7391448,'御用守護者',unistr('地屬性協調+協調以外的怪獸1隻以上\u000a①：此卡戰鬥破壞對手怪獸送去墓地時可以發動。那隻怪獸在我方場上守備表示特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7392745,'鼠骨','①：此卡反轉的場合發動。在對手場上將3隻「鼠骨二世衍生物」（不死族、地、等級1、攻100/守300）守備表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7392746,'鼠骨二世衍生物','由「鼠骨」的效果特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7394770,'明亮結合',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，我方牌組的怪獸作為融合素材，將1隻「寶石騎士」融合怪獸攻擊力、守備力變成0融合召喚。此卡從場上離開時，那隻怪獸破壞。\u000a②：1回合1次，從手牌捨棄1張魔法卡可以發動。此卡的①效果特殊召喚的怪獸的攻擊力、守備力直到對手回合結束時上升原本數值。\u000a\u000a※明亮融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7403341,'電腦網衝突',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「碼語者」怪獸存在，怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並除外。直到下個回合結束時，對手不能發動原卡名和此效果除外的卡相同的卡的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7405310,'額外之門','宣言從1到12的任意等級可以發動。對手將額外牌組的1隻和宣言等級相同的怪獸除外。對手的額外牌組沒有和宣言等級相同的怪獸的場合，選1張我方的手牌捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7407724,'六花精 歐石楠',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡以外的我方的植物族怪獸進行戰鬥的攻擊宣言時，解放手牌、場上的此卡可以發動。那隻我方怪獸的攻擊力、守備力直到回合結束時上升1000。\u000a②：此卡在墓地存在的狀態，我方場上的植物族怪獸被解放的場合可以發動。此卡守備表示特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7409792,'俊足的河馬 馬力巨犀',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：此卡可以從手牌特殊召喚。\u000a②：此卡的①方法特殊召喚成功的場合發動。對手可以從我方或對手的墓地選1隻等級4怪獸在自身場上特殊召喚。'),'對手特殊召喚','是否從墓地選1隻怪獸在自身場上特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7436169,'三步業',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上1隻「維薩斯-星霜」和對手場上1隻效果怪獸為對象可以發動。那隻對手怪獸的效果無效，作為對象的我方怪獸的攻擊力上升那個原攻擊力和原守備力之中較高數值的一半。\u000a②：將墓地的此卡除外可以發動。從牌組將「三步業」以外的1張記載「維薩斯-星霜」的卡名的魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7443908,'地翔星 疾風',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只有對手場上有怪獸存在的場合，或我方場上有光屬性怪獸存在的場合，此卡可以不用解放來召喚。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從手牌將1隻戰士族、光屬性、等級5怪獸特殊召喚。\u000a③：1回合1次，我方的戰士族怪獸被選擇作為攻擊對象時可以發動。此卡的攻擊力下降500，那次攻擊無效。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7445307,'雙組譯亞龍',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在的場合，從手牌以及我方場上的表側表示怪獸之中將2隻電子界族怪獸除外可以發動。此卡特殊召喚。此效果特殊召喚的此卡的攻擊力變成一半。\u000a②：1回合1次，將1張手牌除外可以發動。選場上1隻攻擊力在此卡的攻擊力以下的怪獸除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7452945,'天命的聖劍',unistr('只能給戰士族怪獸裝備。這個卡名的③效果1回合只能使用1次。\u000a①：「天命的聖劍」在我方場上只能有1張表側表示存在。\u000a②：裝備怪獸1回合只有1次不會被戰鬥、效果破壞。\u000a③：場上的表側表示的此卡被破壞送去墓地的場合，以我方場上1隻戰士族的「聖騎士」怪獸為對象可以發動。此卡給那隻我方的戰士族的「聖騎士」怪獸裝備。'),'給怪獸裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7459013,'暗黑界的騎士 祖爾','暗黑界裡其名無人不知的高傲騎士。絕對不會對弱者出手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7459919,'BF-刻夜之佐達',unistr('這個卡名的②③效果1回合只有1次能使用其中1個。\u000a①：只要此卡在怪獸區域存在，我方除了同步怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合，以場上1隻怪獸為對象可以發動。那隻怪獸回到持有者的手牌。\u000a③：將墓地的此卡除外可以發動。從手牌、牌組將1隻等級5以上的「BF」怪獸特殊召喚。那之後，我方受到此效果特殊召喚的怪獸的攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7473735,'異界共鳴-同步結合',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了融合、同步怪獸以外不能從額外牌組特殊召喚。\u000a①：將我方場上的表側表示的協調和協調以外的怪獸各1隻送去墓地可以發動。從額外牌組將以下怪獸各1隻特殊召喚。\u000a●墓地的那2隻怪獸為素材可以同步召喚的同步怪獸\u000a●墓地的那2隻怪獸為素材可以融合召喚的融合怪獸\u000a\u000a※異界共鳴-同步融合'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7477101,'時空的七皇',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：向對手展示額外牌組的「No.101」～「No.107」其中任何1隻「No.」超量怪獸可以發動。從牌組將1隻種族或屬性和展示的怪獸相同，等級和那隻怪獸的階級數值相同的怪獸加入手牌。那之後，選1張我方的手牌回到牌組最上方。此卡的發動後，直到回合結束時我方除了超量怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7478431,'大植然向日葵','①：對手發動怪獸的效果時，將此卡和我方場上1隻「大植然」怪獸解放可以發動。那個發動無效並破壞。','發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7480763,'聖遺物-達格達之棍',unistr('卡名不同的怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡以外的場上的卡的效果發動時可以發動。從手牌、牌組選1隻「聖遺物」怪獸當作魔法卡在我方的魔法與陷阱區域覆蓋。此效果覆蓋的卡在下個對手結束階段破壞。\u000a②：連結召喚的此卡在對手回合被破壞的場合可以發動。從我方墓地選1隻「聖遺物」怪獸守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7489323,'金毛終結犬','只要此卡在場上表側表示存在，場上的地屬性怪獸的攻擊力上升500，風屬性怪獸的攻擊力下降400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7496001,'守寶妖精戰利品',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的表側表示的超量怪獸因效果從場上離開的場合，以對手場上1隻效果怪獸為對象可以發動。這個回合，那隻效果怪獸在場上發動的效果不能發動。\u000a②：將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。從我方的牌組、墓地將1張「大沙海 黃金戈爾工達」發動。'),'效果1','效果2','請選擇不能發動效果的怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7500772,'鷹鯊',unistr('對手場上的怪獸是2隻以上的場合，此卡可以不用解放來召喚。\u000a此外，我方場上有「豹鯊」存在的場合，此卡可以從手牌特殊召喚。\u000a「鷹鯊」在我方場上只能有1隻表側表示存在。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7511613,'雷熱渦爐 雙驅進擊',unistr('等級4怪獸×2隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。我方墓地1隻「雷熱渦爐」怪獸作為此卡的超量素材。\u000a②：我方場上的怪獸的攻擊力上升且對手場上的怪獸的攻擊力下降此卡的超量素材數量×100。\u000a③：我方主要階段可以發動。去除我方場上的2個超量素材，從牌組將2張「雷熱渦爐」卡片加入手牌（同名卡最多1張）。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7512044,'精神統一','從牌組將1張「精神統一」加入手牌。「精神統一」在1回合只能使用1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7526150,'戈魯戈伊爾','從與異次元相通的洞裡出來的鋼鐵大魔人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7540107,'剛鬼 毅力',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：守備表示的此卡不會被戰鬥破壞。\u000a②：我方主要階段可以發動。我方場上的全部「剛鬼」怪獸的攻擊力上升200。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將「剛鬼 毅力」以外的1張「剛鬼」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7541475,'歌舞伎龍',unistr('①：1回合1次，我方怪獸攻擊對手怪獸的傷害計算前可以發動。那隻對手怪獸的表示形式變更。\u000a②：1回合1次，對手怪獸攻擊我方怪獸的傷害計算前可以發動。那隻我方怪獸的表示形式變更。'),'表示形式變更','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7548747,'偉魔神通',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻「偉魔」怪獸為對象可以發動。從我方的額外牌組、場上、墓地挑選1隻等級4以外的「偉魔」怪獸當作裝備卡給對象怪獸裝備。我方墓地有「偉魔」融合、同步、超量、連結怪獸各1隻以上存在的場合，也能從「偉魔」怪獸以外的額外牌組的融合、同步、超量、連結怪獸之中挑選此效果裝備的怪獸。\u000a\u000a※大魔導'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7562372,'超音速之眼','來自宇宙盡頭的殺人機器。用不明金屬製作。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7563579,'娛樂法師 火布偶',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方場上的表側表示的「娛樂法師」怪獸被戰鬥、效果破壞的場合可以發動。此卡特殊召喚。那之後，我方受到500傷害。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：場上的此卡被戰鬥、效果破壞的場合可以發動。從手牌、牌組將「娛樂法師 火布偶」以外的1隻「娛樂法師」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7565547,'力之集約','選擇場上的1隻表側表示怪獸可以發動。場上的全部裝備卡給選擇的怪獸裝備。對象不正確的裝備卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7572887,'異次元的女戰士','①：此卡和對手怪獸進行戰鬥的傷害計算後可以發動。那些進行戰鬥的雙方怪獸除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7573135,'劍鬥獸 奧古斯都',unistr('①：此卡被「劍鬥獸」怪獸的效果特殊召喚成功時可以發動。從手牌將1隻「劍鬥獸」怪獸守備表示特殊召喚。此效果特殊召喚的怪獸在結束階段回到持有者的牌組。\u000a②：此卡進行戰鬥的戰鬥階段結束時，讓此卡回到持有者的牌組可以發動。從牌組將「劍鬥獸 奧古斯都」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7574904,'突變魔物 武裝型',unistr('此卡只能用「突變魔」卡片的效果特殊召喚。這個卡名的②③效果1回合各能使用1次。\u000a①：此卡不會成為對手的陷阱卡的效果的對象。\u000a②：對手發動怪獸的效果時，從我方的手牌、場上將1張卡除外，以場上1隻怪獸為對象可以發動。那隻怪獸除外。\u000a③：此卡被對手破壞的場合，以被除外的1張我方的「突變魔」魔法卡為對象可以發動。那張卡加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7576264,'幻獸 野生角','此卡攻擊守備表示怪獸時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7582066,'念力魔鬼',unistr('協調+協調以外的超能族怪獸1隻以上\u000a①：1回合1次，我方主要階段可以發動。從對手的手牌隨機選1張，猜那張卡的種類（怪獸、魔法、陷阱）。如果猜對，此卡的攻擊力直到下個對手回合結束時上升1000。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7593748,'奇巧人偶-基岡提斯人偶',unistr('等級4「奇巧人偶」怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：去除此卡的2個超量素材，以對手場上最多2隻怪獸為對象可以發動。直到結束階段得到那些怪獸的控制權。此效果的發動後，直到回合結束時我方除了「奇巧人偶」怪獸以外不能特殊召喚，除了用超量怪獸以外不能攻擊宣言。\u000a②：將此卡解放可以發動。我方場上的全部怪獸的等級直到回合結束時變成8。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7594154,'禪那乃追儺戲姬',unistr('效果怪獸2隻以上\u000a此卡連結召喚的場合，手牌的1隻怪獸也能作為連結素材。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組將1隻怪獸送去墓地。只用我方場上的怪獸為素材連結召喚的場合，送去墓地的怪獸也能從額外牌組挑選。\u000a②：此卡從場上被送去墓地的場合，下個我方準備階段可以發動。從我方墓地將1隻怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7602800,'黑羽的旋風',unistr('①：1回合1次，我方從額外牌組將闇屬性同步怪獸特殊召喚的場合，以攻擊力低於那隻怪獸的我方的墓地、除外狀態的1隻「BF」怪獸或「黑羽龍」為對象可以發動。那隻怪獸特殊召喚。\u000a②：1回合1次，我方場上的闇屬性怪獸被戰鬥、效果破壞的場合，可以去除我方場上的1個黑羽計數器作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7602840,'UFO機人','此卡被戰鬥破壞送去墓地時，可以從牌組將1隻攻擊力1500以下的機械族怪獸表側攻擊表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7608148,'Vivid Tail',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上1張卡為對象可以發動。那張卡回到持有者的手牌。\u000a②：此卡在墓地存在的場合，以我方場上1張表側表示的卡為對象可以發動。此卡在我方場上覆蓋，那張表側表示的卡回到持有者的手牌。此效果覆蓋的此卡從場上離開的場合被除外。這個回合，我方不能發動以此效果回到手牌的卡以及那些同名卡的效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7610394,'眷現的咒眼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：在我方場上將1隻「咒眼的眷屬衍生物」（惡魔族、闇、等級1、攻/守400）特殊召喚。我方的魔法與陷阱區域有「塞勒涅的咒眼」存在的場合，此效果特殊召喚的數量可以變成2隻。此卡的發動後，直到回合結束時我方除了惡魔族怪獸以外不能特殊召喚。\u000a②：將墓地的此卡除外可以發動。這個回合，我方場上的「咒眼」魔法、陷阱卡不會成為對手的效果的對象。'),'效果1','效果2','是否特殊召喚2隻衍生物？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7610395,'咒眼的眷屬衍生物','由「眷現的咒眼」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7614732,'大融合',unistr('①：從我方的手牌、場上將融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。此效果融合召喚的場合，融合素材怪獸必須是3隻以上。此效果特殊召喚的怪獸得到以下效果。\u000a●此卡不會被效果破壞。\u000a●此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'「大融合」的效果1適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7617062,'鬼計博物館',unistr('只要此卡在場上存在，「鬼計」怪獸以外的我方場上的怪獸不能攻擊，雙方場上的怪獸不能向裡側守備表示怪獸攻擊，可以在對手場上的怪獸只有裡側守備表示怪獸的場合向對手直接攻擊。\u000a此外，怪獸給予玩家戰鬥傷害的傷害步驟結束時，那些怪獸變成裡側守備表示。'),'變成裡側守備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7617253,'虹之所在','對手怪獸的攻擊宣言時，將我方的魔法與陷阱區域的1張「寶玉獸」卡片送去墓地可以發動。那1隻對手怪獸的攻擊無效，可以從我方牌組將1張「究極寶玉神」卡片加入手牌。','是否把1張「究極寶玉神」卡片加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7622360,'惡魔鬥牛士',unistr('藉由「鬥牛士降臨儀式 黑暗入場式」降臨。這個卡名的①效果1回合只能使用1次。\u000a①：此卡儀式召喚的場合可以發動。從牌組將「惡魔鬥牛士」以外的2張「惡魔」卡片加入手牌。這個回合，此卡不能攻擊。\u000a②：此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：此卡和怪獸進行戰鬥的傷害計算後發動。那隻怪獸破壞，給予對手1000傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7623640,'暗黑界的導師 塞魯利',unistr('①：此卡被效果從手牌捨棄到墓地的場合發動。此卡在對手場上守備表示特殊召喚。\u000a②：此卡用「暗黑界」卡片的效果特殊召喚成功的場合發動。對手選1張自身的手牌捨棄。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7625614,'稀有金鎧甲','只要裝備怪獸在我方場上存在，對手不能攻擊裝備怪獸以外的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7628844,'CNo.32 海咬龍 鯊龍獸・白海煞',unistr('等級5怪獸×4\u000a此卡也能將手牌1張魔法卡捨棄，重疊在我方場上的階級4的「鯊龍獸」超量怪獸上方來超量召喚。\u000a①：我方、對手回合1次，去除此卡的1個超量素材，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果無效化，那個攻擊力、守備力變成0。\u000a②：此卡在1次戰鬥階段中可以攻擊2次，向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'是否重疊在「鯊龍獸」超量怪獸上方來超量召喚？','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7631534,'雙天腳 鎧吽',unistr('「雙天」怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的「雙天」融合怪獸被效果破壞的場合，可以將我方場上1隻「雙天」怪獸破壞作為代替。\u000a②：我方場上有用效果怪獸為素材融合召喚的「雙天」融合怪獸存在的場合，我方、對手的主要階段，以從額外牌組特殊召喚的1隻表側表示怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7634581,'奧雷卡爾克斯修羅諾斯',unistr('此卡不能通常召喚。以此卡的①效果可以特殊召喚。\u000a①：我方的通常怪獸被戰鬥破壞的場合，傷害步驟結束時可以發動。此卡從手牌特殊召喚。\u000a②：此卡的攻擊力上升對手場上的怪獸數量×1000。\u000a③：只要此卡在怪獸區域存在，場上的等級4的通常怪獸不會被效果破壞。'),'此卡特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7653207,'水波噴射機','①：以我方場上1隻魚族、海龍族、水族怪獸為對象可以發動。那隻怪獸的攻擊力上升1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7656689,'安迪米翁的侍女 傑妮',unistr('這個卡名在規則上也當作「魔女工坊」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，我方場上有魔法使族怪獸存在的場合可以發動。此卡特殊召喚。\u000a②：我方、對手的主要階段，以我方場上1隻魔法使族怪獸為對象可以發動。那隻怪獸除外，從牌組將「安迪米翁的侍女 傑妮」以外的1隻「魔女工坊」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7670542,'生化植物','地下研究所的試驗大失敗所產生的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7672244,'紫焰的間諜','選擇我方場上表側表示存在的1隻怪獸可以發動。直到這個回合的結束階段時，選擇的卡的控制權轉移給對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7700132,'蠕蟲 貴族','反轉：此卡因對手怪獸的攻擊而反轉的場合，給予對手那隻對手怪獸的攻擊力一半的傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7714344,'娛樂夥伴 小獨',unistr('①：此卡召喚、特殊召喚成功的回合的我方主要階段可以發動1次。從手牌將1隻等級3以下的「娛樂夥伴」怪獸攻擊表示特殊召喚。\u000a②：對手回合，從我方墓地將此卡和1隻「娛樂夥伴 小獨」以外的「娛樂夥伴」怪獸除外可以發動。這個回合我方受到的戰鬥傷害只有1次變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7721912,'聖騎士的持槍者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，以我方場上1隻等級8以下的怪獸為對象可以發動。那隻怪獸直到結束階段卡名當作「花之同步者」，當作協調。\u000a②：將此卡解放可以發動。從牌組將1張裝備魔法卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7733560,'時械神 米奇恩',unistr('此卡不能從牌組特殊召喚。\u000a①：我方場上沒有怪獸存在的場合，此卡可以不用解放來召喚。\u000a②：此卡不會被戰鬥、效果破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：此卡進行戰鬥的戰鬥階段結束時發動。對手的生命值變成一半。\u000a④：我方準備階段發動。此卡回到持有者的牌組。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7736719,'空氣循環機',unistr('①：此卡召喚成功時可以發動。讓2張手牌回到牌組洗牌。那之後，我方從牌組抽2張卡。\u000a②：此卡被破壞的場合發動。我方從牌組抽1張卡。'),'慮抽','抽卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7778726,'高能星星',unistr('光屬性怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：場上的光屬性怪獸的攻擊力、守備力上升500，闇屬性怪獸的攻擊力、守備力下降400。\u000a②：此卡被戰鬥、效果破壞的場合，以我方墓地1隻光屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7782069,'剛鬼 暴君食人魔',unistr('「剛鬼」連結怪獸+戰士族、恐龍族、電子界族怪獸\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡融合召喚的場合，最多到那些作為融合素材的「剛鬼」連結怪獸的連結標記的總和，以場上的卡為對象可以發動（連結3以上的怪獸作為融合素材的場合，應對這個發動，不能發動對象卡片的效果）。那些卡破壞。\u000a②：此卡進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法、陷阱、怪獸的效果。'),'效果1','不能發動效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7799906,'娛樂夥伴 微笑魔術士',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方場上的攻擊力高於原攻擊力的怪獸被戰鬥、效果破壞的場合可以發動。靈擺區域的此卡特殊召喚。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「微笑」魔法、陷阱卡加入手牌。\u000a②：我方場上的怪獸只有「娛樂夥伴」怪獸、「魔術師」靈擺怪獸、「異色眼」怪獸，此卡的攻擊力高於原攻擊力的場合可以發動。我方依照我方場上的攻擊力高於原攻擊力的怪獸數量從牌組抽牌。這個回合，我方不能將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7802006,'魔草曼德拉','反轉：給場上表側表示存在的可以放置魔力計數器的卡各放置1個魔力計數器。','放置魔力計數器','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7805147,'兵隊龍','①：1回合1次，對手發動魔法、陷阱、怪獸的效果時可以發動。從牌組將1隻等級2以下的龍族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7805359,'喔喔','將敵人整個吞下並吸收成能量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7811875,'重力崩壞','①：對手將怪獸召喚、反轉召喚、特殊召喚之際，將我方場上1隻表側表示的同步怪獸送去墓地可以發動。使其無效，那些怪獸破壞。這個回合，對手不能將怪獸召喚、反轉召喚、特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7817703,'變形鬥士 力量裝備',unistr('只能給等級3的「變形鬥士」怪獸裝備。\u000a裝備怪獸的攻擊力變成原攻擊力的2倍。\u000a此卡發動後第2次的我方準備階段發動。此卡破壞，我方受到裝備怪獸的原攻擊力數值的傷害。'),'此卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7841112,'救世星龍',unistr('「救世龍」+「星塵龍」+協調以外的怪獸1隻\u000a對手發動魔法、陷阱、效果怪獸的效果時，可以藉由解放此卡，將那個發動無效，對手場上的卡全部破壞。\u000a1回合1次，可以選擇對手場上的1隻表側表示怪獸，那個效果直到回合結束時無效。這個效果無效的怪獸記載的效果在這個回合可以作為此卡的效果發動1次。\u000a結束階段時，此卡回到額外牌組，選擇我方墓地的1隻「星塵龍」特殊召喚。'),'發動無效','怪獸效果無效','回到額外牌組','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7841921,'疾走的暗黑騎士蓋亞',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：此卡可以不用解放來召喚。\u000a②：不用解放來召喚的此卡的原攻擊力變成1900。\u000a③：此卡被解放的場合可以發動。從牌組將1隻「混沌士兵」怪獸加入手牌。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7845138,'茫漠的死者',unistr('①：我方的生命值是2000以下的場合，此卡可以從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合發動。此卡的攻擊力變成對手的生命值一半的數值。'),'攻擊變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7850740,'超量滑行海豚',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有超量怪獸特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡在墓地存在，我方場上有超量怪獸特殊召喚的場合，以那1隻超量怪獸為對象可以發動。將此卡重疊在那隻怪獸下方作為超量素材。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852509,'破壞輪迴',unistr('①：只要此卡在魔法與陷阱區域存在，卡名當作「破壞輪」。\u000a②：1回合1次，場上的怪獸被效果破壞的場合，以場上1隻怪獸為對象可以發動。那隻怪獸破壞，雙方受到500傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852510,'破壞輪迴',unistr('①：只要此卡在魔法與陷阱區域存在，卡名當作「破壞輪」。\u000a②：1回合1次，場上的怪獸被效果破壞的場合，以場上1隻怪獸為對象可以發動。那隻怪獸破壞，雙方受到500傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852878,'三千根針','向守備表示的此卡攻擊的對手怪獸的攻擊力低於此卡的守備力的場合，傷害步驟結束時那隻攻擊怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7864030,'超重武者 松明-2',unistr('①：對手怪獸的攻擊宣言時，我方墓地沒有魔法、陷阱卡存在的場合，將此卡從手牌送去墓地，以我方場上1隻「超重武者」怪獸為對象可以發動。攻擊對象轉移到那隻怪獸進行傷害計算。\u000a②：1回合1次，對手怪獸的攻擊宣言時可以發動。攻擊對象轉移到此卡進行傷害計算。\u000a③：此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7868571,'鍊裝 銀鳥',unistr('【靈擺效果】\u000a①：1回合1次，以此卡以外的我方場上1張表側表示的卡為對象可以發動。那張卡破壞，從牌組選1張「鍊裝」魔法、陷阱卡在我方場上覆蓋。\u000a【怪獸敘述】\u000a操縱著白銀次光速噴氣機的美麗狙擊手。想捕捉到用超常識速度飛馳的她是幾乎不可能的事，沒有辦法能從快如光速時施展的一擊中逃脫出去。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7889323,'鐵獸的死線',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有獸族、獸戰士族、鳥獸族怪獸特殊召喚的場合，以我方的除外狀態的1隻「鐵獸」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：我方的「鐵獸」怪獸和對手怪獸進行戰鬥的傷害計算後可以發動。那隻對手怪獸回到手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7892180,'念力河童','能使用多種超能力避開攻擊的河童。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7894706,'混沌的三幻魔',unistr('不能通常召喚的等級10怪獸×3\u000a「混沌的三幻魔」1回合1次，只能用融合召喚或以下方法特殊召喚。\u000a●將我方場上的上述卡送去墓地，可以從額外牌組特殊召喚。\u000a①：場上的此卡1回合最多2次不會被效果破壞。\u000a②：我方、對手回合最多3次，以對手場上1隻表側表示怪獸為對象可以發動（同一連鎖上最多1次）。那隻怪獸的效果直到回合結束時無效。那之後，可以讓我方的生命值回復那個攻擊力的一半數值。'),'效果2','是否回復生命值？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7894707,'混沌的三幻魔',unistr('不能通常召喚的等級10怪獸×3\u000a「混沌的三幻魔」1回合1次，只能用融合召喚或以下方法特殊召喚。\u000a●將我方場上的上述卡送去墓地，可以從額外牌組特殊召喚。\u000a①：場上的此卡1回合最多2次不會被效果破壞。\u000a②：我方、對手回合最多3次，以對手場上1隻表側表示怪獸為對象可以發動（同一連鎖上最多1次）。那隻怪獸的效果直到回合結束時無效。那之後，可以讓我方的生命值回復那個攻擊力的一半數值。'),'效果2','是否回復生命值？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7902349,'被封印者的左手','被封印的左腕。封印解開的話能夠得到無限的力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7903368,'水晶頭骨',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚成功的場合發動。我方受到1000傷害。那之後，此卡變成守備表示。\u000a②：我方沒有受到效果傷害的回合的結束階段可以發動。從牌組選1隻攻擊力0的岩石族怪獸加入手牌或特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7913375,'砲擊的飛箭龜',unistr('這個卡名的效果1回合只能使用1次。\u000a①：解放我方場上1隻怪獸可以發動。從手牌、牌組將1隻「暗黑騎士蓋亞」怪獸或龍族、等級5怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7914843,'電磁蓑衣蟲',unistr('①：此卡反轉的場合，以對手場上1隻機械族怪獸為對象發動。直到下個我方結束階段，得到那隻機械族怪獸的控制權。\u000a②：此卡被怪獸戰鬥破壞的場合發動。那隻怪獸的攻擊力、守備力下降500。'),'取得控制權','攻守下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7917970,'神風的龍盟',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方主要階段可以發動。我方墓地有「龍之溪谷」存在的場合，以下效果各自可以適用。不存在的場合，從以下效果挑選1個適用。\u000a●從我方墓地將1隻龍族、鳥獸族怪獸加入手牌。\u000a●從手牌將1隻「龍盟」怪獸特殊召喚。那之後，可以從牌組將1隻龍族的「龍盟」怪獸當作裝備魔法卡，給此效果特殊召喚的怪獸裝備。'),'效果1','●怪獸加入手牌','●從手牌特殊召喚','是否從牌組將1隻怪獸裝備？','','','','','','','','','','','','');
INSERT INTO texts VALUES(7922915,'魔法師引導',unistr('①：從手牌將1隻「黑魔導」特殊召喚。那之後，從牌組將1隻等級7以下的魔法使族、闇屬性怪獸特殊召喚。\u000a②：我方場上有「黑魔導」存在的場合，將不是在這個回合送去墓地的此卡從墓地除外，以對手場上1張表側表示的魔法、陷阱卡為對象可以發動。那張卡的效果直到回合結束時無效。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7925734,'連結蘋果',unistr('這個卡名的效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。我方的額外牌組的裡側表示的卡隨機選1張除外。除外的卡是連結怪獸的場合，此卡特殊召喚。不是的場合，此卡從手牌捨棄，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7930346,'折折之紙神',unistr('①：1回合1次，我方主要階段可以發動。投擲硬幣直到反面出現為止。正面出現的次數每有2次，我方抽1張卡。\u000a②：此卡在怪獸區域存在的狀態，每次我方、對手投擲硬幣發動。那些投擲硬幣擲出正面的次數每有1次，此卡的攻擊力加倍1次。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7934362,'娛樂法師 火舞者',unistr('【靈擺效果】\u000a①：1回合1次，以我方場上1隻「娛樂法師」怪獸為對象可以發動。這個回合，那隻怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將「娛樂法師 火舞者」以外的1隻「娛樂法師」怪獸加入手牌。\u000a②：場上的此卡被戰鬥、效果破壞的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力下降500。'),'靈擺效果1','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7935043,'海龍神的加護','直到這個回合結束時，我方場上的等級3以下的水屬性怪獸不會被戰鬥、效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7953868,'蒼血鬼',unistr('此卡召喚、反轉召喚成功時，變成守備表示。\u000a1回合1次，藉由去除我方場上的1個超量素材，選擇我方墓地的1隻等級4的不死族怪獸特殊召喚。'),'變成守備表示','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7969770,'移魂使魔','①：1回合1次，以我方場上1隻怪獸為對象可以發動。那隻我方怪獸的位置向其他的我方的主要怪獸區域移動。','效果1','請選擇要移動的位置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7984540,'聖天樹的月桂精',unistr('植物族怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。\u000a②：將我方場上1隻怪獸解放，以「聖天樹的月桂精」以外的我方墓地2隻植物族連結怪獸為對象可以發動。那些怪獸回到額外牌組。'),'效果2','請選擇要回到額外牌組的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7986397,'復仇屍者覺醒',unistr('「仇屍」儀式怪獸的降臨所必需。這個卡名的卡在1回合只能發動1張。\u000a①：解放我方的手牌、場上的怪獸，或從牌組將「仇屍」怪獸（最多1隻）送去墓地來代替解放，直到等級合計和儀式召喚的怪獸相同為止，從我方的手牌、墓地儀式召喚1隻「仇屍」儀式怪獸。此效果儀式召喚的怪獸在下個回合的結束階段破壞。'),'是否從牌組把1隻「仇屍」怪獸送去墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7987191,'槍管上膛暴動龍',unistr('藉由「重型扳機」降臨。這個卡名的①②效果1回合各能使用1次。\u000a①：對手將怪獸特殊召喚之際可以發動。那次特殊召喚無效，那些怪獸破壞。那之後，選此卡或我方場上1隻「槍彈」怪獸破壞。\u000a②：此卡在墓地存在的場合，以我方墓地1隻「槍管」怪獸或「槍彈」怪獸為對象可以發動。選我方的手牌、場上的1張卡破壞，對象怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8025950,'小工具箱子',unistr('這個卡名在規則上也當作「變形鬥士」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，給此卡放置3個變形鬥士計數器。\u000a②：1回合1次，我方主要階段可以發動。去除我方場上的1個變形鬥士計數器，在我方場上將1隻「小工具箱子衍生物」（機械族、地、等級1、攻/守0）特殊召喚。只要此效果特殊召喚的衍生物存在，我方除了同步怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8025951,'小工具箱子衍生物','由「小工具箱子」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8034697,'魔法提線木偶',unistr('每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a此卡的攻擊力上升此卡的魔力計數器的數量×200。\u000a藉由去除此卡放置的2個魔力計數器，選擇場上的1隻怪獸破壞。'),'放置魔力計數器','破壞1隻怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8038143,'時空轉生',unistr('我方場上有「銀河眼時空龍」怪獸存在的場合，此卡也能從手牌發動。\u000a①：我方場上有「銀河眼」怪獸存在的場合，連鎖2以後可以發動。此卡的發動時累積的連鎖上的全部對手的怪獸的效果、魔法、陷阱卡的發動無效，用此效果將發動無效的卡在場上存在的場合，那些全部回到牌組。'),'適用「時空轉生」的效果來發動','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8039562,'龍盟-彎刃刀龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌、墓地的此卡除外，以我方場上1隻「龍盟」怪獸為對象可以發動。從我方的牌組、墓地將1隻龍族的「龍盟」怪獸當作裝備魔法卡給對象怪獸裝備。\u000a②：將給「龍盟」怪獸裝備中的此卡送去墓地，以對手場上1張表側表示卡為對象可以發動。那張卡除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8041569,'熔岩炎湖畔的淑女','我方墓地有3種以上「熔岩」怪獸存在的場合，將我方墓地的此卡和1隻「熔岩」怪獸除外可以發動。選擇對手場上覆蓋的1張卡破壞。','覆蓋的卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8057630,'核心再練成',unistr('選擇我方墓地的1隻「核成」怪獸，攻擊表示特殊召喚。\u000a我方的結束階段中那隻怪獸被破壞時，此卡的控制者受到那隻怪獸的攻擊力數值的傷害。\u000a此卡不在場上存在時，那隻怪獸破壞。那隻怪獸被破壞時，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8058240,'封印之鎖','咯吱咯吱的勒住對手，擁有封印的力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8062132,'毒蛇神 維諾米納迦',unistr('此卡不能通常召喚。只能用「蛇神降臨」的效果以及此卡的效果特殊召喚。\u000a此卡的攻擊力上升我方墓地的爬蟲類族怪獸數量×500。\u000a只要此卡在場上表側表示存在，此卡不會成為此卡以外的卡片效果的對象，也不受那些效果影響。\u000a此卡被戰鬥破壞送去墓地時，可以藉由將此卡以外的我方墓地1隻爬蟲類族怪獸除外，此卡特殊召喚。\u000a此卡給予對手戰鬥傷害時，給此卡放置1個高等毒液計數器。此卡放置3個高等毒液計數器時，此卡的控制者獲得決鬥勝利。'),'從墓地特殊召喚','放置計數器','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8078366,'海皇的突擊兵','我方場上有此卡以外的魚族、海龍族、水族怪獸存在的場合，此卡的攻擊力上升800。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8080257,'炎之劍舞',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：怪獸特殊召喚的場合可以發動。從額外牌組將1隻等級7以下的「炎之劍士」或記載那個卡名的融合怪獸特殊召喚。那之後，可以將場上1隻表側表示怪獸變成裡側守備表示。\u000a②：對手戰鬥階段，將墓地的此卡除外，將我方場上1隻裡側守備表示怪獸解放可以發動。從牌組、額外牌組將1隻「炎之劍士」或記載那個卡名的怪獸特殊召喚。'),'從額外牌組特殊召喚','從牌組、額外牌組特殊召喚','是否將1隻怪獸變成裡側守備表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8083925,'Live☆Twin入口頁',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：捨棄1張手牌可以發動。從牌組將1隻「姬絲吉爾」怪獸或「璃拉」怪獸特殊召喚。此卡的發動後，直到回合結束時我方除了「Evil★Twin」怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8085950,'燃燒龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，對手場上有2隻以上怪獸存在的場合可以發動。此卡特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合，從手牌捨棄1張魔法卡可以發動。場上的魔法、陷阱卡全部破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8091563,'SD機器人 獅鬥士',unistr('此卡召喚成功時，可以從手牌將1隻「SD機器人」怪獸或「軌道7」特殊召喚。\u000a1回合1次，從我方墓地有「SD機器人」怪獸或「軌道7」加入我方的手牌時，可以將那隻怪獸從手牌特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8102334,'大門阻擋者','①：只要此卡在怪獸區域存在，對手不能將其他的我方場上的怪獸作為效果的對象，不能給場上的卡放置計數器。此外，對手的場地魔法卡的效果無效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8124921,'被封印者的右腳','被封印的右腳。封印解開的話能夠得到無限的力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8129306,'六花精 櫻草',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的怪獸被解放的場合可以發動。此卡從手牌守備表示特殊召喚。\u000a②：以我方場上最多2隻植物族怪獸為對象可以發動。那些怪獸的等級直到回合結束時上升2。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8131171,'殺手蛇',unistr('「殺手蛇」的效果1回合只能使用1次。\u000a①：此卡在墓地存在的場合，我方準備階段可以發動。此卡回到手牌。下個對手結束階段，選我方墓地1隻「殺手蛇」除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8148322,'捕食霸種結合',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：場上有「捕食植物」怪獸存在的場合可以發動。依照闇屬性融合怪獸卡，從我方、對手場上將包含我方場上的2隻以上闇屬性怪獸的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a\u000a※捕食霸種融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8152834,'陀羅威',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡在手牌存在的場合，以這個回合在場上發動過效果的我方、對手的主要怪獸區域1隻表側表示怪獸為對象可以發動。那隻怪獸破壞，此卡在那隻怪獸存在過的區域特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8165596,'No.90 銀河眼光子卿',unistr('等級8怪獸×2\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：持有「光子」卡片作為超量素材的此卡不會被效果破壞。\u000a②：對手發動怪獸的效果時，去除此卡的1個超量素材可以發動。那個效果無效。去除的超量素材是「銀河」卡片的場合，再將那隻怪獸破壞。\u000a③：對手回合可以發動。從牌組選1張「光子」卡片或「銀河」卡片加入手牌或作為此卡的超量素材。'),'效果2','效果3','成為超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8170654,'巨型章玉米',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。此卡從手牌守備表示特殊召喚，那隻對手怪獸的攻擊對象轉移為此卡進行傷害計算。\u000a②：以「巨型章玉米」以外的我方場上1隻植物族怪獸為對象可以發動。那隻怪獸和此卡的攻擊力變成那2隻的原攻擊力合計數值。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8173184,'修復次世代控制者',unistr('等級4以下的「次世代」怪獸1隻\u000a我方1回合只能特殊召喚1次「修復次世代控制者」。\u000a①：此卡連結召喚的場合可以發動。從我方墓地將1隻「次世代」怪獸加入手牌。\u000a②：「次世代」怪獸用抽牌以外的方法加入我方的手牌的場合可以發動（同一連鎖上最多1次）。進行1隻「次世代」怪獸的召喚。這個回合，我方除了用「次世代」協調為同步素材的同步召喚以外不能從額外牌組將怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8175346,'口袋龍','此卡召喚成功時，可以從我方牌組將1隻「口袋龍」加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8192327,'光靈神 福斯奧拉奇',unistr('此卡不能通常召喚。只能在我方墓地的光屬性怪獸是5隻的場合特殊召喚。這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚成功時可以發動。對手場上的怪獸全部破壞。\u000a②：表側表示的此卡從場上離開的場合，跳過下個我方回合的戰鬥階段。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198620,'冥界龍 龍亡',unistr('不死族怪獸×2\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：「冥界龍 龍亡」在我方場上只能有1隻表側表示存在。\u000a②：和此卡進行戰鬥的怪獸不會被那次戰鬥破壞。\u000a③：此卡和怪獸進行戰鬥的傷害步驟結束時發動。那隻怪獸的攻擊力變成0，將1隻等級、攻擊力和那隻怪獸的原本的等級、攻擊力相同的「暗魂衍生物」（不死族、闇、攻?/守0）在我方場上特殊召喚。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198621,'暗魂衍生物','由「冥界龍 龍亡」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198712,'世界終滅','①：解放我方的手牌、場上的怪獸，直到等級合計和儀式召喚的怪獸相同為止，從手牌儀式召喚1隻「破滅之女神 茹茵」或「終焉之王 帝滅斯」。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8200556,'實驗體突變魔 ST-46',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「突變魔」魔法、陷阱卡加入手牌。\u000a②：將此卡解放，將1張手牌或我方場上的表側表示的卡除外可以發動。依照除外的卡的種類，從手牌、牌組將1隻以下的怪獸特殊召喚。\u000a●怪獸：「突變魔物 獸化型」\u000a●魔法：「突變魔物 魔霧型」\u000a●陷阱：「突變魔物 武裝型」'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8201910,'海星男孩','只要此卡在場上表側表示存在，場上的水屬性怪獸的攻擊力上升500，炎屬性怪獸的攻擊力下降400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8226374,'奇巧人偶-小矮蛋',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功時可以發動。從手牌將1隻「奇巧人偶」怪獸特殊召喚。'),'從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8233522,'正義盟軍 週期解讀蟲','將此卡從手牌捨棄到墓地可以發動。選擇對手墓地最多2隻光屬性怪獸除外。此效果在對手回合也能發動。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8240199,'青之眼賢士',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚時可以發動。從牌組將「青之眼賢士」以外的1隻光屬性、等級1協調加入手牌。\u000a②：將此卡從手牌捨棄，以我方場上1隻效果怪獸為對象可以發動。那隻怪獸送去墓地，從牌組將1隻「青眼」怪獸特殊召喚。'),'從牌組加入手牌','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8243121,'LL-比翼的麗鳥',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「LL-」怪獸為對象可以發動。對手場上的全部怪獸的攻擊力變成和對象怪獸的攻擊力相同，對手場上的全部怪獸的等級、階級變成1。\u000a②：對手怪獸向我方的「LL-」怪獸攻擊宣言時，將墓地的此卡除外可以發動。那隻我方怪獸的攻擊力直到回合結束時變成和那隻對手怪獸的攻擊力相同。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8251996,'搗蛋三角颶風！！','我方場上有「搗蛋小綠」「搗蛋小黃」「搗蛋小黑」表側表示存在的場合可以發動。對手場上的卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8252010,'X-軍刀 卡多姆茲',unistr('協調+地屬性怪獸1隻以上\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從牌組將1張「軍刀」魔法、陷阱卡或「卡多姆茲」魔法、陷阱卡加入手牌。\u000a②：此卡給予對手戰鬥傷害時可以發動。對手的手牌隨機選1張捨棄。\u000a③：此卡在墓地存在的狀態，我方的「X-軍刀」怪獸被選擇作為攻擊對象時可以發動。此卡特殊召喚。那之後，攻擊對象轉移到此卡。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8264361,'暗影的闇靈使 達爾克',unistr('包含闇屬性怪獸的怪獸2隻\u000a這個卡名在規則上也當作「憑依裝著」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：以對手墓地1隻闇屬性怪獸為對象可以發動。那隻怪獸在此卡指向的我方場上特殊召喚。\u000a②：連結召喚的此卡被戰鬥或對手的效果破壞的場合可以發動。從牌組將1隻守備力1500以下的闇屬性怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8267140,'宇宙氣旋','①：支付1000生命值，以場上1張魔法、陷阱卡為對象可以發動。那張卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8275702,'寶玉的契約','①：以我方的魔法與陷阱區域1張「寶玉獸」怪獸卡為對象可以發動。那張卡特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8279188,'深淵的護身符',unistr('此卡在發動後，在第3次的對手結束階段破壞。\u000a對手怪獸的攻擊宣言時可以發動。捨棄1張手牌，選擇的1隻對手怪獸的攻擊無效。'),'是否現在發動此卡的效果？','攻擊無效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8284390,'疾行機人 56飛機',unistr('「疾行機人 56飛機」的①效果1回合只能使用1次。\u000a①：我方場上有怪獸特殊召喚的場合可以發動。此卡從手牌特殊召喚。此效果的發動後，直到回合結束時我方除了風屬性怪獸以外不能特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時下降600。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8310162,'Sin 悖論龍',unistr('「Sin 平行齒輪」+協調以外的「Sin」怪獸1隻\u000a①：「Sin 悖論龍」在場上只能有1隻表側表示存在。\u000a②：此卡同步召喚成功時，以我方或對手的墓地1隻同步怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。\u000a③：場上沒有「Sin World」存在的場合，此卡破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8316565,'猛拳反擊','我方場上有「燃燒拳手」怪獸存在的場合可以發動。戰鬥階段中發動的效果怪獸的效果、魔法、陷阱卡的發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8316661,'魔轟神 密茲托吉','將此卡從手牌送去墓地，選擇我方場上的1隻「魔轟神」怪獸可以發動。選擇的怪獸只要在場上表側表示存在就當作協調。','當作協調','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8321183,'靈獸的誓還','①：從手牌將1隻「靈獸」怪獸除外，以我方的墓地、除外狀態的1隻「靈獸」怪獸為對象可以發動。那隻怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8323633,'夜霧的狙擊手',unistr('作為此卡的發動時的效果處理，宣言1個怪獸卡名。\u000a對手將宣言的怪獸召喚、特殊召喚、反轉的場合，宣言的怪獸和此卡除外。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8324284,'死靈之盾',unistr('①：對手怪獸的攻擊宣言時1次，從我方墓地將1隻惡魔族、不死族怪獸除外可以發動。那次攻擊無效。\u000a②：1回合1次，對手發動要讓卡破壞的效果時，從我方墓地將1隻惡魔族、不死族怪獸除外可以發動。那個發動無效。\u000a③：我方、對手的結束階段，惡魔族、不死族怪獸不在我方場上存在的場合發動。此卡送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8327462,'死亡鳥','「橐蜚」+「骷髏的寺院」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8339504,'超量變換','將我方場上1隻超量怪獸解放可以發動。從額外牌組將1隻和解放的怪獸種族、屬性、階級相同且卡名不同的超量怪獸特殊召喚，將此卡重疊在下方作為超量素材。此效果特殊召喚的怪獸在結束階段時送去墓地。「超量變換」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8353769,'空氣吞食者','吸收周圍的空氣，使對手窒息的妖怪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8372133,'緋暗紅使魔',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：解放我方場上1隻惡魔族怪獸，以我方墓地1隻龍族、闇屬性同步怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。\u000a②：將墓地的此卡除外，以我方場上1隻龍族、闇屬性同步怪獸為對象，宣言1～8的任意等級可以發動。那隻怪獸直到回合結束時變成宣言的等級。'),'效果1','效果2','請宣言1個等級','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8379983,'月光金獅子',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將「月光金獅子」以外的1隻「月光」怪獸加入手牌。那之後，選1張我方的手牌捨棄。\u000a②：此卡在怪獸區域存在的狀態，「月光」怪獸被送去我方墓地的場合，以其中1隻為對象可以發動（傷害步驟也能發動）。那隻怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8384771,'娛樂夥伴 橡膠綿羊',unistr('【靈擺效果】\u000a①：1回合1次，我方怪獸和對手怪獸進行戰鬥的攻擊宣言時可以發動。那隻我方怪獸不會被那次戰鬥破壞。\u000a【怪獸效果】\u000a①：1回合1次，我方怪獸和對手怪獸進行戰鬥的攻擊宣言時可以發動。那隻我方怪獸不會被那次戰鬥破壞。'),'不會被戰鬥破壞','不會被戰鬥破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8387138,'No.27 弩級戰艦-無畏艦',unistr('等級4怪獸×2隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡戰鬥破壞對手怪獸的戰鬥階段結束時可以發動。將1隻階級10以上的機械族超量怪獸重疊在我方場上的此卡上方，當作超量召喚從額外牌組特殊召喚。\u000a②：場上的此卡被戰鬥、效果破壞的場合，可以去除此卡的1個超量素材作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8396952,'大秘儀之力I-魔術師',unistr('此卡召喚、反轉召喚、特殊召喚成功時，投擲1次硬幣並得到以下效果。\u000a●正：魔法卡發動的場合，此卡的攻擊力直到回合結束時變成原攻擊力的2倍。\u000a●反：每次魔法卡發動，對手回復500生命值。'),'投擲硬幣','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8400623,'邪龍 阿難陀',unistr('此卡不能通常召喚。只能從我方墓地以及我方場上的表側表示怪獸之中將爬蟲類族怪獸全部除外來特殊召喚。\u000a①：此卡的攻擊力、守備力變成為了此卡特殊召喚而除外的怪獸數量×600。\u000a②：我方結束階段，以場上1張卡為對象發動。此卡在我方場上表側表示存在的場合，對象卡片破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8414337,'薰風的風塵','此卡發動的回合，我方場上的「薰風」怪獸的攻擊宣言時，對手不能發動魔法、陷阱、效果怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8428836,'冥占術的儀式',unistr('「占術姬」儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從我方的手牌、墓地將1隻「占術姬」儀式怪獸表側攻擊表示或裡側守備表示儀式召喚。\u000a②：我方場上有「占術姬」儀式怪獸存在的場合，我方、對手的準備階段，將墓地的此卡除外可以發動。從牌組將儀式怪獸以外的1隻「占術姬」怪獸裡側守備表示特殊召喚。'),'N/A','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8437145,'煉獄的死徒',unistr('①：以我方場上1隻「獄火機」怪獸為對象可以發動。這個回合，那隻我方怪獸不受對手的效果影響。\u000a②：我方場上的「獄火機」怪獸被效果破壞的場合，可以將墓地的此卡除外作為那些「獄火機」怪獸之中的1隻的代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8445808,'戀愛少女',unistr('①：只要此卡在怪獸區域存在，可以攻擊的對手怪獸必須向此卡攻擊。\u000a②：此卡不會被戰鬥破壞。\u000a③：此卡和對手怪獸進行戰鬥的傷害步驟結束時，可以從以下效果選擇1個發動。\u000a●給對手場上1隻表側表示怪獸放置1個少女計數器。\u000a●得到已放置少女計數器的1隻對手怪獸的控制權。'),'','','效果3','●放置計數器','●得到控制權','','','','','','','','','','','');
INSERT INTO texts VALUES(8454126,'奈芙蒂斯的聯繫者',unistr('藉由「奈芙蒂斯的輪迴」降臨。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡儀式召喚成功的場合可以發動。從手牌、牌組將「奈芙蒂斯的聯繫者」以外的1隻「奈芙蒂斯」儀式怪獸當作儀式召喚作特殊召喚。\u000a②：此卡被「奈芙蒂斯」卡片的效果解放的場合或破壞的場合可以發動。下個準備階段，從我方的手牌、牌組、場上各選最多1張儀式怪獸以外的「奈芙蒂斯」卡片破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8463720,'DDD剋龍王 貝奧武夫',unistr('「DDD」怪獸+「DD」怪獸\u000a①：只要此卡在怪獸區域存在，我方的「DD」怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：我方準備階段可以發動。雙方的魔法與陷阱區域的卡全部破壞。'),'破壞魔法陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8471389,'高科技狼','全身由鋼鐵製成的狼，用銳利的牙齒撕咬敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8483333,'嵌合蠍尾獅','①：此卡上級召喚成功的場合，下個我方回合的準備階段發動。為了此卡的上級召喚而解放的怪獸從墓地盡可能往我方場上特殊召喚。此效果特殊召喚的怪獸不能攻擊宣言，效果無效化。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8487449,'糖果小丑',unistr('①：「糖果小丑」在我方場上只能有1隻表側表示存在。\u000a②：此卡可以從手牌攻擊表示特殊召喚。\u000a③：此卡的②方法特殊召喚的場合，下個對手結束階段，以對手場上1隻表側表示怪獸為對象發動。那隻對手的表側表示怪獸和表側表示的此卡回到持有者的手牌。'),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491308,'閃刀姬-颯',unistr('風屬性以外的「閃刀姬」怪獸1隻\u000a我方1回合只能特殊召喚1次「閃刀姬-颯」。\u000a①：此卡可以直接攻擊。\u000a②：此卡進行戰鬥的傷害計算後可以發動。從牌組將1張「閃刀」卡片送去墓地。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491309,'閃刀姬-颯',unistr('風屬性以外的「閃刀姬」怪獸1隻\u000a我方1回合只能特殊召喚1次「閃刀姬-颯」。\u000a①：此卡可以直接攻擊。\u000a②：此卡進行戰鬥的傷害計算後可以發動。從牌組將1張「閃刀」卡片送去墓地。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491961,'LL-吟誦椋鳥',unistr('等級1怪獸×2隻以上\u000a①：此卡超量召喚成功的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力、守備力上升此卡的超量素材數量×300。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。從牌組將1隻鳥獸族、等級1怪獸加入手牌。\u000a③：超量召喚的此卡的戰鬥產生給我方的戰鬥傷害對手也要承受。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8495780,'深海的工匠',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用水屬性怪獸的效果從牌組、墓地加入手牌的場合，向對手展示此卡可以發動。確認對手的全部手牌。\u000a②：此卡特殊召喚成功的場合，從我方牌組上方將1張卡送去墓地，以「深海的工匠」以外的我方墓地1隻等級4以下的水屬性怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8505920,'合體魔神-門之守護者',unistr('「雷魔神-桑卡」+「風魔神-胡卡」+「水魔神-斯卡」\u000a只能將我方的手牌、場上、墓地的上述卡除外來特殊召喚。這個卡名的①效果1回合可以使用最多3次。\u000a①：對手發動以我方場上的卡為對象的效果時可以發動。那個效果無效並破壞。\u000a②：特殊召喚的表側表示的此卡因對手從場上離開的場合可以發動。從牌組、額外牌組將1隻等級11以下的「門之守護者」怪獸無視召喚條件特殊召喚。'),'效果無效並破壞','無視條件特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8508055,'格鬥鼠 邱助','目標是成為鼠界最強的格鬥家而在世界範圍內流浪的熱血鼠。無知的觸碰它會很受傷哦。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8512558,'希望皇擬聲烏托邦',unistr('這個卡名在規則上也當作「刷啦啦」、「我我我」、「隆隆隆」、「怒怒怒」卡片。這個卡名的效果1回合只能使用1次。\u000a①：我方主要階段可以發動。從手牌將「希望皇擬聲烏托邦」以外的以下怪獸各最多1隻守備表示特殊召喚。此效果的發動後，直到回合結束時我方除了超量怪獸以外不能從額外牌組特殊召喚。\u000a●「刷啦啦」怪獸\u000a●「我我我」怪獸\u000a●「隆隆隆」怪獸\u000a●「怒怒怒」怪獸'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8522996,'始源的帝王',unistr('①：此卡發動後變成效果怪獸（惡魔族、闇、等級6、攻1000/守2400）在怪獸區域特殊召喚。此卡也當作陷阱卡。\u000a②：此卡的效果將此卡特殊召喚成功的場合，捨棄1張手牌，宣言1個屬性可以發動。此卡當作宣言的屬性，和此卡屬性相同的怪獸上級召喚的場合，此卡可以當作2隻解放。\u000a③：只要此卡的效果特殊召喚的此卡存在，我方除了和此卡相同屬性的怪獸以外不能特殊召喚。'),'改變屬性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8529136,'廢鐵拳',unistr('①：以我方場上1隻「廢品戰士」為對象可以發動。這個回合，那隻我方怪獸和對手怪獸進行戰鬥的場合，適用以下效果。\u000a●對手直到傷害步驟結束時不能發動魔法、陷阱、怪獸的效果。\u000a●對象怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a●對手受到的戰鬥傷害變成2倍。\u000a●對象怪獸不會被戰鬥破壞。\u000a●進行戰鬥的對手怪獸在傷害步驟結束時破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8540986,'滅亡之闇 維多斯',unistr('「滅亡龍 維多斯」+等級9以下的炎族怪獸2隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡融合召喚的場合可以發動。對手場上的魔法、陷阱卡全部破壞。\u000a②：只要此卡在怪獸區域存在，此卡不會被效果破壞，對手不能將此卡作為怪獸的效果的對象。\u000a③：對手發動場上的魔法、陷阱、怪獸的效果時，將我方場上1張表側表示的「灰滅」卡片送去墓地可以發動。那張卡破壞。'),'N/A','效果1','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8559524,'指揮共鳴體',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌捨棄1隻「共鳴體」怪獸可以發動。從牌組將1隻等級4以下的惡魔族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8559793,'RR-鳥巢',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上有2隻以上「RR-」怪獸存在的場合可以發動。從我方的牌組、墓地將1隻「RR-」怪獸加入手牌。'),'從牌組、墓地加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8561192,'神樹的守護獸-牙王',unistr('協調+協調以外的怪獸1隻以上\u000a此卡在我方的主要階段2以外不會成為對手的效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8567955,'平衡負載王',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，支付1000生命值可以發動。這個回合我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻電子界族怪獸。\u000a②：此卡被除外的場合可以發動。從手牌將1隻等級4以下的怪獸特殊召喚。'),'效果1','效果2','召喚（平衡負載王）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8571567,'BF-嵐砂之夏馬',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌、場上的此卡送去墓地可以發動。從牌組將1張「黑羽的旋風」在我方場上表側表示放置。\u000a②：此卡在墓地存在的狀態，我方場上有「BF」同步怪獸或「黑羽龍」特殊召喚的場合，將此卡除外，以我方墓地1隻「BF」怪獸為對象可以發動。那隻怪獸加入手牌。那之後，我方受到700傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8576764,'貪食魚 貪魚龍',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方墓地1隻等級在對手的手牌數量以下的魚族、海龍族、水族怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能發動效果。\u000a②：此卡作為同步素材送去墓地的場合可以發動。用此卡為同步素材的同步怪獸的攻擊力、守備力上升對手的手牌數量×200。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8581705,'獄火皇后惡魔',unistr('此卡的控制者在每次我方準備階段必須支付500生命值。如果不能支付，此卡破壞。\u000a如果此卡成為對手的效果的對象，在那次處理時擲1次骰子。擲出2、5的場合，那個效果無效並破壞。\u000a只要此卡在場上存在，每次準備階段，選擇1隻「惡魔」怪獸的攻擊力直到回合結束時上升1000。'),'攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8594079,'朱羅紀腕龍','場上有此卡以外的「朱羅紀」怪獸表側表示存在的場合，此卡不會被戰鬥破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8602351,'爬蟲妖 厄客德娜',unistr('包含爬蟲類族怪獸的怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力變成0。\u000a②：我方主要階段可以發動。最多到對手場上的攻擊力0的怪獸數量，從牌組將爬蟲類族怪獸加入手牌（同名卡最多1張）。此效果的發動後，直到回合結束時我方除了爬蟲類族怪獸以外不能從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8608979,'一族的集結',unistr('①：以場上1隻表側表示怪獸為對象可以發動。從我方的手牌、墓地選1隻和那隻怪獸原卡名不同且原種族相同的怪獸特殊召喚。\u000a②：魔法與陷阱區域的此卡被對手的效果破壞的場合可以發動。從牌組選1張「一族的集結」在我方的魔法與陷阱區域覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8611007,'熔岩谷龍騎兵',unistr('協調+協調以外的炎屬性怪獸1隻以上\u000a①：1回合1次，我方主要階段可以發動。從牌組將1隻「熔岩」怪獸加入手牌。那之後，從手牌選1隻「熔岩」怪獸送去墓地。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8617563,'RR-勇敢林鴞',unistr('等級5怪獸×2\u000a這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：去除此卡的1個超量素材可以發動。從牌組將1張「RR-」魔法、陷阱卡在我方場上覆蓋。\u000a②：此卡有鳥獸族怪獸作為超量素材的場合，去除此卡的1個超量素材可以發動。從牌組將1張「升階魔法」魔法卡加入手牌。\u000a③：持有此卡作為素材的「RR-」超量怪獸得到以下效果。\u000a●此卡的攻擊力上升自身的階級×100。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8628798,'D.D.炸彈','給予對手相當於除外的對手的卡片數量×300傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8632967,'進化的宿命','在我方的「進化蟲」怪獸的效果將怪獸特殊召喚成功時，對手不能發動魔法、陷阱、效果怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8633261,'冰燃雷熱渦爐',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：此卡可以將我方的手牌、場上1張卡送去墓地，從手牌特殊召喚。這個方法特殊召喚過的回合，我方除了階級4超量怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡召喚的場合可以發動。從牌組將「冰燃雷熱渦爐」以外的1隻「雷熱渦爐」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8634636,'白尾黑貓','反轉：對手場上2隻怪獸和我方場上1隻怪獸回到持有者的手牌。','回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8643186,'DD徵募',unistr('「DD徵募」在1回合只能發動1張。\u000a①：對手場上的怪獸數量比我方場上的怪獸多的場合，以我方墓地最多到相差數量的「DD」怪獸或「契約書」卡片為對象可以發動。那些卡加入手牌。'),'從墓地加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8649148,'深海清道夫','解放此卡可以發動。選擇場上的1張魔法、陷阱卡破壞。','魔法‧陷阱卡破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8653757,'光子延遲',unistr('①：從牌組選1張「光子」永續魔法、永續陷阱卡或「銀河」永續魔法、永續陷阱卡，加入手牌或在我方場上表側表示放置。\u000a②：覆蓋的此卡在對手回合被對手的效果破壞的場合，如果我方場上有「銀河眼光子龍」或持有「銀河眼光子龍」作為超量素材的超量怪獸存在可以發動。變成這個回合的結束階段。'),'效果1','是否加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8660395,'偉魔女神 結晶之寧阿魯魯',unistr('魔法使族等級4怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材，以我方墓地1隻等級4以上的魔法使族怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：裝備此卡的怪獸在1次戰鬥階段中可以向怪獸攻擊2次。\u000a③：此卡裝備中的場合，以我方的魔法與陷阱區域1張「偉魔」卡片和對手場上1張魔法、陷阱卡為對象可以發動。那些卡破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8662794,'碼破者 零日',unistr('①：「碼破者」連結怪獸以外的和此卡連結狀態的連結怪獸的攻擊力下降1000。\u000a②：此卡已在怪獸區域存在的狀態，場上的「碼破者」連結怪獸被戰鬥、效果破壞的場合發動。此卡破壞。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從牌組將1隻「碼破者 零日」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8687195,'幻影的妖精','此卡被對手怪獸攻擊的傷害計算前，選擇我方場上1隻怪獸發動。攻擊對象轉移到選擇的怪獸進行傷害計算。','代替承受攻擊','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8690387,'地縛戒隸 地畫戈蘭林',unistr('闇屬性協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，以對手場上1隻表側表示怪獸為對象可以發動。對手從以下挑選1個，我方將那個效果適用。\u000a●對象怪獸破壞。\u000a●我方的生命值回復對象怪獸的攻擊力的數值。\u000a②：我方、對手的戰鬥階段可以發動。我方的手牌、場上、墓地的怪獸作為融合素材除外，將1隻「地縛」融合怪獸融合召喚。'),'效果1','效果2','●那隻怪獸破壞','●發動玩家的生命值回復那隻怪獸的攻擊力數值','','','','','','','','','','','','');
INSERT INTO texts VALUES(8692301,'寶石騎士 仿鑽','「寶石騎士」怪獸+岩石族怪獸','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8696773,'陽炎獸 九頭蛇',unistr('只要此卡在場上表側表示存在，對手不能將此卡作為效果的對象，我方除了炎屬性怪獸以外不能特殊召喚。\u000a用此卡為素材的超量怪獸得到以下效果。\u000a●這次超量召喚成功時，可以從我方墓地選擇1隻「陽炎獸」怪獸，重疊在此卡下方作為超量素材。'),'●墓地的怪獸成為素材（陽炎獸 九頭蛇）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8698851,'D-反擊','我方場上表側表示存在的「D-HERO」怪獸被選擇作為攻擊對象時可以發動。攻擊怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8700633,'不屈的獸僕',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：對手將3隻以上怪獸特殊召喚的回合的主要階段可以發動。此卡從手牌、墓地特殊召喚。此效果在對手回合也能發動。\u000a②：我方場上沒有其他怪獸存在的場合，攻擊表示的此卡不會被戰鬥破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8706701,'紅蓮鏡',unistr('「紅蓮鏡」的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時，將此卡從手牌送去墓地，以「紅蓮鏡」以外的我方墓地1隻惡魔族、炎屬性怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：此卡在墓地存在，我方同步召喚成功的場合可以發動。墓地的此卡加入手牌。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8715625,'魔貨物車輛 博科伊奇','迪科伊奇專用的貨物車輛。可以運載任何東西。但是到達目的地時大部分貨物都會損壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8719957,'邃淵鱗甲-海怪',unistr('只能給「水精鱗」怪獸裝備。\u000a裝備怪獸的攻擊力上升400。\u000a只要此卡在場上存在，對手場上發動的效果怪獸的效果無效。那之後，此卡送去墓地。'),'效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8728498,'空牙團的懷劍 唐娜',unistr('種族不同的怪獸2隻\u000a這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上1隻「空牙團」怪獸和對手場上1隻怪獸為對象可以發動。那些怪獸破壞。\u000a②：將我方場上1隻怪獸解放可以發動。從我方的手牌、墓地將原卡名和解放的怪獸不同的1隻「空牙團」怪獸特殊召喚。將連結怪獸解放發動的場合，隨後可以再選1隻特殊召喚。'),'效果1','效果2','是否再選1隻特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8730435,'劍鬥獸的鬥器 惡魔之盾',unistr('只能給「劍鬥獸」怪獸裝備。\u000a裝備怪獸被破壞的場合，破壞此卡作為代替。\u000a裝備怪獸從我方場上回到牌組讓此卡被送去墓地時，此卡回到手牌。'),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8736823,'電腦堺姬-娘娘',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在墓地存在，我方場上有等級3怪獸召喚、特殊召喚的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡當作協調，從場上離開的場合被除外。這個回合，我方除了等級或階級是3以上的怪獸以外不能特殊召喚。\u000a②：此卡被除外的場合，以此卡以外的被除外的1張我方的卡為對象可以發動。那張卡回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8763963,'魔王超龍 別西卜宙斯',unistr('闇屬性協調+協調以外的怪獸2隻以上\u000a①：此卡不會被戰鬥、效果破壞。\u000a②：只要此卡在怪獸區域存在，此卡以外的我方怪獸不能攻擊。\u000a③：1回合1次，以對手場上1隻怪獸為對象可以發動。那隻怪獸的攻擊力變成0，我方回復那個原攻擊力數值的生命值。此外，這個回合此卡的戰鬥產生給對手玩家的戰鬥傷害變成一半。'),'攻擊力變成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8775395,'災誕的咒眼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻「咒眼」怪獸和1張「咒眼」魔法、陷阱卡送去墓地可以發動。從牌組將1張「咒眼」裝備魔法卡加入手牌。這個回合，每次我方發動「咒眼」卡片以外的卡的效果，我方失去500生命值。\u000a②：我方將「咒眼」連結怪獸連結召喚成功的場合，將墓地的此卡除外可以發動。從我方墓地選1張「咒眼」裝備魔法卡，給我方場上1隻「咒眼」連結怪獸裝備。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8778267,'穿透結合',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：怪獸被戰鬥破壞的回合可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻融合怪獸融合召喚。此效果特殊召喚的怪獸得到以下效果。\u000a●我方、對手回合，將此卡解放，以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力上升500。\u000a\u000a※穿透融合'),'效果1','「穿透結合」的效果1適用中','●攻擊力上升（穿透結合）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8783685,'生命的沙漏','掌管生命的天使。以縮短生命的代價來賜與力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8785161,'RR-野性禿鷲','①：此卡召喚、特殊召喚成功的回合的我方主要階段將此卡解放可以發動。直到等級合計為6為止，從我方的手牌、墓地選2隻「RR-」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8794055,'至深魊宙',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有魚族同步怪獸存在，此卡不會被效果破壞，不能被效果除外。\u000a②：從我方的手牌、墓地將1隻魚族怪獸除外可以發動。從牌組將1隻「游魊」怪獸加入手牌。\u000a③：此卡在墓地存在的狀態，我方場上有魚族怪獸召喚、特殊召喚的場合，以我方場上1隻魚族怪獸為對象可以發動。那隻怪獸除外，此卡加入手牌。'),'從牌組加入手牌','墓地的此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8794435,'合成魔獸 加澤特','此卡的攻擊力變成上級召喚時解放的2隻怪獸的原攻擊力的合計數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8802510,'PSY骨架王Λ',unistr('衍生物以外的怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方在我方場上有怪獸存在的場合也能發動手牌的「PSY骨架裝備」怪獸的效果。\u000a②：此卡已在怪獸區域存在的狀態，此卡以外的我方場上的表側表示的超能族怪獸被除外的場合可以發動。這個回合的結束階段，從牌組將1張「PSY骨架」卡片加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8805651,'巨石遺物 富洛曲',unistr('藉由「巨石遺物」卡片降臨\u000a這個卡名的②效果1回合只能使用1次，①②效果不能在同一連鎖上發動。\u000a①：此卡儀式召喚的場合可以發動。從我方墓地將1張「巨石遺物」卡片加入手牌。\u000a②：我方、對手的主要階段可以發動。解放包含場上的此卡的我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從我方墓地儀式召喚「巨石遺物 富洛曲」以外的1隻「巨石遺物」儀式怪獸。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8806072,'連擊打手','只要此卡在場上表側表示存在，我方回合的主要階段1有連鎖發生的場合，這個回合此卡在1次戰鬥階段中可以攻擊2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8809344,'外神 奈亞拉',unistr('等級4怪獸×2\u000a①：此卡超量召喚成功時，捨棄任意張數的手牌可以發動。此卡的階級上升捨棄的張數。\u000a②：1回合1次，此卡持有超量素材的場合，以我方墓地1隻怪獸為對象可以發動。此卡的超量素材全部去除，對象怪獸重疊在此卡下方作為超量素材。此卡的種族、屬性變成和此效果作為超量素材的怪獸的原本的種族、屬性相同。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8814959,'入魔曼德拉','①：對手場上的怪獸數量比我方場上的怪獸多的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8820526,'娛樂夥伴 黏土破壞者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：上級召喚的此卡和對手怪獸進行戰鬥傷害計算時可以發動。那隻對手怪獸的攻擊力直到回合結束時下降我方的額外牌組的表側表示的靈擺怪獸數量×500。\u000a②：此卡在墓地存在，我方將2隻以上的怪獸同時靈擺召喚時可以發動。墓地的此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8822710,'正義盟軍 宇宙幽閉者','對手場上有包含光屬性怪獸的2隻以上怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8836329,'颶風龍-蒲福九級',unistr('藉由「褒譽的吹息」降臨。這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的直接攻擊宣言時，將此卡從手牌捨棄可以發動。那次攻擊無效，那隻怪獸的效果無效化。\u000a②：以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸和此卡回到持有者的手牌。此效果在對手回合也能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8837932,'方界曼荼羅',unistr('①：我方場上有「方界」怪獸存在的場合，以任意數量這個回合被破壞送去對手墓地的怪獸為對象可以發動此卡。那些怪獸的攻擊力變成0在對手場上特殊召喚，給那些怪獸各放置1個方界計數器。已放置方界計數器的怪獸不能攻擊，效果無效化。\u000a②：只要對象怪獸在對手場上存在，對手發動的怪獸的效果無效化。\u000a③：對象怪獸全部從場上離開的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8841431,'百夫長騎士皇 普莉梅拉・普里默斯',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從我方的牌組、墓地將1張「徽紋」卡片加入手牌。那之後，可以將我方以及對手場上的卡各1張破壞。\u000a②：從額外牌組以外特殊召喚的此卡不會被戰鬥破壞。\u000a③：我方場上的表側表示的「百夫長」卡片因對手的效果從場上離開的場合可以發動。此卡從墓地特殊召喚。'),'效果1','效果3','是否將場上的卡破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8842266,'隱居者的猛毒藥',unistr('①：可以從以下效果選擇1個發動。\u000a●我方回復1200生命值。\u000a●給予對手800傷害。'),'我方回復1200生命值','給予對手800傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8843569,'翼之報恩',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的怪獸只有鳥獸族怪獸，且有原卡名不同的怪獸2隻以上的場合，支付600生命值可以發動。我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8852158,'翼影依 雯蒂之影',unistr('「影依」怪獸+風屬性怪獸\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手回合可以發動。場上任意數量的裡側守備表示怪獸變成表側守備表示。那之後，最多到其中的反轉怪獸數量，可以將變成表側守備表示的怪獸以外的表側表示怪獸變成裡側守備表示。\u000a②：此卡被送去墓地的場合，以我方墓地1張「影依」卡片為對象可以發動。那張卡加入手牌。\u000a\u000a※影靈翼騎 雯蒂之影'),'效果1','效果2','是否將怪獸變成裡側守備表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8868767,'骰子減肥法',unistr('①：擲1次骰子。依照發動回合適用以下效果。\u000a●我方回合：從我方墓地選擲出點數的數量的卡除外。擲出點數是1的場合，隨後從我方牌組上方將6張卡送去墓地。\u000a●對手回合：將擲出點數的數量的卡從我方牌組上方送去墓地。擲出點數是6的場合，隨後挑選我方墓地1張卡除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8873112,'聖遺物-環刃',unistr('①：此卡可以當作魔法卡從手牌覆蓋到魔法與陷阱區域。\u000a②：魔法與陷阱區域覆蓋的此卡在對手回合被破壞送去墓地的場合發動。此卡特殊召喚。\u000a③：要讓我方場上的魔法、陷阱卡破壞的效果發動時，讓我方場上1張覆蓋的魔法、陷阱卡回到手牌可以發動。此卡從手牌特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8875971,'光天使 翼','此卡召喚成功時，可以從手牌將1隻「光天使」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8903700,'儀式魔人 解放者',unistr('①：進行儀式召喚的場合，可以將墓地的此卡除外，作為那次儀式召喚所需等級數值的1隻怪獸。\u000a②：從使用此卡儀式召喚的玩家所見的對手，只要儀式召喚的那隻怪獸在怪獸區域表側表示存在，不能將怪獸特殊召喚。'),'禁止特殊召喚（儀式魔人 解放者）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8910240,'薔薇蝶',unistr('①：只要此卡在怪獸區域存在，我方在通常召喚之外只有1次，在我方主要階段可以表側攻擊表示上級召喚1隻等級7以上的怪獸。\u000a②：只要我方場上有此卡以外的昆蟲族怪獸存在，此卡可以直接攻擊。'),'上級召喚（薔薇蝶）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8910971,'暗黑騎士蓋亞王',unistr('①：對手場上有怪獸存在，我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：1回合1次，比此卡的攻擊力高的怪獸在對手場上特殊召喚的場合可以發動。此卡的攻擊力直到回合結束時上升700。'),'攻擊力上升700','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8915275,'邪惡箱',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上有「卡通世界」存在的場合可以發動。此卡從手牌特殊召喚。那之後，可以適用以下效果。\u000a●從牌組選1張「卡通」陷阱卡加入手牌或在我方場上覆蓋。\u000a②：只要場上有「卡通世界」存在，此卡當作卡通怪獸。\u000a③：我方、對手回合1次，以我方或對手墓地的1張卡為對象可以發動。那張卡回到牌組最下方。'),'效果1','效果3','是否挑選1張陷阱卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8944575,'死亡之足','眼珠子上長了腳的妖怪。用高高的跳躍進行攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8949584,'英雄到來','①：我方場上沒有表側表示怪獸存在的場合，支付一半生命值可以發動。從牌組將1隻等級4以下的「E.HERO」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8951260,'正正堂堂','雙方玩家各自在自己的回合將手牌全部持續公開。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8953369,'剎帝利怒威 交疊',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以場上1隻怪獸為對象可以發動。從我方的手牌、墓地以及我方、對手場上的表側表示怪獸之中，選1隻攻擊力1500/守備力2100的怪獸除外，對象怪獸的攻擊力上升1500。\u000a②：此卡被除外的場合，如果我方場上有「剎帝利怒威」怪獸存在，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8955148,'石蕊的死儀式',unistr('「石蕊的死劍士」的降臨所必需。這個卡名的②效果1回合只能使用1次。\u000a①：從我方的手牌、場上解放怪獸直到等級合計為8以上為止，從手牌儀式召喚「石蕊的死劍士」。\u000a②：此卡在墓地存在的場合，以我方墓地1隻「石蕊的死劍士」為對象可以發動。墓地的此卡和對象怪獸合計2張加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8963089,'黎銘機 赫歐史瓦羅格',unistr('機械族、光屬性怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡融合召喚的場合可以發動。下個回合的準備階段，從我方墓地將1張持有融合召喚效果的卡加入手牌。\u000a②：對手發動魔法、陷阱卡的效果時，將我方場上1隻表側表示的機械族、光屬性怪獸或我方墓地2隻機械族、光屬性怪獸除外可以發動。那個發動無效。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8964854,'合體突擊','已裝備聯合怪獸的怪獸進行戰鬥的戰鬥階段可以發動。選擇1隻已裝備聯合怪獸且進行戰鬥的怪獸，將裝備的聯合解除。選擇的怪獸在這個回合只有1次可以再度攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8967776,'究極時械神 賽菲隆',unistr('此卡不能通常召喚。只能在我方墓地有10隻以上怪獸存在的場合特殊召喚。\u000a1回合1次，可以將1隻等級8以上的天使族怪獸從我方的手牌、墓地特殊召喚。此效果特殊召喚的怪獸的效果無效化，攻擊力變成4000。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8972398,'妖醒龍 幼生獄風神',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌、墓地存在，我方場上的怪獸被戰鬥或對手的效果破壞的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：此卡特殊召喚成功的場合，以場上1隻表側表示怪獸為對象可以發動。選1張我方的手牌捨棄，從牌組將1隻和對象怪獸種族、屬性相同且卡名不同的怪獸加入手牌。'),'此卡特殊召喚','從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8978197,'龍之主宰-龍的統制者',unistr('①：只要此卡在怪獸區域存在，卡名當作「龍之主宰-龍的支配者」。\u000a②：此卡召喚成功時，從手牌捨棄1張魔法、陷阱卡可以發動。從牌組將「喚龍笛」「龍覺醒的旋律」「龍復活的狂奏」其中1張加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9000988,'娛樂夥伴 小判龍',unistr('【靈擺效果】\u000a①：1回合1次，以我方場上1隻從額外牌組特殊召喚的龍族怪獸為對象可以發動。這個回合，那隻我方怪獸和對手怪獸進行戰鬥的場合，那隻對手怪獸在傷害計算後除外。\u000a【怪獸效果】\u000a①：只要此卡在怪獸區域存在，此卡以外的我方場上的龍族怪獸的攻擊力上升500，不會被效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9012916,'黑羽龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：我方受到效果傷害的場合，給此卡放置1個黑羽計數器作為代替。\u000a②：此卡的攻擊力下降此卡的黑羽計數器的數量×700。\u000a③：1回合1次，去除此卡的全部黑羽計數器，以對手場上1隻表側表示怪獸為對象可以發動。那隻對手怪獸的攻擊力下降去除的黑羽計數器的數量×700，給予對手下降數值的傷害。'),'攻擊力下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9012917,'黑羽龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：我方受到效果傷害的場合，給此卡放置1個黑羽計數器作為代替。\u000a②：此卡的攻擊力下降此卡的黑羽計數器的數量×700。\u000a③：1回合1次，去除此卡的全部黑羽計數器，以對手場上1隻表側表示怪獸為對象可以發動。那隻對手怪獸的攻擊力下降去除的黑羽計數器的數量×700，給予對手下降數值的傷害。'),'攻擊力下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9024198,'DDD深淵王 吉爾伽美什',unistr('「DD」怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從牌組選2隻卡名不同的「DD」靈擺怪獸在我方的靈擺區域放置，我方受到1000傷害。此效果的發動後，直到回合結束時我方除了「DD」怪獸以外不能特殊召喚。\u000a②：連結召喚的此卡被對手怪獸的攻擊或對手的效果破壞的場合可以發動。從我方的額外牌組、墓地將1隻「DD」怪獸守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9024367,'銀河龍騎士',unistr('①：此卡不能直接攻擊，只能向龍族怪獸攻擊。\u000a②：此卡和龍族怪獸進行戰鬥的場合，只在戰鬥階段期間那隻怪獸的效果無效化，只在傷害步驟期間此卡的攻擊力上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9028399,'樂天禍 卡爾克拉格拉',unistr('這個卡名的效果1回合只能使用1次。\u000a①：我方場上的表側表示的地屬性怪獸被戰鬥或對手的效果破壞的場合可以發動。此卡從手牌特殊召喚。那之後，可以從牌組將1隻怪獸送去墓地。'),'從手牌特殊召喚（樂天禍 卡爾克拉格拉）','是否從牌組把1隻怪獸送去墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9030160,'常闇的契約書',unistr('①：我方的靈擺區域有2張「DD」卡片存在的場合，對手不能將場上的怪獸作為魔法、陷阱卡的效果的對象，不能作為上級召喚的解放，也不能作為融合、同步、超量召喚的素材。\u000a②：我方準備階段發動。我方受到1000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9032529,'天使之淚','①：選1張我方的手牌加入對手的手牌。那之後，我方回復2000生命值。','請選擇加入對手的手牌的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9047460,'BF-隱蓑之斯蒂姆',unistr('「BF-隱蓑之斯蒂姆」的②效果在決鬥中只能使用1次。\u000a①：表側表示的此卡從場上離開的場合發動。在我方場上將1隻「斯蒂姆衍生物」（水族、風、等級1、攻/守100）特殊召喚。\u000a②：此卡在墓地存在的場合，將我方場上1隻怪獸解放可以發動。此卡從墓地特殊召喚。將此效果特殊召喚的此卡作為同步素材的場合，其他的同步素材怪獸必須全部都是「BF」怪獸。'),'特殊召喚衍生物','此卡特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9047461,'斯蒂姆衍生物','由「BF-隱蓑之斯蒂姆」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9053187,'覺醒的勇士 咖咖吉哥','等級4怪獸×3','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9056100,'冰結界的虎將 神兵','①：只要此卡在怪獸區域存在，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻「冰結界」怪獸。','召喚（冰結界的虎將 神兵）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9059700,'無限地獄防護罩','我方場上有「無限地獄」怪獸表側攻擊表示存在，我方的手牌是0張的場合可以發動。對手發動的效果怪獸的效果、魔法、陷阱卡的發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9061682,'魔轟神 安托士',unistr('「魔轟神」協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。對手可以選1張手牌捨棄讓此效果無效。不捨棄的場合，我方抽2張卡。抽牌的場合，隨後挑選1張我方的手牌捨棄。\u000a②：怪獸從對手的手牌送去墓地的場合，以其中1隻怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'效果1','是否捨棄1張手牌將「魔轟神 安托士」的效果1無效？','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9064354,'闇之增產工廠',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：將我方的手牌、場上1隻怪獸送去墓地可以發動。我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9069157,'龍機人',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：可以將此卡從手牌捨棄，從以下效果選擇1個發動。\u000a●從牌組將1隻風屬性以外的「機人」怪獸加入手牌。\u000a●這個回合，我方發動包含將融合怪獸融合召喚的效果在內的效果的場合，那個發動不會被無效化，那次融合召喚成功時對手不能發動魔法、陷阱、怪獸的效果。\u000a②：1回合1次，此卡在墓地存在的場合可以發動。墓地的此卡直到回合結束時變成龍族。'),'●從牌組加入手牌','●融合召喚的發動不會被無效化','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9070454,'龍皇的波動',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手發動場上的怪獸的效果時可以發動。那個發動無效並破壞。那之後，可以適用以下效果。\u000a●從我方的手牌選1隻怪獸除外，此效果被破壞送去墓地的怪獸效果無效在我方場上特殊召喚。'),'是否適用以下效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9074847,'大騷動','我方的怪獸因對手的效果從場上回到手牌時可以發動。場上的全部怪獸回到持有者的手牌。那之後，雙方從手牌將回去數量的怪獸裡側守備表示特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9076207,'青色忍者','①：此卡反轉的場合，以場上1張表側表示的魔法卡或場上覆蓋的1張魔法、陷阱卡為對象發動。那張魔法卡破壞（如果那張卡被覆蓋在場上，則翻開確認）。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9091064,'征服鬥魂 蛟龍',unistr('這個卡名的①②效果1回合各能使用1次，不能在同一連鎖上發動。\u000a①：我方為了發動「征服鬥魂」卡片的效果而展示手牌的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方、對手回合，可以從以下選擇1個，向對手展示那些屬性的手牌的怪獸各1隻發動。\u000a●炎：場上1隻怪獸的表示形式變更。\u000a●炎、炎：從牌組將「征服鬥魂 蛟龍」以外的1張「征服鬥魂」卡片加入手牌。'),'效果1','●炎','●炎、炎','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9097866,'交叉除錯瓢蟲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有2隻以上連結怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方和對手的連結怪獸之間進行戰鬥的傷害計算時，將墓地的此卡除外，以我方墓地1隻連結怪獸為對象可以發動。那隻進行戰鬥的我方怪獸的攻擊力直到回合結束時上升對象怪獸的攻擊力數值，不會被那次戰鬥破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9102835,'沙羅曼龍結合',unistr('只能給戰士族、炎屬性怪獸裝備。這個卡名的③效果1回合只能使用1次。\u000a①：裝備怪獸的攻擊力上升700。\u000a②：裝備怪獸被戰鬥、效果破壞的場合，可以將此卡破壞作為代替。\u000a③：此卡給我方場上的融合怪獸裝備中的場合可以發動。裝備怪獸和此卡送去墓地，從額外牌組將1隻「炎之劍士」或記載那個卡名的融合怪獸當作融合召喚特殊召喚。\u000a\u000a※沙羅曼龍融合'),'融合召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9106362,'娛樂夥伴 銅鑼野貓',unistr('【靈擺效果】\u000a①：1回合1次，對手怪獸的直接攻擊宣言時可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。\u000a【怪獸效果】\u000a①：1回合1次，我方怪獸和對手怪獸進行戰鬥的攻擊宣言時可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。'),'戰鬥傷害變成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9107531,'電鍍砲手',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方將炎屬性怪獸召喚、特殊召喚的場合可以發動。此卡從手牌特殊召喚。那之後，可以從牌組將1隻炎族、等級8怪獸送去墓地。\u000a②：1回合1次，魔法卡發動的場合可以發動。我方場上的全部炎屬性怪獸的攻擊力上升300。'),'是否要從牌組送去墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9109991,'BF-鐵鎖之費恩',unistr('此卡可以直接攻擊對手。\u000a此卡直接攻擊給予對手戰鬥傷害時，選擇對手場上1隻攻擊表示怪獸變成守備表示。'),'變成守備表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9113513,'固定音型','①：我方場上沒有怪獸存在的場合可以發動。從我方的手牌、牌組將「幻奏」融合怪獸卡決定的2隻融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。這個回合的結束階段，此效果融合召喚的怪獸破壞，如果那整組融合素材怪獸都在我方墓地，可以將那整組特殊召喚。','是否特殊召喚融合素材怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9126351,'鬼青蛙',unistr('①：此卡可以從手牌將此卡以外的1隻水屬性怪獸捨棄，從手牌特殊召喚。\u000a②：此卡召喚、反轉召喚、特殊召喚成功時可以發動。從牌組以及我方場上的表側表示怪獸之中選1隻水族、水屬性、等級2以下的怪獸送去墓地。\u000a③：1回合1次，讓我方場上1隻怪獸回到手牌可以發動。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚「鬼青蛙」以外的1隻「青蛙」怪獸。'),'召喚（鬼青蛙）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9145181,'儀式降臨封印之書','選擇場上的1隻儀式怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9156135,'見習魔術師',unistr('①：此卡召喚、反轉召喚、特殊召喚成功的場合，以場上1張可以放置魔力計數器的卡為對象發動。給那張卡放置1個魔力計數器。\u000a②：此卡被戰鬥破壞時可以發動。從牌組將1隻等級2以下的魔法使族怪獸裡側守備表示特殊召喚。'),'放置魔力計數器','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9159938,'黑暗灰羚','全身灰色的走獸。非常少見的珍貴品種。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9161357,'No.6 先史遺產 大西洲巨人',unistr('等級6怪獸×2\u000a①：此卡超量召喚成功時，以我方墓地1隻「No.」怪獸為對象可以發動。那隻怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力一半數值。\u000a③：1回合1次，去除此卡的1個超量素材，將此卡的效果裝備的我方的魔法與陷阱區域的1張卡送去墓地可以發動。對手的生命值變成一半。此效果發動的整回合中，我方不能進行戰鬥階段。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9175957,'發現目標！守寶妖精！',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。此卡也能去除我方場上的最多3個超量素材來發動。\u000a①：從牌組將1隻「守寶妖精」怪獸加入手牌。去除超量素材來發動此卡的場合，隨後可以依照那個數量，從我方的手牌、墓地將「守寶妖精」怪獸特殊召喚。\u000a②：我方主要階段此卡在墓地存在的場合，以場上1隻超量怪獸為對象可以發動。去除那隻怪獸的1個超量素材，此卡加入手牌。'),'效果1','是否去除超量素材來發動？','是否從手牌、墓地特殊召喚？','效果2','','','','','','','','','','','','');
INSERT INTO texts VALUES(9190563,'RAM 雲雄羊',unistr('這個卡名的效果1回合只能使用1次。\u000a①：解放我方場上的1隻怪獸，以我方墓地的1隻電子界族怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9197735,'龍魂的石像','擁有龍的靈魂的石像戰士。用自豪的劍劈開敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9201964,'D-幸運','對手的直接攻擊宣言時，將我方墓地的1隻「D-HERO」怪獸除外可以發動。戰鬥階段結束。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9205573,'Evil★Twin 姬絲吉爾',unistr('包含「姬絲吉爾」怪獸的怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，如果我方場上有「璃拉」怪獸存在可以發動。我方抽1張卡。\u000a②：我方、對手的主要階段，我方場上沒有「璃拉」怪獸存在的場合可以發動。從我方墓地將1隻「璃拉」怪獸特殊召喚。這個回合，我方除了惡魔族怪獸以外不能從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9205574,'Evil★Twin 姬絲吉爾',unistr('包含「姬絲吉爾」怪獸的怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，如果我方場上有「璃拉」怪獸存在可以發動。我方抽1張卡。\u000a②：我方、對手的主要階段，我方場上沒有「璃拉」怪獸存在的場合可以發動。從我方墓地將1隻「璃拉」怪獸特殊召喚。這個回合，我方除了惡魔族怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9212051,'SPYRAL MISSION-救出',unistr('此卡發動後，在第3次的我方結束階段破壞。\u000a①：「SPYRAL MISSION-救出」在我方場上只能有1張表側表示存在。\u000a②：1回合1次，以我方墓地1隻「SPYRAL」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a③：將墓地的此卡除外，以我方墓地1隻「SPYRAL」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'發動但不使用效果','發動並使用效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9213491,'靜寂的念力女孩',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。選1張我方的手牌除外，除了「靜寂的念力女孩」以外，從牌組將1隻等級4以下的超能族怪獸特殊召喚。這個回合，我方除了超能族怪獸以外不能從額外牌組特殊召喚。\u000a②：最多到我方場上的超能族怪獸數量，以場上的表側表示怪獸為對象可以發動。那些怪獸的等級直到回合結束時上升1。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9236985,'咒法的寫魂鏡','「咒法」儀式怪獸的降臨所必需。必須支付儀式召喚的怪獸的等級×500生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9238125,'山與雪解的春化精',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將此卡，和1隻怪獸或1張「春化精」卡片捨棄可以發動。我方從牌組抽1張卡。那之後，可以從我方墓地選1隻地屬性怪獸特殊召喚。這個回合，我方不能發動地屬性以外的怪獸的效果。\u000a②：以我方場上1隻「春化精」怪獸為對象可以發動。這個回合，那隻怪獸在1次戰鬥階段中可以攻擊2次。'),'是否從墓地特殊召喚？','「山與雪解的春化精」的效果2適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9251497,'救金魚',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以對手墓地1隻怪獸為對象可以發動。翻開我方牌組最上方的卡。如果翻開的卡是和對象怪獸屬性相同的怪獸，翻開的卡加入手牌，對象怪獸回到對手的牌組。如果不是，翻開的卡送去墓地，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9260791,'銀河眼雲籠',unistr('解放此卡可以發動。從我方的手牌、墓地選「銀河眼雲籠」以外的1隻「銀河眼」怪獸特殊召喚。「銀河眼雲籠」的這個效果1回合只能使用1次。\u000a此外，此卡在墓地存在的場合，在我方的主要階段時，選擇我方場上的1隻「銀河眼」超量怪獸可以發動。墓地的此卡重疊在選擇怪獸下方作為超量素材。「銀河眼雲籠」的這個效果在決鬥中只能使用1次。'),'特殊召喚','成為素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9264485,'荷魯斯的僕人','只要此卡在我方場上表側表示存在，對手不能將場上的「荷魯斯的黑炎龍」卡片作為效果的對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9267769,'閃光彈','對手怪獸的直接攻擊使我方受到戰鬥傷害時可以發動。變成這個回合的結束階段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9272381,'輝星騎士 星聖 鑽石',unistr('光屬性等級5怪獸×3隻以上\u000a此卡也能在我方的主要階段2重疊在「輝星騎士 星聖 鑽石」以外的我方場上的「星騎士」超量怪獸上方來超量召喚。\u000a①：只要持有超量素材的此卡在怪獸區域存在，雙方不能從牌組將卡送去墓地，從墓地回到手牌的卡不回到手牌而除外。\u000a②：對手的闇屬性怪獸的效果發動時，去除此卡的1個超量素材可以發動。那個發動無效並破壞。'),'是否重疊在「星騎士」怪獸上方超量召喚？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9275482,'幻日燈火',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：戰鬥階段以外，對手不能將場上的此卡作為效果的對象。\u000a②：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a③：我方、對手的結束階段可以發動。我方抽1張卡。那之後，選任意數量我方的手牌除外，此卡的攻擊力上升此效果除外的卡片數量×500。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9283801,'叛逆的帝王',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：捨棄1張手牌可以發動。向對手展示牌組的3隻攻擊力是2400以上或800，且守備力是1000的怪獸，對手從其中選1隻。那1隻怪獸加入我方的手牌，其餘送去墓地。此卡的發動後，直到回合結束時我方不能從額外牌組將怪獸特殊召喚。\u000a②：將墓地的此卡除外可以發動。從手牌將1隻攻擊力800/守備力1000的怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9284723,'毒液蟒蛇','1回合1次，可以選擇對手場上1隻怪獸放置2個毒液計數器。此效果發動的整回合中，此卡不能攻擊宣言。','放置計數器','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9287078,'黑魔族復活之棺','①：對手將怪獸召喚、特殊召喚成功時，以那1隻怪獸和我方場上1隻魔法使族怪獸為對象可以發動。那2隻怪獸送去墓地。那之後，可以從我方的牌組、墓地選1隻魔法使族、闇屬性怪獸特殊召喚。','是否特殊召喚魔法使族、闇屬性怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9293977,'金屬龍','「鋼鐵巨神像」+「下級龍」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9298235,'絨毛動物娃娃機','①：我方場上的表側表示的「絨毛動物」怪獸被對手怪獸的攻擊或對手的效果破壞送去我方墓地時，以破壞的那1隻我方怪獸為對象可以發動。那隻怪獸加入手牌，我方從牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9322133,'念力抹除光線',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：選擇對手場上1隻從額外牌組特殊召喚的怪獸送去墓地。那之後，對手的生命值回復那隻怪獸的原攻擊力和原守備力之中較高的數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9327502,'E.HERO 電流','①：此卡給予對手戰鬥傷害時，以被除外的1隻我方的「E.HERO」怪獸為對象可以發動。那隻怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9334391,'寶玉的牽絆',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻「寶玉獸」怪獸加入手牌，從牌組選1隻和那隻怪獸卡名不同的「寶玉獸」怪獸當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9336190,'魅影騎士團 霧鴉爪',unistr('①：以被除外的1隻我方的「魅影騎士團」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：此卡在墓地存在的場合，對手的直接攻擊宣言時，以我方墓地1隻等級4以下的「魅影騎士團」怪獸為對象可以發動。那隻怪獸特殊召喚，此卡變成持有和那隻怪獸相同的原等級的通常怪獸（戰士族、闇、攻/守0）在怪獸區域特殊召喚（不當作陷阱卡）。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9341993,'魔救的救碎','①：解放我方場上任意數量的「魔救」怪獸，以那個數量+1張的場上的卡為對象可以發動。那些卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9342162,'彼岸的惡鬼 哈羅杭德',unistr('「彼岸的惡鬼 哈羅杭德」的①③效果1回合只有1次能使用其中1個。\u000a①：我方場上沒有魔法、陷阱卡存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方場上有「彼岸」怪獸以外的怪獸存在的場合，此卡破壞。\u000a③：此卡被送去墓地的場合可以發動。從牌組將1張「彼岸」魔法、陷阱卡送去墓地。'),'此卡特殊召喚','從牌組送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9348522,'浮鵺城',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡同步召喚成功時，以我方墓地1隻等級9怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：只要此卡在怪獸區域存在，召喚、特殊召喚的等級8以下的怪獸在那個回合不能攻擊。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9349094,'神樹獸 許珀利冬',unistr('等級9怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方回合，我方發動魔法、陷阱、怪獸的效果時，以我方墓地的1張和那個效果相同種類（怪獸、魔法、陷阱）的卡為對象可以發動。對象卡片重疊在此卡下方作為超量素材。\u000a②：對手回合，魔法、陷阱、怪獸的效果發動時可以發動。從此卡去除1個和那個效果相同種類（怪獸、魔法、陷阱）的超量素材，那個發動無效並破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9350312,'丘與芽吹的春化精',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：從手牌將此卡，和1隻怪獸或1張「春化精」卡片捨棄可以發動。從牌組將「丘與芽吹的春化精」以外的1張「春化精」卡片加入手牌。那之後，可以從我方墓地選1隻地屬性怪獸特殊召喚。這個回合，我方不能發動地屬性以外的怪獸的效果。\u000a②：只要此卡在怪獸區域存在，我方場上的「春化精」怪獸不會被效果破壞。'),'是否從墓地特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9354555,'光子帷幕','從我方的手牌選3隻光屬性怪獸回到牌組，從我方牌組將最多3隻光屬性、等級4以下的怪獸加入手牌。如果將2隻以上怪獸加入手牌，必須全部都是同名怪獸。','是否繼續選擇要加入手牌的怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9365703,'高速戰士','①：此卡召喚成功的回合的戰鬥步驟可以發動。此卡的攻擊力直到戰鬥階段結束時變成原攻擊力的2倍。','攻擊力變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9373534,'風魔手裡劍',unistr('只能給「忍者」怪獸裝備。\u000a裝備怪獸的攻擊力上升700。\u000a此卡從場上送去墓地時，給予對手700傷害。'),'給予對手700傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9391354,'重力擊龍','①：將我方場上1張表側表示的永續魔法卡送去墓地，以對手場上1隻怪獸為對象可以發動。那隻對手怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9396662,'冰結界的鏡魔師',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻其他的效果怪獸解放可以發動。在我方場上將最多3隻「冰結界衍生物」（水族、水、等級1、攻/守0）特殊召喚，此卡的等級上升那個數量的數值。這個回合，我方除了水屬性同步怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。「冰結界的鏡魔師」以外的我方的牌組、除外狀態的1張「冰結界」卡片加入手牌。'),'','請選擇要特殊召喚的衍生物數量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9396663,'冰結界衍生物','由「冰結界的鏡魔師」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9400127,'溟界之漠-弗洛吉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡從場上送去墓地的場合，或從墓地特殊召喚成功的場合，以對手場上1隻表側表示怪獸和持有那隻怪獸的攻擊力以上的攻擊力的對手墓地1隻怪獸為對象可以發動。作為對象的墓地的怪獸在對手場上特殊召喚，作為對象的對手場上的怪獸送去墓地。\u000a②：此卡在墓地存在的場合，將1張手牌送去墓地可以發動。此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9402966,'超重武者 魂-C',unistr('「超重武者 魂-C」的效果1回合只能使用1次。\u000a①：我方場上沒有「超重武者」怪獸以外的怪獸存在，我方墓地沒有魔法、陷阱卡存在的場合，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸和此卡從場上送去墓地。那之後，從額外牌組將1隻等級和送去墓地的那2隻怪獸的原等級合計相同的「超重武者」同步怪獸當作同步召喚特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9409625,'虛無械 Ain',unistr('①：此卡在場上表側表示存在期間只有1次不會被對手的效果破壞。\u000a②：1回合1次，可以從以下效果選擇1個發動。\u000a●從手牌捨棄1隻等級10怪獸可以發動。我方從牌組抽1張卡。\u000a●我方的魔法與陷阱區域沒有此卡以外的卡存在的場合，以我方墓地1隻「時械神」怪獸為對象可以發動。那隻怪獸回到牌組。那之後，可以從手牌、牌組選1張「無限械 Ain Soph」在我方的魔法與陷阱區域覆蓋。'),'●從牌組抽1張卡','●墓地的怪獸回到牌組','是否覆蓋「無限械 Ain Soph」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9411399,'D-HERO 魔性小子','①：將墓地的此卡除外可以發動。從牌組將1隻「D-HERO 魔性小子」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9416697,'游魊之看守 伊諾可',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，以我方的除外狀態的1隻等級4以下的魚族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。\u000a②：從我方的手牌、場上（表側表示）將1隻魚族怪獸除外可以發動。從牌組將1張「游魊」陷阱卡加入手牌。'),'效果無效特殊召喚','從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9418365,'武尊神-日孁',unistr('此卡不能通常召喚。將「武尊神-日孁」以外的我方墓地的1隻「武尊神」怪獸除外可以特殊召喚。\u000a這個方法特殊召喚的此卡被對手破壞送去墓地的場合可以發動。我方捨棄1張手牌。那之後，對手選1張手牌捨棄。\u000a「武尊神-日孁」在我方場上只能有1隻表側表示存在。'),'捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9418534,'人造人-念力回歸者',unistr('①：此卡可以直接攻擊。\u000a②：此卡被送去墓地時，以我方墓地1隻「人造人-念力震懾者」為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在我方結束階段破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9430387,'雷雲怪','帶電的雲型怪獸。降下不管什麼都能溶化的雨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9433350,'Sin 青眼白龍',unistr('此卡不能通常召喚。從牌組將1隻「青眼白龍」除外可以特殊召喚。\u000a①：「Sin」怪獸在場上只能有1隻表側表示存在。\u000a②：只要此卡在怪獸區域存在，其他的我方怪獸不能攻擊宣言。\u000a③：沒有場地魔法卡表側表示存在的場合，此卡破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9453320,'海皇精 邃淵特里忒',unistr('水屬性等級7怪獸×2隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡超量召喚的場合，以我方墓地1隻等級7以下的魚族、海龍族、水族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：只要此卡在怪獸區域存在，我方場上的水屬性怪獸的攻擊力、守備力上升此卡的超量素材數量×300。\u000a③：去除此卡的1個超量素材可以發動。從牌組將1張「邃淵」陷阱卡在我方場上覆蓋。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9464441,'魔救的奇蹟-巨龍晶石',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從我方牌組上方翻開5張卡。最多到其中的岩石族怪獸數量，可以讓對手場上的卡回到手牌。翻開的卡以喜歡的順序回到牌組下方。\u000a②：我方墓地有水屬性怪獸存在，對手發動魔法、陷阱卡的效果時可以發動。那個發動無效並破壞。'),'效果1','效果2','是否選擇對手場上的卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9482987,'偉魔賢者 聖魔之安迪米翁',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「偉魔」怪獸為對象可以發動。從額外牌組選1隻「偉魔」怪獸當作裝備卡給對象怪獸裝備。\u000a②：以我方場上1張表側表示的魔法卡為對象可以發動。那張卡破壞，我方從牌組抽1張卡。那之後，選1張手牌回到牌組最下方。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9485511,'U.A. 守門員',unistr('「U.A. 守門員」的①方法的特殊召喚1回合只能有1次。\u000a①：此卡可以讓「U.A. 守門員」以外的我方場上1隻「U.A.」怪獸回到手牌，從手牌特殊召喚。\u000a②：對手回合1次，以我方場上1隻「U.A.」怪獸為對象可以發動。那隻怪獸在這個回合只有1次不會被戰鬥、效果破壞。'),'對象不會被破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9486959,'神隱鬼火丸',unistr('等級2怪獸×2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材，以對手場上1隻怪獸為對象可以發動。那隻怪獸直到對手結束階段除外。\u000a②：持有超量素材的此卡被對手破壞的場合，最多到此卡原先持有的超量素材數量，以我方、對手的除外狀態的怪獸為對象可以發動。那些怪獸回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9491461,'我我我加把勁騎士',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示額外牌組的1隻「我我我」怪獸可以發動。此卡從手牌特殊召喚。那之後，可以從以下效果挑選1個適用。\u000a●從手牌將1隻「我我我」怪獸特殊召喚。\u000a●場上1隻怪獸的表示形式變更。\u000a②：超量素材的此卡為了發動超量怪獸的效果而被去除的場合可以發動。從牌組將1隻「隆隆隆」怪獸加入手牌。'),'效果1','效果2','●從手牌特殊召喚','●表示形式變更','都不選擇','','','','','','','','','','','');
INSERT INTO texts VALUES(9505425,'偉魔賢者 法典之克勞利',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：從手牌以及我方場上的表側表示怪獸之中將1隻魔法使族怪獸送去墓地可以發動。此卡從手牌特殊召喚。\u000a②：宣言1個屬性可以發動。此卡直到回合結束時變成宣言的屬性。\u000a③：將墓地的此卡除外，以我方場上1隻「偉魔」怪獸為對象可以發動。從我方墓地選1隻等級4以外的「偉魔」怪獸當作裝備卡給對象怪獸裝備。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9523599,'堆疊修復者',unistr('這個卡名的效果在決鬥中只能使用1次。\u000a①：用此卡為素材連結召喚的場合，以此卡以外的我方墓地1隻作為那次連結召喚的素材的等級4以下的電子界族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9540040,'岩石龜','全身由岩石做成的龜。特點是守備力非常高。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9547962,'歐拉迴路',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上有3隻以上「廷達三角」怪獸存在的場合，對手怪獸不能攻擊。\u000a②：我方準備階段，以我方場上1隻「廷達三角」怪獸為對象可以發動。那隻怪獸的控制權轉移給對手。\u000a③：將墓地的此卡除外，從手牌捨棄1張「廷達三角」卡片可以發動。從牌組將1張「歐拉迴路」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9551692,'HAM之主',unistr('獸族怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡融合召喚、反轉的場合可以發動。從我方的手牌、牌組將1隻反轉怪獸裡側守備表示特殊召喚。\u000a②：此卡在墓地存在的場合，從我方場上（表側表示）、墓地將2隻反轉怪獸除外可以發動。此卡裡側守備表示特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9553721,'靈魂鳥之據所',unistr('「靈魂鳥之據所」的②效果1回合只能使用1次。\u000a①：我方場上的靈魂怪獸的攻擊力、守備力上升500。\u000a②：我方場上的表側表示的風屬性怪獸回到我方的手牌的場合可以發動。從牌組將1隻靈魂怪獸或1張儀式魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9560338,'魔導冥士 拉摩爾',unistr('此卡召喚、特殊召喚成功時可以發動。依照我方墓地的「魔導書」魔法卡的種類適用以下效果。「魔導冥士 拉摩爾」的效果1回合只能使用1次。\u000a●3種以上：此卡的攻擊力上升600。\u000a●4種以上：從牌組將1張「魔導書」魔法卡加入手牌。\u000a●5種以上：從牌組將1隻魔法使族、闇屬性、等級5以上的怪獸特殊召喚。'),'依照種類適用效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9567495,'鬥龍門',unistr('等級6怪獸×2\u000a「鬥龍門」1回合1次也能重疊在我方場上的階級3以下的超量怪獸上方來超量召喚。\u000a此卡在超量召喚的回合不能作為超量召喚的素材。\u000a①：1回合1次，可以發動。去除此卡的任意數量的超量素材。此卡的攻擊力上升去除的超量素材的種類（怪獸、魔法、陷阱）×1000，對手場上有怪獸存在的場合，那些怪獸的攻擊力下降相當於上升的數值。這個回合，此卡可以向全部對手怪獸各攻擊1次。'),'是否重疊在超量怪獸上方來超量召喚？','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9576193,'怪獸角子機','選擇我方場上表側表示存在的1隻怪獸，選擇我方墓地的1隻等級和那隻怪獸相同的怪獸除外。那之後，從我方牌組抽1張卡。這個效果抽到的卡給雙方確認，那是和選擇的怪獸相同等級的怪獸的場合，那隻怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9581215,'連鎖空洞','①：對手連鎖魔法、陷阱、怪獸的效果的發動，來發動怪獸的效果時可以發動。那個效果無效。那之後，對手可以從手牌、牌組選1張原卡名和被此效果無效的卡相同的卡除外。沒有除外的場合，我方可以將對手的手牌隨機選1張除外。','是否從手牌、牌組選1張同名卡除外？','是否選1張對手的手牌除外？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9583383,'我我我凱撒',unistr('我方場上有此卡以外的「我我我」怪獸存在的場合，此卡才能攻擊。\u000a此外，1回合1次，將我方墓地的1隻怪獸除外可以發動。我方場上的全部「我我我」怪獸的等級變成和為了發動此效果而除外的怪獸相同等級。\u000a此卡不能作為同步素材。'),'等級變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9591819,'我我我的逃脫劇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「我我我」怪獸存在，對手發動怪獸的效果時可以發動。那個發動無效。那之後，可以適用以下效果。\u000a●選1張我方的手牌捨棄，從牌組將1隻「我我我」怪獸特殊召喚。\u000a②：將墓地的此卡除外可以發動。我方場上的「我我我」怪獸全部變成守備表示，這個回合中，我方場上的「我我我」怪獸不會被戰鬥、效果破壞。'),'效果1','效果2','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9596126,'混沌巫師',unistr('此卡不能通常召喚。從我方墓地將光、闇屬性怪獸各1隻除外可以特殊召喚。\u000a①：1回合1次，以場上1隻表側表示怪獸為對象可以發動（此效果發動的整回合中，此卡不能攻擊）。那隻表側表示怪獸除外。'),'特殊召喚','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9597987,'天地晦冥',unistr('這個卡名在規則上也當作「忍法」卡片。\u000a①：我方的「忍者」怪獸給予對手戰鬥傷害時，以對手場上1張卡為對象可以發動。那張卡破壞。\u000a②：場地區域的表側表示的此卡因對手的效果從場上離開，被送去墓地的場合或被除外的場合，以我方墓地任意數量的「忍者」怪獸為對象可以發動（同名卡最多1張）。那些怪獸裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603252,'魔女工坊 代理大師',unistr('「魔女工坊」怪獸+魔法使族怪獸\u000a①：融合怪獸以外的魔法使族怪獸或魔法卡的效果發動時，可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●場上1張卡破壞。\u000a●從手牌、牌組將1隻等級6以下的「魔女工坊」怪獸特殊召喚。\u000a●從我方墓地將1張「魔女工坊」魔法、陷阱卡加入手牌。'),'●場上1張卡破壞','●從手牌、牌組特殊召喚','●從我方墓地加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603253,'魔女工坊 代理大師',unistr('「魔女工坊」怪獸+魔法使族怪獸\u000a①：融合怪獸以外的魔法使族怪獸或魔法卡的效果發動時，可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●場上1張卡破壞。\u000a●從手牌、牌組將1隻等級6以下的「魔女工坊」怪獸特殊召喚。\u000a●從我方墓地將1張「魔女工坊」魔法、陷阱卡加入手牌。'),'●場上1張卡破壞','●從手牌、牌組特殊召喚','●從我方墓地加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603356,'暗影騎士惡魔',unistr('此卡的控制者在每次我方準備階段必須支付900生命值。如果不能支付，此卡破壞。\u000a如果此卡成為對手的效果的對象，在那次處理時擲1次骰子。擲出3的場合，那個效果無效並破壞。\u000a此卡給予對手玩家的傷害變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9608555,'轉生炎獸 烈焰龍',unistr('等級4怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡被戰鬥、效果破壞的場合，去除此卡的1個超量素材作為代替。\u000a②：此卡沒有超量素材的場合，我方、對手的戰鬥階段可以發動。將1隻「轉生炎獸」超量怪獸重疊在我方場上的此卡上方，當作超量召喚從額外牌組特殊召喚。\u000a③：此卡用「轉生炎獸 烈焰龍」為素材超量召喚成功的場合可以發動。選對手場上1隻怪獸破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9617996,'獅王聖像騎士',unistr('包含「聖像騎士」怪獸的效果怪獸2隻\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡的攻擊力上升此卡指向的怪獸的原攻擊力數值。\u000a②：此卡指向的怪獸不能攻擊。\u000a③：此卡指向的區域有效果怪獸特殊召喚的場合可以發動。從牌組將1張「聖像騎士」魔法、陷阱卡加入手牌。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9622164,'D.D.R.','①：捨棄1張手牌，以被除外的1隻我方怪獸為對象可以發動此卡。那隻怪獸攻擊表示特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9627299,'齋潔狹依姬',unistr('此卡不能特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，我方場上有攻擊力或守備力是800的怪獸存在的場合可以發動。進行此卡的召喚。\u000a②：此卡召喚的場合可以發動。從牌組將「齋潔狹依姬」以外的1隻攻擊力或守備力是800且等級4的光、闇屬性怪獸加入手牌。\u000a③：此卡召喚、反轉的回合的結束階段發動。此卡回到手牌。'),'','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9627468,'甲蟲合體 鍬形蟲鬥士',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：昆蟲族怪獸特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡的攻擊力上升場上的其他昆蟲族怪獸數量×300。\u000a③：我方、對手的結束階段發動。雙方各自可以從自身的手牌、墓地將1隻昆蟲族怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'效果1','效果3','是否從手牌、墓地選1隻昆蟲族怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9628664,'地母神 艾莉絲','如果同一連鎖上沒有多次同名卡的效果發動，連鎖累積到3的場合，從我方牌組抽1張卡。','抽1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9633505,'守護者 姬絲特',unistr('我方場上沒有「靜寂之杖-姬絲特」的場合，此卡不能召喚、反轉召喚、特殊召喚。\u000a此卡不受魔法卡的效果影響，不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9634146,'信號戰士',unistr('協調+協調以外的怪獸1隻以上\u000a①：每次雙方的準備階段發動。給此卡和場地區域的表側表示的卡各放置1個信號計數器。\u000a②：已放置信號計數器的此卡不會被戰鬥以及對手的效果破壞。\u000a③：1回合1次，可以去除我方、對手場上的以下數量的信號計數器，發動那個效果。\u000a●4：給予對手800傷害。\u000a●7：我方從牌組抽1張卡。\u000a●10：選場上1張卡破壞。'),'放置計數器','●4：給予對手800傷害','●7：我方從牌組抽1張卡','●10：選場上1張卡破壞','','','','','','','','','','','','');
INSERT INTO texts VALUES(9637706,'死亡袋熊','只要此卡在場上表側表示存在，卡片效果給予此卡的控制者的傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9653271,'雷神之怒','「耳天使」+「大雷電球」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9659580,'方界業',unistr('①：此卡發動時，可以選擇「方界胤 毗濕奴」以外的我方場上1隻「方界」怪獸為對象。那個場合，從手牌、牌組將任意張數的「方界胤 毗濕奴」送去墓地。那之後，對象怪獸的攻擊力上升這個效果送去墓地的怪獸數量×800。\u000a②：對手回合中「方界」怪獸的效果讓「方界胤 毗濕奴」特殊召喚的場合發動。此卡送去墓地，對手的生命值變成一半。\u000a③：將墓地的此卡除外可以發動。從牌組將1隻「方界」怪獸加入手牌。'),'是否以「方界」怪獸為對象發動？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9666558,'石魔龍','只要此卡在場上表側表示存在，對手不能選擇表側表示存在的其他龍族怪獸作為攻擊對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9674034,'蛇眼梣樹靈',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻炎屬性、等級1怪獸加入手牌。\u000a②：將包含此卡的我方場上2張表側表示卡送去墓地可以發動。從手牌、牌組將「蛇眼梣樹靈」以外的1隻「蛇眼」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9677699,'玻璃鞋',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：裝備怪獸的種族是天使族的場合，裝備怪獸的攻擊力上升1000。天使族以外的場合，裝備怪獸不能攻擊，攻擊力下降1000。\u000a②：裝備怪獸被破壞讓此卡被送去墓地的場合，以我方場上1隻「仙杜瑞拉」為對象可以發動。此卡給那隻我方的「仙杜瑞拉」裝備。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9709452,'烈日的騎士 蓋亞烈焰',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡的攻擊破壞對手怪獸時可以發動。此卡只有1次可以繼續攻擊。\u000a②：我方、對手的戰鬥階段結束時，最多到這個回合此卡戰鬥破壞的怪獸數量，以我方墓地的炎屬性怪獸為對象可以發動。那些怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9715126,'起動指令 齒輪之力','①：如果我方場上的怪獸只有機械族怪獸，我方或對手的怪獸的攻擊宣言時可以發動。最多到我方場上的機械族怪獸數量，選對手場上的攻擊表示怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9718968,'光子殺戮者','場上有超量怪獸存在的場合，此卡可以從手牌表側守備表示特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9720537,'所有者的刻印','①：場上的全部怪獸的控制權回歸原持有者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9726840,'閃刀起動-連刀','①：我方的主要怪獸區域沒有怪獸存在的場合可以發動。我方場上1張其他卡送去墓地，從額外牌組將1隻「閃刀姬」怪獸在額外怪獸區域特殊召喚。我方的場上、墓地有光屬性和闇屬性的「閃刀姬」怪獸各1隻以上存在的場合，此效果特殊召喚的怪獸的攻擊力上升1000。此卡的發動後，直到回合結束時我方除了「閃刀姬」怪獸以外不能從額外牌組特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9742784,'噴射同步者',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡作為同步素材送去墓地的場合可以發動。從牌組將1隻「廢品」怪獸加入手牌。\u000a②：此卡在墓地存在的場合，將1張手牌送去墓地可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'檢索','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9744376,'哥布林的精打細算','依照我方墓地的「哥布林的精打細算」的數量+1張，從我方的牌組抽牌，選1張我方的手牌放到牌組最下方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9748752,'邪帝 蓋烏斯','①：此卡上級召喚成功的場合，以場上1張卡為對象發動。那張卡除外，除外的卡是闇屬性怪獸卡的場合，給予對手1000傷害。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9753964,'琰魔龍 暗紅惡魔邃淵',unistr('協調+協調以外的龍族、闇屬性同步怪獸1隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，以對手場上1張表側表示卡為對象可以發動。那張卡的效果直到回合結束時無效。\u000a②：此卡給予對手戰鬥傷害時，以我方墓地1隻協調為對象可以發動。那隻怪獸守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9763474,'盛悴的藥蜥',unistr('卡名不同的怪獸2隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：從我方的場上（表側表示）、墓地將1隻攻擊力2000以下的怪獸除外，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時變成和為了發動此效果而除外的怪獸的原攻擊力相同。將原種族是爬蟲類族的怪獸除外發動的場合，隨後我方抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9765723,'女武神的契約書',unistr('「女武神的契約書」的①效果1回合只能使用1次。\u000a①：從手牌將1張「DD」卡片或「契約書」卡片送去墓地，以場上1張卡為對象可以發動。那張卡破壞。\u000a②：只要此卡在魔法與陷阱區域存在，我方場上的惡魔族怪獸的攻擊力在對手回合中上升1000。\u000a③：我方準備階段發動。我方受到1000傷害。'),'破壞場上的卡片','受到1000傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9780364,'劍鬥調教',unistr('場上有「劍鬥獸」怪獸存在的場合，可以從以下效果選擇1個發動。\u000a●選擇對手場上1隻表側表示怪獸，將表示形式變更。\u000a●選擇對手場上1隻「劍鬥獸」怪獸，直到結束階段時得到控制權。'),'●變更表示形式','●得到控制權','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9785661,'飢渴聖徒 索爾厄律西克同',unistr('幻想魔族怪獸+惡魔族怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡融合召喚的場合，以場上1張卡為對象可以發動。那張卡送去墓地。\u000a②：我方、對手的準備階段，以我方墓地1張「聖徒」卡片或「罪寶」卡片為對象可以發動。那張卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9786492,'白龍降臨',unistr('「白龍的騎士」的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計為4以上為止，從手牌儀式召喚「白龍的騎士」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9791914,'白銀的狙擊手',unistr('此卡可以當作魔法卡從手牌覆蓋在魔法與陷阱區域。\u000a覆蓋在魔法與陷阱區域的此卡被對手的卡片效果破壞送去墓地的回合的結束階段時，此卡從墓地特殊召喚，選擇對手場上的1張卡破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9794980,'夢魘曲 轉星之易德麗絲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：場上的連結怪獸的連結標記合計為8以上的場合可以發動。此卡從手牌特殊召喚。此效果在對手回合也能發動。\u000a②：對手場上的連結怪獸數量比我方場上的連結怪獸多的狀態，此卡特殊召喚成功的場合可以發動。場上的連結怪獸全部送去墓地。\u000a③：我方場上的等級9怪獸不會被效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9798352,'奇采的普魯菲尼斯',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，從牌組將1張陷阱卡除外可以發動。此卡的等級上升1。\u000a②：以我方或對手的墓地1張陷阱卡為對象可以發動。那張卡除外，此卡的等級上升1。\u000a③：此卡被對手破壞的場合可以發動。選除外的1張我方的通常陷阱卡在我方場上覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9817927,'反怒的貓熊','對手場上每有1隻怪獸，此卡的攻擊力上升500。此卡攻擊守備表示怪獸時，給予對手攻擊力超過守備力數值的戰鬥傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9822220,'天獄之王',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方主要階段可以發動。手牌的此卡直到對手回合結束時公開。此效果公開期間，場上的裡側表示卡不會被效果破壞。\u000a②：覆蓋的魔法、陷阱卡發動的場合可以發動。此卡從手牌特殊召喚。以在手牌被公開中的狀態發動此效果的場合，隨後可以從牌組將1張魔法、陷阱卡在我方場上覆蓋。那張卡在下個回合的結束階段除外。'),'效果1','效果2','是否從牌組將1張魔法、陷阱卡覆蓋？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9831539,'唐懷瑟之門','選擇我方場上2隻攻擊力1000以下的相同種族的怪獸可以發動。選擇的2隻怪獸變成那2隻的等級合計的等級。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9837195,'薰風的神官 姆斯特','1回合1次，我方的主要階段時可以發動。選擇我方墓地的1隻「薰風」怪獸回到牌組，選擇場上的1隻表側表示怪獸，那個效果直到回合結束時無效。','效果無效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9839115,'月朧龍 巴庫那瓦',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡同步召喚的場合可以發動。此卡的攻擊力直到下個回合結束時上升那些作為同步素材的協調以外的怪獸的等級總和×300。那之後，給予對手那隻作為同步素材的協調的等級×300傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9839945,'照耀的光靈使 萊娜',unistr('包含光屬性怪獸的怪獸2隻\u000a這個卡名在規則上也當作「憑依裝著」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：以對手墓地1隻光屬性怪獸為對象可以發動。那隻怪獸在此卡指向的我方場上特殊召喚。\u000a②：連結召喚的此卡被戰鬥或對手的效果破壞的場合可以發動。從牌組將1隻守備力1500以下的光屬性怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9845733,'覺醒之証','「覺醒戰士 庫弗林」的降臨所必需。必須從我方的手牌、場上解放怪獸直到等級合計為4以上為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9848939,'樹海的射手',unistr('此卡不能通常召喚。只能在我方墓地有2隻以上通常怪獸存在的場合特殊召喚。\u000a藉由將此卡解放，從我方牌組將1隻二重怪獸加入手牌。'),'從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9852718,'訣別','①：在對手戰鬥階段，從手牌將1張魔法卡送去墓地可以發動。那次戰鬥階段結束。場上的表側表示怪獸直到回合結束時效果無效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9861795,'遁地鼴鼠','場上的此卡被破壞送去墓地時，此卡可以從墓地表側守備表示特殊召喚。「遁地鼴鼠」的效果在決鬥中只能使用1次。','此卡特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9888196,'正義盟軍 決戰兵器',unistr('協調+協調以外的怪獸2隻以上\u000a對手場上有光屬性怪獸存在的場合，1回合1次，可以從以下效果選擇1個發動。\u000a●選擇對手場上1張覆蓋的卡破壞。\u000a●藉由將1張手牌送去墓地，對手場上的魔法、陷阱卡全部破壞。\u000a●藉由將我方的全部手牌送去墓地，確認對手的手牌並將其中的光屬性怪獸全部送去墓地。那之後，給予對手此效果送去墓地的怪獸的攻擊力合計數值的傷害。'),'●對手場上1張覆蓋的卡破壞','●對手場上魔法陷阱全部破壞','●確認對手的手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9897998,'薰風鷲','此卡戰鬥破壞對手怪獸送去墓地時，可以從我方牌組將1隻守備力1500以下的超能族、風屬性怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9910360,'三死青蛙',unistr('「死亡青蛙」+「死亡青蛙」+「死亡青蛙」\u000a此卡的融合召喚只能使用上述卡進行。\u000a此卡的攻擊力上升我方墓地的「黃泉青蛙」的數量×500。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9925982,'黑色復仇','①：我方場上的鳥獸族怪獸被戰鬥破壞送去墓地時可以發動。在我方場上將2隻「BF-黑冠羽衍生物」（鳥獸族、闇、等級2、攻0/守800）特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9925983,'BF-黑冠羽衍生物','由「黑色復仇」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9929398,'BF-朧影之業風',unistr('此卡不能通常召喚。我方場上沒有怪獸存在的場合可以特殊召喚。\u000a①：此卡從手牌特殊召喚成功時可以發動。在我方場上將2隻「朧影衍生物」（鳥獸族、闇、等級1、攻/守0）特殊召喚。這個衍生物不能解放，不能作為同步素材。\u000a②：從我方場上將此卡和1隻以上協調以外的怪獸除外，以我方墓地1隻等級和那個等級合計相同的「BF」同步怪獸為對象可以發動。那隻怪獸當作協調特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9929399,'朧影衍生物','由「BF-朧影之業風」的效果特殊召喚。這個衍生物不能解放，不能作為同步素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9940036,'分體論聚合員',unistr('等級9怪獸×2隻以上\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡超量召喚的場合可以發動。從額外牌組將1隻怪獸送去墓地。\u000a②：最多到此卡的超量素材數量，以我方墓地的怪獸為對象可以發動。依照對象怪獸的數量去除此卡的超量素材，將對象怪獸作為此卡的超量素材。\u000a③：此卡被送去墓地的場合，以場上1張表側表示卡為對象可以發動。那張卡的效果直到回合結束時無效。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9952083,'召喚連鎖','①：同一連鎖上沒有多次同名卡的效果發動的場合，那個連鎖3以後可以發動。這個回合我方可以進行通常召喚最多3次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9978697,'X-軍刀 佩里娜',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，將此卡送去墓地可以發動。從牌組將「X-軍刀 佩里娜」以外的2隻「X-軍刀」怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。\u000a②：此卡作為「X-軍刀」同步怪獸的同步素材送去墓地的場合可以發動。從以下挑選1個適用。\u000a●那隻怪獸在1次戰鬥階段中可以攻擊2次。\u000a●那隻怪獸可以直接攻擊。'),'效果1','效果2','●攻擊2次','●直接攻擊','攻擊2次（X-軍刀 佩里娜）','直接攻擊（X-軍刀 佩里娜）','','','','','','','','','','');
INSERT INTO texts VALUES(9989792,'古代遺跡要塞',unistr('「古代遺跡要塞」的③效果1回合只能使用1次。\u000a①：場上的岩石族怪獸的守備力上升500。\u000a②：場上的「古代遺跡」怪獸不會被效果破壞。\u000a③：場地區域的表側表示的此卡被送去墓地的場合，以我方墓地1隻「古代遺跡」怪獸為對象可以發動。那隻怪獸加入手牌。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9995766,'宮廷的規矩',unistr('①：「宮廷的規矩」在我方場上只能有1張表側表示存在。\u000a②：只要此卡在魔法與陷阱區域存在，「宮廷的規矩」以外的雙方場上的表側表示的永續陷阱卡不會被戰鬥、效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9999961,'野獸之怒','我方場上的全部怪獸的攻擊力上升被除外的我方的獸族、鳥獸族怪獸數量×200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000000,'歐貝利斯克的巨神兵',unistr('通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動卡的效果。\u000a③：雙方不能將場上的此卡作為效果的對象。\u000a④：將我方場上2隻怪獸解放可以發動（此效果發動的整回合中，此卡不能攻擊宣言）。對手場上的怪獸全部破壞。\u000a⑤：如果此卡已被特殊召喚，結束階段發動。此卡送去墓地。'),'效果5','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000001,'歐貝利斯克的巨神兵',unistr('通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動卡的效果。\u000a③：雙方不能將場上的此卡作為效果的對象。\u000a④：將我方場上2隻怪獸解放可以發動（此效果發動的整回合中，此卡不能攻擊宣言）。對手場上的怪獸全部破壞。\u000a⑤：如果此卡已被特殊召喚，結束階段發動。此卡送去墓地。'),'效果5','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000002,'歐貝利斯克的巨神兵',unistr('通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動卡的效果。\u000a③：雙方不能將場上的此卡作為效果的對象。\u000a④：將我方場上2隻怪獸解放可以發動（此效果發動的整回合中，此卡不能攻擊宣言）。對手場上的怪獸全部破壞。\u000a⑤：如果此卡已被特殊召喚，結束階段發動。此卡送去墓地。'),'效果5','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000003,'歐貝利斯克的巨神兵',unistr('通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動卡的效果。\u000a③：雙方不能將場上的此卡作為效果的對象。\u000a④：將我方場上2隻怪獸解放可以發動（此效果發動的整回合中，此卡不能攻擊宣言）。對手場上的怪獸全部破壞。\u000a⑤：如果此卡已被特殊召喚，結束階段發動。此卡送去墓地。'),'效果5','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000004,'歐貝利斯克的巨神兵',unistr('通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動卡的效果。\u000a③：雙方不能將場上的此卡作為效果的對象。\u000a④：將我方場上2隻怪獸解放可以發動（此效果發動的整回合中，此卡不能攻擊宣言）。對手場上的怪獸全部破壞。\u000a⑤：如果此卡已被特殊召喚，結束階段發動。此卡送去墓地。'),'效果5','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000005,'歐貝利斯克的巨神兵',unistr('通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動卡的效果。\u000a③：雙方不能將場上的此卡作為效果的對象。\u000a④：將我方場上2隻怪獸解放可以發動（此效果發動的整回合中，此卡不能攻擊宣言）。對手場上的怪獸全部破壞。\u000a⑤：如果此卡已被特殊召喚，結束階段發動。此卡送去墓地。'),'效果5','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000010,'拉的翼神龍',unistr('此卡不能特殊召喚。通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動其他卡的效果。\u000a③：此卡召喚時，支付生命值到100為止可以發動。此卡的攻擊力、守備力上升支付的數值。\u000a④：支付1000生命值，以場上1隻怪獸為對象可以發動。那隻怪獸破壞。'),'效果3','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000011,'拉的翼神龍',unistr('此卡不能特殊召喚。通常召喚此卡的場合，必須解放3隻怪獸來召喚。\u000a①：此卡的召喚不會被無效化。\u000a②：在此卡的召喚成功時，雙方不能發動其他卡的效果。\u000a③：此卡召喚時，支付生命值到100為止可以發動。此卡的攻擊力、守備力上升支付的數值。\u000a④：支付1000生命值，以場上1隻怪獸為對象可以發動。那隻怪獸破壞。'),'效果3','效果4','解放3隻怪獸召喚','','','','','','','','','','','','','');
