INSERT INTO texts VALUES(38035986,'紅A','施放死亡詛咒的法師。聽到咒文的敵人將變得神智不清。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38041940,'火焰的種子','我方場上的此卡被效果破壞送去墓地時可以發動。從我方墓地選擇「火焰的種子」以外的1隻等級4以下的植物族怪獸在我方場上特殊召喚，在對手場上將1隻「種子衍生物」（植物族、地、等級1、攻/守0）守備表示特殊召喚。這個衍生物不能為了上級召喚而解放。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38041941,'種子衍生物','由「火焰的種子」的效果特殊召喚。這個衍生物不能為了上級召喚而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38044854,'起升階魔法-急襲猛禽之力',unistr('這個卡名在規則上也當作「RR-」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：我方、對手的主要階段以及對手戰鬥階段，以包含場上的怪獸的我方的場上、墓地的2隻以上「RR-」超量怪獸為對象可以發動。將1隻階級和那2隻以上的怪獸的階級合計相同的「RR-」超量怪獸當作超量召喚從額外牌組特殊召喚，對象怪獸作為那個超量素材（對象怪獸持有超量素材的場合，那些也全部作為超量素材）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38049541,'盟軍次世代化學家','①：我方、對手回合，將此卡從手牌捨棄，以我方場上1隻「次世代」怪獸為對象，宣言1個屬性可以發動。那隻我方的「次世代」怪獸變成宣言的屬性。','改變屬性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38049934,'炎塵爆發','將我方墓地的「熔岩」怪獸全部除外可以發動。最多到為了發動此卡而除外的怪獸數量，選場上的卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38053381,'王戰的舞臺',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，對手從牌組將卡加入手牌的場合可以發動。從牌組將1隻「王戰」怪獸守備表示特殊召喚。\u000a②：對手回合，我方將「王戰」怪獸特殊召喚成功的場合可以發動。在我方場上將「王戰衍生物」（天使族、光、等級4、攻/守1500）盡可能攻擊表示特殊召喚。這些衍生物在結束階段破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38053382,'王戰衍生物','由「王戰的舞臺」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38057522,'大靈術-「一輪」',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要我方場上有守備力1500的魔法使族怪獸存在，對手發動的怪獸的效果1回合只有1次無效化。\u000a②：我方主要階段可以發動。向對手展示手牌的1隻魔法使族怪獸，從牌組將1隻和那隻怪獸相同屬性且攻擊力1500/守備力200的怪獸加入手牌，展示的怪獸回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38082437,'變形鬥士 電話',unistr('①：此卡依照表示形式得到以下效果。\u000a●攻擊表示：1回合1次，我方主要階段可以發動。擲1次骰子。我方回復擲出點數×100生命值。那之後，可以從我方墓地選1隻等級在擲出點數以下的「變形鬥士」怪獸特殊召喚。\u000a●守備表示：1回合1次，我方主要階段可以發動。擲1次骰子，從我方牌組上方翻開擲出點數的數量的卡。可以從其中選1張「變形鬥士」卡片送去墓地。其餘以喜歡的順序回到牌組上方或下方。'),'●攻擊表示：','是否從墓地特殊召喚？','●守備表示：','是否選1張卡送去墓地？','回到牌組上方','回到牌組下方','','','','','','','','','','');
INSERT INTO texts VALUES(38105306,'逐漸削減的生命',unistr('①：「逐漸削減的生命」在我方場上只能有1張表側表示存在。\u000a②：對手結束階段發動。給此卡放置1個計數器。\u000a③：此卡已放置計數器的場合，我方、對手的主要階段以及戰鬥階段可以發動。此卡送去墓地。那之後，最多到此卡放置的計數器數量，對手盡可能選擇手牌捨棄。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38107923,'黑暗奈芙蒂斯',unistr('我方的主要階段時，我方墓地的闇屬性怪獸有3隻以上的場合，藉由將其中2隻除外，此卡從手牌送去墓地。\u000a下個我方的準備階段時，將被這個效果送去墓地的此卡從墓地特殊召喚。\u000a此卡特殊召喚成功時，選擇場上的1張魔法、陷阱卡破壞。'),'從手牌送去墓地','特殊召喚','破壞魔法、陷阱卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38109772,'龍之騎士','對手怪獸發動要讓我方場上的卡破壞的效果時，將成為對象的我方的卡全部送去墓地可以發動。此卡從手牌特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38116136,'機械突擊兵','特攻用的機械。以突擊之力打倒敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38120068,'抵價購物','①：從手牌捨棄1隻等級8怪獸可以發動。我方抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38124994,'絨毛動物兔',unistr('「絨毛動物兔」的效果1回合只能使用1次。\u000a①：此卡作為融合素材送去墓地的場合，以我方墓地1隻「鋒利小鬼 剪刀」或1隻「絨毛動物兔」以外的「絨毛動物」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38129297,'雙重扳機',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●包含「槍彈」怪獸的我方墓地的怪獸作為融合素材除外，將1隻融合怪獸融合召喚。\u000a●直到等級合計為儀式召喚的怪獸的等級以上為止，將包含「槍彈」怪獸的我方墓地的怪獸除外，從手牌將1隻儀式怪獸儀式召喚。'),'效果1','●融合召喚','●儀式召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38142739,'小天使','依靠靈活行動閃避攻擊，很小的天使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38143903,'腦內審判',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方或對手發動場上的怪獸的效果時可以發動。發動那個效果的玩家投擲1次硬幣，猜正反面。如果猜對，此卡送去墓地。如果猜錯，那個發動無效，那隻怪獸的控制權移給那個玩家所見的對手。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38148100,'芬芳熾天使-薔薇迷迭香',unistr('協調+協調以外的怪獸1隻以上\u000a①：只要我方的生命值高於對手，且此卡在怪獸區域存在，我方場上的植物族怪獸的攻擊力、守備力上升500。\u000a②：1回合1次，我方的生命值回復的場合，以對手場上1張表側表示卡為對象發動。那張卡的效果直到回合結束時無效。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38167722,'闇靈術-「欲」','解放我方場上的1隻闇屬性怪獸可以發動。對手可以從手牌展示1張魔法卡讓此卡的效果無效。不展示的場合，我方從牌組抽2張卡。','是否從手牌展示1張魔法卡使此卡無效？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38173725,'電弧火箭光船',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上沒有怪獸存在的場合，此卡可以不用解放來召喚。\u000a②：此卡召喚、特殊召喚成功的場合，以我方墓地1隻等級8以下的機械族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的等級變成9，效果無效化。\u000a③：只要此卡在怪獸區域存在，我方除了機械族超量怪獸以外不能從額外牌組特殊召喚。'),'不解放的召喚','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38179121,'究極進化藥',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、墓地將1隻恐龍族怪獸和1隻恐龍族以外的怪獸除外可以發動。從手牌、牌組將1隻等級7以上的恐龍族怪獸無視召喚條件特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38180759,'虛構王 無定形虛空',unistr('等級4怪獸×3\u000a對手的主要階段時1次，去除此卡的1個超量素材可以發動。此卡的攻擊力、守備力上升對手場上的超量怪獸的攻擊力合計數值。'),'攻守上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38192988,'真紅眼不死龍皇',unistr('不死族協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：對手回合，以「真紅眼不死龍皇」以外的我方墓地1隻不死族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：此卡在墓地存在的場合，將我方場上1隻不死族怪獸除外可以發動。此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38199696,'紅藥水','我方回復500生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38203732,'靈擺悖論',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的額外牌組的表側表示的靈擺怪獸之中選2隻靈擺刻度相同且卡名不同的怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38210374,'爆貘團',unistr('我方的主要階段時，手牌或我方場上的這隻怪獸，可以當作裝備卡給對手場上的1隻超量怪獸裝備。\u000a用此效果裝備此卡的怪獸沒有超量素材的場合，那隻怪獸破壞。\u000a此卡當作裝備卡裝備中的場合，每次對手的準備階段，去除裝備怪獸的1個超量素材。'),'變成裝備卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38229962,'大騎甲蟲 無敵阿特拉斯',unistr('昆蟲族怪獸2隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：連結召喚的此卡的攻擊力是3000以下的場合，此卡不會成為對手的效果的對象，不會被對手的效果破壞。\u000a②：只要此卡在怪獸區域存在，我方除了昆蟲族怪獸以外不能特殊召喚。\u000a③：可以將我方場上1隻昆蟲族怪獸解放，從以下效果選擇1個發動。\u000a●從牌組將1隻「騎甲蟲」怪獸特殊召喚。\u000a●此卡的攻擊力直到回合結束時上升2000。'),'●從牌組特殊召喚','●攻擊力上升2000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38247752,'暗眼幻像師','反轉：選擇場上的1隻怪獸發動。只要此卡在場上表側表示存在，選擇的怪獸不能攻擊。','反轉','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38250531,'紅貴士-吸血鬼布拉姆',unistr('不死族等級5怪獸×2\u000a這個卡名的①效果1回合只能使用1次。\u000a①：去除此卡的1個超量素材，以對手墓地1隻怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。此效果特殊召喚成功的回合，那隻怪獸以外的我方怪獸不能攻擊。\u000a②：場上的此卡被對手破壞送去墓地的下個回合的準備階段發動。此卡從墓地守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38264974,'幻想魔獸 客邁拉',unistr('「有翼幻獸 客邁拉」+幻想魔族怪獸1隻以上\u000a①：只要此卡在場上、墓地存在，卡名當作「有翼幻獸 客邁拉」。\u000a②：此卡在1次戰鬥階段中可以向怪獸攻擊多次，次數上限為作為此卡的融合素材的怪獸數量。\u000a③：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a④：此卡和對手怪獸進行戰鬥的傷害步驟結束時可以發動。那隻對手怪獸的攻擊力變成0，效果無效化。'),'效果4','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38265153,'電子能量衝擊',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「人造人-念力震懾者」存在的場合，以場上1張卡為對象可以發動。那張卡破壞。此效果將場上的陷阱卡破壞的場合，隨後可以從以下效果挑選1個適用。\u000a●挑選場上1張表側表示的卡，那個效果直到回合結束時無效。\u000a●我方場上的全部「人造人-念力震懾者」的攻擊力上升800。\u000a\u000a※電腦能量衝擊'),'不選擇效果','●表側表示的卡無效','●攻擊力上升800','請選擇要無效的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(38267552,'夢魔鏡的黑騎士-盧甫斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用「夢魔鏡」怪獸的效果特殊召喚成功的場合，以場上1張卡為對象可以發動。那張卡破壞。\u000a②：場地區域有「聖光的夢魔鏡」存在的場合，我方、對手主要階段和戰鬥階段，解放此卡可以發動。從牌組將1隻「夢魔鏡的白騎士-盧甫斯」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38273745,'入魔烏洛波洛斯',unistr('等級4怪獸×3\u000a1回合1次，可以去除此卡的1個超量素材，從以下效果選擇1個發動。此卡在場上表側表示存在期間，以下效果各能選擇1次。\u000a●選擇對手場上的1張卡回到持有者的手牌。\u000a●對手的手牌隨機選1張送去墓地。\u000a●選擇對手墓地的1張卡除外。'),'N/A','●對手場上的1張卡回到手牌','●手牌隨機選1張送去墓地','●對手墓地的1張卡除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(38275183,'八式對魔法多重結界',unistr('可以從以下效果選擇1個發動。\u000a●以場上的1隻怪獸為對象的魔法卡發動時可以發動。那個發動無效並破壞。\u000a●魔法卡發動時，從手牌將1張魔法卡送去墓地可以發動。那個發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38277918,'新月龍','據說來自月亮，手持三日月刀的龍戰士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38280762,'紫炎的老中 緣',unistr('此卡不能通常召喚。只能將我方墓地的2隻「六武眾」怪獸除外來特殊召喚。\u000a1回合1次，可以選擇場上的1隻表側表示怪獸破壞。此效果發動的整回合中，此卡不能攻擊宣言。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38289717,'貪屍龍','什麼都能咬碎的恐龍，攻擊力十分恐怖。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38296564,'安全地帶',unistr('以場上1隻表側攻擊表示怪獸為對象可以發動此卡。\u000a①：只要此卡在魔法與陷阱區域存在，那隻表側表示怪獸不會成為對手的效果的對象，不會被戰鬥以及對手的效果破壞，不能直接攻擊對手。此卡從場上離開時那隻怪獸破壞。那隻怪獸從場上離開時此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38299233,'針牆','我方準備階段發動。擲1次骰子。對手的主要怪獸區域從此卡的控制者所見的右方分成1～5格，擲出點數的主要怪獸區域的怪獸破壞。擲出6的場合，重新擲骰子。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38318146,'暴君的暴力',unistr('將我方場上的2隻怪獸解放可以發動。\u000a只要此卡在場上表側表示存在，對手必須從牌組將1張魔法卡送去墓地，才能發動魔法卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38325384,'魔導加速',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方牌組上方將2張卡送去墓地，以場上1張可以放置魔力計數器的卡為對象可以發動。給那張卡放置最多2個魔力計數器。\u000a②：此卡被對手的效果破壞的場合可以發動。從牌組將1隻可以放置魔力計數器的怪獸特殊召喚，給那隻怪獸放置最多2個魔力計數器。'),'是否放置2個魔力計數器？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38331564,'光天使 杖',unistr('①：此卡召喚、特殊召喚成功時可以發動。從牌組將「光天使 杖」以外的1隻「光天使」怪獸加入手牌。\u000a②：用包含場上的此卡的3隻以上怪獸為素材超量召喚的怪獸得到以下效果。\u000a●這次超量召喚成功時，以此卡以外的場上1張卡為對象可以發動。那張卡破壞，我方可以從牌組抽1張卡。'),'效果1','●破壞並抽牌（光天使 杖）','是否從牌組抽1張卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38339996,'R-ACE 脈衝消防員',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。挑選對手場上1隻攻擊力最高的效果怪獸。這個回合，雙方不能發動那隻表側表示怪獸的在場上發動的效果。\u000a②：對手在場上發動怪獸的效果時，將手牌、場上的此卡解放可以發動。從牌組將1隻機械族的「R-ACE」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38342335,'夢魘曲 獨角獸',unistr('卡名不同的怪獸2隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚成功的場合，捨棄1張手牌，以場上1張卡為對象可以發動。那張卡回到牌組。此效果的發動時此卡是互相連結狀態的場合，隨後我方可以抽1張卡。\u000a②：只要互相連結狀態的「夢魘曲」怪獸存在，我方抽牌階段的通常抽牌的張數變成那些「夢魘曲」怪獸種類的數量。'),'效果1','是否抽1張卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38342336,'夢魘曲 獨角獸',unistr('卡名不同的怪獸2隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚成功的場合，捨棄1張手牌，以場上1張卡為對象可以發動。那張卡回到牌組。此效果的發動時此卡是互相連結狀態的場合，隨後我方可以抽1張卡。\u000a②：只要互相連結狀態的「夢魘曲」怪獸存在，我方抽牌階段的通常抽牌的張數變成那些「夢魘曲」怪獸種類的數量。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38354018,'超弩級砲塔列車 飛行發射器',unistr('等級10怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡超量召喚的場合可以發動。從牌組將1隻機械族、地屬性怪獸或1張「掃射特攻」加入手牌。\u000a②：只要此卡在怪獸區域存在，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻機械族怪獸。\u000a③：去除此卡的任意數量的超量素材，以那個數量的場上的魔法、陷阱卡為對象可以發動。那些卡破壞。'),'效果1','召喚（超弩級砲塔列車 飛行發射器）','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38354937,'真次世代黑機神',unistr('「次世代」協調+協調以外的闇屬性怪獸1隻以上\u000a①：此卡同步召喚的場合發動。得到對手場上的等級最高的1隻怪獸的控制權。'),'獲得控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38356857,'咒法冷酷',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：儀式召喚1隻水屬性的儀式怪獸的場合，可以使用1張此卡作為儀式召喚所需的解放。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從牌組將「咒法冷酷」以外的1隻「咒法」怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了用儀式怪獸以外不能攻擊宣言。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38363525,'不死屍化',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：場上有等級5以上的不死族怪獸存在的場合，以對手場上1隻怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。\u000a②：此卡在墓地存在的場合可以發動。選被除外的1隻我方的不死族怪獸回到牌組，此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38369349,'卡通龍蛋',unistr('此卡不能通常召喚。我方場上有「卡通世界」存在，解放我方場上的2隻怪獸可以特殊召喚。\u000a①：此卡在特殊召喚的回合不能攻擊。\u000a②：此卡的攻擊宣言之際，我方必須支付500生命值。\u000a③：對手場上沒有卡通怪獸存在的場合，此卡可以直接攻擊。存在的場合，只能選擇卡通怪獸作為攻擊對象。\u000a④：場上的「卡通世界」被破壞時，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38379052,'阿爾戈☆群星-屠龍的艾提翁',unistr('①：只要此卡在魔法與陷阱區域存在，我方場上的戰士族怪獸不會被效果破壞。\u000a②：1回合1次，對手發動效果時可以發動。此卡當作持有以下效果的效果怪獸（戰士族、光、等級4、攻/守800）在怪獸區域特殊召喚（也當作陷阱卡）。我方的「阿爾戈☆群星」怪獸已被除外的場合，隨後可以讓場上1張卡回到手牌。\u000a●我方、對手回合1次，可以發動。此卡在我方的魔法與陷阱區域表側表示放置。'),'效果2','●在魔法與陷阱區域表側表示放置','是否讓場上1張卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38383368,'三角龍裝臨時演員',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在墓地存在，額外怪獸區域的怪獸被主要怪獸區域的怪獸戰鬥破壞送去墓地時可以發動。此卡在那隻被破壞的額外怪獸區域的怪獸的持有者的場上守備表示特殊召喚。\u000a②：此卡的①效果特殊召喚的此卡被破壞送去墓地的場合發動。我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38395123,'搗蛋混合賽',unistr('①：從手牌以及我方場上的表側表示的卡之中將1張「搗蛋」卡片送去墓地可以發動。從我方的牌組、墓地選卡名和那張卡不同的1隻「搗蛋」怪獸和1隻「武裝龍」怪獸加入手牌。那之後，可以將此效果加入手牌的1隻怪獸召喚。\u000a②：我方主要階段將墓地的此卡除外，以被除外的3隻我方的「搗蛋」怪獸為對象可以發動。那些怪獸加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'是否選1隻加入手牌的怪獸召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38406364,'常夏的避暑雷神',unistr('雷族怪獸2隻\u000a①：對手回合1次，捨棄1張手牌，以連結怪獸以外的我方墓地1隻雷族怪獸為對象可以發動。那隻怪獸在此卡指向的我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38409239,'游魊宇宙',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：依照除外狀態的魚族怪獸數量，以下效果各自適用。\u000a●1隻以上：這個回合，我方的魚族怪獸不會被戰鬥破壞。\u000a●4隻以上：這個回合，我方場上的魚族怪獸的效果的發動以及那些發動的效果不會被無效化。\u000a●8隻以上：從額外牌組將1隻魚族同步怪獸當作同步召喚特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38411870,'掉落的天井','場上有4隻以上怪獸存在的場合可以發動。場上的表側表示怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38412161,'靈塞術師 澄最',unistr('①：只要此卡在怪獸區域存在，雙方不能發動墓地的魔法、陷阱卡的效果。\u000a②：此卡從場上送去墓地的場合，以對手墓地1張魔法、陷阱卡為對象可以發動。那張卡除外。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38423248,'召喚獸 偉魔狂獸',unistr('「召喚師 阿萊斯特」+融合、同步、超量、連結怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方墓地1隻融合、同步、超量、連結怪獸和場上1隻怪獸為對象可以發動。那些怪獸除外。\u000a②：融合召喚的此卡被戰鬥、效果破壞的場合可以發動。從牌組將1隻魔法使族、等級4怪獸特殊召喚。那之後，可以將此卡當作攻擊力上升1000的裝備魔法卡給那隻怪獸裝備。'),'效果1','效果2','是否裝備？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38430673,'大十字星','我方場上有「宏觀宇宙」存在時可以發動。給予對手300傷害，場上的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38436986,'珠淚哀歌的爪音',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有「珠淚哀歌」怪獸或「維薩斯-星霜」存在的場合，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。那之後，從牌組將1隻「珠淚哀歌」怪獸送去墓地。\u000a②：此卡被效果送去墓地的場合，以我方墓地1隻「珠淚哀歌」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38445524,'鉤刀魔','身穿鋼鐵鎧甲的殺戮機器。使用巨刀攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38450736,'甲蟲裝機 蠼螋',unistr('1回合1次，可以從我方的手牌、墓地將1隻「甲蟲裝機」怪獸當作裝備卡給此卡裝備。\u000a此卡已當作裝備卡裝備的場合，裝備怪獸的攻擊力、守備力上升此卡的對應數值。\u000a給怪獸裝備的此卡被送去墓地時，裝備怪獸的攻擊力直到回合結束時上升1000。'),'裝備','攻擊力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38459905,'F.A. 試跑',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「F.A.」怪獸為對象可以發動。那隻怪獸的表示形式變更。那之後，選場上1張卡破壞。\u000a②：我方主要階段將墓地的此卡除外，以我方場上1張表側表示的卡為對象可以發動。那張卡破壞，從牌組將1隻「F.A.」怪獸特殊召喚。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38468214,'類催眠外星人',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●選擇對手場上1隻已放置A計數器的怪獸，得到控制權。每到我方的結束階段，去除得到控制權的怪獸的1個A計數器。如果得到控制權的怪獸的A計數器全部被去除，那隻怪獸破壞。'),'得到控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38479725,'特洛伊木馬','地屬性怪獸上級召喚的場合，此卡可以當作2隻解放。','地屬性雙祭品','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38480590,'女豹的傭兵','解放表側表示的此卡可以發動。選擇1隻這個回合被戰鬥破壞送去我方墓地的怪獸回到牌組最上方。','回到牌組','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38491199,'廢品栗子球','①：對手發動給予我方傷害的魔法、陷阱、怪獸的效果時，將我方的手牌、場上的此卡送去墓地可以發動。那個發動無效並破壞。','發動無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38491852,'異響鳴琴邀請',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從以下效果挑選1個適用。\u000a●從牌組將1隻「異響鳴琴」怪獸特殊召喚。此卡的發動後，直到回合結束時我方不能發動「異響鳴琴」怪獸以外的場上的怪獸的效果。\u000a●我方場上有靈擺怪獸以外的「異響鳴琴」怪獸存在的場合，從牌組選2隻卡名不同的「異響鳴琴」靈擺怪獸，其中1隻加入手牌，另1隻表側加入額外牌組。'),'效果1','●從牌組特殊召喚','●從牌組加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38492752,'熔岩加農','此卡召喚、反轉召喚成功時，可以選擇除外的1隻我方的「熔岩」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38495396,'托勒密M7星聖',unistr('等級6怪獸×2\u000a此卡也能重疊在「托勒密M7星聖」以外的我方場上的「星聖」超量怪獸上方來超量召喚。這個方法特殊召喚的回合，此卡的①效果不能發動。\u000a①：1回合1次，去除此卡的1個超量素材，以我方或對手的場上、墓地1隻怪獸為對象可以發動。那隻怪獸回到手牌。'),'效果1','是否重疊在「星聖」超量怪獸上方來超量召喚？','選擇場上的怪獸','選擇墓地的怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(38495397,'托勒密M7星聖',unistr('等級6怪獸×2\u000a此卡也能重疊在「托勒密M7星聖」以外的我方場上的「星聖」超量怪獸上方來超量召喚。這個方法特殊召喚的回合，此卡的①效果不能發動。\u000a①：1回合1次，去除此卡的1個超量素材，以我方或對手的場上、墓地1隻怪獸為對象可以發動。那隻怪獸回到手牌。'),'效果1','是否重疊在「星聖」超量怪獸上方來超量召喚？','選擇場上的怪獸','選擇墓地的怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(38502358,'星痕之機界騎士',unistr('「機界騎士」怪獸2隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：和此卡相同縱列沒有其他卡存在的場合，此卡可以直接攻擊。\u000a②：額外怪獸區域的此卡指向的區域沒有怪獸存在的場合，此卡不會被效果破壞，不會成為對手的效果的對象。\u000a③：將和此卡相同縱列的1張其他的我方的卡送去墓地可以發動。從牌組將1隻「機界騎士」怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38505587,'增量棉花糖',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：對手回合，我方場上有「光之黃金櫃」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：只要我方場上有「光之黃金櫃」存在，此卡不會被戰鬥破壞，對手怪獸不能選擇其他怪獸作為攻擊對象。\u000a③：此卡被效果破壞的場合可以發動。除了此卡以外，我方的手牌、牌組、墓地、除外狀態的1隻「增量棉花糖」特殊召喚，給予對手1000傷害。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38511382,'背叛之罪寶-西爾維亞',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方的手牌、場上（表側表示）將1隻「迪亞貝爾斯塔」怪獸送去墓地，以場上1張表側表示卡為對象可以發動。那張卡的效果無效。\u000a②：對手連鎖我方的「迪亞貝爾斯塔」怪獸或我方的「罪寶」魔法、陷阱卡的效果的發動，來發動魔法、陷阱、怪獸的效果時，將墓地的此卡除外可以發動。那個對手的效果無效。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38517737,'青眼亞白龍',unistr('此卡不能通常召喚。向對手展示手牌的1隻「青眼白龍」可以特殊召喚。這個方法的「青眼亞白龍」的特殊召喚1回合只能有1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「青眼白龍」。\u000a②：1回合1次，以對手場上1隻怪獸為對象可以發動（此效果發動的整回合中，此卡不能攻擊）。那隻怪獸破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38520918,'古龍','①：此卡直接攻擊給予對手戰鬥傷害時可以發動。此卡的等級上升1，攻擊力上升500。','等級和攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38522377,'機皇神龍 星標',unistr('此卡不能通常召喚。我方場上的「機皇」怪獸是3隻以上的場合可以特殊召喚。\u000a①：此卡特殊召喚成功時，以此卡以外的我方場上任意數量的「機皇」怪獸為對象可以發動。那些我方的「機皇」怪獸送去墓地。此卡的攻擊力變成此效果送去墓地的怪獸的原攻擊力合計數值。\u000a②：每次同步怪獸特殊召喚發動。給予將那些怪獸特殊召喚的玩家1000傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38525760,'陽炎獸 地獄犬',unistr('此卡可以不用解放來召喚。這個方法召喚的此卡的原攻擊力變成1000。\u000a只要此卡在場上表側表示存在，對手不能將此卡作為效果的對象。\u000a此卡被破壞送去墓地時，可以從牌組將1張「陽炎」卡片加入手牌。'),'不解放的召喚','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38527680,'聯合啟動',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌、牌組將1隻機械族、光屬性的，通常怪獸或聯合怪獸送去墓地，從牌組將1隻和那隻怪獸攻擊力相同且原卡名不同的機械族、光屬性怪獸加入手牌。\u000a②：此卡在墓地存在的狀態，我方將3隻機械族、光屬性怪獸同時特殊召喚的場合，將此卡除外可以發動。從牌組將1隻攻擊力3000以上的怪獸加入手牌。那之後，進行那1隻怪獸的召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38528901,'冰結界的決起隊','①：將此卡解放，以場上1隻水屬性怪獸為對象可以發動。那隻水屬性怪獸破壞，從牌組將1隻「冰結界」怪獸加入手牌。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38529357,'命之代行者 海王星',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。從我方的手牌、墓地選「命之代行者 海王星」以外的1隻「代行者」怪獸特殊召喚。場上或墓地有「天空的聖域」存在的場合，可以將特殊召喚的怪獸改成1隻「赫貝里翁」怪獸。直到對手回合結束時，雙方不能將此效果特殊召喚的怪獸解放。\u000a②：此卡被除外的場合可以發動。從牌組將1張「天空的聖域」加入手牌。'),'從手牌或墓地特殊召喚','從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38532954,'F.A. 進站',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「F.A.」怪獸為對象可以發動。那隻怪獸的等級下降2，我方從牌組抽我方墓地的「F.A. 進站」的數量+1張卡。\u000a②：我方主要階段將墓地的此卡除外，以我方墓地1隻「F.A.」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38538445,'不死之炎鳥',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡給予對手戰鬥傷害時，我方回復給予的戰鬥傷害數值的生命值。'),'回到手牌','回復','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38552107,'光之角',unistr('裝備怪獸的守備力上升800。\u000a此卡從場上送去墓地時，可以藉由支付500生命值，此卡回到牌組最上方。'),'回至牌組最上面','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38562933,'BF-空風之琴','此卡和守備力在此卡的攻擊力以下的怪獸進行戰鬥的場合，不進行傷害計算，那隻怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38568567,'奇異三葉草',unistr('選擇我方場上表側表示存在的1隻怪獸，從手牌將1隻等級4的植物族怪獸送去墓地可以發動。這個回合，選擇的怪獸在1次戰鬥階段中可以攻擊2次。此卡發動的整回合中，我方場上的其他怪獸不能攻擊宣言。\u000a[按照判例修正]'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38572779,'幻創的混種恐龍',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方、對手的主要階段，將此卡從手牌送去墓地可以發動。這個主要階段中，我方場上的恐龍族怪獸不受對手發動的效果影響。\u000a②：從我方墓地將任意數量的包含此卡的恐龍族怪獸除外可以發動。從牌組將1隻等級和除外的怪獸數量相同的恐龍族怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。'),'效果1','效果2','請選擇要特殊召喚的怪獸的等級','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38576155,'女神詩寇蒂的神諭',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，我方場上的怪獸只有「華爾裘蓮」怪獸的場合，可以從牌組將1張「女神薇兒丹蒂的引導」加入手牌。\u000a②：1回合1次，我方主要階段可以發動。從對手牌組上方確認3張卡，以喜歡的順序回到牌組上方。此效果的發動後，直到回合結束時我方除了天使族怪獸以外不能召喚、特殊召喚。'),'是否把「女神薇兒丹蒂的引導」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38589847,'上級之力','只要此卡在場上存在，等級7以上的怪獸可以解放1隻等級5以上的怪獸來上級召喚。','解放1隻等級5以上的怪獸（上級之力）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38590361,'螺旋結合',unistr('①：從我方的手牌、場上將龍族融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。此效果將「龍騎士蓋亞」特殊召喚的場合，那隻怪獸的攻擊力上升2600，在1次戰鬥階段中可以向怪獸攻擊2次。\u000a\u000a※螺旋融合'),'「螺旋融合」的效果1適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38601126,'破壞劍-武裝爆裂劍',unistr('①：我方主要階段以我方場上1隻「爆裂劍士」為對象可以發動。從我方的手牌、場上將這隻怪獸當作裝備卡給那隻我方怪獸裝備。\u000a②：此卡裝備中的場合，對手場上的已經表側表示存在的魔法、陷阱卡不能發動效果。\u000a③：將裝備的此卡送去墓地可以發動。此卡裝備過的怪獸的攻擊力直到回合結束時上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38606913,'方界緣起',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將最多到我方場上的「方界」怪獸數量的方界計數器給對手場上的表側表示怪獸放置。已放置方界計數器的怪獸不能攻擊，效果無效化。\u000a②：將墓地的此卡除外，以我方場上1隻「方界」怪獸為對象可以發動。這個回合，每次那隻怪獸以戰鬥破壞已放置方界計數器的怪獸，給予對手那隻被破壞的怪獸的原攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38625110,'清晨一片雪白色 兩人一同雪中行','①：我方的場上（表側表示）、墓地、除外狀態全部都沒有「清晨一片雪白色 兩人一同雪中行」存在的場合，從我方牌組上方將7張卡裡側除外可以發動。對手必須從自身的牌組上方、額外牌組將合計7張卡裡側除外。','','請選擇7張卡裡側除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38628859,'恐啡肽狂龍 梁龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「恐啡肽狂龍」卡片送去墓地。我方的生命值是2000以下的場合，隨後給予對手500傷害。\u000a②：此卡被戰鬥、效果破壞的場合，從我方墓地將1張陷阱卡除外可以發動。從我方墓地選「恐啡肽狂龍 梁龍」以外的1隻等級4以下的「恐啡肽狂龍」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38643567,'甲蟲裝機的寶珠',unistr('發動後此卡當作攻擊力、守備力上升500的裝備卡給我方場上的1隻「甲蟲裝機」怪獸裝備。\u000a我方場上的「甲蟲裝機」怪獸1隻成為卡片效果的對象時，可以藉由將當作裝備卡的此卡送去墓地，那個效果無效。'),'效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38648860,'白森林的聖徒 莉賽特',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡可以發動。從手牌將1隻「白森林」怪獸或「聖徒」怪獸特殊召喚。\u000a②：我方主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「聖徒」融合怪獸融合召喚。\u000a③：此卡作為同步素材送去墓地的場合可以發動。從牌組將1張「罪寶」卡片加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38667773,'衛星騎士 織女一',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚的場合可以發動。從手牌將「衛星騎士 織女一」以外的1隻「星騎士」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38669664,'原物質的爐心熔毀',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方主要階段可以發動。從我方牌組上方翻開6張卡，可以從其中選1張「原物質」卡片加入手牌。其餘以喜歡的順序回到牌組上方。那之後，可以將我方場上的階級3超量怪獸作為超量素材持有的1張卡加入手牌。\u000a②：我方的超量怪獸發動效果的場合可以發動。我方牌組最上方的卡作為我方場上1隻「原物質」超量怪獸的超量素材。'),'效果1','效果2','是否將1張卡加入手牌？','是否將1張超量素材加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(38670435,'暗黑恐獸','對手場上只有守備表示怪獸存在的場合，此卡可以直接攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38679204,'大日神械星狀體',unistr('此卡從怪獸區域送去墓地的場合，可以藉由支付500生命值，此卡當作裝備卡給我方場上的1隻怪獸裝備。\u000a此卡已當作裝備卡裝備的場合，裝備怪獸和對手怪獸進行戰鬥的傷害步驟結束時，那隻對手怪獸破壞。'),'當成裝備卡裝備','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38680149,'信賴之心','將我方場上的1隻等級2以上的怪獸解放可以發動。選擇我方墓地1隻等級在解放的怪獸的一半以下的協調加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38694052,'黑熔龍騎 沃爾尼吉斯',unistr('等級7怪獸×2\u000a①：1回合1次，去除此卡的2個超量素材，以場上1張表側表示的卡為對象可以發動。那張卡破壞。此效果將怪獸破壞的場合，可以選我方場上1隻表側表示怪獸，那個攻擊力直到下個回合結束時上升破壞的怪獸的原本的等級、階級的數值×300。此效果發動的整回合中，此卡不能攻擊。此卡有龍族怪獸作為超量素材的場合，此效果在對手回合也能發動。'),'效果1','是否讓我方場上的1隻表側表示怪獸攻擊力上升？','請選擇攻擊力上升的怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38695361,'混沌的使者',unistr('①：我方、對手的戰鬥階段將此卡從手牌捨棄，以我方場上1隻「混沌士兵」怪獸或「暗黑騎士蓋亞」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升1500，這個回合和那隻怪獸進行戰鬥的對手怪獸的攻擊力只在傷害計算時變成原攻擊力。\u000a②：我方、對手的結束階段有此卡在墓地存在的場合，從我方墓地將此卡以外的光屬性和闇屬性的怪獸各1隻除外可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38699854,'太陽之書','①：以場上1隻裡側表示怪獸為對象可以發動。那隻裡側表示怪獸變成表側攻擊表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38723936,'猜謎','此卡發動中，對手不能確認墓地的卡。對手玩家猜發動「猜謎」的玩家的墓地最下方的怪獸名稱。如果猜對，那張卡除外。如果猜錯，那張卡在持有者的場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38730226,'英知的代行者 水星','①：對手回合結束時，此卡在我方的怪獸區域表側表示存在，我方的手牌是0張的場合，下個我方準備階段發動。我方從牌組抽1張卡。','抽1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38737148,'光芒使者 戴達羅斯',unistr('此卡不能通常召喚。只能在我方墓地的光屬性怪獸有4隻以上的場合特殊召喚。\u000a1回合1次，選擇場上的2張卡和1張場地魔法卡合計3張可以發動。選擇的卡破壞。'),'破壞場上的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38742075,'邊境的大賢者','只要此卡在場上表側表示存在，以我方場上的表側表示的戰士族怪獸為對象的魔法卡的效果無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38745241,'魔法甜點貓 喵卡龍',unistr('包含「魔法甜點」怪獸的效果怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組將1張「魔法甜點」卡片加入手牌。\u000a②：以我方墓地1隻怪獸為對象可以發動。從手牌將1隻「魔法甜點」怪獸特殊召喚，對象怪獸回到牌組。此效果的發動後，直到回合結束時我方不能發動「魔法甜點」怪獸以外的怪獸的效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38745520,'騎龍 多拉貢巴克',unistr('只能給我方場上的怪獸裝備。這個卡名的②③效果1回合各能使用1次。\u000a①：「騎龍 多拉貢巴克」在我方場上只能有1張表側表示存在。\u000a②：此卡給效果怪獸以外的怪獸裝備中的場合，以對手場上1張卡為對象可以發動。那張卡回到持有者的手牌。\u000a③：此卡被送去墓地的場合，以我方場上1隻「勇者衍生物」為對象可以發動。那隻我方怪獸將此卡裝備。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38757297,'光子獅','此卡召喚成功時可以發動。對手的手牌全部加入牌組洗牌。那之後，依照加入牌組的數量，對手從牌組抽牌。','重新抽卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38761908,'伯吉斯異獸 高足杯蟲',unistr('①：以場上1張表側表示的卡為對象可以發動。選1張我方的手牌捨棄，對象卡片除外。\u000a②：陷阱卡發動時，連鎖那個發動可以在墓地發動此效果。此卡變成通常怪獸（水族、水、等級2、攻1200/守0）在怪獸區域特殊召喚（不當作陷阱卡）。此效果特殊召喚的此卡不受怪獸的效果影響，從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38775407,'從仟年沉眠中甦醒的原人',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合可以發動。此卡當作永續魔法卡在我方的魔法與陷阱區域表側表示放置。\u000a②：此卡當作永續魔法卡的場合，支付2000生命值或向對手展示手牌的1張「仟年的十字」可以發動。此卡特殊召喚。那之後，可以從牌組將1隻「仟年」怪獸或「千年」怪獸加入手牌。\u000a③：此卡只要在怪獸區域存在，不會被怪獸的效果破壞。'),'效果1','效果2','是否展示「仟年的十字」？','是否從牌組加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(38776201,'三幻魔解放',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將卡名不同的3隻「三幻魔」怪獸加入手牌。那之後，選2張我方的手牌捨棄。\u000a②：將不是在這個回合送去墓地的此卡從墓地除外可以發動。從牌組將1隻不能通常召喚的等級10的炎族、雷族、惡魔族怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38777931,'解放反轉爆發','解放我方場上1隻「希望皇霍普」怪獸可以發動。對手場上覆蓋的魔法、陷阱卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38783169,'調整鼠騎士',unistr('①：此卡特殊召喚成功的場合可以發動。這個回合，此卡當作協調。此效果的發動後，直到回合結束時，我方只能從額外牌組將怪獸特殊召喚1次。\u000a②：1回合1次，可以從以下效果選擇1個發動。\u000a●以我方場上1隻表側表示怪獸為對象，此卡當作裝備卡給那隻怪獸裝備。裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備的此卡特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38784726,'轉生炎獸的降臨',unistr('「轉生炎獸」儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻「轉生炎獸」儀式怪獸。我方場上有炎屬性連結怪獸存在的場合，可以讓我方墓地的「轉生炎獸」怪獸回到牌組來代替解放。\u000a②：此卡被對手的效果破壞的場合可以發動。從手牌將1隻「轉生炎獸 翠玉鷹」無視召喚條件特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38798785,'炎王的結襲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、牌組、墓地將各將1隻獸族、獸戰士族、鳥獸族的炎屬性怪獸特殊召喚（相同種族最多1隻）。此效果特殊召喚的怪獸的效果無效化，在結束階段破壞。\u000a②：將墓地的此卡除外可以發動。這個回合，在我方的「炎王」怪獸的召喚、特殊召喚成功時對手不能發動魔法、陷阱、怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38811586,'真炎龍 阿爾比昂',unistr('「阿不思的落胤」+魔法使族、光屬性怪獸\u000a此卡不能作為融合素材。\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：對手不能將場上的此卡作為效果的對象。\u000a②：對手回合，以我方、對手的墓地的怪獸合計2隻為對象可以發動。那2隻在雙方場上各選1隻特殊召喚。\u000a③：此卡在墓地存在的場合可以發動。額外怪獸區域以及雙方的中央的主要怪獸區域的4隻怪獸解放，此卡特殊召喚。'),'效果2','請選擇要在我方場上特殊召喚的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38814750,'PSY骨架裝備γ',unistr('此卡不能通常召喚，只能用卡的效果特殊召喚。\u000a①：我方場上沒有怪獸存在，對手發動怪獸的效果時可以發動（同一連鎖上最多1次）。手牌的此卡和我方的手牌、牌組、墓地1隻「PSY骨架驅動者」特殊召喚，那個發動無效並破壞。此效果特殊召喚的怪獸在結束階段被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38815069,'光道盜賊貓 萊喵','反轉：選擇我方墓地的1隻「光道」怪獸回到牌組，從我方牌組抽1張卡。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38834303,'計數器清除者','支付500生命值可以發動。將場上的計數器全部去除。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38837163,'豹人 阿庫茲',unistr('此卡不能通常召喚。將我方墓地的2隻獸戰士族怪獸除外可以特殊召喚。\u000a1回合1次，可以從手牌將1隻獸戰士族怪獸捨棄，從以下效果選擇1個發動。\u000a●此卡的攻擊力直到回合結束時變成2倍。\u000a●這個回合，此卡可以向對手玩家直接攻擊。'),'效果1','●攻擊力變成2倍','●直接攻擊','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38844957,'緊急儀式術','①：我方場上沒有儀式怪獸存在的場合，從我方的手牌、墓地將1張儀式魔法卡除外可以發動。此卡的效果變成和那張儀式魔法卡發動時的儀式召喚的效果相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38848158,'點火騎士團結',unistr('「點火騎士團結」在1回合只能發動1張。\u000a①：以我方場上1張「點火騎士」卡片為對象可以發動。那張卡破壞，從牌組將1隻「點火騎士」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38891741,'神的攝理','①：怪獸的效果、魔法、陷阱卡發動時，將和那個效果相同種類（怪獸、魔法、陷阱）的1張卡從手牌捨棄可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38898779,'巨人鬥士/爆裂',unistr('此卡不能通常召喚。只能用「爆裂模式」的效果特殊召喚。\u000a只要此卡在場上表側表示存在，全部對手怪獸的攻擊力下降我方墓地的戰士族怪獸數量×100。\u000a此卡特殊召喚成功時，可以從我方牌組選最多2隻戰士族怪獸送去墓地。\u000a場上的此卡被破壞時，可以選擇我方墓地的1隻「巨人鬥士」特殊召喚。'),'從牌組送去墓地','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38904695,'無限地獄地獄惡魔',unistr('協調+協調以外的怪獸1隻以上\u000a①：1回合1次，以場上1張表側表示的卡為對象可以發動。那張卡的效果直到回合結束時無效。我方的手牌是0張的場合，隨後可以將那張卡破壞。\u000a②：只要我方的手牌是0張，此卡和對手怪獸的戰鬥給予對手的戰鬥傷害變成2倍。\u000a③：用此卡為同步素材的闇屬性同步怪獸在1次戰鬥階段中可以向怪獸攻擊最多2次。'),'效果1','是否破壞？','「無限地獄地獄惡魔」的效果3適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38910263,'炎王獸 哈奴曼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的表側表示的「炎王」怪獸被效果破壞的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡在怪獸區域存在，魔法、陷阱卡的效果發動時可以發動。那個發動無效，此卡以外的我方的手牌、場上（表側表示）1隻炎屬性怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38916461,'稀有金屬士兵','全身覆蓋著金屬裝甲的戰士。與「稀有金屬女士」融合將提升力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38916526,'空牙團的英雄 拉斐爾',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。依照「空牙團的英雄 拉斐爾」以外的我方場上的「空牙團」怪獸種類的數量，從我方牌組上方翻開卡片，從其中選1張加入手牌，其餘回到牌組。\u000a②：對手發動怪獸的效果時，從手牌捨棄1張「空牙團」卡片可以發動。那個發動無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38942059,'音女','擅長操縱聲音的少女，能使音符變成鐮刀攻擊敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38943357,'魔力統轄',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1張「安迪米翁」卡片加入手牌。那之後，最多到我方的場上、墓地的「魔力統轄」「魔力掌握」的數量，可以給我方場上的可以放置魔力計數器的卡盡可能放置魔力計數器。'),'是否放置魔力計數器？','請選擇要放置魔力計數器的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38955728,'龍核的咒靈者',unistr('由於長年不斷獵龍而染上的龍血，獲得超越常人力量的女戰士。\u000a她的靈魂被所殺之龍的怨氣浸染，最終化為散播疫病的邪惡龍核。\u000a能回去的故鄉已不復存在，出於本能讓刀刃染血的目的，她自己也早已不記得了…。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38960450,'武器呼喚',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1張裝備魔法卡加入手牌。那之後，可以選我方場上1隻可以裝備那張卡的怪獸，給那隻怪獸裝備。'),'是否給怪獸裝備？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38973775,'光子蜥蜴',unistr('「光子蜥蜴」的效果1回合只能使用1次。\u000a將此卡解放可以發動。從牌組將1隻等級4以下的「光子」怪獸加入手牌。'),'檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38975369,'軍荼利',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡和同步怪獸進行戰鬥的場合，不進行傷害計算，那隻怪獸和此卡回到持有者的手牌。'),'雙方回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38981606,'沙漠守衛者','此卡的守備力上升場上的魔法、陷阱卡數量×300。我方場上的昆蟲族怪獸破壞的場合，可以將此卡破壞作為代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38982356,'冰','全身用冰做的戰士。將一切與其解觸者冰凍起來。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38984832,'第55次GMX實驗報告',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方的手牌、場上的怪獸作為融合素材，將1隻恐龍族融合怪獸融合召喚。對手場上有怪獸存在的場合，我方牌組的「GMX」怪獸也能有最多1隻作為融合素材。\u000a②：我方主要階段將墓地的此卡除外可以發動。從我方牌組上方翻開卡片，直到「GMX」卡片出現為止，那張「GMX」卡片加入手牌。其餘回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38988538,'機動霧龍 蛇頸龍',unistr('【靈擺效果】\u000a①：此卡在靈擺區域期間只有1次，可以將以此卡以外的我方場上的「機動霧龍」卡片為對象發動的效果無效。那之後，此卡破壞。\u000a【怪獸效果】\u000a①：只要此卡在怪獸區域存在，對手場上的怪獸的攻擊力、守備力下降我方場上的「機動霧龍」卡片數量×100。'),'是否用「機動霧龍 蛇頸龍」的靈擺效果將其無效？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38992735,'波動加農砲','①：將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。給予對手此卡的發動後經過的我方準備階段次數×1000傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38999506,'宇宙女王','統治著存在於宇宙中所有星球的女王。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39000945,'安迪米翁的皇后',unistr('【靈擺效果】\u000a①：每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a②：去除此卡的3個魔力計數器可以發動。手牌的1隻可以放置魔力計數器的怪獸和靈擺區域的此卡特殊召喚，給那2隻各放置1個魔力計數器。\u000a【怪獸效果】\u000a我方1回合只能特殊召喚1次「安迪米翁的皇后」。\u000a①：此卡特殊召喚成功的場合，以我方場上1張其他的已放置魔力計數器的卡和對手場上1張卡為對象可以發動。那些我方以及對手的卡回到持有者的手牌。那之後，給此卡放置相當於從我方場上回到手牌的卡放置數量的魔力計數器。\u000a②：已放置魔力計數器的此卡被戰鬥破壞時可以發動。從牌組將1張「安迪米翁」卡片加入手牌。'),'靈擺效果2','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39004808,'水源','海中的半魚人。掀起暗黑的大海嘯來攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39016067,'龍劍士 風麒麟平行',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：另一邊的我方的靈擺區域有卡存在的場合，可以從以下效果選擇1個發動。\u000a●此卡特殊召喚。\u000a●此卡破壞，我方的靈擺區域1張等級5以下的靈擺怪獸卡特殊召喚。\u000a【怪獸效果】\u000a這個卡名的②怪獸效果1回合只能使用1次。\u000a①：只要靈擺召喚的此卡在怪獸區域存在，此卡不會被對手的效果破壞，對手不能將此卡作為效果的對象。\u000a②：我方、對手回合，以我方場上1張靈擺怪獸卡和對手場上1張卡為對象可以發動。那些卡回到手牌。'),'靈擺效果1','效果2','●此卡特殊召喚','●此卡破壞','','','','','','','','','','','','');
INSERT INTO texts VALUES(39019325,'玉碎指令','選擇衍生物以外的我方場上1隻等級2以下的通常怪獸可以發動。選擇的通常怪獸解放，選對手場上最多2張魔法、陷阱卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39024589,'魔界劇團-花花配角',unistr('【靈擺效果】\u000a①：我方靈擺召喚成功時可以發動。從我方的額外牌組將1隻表側表示的等級1或等級8的「魔界劇團」靈擺怪獸加入手牌。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：我方的靈擺區域有2張「魔界劇團」卡片存在的場合，將此卡解放可以發動。從手牌以及我方的額外牌組的表側表示怪獸之中，將1隻等級1或等級8的「魔界劇團」靈擺怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39030163,'銀河眼全裝甲光子龍',unistr('等級8怪獸×3\u000a此卡也能重疊在「銀河眼全裝甲光子龍」以外的我方場上的「銀河眼」超量怪獸上方來超量召喚。\u000a①：1回合1次，以最多2張此卡的裝備卡為對象可以發動。那些卡重疊在此卡下方作為超量素材。\u000a②：1回合1次，去除此卡的1個超量素材，以對手場上1張表側表示的卡為對象可以發動。那張卡破壞。'),'是否重疊在「銀河眼」超量怪獸上方超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39033131,'妖怪築巢的祠堂',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上沒有怪獸存在的場合，以我方墓地1隻不死族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方場上沒有怪獸存在的場合，將墓地的此卡除外，以我方墓地1隻不死族怪獸為對象可以發動。那隻怪獸效果無效特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39037517,'核成甲殼蟲',unistr('此卡的控制者在每次我方結束階段，從手牌將1張「核成的鋼核」送去墓地，或向對手展示手牌的1隻昆蟲族怪獸，或都不做讓此卡破壞。\u000a光屬性或闇屬性怪獸表側攻擊表示特殊召喚成功時，那些怪獸變成守備表示。'),'「核成的鋼核」送去墓地','展示昆蟲族怪獸','破壞','變成守備表示','','','','','','','','','','','','');
INSERT INTO texts VALUES(39041550,'騎甲蟲 鱗粉炸彈兵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有昆蟲族怪獸召喚、特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：對手發動場上的怪獸的效果時，將我方場上1隻昆蟲族怪獸解放可以發動。那隻怪獸破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39041729,'時光超越',unistr('①：從我方墓地將2隻以上恐龍族怪獸除外可以發動。從我方的手牌、墓地選1隻等級和除外的怪獸的等級合計相同的恐龍族怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。\u000a\u000a※時空超越'),'請選擇要特殊召喚的怪獸的等級','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39049051,'歌冰麗月',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1隻等級4以下的天使族、魔法使族、鳥獸族、獸戰士族怪獸特殊召喚，並裝備此卡。那之後，可以讓場上的龍族怪獸全部回到持有者的手牌。\u000a②：魔法與陷阱區域的表側表示的此卡被送去墓地的回合的結束階段可以發動。從牌組將1張「融合」魔法卡或「結合」魔法卡或1隻「寄生結融者」加入手牌。'),'N/A','N/A','是否讓場上的龍族怪獸全部回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39064822,'夢魘曲 哥布林',unistr('卡名不同的怪獸2隻\u000a①：此卡在我方回合連結召喚的場合，捨棄1張手牌可以發動。此效果的發動時此卡是互相連結狀態的場合，我方可以抽1張卡。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以從手牌將1隻怪獸在此卡指向的我方場上召喚。\u000a②：只要此卡在怪獸區域存在，雙方不能將我方場上的互相連結狀態的怪獸作為效果的對象。'),'效果1','是否抽1張卡？','召喚（夢魘曲 哥布林）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39078434,'巨大彌賽亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從我方的手牌、墓地選1隻昆蟲族怪獸，當作攻擊力、守備力上升500的裝備卡給此卡裝備。\u000a③：1回合1次，昆蟲族怪獸進行戰鬥的傷害步驟開始時，以我方以及對手場上的卡各1張為對象可以發動。那些卡破壞。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39091951,'貓熊博格','此卡被戰鬥破壞送去墓地時，支付800生命值可以發動。從牌組將1隻等級4的超能族怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39103226,'地磅計量','①：對手場上的怪獸數量比我方場上的怪獸多2隻以上的場合可以發動。對手必須將自身場上的怪獸送去墓地，直到變成1隻為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39109382,'機皇創出',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②③效果1回合各能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻「機皇」怪獸加入手牌。\u000a②：捨棄1張手牌，以我方場上1隻怪獸為對象可以發動。那隻怪獸破壞。\u000a③：我方場上的表側表示的「機皇」怪獸被戰鬥、效果破壞的場合，以此卡以外的場上的1張表側表示的魔法、陷阱卡為對象可以發動。那張卡破壞。'),'是否從牌組把1隻「機皇」怪獸加入手牌？','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39111158,'三角龍','頭上長了3支角的魔鬼龍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39114494,'肅聲的祝福',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以「肅聲的祝福」以外的我方的墓地、除外狀態的1張「肅聲」卡片為對象可以發動。那張卡加入手牌。\u000a②：儀式怪獸以外的怪獸表側表示召喚、特殊召喚的場合可以發動。解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻戰士族、龍族且光屬性的儀式怪獸。此效果特殊召喚的怪獸不會被戰鬥破壞。'),'','效果1','效果2','「肅聲的祝福」的效果2適用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(39118197,'機偶武者 六三一八',unistr('此卡可以攻擊的場合必須攻擊。\u000a場上表側攻擊表示的此卡被選擇作為攻擊對象時，此卡的表示形式變成守備表示。\u000a場上的「機偶」怪獸被破壞的場合，此卡的攻擊力上升400。'),'變為守備表示','攻擊力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39122311,'龍魂的幻泉','①：以我方墓地1隻怪獸為對象可以發動此卡。那隻怪獸守備表示特殊召喚。只要此卡在魔法與陷阱區域存在，特殊召喚的那隻怪獸的種族變成幻龍族。此卡從場上離開時那隻怪獸破壞。那隻怪獸從場上離開時此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39131963,'死亡反擊','怪獸直接攻擊給予玩家戰鬥傷害時，那隻怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39138610,'協碼語者@伊格尼斯者',unistr('效果怪獸3隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡連結召喚的場合可以發動。從我方墓地將攻擊力2300的電子界族怪獸盡可能在此卡指向的我方場上特殊召喚，此卡的攻擊力上升那個數量×500。此效果的發動後，直到回合結束時我方不能將怪獸特殊召喚。\u000a②：對手將卡的效果發動時，將此卡指向的1隻我方的連結怪獸解放可以發動。那個發動無效並除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39139935,'No.33 先史遺產-超兵器天空之城',unistr('等級5怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以對手場上1隻攻擊力和原攻擊力不同的怪獸為對象可以發動。給予對手那隻怪獸的攻擊力和那個原攻擊力的差額的傷害，此卡的攻擊力上升此效果給予的傷害數值。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39153655,'DD刻耳柏洛斯',unistr('【靈擺效果】\u000a①：1回合1次，以我方場上的1隻「DD」怪獸為對象可以發動。那隻怪獸的等級變成4，攻擊力、守備力上升400。\u000a【怪獸效果】\u000a①：此卡從手牌靈擺召喚成功時，「DD刻耳柏洛斯」以外的「DD」怪獸在我方場上存在的場合，以我方墓地1張永續魔法卡為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39163598,'行星汙染病毒','解放我方場上的1隻「外星人」怪獸可以發動。對手場上沒有放置A計數器的表側表示怪獸全部破壞。以對手回合計算的3回合內，對手召喚、反轉召喚、特殊召喚的怪獸全部放置1個A計數器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39168895,'憤怒類人猿',unistr('此卡在場上表側守備表示存在的場合，此卡破壞。\u000a此卡在可以攻擊的狀態必須攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39175982,'黑暗殺手','揮舞像鐮刀般發達的手臂進行攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39180960,'嚴格收割者',unistr('①：此卡反轉的場合發動。雙方玩家各自選自己的1張手牌捨棄。\u000a②：此卡被怪獸戰鬥破壞的場合發動。那隻怪獸的攻擊力、守備力下降500。'),'捨棄手牌','攻守下降500','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39185163,'死靈王 惡眼',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：「死靈王 惡眼」以外的不死族怪獸的效果發動時可以發動（同一連鎖上最多1次）。從以下效果將1個適用。這個回合，我方的「死靈王 惡眼」的效果不能適用相同效果。\u000a●那個效果無效。\u000a●我方或對手的場上、墓地1隻怪獸除外。\u000a②：場地區域有表側表示卡存在的場合，我方、對手的準備階段可以發動。此卡從墓地守備表示特殊召喚。'),'效果1','●效果無效','●場上、墓地1隻怪獸除外','效果2','','','','','','','','','','','','');
INSERT INTO texts VALUES(39188539,'風暴射手',unistr('1回合1次，可以從以下效果選擇1個發動。\u000a●此卡向相鄰且沒有使用的怪獸區域移動。\u000a●選擇此卡的正前方的1張對手的怪獸、魔法、陷阱卡回到持有者的手牌。'),'●移動到相鄰且沒有使用的怪獸區域','●正前方的卡回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39191307,'假面龍','①：此卡被戰鬥破壞送去墓地時可以發動。從牌組將1隻攻擊力1500以下的龍族怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39210885,'天魔的聲選器-『異響鳴琴』',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻「異響鳴琴」怪獸加入手牌。\u000a②：我方的靈擺區域的卡被放置響鳴計數器，那張卡的響鳴計數器變成3個的場合，以對手場上1隻怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。此效果得到控制權的怪獸不能攻擊宣言。'),'效果2','是否從牌組加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39229392,'疊放狙擊者',unistr('此卡不能特殊召喚。\u000a此卡召喚成功時，變成守備表示。\u000a此外，我方場上有持有超量素材的超量怪獸存在的場合，將墓地的此卡除外，選擇對手場上的1隻怪獸可以發動。那隻怪獸的攻擊力下降我方場上的超量素材數量×500。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39238953,'天聲的服從',unistr('①：支付2000生命值，宣言1個怪獸卡名可以發動。對手確認自身牌組，其中有宣言的怪獸的場合，將其中1隻給雙方確認，從以下效果挑選1個適用。\u000a●確認的卡加入發動此卡的玩家的手牌。\u000a●確認的卡在發動此卡的玩家的場上無視召喚條件攻擊表示特殊召喚。'),'●加入發動玩家的手牌','●在發動玩家的場上以攻擊表示特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39239728,'王室守衛','為了守護王座而開發的，且擁有意志的機械部隊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39246582,'絨毛動物狗',unistr('「絨毛動物狗」的效果1回合只能使用1次。\u000a①：此卡從手牌召喚、特殊召喚成功時可以發動。從牌組將1隻「鋒利小鬼 剪刀」或1隻「絨毛動物狗」以外的「絨毛動物」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39256679,'磁石戰士β','湊齊α、β、γ3隻可以合體。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39260991,'水伶女 燈魚','①：1回合1次，我方主要階段可以發動。從牌組將1張「水族館」卡片加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39261576,'粒子結合',unistr('從我方場上將「寶石騎士」融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a此效果融合召喚成功時，將墓地的此卡除外，選擇那次融合召喚使用的1隻「寶石騎士」融合素材怪獸發動。那隻融合怪獸的攻擊力直到回合結束時上升選擇怪獸的攻擊力數值。\u000a\u000a※粒子融合'),'攻擊力上升','請選擇1個使用的融合素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39271553,'F.A. 自動導航機',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌、墓地存在的場合，以我方場上1隻等級高於原等級的「F.A.」怪獸為對象可以發動。此卡特殊召喚，對象怪獸的等級下降和其原等級的差額。此效果特殊召喚的此卡的等級變成那個差額。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「F.A.」場地魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39272762,'超銀河眼光子龍',unistr('等級8怪獸×3\u000a用「銀河眼光子龍」作為素材將此卡超量召喚成功時，此卡以外的場上表側表示存在的卡的效果無效。\u000a1回合1次，去除此卡的1個超量素材可以發動。去除對手場上的全部超量素材，這個回合此卡的攻擊力上升去除數量×500。那之後，這個回合此卡在1次戰鬥階段中可以攻擊多次，次數上限為去除數量。'),'效果無效','攻擊力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39275698,'神鷹的羽翼休息',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方墓地的「神鷹女郎」「神鷹女郎三姊妹」之中以合計3隻為對象可以發動。那些卡加入牌組洗牌。那之後，我方從牌組抽1張卡。我方場上有等級5以上的「神鷹」怪獸存在的狀態發動的場合，抽牌的張數變成2張。此卡的發動後，直到回合結束時我方除了風屬性怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39276790,'真劍勝負','①：傷害步驟有怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39284521,'機甲部隊加農砲',unistr('此卡不能通常召喚。將此卡以外的任意張數的手牌的機械族怪獸送去墓地可以特殊召喚。\u000a①：此卡的攻擊力上升為了此卡的特殊召喚而送去墓地的怪獸數量×800。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39299733,'命運的戰車',unistr('這個卡名在規則上也當作「華爾裘蓮」卡片。\u000a①：1回合1次，可以從以下效果選擇1個發動。\u000a●以我方場上1隻天使族怪獸為對象，此卡當作裝備卡給那隻怪獸裝備。裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備的此卡特殊召喚。\u000a②：裝備怪獸可以直接攻擊。那次直接攻擊給予對手的戰鬥傷害變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39303359,'古代機械齒輪騎士',unistr('①：只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a②：可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39317553,'旋壞的貫破黃蜂巢',unistr('等級5怪獸×2\u000a「旋壞的貫破黃蜂巢」1回合1次也能重疊在我方場上的階級4超量怪獸上方來超量召喚。此卡在超量召喚的回合不能作為超量素材。這個卡名的②效果1回合只能使用1次。\u000a①：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：超量召喚的此卡被對手破壞的場合，以我方墓地1隻等級5以下的怪獸為對象可以發動。那隻怪獸特殊召喚。'),'是否重疊在階級4超量怪獸上方來超量召喚？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39321065,'沉默劍士 零',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方、對手的準備階段發動。此卡的等級上升1。\u000a②：此卡的等級高於原等級的場合，此卡的攻擊力上升那個差額×500。\u000a③：對手發動以我方場上的「光之黃金櫃」或記載那個卡名的怪獸為對象的效果時可以發動。那個發動無效，此卡的等級上升1。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39341885,'絢嵐之海靈 伐樓侖',unistr('「絢嵐」怪獸2隻\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從我方的牌組、墓地將1張「氣旋」加入手牌。\u000a②：以包含我方場上的「絢嵐」怪獸的場上2隻表側表示怪獸為對象可以發動。那些怪獸當作永續魔法卡在原持有者的魔法與陷阱區域表側表示放置。\u000a③：速攻魔法卡發動的場合可以發動。從我方的牌組、墓地將1張「絢嵐」永續陷阱卡在我方場上表側表示放置。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39343610,'黑暗烈焰龍',unistr('①：此卡從墓地特殊召喚成功的場合發動。此卡的攻擊力、守備力變成原本數值的2倍。\u000a②：此卡戰鬥破壞怪獸送去墓地的場合發動。給予對手那隻怪獸的原攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39354437,'冰水的霓石精',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「冰水」魔法、陷阱卡加入手牌。\u000a②：場上的此卡成為對手的效果的對象時，或被選擇作為對手怪獸的攻擊對象時可以發動。從我方的手牌、墓地將「冰水的霓石精」以外的1隻水屬性怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段回到手牌。這個回合，此卡只有1次不會被戰鬥、效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39357122,'真紅眼凶雷皇-邪性惡魔',unistr('①：只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a②：可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●1回合1次，我方主要階段可以發動。對手場上的守備力低於此卡的攻擊力的表側表示怪獸全部破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39373426,'SPYRAL MISSION-奪還',unistr('此卡發動後，在第3次的我方結束階段破壞。\u000a①：1回合1次，我方場上有「SPYRAL」怪獸特殊召喚的場合，以對手場上1隻怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。以此效果得到控制權的怪獸在這個回合不能直接攻擊。\u000a②：我方場上的「SPYRAL」怪獸被戰鬥、效果破壞的場合，可以將墓地的此卡除外，作為其中1隻被破壞的怪獸的代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39387565,'真紅眼的鎧旋',unistr('「真紅眼的鎧旋」的①②效果1回合各能使用1次。\u000a①：我方場上有「真紅眼」怪獸存在的場合，以我方墓地1隻通常怪獸為對象可以發動此效果。那隻怪獸特殊召喚。\u000a②：此卡被對手的效果破壞送去墓地的場合，以我方墓地1隻「真紅眼」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'是否現在發動此卡的效果1？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39389320,'野蠻人國王','①：1回合1次，解放此卡以外的我方場上任意數量的戰士族怪獸可以發動。這個回合，除了通常攻擊以外，此卡在1次戰鬥階段中可以攻擊的次數相當於為了發動此效果而解放的怪獸數量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39392286,'神鷹調香師',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「神鷹女郎」。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1張記載「神鷹女郎三姊妹」的卡名的魔法、陷阱卡加入手牌。我方場上有等級5以上的「神鷹」怪獸存在的狀態發動此效果的場合，此效果加入手牌的數量可以改成2張（同名卡最多1張）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39396763,'恐龍底座',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的生命值低於對手的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方主要階段可以發動。融合怪獸卡決定的包含場上的此卡的融合素材怪獸從我方的手牌、場上送去墓地，從額外牌組融合召喚那1隻融合怪獸。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39399168,'夏古拉的復活','「夏古拉」的降臨所必需。必須從我方的手牌、場上解放怪獸直到等級合計為7以上為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39402797,'三叉戟龍軍王',unistr('龍族協調+協調以外的龍族怪獸1隻以上\u000a此卡只能用同步召喚來特殊召喚。\u000a①：此卡同步召喚時，以我方場上最多2張其他卡為對象可以發動。那些我方的卡破壞。此卡在這個回合，除了通常攻擊以外，在1次戰鬥階段中可以攻擊的次數為此效果破壞的卡片數量。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39432962,'怒怒怒魔女','①：此卡召喚、特殊召喚成功時可以發動。從手牌將「怒怒怒魔女」以外的1隻「怒怒怒」怪獸以表側攻擊表示或裡側守備表示特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39439590,'電子恐龍','對手從手牌將怪獸特殊召喚時，可以將此卡從手牌特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39440937,'妨害電波','場上有同步怪獸表側攻擊表示存在的場合可以發動。場上的同步怪獸全部變成守備表示。這個回合的結束階段，場上的同步怪獸全部回到額外牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39454112,'荒唐',unistr('①：只要此卡在魔法與陷阱區域存在，我方或對手擲骰子的場合，可以讓其中1個點數當作以下點數適用。\u000a●擲出1、3、5的場合：當作6。\u000a●擲出2、4、6的場合：當作1。'),'是否使用「荒唐」的效果改變點數？','要改變第幾次骰子的結果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39468724,'灼熱毒槍的影靈衣',unistr('藉由「影靈衣」儀式魔法卡降臨\u000a只能以只使用等級10以外的怪獸的儀式召喚來特殊召喚。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。我方的手牌、場上最多2隻「影靈衣」怪獸解放，從牌組將那個數量的「影靈衣」卡片送去墓地。\u000a②：怪獸的效果發動時，將我方的手牌、場上1隻怪獸解放可以發動。那個發動無效並除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39475024,'骸之魔妖-餓者髑髏',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：「骸之魔妖-餓者髑髏」在我方場上只能有1隻表側表示存在。\u000a②：此卡在墓地存在，我方的連結怪獸被戰鬥或對手的效果破壞的場合可以發動。從我方墓地將1隻其他的不死族怪獸除外，此卡特殊召喚。\u000a③：此卡從墓地特殊召喚成功的場合可以發動。這個回合，表側表示的此卡不受其他卡的效果影響。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39477584,'魔轟神 勒維亞坦',unistr('「魔轟神」協調+協調以外的怪獸1隻以上\u000a①：場上的此卡被破壞送去墓地時，以我方墓地最多3隻「魔轟神」怪獸為對象可以發動。那些怪獸加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39491690,'聖徒救贖',unistr('這個卡名在規則上也當作「白森林」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：最多到我方的場上、墓地的惡魔族、幻想魔族、魔法使族的融合、同步怪獸數量，以場上的卡為對象可以發動。那些卡回到手牌。\u000a②：此卡為了發動怪獸的效果而被送去墓地的場合可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39505816,'炎天禍 日燒',unistr('這個卡名的效果1回合只能使用1次。\u000a①：我方場上的表側表示的炎屬性怪獸被戰鬥或對手的效果破壞的場合可以發動。此卡從手牌特殊召喚。那之後，可以選那1隻破壞的我方墓地的炎屬性怪獸，給予對手那個攻擊力一半數值的傷害。'),'特殊召喚','是否給予對手傷害？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39507162,'鋼刀騎士',unistr('①：只要我方的手牌是1張以下，此卡的攻擊力上升400。\u000a②：我方場上沒有此卡以外的怪獸存在的場合，此卡戰鬥破壞的反轉怪獸的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39512984,'寶石騎士掌門 鑽石',unistr('「寶石騎士」怪獸×3\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：此卡的攻擊力上升我方墓地的「寶石」怪獸數量×100。\u000a②：1回合1次，從我方墓地將1隻等級7以下的「寶石騎士」融合怪獸除外可以發動。此卡直到結束階段得到和除外的怪獸的原本的卡名、效果相同的卡名、效果。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39520293,'廢品盔甲',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：用此卡作為同步素材的同步怪獸不會被戰鬥破壞。\u000a②：不是在這個回合送去墓地的此卡在墓地存在，原卡名包含「戰士」、「同步者」、「星塵」其中任何種類的同步怪獸在我方場上存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'「廢品盔甲」的效果1適用中','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39522887,'游魊之陰影 史諾匹奧斯',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方、對手的主要階段，從我方的手牌、墓地將2隻魚族怪獸除外可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合，以場上1張表側表示卡為對象可以發動。那張卡從場上離開的場合被除外。\u000a③：此卡被除外的場合，從我方墓地將1隻魚族怪獸除外可以發動。此卡加入手牌。'),'從手牌特殊召喚','從場上離開的場合被除外','「游魊的陰影 斯諾皮烏斯」的效果2適用中','此卡加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(39526584,'禮品卡','對手的生命值回復3000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39528955,'劍巫聖像騎士',unistr('包含「聖像騎士」怪獸的效果怪獸2隻\u000a①：此卡的攻擊力上升此卡指向的怪獸的原攻擊力數值。\u000a②：此卡指向的怪獸不能攻擊。\u000a③：1回合1次，此卡指向的區域有效果怪獸特殊召喚的場合，以此卡以外的我方或對手的主要怪獸區域的1隻怪獸為對象可以發動。那隻怪獸的位置向其他的主要怪獸區域移動（不能向從那隻怪獸所見的對手場上移動）。'),'效果3','請選擇要移動的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39531794,'腦部危機','①：以被除外的1隻我方的超能族怪獸為對象可以發動此卡。那隻怪獸特殊召喚。此卡從場上離開時那隻怪獸破壞。那隻怪獸被破壞時此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39537362,'旅人的試煉','①：對手怪獸的攻擊宣言時1次，可以發動此效果。對手隨機選1張我方的手牌，對手猜那張卡的種類（怪獸、魔法、陷阱）。猜錯的場合，那隻攻擊怪獸回到持有者的手牌。','效果1','是否現在發動此卡的效果1？','發動效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39552584,'暗黑界的龍神王 古拉法',unistr('「暗黑界的龍神 古拉法」+闇屬性怪獸\u000a這個卡名的①效果1回合只能使用1次。\u000a①：對手發動怪獸的效果、通常魔法、通常陷阱卡時可以發動。那個效果變成「對手選1張自身的手牌捨棄」。\u000a②：融合召喚的此卡因對手從場上離開的場合可以發動。從我方墓地的怪獸以及被除外的我方怪獸之中，選1隻「暗黑界的龍神 古拉法」特殊召喚。那之後，有手牌的玩家選1張自身的手牌捨棄。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39552864,'神聖球體','被神聖光輝包住的天使靈魂。據域看見其美麗姿態的人，可以實現心中的願望。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39564736,'重鍊裝結合',unistr('①：從我方的手牌、場上將「鍊裝」融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a\u000a※重鍊裝融合'),'融合召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39568067,'命運的旅途',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從牌組將1隻記載「勇者衍生物」的衍生物名的怪獸加入手牌。那之後，選1張我方的手牌送去墓地。\u000a②：怪獸召喚、特殊召喚的場合可以發動。從牌組選1張記載「勇者衍生物」的衍生物名的裝備魔法卡加入手牌或給我方場上1隻「勇者衍生物」裝備。\u000a③：1回合只有1次，已裝備裝備卡的我方怪獸不會被戰鬥破壞。'),'效果1','效果2','裝備','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39568068,'命運的旅途',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從牌組將1隻記載「勇者衍生物」的衍生物名的怪獸加入手牌。那之後，選1張我方的手牌送去墓地。\u000a②：怪獸召喚、特殊召喚的場合可以發動。從牌組選1張記載「勇者衍生物」的衍生物名的裝備魔法卡加入手牌或給我方場上1隻「勇者衍生物」裝備。\u000a③：1回合只有1次，已裝備裝備卡的我方怪獸不會被戰鬥破壞。'),'效果1','效果2','裝備','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39576656,'殺手旋律 爆響',unistr('「殺手旋律 酷莉普」+協調1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。確認對手的額外牌組，其中1張直到結束階段表側除外。那之後，可以讓此卡的攻擊力上升除外的怪獸的攻擊力數值。\u000a②：同步召喚的此卡被送去墓地的場合可以發動。此卡特殊召喚。那之後，可以適用以下效果。\u000a●確認對手的額外牌組，其中2張直到結束階段表側除外。'),'效果1','效果2','是否上升攻擊力？','是否從額外牌組選2張除外？','直到結束階段除外','','','','','','','','','','','');
INSERT INTO texts VALUES(39581190,'地中族的射手',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有此卡以外的「地中族」怪獸存在，此卡向對手的裡側守備表示怪獸攻擊的傷害步驟開始時可以發動。那隻對手怪獸回到持有者的牌組。\u000a②：場上的此卡被戰鬥、效果破壞送去墓地的場合可以發動。從牌組將1隻「地中族」怪獸以表側守備表示或裡側守備表示特殊召喚。'),'回到牌組','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39613288,'黑暗霸權',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：最多到我方墓地的「黑暗結合」以及記載那個卡名的魔法卡數量，以對手場上的表側表示卡為對象可以發動。那些卡的效果直到回合結束時無效。\u000a②：將不是在這個回合送去墓地的此卡從墓地除外，以我方的墓地、除外狀態的最多5隻「HERO」怪獸為對象可以發動。那些怪獸回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39618799,'電子天使－荼吉尼－',unistr('藉由「機械天使的儀式」降臨。\u000a①：此卡儀式召喚成功的場合可以發動。對手必須將自身場上1隻怪獸送去墓地。\u000a②：只要此卡在怪獸區域存在，我方的儀式怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a③：在我方結束階段，以我方墓地的1隻儀式怪獸或1張「機械天使的儀式」為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39622156,'No.26 次元孔路 繞道章魚',unistr('等級3怪獸×2\u000a這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手的戰鬥階段開始時，去除此卡的1個超量素材可以發動。這次戰鬥階段中，只能用1隻怪獸攻擊，那隻怪獸的攻擊變成直接攻擊。\u000a②：怪獸直接攻擊給予戰鬥傷害的傷害步驟結束時發動。那隻攻擊的怪獸的控制權轉移給回合玩家所見的對手。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39643167,'兔耳導師',unistr('①：「兔耳導師」以外的場上的怪獸的效果發動時可以發動（同一連鎖上最多1次）。給那隻怪獸放置1個兔耳計數器。已放置兔耳計數器的怪獸不會被戰鬥破壞。\u000a②：1回合1次，以已放置兔耳計數器的1隻怪獸為對象可以發動。那隻怪獸和此卡直到下個回合的準備階段除外。此效果在對手回合也能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39648965,'機皇兵 神智一型',unistr('①：此卡的攻擊力上升此卡以外的場上的「機皇」怪獸數量×100。\u000a②：1回合1次，此卡以外的我方的「機皇」怪獸向守備表示怪獸攻擊宣言時可以發動。那次戰鬥用那隻我方怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39672388,'進化龍 達爾文翼龍','此卡被「進化蟲」怪獸的效果特殊召喚成功時，可以選擇場上1隻表側表示怪獸等級上升最多2。','請選擇要上升的等級','等級上升1','等級上升2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39674352,'超巨大咖咖吉哥','已經精神崩潰，肉體追求更強的力量而暴走。在它身上再也找不到昔日的面影……','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39680372,'創造的聖刻印',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上1隻龍族超量怪獸為對象可以發動。將原卡名和那隻我方怪獸不同的1隻「聖刻」超量怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。\u000a②：將墓地的此卡除外，以我方墓地1隻「聖刻」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39695323,'隆隆隆巨人',unistr('①：此卡召喚成功時，以我方墓地1隻「隆隆隆」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。那之後，此卡變成守備表示。\u000a②：此卡攻擊的場合，在戰鬥階段結束時變成守備表示。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39699564,'速炎星-戴豹','此卡召喚、特殊召喚成功的回合主要階段時，解放我方場上1隻「炎星」怪獸可以發動。從牌組選1張「炎舞」魔法、陷阱卡在我方場上覆蓋。「速炎星-戴豹」的效果1回合只能使用1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39701395,'調和的寶牌','①：從手牌捨棄1隻攻擊力1000以下的龍族協調可以發動。我方從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39703254,'小番茄','此卡以外的場上的1隻植物族怪獸成為對手的魔法、陷阱卡的效果的對象時，將此卡解放可以發動。從牌組抽2張卡。','抽2張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39706423,'GMX鎮壓部隊 阿普特',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，「GMX」怪獸或恐龍族怪獸在我方場上存在的場合可以發動。此卡特殊召喚。\u000a②：以場上1隻表側表示怪獸為對象可以發動。從我方牌組上方翻開卡片，直到恐龍族怪獸出現為止，那隻恐龍族怪獸送去墓地，對象怪獸的種族直到回合結束時變成恐龍族。剩下的翻開的卡回到牌組。'),'特殊召喚','翻卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39711336,'不死王 巫妖',unistr('此卡不能通常召喚。用「大神官 德那杜」的效果可以特殊召喚。\u000a我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a此卡反轉時，可以選擇我方墓地的1隻不死族怪獸特殊召喚。\u000a以場上表側表示存在的此卡為對象的魔法、陷阱卡發動時，那個發動無效並破壞。'),'變成裡側守備','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39712330,'決戰的火蓋','我方回合的主要階段，將我方墓地的1張怪獸卡除外可以發動此效果。從手牌將1隻通常怪獸通常召喚。','通常召喚','是否現在發動此卡的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39719977,'三蠍聯盟','我方場上有3隻同名的通常怪獸（衍生物以外）存在時可以發動。這個回合，那3隻同名的通常怪獸可以直接攻擊對手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39730727,'天威無崩之地',unistr('①：只要此卡在場地區域存在，效果怪獸以外的場上的表側表示怪獸不受怪獸的效果影響。\u000a②：1回合1次，對手將效果怪獸特殊召喚的場合，如果我方場上有效果怪獸以外的怪獸存在可以發動。我方抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39732186,'禁止檔案蛇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的電子界族連結怪獸和對手怪獸進行戰鬥的傷害步驟開始時，將此卡從手牌送去墓地可以發動。那隻對手怪獸回到持有者的手牌。\u000a②：此卡在墓地存在，我方的電子界族怪獸以戰鬥破壞對手怪獸送去墓地時，從我方墓地將1張卡除外，以我方墓地1隻等級4以下的電子界族怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39733924,'全裝甲超量',unistr('①：場上有超量怪獸存在的場合可以發動。進行1隻超量怪獸的超量召喚。\u000a②：將墓地的此卡除外，以我方場上1隻超量怪獸為對象可以發動。那隻怪獸以外的我方的場上（表側表示）、墓地1隻超量怪獸當作持有以下效果的裝備魔法卡給對象怪獸裝備。\u000a●裝備怪獸的攻擊力上升此卡的攻擊力數值。\u000a●裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。'),'N/A','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39751093,'龍宮之姬',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡召喚、反轉時，可以選擇對手場上的1隻表側表示怪獸的表示形式變更。'),'回到手牌','表示形式變更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39751094,'龍宮之姬',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡召喚、反轉時，可以選擇對手場上的1隻表側表示怪獸的表示形式變更。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39752820,'星鍵士 利伊布',unistr('怪獸2隻\u000a此卡只能在我方墓地有「星遺物」卡片存在的場合連結召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從牌組選1張「星遺物」魔法、陷阱卡在我方場上覆蓋。這個回合，我方墓地沒有「星遺物」怪獸存在的場合，那張卡不能發動。\u000a②：連結召喚的此卡作為連結素材送去墓地的場合可以發動。選場上1張卡回到持有者的牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39753577,'魔妖變生',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了「魔妖」怪獸以外不能從額外牌組特殊召喚。\u000a①：捨棄1張手牌，從我方墓地的怪獸以及被除外的我方怪獸之中以1隻「魔妖」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不會成為對手的效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39761138,'新炎獄薩滿','如果我方墓地有3隻以上「炎獄」怪獸存在，此卡戰鬥破壞對手怪獸的場合，選擇對手墓地的1張卡除外。此效果發動時對手的墓地沒有魔法卡存在的場合，隨後給予對手500傷害。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39761418,'大秘儀之力XIX-太陽',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：持有投擲硬幣效果的卡在場上存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、反轉召喚、特殊召喚的場合發動。投擲1次硬幣，依照那個正反面適用以下效果。\u000a●正：從牌組將1張持有投擲硬幣效果的魔法卡在我方場上覆蓋。\u000a●反：雙方的魔法與陷阱區域的卡全部破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39765115,'飛濺捕獲','對手超量召喚成功時，將我方墓地的2隻魚族怪獸除外可以發動。得到選擇的那1隻超量怪獸的控制權。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39765958,'琰魔龍 暗紅惡魔',unistr('協調+協調以外的怪獸1隻以上\u000a1回合1次，我方的主要階段1可以發動。此卡以外的場上表側攻擊表示存在的怪獸全部破壞。此效果發動的整回合中，此卡以外的怪獸不能攻擊。'),'破壞場上的怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39767432,'索貝克的魔導士',unistr('效果怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡或此卡指向的我方怪獸給予對手戰鬥傷害時可以發動。我方的生命值回復那個數值。\u000a②：我方或對手的生命值回復的場合可以發動（傷害步驟也能發動）。雙方受到1000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39774685,'魔菌',unistr('只能給植物族怪獸裝備。\u000a裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39778366,'聯合緊急出動',unistr('「聯合緊急出動」在1回合只能發動1張。\u000a①：以被除外的我方的機械族、光屬性的最多3隻通常怪獸或聯合怪獸為對象可以發動。那些怪獸特殊召喚。\u000a②：將墓地的此卡除外，以被除外的我方的機械族、光屬性的1隻通常怪獸或聯合怪獸為對象可以發動。那隻怪獸回到手牌。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39806198,'奇巧人偶-磁力玩偶','①：對手場上有怪獸存在，我方場上的怪獸只有「奇巧人偶」怪獸的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39817919,'靈魂鳥-忍鴉',unistr('此卡不能特殊召喚。\u000a①：1回合1次，此卡和對手怪獸進行戰鬥的從傷害步驟開始時到傷害計算前，從手牌捨棄1隻靈魂怪獸可以發動。此卡的攻擊力、守備力直到戰鬥階段結束時上升捨棄的怪獸的攻擊力、守備力的對應數值。\u000a②：此卡召喚、反轉的回合的結束階段發動。此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39823987,'太陽龍 印地',unistr('「赤蟻 阿斯卡托爾」+協調以外的怪獸1隻以上\u000a①：此卡被戰鬥破壞送去墓地的場合發動。將破壞此卡的怪獸破壞，給予對手那個攻擊力一半的傷害。\u000a②：場上的此卡被破壞的下個回合的準備階段，以我方墓地1隻「月影龍 奎拉」為對象可以發動。那隻怪獸特殊召喚。'),'效果1','N/A','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39829561,'D-HERO 死逝小子',unistr('我方的準備階段時，此卡在墓地存在的場合，在對手場上表側攻擊表示特殊召喚。\u000a此卡被戰鬥破壞的場合，不送去墓地而是除外。\u000a此卡被效果從手牌或牌組送去墓地的場合，不送去墓地而是除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39838559,'F.A. 賽道大獎賽',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在場地區域存在，場上的「F.A.」怪獸的等級在戰鬥階段期間上升2。\u000a②：1回合1次，我方的「F.A.」怪獸戰鬥破壞對手怪獸時可以發動。我方從牌組抽1張卡。\u000a③：場上的表側表示的此卡被效果破壞的場合可以發動。從牌組將「F.A. 賽道大獎賽」以外的1張「F.A.」卡片加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39848658,'白骨主宰者',unistr('①：我方的「白骨王」向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：1回合1次，以我方墓地1隻「白骨」或「白骨王」為對象可以發動。從牌組將1隻「白骨」或記載那個卡名的怪獸送去墓地，對象怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了不死族怪獸以外不能特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39853199,'妖仙獸 閻魔巳裂',unistr('①：此卡和風屬性以外的表側表示怪獸進行戰鬥的傷害步驟開始時可以發動。那隻怪獸破壞。\u000a②：此卡靈擺召喚成功時，以對手場上的1張卡為對象可以發動。那張卡破壞。\u000a③：此卡特殊召喚的回合的結束階段發動。此卡回到持有者的手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39880350,'聖天樹的精靈',unistr('包含「聖天樹」連結怪獸的植物族怪獸2隻\u000a①：此卡不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。\u000a②：我方因戰鬥、效果受到傷害的場合可以發動。我方的生命值回復那個數值，從額外牌組將1隻「聖蔓」怪獸特殊召喚。這個效果1回合可以使用最多2次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39881252,'興妖迪亞貝爾',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：魔法、陷阱卡為了發動卡的效果而被送去墓地的場合可以發動。從手牌、牌組、額外牌組將1隻幻想魔族、魔法使族怪獸送去墓地。\u000a②：我方主要階段，從我方墓地將包含此卡的3張魔法、陷阱卡除外可以發動。從我方的手牌、墓地將1隻「迪亞貝爾」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39890958,'強化支援機械 重型裝甲',unistr('①：此卡召喚成功的場合，以我方墓地1隻聯合怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：1回合1次，可以從以下效果選擇1個發動。\u000a●以我方場上1隻機械族怪獸為對象，此卡當作裝備卡給那隻怪獸裝備。裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備的此卡特殊召喚。\u000a③：裝備怪獸不會成為對手的效果的對象。'),'N/A','N/A','效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39892082,'氣球蜥蝪',unistr('每次我方的準備階段，給此卡放置1個計數器。\u000a此卡被破壞的場合，給予破壞此卡的卡的控制者計數器數量×400傷害。'),'放置計數器','給予傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39897277,'精靈之光',unistr('只能給光屬性怪獸裝備。\u000a裝備怪獸的攻擊力上升400，守備力下降200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39900763,'異次元的邂逅','①：雙方都有被除外的自己的怪獸1隻以上存在的場合可以發動。雙方玩家各自選被除外的1隻自己的怪獸裡側守備表示特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39905966,'咒法紋章魚','此卡召喚、反轉召喚、特殊召喚成功時，可以選擇我方墓地的1隻「咒法」儀式怪獸或1張「咒法」儀式魔法卡加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39910367,'魔法都市 安迪米翁',unistr('①：只要此卡在場地區域存在，每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a②：已放置魔力計數器的卡被破壞的場合，依照那些卡放置的魔力計數器的數量，給此卡放置魔力計數器。\u000a③：1回合1次，我方為了發動卡的效果而去除我方場上的魔力計數器的場合，可以從此卡去除作為代替。\u000a④：此卡被破壞的場合，可以去除此卡的1個魔力計數器作為代替。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39913299,'真實之名',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：宣言1個卡名可以發動。翻開我方牌組最上方的卡，如果是宣言的卡，那張卡加入手牌。那之後，可以從牌組將1隻神屬性怪獸加入手牌或特殊召喚。如果不是，翻開的卡送去墓地。'),'是否從牌組將1隻怪獸加入手牌或特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39915560,'飢餓毒液捕食結合龍',unistr('闇屬性的融合怪獸+融合怪獸\u000a這個卡名在規則上也當作「捕食植物」卡片。這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，魔法、陷阱、怪獸的效果發動時可以發動。我方或對手場上1隻已放置捕食計數器的怪獸解放，那個發動無效。\u000a②：融合召喚的此卡被對手送去墓地的場合，以我方墓地1隻闇屬性怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39931513,'天盃龍 白龍',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組選1張「燦幻」魔法、陷阱卡加入手牌或在我方場上覆蓋。\u000a②：只要此卡在怪獸區域存在，我方的龍族、炎屬性怪獸的戰鬥發生的對我方的戰鬥傷害變成0。\u000a③：1回合1次，我方、對手的戰鬥階段可以發動。用包含此卡的我方場上的怪獸為素材進行同步召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39943352,'液狀巨人 脹流大太郎',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：以我方場上1隻超量怪獸為對象可以發動。此卡作為那隻怪獸的超量素材。\u000a【怪獸效果】\u000a等級4怪獸×2\u000a等級4可以靈擺召喚的場合，額外牌組的表側表示的此卡可以靈擺召喚。\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材可以發動。此卡在我方的靈擺區域放置。那之後，可以從我方墓地將1隻靈擺怪獸表側加入額外牌組。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','是否從我方墓地選1隻靈擺怪獸加入額外牌組？','','','','','','','','','','','','');
INSERT INTO texts VALUES(39956951,'封魔一閃','對手場上的怪獸區域全部都有怪獸存在的場合可以發動。對手場上的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39964797,'水晶機巧-量子石英',unistr('協調+協調以外的怪獸1隻以上\u000a①：對手的主要階段以及戰鬥階段可以發動。用包含此卡的我方場上的怪獸為同步素材同步召喚。\u000a②：同步召喚的此卡被戰鬥、效果破壞的場合，以同步怪獸以外的我方墓地1隻「水晶機巧」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'同步召喚','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39967326,'過早的復活','選擇我方墓地的1隻「地縛神」怪獸可以發動。選擇的怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊宣言。此效果特殊召喚的怪獸進行戰鬥的場合，對手玩家受到的戰鬥傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39972129,'No.64 古狸三太夫',unistr('獸族等級2怪獸×2\u000a①：只要我方場上有其他的獸族怪獸存在，此卡不會被戰鬥、效果破壞。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。在我方場上將1隻「影武者狸衍生物」（獸族、地、等級1、攻?/守0）特殊召喚。這個衍生物的攻擊力變成和場上的怪獸的最高的攻擊力相同。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39972130,'影武者狸衍生物','由「No.64 古狸三太夫」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39973386,'表裡一體',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻光、闇屬性怪獸解放可以發動。從手牌、額外牌組將1隻和那隻怪獸原本的種族、等級相同且原屬性不同的光、闇屬性怪獸特殊召喚。\u000a②：我方主要階段將墓地的此卡除外，以我方墓地的光、闇屬性怪獸各1隻為對象可以發動。那2隻怪獸回到牌組洗牌。那之後，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39978267,'電子襲擊者',unistr('此卡召喚、反轉召喚、特殊召喚成功時，從以下效果選擇1個發動。\u000a●選擇場上的1隻怪獸裝備的1張裝備卡破壞。\u000a●選擇場上的1隻怪獸裝備的1張裝備卡給此卡裝備。'),'效果1','●破壞裝備卡','●裝備卡給此卡裝備','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39980304,'連鎖物質','此卡發動的回合中我方融合召喚的場合，可以將融合怪獸卡記載的融合素材怪獸從我方的手牌、牌組、場上、墓地除外作為融合素材。此卡發動的整回合中，我方不能攻擊，此效果融合召喚的融合怪獸在結束階段時破壞。','是否使用「連鎖物質」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39984786,'產卵短吻鱷','解放爬蟲類族怪獸將此卡上級召喚成功的場合，這個回合的結束階段時，從墓地選擇1隻為了此卡的上級召喚而解放的怪獸在我方場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39987164,'大日神械迪西格瑪',unistr('等級4怪獸×3\u000a1回合1次，去除此卡的1個超量素材可以發動。選擇對手場上表側攻擊表示存在的1隻效果怪獸，當作裝備卡給此卡裝備。\u000a此卡和屬性與此效果裝備的怪獸卡相同的怪獸進行戰鬥的場合，不進行傷害計算，那隻怪獸破壞。'),'變成裝備卡','破壞怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39987731,'威脅的人造人-念力震懾者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方或對手的場上、墓地有陷阱卡存在的場合可以發動。此卡從手牌特殊召喚。此效果特殊召喚的此卡的等級直到回合結束時變成6。\u000a②：我方、對手的主要階段，解放此卡可以發動。從我方的手牌、墓地選1隻「人造人-念力震懾者」特殊召喚。那之後，可以將對手場上的陷阱卡全部破壞（如果那些卡被覆蓋，則翻開確認）。'),'效果1','效果2','是否把對手場上的陷阱卡全部破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39996157,'機械天使的儀式',unistr('「電子天使」儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻「電子天使」儀式怪獸。\u000a②：我方場上的光屬性怪獸被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39998992,'超機怪蟲 對觀突觸',unistr('地屬性怪獸2隻\u000a①：此卡指向的「機怪蟲」怪獸不會被戰鬥破壞，攻擊力、守備力上升300，在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a②：表側表示的此卡因對手的效果從場上離開的場合，或被戰鬥破壞的場合，以我方墓地2隻「機怪蟲」怪獸為對象可以發動（同名卡最多1張）。那些怪獸裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40003819,'轉臨的守護龍',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的場上、墓地將融合怪獸卡決定的融合素材怪獸除外，從額外牌組融合召喚那1隻融合怪獸。此時融合素材怪獸必須全部都是連結怪獸。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40005099,'不知火流 轉生之陣',unistr('「不知火流 轉生之陣」在1回合只能發動1張。\u000a①：1回合1次，我方場上沒有怪獸存在的場合，可以將1張手牌送去墓地，從以下效果選擇1個發動。\u000a●以我方墓地1隻守備力0的不死族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a●以被除外的1隻我方的守備力0的不死族怪獸為對象可以發動。那隻怪獸回到墓地。'),'●從墓地特殊召喚','●回到墓地','請選擇要回到墓地的不死族怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40012727,'爆裂斬','我方場上有「/爆裂」怪獸表側表示存在的場合可以發動。場上表側表示存在的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40028305,'超重武者裝留 光爪',unistr('「超重武者裝留 光爪」的②效果1回合只能使用1次。\u000a①：我方主要階段以我方場上1隻「超重武者」怪獸為對象可以發動。從我方的手牌、場上將這隻怪獸當作攻擊力、守備力上升500的裝備卡給那隻我方怪獸裝備。裝備怪獸不會被戰鬥破壞。\u000a②：此卡的效果讓此卡裝備中的場合可以發動。裝備的此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40041559,'指環的精靈 傑妮亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，以場上1隻表側表示怪獸為對象可以發動。此卡特殊召喚。作為對象的表側表示怪獸變成魔法使族，這個回合只有1次不會被效果破壞。這個回合，我方除了魔法使族怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡為了發動魔法使族怪獸的效果而被解放的場合或除外的場合可以發動。此卡加入手牌。'),'特殊召喚','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40044918,'E.HERO 空氣人',unistr('①：此卡召喚、特殊召喚時，可以從以下效果選擇1個發動。\u000a●最多到我方場上的其他的「HERO」怪獸數量，將場上的魔法、陷阱卡破壞。\u000a●從牌組將1隻「HERO」怪獸加入手牌。'),'效果1','●破壞魔法、陷阱卡','●「HERO」怪獸加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40044919,'E.HERO 空氣人',unistr('①：此卡召喚、特殊召喚時，可以從以下效果選擇1個發動。\u000a●最多到我方場上的其他的「HERO」怪獸數量，將場上的魔法、陷阱卡破壞。\u000a●從牌組將1隻「HERO」怪獸加入手牌。'),'效果1','●破壞魔法、陷阱卡','●「HERO」怪獸加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40048324,'秘術魔刃','此卡被同步怪獸的同步召喚使用送去墓地的場合，可以從我方牌組將1張「爆裂模式」加入手牌。','從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40061558,'隱藏的機殼核心 無神論',unistr('此卡不能特殊召喚，只能解放我方場上3隻「機殼」怪獸來通常召喚。\u000a①：通常召喚的此卡不受魔法、陷阱卡的效果影響，也不受原本的等級或階級低於此卡的等級的怪獸發動的效果影響。\u000a②：1回合1次，以對手場上的1隻怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。'),'解放3隻怪獸通常召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40080312,'E.HERO 星雲新宇俠',unistr('「E.HERO 新宇俠」+「新空間俠 大地鼴鼠」+「新空間俠 漆黑獵豹」\u000a只能讓我方場上的上述卡回到牌組，從額外牌組特殊召喚。（不需要「融合」）\u000a①：此卡從額外牌組特殊召喚成功的場合發動。我方依照對手場上的卡片數量從牌組抽牌。那之後，選場上1張表側表示的卡，那個效果直到回合結束時無效。\u000a②：結束階段發動。此卡回到額外牌組，場上的卡全部裡側表示除外。'),'N/A','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40089744,'混沌之場',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，從牌組將1隻「混沌士兵」儀式怪獸或「暗黑騎士蓋亞」怪獸加入手牌。\u000a②：只要此卡在場地區域存在，每次從雙方的手牌、場上有怪獸被送去墓地，每有1隻給此卡放置1個魔力計數器（最多6個）。\u000a③：1回合1次，去除此卡的3個魔力計數器可以發動。我方從牌組將1張儀式魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40101111,'究極念動力者',unistr('超能族同步怪獸+超能族怪獸\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：此卡只要在怪獸區域存在，不會被效果破壞。\u000a②：此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a③：此卡戰鬥破壞怪獸送去墓地的場合發動。我方的生命值回復那隻怪獸的原攻擊力數值。'),'回復','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40110009,'龍女僕的更衣',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方的手牌、場上的怪獸作為融合素材，將1隻龍族融合怪獸融合召喚。\u000a②：此卡在墓地存在的場合，以我方場上1隻「龍女僕」怪獸為對象可以發動。此卡加入手牌，那隻怪獸回到手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40133511,'食魂者 巴茲','1回合1次，將我方墓地最多3隻怪獸除外可以發動。此卡的攻擊力直到對手回合結束時上升除外的怪獸數量×300。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40139997,'紅蓮薔薇龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡同步召喚的場合可以發動。雙方墓地的卡全部除外。此卡用「黑薔薇龍」或植物族同步怪獸為素材同步召喚的場合，隨後可以將場上的其他卡全部破壞。\u000a②：對手發動要讓卡片破壞的效果時，將此卡解放可以發動。那個發動無效。那之後，可以從我方的額外牌組、墓地將1隻「黑薔薇龍」特殊召喚。'),'效果1','效果2','是否將此卡以外雙方場上的卡全部破壞？','是否從我方的額外牌組、墓地選1隻「黑薔薇龍」特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(40140448,'戰華之仲-孫謀',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有其他的「戰華」怪獸存在，對手不能選擇此卡作為攻擊對象。\u000a②：從我方的手牌、場上將1張卡送去墓地可以發動。從牌組將「戰華之仲-孫謀」以外的1隻「戰華」怪獸加入手牌。\u000a③：此卡以外的我方的「戰華」怪獸的效果發動的場合，以對手場上1隻怪獸為對象可以發動。那隻怪獸回到持有者的手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40143123,'室女星聖 角宿一','此卡召喚成功時，可以從手牌將1張等級5的「星聖」怪獸表側守備表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40155014,'百夫長騎士魔防陣',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以場上1張表側表示的怪獸卡為對象可以發動。那張卡除外。下個回合的準備階段，此效果除外的怪獸在持有者的場上特殊召喚。\u000a②：將墓地的此卡除外，以我方墓地1隻「百夫長」同步怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸的攻擊力下降1500。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40155554,'盟軍之心','為了強化正義盟軍的思考迴路而開發的高性能裝置。採集從蠕蟲星雲飛來的隕石，擁有很高的調和能力。那個未知的力量到現在還沒有明朗。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40159926,'鏡子共鳴體',unistr('「鏡子共鳴體」的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在，從額外牌組特殊召喚的怪獸只在對手場上存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。此卡在這個回合作為同步素材的場合，等級當作對象怪獸的原等級。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40160226,'機海龍 蛇頸龍','我方場上有海龍族怪獸存在的場合，此卡可以不用解放來召喚。1回合1次，藉由解放我方場上的1隻水屬性怪獸，選擇對手場上表側表示存在的1張卡破壞。','不解放的召喚','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40164421,'光道少女 密涅瓦',unistr('①：此卡召喚成功時可以發動。從牌組將1隻等級在我方墓地的「光道」怪獸種類的數量以下的龍族、光屬性怪獸加入手牌。\u000a②：此卡從手牌、牌組送去墓地的場合發動。從我方牌組上方將1張卡送去墓地。\u000a③：我方結束階段發動。從我方牌組上方將2張卡送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40172183,'狹窄通路','雙方場上的怪獸各自都是2隻以下時可以發動。雙方玩家可以在自身場上召喚的怪獸最多只有2隻。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40173854,'水陸兩用戰鬥艇','「陸戰型 戰鬥艦」+「守海戰士」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40177746,'外星生命體',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡被送去墓地的場合，將此卡以外的我方的場上、墓地最多2隻天使族、光屬性怪獸除外可以發動。從牌組將除外數量的「外星生命體」以外的等級2以下的天使族、光屬性怪獸加入手牌（同名卡最多1張）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40189917,'炎獄死亡砲手',unistr('此卡不能特殊召喚。只能解放我方場上的1隻「炎獄」怪獸來召喚。\u000a1回合1次，藉由將我方墓地的1隻守備力200的怪獸除外，給予對手那隻怪獸的攻擊力數值的傷害。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40196604,'黑暗陰影','從水晶中發射強烈的光線進行攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40200834,'沉睡的獅子','平時沉睡著的猛獸。一旦甦醒就使人招架不住。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40204620,'巨石遺物升格',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方場上1隻等級4以下的怪獸為對象可以發動。那隻怪獸的等級直到回合結束時變成原等級的2倍。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40213117,'預言魔導弓士 拉穆爾','1回合1次，向對手展示手牌的1張「魔導書」魔法卡可以發動。從手牌將1隻等級4以下的魔法使族怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40216089,'白金小工具',unistr('機械族怪獸2隻\u000a此卡在連結召喚的回合不能作為連結素材。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將1隻等級4以下的機械族怪獸在此卡指向的我方場上特殊召喚。\u000a②：此卡被戰鬥、效果破壞的場合可以發動。從牌組將1隻等級4的「小工具」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40217358,'藍塵妖','此卡不能解放，也不能當作融合、同步、超量召喚的素材。場上的此卡被破壞時，隨機選此卡的控制者的1張手牌，直到下個回合的準備階段時裡側表示除外。「藍塵妖」在我方場上只能有1隻表側表示存在。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40221691,'幻惑的魔術師',unistr('①：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a②：此卡和對手怪獸進行戰鬥的傷害步驟結束時可以發動。得到那隻對手怪獸的控制權。\u000a③：1回合1次，此卡以外的怪獸攻擊的傷害步驟開始時可以發動。場上1張卡破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40225398,'雙擊破壞者',unistr('①：此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：此卡向守備表示怪獸進行攻擊的場合，只有1次可以繼續攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40227329,'GO-DDD神零王 零神零兒',unistr('【靈擺效果】\u000a這個卡名的①②靈擺效果1回合各能使用1次。\u000a①：此卡在靈擺區域存在，我方受到效果傷害的場合，那次傷害變成0。\u000a②：只要此卡在靈擺區域存在，我方將等級5以上的「DD」怪獸召喚的場合可以不用解放。\u000a【怪獸效果】\u000a①：解放此卡以外的我方場上1隻怪獸可以發動。從以下效果挑選1個，直到回合結束時適用。\u000a●此卡可以直接攻擊。\u000a●對手不能發動魔法與陷阱區域的卡的效果。\u000a●對手不能發動手牌、墓地的卡的效果。\u000a②：如果對手的生命值是4000以下，此卡的攻擊宣言時可以發動。此卡的攻擊力直到回合結束時上升對手的生命值數值。\u000a③：此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。'),'●此卡可以直接攻擊','●對手不能發動魔法與陷阱區域的效果','●對手不能發動手牌、墓地的效果','效果1','不解放的召喚（GO-DDD神零王 零神零兒）','','','','','','','','','','','');
INSERT INTO texts VALUES(40230018,'魔導書庫 柯瑞森','我方墓地沒有「魔導書」魔法卡存在的場合可以發動。從牌組選3種「魔導書」魔法卡向對手展示，對手從其中隨機選1張。對手選的1張卡加入我方的手牌，剩下的卡回到牌組。「魔導書庫 柯瑞森」在1回合只能發動1張，此卡發動的整回合中，我方不能發動「魔導書」卡片以外的魔法卡。','展示3張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40237839,'羽翼栗子球・薩帕迪艾爾 LV10',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡，支付一半生命值可以發動。從牌組將1張「融合」魔法卡或「結合」魔法卡加入手牌，此卡回到牌組。這個回合，我方除了「HERO」怪獸以外不能從額外牌組特殊召喚。\u000a②：對手回合，我方的生命值是1000以下的場合可以發動。此卡從手牌特殊召喚。那之後，可以給予對手相當於對手場上的怪獸的最高攻擊力數值的傷害。'),'效果1','效果2','是否給予傷害？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40237840,'羽翼栗子球・薩帕迪艾爾 LV10',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡，支付一半生命值可以發動。從牌組將1張「融合」魔法卡或「結合」魔法卡加入手牌，此卡回到牌組。這個回合，我方除了「HERO」怪獸以外不能從額外牌組特殊召喚。\u000a②：對手回合，我方的生命值是1000以下的場合可以發動。此卡從手牌特殊召喚。那之後，可以給予對手相當於對手場上的怪獸的最高攻擊力數值的傷害。'),'效果1','效果2','是否給予傷害？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40240595,'進化之繭',unistr('手牌的此卡可以當作裝備卡，選擇我方場上的1隻「小毛蟲」裝備。\u000a這個效果裝備此卡的「小毛蟲」的原本的攻擊力、守備力適用「進化之繭」的數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40251688,'焰聖騎士導-羅蘭',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚成功的場合可以發動。這個回合的結束階段，從牌組將1張裝備魔法卡送去墓地。那之後，從牌組將1隻戰士族怪獸加入手牌。\u000a②：此卡在墓地存在的場合，我方、對手的主要階段，以我方場上1隻戰士族怪獸為對象可以發動。此卡當作攻擊力上升500的裝備卡給那隻我方怪獸裝備。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40252269,'魔術師的再演',unistr('①：此卡在場上表側表示存在期間只有1次，以我方墓地1隻等級3以下的魔法使族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。從牌組將「魔術師的再演」以外的1張「魔術師」永續魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40253382,'TG-SX1','我方場上的「T.G.」怪獸戰鬥破壞對手怪獸送去墓地時可以發動。選擇我方墓地的1隻「T.G.」同步怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40267580,'腦袋怪','反轉：此卡當作裝備卡給對手場上的1隻怪獸裝備。得到裝備此卡的怪獸的控制權。對手的準備階段時，對手回復500生命值。','裝備取得控制權','LP回復','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40279770,'黑羽的引導','由於卡片效果使我方受到傷害時可以發動。從手牌將1隻等級4以下的「BF」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40318957,'娛樂夥伴 骷髏雜技小丑',unistr('【靈擺效果】\u000a①：我方除了「娛樂夥伴」怪獸、「魔術師」靈擺怪獸、「異色眼」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a【怪獸效果】\u000a①：此卡召喚時可以發動。「娛樂夥伴 骷髏雜技小丑」以外的「娛樂夥伴」怪獸、「魔術師」靈擺怪獸、「異色眼」怪獸之中，從牌組將其中任何1張加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40320754,'毒王','此卡被戰鬥破壞送去墓地的場合，選擇「毒王」以外的我方墓地1隻植物族怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40343749,'屋塵妖','①：場上的表側表示的此卡被對手的效果破壞送去墓地時，或在傷害步驟開始時是表側表示的此卡被對手怪獸戰鬥破壞送去墓地時可以發動。從手牌、牌組選任意數量的「塵妖」怪獸，在雙方場上將相同數量的怪獸特殊召喚。','特殊召喚','請選擇在我方場上特殊召喚的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40348946,'高能同步者','此卡被龍族怪獸的同步召喚使用送去墓地的場合，以此卡為同步素材的同步怪獸的攻擊力上升800，在結束階段除外。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40350910,'膽小之風','直到下個對手回合結束時，場上覆蓋的魔法、陷阱卡不會被破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40352445,'凶教導的白騎士',unistr('藉由「凶教導的福音」降臨\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方不能從額外牌組將怪獸特殊召喚。\u000a②：對手發動魔法、陷阱、怪獸的效果的場合可以發動。從我方的額外牌組將1隻怪獸送去墓地，確認對手的額外牌組，將其中1隻怪獸送去墓地。此卡的攻擊力直到回合結束時上升送去墓地的怪獸的攻擊力合計數值的一半。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40364916,'不知火流 傳承之陣',unistr('①：只要此卡在魔法與陷阱區域存在，卡名當作「不知火流 轉生之陣」。\u000a②：1回合1次，可以從以下效果選擇1個發動。\u000a●從我方墓地將1隻不死族怪獸除外可以發動。這個回合，我方的不死族怪獸的召喚、特殊召喚不會被無效化。\u000a●以我方場上1隻不死族怪獸為對象可以發動。那隻怪獸除外。那之後，可以從牌組將1隻守備力0的不死族怪獸送去墓地。'),'●召喚不會被無效化','●除外場上的怪獸','是否從牌組把怪獸送去墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40366667,'靈主王的波動',unistr('這個卡名的卡在1回合只能發動1張。對手場上有卡存在的場合，此卡也能從手牌發動。\u000a①：包含將怪獸特殊召喚效果的魔法、陷阱、怪獸的效果發動時可以發動。那個效果無效。我方墓地有陷阱卡存在的場合，再將那張無效的卡破壞。此卡從手牌發動的場合，發動後，這次決鬥中我方不能發動光、地、風屬性怪獸的效果。\u000a\u000a※靈王的波動'),'N/A','適用「靈主王的波動」的效果來發動','「靈主王的波動」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40366668,'靈主王的波動',unistr('這個卡名的卡在1回合只能發動1張。對手場上有卡存在的場合，此卡也能從手牌發動。\u000a①：包含將怪獸特殊召喚效果的魔法、陷阱、怪獸的效果發動時可以發動。那個效果無效。我方墓地有陷阱卡存在的場合，再將那張無效的卡破壞。此卡從手牌發動的場合，發動後，這次決鬥中我方不能發動光、地、風屬性怪獸的效果。\u000a\u000a※靈王的波動'),'N/A','適用「靈主王的波動」的效果來發動','「靈主王的波動」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40371092,'白夜的騎士 蓋亞',unistr('「白夜的騎士 蓋亞」的以下效果1回合各能使用1次。\u000a●將此卡以外的我方場上1隻光屬性怪獸解放可以發動。從牌組將1隻戰士族、闇屬性、等級4怪獸加入手牌，那之後將1張手牌送去墓地。\u000a●將我方墓地1隻闇屬性怪獸除外，選擇場上1隻怪獸可以發動。選擇的怪獸的攻擊力直到對手的回合結束時下降500。'),'加入手牌','攻擊力下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40374923,'猛獁象的墓場','守護同伴的墳墓的猛獁象。毫不留情地攻擊盜墓者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40380686,'泥龍寶寶',unistr('①：將我方場上的此卡作為同步素材的場合，可以將此卡當作協調以外的怪獸。\u000a②：此卡作為同步素材送去墓地的場合，宣言1個種族或屬性，以我方場上1隻同步怪獸為對象可以發動。那隻怪獸直到回合結束時變成宣言的種族或屬性。'),'改變種族','改變屬性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40383551,'大寒氣','這個回合，我方不能使用魔法、陷阱卡的效果，也不能發動或覆蓋。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40384720,'音速射手','對手的魔法與陷阱區域沒有卡存在的場合，此卡可以直接攻擊對手。此時給予對手的戰鬥傷害為此卡的原攻擊力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40387124,'在深淵綻放之花','默默生長在黑暗的深淵裡的花，平常很難見到。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40390147,'輝光皇帝 蓋勒克西恩',unistr('等級4的「光子」怪獸×2\u000a1回合1次，去除此卡最多2個超量素材可以發動。依照為了發動這個效果去除的超量素材數量適用以下效果。\u000a●1個：從手牌將1隻「銀河眼光子龍」特殊召喚。\u000a●2個：從牌組將1隻「銀河眼光子龍」特殊召喚。'),'特殊召喚','●去除1個超量素材','●去除2個超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40391316,'搗蛋騎士',unistr('「搗蛋」怪獸×2\u000a①：此卡在怪獸區域表側表示存在期間，指定最多2格沒有使用的對手的怪獸區域，那些區域不能使用。'),'是否繼續選擇第2個區域？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40392714,'方界帝 風神蓋爾',unistr('此卡不能通常召喚。將我方場上1隻「方界」怪獸送去墓地可以特殊召喚。\u000a①：這個方法特殊召喚的此卡的攻擊力上升800。\u000a②：此卡從手牌特殊召喚成功的場合發動。給予對手800傷害。\u000a③：此卡戰鬥的傷害步驟結束時，以我方墓地最多2隻「方界胤 毗濕奴」為對象可以發動。此卡送去墓地，對象怪獸特殊召喚。那之後，可以從牌組將1隻「方界帝 火神德拉耆尼」加入手牌。'),'是否把1隻「方界帝 火神德拉耆尼」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40398073,'龍女僕 育嬰龍女',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，除了「龍女僕 育嬰龍女」以外，以我方墓地1隻等級4以下的「龍女僕」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方、對手的戰鬥階段開始時可以發動。此卡回到手牌，從我方的手牌、墓地將1隻等級7的「龍女僕」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40410110,'鍊金生物 人工生命體','1回合1次，我方的主要階段時可以發動。變更此卡的屬性。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40418351,'鎧黑龍-電子暗黑龍',unistr('「電子暗黑角」+「電子暗黑刃」+「電子暗黑骨」\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡特殊召喚成功的場合，以我方墓地1隻龍族怪獸為對象發動。那隻龍族怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力數值以及我方墓地的怪獸數量×100。\u000a③：此卡被戰鬥破壞的場合，將裝備的那隻怪獸破壞作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40424929,'烈華砲艦 撫子',unistr('等級3怪獸×3\u000a去除此卡的1個超量素材可以發動。給予對手相當於對手的手牌數量×200傷害。「烈華砲艦 撫子」的效果1回合只能使用1次。'),'給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40428851,'戰華之德-劉玄',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有其他的「戰華」怪獸存在，對手不能選擇此卡作為攻擊對象。\u000a②：對手場上的怪獸數量比我方場上的怪獸多的場合，從我方的手牌、場上將1張卡送去墓地可以發動。從牌組將「戰華之德-劉玄」以外的1隻「戰華」怪獸特殊召喚。\u000a③：此卡以外的我方的「戰華」怪獸進行戰鬥的攻擊宣言時可以發動。我方從牌組抽1張卡。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40441990,'星遺物-『星鍵』',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌捨棄1張「星遺物」卡片可以發動。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以上級召喚。\u000a②：此卡和對手的連結怪獸進行戰鬥的傷害步驟開始時可以發動。那隻怪獸回到持有者的額外牌組。'),'效果1','效果2','上級召喚（星遺物-『星鍵』）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40450317,'同胞的牽絆',unistr('此卡發動的整回合中，我方不能進行戰鬥階段。\u000a①：支付2000生命值，以我方場上1隻等級4以下的怪獸為對象可以發動。和那隻怪獸卡名不同，且種族、屬性、等級相同的2隻怪獸從牌組特殊召喚（同名卡最多1張）。此卡的發動後，直到回合結束時我方不能將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40453765,'野蠻人2號','①：我方場上每有1隻「野蠻人1號」，此卡的攻擊力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40456412,'霸王龍的奇蹟',unistr('①：我方場上有「霸王龍 札克」存在的場合，可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●我方場上1張「霸王龍 札克」破壞，從牌組、額外牌組將1隻「異色眼」靈擺怪獸或光屬性的「霸王龍 札克」無視召喚條件特殊召喚。\u000a●我方的額外牌組1隻表側的靈擺怪獸在我方的靈擺區域放置。\u000a●從牌組將1張速攻魔法卡在我方場上覆蓋。'),'效果1','●破壞並特殊召喚','●從額外牌組放置靈擺怪獸','●從牌組覆蓋速攻魔法卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(40460013,'炎魔的觸媒',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡和手牌的1隻惡魔族怪獸可以發動。那2隻之中的1隻特殊召喚，另1隻捨棄。\u000a②：此卡在墓地存在的狀態，我方的惡魔族怪獸的戰鬥讓怪獸被破壞時可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40465719,'凡人的施捨','從牌組抽2張卡，那之後從手牌將1隻通常怪獸除外。手牌沒有通常怪獸的場合，手牌全部送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40473581,'雷帝神',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡給予對手的戰鬥傷害變成一半。'),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40493210,'魔鍵錠－施－',unistr('①：將衍生物以外的我方場上1隻通常怪獸或「魔鍵」怪獸解放，以我方墓地最多2隻等級合計為8以下的通常怪獸或「魔鍵」怪獸為對象可以發動。那些怪獸守備表示特殊召喚。那之後，可以從以下效果挑選1個適用。\u000a●用我方場上的怪獸為同步素材將1隻「魔鍵」同步怪獸同步召喚。\u000a●用我方場上的怪獸為超量素材將1隻「魔鍵」超量怪獸超量召喚。'),'●同步召喚','●超量召喚','都不選擇','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40502912,'幻奏的音女 亞莉亞','①：只要特殊召喚的此卡在怪獸區域存在，我方場上的「幻奏」怪獸不會成為效果的對象，不會被戰鬥破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40509732,'鬼動武者',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡和對手怪獸進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法、陷阱、怪獸的效果，只在那次戰鬥階段期間那隻對手怪獸的效果無效化。\u000a②：表側表示的此卡因對手的效果從場上離開的場合，以我方墓地1隻機械族怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40516623,'相撲魂 YOKO-ZUNA',unistr('【靈擺效果】\u000a①：場上有怪獸靈擺召喚的場合發動。靈擺區域的此卡回到持有者的手牌。\u000a【怪獸效果】\u000a①：此卡召喚成功時可以發動。和我方的靈擺區域的卡相同縱列的對手怪獸全部送去墓地。\u000a②：此卡召喚、反轉的回合的結束階段發動。此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40522482,'摩天射擊','①：以我方場上1隻「E.HERO」融合怪獸為對象可以發動。攻擊力高於那隻怪獸的對手場上的表側表示怪獸全部破壞。那之後，給予對手此效果破壞送去墓地的怪獸之中原攻擊力最高的怪獸的那個數值的傷害。我方的場地區域有「摩天樓」場地魔法卡存在的場合，給予對手的傷害變成此效果破壞送去墓地的怪獸全部的原攻擊力的合計數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40529384,'爆破翼龍',unistr('協調+協調以外的龍族怪獸1隻以上\u000a此卡和攻擊力在此卡的攻擊力以下的場上表側表示存在的怪獸進行戰鬥的場合，可以不進行傷害計算，那隻怪獸破壞，給予對手那個攻擊力數值的傷害。'),'進行戰鬥的怪獸破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40542825,'憑依裝著-萊娜',unistr('①：此卡可以將我方場上的表側表示的1隻「光靈使 萊娜」和1隻光屬性怪獸送去墓地，從手牌、牌組特殊召喚。\u000a②：此卡的①方法特殊召喚成功時可以發動。從牌組將「憑依裝著-萊娜」以外的1隻守備力1500的魔法使族怪獸加入手牌。\u000a③：此卡的①方法特殊召喚的此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40542826,'憑依裝著-萊娜',unistr('①：此卡可以將我方場上的表側表示的1隻「光靈使 萊娜」和1隻光屬性怪獸送去墓地，從手牌、牌組特殊召喚。\u000a②：此卡的①方法特殊召喚成功時可以發動。從牌組將「憑依裝著-萊娜」以外的1隻守備力1500的魔法使族怪獸加入手牌。\u000a③：此卡的①方法特殊召喚的此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40543231,'巳劍之尊 麁正',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，或此卡被解放的場合可以發動。從牌組將「巳劍之尊 麁正」以外的1隻「巳劍」怪獸加入手牌。\u000a②：我方場上的其他的爬蟲類族怪獸被戰鬥、效果破壞的場合，可以將場上的此卡解放作為代替。'),'從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40551410,'Recette de Personnel ～員工餐的食譜～',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻儀式怪獸為對象可以發動。在我方場上將1隻「新式魔廚衍生物」（惡魔族、闇、等級1、攻/守50）特殊召喚。這個衍生物的等級變成和對象怪獸相同。\u000a②：將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。解放我方的手牌、場上的怪獸，直到等級合計和儀式召喚的怪獸相同為止，從手牌儀式召喚1隻「新式魔廚」儀式怪獸。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40551411,'新式魔廚衍生物','由「Recette de Personnel ～員工餐的食譜～」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40555959,'空手假象','我方場上有「無限地獄」怪獸表側表示存在的場合，1回合1次，可以直到下個我方準備階段時將我方的手牌全部裡側表示除外。','手牌除外','是否現在發動此卡的效果？','發動效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40575313,'地獄亡靈','出現在荒野的亡靈。聚集很多的話會相當麻煩。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40583194,'力量共鳴體','將我方場上表側表示存在的此卡送去墓地，選擇我方場上表側表示存在的1隻怪獸可以發動。這個回合，選擇的怪獸攻擊的場合，對手直到傷害步驟結束時不能發動以怪獸為對象的魔法、陷阱、效果怪獸的效果。','傷害步驟不能發動效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40591390,'D-HERO 恐懼小子',unistr('①：此卡用「幽獄的時鐘塔」的效果特殊召喚的場合發動。以下適用。\u000a●除了「D-HERO」怪獸以外，我方場上的怪獸全部破壞。\u000a●可以從我方墓地將最多2隻「D-HERO」怪獸特殊召喚。\u000a②：此卡特殊召喚時適用。這個回合中，我方場上的「D-HERO」怪獸不會被破壞，那些怪獸的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：此卡的攻擊力、守備力變成我方場上的其他的「D-HERO」怪獸的原攻擊力的合計值。'),'破壞','是否從我方墓地特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40597694,'分散結合',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：對手場上有怪獸存在的場合可以發動。岩石族以外的「寶石騎士」融合怪獸卡決定的融合素材怪獸從我方牌組送去墓地，從額外牌組融合召喚那1隻融合怪獸。此卡從場上離開時那隻怪獸破壞。此效果的發動後，直到回合結束時我方除了「寶石騎士」怪獸以外不能從額外牌組特殊召喚。\u000a\u000a※分散融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40605147,'神的通告',unistr('①：可以支付1500生命值發動以下效果。\u000a●怪獸的效果發動時可以發動。那個發動無效並破壞。\u000a●我方或對手將怪獸特殊召喚之際可以發動。那次特殊召喚無效，那些怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40607210,'吸血鬼格蕾絲',unistr('此卡在墓地存在，不死族怪獸的效果在我方場上將等級5以上的不死族怪獸特殊召喚時，支付2000生命值可以發動。此卡從墓地特殊召喚。「吸血鬼格蕾絲」的這個效果1回合只能使用1次。\u000a此外，1回合1次，宣言卡的種類（怪獸、魔法、陷阱）可以發動。對手從牌組將1張宣言種類的卡片送去墓地。'),'特殊召喚','送入墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40619741,'大日神械士兵','此卡的攻擊宣言時，最多到此卡裝備的裝備卡數量，可以選擇對手場上的怪獸，那些怪獸的表示形式變更。','改變表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40619825,'惡魔之斧',unistr('①：裝備怪獸的攻擊力上升1000。\u000a②：此卡從場上送去墓地時，解放我方場上1隻怪獸可以發動。此卡回到牌組最上方。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40633084,'騎甲蟲步兵分隊',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將衍生物以外的我方場上1隻昆蟲族怪獸解放可以發動。那隻怪獸的原攻擊力每1000最多1隻，在我方場上將「騎甲蟲衍生物」（昆蟲族、地、等級3、攻/守1000）特殊召喚。'),'效果1','請選擇特殊召喚的衍生物數量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40633085,'騎甲蟲衍生物','由「騎甲蟲」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40633297,'藥物的副作用','當回復對手的生命值的效果時，會變成給予對手的生命值傷害的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40634253,'BM-4 炸彈蜘蛛',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，以我方場上1隻機械族、闇屬性怪獸和對手場上1張表側表示的卡為對象可以發動。那些卡破壞。\u000a②：我方場上的原本的種族、屬性是機械族、闇屬性的怪獸用戰鬥或自身的效果破壞對手場上的怪獸送去墓地的場合可以發動。給予對手其中1隻破壞送去墓地的怪獸的原攻擊力一半數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40636712,'魔玩具 鉤烏賊',unistr('「鋒利小鬼」怪獸+「絨毛動物」怪獸\u000a①：1回合1次，以對手場上1隻怪獸為對象可以發動。那隻怪獸送去墓地。此效果發動的整回合中，此卡不能直接攻擊。\u000a②：此卡在1次戰鬥階段中可以攻擊2次。\u000a③：此卡進行戰鬥的戰鬥階段結束時可以發動。此卡變成守備表示。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640057,'栗子球','①：對手怪獸的攻擊讓我方將要受到戰鬥傷害的傷害計算時，將此卡從手牌捨棄可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640058,'栗子球','①：對手怪獸的攻擊讓我方將要受到戰鬥傷害的傷害計算時，將此卡從手牌捨棄可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640059,'栗子球','①：對手怪獸的攻擊讓我方將要受到戰鬥傷害的傷害計算時，將此卡從手牌捨棄可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640060,'栗子球','①：對手怪獸的攻擊讓我方將要受到戰鬥傷害的傷害計算時，將此卡從手牌捨棄可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640061,'栗子球','①：對手怪獸的攻擊讓我方將要受到戰鬥傷害的傷害計算時，將此卡從手牌捨棄可以發動。那次戰鬥產生給我方的戰鬥傷害變成0。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40659562,'守護者 斯芬克斯',unistr('我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a此卡反轉召喚成功時，對手場上的怪獸全部回到持有者的手牌。'),'變成裡側守備表示','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40663548,'芬芳法師-馬鬱蘭',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方的植物族怪獸被戰鬥破壞時可以發動。此卡從手牌特殊召喚。那之後，我方回復500生命值。\u000a②：只要我方的生命值高於對手且此卡在怪獸區域存在，我方的植物族怪獸的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：我方的生命值回復的場合，最多到我方場上的「芬芳」怪獸數量，以對手墓地的卡為對象發動。那些卡除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40666140,'極星靈 光明精靈','此卡召喚成功時，選擇此卡以外的我方場上1隻表側表示怪獸可以發動。選擇的怪獸的等級以下的1隻「極星」怪獸從手牌特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40669071,'餘碼語者',unistr('電子界族怪獸2隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚成功時，依照額外怪獸區域的怪獸數量，指定沒有使用的主要怪獸區域可以發動。指定的區域在這隻怪獸表側表示存在期間不能使用。\u000a②：此卡指向的怪獸的攻擊力上升500，不會被效果破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40672993,'避雷神','①：只要此卡在怪獸區域存在，我方、對手的主要階段1期間，雙方不能發動魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40673853,'超念銃士 瓦隆',unistr('等級5怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，去除此卡的1個超量素材，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。\u000a②：此卡被送去墓地的場合，以場上1張裡側表示卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40678060,'天子的指輪',unistr('只能給已裝備裝備卡的我方場上的怪獸裝備。\u000a①：「天子的指輪」在我方場上只能有1張表側表示存在。\u000a②：對手發動的魔法卡的效果1回合只有1次無效化。\u000a③：1回合1次，此卡裝備中的場合可以發動。我方回復500生命值。那之後，此卡破壞，適用以下效果。\u000a●只要此卡裝備過的怪獸在怪獸區域表側表示存在，對手不能將那隻怪獸作為效果的對象。'),'卡片發動','效果3','「天子的指輪」的效果3適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40680521,'群豪之聚-幻中',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：可以從以下效果選擇1個發動。\u000a●此卡在正前方的我方的主要怪獸區域特殊召喚。\u000a●選我方的主要怪獸區域1隻怪獸，那個位置向與其相鄰的怪獸區域移動。\u000a【怪獸效果】\u000a「群豪」怪獸×3\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：雙方的主要階段，以對手的主要怪獸區域1隻效果怪獸為對象可以發動。那隻對手怪獸在與其相同縱列的對手的魔法與陷阱區域當作永續魔法卡以表側表示放置（將要放置區域的卡破壞，那是怪獸卡的場合，對手失去那個攻擊力數值的生命值）。\u000a②：特殊召喚的此卡被對手的效果破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'●此卡在正前方特殊召喚','●我方怪獸向相鄰區域移動','請選擇移動的怪獸','請選擇要向後移動的怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(40695128,'磨破羅魏',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡召喚、反轉時發動。下個我方抽牌階段的抽牌前，確認我方牌組最上方的卡，回到牌組最上方或最下方。'),'此卡回到手牌','抽牌前確認','回到牌組最上方','回到牌組最下方','','','','','','','','','','','','');
INSERT INTO texts VALUES(40702028,'DPA 鎧裝騎兵',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從我方墓地將1隻電子界族、等級4怪獸效果無效守備表示特殊召喚。這個回合，我方除了電子界族怪獸以外不能特殊召喚。\u000a②：我方的電子界族怪獸和對手怪獸的戰鬥給予對手戰鬥傷害時，將墓地的此卡除外可以發動。給予對手那個數值的傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40703222,'增殖','將我方場上表側表示存在的1隻「栗子球」解放可以發動。在我方場上將「栗子球衍生物」（惡魔族、闇、等級1、攻300/守200）盡可能守備表示特殊召喚。這個衍生物不能為了上級召喚而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40703223,'栗子球衍生物','由「增殖」的效果特殊召喚。這個衍生物不能為了上級召喚而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40703393,'冥界流傀儡術','選擇我方墓地的1隻惡魔族怪獸可以發動。從我方場上將怪獸除外，直到等級合計和對象怪獸的等級相同。那之後，選擇的怪獸從墓地特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40706444,'阿爾戈☆群星-勇駿的阿里翁',unistr('等級4怪獸×2\u000a「阿爾戈☆群星-勇駿的阿里翁」1回合1次也能重疊在我方場上的「阿爾戈☆群星」怪獸上方來超量召喚。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡超量召喚的場合可以發動。從牌組將1張「阿爾戈☆群星」魔法卡加入手牌。\u000a②：我方、對手的準備階段，去除此卡的2個超量素材可以發動。從我方墓地將最多3張「阿爾戈☆群星」永續陷阱卡在我方的魔法與陷阱區域表側表示放置。'),'是否重疊在「阿爾戈☆群星」怪獸上方來超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40725446,'熒焅聖 阿勒克斯',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②③效果1回合各能使用1次。\u000a①：我方的魔法與陷阱區域有表側表示卡存在的場合，此卡可以從手牌特殊召喚。\u000a②：以我方場上1張表側表示的魔法、陷阱卡為對象可以發動。那張卡和此卡破壞。那之後，我方抽1張卡。\u000a③：此卡被破壞的場合，以我方場上1隻超量怪獸為對象可以發動。此卡作為那隻怪獸的超量素材。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40732515,'神聖魔導王 安迪米翁',unistr('①：此卡可以藉由去除我方場上的「魔法都市 安迪米翁」放置的6個魔力計數器，從手牌、墓地特殊召喚。\u000a②：此卡的①方法特殊召喚成功的場合，以我方墓地1張魔法卡為對象發動。那張卡加入手牌。\u000a③：1回合1次，從手牌捨棄1張魔法卡，以場上1張卡為對象可以發動。那張卡破壞。'),'墓地的魔法卡加入手牌','破壞場上的卡','請選擇要去除計數器的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40736921,'心鎮壺的複製品','選擇場上覆蓋的1張魔法、陷阱卡可以發動。只要此卡在場上存在，選擇的卡不能發動。應對此卡的發動，不能發動魔法、陷阱、怪獸的效果。','請選擇覆蓋的1張魔法、陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40737112,'混沌的黑魔術師',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的回合的結束階段，以我方墓地1張魔法卡為對象可以發動。那張卡加入手牌。\u000a②：此卡戰鬥破壞對手怪獸的傷害計算後發動。那隻對手怪獸除外。\u000a③：表側表示的此卡從場上離開的場合被除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40740224,'交叉看守者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌、場上的此卡送去墓地可以發動。從我方的手牌、墓地選1隻「E.HERO」怪獸或「新空間俠」怪獸特殊召喚。此效果從墓地特殊召喚的怪獸的效果無效化。\u000a②：此卡在墓地存在的狀態，我方將「E.HERO」融合怪獸特殊召喚成功的場合，將此卡除外可以發動。我方從牌組抽2張卡，那之後選1張手牌回到牌組最下方。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40771118,'死亡宣告',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方墓地的怪獸以及被除外的我方怪獸之中，以最多到我方場上的「威加盤」以及「死亡訊息」卡片數量的惡魔族怪獸為對象可以發動。那些怪獸加入手牌。\u000a②：將魔法與陷阱區域的此卡送去墓地可以發動。從我方的手牌、牌組、墓地選1張「死亡訊息」卡片當作「威加盤」的效果出到我方的魔法與陷阱區域。'),'效果1','效果2','請選擇進入魔法與陷阱區域的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40785230,'吠陀-優婆尼沙曇',unistr('【靈擺效果】\u000a①：我方或對手的怪獸被破壞的場合發動（同一連鎖上最多1次）。給此卡放置3個計數器。\u000a②：此卡的靈擺刻度上升此卡的計數器數量。\u000a③：去除此卡的12個計數器可以發動。此卡特殊召喚。\u000a【怪獸效果】\u000a此卡不能通常召喚，只能用此卡的靈擺效果特殊召喚。我方1回合只能特殊召喚1次「吠陀-優婆尼沙曇」。\u000a①：1回合1次，對手從額外牌組將怪獸特殊召喚的場合，從我方的手牌、場上、墓地將12張卡裡側除外可以發動。變成這個回合的結束階段。\u000a②：我方準備階段發動。此卡回到手牌。那之後，可以將我方的手牌、牌組、墓地、除外狀態的1隻「吠陀」怪獸特殊召喚。'),'靈擺效果3','效果1','效果2','是否特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(40817915,'雷電栗子',unistr('此卡不能作為同步素材。\u000a我方主要階段，選擇1隻持有超量素材的超量怪獸可以發動。去除那隻怪獸的1個超量素材，從我方牌組將1隻「雷電栗子」特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40826495,'岩漿人','岩漿中生出的怪獸。用可怕的熱能溶化事物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40830387,'古代機械齒輪掌',unistr('只能給「古代機械齒輪」怪獸裝備。\u000a裝備怪獸和怪獸進行戰鬥的傷害步驟結束時，那隻怪獸破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40838625,'沙塵防護罩 －塵埃之力－','①：對手怪獸的攻擊宣言時可以發動。對手場上的攻擊表示怪獸全部變成裡側守備表示。這個效果變成裡側守備表示的怪獸不能變更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40844552,'極星天 女武神','①：此卡召喚成功時，對手場上有怪獸存在，我方場上沒有此卡以外的卡存在的場合，從手牌將2隻「極星」怪獸除外可以發動。在我方場上將2隻「英靈衍生物」（戰士族、地、等級4、攻/守1000）守備表示特殊召喚。','特殊召喚衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40844553,'英靈衍生物','由「極星天 女武神」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40847034,'殺手旋律 歌單',unistr('這個卡名的卡在1回合可以發動最多2張。\u000a①：以我方的場上、墓地1隻「殺手旋律」怪獸為對象可以發動。以下效果各自適用。此卡的發動後，直到回合結束時我方除了協調以外不能特殊召喚。\u000a●對象怪獸的自身作為同步素材送去墓地的場合發動的效果適用。\u000a●對象怪獸回到手牌。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40854197,'E.HERO 絕對零度',unistr('「HERO」怪獸+水屬性怪獸\u000a此卡只能用融合召喚來特殊召喚。\u000a此卡的攻擊力上升場上表側表示存在的「E.HERO 絕對零度」以外的水屬性怪獸數量×500。\u000a此卡從場上離開時，對手場上的怪獸全部破壞。'),'破壞場上的怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40854824,'飛越彩虹','①：原卡名是「究極寶玉神 彩虹龍」或「究極寶玉神 彩虹黑暗龍」的怪獸在我方場上發動效果的回合可以發動。從牌組將任意數量的「寶玉獸」怪獸特殊召喚（同名卡最多1張）。','是否繼續特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40867519,'靜寂蟲',unistr('此卡召喚、反轉召喚成功的場合，變成守備表示。\u000a只要此卡在場上表側表示存在，永續魔法、永續陷阱卡的效果無效。'),'變成守備表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40884383,'兇惡犯-開膛手','此卡反轉召喚成功時，可以從我方墓地中選擇1張裝備魔法卡給此卡裝備。','裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40894584,'千兆位元吉哥',unistr('①：「千兆位元吉哥」在我方場上只能有1張表側表示存在。\u000a②：我方場上有魔法使族怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a③：此卡被戰鬥、效果破壞送去墓地時可以發動。從牌組將「千兆位元吉哥」以外的1隻攻擊力1500/守備力200的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40907115,'靈獸使 雯',unistr('我方1回合只能特殊召喚1次「靈獸使 雯」。\u000a①：此卡召喚時，以我方的除外狀態的1隻「靈獸」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40908371,'蒼眼銀龍',unistr('協調+協調以外的通常怪獸1隻以上\u000a①：此卡特殊召喚的場合發動。我方場上的全部龍族怪獸直到下個回合結束時不會被效果破壞，雙方直到下個回合結束時不能將那些作為效果的對象。\u000a②：我方準備階段，以我方墓地1隻通常怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40916023,'水之精靈 阿庫艾莉亞',unistr('此卡不能通常召喚。從我方墓地將1隻水屬性怪獸除外可以特殊召喚。\u000a①：對手準備階段，以對手場上1隻表側表示怪獸為對象可以發動。那隻對手的表側表示怪獸的表示形式變更。這個回合，那隻怪獸不能變更表示形式。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40921545,'入魔鯨','解放此卡可以發動。選擇對手場上的1張魔法、陷阱卡破壞。','魔陷破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40921744,'墮天使 傑拉特',unistr('我方墓地有4種以上闇屬性怪獸存在的場合，此卡可以解放1隻闇屬性怪獸來上級召喚。\u000a①：從手牌將1隻闇屬性怪獸送去墓地可以發動。對手場上的怪獸全部破壞。\u000a②：此卡的①效果發動的回合的結束階段發動。此卡破壞。'),'解放1隻闇屬性怪獸上級召喚','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40933924,'黑蠍盜掘團','此卡給予對手戰鬥傷害時，對手從牌組中將1張魔法卡送去墓地。','選擇1張魔法卡送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40937767,'墓穴食人魔',unistr('只要我方場上有裡側守備表示怪獸存在，此卡不能被選擇為攻擊對象。\u000a我方場上的怪獸反轉召喚時，給予對手300傷害。'),'LP傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40939228,'流天救世星龍',unistr('「救世龍」+包含龍族同步怪獸的協調以外的怪獸1隻以上\u000a此卡只能用同步召喚從額外牌組特殊召喚。\u000a①：1回合1次，可以發動。選對手場上1隻效果怪獸，那個效果無效。\u000a②：除了通常攻擊以外，此卡可以攻擊的次數為我方墓地的「星塵龍」以及記載那個卡名的同步怪獸數量。\u000a③：1回合1次，對手發動效果時可以發動。此卡直到結束階段除外，那個發動無效並除外。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40941889,'ZW-阿修羅副腕',unistr('①：「ZW-阿修羅副腕」在我方場上只能有1張表側表示存在。\u000a②：以我方場上1隻「希望皇霍普」怪獸為對象可以發動。從我方的手牌、場上將此卡當作攻擊力上升1000的裝備卡給那隻我方的「希望皇霍普」怪獸裝備。\u000a③：此卡裝備中的場合，裝備怪獸可以向對手場上的全部怪獸各攻擊1次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40945356,'黃昏的中忍-日輪',unistr('此卡在規則上也當作「忍者」卡片。\u000a①：1回合1次，可以從手牌捨棄1隻「忍者」怪獸，從以下效果選擇1個發動。此效果在對手回合也能發動。\u000a●這個回合，我方場上的「忍者」怪獸以及「忍法」卡片不會被戰鬥、效果破壞。\u000a●選我方場上1隻「忍者」怪獸，其攻擊力直到回合結束時上升1000。'),'●「忍者」怪獸和「忍法」卡片不會被破壞','●攻擊力上升1000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40971261,'亡龍的旋律',unistr('宣言1個卡名可以發動此卡。\u000a①：只要此卡在魔法與陷阱區域存在，每次宣言的卡的效果發動，發動那個效果的卡的原持有者的生命值變成一半。此效果適用的回合的結束階段，此卡送去墓地。\u000a②：對手場上有怪獸存在的場合，此卡不會被效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40975243,'鐵獸的抗戰',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的墓地、除外狀態的任意數量的獸族、獸戰士族、鳥獸族怪獸效果無效特殊召喚，只用那些怪獸為素材進行1隻「鐵獸」連結怪獸的連結召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40975574,'紅蓮共鳴體',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚時可以發動。從手牌將1隻等級4以下的怪獸特殊召喚。\u000a②：此卡特殊召喚時，以場上1隻表側表示怪獸為對象可以發動。我方的生命值回復那隻怪獸的攻擊力數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40991587,'白骨夫人',unistr('只要此卡在墓地存在，卡名當作「白骨」。\u000a只要此卡在場上表側表示存在，「白骨夫人」以外的場上的等級3以下的不死族怪獸不會被戰鬥破壞，不會受到魔法、陷阱卡的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40998517,'劍界王戰 弗羅德王',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：「劍界王戰 弗羅德王」在我方場上只能有1隻表側表示存在。\u000a②：解放我方場上任意數量的「王戰」怪獸或戰士族怪獸，以那個數量的場上的怪獸為對象可以發動。那些怪獸破壞。那之後，對手可以依照被破壞的對手場上的怪獸數量從牌組抽牌。此效果在對手回合也能發動。'),'效果2','是否依照自身被破壞的怪獸數量抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41002238,'皇帝滑翔龍-黃金爆裂',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：將我方場上1隻怪獸解放可以發動。此卡從手牌特殊召喚。此效果在對手回合也能發動。\u000a②：此卡召喚、特殊召喚成功的場合，以對手場上1隻表側表示怪獸為對象可以發動。此卡的攻擊力直到回合結束時變成和那隻怪獸的攻擊力相同。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41006930,'速攻的黑色忍者',unistr('這個卡名的效果1回合只能使用1次。\u000a①：從我方墓地將2隻闇屬性怪獸除外可以發動。表側表示的此卡直到結束階段除外。此效果在對手回合也能發動。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41039846,'烏鴉巨群',unistr('此卡不能從牌組特殊召喚。\u000a此卡1回合只有1次可以變成裡側守備表示。\u000a此卡反轉召喚成功時，對手的手牌隨機選1張捨棄。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41044418,'仟年的啟示',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1隻幻神獸族怪獸送去墓地可以發動。從我方的牌組、墓地選1張「死者蘇生」加入手牌。\u000a②：將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。這個回合，可以用我方的「死者蘇生」將我方墓地的「拉的翼神龍」無視召喚條件特殊召喚。此效果發動的回合的結束階段，我方必須將「死者蘇生」的效果特殊召喚的「拉的翼神龍」送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41061625,'椰子樹','有意志的椰子樹。以落下的果實進行攻擊。果實中的椰子汁味道鮮美。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41069676,'殺手旋律 響度戰爭',unistr('協調+協調1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方場上的其他協調不會被效果破壞，對手不能將其作為效果的對象。\u000a②：對手發動效果時，從我方墓地將1隻「殺手旋律」怪獸除外可以發動。除外的怪獸的自身作為同步素材送去墓地的場合發動的效果適用。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41077745,'E.HERO 冰刀',unistr('1回合1次，我方的主要階段1，捨棄1張手牌可以發動。這個回合此卡可以直接攻擊對手玩家。\u000a此外，此卡直接攻擊給予對手戰鬥傷害時，可以選擇對手的魔法與陷阱區域覆蓋的1張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41085464,'書靈師再起',unistr('「書靈師」儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻「書靈師」儀式怪獸。此效果使用場上的「書靈師 熾火點燃俠」儀式召喚的「書靈師 熾火爆裂俠」不會被效果破壞，不能被效果除外。'),'「書靈師再起」的效果適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41089128,'火炎的支配者','炎屬性怪獸上級召喚的場合，此卡可以當作2隻解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41090784,'冰結界的大僧正',unistr('①：此卡召喚、反轉召喚的場合發動。此卡變成守備表示。\u000a②：只要此卡在怪獸區域存在，我方場上的「冰結界」怪獸不會被魔法、陷阱卡的效果破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41091257,'SPYRAL-花花公子',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，宣言卡的種類（怪獸、魔法、陷阱）可以發動。對手牌組最上方的卡給雙方確認，如果是宣言的種類的卡，此卡從手牌特殊召喚。\u000a②：此卡用「SPYRAL」卡片的效果特殊召喚成功的場合，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41097056,'同步破解','①：以我方場上1隻同步怪獸為對象可以發動。那隻怪獸回到持有者的額外牌組，持有那隻同步怪獸的原攻擊力以下的攻擊力的對手場上的表側表示怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41098335,'戰士猿',unistr('此卡戰鬥破壞對手怪獸的場合，此卡的攻擊力上升300。\u000a此卡在我方回合沒有攻擊的場合，這個效果上升的數值在回合結束時回到0。'),'攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41113025,'圓盤騎士','1回合1次，選擇我方墓地的1張通常陷阱卡可以發動。那張卡除外，此卡的攻擊力直到對手回合結束時上升500。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41114306,'方界獸 黑暗葛內克斯',unistr('此卡不能通常召喚。將我方場上1隻「方界」怪獸送去墓地可以特殊召喚。\u000a①：這個方法特殊召喚的此卡的攻擊力上升1000。\u000a②：此卡戰鬥破壞怪獸時，以我方墓地最多2隻「方界胤 毗濕奴」為對象可以發動。此卡送去墓地，對象怪獸特殊召喚。那之後，可以從牌組將1隻「方界獸 利刃迦樓迪亞」加入手牌。'),'是否把1隻「方界獸 利刃迦樓迪亞」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41128647,'機動陣 強化',unistr('①：場上的「機動霧龍」怪獸的攻擊力、守備力上升300。\u000a②：我方的「機動霧龍」怪獸進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法、陷阱、怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41139112,'召喚骰子',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：支付1000生命值可以發動。擲1次骰子，適用擲出點數的效果。\u000a●1、2：可以將1隻怪獸召喚。\u000a●3、4：可以從我方墓地選1隻怪獸特殊召喚。\u000a●5、6：可以從手牌將1隻等級5以上的怪獸特殊召喚。'),'是否召喚？','是否從墓地特殊召喚？','是否從手牌特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41141943,'超重武者 飛腳-Q',unistr('「超重武者 飛腳-Q」的②效果1回合只能使用1次。\u000a①：我方墓地沒有魔法、陷阱卡存在的場合，此卡可以從手牌特殊召喚。這個方法特殊召喚成功的回合，我方除了「超重武者」怪獸以外不能特殊召喚。\u000a②：我方墓地沒有魔法、陷阱卡存在的場合，將此卡解放可以發動。從手牌將最多2隻怪獸在對手場上守備表示特殊召喚。那之後，我方從牌組抽此效果特殊召喚的怪獸數量的卡。'),'從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41142615,'陽氣葬儀屋','從我方的手牌捨棄最多3隻怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41147577,'混沌超量 風紀大宮司 祭文',unistr('等級7怪獸×3\u000a此卡不受此卡以外的怪獸的效果影響。\u000a此卡有「風紀宮司 祝詞」作為超量素材的場合，得到以下效果。\u000a●1回合1次，去除此卡的1個超量素材，選擇對手場上1隻怪獸可以發動。選擇的怪獸的表示形式變更，那隻怪獸的效果直到回合結束時無效。此效果在對手回合也能發動。'),'●效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41158734,'阿波卡提奎爾',unistr('我方場上有協調存在的場合，場上的此卡的等級當作5。\u000a場上的此卡被破壞送去墓地時，可以選擇我方墓地的1隻「太陽的神官」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41160533,'薔薇藤蔓',unistr('此卡不能特殊召喚。\u000a我方戰鬥階段開始時對手場上有表側表示的植物族怪獸存在的場合，這個回合除了通常攻擊以外，此卡可以攻擊的次數為那些植物族怪獸數量。\u000a此卡戰鬥破壞植物族怪獸的場合，給予對手300傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41160595,'召集魔法','對手的魔法、陷阱卡的效果將覆蓋的此卡破壞送去墓地時，從牌組選1張速攻魔法卡給雙方確認，在我方場上覆蓋。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41165831,'破械神 薩巴拉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，我方、對手的主要階段，以我方場上1隻惡魔族怪獸或1張裡側表示卡為對象可以發動。那張卡破壞，此卡特殊召喚。只要此效果特殊召喚的此卡在怪獸區域表側表示存在，我方除了惡魔族怪獸以外不能特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1張「破械」魔法、陷阱卡在我方場上覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41172955,'綠色小工具','①：此卡召喚、特殊召喚成功時可以發動。從牌組將1隻「紅色小工具」加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41175645,'沉默魔術師',unistr('此卡不能通常召喚。只能解放我方場上1隻魔法使族怪獸來特殊召喚。\u000a①：此卡的攻擊力上升我方的手牌數量×500。\u000a②：1回合1次，魔法卡發動時可以發動。那個發動無效。\u000a③：場上的此卡被戰鬥或對手的效果破壞的場合可以發動。從手牌、牌組將「沉默魔術師」以外的1隻「沉默魔術師」怪獸無視召喚條件特殊召喚。'),'發動無效','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41181774,'地縛神 Wiraqocha Rasca',unistr('①：「地縛神」怪獸在場上只能有1隻表側表示存在。\u000a②：此卡召喚成功的場合，最多到對手的手牌數量，以此卡以外的我方場上的卡為對象發動（最多3張）。那些卡回到持有者的牌組。那之後，對手的手牌隨機挑選回去的數量捨棄，此卡的攻擊力上升捨棄的數量×1000。\u000a③：此卡可以直接攻擊。\u000a④：對手不能選擇此卡作為攻擊對象。\u000a⑤：沒有場地魔法卡表側表示存在的場合，此卡破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41182875,'標槍甲蟲的契約','「標槍甲蟲」的降臨所必需。必須從我方的手牌、場上解放怪獸直到等級合計為8以上為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41197012,'緋暗紅地毯','①：場上有龍族同步怪獸存在的場合，以我方墓地最多2隻「共鳴體」怪獸為對象可以發動。那些怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41201386,'升階魔法-急襲之力',unistr('①：以我方場上1隻超量怪獸為對象可以發動。將1隻階級比那隻怪獸高1階的「RR-」怪獸重疊在作為對象的我方怪獸上方，當作超量召喚從額外牌組特殊召喚。\u000a②：將墓地的此卡和手牌的1張「RR-」卡片除外，以「升階魔法-急襲之力」以外的我方墓地1張「升階魔法」魔法卡為對象可以發動。那張卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41201555,'核成孕婦薔薇',unistr('此卡的控制者在每次我方結束階段，從手牌將1張「核成的鋼核」送去墓地，或向對手展示手牌的1隻植物族怪獸，或都不做讓此卡破壞。\u000a我方的準備階段時1次，可以從我方牌組將1隻等級3以下的怪獸送去墓地。'),'「核成的鋼核」送去墓地','展示植物族怪獸','破壞','從牌組送去墓地','','','','','','','','','','','','');
INSERT INTO texts VALUES(41209827,'飢餓毒液結合龍',unistr('衍生物以外的場上的闇屬性怪獸×2\u000a①：此卡融合召喚的場合可以發動。此卡的攻擊力直到回合結束時上升對手場上1隻特殊召喚的怪獸的攻擊力數值。\u000a②：1回合1次，以對手場上1隻等級5以上的怪獸為對象可以發動。此卡直到結束階段得到和那隻怪獸的原本的卡名、效果相同的卡名、效果。\u000a③：融合召喚的此卡被破壞的場合可以發動。對手場上的特殊召喚的怪獸全部破壞。'),'效果1','效果2','效果3','解除複製效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(41209828,'飢餓毒液結合龍',unistr('衍生物以外的場上的闇屬性怪獸×2\u000a①：此卡融合召喚的場合可以發動。此卡的攻擊力直到回合結束時上升對手場上1隻特殊召喚的怪獸的攻擊力數值。\u000a②：1回合1次，以對手場上1隻等級5以上的怪獸為對象可以發動。此卡直到結束階段得到和那隻怪獸的原本的卡名、效果相同的卡名、效果。\u000a③：融合召喚的此卡被破壞的場合可以發動。對手場上的特殊召喚的怪獸全部破壞。'),'效果1','效果2','效果3','解除複製效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(41215808,'隨風飄飄遊與夢之鄉',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方、對手的主要階段可以發動。將1隻等級4以下的鳥獸族怪獸召喚。\u000a②：此卡在墓地存在的狀態，我方將等級7以上的怪獸的上級召喚成功的場合，將此卡除外可以發動。對手場上的怪獸全部變成裡側守備表示。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41218256,'利爪殺手','手腕可以伸縮自如，可以用銳利的爪子刺穿對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41224658,'野心的哥法','1回合1次，選擇對手場上最多2隻怪獸可以發動。對手可以展示手牌的1隻怪獸讓此效果無效。不展示的場合，選擇的怪獸破壞。','破壞','是否展示手牌的1隻怪獸讓「野心的哥法」的效果無效？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41230939,'電子暗黑角',unistr('①：此卡召喚成功的場合，以我方墓地1隻等級3以下的龍族怪獸為對象發動。那隻龍族怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力數值。\u000a③：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a④：此卡被戰鬥破壞的場合，將此卡的效果裝備的怪獸破壞作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41232647,'龍女僕 龍女管家',unistr('「龍女僕」怪獸+龍族怪獸\u000a①：我方、對手的準備階段，以我方場上1隻其他的「龍女僕」怪獸為對象可以發動。從我方的手牌、墓地將1隻等級比那隻怪獸高1級或低1級的「龍女僕」怪獸守備表示特殊召喚。\u000a②：此卡在怪獸區域存在的狀態，我方場上的表側表示的龍族怪獸回到我方的手牌時，以對手場上1隻怪獸為對象可以發動。那隻怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41232648,'龍女僕 龍女管家',unistr('「龍女僕」怪獸+龍族怪獸\u000a①：我方、對手的準備階段，以我方場上1隻其他的「龍女僕」怪獸為對象可以發動。從我方的手牌、墓地將1隻等級比那隻怪獸高1級或低1級的「龍女僕」怪獸守備表示特殊召喚。\u000a②：此卡在怪獸區域存在的狀態，我方場上的表側表示的龍族怪獸回到我方的手牌時，以對手場上1隻怪獸為對象可以發動。那隻怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41234315,'偽爆破五星','對手怪獸的攻擊宣言時可以發動。怪獸不會被那次戰鬥破壞，在傷害計算後從我方的手牌、墓地將1隻「召喚反應機 AI」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41248270,'流量幽靈','怪獸3隻','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41249545,'魅影草','此卡的攻擊力上升我方墓地的「魅影草」的數量×500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41255165,'企鵝忍者',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡反轉的場合，以對手場上最多2張魔法、陷阱卡為對象可以發動。那些卡回到持有者的手牌。\u000a②：以我方場上1隻「企鵝」怪獸為對象可以發動。那隻怪獸變成裡側守備表示。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41269771,'摩羯星聖 牛宿二','①：此卡召喚成功時可以發動。從手牌將1隻等級4的「星聖」怪獸特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41302052,'花樣明星 顛茄歌后',unistr('「花樣明星」怪獸2隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：連結召喚的此卡指向的區域沒有怪獸存在的場合，此卡不受其他卡發動的效果影響。\u000a②：此卡指向的區域沒有怪獸存在的場合可以發動。給予對手我方墓地的「花樣明星」怪獸種類×200傷害。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41306080,'冰冰妖@伊格尼斯者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「@伊格尼斯者」怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：解放此卡以外的我方場上1隻電子界族怪獸可以發動。從牌組將1隻等級5以上的「@伊格尼斯者」怪獸加入手牌，此卡的等級直到回合結束時變成4。為此效果發動而將連結怪獸解放的場合，隨後可以從牌組將1張「A.i.的儀式」加入手牌。'),'','','是否從牌組把1張「A.i.的儀式」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41307269,'超重武者 兜-10','①：對手將怪獸特殊召喚成功的場合可以發動。我方場上的攻擊表示的「超重武者」怪獸全部變成守備表示，那個守備力直到回合結束時上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41309158,'混沌超量 機裝魔人 安杰涅拉爾',unistr('等級4怪獸×3\u000a此卡超量召喚成功時，可以選擇場上1隻守備表示怪獸變成表側攻擊表示。\u000a此卡有「機裝天使 安杰涅爾」作為超量素材的場合，得到以下效果。\u000a●此卡給予對手戰鬥傷害時，去除此卡的1個超量素材可以發動。給予對手1000傷害。'),'變成表側攻擊表示','●給予對手1000傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41329458,'幻獸機 加里寧獅鷲',unistr('我方的主要階段時，將我方場上2隻「幻獸機」怪獸解放可以發動。此卡從手牌特殊召喚。「幻獸機 加里寧獅鷲」的這個效果1回合只能使用1次。\u000a只要我方場上有衍生物存在，此卡不會被戰鬥、效果破壞。\u000a1回合1次，捨棄手牌的1隻「幻獸機」怪獸可以發動。將1隻「幻獸機衍生物」（機械族、風、等級3、攻/守0）特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41329459,'幻獸機衍生物','由「幻獸機」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41348446,'爆破代碼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「拓撲邏輯」連結怪獸存在的場合，以我方墓地的1隻連結怪獸以外的龍族、機械族、電子界族的闇屬性怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：此卡從魔法與陷阱區域除外的場合，下個回合的準備階段可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41350417,'黑之魔導的布幕',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：雙方可以各自從自身的手牌、牌組將1隻魔法使族、闇屬性怪獸特殊召喚。此效果讓我方特殊召喚的怪獸的原卡名是「黑魔導」或「黑魔導女孩」的場合，隨後可以從牌組將「黑之魔導的布幕」以外的1張記載「黑魔導」的卡名的魔法、陷阱卡加入手牌。這個回合，此效果特殊召喚的怪獸不能發動效果。'),'效果1','是否從自身的手牌、牌組特殊召喚？','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41350418,'黑之魔導的布幕',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：雙方可以各自從自身的手牌、牌組將1隻魔法使族、闇屬性怪獸特殊召喚。此效果讓我方特殊召喚的怪獸的原卡名是「黑魔導」或「黑魔導女孩」的場合，隨後可以從牌組將「黑之魔導的布幕」以外的1張記載「黑魔導」的卡名的魔法、陷阱卡加入手牌。這個回合，此效果特殊召喚的怪獸不能發動效果。'),'效果1','是否從自身的手牌、牌組特殊召喚？','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41356845,'硫酸的落穴','①：以場上1隻裡側守備表示怪獸為對象可以發動。那隻怪獸變成表側守備表示，若守備力是2000以下則破壞，若守備力超過2000則回到裡側守備表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41356846,'硫酸的落穴','①：以場上1隻裡側守備表示怪獸為對象可以發動。那隻怪獸變成表側守備表示，若守備力是2000以下則破壞，若守備力超過2000則回到裡側守備表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41359411,'聖劍 克拉倫特',unistr('只能給戰士族怪獸裝備。這個卡名的③效果1回合只能使用1次。\u000a①：「聖劍 克拉倫特」在我方場上只能有1張表側表示存在。\u000a②：1回合1次，支付500生命值可以發動。這個回合，裝備怪獸可以直接攻擊。\u000a③：場上的表側表示的此卡被破壞送去墓地的場合，以我方場上1隻戰士族的「聖騎士」怪獸為對象可以發動。此卡給那隻我方的戰士族的「聖騎士」怪獸裝備。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41367003,'抽牌肌肉',unistr('「抽牌肌肉」在1回合只能發動1張。\u000a①：以我方場上1隻守備力1000以下的表側守備表示怪獸為對象可以發動。我方從牌組抽1張卡。那隻怪獸在這個回合不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41371602,'起立吧百夫長！',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有「百夫長」怪獸卡存在，此卡不會被對手的效果破壞。\u000a②：此卡發動的回合的我方主要階段，將1張手牌送去墓地可以發動。從牌組將1隻「百夫長」怪獸當作永續陷阱卡在我方的魔法與陷阱區域表側表示放置。\u000a③：怪獸特殊召喚的場合可以發動。用包含「百夫長」怪獸的我方場上的怪獸為素材進行同步召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41371603,'起立吧百夫長！',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有「百夫長」怪獸卡存在，此卡不會被對手的效果破壞。\u000a②：此卡發動的回合的我方主要階段，將1張手牌送去墓地可以發動。從牌組將1隻「百夫長」怪獸當作永續陷阱卡在我方的魔法與陷阱區域表側表示放置。\u000a③：怪獸特殊召喚的場合可以發動。用包含「百夫長」怪獸的我方場上的怪獸為素材進行同步召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41373230,'灰燼龍 劣種',unistr('「阿不思的落胤」+攻擊力2500以上的怪獸\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡的攻擊力上升作為此卡的融合素材的怪獸的原等級的總和×100。\u000a②：此卡融合召喚時適用。這個回合，此卡不受從額外牌組特殊召喚的其他怪獸發動的效果影響。\u000a③：此卡被送去墓地的回合的結束階段可以發動。從牌組選1隻「教導」怪獸或「阿不思的落胤」加入手牌或特殊召喚。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41375811,'十二獸 狗環',unistr('等級4怪獸×2隻以上\u000a「十二獸 狗環」1回合1次也能重疊在同名卡以外的我方場上的「十二獸」怪獸上方來超量召喚。\u000a①：此卡的攻擊力、守備力上升此卡持有的超量素材的「十二獸」怪獸的對應數值。\u000a②：1回合1次，去除此卡的1個超量素材，以我方墓地1隻「十二獸」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合效果無效化，不能作為超量召喚的素材。'),'是否重疊在「十二獸」怪獸上面來超量召喚？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41382147,'星見鳥 拉利斯',unistr('此卡進行戰鬥的場合，傷害步驟期間此卡的攻擊力上升進行戰鬥的對手怪獸的等級×200。\u000a此卡攻擊的傷害步驟結束時，此卡除外，在下個我方回合的戰鬥階段開始時以表側攻擊表示回到我方場上。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41386308,'數學家',unistr('①：此卡召喚時可以發動。從牌組將1隻等級4以下的怪獸送去墓地。\u000a②：此卡被戰鬥破壞送去墓地時可以發動。我方抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41392891,'戈蘭林','喜歡惡作劇的小魔鬼，從黑暗中襲來。要小心！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41396436,'蒼翼羽冠','青白色的火鳥，頭上的毛有如皇冠。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41398771,'老化的詛咒','捨棄1張手牌可以發動。對手場上的全部怪獸的攻擊力、守備力直到回合結束時下降500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41403766,'冰原的大蠍','不是在沙漠而是分佈在冰土帶上的罕見的深藍色的蠍子。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41406613,'暗黑界的魔神王 瑞恩',unistr('①：此卡可以讓我方場上1隻等級7以下的「暗黑界」怪獸回到持有者的手牌，從墓地特殊召喚。\u000a②：此卡被效果從手牌捨棄到墓地的場合可以發動。從牌組將「暗黑界的魔神王 瑞恩」以外的1隻等級5以上的「暗黑界」怪獸加入手牌。被對手的效果捨棄的場合，隨後可以從我方的牌組、墓地選1隻等級4以下的「暗黑界」怪獸在我方或對手場上特殊召喚。'),'效果1','效果2','是否再選1隻怪獸特殊召喚？','在我方場上特殊召喚','在對手場上特殊召喚','','','','','','','','','','','');
INSERT INTO texts VALUES(41410651,'斬機刀 那由他',unistr('只能給電子界族怪獸裝備。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：裝備怪獸和對手怪獸進行戰鬥的傷害計算時，從牌組將1隻「斬機」怪獸送去墓地可以發動。裝備怪獸的攻擊力直到回合結束時上升送去墓地的怪獸的攻擊力數值。\u000a②：此卡從魔法與陷阱區域送去墓地的場合，以「斬機刀 那由他」以外的我方墓地1張「斬機」卡片為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41418852,'源數網路',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方主要階段，將滿足發動條件的1張「源數」通常魔法卡從牌組送去墓地可以發動。此效果變成和那張魔法卡發動時的效果相同。\u000a②：只要此卡在場地區域存在，我方場上的「源數」超量怪獸去除超量素材來發動效果的場合，也能不去除超量素材來發動。'),'效果1','不去除超量素材（源數網路）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41420027,'神的宣告',unistr('①：可以支付一半生命值發動以下效果。\u000a●魔法、陷阱卡發動時可以發動。那個發動無效並破壞。\u000a●我方或對手將怪獸召喚、反轉召喚、特殊召喚之際可以發動。使其無效，那些怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41420028,'神的宣告',unistr('①：可以支付一半生命值發動以下效果。\u000a●魔法、陷阱卡發動時可以發動。那個發動無效並破壞。\u000a●我方或對手將怪獸召喚、反轉召喚、特殊召喚之際可以發動。使其無效，那些怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41422426,'暗處的協力者','從暗處悄悄幫助別人的可愛小人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41424250,'混沌終結支配者 －開闢與終焉的支配者－',unistr('此卡不能通常召喚。只能從我方墓地將戰士族、光屬性和惡魔族、闇屬性怪獸各1隻除外來特殊召喚。這個卡名的③效果1回合只能使用1次。\u000a①：此卡的特殊召喚不會被無效化。\u000a②：在此卡特殊召喚成功時，雙方不能發動卡的效果。\u000a③：此卡已用上述方法特殊召喚的場合，支付1000生命值可以發動。對手的場上、墓地的卡全部除外。那之後，給予對手此效果除外的數量×500傷害。'),'','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41426869,'幻像的儀式',unistr('「納祭」的降臨所必需。\u000a①：從我方的手牌、場上解放怪獸直到等級合計為1以上為止，從手牌儀式召喚「納祭」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41431329,'大日神械立方體','此卡被光屬性怪獸的同步召喚使用送去墓地的場合，可以從牌組將1張裝備魔法卡加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41436536,'E.HERO 鳳凰小子',unistr('「E.HERO 羽毛人」+「E.HERO 爆炎女郎」\u000a此卡只能用融合召喚來特殊召喚。\u000a此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41440148,'娛樂夥伴 探索河馬','①：此卡召喚成功的回合，我方在通常召喚之外只有1次，在我方主要階段可以表側攻擊表示上級召喚1隻等級7以上的怪獸。','上級召喚（娛樂夥伴 探索河馬）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41440817,'心太砲式','①：我方或對手的怪獸的攻擊宣言時，以場上1隻怪獸為對象可以發動。那隻怪獸回到持有者的牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41442341,'操縱死靈的人偶大師','①：此卡上級召喚成功時，支付2000生命值，以我方墓地2隻惡魔族怪獸為對象可以發動。那些惡魔族怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41443249,'R-ACE 預防者',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：從我方墓地將1張「R-ACE」卡片除外可以發動。此卡從手牌特殊召喚。\u000a②：我方、對手回合，我方場上有其他的「R-ACE」怪獸存在的場合，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸變成裡側守備表示。\u000a③：此卡被送去墓地的場合，以等級8怪獸以外的我方的除外狀態的1隻「R-ACE」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41456841,'究極變異態 昆蟲女王',unistr('此卡不能通常召喚，只能用卡的效果特殊召喚。\u000a①：場上有其他的昆蟲族怪獸存在的場合，我方場上的昆蟲族怪獸不會成為對手的效果的對象，不會被對手的效果破壞。\u000a②：此卡攻擊的傷害步驟結束時，將我方場上1隻怪獸解放可以發動。此卡可以向對手怪獸繼續攻擊。\u000a③：我方、對手的結束階段可以發動。在我方場上將1隻「昆蟲怪獸衍生物」（昆蟲族、地、等級1、攻/守100）特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41456842,'昆蟲怪獸衍生物','由「究極變異態 昆蟲女王」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41458579,'六尺瓊勾玉','①：我方場上有「六武眾」怪獸存在，對手發動要讓卡片破壞的怪獸的效果、魔法、陷阱卡時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41462083,'千歲龍',unistr('「時間魔術師」+「寶貝龍」\u000a\u000a※千年龍'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41462084,'千歲龍',unistr('「時間魔術師」+「寶貝龍」\u000a\u000a※千年龍'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41463181,'轉生炎獸 熾熱多頭獅',unistr('炎屬性效果怪獸2隻以上\u000a①：此卡連結召喚的場合，以對手的魔法與陷阱區域1張卡為對象可以發動。那張卡回到牌組。\u000a②：如果此卡已用「轉生炎獸 熾熱多頭獅」為素材連結召喚，1回合1次，以場上1隻表側表示怪獸和我方墓地1隻怪獸為對象可以發動。作為對象的場上的怪獸的攻擊力直到回合結束時變成和作為對象的墓地的怪獸的攻擊力相同。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41463182,'轉生炎獸 熾熱多頭獅',unistr('炎屬性效果怪獸2隻以上\u000a①：此卡連結召喚的場合，以對手的魔法與陷阱區域1張卡為對象可以發動。那張卡回到牌組。\u000a②：如果此卡已用「轉生炎獸 熾熱多頭獅」為素材連結召喚，1回合1次，以場上1隻表側表示怪獸和我方墓地1隻怪獸為對象可以發動。作為對象的場上的怪獸的攻擊力直到回合結束時變成和作為對象的墓地的怪獸的攻擊力相同。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41470137,'劍鬥獸 飛槍鬥士',unistr('①：此卡用「劍鬥獸」怪獸的效果特殊召喚成功的場合，以場上1張魔法、陷阱卡為對象發動。那張卡破壞。\u000a②：此卡進行戰鬥的戰鬥階段結束時，讓此卡回到持有者的牌組可以發動。從牌組將「劍鬥獸 飛槍鬥士」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'破壞','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41475424,'機限爆彈','選擇我方場上的1隻「機皇」怪獸和對手場上的1張卡可以發動。那些卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41482598,'惡夢的蜃氣樓',unistr('對手準備階段時，我方從牌組抽牌直到手牌變成4張為止。\u000a此效果抽牌的場合，我方準備階段時，我方的手牌隨機選抽牌的張數捨棄。'),'抽卡','捨棄','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41488249,'原石的號咆',unistr('①：宣言1個通常怪獸的卡名可以發動。這個回合，我方的宣言的通常怪獸以及我方的「原石」怪獸的戰鬥產生給我方的戰鬥傷害變成0。我方場上沒有怪獸存在的場合，隨後可以從我方的牌組、墓地將1隻宣言的通常怪獸特殊召喚。\u000a②：對手回合將墓地的此卡除外，以我方的場上、墓地1隻通常怪獸為對象可以發動。直到結束階段得到對手場上1隻攻擊力高於那隻怪獸的怪獸的控制權。'),'效果1','效果2','是否將1隻宣言的通常怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41493640,'行列怪獸 桂馬',unistr('此卡召喚成功時，選擇對手的魔法與陷阱區域覆蓋的1張卡可以發動。確認覆蓋的那張卡，那是陷阱卡的場合，那張卡破壞。不是的場合，那張卡回復原狀。\u000a此效果將陷阱卡破壞時，可以發動以下效果。\u000a●從手牌將1隻地屬性、等級3的怪獸表側守備表示特殊召喚。'),'破壞','●從手牌特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41510920,'神星的因子','①：怪獸的效果、魔法、陷阱卡發動時，將我方場上1隻表側表示的「星騎士」怪獸送去墓地可以發動。那個發動無效並破壞。那之後，我方從牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41516133,'超巨大戰艦 金屬奴隸',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：從手牌、牌組將最多5隻等級10以下的「巨大戰艦」怪獸送去墓地可以發動（同名卡最多1張）。此卡從手牌特殊召喚。那之後，依照為了發動此效果而送去墓地的數量，給此卡放置計數器。\u000a②：我方、對手回合，去除此卡的1個計數器，以包含我方場上的「巨大戰艦」怪獸的場上2張表側表示卡為對象可以發動（同一連鎖上最多1次）。那些卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41517789,'星態龍',unistr('協調+協調以外的怪獸1隻以上\u000a此卡只能用同步召喚來特殊召喚。\u000a①：此卡的同步召喚不會被無效化。\u000a②：在此卡的同步召喚成功時，雙方不能發動魔法、陷阱、怪獸的效果。\u000a③：此卡攻擊的場合，直到傷害步驟結束時不受其他卡的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41517968,'E.HERO 暗輝人',unistr('「E.HERO 閃光人」+「E.HERO 死靈黑暗人」\u000a此卡只能用融合召喚來特殊召喚。\u000a此卡向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a此卡攻擊的場合，在傷害步驟結束時變成守備表示。\u000a此卡被破壞時，選擇對手場上的1隻怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41522092,'FNo.0 未來皇霍普ZEXAL',unistr('相同階級的超量怪獸×2\u000a規則上此卡的階級當作1。\u000a①：此卡的攻擊力、守備力上升我方場上以及對手墓地的超量怪獸的階級的總和×500。\u000a②：對手怪獸不能選擇其他怪獸作為攻擊對象，對手不能將場上的其他卡作為效果的對象。\u000a③：1回合1次，對手在場上發動效果時，去除此卡的1個超量素材可以發動。得到對手場上1隻怪獸的控制權。這個回合，此卡不會被戰鬥、效果破壞。'),'','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41524885,'驅魔修女 阿索菲勒',unistr('等級4怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡用「驅魔修女」怪獸為素材超量召喚的場合可以發動。這個回合，雙方不能發動墓地的卡的效果。\u000a②：此卡不會被從墓地特殊召喚的怪獸發動的效果破壞。\u000a③：去除此卡的1個超量素材，以對手場上1隻怪獸為對象可以發動。那隻怪獸回到手牌。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41525660,'群豪的忍者-南月',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：場地區域有「群豪世界-真羅萬象」存在的場合或我方場上有水屬性的「群豪」怪獸存在的場合可以發動。此卡在正前方的我方的主要怪獸區域特殊召喚。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：以此卡以外的主要怪獸區域1隻怪獸為對象可以發動。那隻怪獸的位置向與其相鄰的怪獸區域移動。\u000a②：怪獸區域的此卡向其他的怪獸區域移動的場合，以我方的魔法與陷阱區域1張「群豪」怪獸卡為對象可以發動。那張卡在那個正前方的我方的主要怪獸區域特殊召喚。'),'請選擇移動位置的怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41544074,'混沌男巫','「神聖精靈」+「黑魔族的布幕」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41554273,'機動霧龍衝鋒',unistr('「機動霧龍衝鋒」在1回合只能發動1張。\u000a①：從牌組將1隻「機動霧龍」怪獸特殊召喚。此效果特殊召喚的怪獸不受其他卡的效果影響，在結束階段破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41562624,'不知火的武部',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚成功時可以發動。從手牌、牌組將1隻「妖刀-不知火」怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了不死族怪獸以外不能特殊召喚。\u000a②：此卡被除外的場合可以發動。我方從牌組抽1張卡。那之後，選1張手牌捨棄。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41578483,'千年眼納祭',unistr('「納祭」+效果怪獸\u000a①：1回合1次，對手怪獸的效果發動時，以對手的場上、墓地1隻效果怪獸為對象可以發動。那隻對手的效果怪獸當作裝備卡給此卡裝備。\u000a②：此卡的攻擊力、守備力上升此卡的效果裝備的怪獸的對應數值。\u000a③：原卡名和此卡的效果裝備的怪獸相同的怪獸不能攻擊，那個效果無效化。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41587307,'折斷的竹光','①：裝備怪獸的攻擊力上升0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41589166,'天下人 紫炎','此卡不受陷阱卡的效果影響。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41613948,'D-HERO 魔鬼小子',unistr('這個卡名的效果發動的整回合中，我方不能攻擊宣言。\u000a①：1回合1次，以對手場上1隻怪獸為對象可以發動（此效果在此卡在我方場上表側攻擊表示存在的場合可以發動和處理）。那隻對手怪獸直到發動後第2次的我方準備階段除外。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41619242,'恐懼爪牙 來自肆世壞的天跨',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從以下效果選擇1個發動。\u000a●以我方場上1隻「恐懼爪牙」怪獸或「維薩斯-星霜」，以及對手場上1隻表側表示怪獸為對象可以發動。那隻我方怪獸的攻擊力、守備力上升那隻對手怪獸的攻擊力和守備力之中較高的數值。\u000a●以我方場上的「恐懼爪牙」怪獸或「維薩斯-星霜」為對象的效果發動時可以發動。那個效果無效。'),'●攻守上升','●效果無效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41620959,'龍之靈廟',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻龍族怪獸送去墓地。此效果送去墓地的怪獸是龍族通常怪獸的場合，隨後可以從牌組將1隻龍族怪獸送去墓地。'),'是否再把1隻龍族怪獸送去墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41628550,'超重武者 鬼若-O2',unistr('①：此卡召喚、特殊召喚成功時可以發動。此卡的表示形式變更。\u000a②：此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41639001,'聖刻龍-龍努特','1回合1次，場上表側表示存在的此卡成為魔法、陷阱、效果怪獸的效果的對象時發動。從我方的手牌、牌組、墓地選1隻龍族通常怪獸，攻擊力、守備力變成0特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41659072,'熾天龍 裁決',unistr('協調+協調以外的怪獸1隻以上\u000a此卡同步召喚的場合，同步素材怪獸必須全部都是相同屬性的怪獸。\u000a①：如果我方墓地有4種以上協調怪獸存在，此卡已被同步召喚，1回合1次，支付一半生命值可以發動。此卡以外的場上的卡全部破壞。此效果的發動後，直到回合結束時我方除了龍族怪獸以外不能特殊召喚。\u000a②：我方結束階段發動。從我方牌組上方將4張卡除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41685633,'雷神龍-雷龍',unistr('「雷龍」怪獸×3\u000a此卡只能用融合召喚或以下方法特殊召喚。\u000a●將手牌1隻雷族怪獸和「雷神龍-雷龍」以外的我方場上1隻雷族融合怪獸除外，可以從額外牌組特殊召喚。\u000a①：雷族怪獸的效果在手牌發動時可以發動（傷害步驟也能發動）。場上1張卡破壞。\u000a②：場上的此卡被效果破壞的場合，可以將我方墓地2張卡除外作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41705642,'打撈戰士','此卡上級召喚成功時，可以將手牌或是我方墓地存在的1隻協調特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41721210,'龍騎士 黑魔導',unistr('「黑魔導」+龍族怪獸\u000a①：只要此卡在場上、墓地存在，卡名當作「黑魔導」。\u000a②：只要此卡在怪獸區域存在，我方場上的魔法、陷阱卡不會被對手的效果破壞，對手不能將其作為效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41722932,'黑暗滅絕斬','我方場上有3隻以上闇屬性怪獸存在的場合可以發動。選擇場上的1張表側表示的卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41729254,'翼之魔妖-波旬',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將「翼之魔妖-波旬」以外的1隻「魔妖」怪獸特殊召喚。\u000a②：只要此卡在怪獸區域存在，我方除了「魔妖」怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41735184,'黑魔術的繼承',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方墓地將2張魔法卡除外可以發動。從牌組將「黑魔術的繼承」以外的1張記載「黑魔導」的卡名或「黑魔導女孩」的卡名的魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41739381,'機械裝置作響騎士',unistr('連結怪獸以外的原攻擊力是1000以下的機械族怪獸1隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合，將我方場上1張表側表示的永續魔法卡送去墓地可以發動。從牌組將1張「機械裝置作響之夜」加入手牌。\u000a②：以我方墓地1隻攻擊力1000以下的機械族怪獸為對象可以發動。我方場上1隻其他的機械族怪獸解放，對象怪獸守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41741922,'火山岩龍','將我方場上表側守備表示的此卡解放可以發動。從我方的手牌以及墓地各將1隻等級3以下的龍族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41753322,'龍腳獸 腕龍',unistr('此卡不能從牌組特殊召喚。此卡可以解放1隻恐龍族怪獸以表側表示上級召喚。\u000a①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉召喚成功的場合發動。此卡以外的場上的怪獸全部變成裡側守備表示。\u000a③：此卡被攻擊的場合，那次戰鬥產生給對手的戰鬥傷害變成2倍。'),'解放1隻恐龍族怪獸召喚','變成裡側守備','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41762634,'吸血跳蚤','攻擊力高強的巨型吸血跳蚤，輕視它會非常危險。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41763141,'蜃欺龍',unistr('種族、屬性相同且等級不同的怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，對手不能將我方場上的融合怪獸作為效果的對象。\u000a②：此卡作為融合召喚的素材送去墓地的場合可以發動。從額外牌組將1隻融合怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化，在結束階段回到額外牌組。這個回合，我方除了融合怪獸以外不能從額外牌組特殊召喚。'),'','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41767843,'幻奏的音女 絲可爾','①：我方的「幻奏」怪獸和對手怪獸進行戰鬥的傷害計算時，將此卡從手牌送去墓地可以發動。那隻對手怪獸的攻擊力、守備力直到回合結束時變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41773061,'Voici la Carte ～這是菜單～',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將2隻卡名不同的「新式魔廚」怪獸向對手展示，對手從其中選1隻。那1隻怪獸加入我方的手牌，其餘回到牌組。那之後，可以依照此效果加入手牌的怪獸的種族選1張以下的卡從我方的牌組、墓地加入手牌。\u000a●獸戰士族：「Recette de Poisson ～魚料理的食譜～」\u000a●戰士族：「Recette de Viande ～肉料理的食譜～」'),'N/A','是否再選1張對應的卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41782653,'超頂科技血神翼龍',unistr('此卡不能通常召喚。只能讓我方的除外狀態的5隻恐龍族怪獸回到牌組來特殊召喚。這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，對手發動魔法、陷阱卡時可以發動。我方的手牌、場上（表側表示）1隻恐龍族怪獸破壞，那個發動無效並破壞。\u000a②：此卡被效果送去墓地的場合可以發動。從牌組將1張「進化藥」魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41788781,'極星獸 古爾法克西','對手場上有同步怪獸表側表示存在，我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41790641,'電力王國',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：對手不能發動位於此卡以及我方場上的「電力」怪獸的正前方的對手怪獸自身的召喚、特殊召喚成功時的效果。\u000a②：以我方場上1隻「電力」怪獸為對象可以發動。從牌組將1隻和那隻怪獸卡名不同的「電力」怪獸特殊召喚。那之後，我方失去此效果特殊召喚的怪獸的攻擊力數值的生命值。此效果的發動後，直到回合結束時我方除了雷族怪獸以外不能特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41802073,'群豪的電擊者-子爵',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方主要階段可以發動。此卡在正前方的我方的主要怪獸區域特殊召喚。此效果的發動後，直到回合結束時我方除了「群豪」怪獸以外不能特殊召喚（從額外牌組特殊召喚不在此限）。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：如果此卡已被特殊召喚，我方主要階段可以發動。從我方的額外牌組選1隻表側表示的「群豪」靈擺怪獸在我方的魔法與陷阱區域當作永續魔法卡以表側表示放置。\u000a②：怪獸區域的此卡向其他的怪獸區域移動的場合可以發動。從我方的額外牌組選1隻表側表示的「群豪」靈擺怪獸在我方的靈擺區域放置。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41803903,'魔界台本「浪漫故事家」',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：選我方場上1隻「魔界劇團」靈擺怪獸回到持有者的手牌，從我方的額外牌組將原卡名和回到手牌的怪獸不同的1隻表側表示的「魔界劇團」靈擺怪獸守備表示特殊召喚。\u000a②：我方的額外牌組有表側表示的「魔界劇團」靈擺怪獸存在，覆蓋的此卡被對手的效果破壞的場合可以發動。從牌組選任意數量的「魔界台本」魔法卡在我方的魔法與陷阱區域覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41830887,'影印機塊 複印小矮人',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「機塊」怪獸為對象可以發動。此卡從手牌特殊召喚。此效果特殊召喚的此卡直到結束階段和對象怪獸當作同名卡。\u000a②：將墓地的此卡除外，以我方場上1隻「機塊」怪獸為對象可以發動。從我方的手牌、墓地選1隻那隻怪獸的同名怪獸特殊召喚。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41850466,'源數混沌儀式','①：我方場上的表側表示的「CNo.1 混沌源數門-空」被怪獸的效果破壞的回合，從我方墓地的卡以及被除外的我方的卡之中，以1張「源數網路」和4隻「No.」超量怪獸為對象可以發動。從額外牌組將1隻「CNo.1000 夢幻虛神 原數天靈」變成攻擊力10000/守備力1000特殊召喚，作為對象的5張卡成為超量素材。此效果的發動後，直到回合結束時我方只能將怪獸召喚、特殊召喚共1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41855169,'昇靈術師 奘玄',unistr('手牌隨機選1張捨棄到墓地可以發動。場上的特殊召喚的怪獸全部破壞。\u000a只要此卡在場上表側表示存在，雙方不能將怪獸特殊召喚。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41858121,'大日神械物質',unistr('選擇我方墓地的3張裝備魔法卡可以發動。選擇的卡回到牌組洗牌，那之後從以下效果挑選1個適用。\u000a●從我方牌組抽1張卡。\u000a●對手場上的1張卡破壞。'),'●從我方牌組抽1張牌','●對手場上的1張卡破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41859700,'燃燒之藻','此卡被送去墓地時，對手回復1000生命值。','回復','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41867019,'魔妖遊行',unistr('這個卡名的①效果在同一連鎖上只能發動1次。\u000a①：從額外牌組以外有不死族同步怪獸特殊召喚的場合可以發動（傷害步驟也能發動）。從以下效果挑選1個適用。這個回合，我方的「魔妖遊行」的效果不能適用相同效果。\u000a●我方從牌組抽1張卡。\u000a●從牌組選「魔妖遊行」以外的1張「魔妖」魔法、陷阱卡在我方場上覆蓋。\u000a●對手場上的攻擊力最低的1隻怪獸送去墓地。\u000a●給予對手800傷害。'),'●從牌組抽1張卡','●從牌組覆蓋魔法陷阱卡','●對手場上攻擊力最低的怪獸送去墓地','●給予對手800傷害','','','','','','','','','','','','');
INSERT INTO texts VALUES(41872150,'蝗蟲軍勢','此卡在1回合1次可以變成裡側守備表示。此卡反轉召喚成功時，破壞對手場上1張魔法、陷阱卡。','變成裡側守備表示','破壞魔法陷阱卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41902352,'BF-東雲之克奇','特殊召喚的此卡不能作為同步素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41908872,'霸王眷龍 光明亞龍',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：怪獸特殊召喚的場合，如果我方場上有「霸王龍 札克」和另1隻靈擺怪獸存在可以發動。此卡特殊召喚。那之後，可以將我方場上的1隻靈擺怪獸和此卡其中1隻的屬性、等級變成和另1隻相同。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從我方的額外牌組（表側）將1隻「霸王眷龍」靈擺怪獸或「霸王門」靈擺怪獸加入手牌。那之後，可以進行1隻「霸王眷龍」同步怪獸的同步召喚或1隻「霸王眷龍」超量怪獸的超量召喚。\u000a②：此卡在額外牌組表側存在的狀態，我方場上的表側表示的靈擺怪獸被戰鬥、效果破壞的場合可以發動。此卡加入手牌。'),'靈擺效果1','效果1','效果2','是否改變怪獸的屬性、等級？','請選擇要改變的怪獸','是否同步召喚或超量召喚？','','','','','','','','','','');
INSERT INTO texts VALUES(41916534,'鐵漢斯',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚成功的場合可以發動。從牌組將1隻「鐵騎士」特殊召喚。此效果的處理時場地區域沒有「斯特朗堡的黃金城」存在的場合，直到回合結束時我方不能從額外牌組將怪獸特殊召喚。\u000a②：場地區域有「斯特朗堡的黃金城」存在的場合，此卡的攻擊力上升我方場上的「鐵騎士」的數量×1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41924516,'白森林的魔狼 西爾維亞',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡特殊召喚的場合可以發動。對手場上的表側表示怪獸全部變成裡側守備表示。\u000a②：只要此卡在怪獸區域存在，我方場上的幻想魔族、魔法使族同步怪獸，攻擊力上升500，向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的2倍的戰鬥傷害。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41925941,'冥王的咆哮','我方場上的惡魔族怪獸進行戰鬥的場合，在那個傷害步驟時支付100的倍數的生命值可以發動。直到這個回合結束時，選擇進行戰鬥的1隻對手怪獸的攻擊力、守備力下降支付的數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41927278,'脆刃之劍',unistr('①：「脆刃之劍」在我方場上只能有1張表側表示存在。\u000a②：裝備怪獸的攻擊力上升2000，裝備怪獸的戰鬥產生的戰鬥傷害由雙方玩家承受。\u000a③：我方受到2000以上的戰鬥傷害的場合發動。此卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41930553,'暗黑的瘴氣','1回合1次，選擇對手墓地的1隻怪獸可以發動。從手牌捨棄1張惡魔族怪獸，選擇的怪獸除外。','是否現在發動此卡的效果？','捨棄手牌並除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41933425,'接觸之門',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方墓地將2種「新空間俠」怪獸各1隻除外可以發動。從我方的手牌、牌組、墓地選2隻「新空間俠」怪獸特殊召喚（同名卡最多1張）。此效果發動過的回合，我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a②：我方場上的表側表示的需以「E.HERO 新宇俠」為融合素材的融合怪獸回到額外牌組的場合，將墓地的此卡除外可以發動。選被除外的1隻我方的「新空間俠」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41940225,'破壞劍士融合',unistr('「破壞劍士融合」的①②效果1回合各能使用1次。\u000a①：從我方的手牌以及我方、對手場上將融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚以「爆裂劍士」為融合素材的1隻融合怪獸。\u000a②：此卡在墓地存在的場合，將1張手牌送去墓地可以發動。墓地的此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41949033,'闇之暗殺者','持有精神之劍、君臨魔界的暗殺者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41952656,'尋你海豚','場上的此卡被對手破壞送去墓地時，我方牌組最上方的卡送去墓地。送去墓地的卡是水屬性怪獸的場合，從我方牌組抽1張卡。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41978142,'霞之谷的執行者','此卡召喚成功時，場上表側表示存在的魔法、陷阱卡全部回到持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41999284,'連結栗子球',unistr('等級1怪獸1隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：對手怪獸的攻擊宣言時，將此卡解放可以發動。那隻對手怪獸的攻擊力直到回合結束時變成0。\u000a②：我方、對手回合，此卡在墓地存在的場合，將我方場上1隻等級1怪獸解放可以發動。此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42002073,'娛樂夥伴 撲克少女',unistr('【靈擺效果】\u000a【怪獸效果】\u000a①：1回合1次，我方主要階段可以發動。融合怪獸卡決定的包含此卡的融合素材怪獸從我方場上送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a②：此卡在靈擺區域被破壞的場合，以我方墓地1隻龍族融合怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42006475,'守護神官 瑪娜',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在，只以我方場上的1隻魔法使族怪獸為對象的對手的魔法、陷阱、怪獸的效果發動時可以發動。此卡特殊召喚。\u000a②：只要此卡在怪獸區域存在，我方場上的等級7以上的魔法使族怪獸不會被效果破壞。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從我方的手牌、牌組、墓地選1隻「黑魔導女孩」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42009836,'化石恐龍 厚頭龍',unistr('①：此卡反轉的場合發動。場上的特殊召喚的怪獸全部破壞。\u000a②：只要此卡在怪獸區域存在，雙方不能將怪獸特殊召喚。'),'特殊召喚的怪獸全部破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42015635,'新宇空間',unistr('只要此卡在場上存在，「E.HERO 新宇俠」以及需以「E.HERO 新宇俠」為融合素材的融合怪獸的攻擊力上升500。\u000a需以「E.HERO 新宇俠」為融合素材的融合怪獸在結束階段時回到額外牌組的效果可以不發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42021064,'機動石器 土偶羅多',unistr('包含岩石族怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方墓地1隻岩石族怪獸為對象可以發動。此卡的攻擊力上升對象怪獸的攻擊力數值。\u000a②：對手主要階段，以場上1隻攻擊力在此卡的攻擊力以下的其他怪獸為對象可以發動。此卡的攻擊力下降對象怪獸的攻擊力數值，對象怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42023223,'電磁石戰士α',unistr('「電磁石戰士α」的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1隻等級8的「磁石勇士」怪獸加入手牌。\u000a②：對手回合將此卡解放可以發動。從牌組將1隻等級4的「磁石戰士」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42024143,'XX-軍刀 突擊守衛','我方墓地有「X-軍刀」怪獸2隻以上存在，我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42029847,'幻奏的音女 塞瑞娜',unistr('①：天使族怪獸上級召喚的場合，此卡可以當作2隻解放。\u000a②：此卡特殊召喚成功的回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻「幻奏」怪獸。'),'召喚（幻奏的音女 塞瑞娜）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42035044,'漆黑的豹戰士','①：只要此卡在怪獸區域存在，此卡的攻擊宣言之際，我方必須解放此卡以外的我方場上1隻怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42035045,'漆黑的豹戰士','①：只要此卡在怪獸區域存在，此卡的攻擊宣言之際，我方必須解放此卡以外的我方場上1隻怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42052439,'切火女郎',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有戰士族怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：將場上的此卡送去墓地可以發動。從手牌將1隻等級4以下的戰士族怪獸特殊召喚。這個回合，對手不能將此效果特殊召喚的怪獸作為效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42055234,'龍女僕 赤焰龍女',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方、對手回合，將此卡從手牌捨棄，以我方場上1隻「龍女僕」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升2000。\u000a②：只要我方場上有融合怪獸存在，此卡不會被效果破壞。\u000a③：我方、對手的戰鬥階段結束時可以發動。此卡回到手牌，從手牌將1隻等級3的「龍女僕」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42071342,'暗黑的海龍兵','守護暗黑海的戰士。在水中的戰鬥力就不用多說了，即使是在陸地上也同時擁有很高的戰鬥能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42079445,'失星降落','①：以我方墓地1隻同步怪獸為對象可以發動。那隻怪獸的等級下降1，守備力變成0守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化，不能變更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42081767,'藏橡實的粗心松鼠',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，以我方墓地最多3張魔法、陷阱卡為對象可以發動。那些卡除外。下個回合的結束階段，此效果除外的卡回到牌組。\u000a②：我方準備階段，以我方的除外狀態的1張魔法、陷阱卡為對象可以發動。那張卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42082363,'薰風獅鷲','此卡從手牌送去墓地的場合，可以從我方牌組將1隻「薰風」怪獸特殊召喚。「薰風獅鷲」的效果1回合只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42090294,'爬蟲妖 尼亞米尼',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方墓地有爬蟲類族怪獸存在的場合，我方、對手的主要階段，將此卡從手牌送去墓地，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力變成0。\u000a②：對手場上有攻擊力0的怪獸存在的場合可以發動。此卡從墓地特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42091632,'命主王的螺旋',unistr('這個卡名的卡在1回合只能發動1張。對手已發動手牌、墓地的怪獸的效果的回合，此卡也能從手牌發動。\u000a①：以對手場上1隻怪獸為對象可以發動。那隻怪獸回到手牌、額外牌組。我方墓地沒有陷阱卡存在的場合，隨後對手可以從自身墓地將1隻怪獸特殊召喚。此卡從手牌發動的場合，發動後，這次決鬥中我方不能發動光、闇屬性怪獸的效果。\u000a\u000a※命王的螺旋'),'效果1','適用「命主王的螺旋」的效果來發動','是否從自身墓地特殊召喚？','「命主王的螺旋」的效果1適用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(42097666,'青之眼的精靈',unistr('等級4以下的龍族、魔法使族怪獸1隻\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組選1張「光之靈堂」加入手牌或送去墓地。\u000a②：只要此卡在怪獸區域存在，我方除了龍族怪獸以外不能特殊召喚。\u000a③：將此卡解放可以發動。從我方的手牌、墓地將1隻「青眼」怪獸特殊召喚。此效果從墓地特殊召喚的效果怪獸不能攻擊，效果無效化。'),'效果1','N/A','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42104806,'希望的天啟',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻表側表示的龍族、等級8怪獸送去墓地可以發動。從額外牌組將1隻龍族、階級8超量怪獸當作超量召喚特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42110434,'大植然蝴蝶','1回合1次，對手怪獸的攻擊宣言時可以發動。我方牌組最上方的1張卡送去墓地，那次攻擊無效。','攻擊無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42110604,'高速疾行機人 比劍騎手',unistr('協調+協調以外的怪獸1隻以上\u000a我方1回合只能特殊召喚1次「高速疾行機人 比劍騎手」。\u000a①：此卡在1次戰鬥階段中可以攻擊2次。\u000a②：此卡進行戰鬥的傷害步驟開始時發動。此卡的攻擊力上升200。\u000a③：此卡被送去墓地的場合，以被除外的1張我方的「疾行機人」卡片為對象可以發動。那張卡加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42125140,'星宿鋏龍 夏烏拉斯',unistr('「星宿」怪獸+手牌的怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地2張「星宿」卡片，以及與其中任何卡相同種類（怪獸、魔法、陷阱）的場上1張表側表示卡為對象可以發動。那3張卡回到牌組。\u000a②：此卡在墓地存在的狀態，2隻以上怪獸同時被送去墓地的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42129512,'巨大無尾熊','非常巨大的一種死亡無尾熊。雖然性格溫順。但是因為擁有非常強大的力量而令人感到恐懼。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42138622,'時光之渦',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有不死族怪獸以及「活死人的呼聲」存在，對手發動怪獸或通常、速攻魔法卡的效果時可以發動。對手投擲1次硬幣，依照那個正反面將那個效果變成以下效果。\u000a●正：「對手必須將自身場上1隻怪獸除外」\u000a●反：「我方必須將我方場上的怪獸全部除外」'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42141493,'多多迷寶 軟綿雀精',unistr('此卡的效果發動的整回合中，我方只能發動1次此卡以外的「多多迷寶」怪獸的效果。\u000a①：我方、對手回合，我方場上沒有卡存在的場合，將此卡從手牌捨棄可以發動。這個回合中，適用以下效果。\u000a●每次對手從牌組、額外牌組將怪獸特殊召喚，我方抽1張卡。\u000a●結束階段中，我方的手牌高於對手場上的卡片數量+6張的場合，依照那個相差數量將我方的手牌隨機放回牌組。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42143067,'怒氣土器',unistr('這個卡名的效果1回合只能使用1次。\u000a①：從手牌捨棄1隻岩石族怪獸可以發動。從牌組將原本的屬性、等級和那隻怪獸相同的1隻岩石族怪獸以表側攻擊表示或裡側守備表示特殊召喚。'),'從牌組特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42149850,'一次性學習裝置',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：裝備怪獸的攻擊力上升我方墓地的怪獸數量×200。\u000a②：此卡從場上送去墓地的回合的結束階段可以發動。此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42155488,'基因組鬥士',unistr('此卡可以不用解放來召喚。\u000a用這個方法召喚的此卡的等級變成3，原攻擊力變成一半。\u000a此外，1回合1次，宣言1個種族可以發動。這個回合此卡作為同步素材的場合，包含此卡的整組同步素材當作宣言的種族。此效果發動過的回合，我方不能將宣言的種族以外的怪獸召喚、特殊召喚。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42158279,'教導劇作術',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：解放我方場上的「教導」怪獸或儀式、融合、同步怪獸，直到等級合計和儀式召喚的怪獸相同為止，從手牌、牌組儀式召喚1隻「教導」儀式怪獸。\u000a②：將墓地的此卡除外，以我方墓地2隻等級不同的「教導」怪獸為對象可以發動。那2隻之中的1隻加入手牌，另1隻回到牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42160203,'霸王眷龍 黑暗反叛',unistr('闇屬性等級4靈擺怪獸×2\u000a①：1回合1次，此卡和對手怪獸進行戰鬥的傷害計算前，去除此卡的1個超量素材可以發動。直到回合結束時，那隻對手怪獸的攻擊力變成0，此卡的攻擊力上升那個原攻擊力數值。\u000a②：我方、對手的戰鬥階段，讓此卡回到額外牌組可以發動。從我方的額外牌組（表側）將「霸王眷龍」靈擺怪獸或「霸王門」靈擺怪獸合計最多2隻守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42166000,'神史萊姆',unistr('水族怪獸+水屬性、等級10怪獸\u000a此卡只能用融合召喚或以下方法從額外牌組特殊召喚。\u000a●將我方場上1隻攻擊力0的水族、等級10怪獸解放，可以從額外牌組特殊召喚。\u000a①：需要解放3隻怪獸的怪獸上級召喚的場合，此卡可以當作3隻解放。\u000a②：此卡不會被戰鬥破壞，對手不能選擇「神史萊姆」以外的我方場上的怪獸作為攻擊對象，也不能作為效果的對象。'),'解放「神史萊姆」當作3隻怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42167046,'闊劍式未爆彈','選擇場上表側攻擊表示存在的2隻怪獸可以發動。選擇的怪獸從場上離開時，此卡破壞。此卡破壞時，選擇的怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42172465,'創星改歸',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌、牌組將1隻「星遺物」怪獸特殊召喚。此效果特殊召喚的怪獸在下個回合的結束階段破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42175079,'大噴火','我方場上有「侏羅紀世界」存在的場合，我方的結束階段時可以發動。場上的卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42193638,'異響鳴琴倒水',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從以下效果挑選1個適用。我方的靈擺區域沒有「異響鳴琴」卡片存在的場合，適用的效果由對手挑選。\u000a●我方回復500生命值。那之後，可以從我方牌組上方翻開卡片，直到「異響鳴琴」卡片出現為止。那個場合，翻開的「異響鳴琴」卡片加入手牌，其餘回到牌組。\u000a●我方受到500傷害。那之後，可以從牌組將「異響鳴琴倒水」以外的1張「異響鳴琴」卡片送去墓地。'),'效果1','●回復','●傷害','是否從我方牌組上方翻開卡片？','是否從牌組將1張卡送去墓地？','','','','','','','','','','','');
INSERT INTO texts VALUES(42198835,'外法的騎士',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上沒有怪獸存在的場合或有「勇者衍生物」存在的場合，我方、對手的主要階段可以發動。此卡從手牌特殊召喚。\u000a②：我方場上有「勇者衍生物」存在的場合，以對手場上最多2張卡為對象可以發動。此卡的控制權轉移給對手，對象卡片回到持有者的手牌。此效果在對手回合也能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42199039,'妖刀竹光',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：裝備怪獸的攻擊力上升0。\u000a②：以我方場上1張其他的「竹光」卡片為對象可以發動。那張卡回到手牌，裝備怪獸在這個回合可以直接攻擊。\u000a③：此卡被送去墓地的場合可以發動。從牌組將「妖刀竹光」以外的1張「竹光」卡片加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42201897,'聖徒棘路',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：向對手展示額外牌組的1隻「聖徒」融合怪獸，那個等級每有4，就讓我方的墓地、除外狀態的1張「罪寶」卡片回到牌組。那之後，展示的怪獸當作融合召喚特殊召喚。\u000a②：將墓地的此卡除外，以我方墓地1張「罪寶」魔法、陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡在這個回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42209438,'真魔六武眾-鬼斬',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：我方場上的「六武眾」怪獸的攻擊力、守備力只在戰鬥階段期間上升600。\u000a②：對手主要階段，從我方墓地將1張「六武式」卡片除外，以場上1張卡為對象可以發動。那張卡破壞。\u000a③：我方場上有2隻以上「六武眾」怪獸存在的場合可以發動。此卡從墓地特殊召喚。'),'','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42216237,'傑拉的天使',unistr('協調+協調以外的怪獸1隻以上\u000a「傑拉的天使」的②效果1回合只能使用1次。\u000a①：此卡的攻擊力上升被除外的對手的卡片數量×100。\u000a②：此卡被除外的場合，下個回合的準備階段發動。被除外的此卡特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42228966,'戰場的慘劇',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：怪獸之間沒有進行戰鬥的回合的我方主要階段2，捨棄1張手牌可以發動。從牌組選1張「戰場的慘劇」在我方的魔法與陷阱區域覆蓋。\u000a②：怪獸之間進行戰鬥的回合的結束階段發動。回合玩家從自身牌組上方將5張卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42230449,'No.2 源數之門-貳',unistr('等級1怪獸×3\u000a①：此卡不會被戰鬥破壞。\u000a②：此卡和對手怪獸進行戰鬥的傷害步驟結束時，去除此卡的1個超量素材可以發動。我方場上的全部「源數」怪獸的攻擊力直到回合結束時變成2倍。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42232157,'命運的盤上',unistr('這個卡名的卡在1回合只能發動1張。此卡也能向對手展示手牌的1隻通常怪獸，在覆蓋的回合發動。\u000a①：從我方的手牌、墓地將最多5隻通常怪獸攻擊表示特殊召喚。此卡的發動後，直到回合結束時我方不能從額外牌組將怪獸特殊召喚。'),'效果1','適用「命運的盤上」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42233477,'野蠻人的憤怒','①：以我方場上的1隻戰士族怪獸為對象可以發動此卡。那隻怪獸的攻擊力上升1000，那隻怪獸戰鬥破壞的怪獸不去墓地而是回到持有者的手牌。對象怪獸從場上離開時，此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42237854,'機動要塞 鋼鐵堡壘',unistr('①：以我方場上任意數量的機械族、等級4怪獸為對象可以發動。此卡發動後變成效果怪獸（機械族、地、等級4、攻/守0）在怪獸區域特殊召喚。那之後，對象的表側表示怪獸當作裝備卡給此卡裝備。此卡也當作陷阱卡。\u000a②：此卡的效果特殊召喚的此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力的合計數值，對手不能選擇其他的我方場上的怪獸作為攻擊對象，也不能作為效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42239546,'繭狀體 小鼴鼠','場上有「新宇空間」存在時，藉由解放此卡，從手牌或牌組將1隻「新空間俠 大地鼴鼠」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42256406,'卡片阻擋者','此卡召喚、反轉召喚、特殊召喚成功時，此卡變成守備表示。我方場上表側表示存在的怪獸被選擇作為攻擊對象時，可以將攻擊對象變更為此卡。此卡成為攻擊對象時，可以將我方牌組上方的卡最多3張送去墓地。送去墓地的卡每有1張，此卡的守備力直到回合結束時上升500。','守備表示','攻擊對象變更','守備力增加','選擇從牌組送進墓地的卡片張數','','','','','','','','','','','','');
INSERT INTO texts VALUES(42280216,'太陽的神官',unistr('①：只有對手場上有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：場上的此卡被破壞送去墓地時可以發動。從牌組將1隻「赤蟻 阿斯卡托爾」或「蘇帕伊」加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42291297,'花札衛－雨四光－',unistr('協調+協調以外的怪獸3隻\u000a①：只要此卡在怪獸區域存在，我方場上的「花札衛」怪獸不會被效果破壞，不會成為對手的效果的對象。\u000a②：對手抽牌階段對手通常抽牌的場合發動。給予對手1500傷害。\u000a③：對手結束階段，從以下效果選擇1個發動。\u000a●跳過下個我方回合的抽牌階段。\u000a●此卡的效果直到下個對手的準備階段無效。'),'效果2','●跳過抽牌階段','●此卡的效果無效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42302563,'獄花的大煌耀聖 斯特莉琪亞',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在中央的主要怪獸區域存在，原攻擊力變成3000。\u000a②：我方、對手的主要階段可以發動。從我方的手牌、墓地將1隻等級6以下的「耀聖」怪獸特殊召喚。那之後，可以讓場上的全部等級4以上的怪獸的等級直到回合結束時下降3。這個回合，我方除了同步怪獸以外不能從額外牌組特殊召喚。'),'效果2','是否使等級下降3？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42303365,'爬蟲妖 毒蛇','①：此卡召喚成功時，以對手場上1隻攻擊力0的怪獸為對象可以發動。得到那隻攻擊力0的怪獸的控制權。','得到控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42307760,'蕾禍之大王鬼牙',unistr('昆蟲族、植物族、爬蟲類族怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：怪獸從對手的牌組、額外牌組特殊召喚的場合可以發動。場上2隻怪獸破壞。\u000a②：此卡在墓地存在的場合，以我方場上1隻昆蟲族、植物族、爬蟲類族怪獸為對象可以發動。那隻怪獸回到牌組最下方，此卡特殊召喚。這個回合，我方除了昆蟲族、植物族、爬蟲類族怪獸以外不能特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42309337,'反擊反擊','反擊陷阱卡的發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42314669,'完全隔音壁','我方場上沒有同步怪獸表側表示存在的場合，在主要階段1開始時可以發動。直到下個對手回合結束時，雙方不能將同步怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42328171,'發條蝙蝠','我方主要階段時可以發動。將我方場上表側攻擊表示存在的此卡變更成表側守備表示，選擇我方墓地存在1隻「發條」怪獸加入手牌。這個效果於此卡在場上表側表示存在期間只能使用1次。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42338879,'喔喔公雞',unistr('①：雙方場上沒有怪獸存在的場合，此卡可以當作等級3怪獸從手牌特殊召喚。\u000a②：對手場上有怪獸存在，我方場上沒有卡存在的場合，此卡可以從當作等級4怪獸從手牌特殊召喚。\u000a③：表側表示的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42348802,'糙齒龍','虎紋恐龍。跑過曠野的速度相當快。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42352091,'源數之壁',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上沒有「源數之壁」以外的卡存在的場合，將手牌、場上的此卡送去墓地可以發動。從手牌、牌組選1張「源數網路」發動。此效果在對手回合也能發動。\u000a②：我方受到戰鬥傷害時可以發動。此卡從手牌特殊召喚，那次傷害步驟結束後戰鬥階段結束。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42364257,'避雷針','對手發動「落雷」時可以發動。那個效果不是將我方場上的怪獸破壞，改成將對手場上的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42364374,'裝甲蒼蠅','我方場上沒有此卡以外的昆蟲族怪獸存在的場合，此卡的攻擊力與守備力都變成1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42377643,'海膽軍貫',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示此卡以外的手牌1張「軍貫」卡片可以發動。此卡從手牌特殊召喚。那之後，依照展示的卡適用以下效果。\u000a●「舍利軍貫」：可以將展示的怪獸特殊召喚。\u000a●其他：展示的卡回到牌組最下方。\u000a②：以我方場上1隻「軍貫」怪獸為對象可以發動。那隻怪獸的等級變成4或5。那之後，可以從牌組將1隻「舍利軍貫」加入手牌。'),'效果1','效果2','是否將展示的怪獸特殊召喚？','變成等級4','變成等級5','是否從牌組將1隻「舍利軍貫」加入手牌？','','','','','','','','','','');
INSERT INTO texts VALUES(42378577,'靈擺切換',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方的靈擺區域1張卡為對象可以發動。那張卡特殊召喚。\u000a②：以我方的怪獸區域的1隻靈擺怪獸為對象可以發動。那隻靈擺怪獸在我方的靈擺區域放置。'),'效果1','效果2','請選擇要放置在靈擺區域的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42382265,'DD刻度測量師',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方、對手的準備階段，以我方、對手的靈擺區域的最多2張卡為對象可以發動。那些卡的靈擺刻度直到回合結束時變成0。\u000a【怪獸效果】\u000a這個卡名的①②③怪獸效果1回合各能使用1次。\u000a①：我方場上有「DD」靈擺怪獸卡存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。此卡的等級變成4。\u000a③：此卡被送去墓地的場合，或表側加入額外牌組的場合，以我方場上1張「DD」靈擺怪獸卡為對象可以發動。那張卡回到手牌。'),'靈擺效果1','效果1','效果2','效果3','','','','','','','','','','','','');
INSERT INTO texts VALUES(42386471,'卡通雙子精靈',unistr('①：此卡在召喚、反轉召喚、特殊召喚的回合不能攻擊。\u000a②：我方場上有「卡通世界」存在，對手場上沒有卡通怪獸存在的場合，此卡可以直接攻擊。\u000a③：此卡給予對手戰鬥傷害時可以發動。對手的手牌隨機選1張捨棄。\u000a④：場上的「卡通世界」被破壞時，此卡破壞。'),'捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42388271,'星遺物-『星櫃』',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上的連結怪獸被對手的效果破壞送去我方墓地的場合，將此卡從手牌送去墓地，以其中1隻連結怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：怪獸上級召喚的場合，此卡可以當作2隻解放。\u000a③：通常召喚的此卡在怪獸區域存在，對手從額外牌組將怪獸特殊召喚的場合可以發動。從牌組將1隻怪獸送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42391240,'天蠍星聖 心宿二','此卡召喚、特殊召喚成功時，可以選擇我方墓地1隻「星聖」怪獸加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42418084,'誕生的天使','據說它能知道女性腹部是否存在著生命。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42421606,'No.85 狂箱',unistr('等級4怪獸×2\u000a①：此卡不能攻擊。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。擲1次骰子，依照擲出點數適用以下效果。\u000a●1：我方的生命值變成一半。\u000a●2：我方從牌組抽1張卡。\u000a●3：對手選1張手牌捨棄。\u000a●4：選場上1張表側表示的卡，那個效果直到回合結束時無效。\u000a●5：選場上1張卡破壞。\u000a●6：此卡破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42425831,'雷遁封印式','1回合1次，可以藉由讓我方場上表側表示存在的1隻風屬性怪獸回到牌組最下方，選擇對手墓地的最多2張卡除外。','對手墓地的卡除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42427230,'分裂機器人',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上的表側表示的「分裂機器人」全部解放可以發動。將最多到解放數量×2隻的「機械衍生物」（機械族、炎、等級1、攻/守200）在我方場上特殊召喚。這個衍生物被破壞時，每有1隻對手受到500傷害。\u000a②：此卡被除外的場合，以我方場上任意數量的衍生物為對象可以發動。那些衍生物破壞。'),'效果1','效果2','請選擇要特殊召喚的衍生物數量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42427231,'機械衍生物','由「分裂機器人」的效果特殊召喚。這個衍生物被破壞時，控制者受到500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42429678,'抖抖妖@伊格尼斯者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1隻「@伊格尼斯者」怪獸送去墓地。\u000a②：此卡作為電子界族同步怪獸的同步素材送去墓地的場合，以「抖抖妖@伊格尼斯者」以外的我方墓地1隻作為那次同步召喚的素材的怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42431833,'衛星閃靈伽瑪暴',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：場上的全部等級2、階級2、連結2的怪獸的攻擊力、守備力直到回合結束時上升1400。\u000a②：我方主要階段將墓地的此卡除外，以我方場上1隻等級2、階級2、連結2的怪獸為對象可以發動。那隻怪獸的攻擊力直到對手回合結束時上升1400。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42431843,'魔天老','被天界放逐的墮落天使，在暗域中的戰鬥很出色。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42444868,'輪迴的珀修斯','①：怪獸的效果、魔法、陷阱卡發動時，向對手展示手牌的1張反擊陷阱卡，捨棄1張手牌，支付1000生命值可以發動。那個發動無效，那張卡回到持有者的牌組。那之後，可以從牌組、額外牌組選1隻「珀修斯」怪獸特殊召喚。','是否特殊召喚1隻「珀修斯」怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42461852,'電腦網風暴',unistr('①：場上的連結狀態的怪獸的攻擊力、守備力上升500。\u000a②：只要此卡在場地區域存在，連結怪獸的連結召喚不會被無效化。\u000a③：我方受到2000以上的戰鬥、效果傷害的場合可以發動。我方的額外牌組的裡側表示的卡洗牌，翻開那張最上方的卡。如果翻開的卡是電子界族連結怪獸，那隻怪獸特殊召喚。如果不是，回復原狀。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42463414,'尖針半魚人','①：只要此卡在怪獸區域存在，我方場上的魚族、海龍族、水族怪獸的攻擊力上升400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42469671,'超電導波 雷擊砲',unistr('這個卡名的卡在1回合只能發動1張。此卡的發動和效果不會被無效化。\u000a①：我方場上有原卡名是「歐西里斯的天空龍」的怪獸存在的場合可以發動。對手場上的表側表示怪獸全部破壞。此卡在我方主要階段發動的場合，隨後可以適用以下效果。\u000a●我方依照此效果破壞送去對手墓地的怪獸數量從牌組抽牌。這個回合，我方只能用1隻怪獸攻擊。'),'是否適用以下效果？','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42472002,'聖騎士 康尼厄斯',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：我方場上有「聖劍」裝備魔法卡存在的場合，此卡可以從手牌特殊召喚。\u000a②：用場上的此卡為素材同步、超量、連結召喚的「聖騎士」怪獸得到以下效果。\u000a●這次特殊召喚成功的場合可以發動。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻怪獸。此效果的發動後，直到回合結束時我方除了「聖騎士」怪獸以外不能從額外牌組特殊召喚。'),'●增加1次召喚（聖騎士 康尼厄斯）','召喚（聖騎士 康尼厄斯）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42493140,'百夫長從騎士 特露迪亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。我方場上的此卡，和「百夫長從騎士 特露迪亞」以外的手牌、牌組1隻「百夫長」怪獸當作永續陷阱卡在我方的魔法與陷阱區域表側表示放置。這個回合，我方不能將「百夫長從騎士 特露迪亞」特殊召喚。\u000a②：此卡當作永續陷阱卡的場合，我方、對手的主要階段可以發動。此卡特殊召喚。那之後，可以讓此卡的等級上升4。'),'效果1','是否將等級上升？','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42502956,'艾爾斯岩的日出',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻獸族怪獸為對象可以發動。那隻獸族怪獸特殊召喚，對手場上有表側表示怪獸存在的場合，那些怪獸的攻擊力直到回合結束時下降我方墓地的獸族、鳥獸族、植物族怪獸數量×200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42510430,'日落節拍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的表側表示怪獸變成裡側守備表示的場合，以場上1張卡為對象可以發動。那張卡破壞。\u000a②：我方場上的反轉怪獸反轉的場合，以其中1隻為對象可以發動（傷害步驟也能發動）。給予對手那隻怪獸的等級×200傷害。'),'破壞','給予傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42516299,'火焰回歸',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以我方墓地1隻炎屬性怪獸為對象可以發動。選1張我方的手牌送去墓地，對象怪獸特殊召喚。\u000a②：將墓地的此卡除外，以我方的墓地、除外狀態的3隻炎屬性怪獸為對象可以發動。那些怪獸回到牌組。那之後，我方抽1張卡。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42517468,'搗蛋小粉',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡從手牌、場上送去墓地的場合可以發動。雙方玩家從牌組抽1張卡，那之後選1張手牌捨棄。此效果讓我方將「搗蛋」卡片捨棄的場合，隨後可以指定1格沒有使用的對手的怪獸區域。那個區域直到對手回合結束時不能使用。'),'是否指定對手的1格怪獸區域不能使用？','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42534368,'沉默的死者','①：以我方墓地1隻通常怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸不能攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42541548,'鬼哥布林','只要此卡在我方場上表側表示存在，我方的結束階段時，可以藉由讓手牌的1張通常怪獸卡回到牌組最下方，從牌組抽1張卡。這個效果1回合只能使用1次。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42542842,'麗之魔妖-妲姬',unistr('①：「麗之魔妖-妲姬」在我方場上只能有1隻表側表示存在。\u000a②：此卡在墓地存在，「魔妖」怪獸從額外牌組往我方場上特殊召喚時可以發動。此卡特殊召喚。此效果發動的整回合中，我方除了「魔妖」怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42544773,'封印之偉魔導士 斯普恩',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：可以將此卡從手牌捨棄，從以下效果選擇1個發動。\u000a●從牌組將「封印之偉魔導士 斯普恩」以外的1隻「偉魔」怪獸加入手牌。\u000a●對手場上1隻怪獸的攻擊力直到回合結束時變成一半。\u000a②：將墓地的此卡除外，以我方場上1隻表側表示怪獸為對象可以發動。從我方的額外牌組、墓地將1隻「偉魔」怪獸當作裝備魔法卡給對象怪獸裝備。'),'效果1','效果2','●從牌組加入手牌','●攻擊力變成一半','','','','','','','','','','','','');
INSERT INTO texts VALUES(42548470,'搖晃的彈簧秤',unistr('選擇我方場上表側表示存在的2隻等級不同的「發條」怪獸可以發動。對手挑選其中1隻，另1隻怪獸的等級直到回合結束時變成和對手挑選的怪獸相同。對手挑選等級較低的怪獸的場合，那之後我方可以從牌組抽1張卡。\u000a\u000a※搖晃的發條秤'),'是否抽1張卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42551040,'武尊神器-生','我方的主要階段時，我方場上有「武尊神」怪獸存在的場合，將墓地的此卡從遊戲中除外，選擇對手場上表側攻擊表示存在的1隻怪獸可以發動。選擇的怪獸變成表側守備表示，那個守備力直到回合結束時變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42560034,'夜之逃飛行','①：以我方場上1隻表側表示怪獸為對象可以發動。那隻表側表示怪獸回到持有者的手牌。這個回合，雙方不能發動此效果加入手牌的卡以及那些同名卡的效果。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42562690,'娛樂夥伴 水黽船','①：攻擊表示的此卡被選擇作為攻擊對象時可以發動。此卡變成表側守備表示，將那次攻擊無效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42566602,'瑚之龍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，捨棄1張手牌，以對手場上1張卡為對象可以發動。那張卡破壞。\u000a②：同步召喚的此卡被送去墓地的場合可以發動。我方從牌組抽1張卡。'),'破壞對手場上的卡','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42577802,'結合突變魔',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、場上將「突變魔」融合怪獸卡決定的融合素材怪獸除外，從額外牌組融合召喚那1隻融合怪獸。這個回合對手已發動卡的效果的場合，我方的牌組、墓地的怪獸也能各選最多1隻作為融合素材。\u000a\u000a※融合突變魔'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42578427,'捕鼠器','對手將攻擊力500以下的怪獸召喚、反轉召喚時，可以選擇那1隻怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42589641,'輝星騎士 冬季大三角',unistr('等級4「星騎士」怪獸×3\u000a此卡超量召喚的整回合中，我方除了「星騎士」怪獸以外不能特殊召喚。\u000a①：此卡超量召喚的場合發動。場上的其他卡全部回到手牌。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。對手的手牌隨機選1張送去墓地。\u000a③：持有超量素材的此卡被送去墓地的場合，以我方墓地1隻「星騎士」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42591472,'笑笑花','總是在笑著的花。如果持續聽它的笑聲的話，頭腦就會變得混亂。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42592719,'劍鬥獸 亞歷山大',unistr('此卡不能被「劍鬥獸 連擊鬥士」以外的效果特殊召喚。只要特殊召喚的此卡在我方場上表側表示存在，此卡不受魔法效果的影響。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到牌組，從牌組將「劍鬥獸 亞歷山大」以外的1隻「劍鬥獸」怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42596828,'龍狸燈',unistr('①：1回合1次，從手牌捨棄1隻幻龍族怪獸可以發動。此卡的守備力直到回合結束時上升1000。此效果在對手回合也能發動。\u000a②：攻擊表示的此卡和攻擊表示怪獸進行戰鬥的傷害計算時1次，可以發動。那次戰鬥用雙方怪獸的守備力當作攻擊力進行傷害計算。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42598242,'特殊颶風','捨棄1張手牌可以發動。場上的特殊召喚的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42599677,'火焰殺手','使用火焰盾的劍士。那個盾能無視任何攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42600274,'電子芭蕾裙',unistr('①：此卡可以從我方的手牌、場上將1隻戰士族或天使族怪獸解放，從手牌特殊召喚。\u000a②：此卡為了儀式召喚而被解放的場合，以我方墓地1張儀式魔法卡為對象可以發動。那張卡加入手牌。'),'特殊召喚出場','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42620460,'時間潛行者動力儲存',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡發動後變成通常怪獸（超能族、闇、等級4、攻1900/守2500）在怪獸區域特殊召喚（也當作陷阱卡）。那之後，可以從我方的手牌、牌組、墓地將1隻機械族的「時間潛行者」怪獸特殊召喚。\u000a②：持有魔法卡和陷阱卡作為超量素材的超量怪獸在我方場上存在的場合，將墓地的此卡除外可以發動。場上1張卡除外。'),'效果1','效果2','是否將1隻怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42625254,'小暴龍','恐龍的孩子。性格極其凶暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42632209,'炎斬機 終末西格瑪',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在額外怪獸區域存在，此卡不受「斬機」卡片以外的卡的效果影響。\u000a②：額外怪獸區域的此卡和對手怪獸的戰鬥給予對手的戰鬥傷害變成2倍。\u000a③：此卡被戰鬥或對手的效果破壞的場合可以發動。從牌組將1張「斬機」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42647539,'石像鬼的小丑','此卡召喚、反轉召喚、特殊召喚成功時，選擇場上1隻表側表示怪獸的表示形式變更。','表示形式變更','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42664989,'天賜的寶牌','①：將我方的手牌、場上的卡全部除外可以發動。我方從牌組抽牌直到手牌變成2張為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42671151,'弗麗格的蘋果','①：我方場上沒有怪獸存在，我方受到戰鬥傷害時可以發動。我方的生命值回復受到的傷害的數值，在我方場上將1隻「邪精衍生物」（惡魔族、闇、等級1、攻/守?）特殊召喚。這個衍生物的攻擊力、守備力變成這個效果讓我方回復的數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42671152,'邪精衍生物','由「弗麗格的蘋果」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42679662,'入魔阿撒托斯','反轉：選擇場上1隻特殊召喚的怪獸回到持有者的牌組。','回到牌組','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42682609,'繭狀體 小海豚','場上有「新宇空間」存在時，藉由解放此卡，從手牌或牌組將1隻「新空間俠 水色海豚」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42685062,'來自地獄的使者',unistr('此卡不能特殊召喚。\u000a此卡可以解放1隻怪獸來召喚。\u000a這個方法召喚的此卡的等級變成5，原本的攻擊力、守備力變成一半。'),'解放1隻怪獸召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42703248,'颶風','場上的魔法、陷阱卡全部回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42705243,'御巫之契',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌、牌組將1隻「御巫」怪獸特殊召喚。那之後，可以從我方的手牌、墓地將1張那隻怪獸可以裝備的裝備魔法卡給那隻怪獸裝備。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'是否選1張裝備魔法卡裝備？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42705244,'御巫之契',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌、牌組將1隻「御巫」怪獸特殊召喚。那之後，可以從我方的手牌、墓地將1張那隻怪獸可以裝備的裝備魔法卡給那隻怪獸裝備。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'是否選1張裝備魔法卡裝備？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42709949,'守護神之矛','裝備怪獸的攻擊力上升雙方墓地的裝備怪獸的同名卡數量×900。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42711820,'廢鐵戰士',unistr('「廢鐵同步者」+協調以外的怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡同步召喚的場合可以發動。從牌組選1隻「廢品同步者」或1張記載「廢品戰士」的卡名的卡加入手牌或送去墓地。\u000a②：「廢鐵戰士」以外的我方場上的以下怪獸發動的效果不會被無效化。\u000a●記載「廢品戰士」的卡名的怪獸\u000a●原卡名包含「戰士」的同步怪獸'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42713844,'地中族邪界獸 利古鑽土蜥',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上的表側表示怪獸變成裡側表示時，我方場上沒有表側表示怪獸存在的場合可以發動。此卡從手牌守備表示特殊召喚。\u000a②：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a③：此卡反轉的場合，以對手場上1隻怪獸為對象可以發動。那隻怪獸除外。'),'效果3','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42717221,'電子界時脈龍',unistr('「時脈翼龍」+連結怪獸1隻以上\u000a①：此卡融合召喚成功時可以發動。依照那些素材的連結標記的合計數量，從我方牌組上方將卡片送去墓地。直到下個回合結束時，其他的我方怪獸不能攻擊，此卡的攻擊力上升此效果送去墓地的數量×1000。\u000a②：只要我方場上有連結怪獸存在，對手不能將我方場上的其他怪獸作為攻擊、效果的對象。\u000a③：融合召喚的此卡被對手的效果送去墓地的場合可以發動。從牌組將1張魔法卡加入手牌。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42719764,'召喚衝擊',unistr('①：每次怪獸召喚、特殊召喚，給此卡放置1個召喚計數器（最多4個）。\u000a②：此卡被放置召喚計數器，那些召喚計數器的數量變成4個的場合發動。此卡的召喚計數器全部去除，場上的怪獸全部送去墓地。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42737833,'XX-軍刀 埃摩斯之刃','①：此卡被戰鬥破壞送去墓地時可以發動。從牌組將1隻等級4以下的「X-軍刀」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42741437,'驅魔修女 米迦埃莉絲',unistr('等級4怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡用「驅魔修女」怪獸為素材超量召喚的我方、對手回合，以對手的場上、墓地1張卡為對象可以發動。那張卡除外。\u000a②：此卡不會被從墓地特殊召喚的怪獸戰鬥破壞。\u000a③：去除此卡的1個超量素材可以發動。從牌組將1張「驅魔修女」魔法、陷阱卡加入手牌。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42741438,'驅魔修女 米迦埃莉絲',unistr('等級4怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡用「驅魔修女」怪獸為素材超量召喚的我方、對手回合，以對手的場上、墓地1張卡為對象可以發動。那張卡除外。\u000a②：此卡不會被從墓地特殊召喚的怪獸戰鬥破壞。\u000a③：去除此卡的1個超量素材可以發動。從牌組將1張「驅魔修女」魔法、陷阱卡加入手牌。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42752141,'進化帝 長鱷龍',unistr('恐龍族等級4怪獸×2\u000a①：此卡以外的怪獸的效果發動時，去除此卡的1個超量素材可以發動。那個發動無效並破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42759961,'小丑戲幫 芙蕾亞',unistr('藉由「小丑戲幫」卡片降臨\u000a這個卡名的①效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。從牌組將儀式怪獸以外的1張「小丑戲幫」卡片加入手牌。那之後，選1張我方的手牌捨棄。\u000a②：此卡被解放的場合，可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●我方、對手的場上、墓地的儀式怪獸全部回到牌組。\u000a●場上1隻效果怪獸變成裡側守備表示。'),'效果1','效果2','●儀式怪獸回到牌組','●變成裡側守備','','','','','','','','','','','','');
INSERT INTO texts VALUES(42776855,'追趕之翼',unistr('以我方場上1隻同步怪獸為對象可以發動此卡。\u000a①：只要此卡在魔法與陷阱區域存在，對象怪獸不會被戰鬥以及對手的效果破壞。\u000a②：對象怪獸和等級5以上的對手怪獸進行戰鬥的傷害步驟開始時可以發動。那隻對手怪獸破壞。對象怪獸的攻擊力直到回合結束時上升這個效果破壞的怪獸的原攻擊力數值。\u000a③：對象怪獸從場上離開的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42776960,'魂之接力','①：從手牌將1隻怪獸特殊召喚。只要此效果特殊召喚的怪獸在我方場上表側表示存在，我方受到的全部傷害變成0。那隻怪獸從場上離開時，對手獲得決鬥勝利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42781164,'殺手旋律 造軌者',unistr('「殺手旋律」協調+協調1隻以上\u000a場上的此卡作為素材同步召喚的場合，手牌的1隻協調也能作為同步素材。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從牌組將1張「殺手旋律」卡片加入手牌。\u000a②：此卡作為同步素材送去墓地的場合可以發動。對手場上1張卡回到手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42790071,'幻變騷靈 多功能詐欺者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方發動陷阱卡的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合可以發動（此效果發動的整回合中，我方除了「幻變騷靈」怪獸以外不能特殊召喚）。從牌組將「幻變騷靈 多功能詐欺者」以外的1隻「幻變騷靈」怪獸守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42793609,'極星寶 布里希嘉曼','選擇我方以及對手場上的表側表示怪獸各1隻可以發動。那隻我方怪獸的攻擊力直到回合結束時變成和那隻對手怪獸的原攻擊力相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42810973,'廢品弓箭手',unistr('「廢品同步者」+協調以外的怪獸1隻以上\u000a1回合1次，選擇對手場上1隻怪獸可以發動。選擇的怪獸除外。此效果除外的怪獸在這個回合的結束階段以相同的表示形式回到對手場上。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42822433,'星騎士 牛郎星',unistr('這個卡名在規則上也當作「星聖」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚的場合，最多到我方場上的光、闇屬性超量怪獸數量，以場上的卡為對象可以發動。那些卡破壞。\u000a②：我方場上有「星騎士 牛郎星」以外的「星騎士」、「星聖」怪獸特殊召喚的場合可以發動。此卡從墓地特殊召喚。這個回合，我方除了用超量怪獸以外不能攻擊宣言。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42829885,'強引的衛兵','確認對手的手牌，從其中選1張卡回到牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42851643,'穿孔重機 齒岩台車',unistr('此卡召喚成功時，可以讓我方場上的全部機械族怪獸等級上升1。\u000a此卡向守備表示怪獸攻擊時，若攻擊力超過那個守備力，給予對手那個數值的戰鬥傷害。\u000a此外，此卡攻擊的場合，在傷害步驟結束時變成守備表示。'),'等級上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42868711,'幻影的哥拿龜','以場上表側表示存在的此卡為對象的對手的魔法、陷阱卡的效果無效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42874792,'發條兔','選擇我方場上的1隻「發條」怪獸可以發動。選擇的怪獸直到下個我方準備階段除外。此效果在對手回合也能發動。這個效果於此卡在場上表側表示存在期間只能使用1次。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42878636,'古代機械齒輪獵犬',unistr('①：此卡召喚的場合發動。給予對手600傷害。\u000a②：此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a③：1回合1次，我方主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「古代機械齒輪」融合怪獸融合召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42880485,'超重輝將 翡翠-E',unistr('【靈擺效果】\u000a①：我方除了「超重武者」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a②：1回合1次，以我方場上1隻「超重武者」怪獸為對象可以發動。那隻怪獸的等級上升1。\u000a【怪獸效果】\u000a此卡在規則上也當作「超重武者」卡片。此卡可以解放1隻「超重武者」怪獸來上級召喚。\u000a①：此卡召喚、特殊召喚成功時可以發動。此卡的表示形式變更。\u000a②：此卡可以在表側守備表示的狀態攻擊。那個場合，此卡用守備力當作攻擊力進行傷害計算。'),'解放1隻「超重武者」怪獸上級召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42883273,'森之住人 沃登','此卡的攻擊力上升場上的植物族怪獸數量×100。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42899204,'死配的咒眼',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手將怪獸攻擊表示特殊召喚時，攻擊力高於那隻怪獸的「咒眼」怪獸在我方場上存在的場合，以那1隻對手怪獸為對象可以發動此卡。得到那隻怪獸的控制權。只要我方的魔法與陷阱區域有「塞勒涅的咒眼」存在，那隻怪獸也當作「咒眼」怪獸。那隻怪獸從場上離開時，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42901635,'電磁石勇士 電磁狂神',unistr('此卡不能通常召喚。從我方的手牌、場上、墓地將「電磁石戰士α」「電磁石戰士β」「電磁石戰士γ」各1隻除外可以特殊召喚。\u000a①：從我方墓地將1隻等級4以下的「磁石戰士」怪獸除外，以對手場上1張卡為對象可以發動。那張卡破壞。\u000a②：此卡被戰鬥或對手的效果破壞的場合，以被除外的我方的「電磁石戰士α」「電磁石戰士β」「電磁石戰士γ」各1隻為對象可以發動。那些怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42908201,'死亡馬尼亞魔鬼','①：此卡戰鬥破壞對手怪獸時可以發動。從牌組將1隻等級4以下的獸族怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42921475,'妖精傳姬-塔利婭',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡反轉的場合可以發動。從手牌將1隻怪獸特殊召喚。\u000a②：對手發動通常魔法、通常陷阱卡時，將我方場上1隻其他怪獸解放可以發動。那個效果變成「對手場上1隻表側表示怪獸變成裡側守備表示」。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42925441,'光子變身',unistr('此卡發動後，在第2次的我方準備階段送去墓地。這個卡名的①效果1回合只能使用1次。\u000a①：可以將我方場上的1隻表側表示的「光子」怪獸或「銀河」怪獸送去墓地，從以下效果選擇1個發動。將「銀河眼光子龍」送去墓地發動的場合，可以兩者都選擇。\u000a●從牌組將1隻和那隻怪獸原卡名不同的「光子」怪獸特殊召喚。\u000a●從牌組將「光子變身」以外的1張「光子」卡片加入手牌。'),'效果1','●從牌組特殊召喚','●從牌組加入手牌','兩者都選','「光子變身」送去墓地','','','','','','','','','','','');
INSERT INTO texts VALUES(42932862,'冥占術姬 塔羅蕾絲',unistr('藉由「冥占術的儀式」降臨。此卡只能用儀式召喚或「聖占術姬 塔羅蕾」的效果特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡反轉的場合可以發動。從牌組將1隻反轉怪獸裡側守備表示特殊召喚。\u000a②：我方、對手回合，可以從以下效果選擇1個發動。\u000a●選我方場上任意數量的裡側表示怪獸變成表側守備表示。\u000a●選我方場上任意數量的表側表示怪獸變成裡側守備表示。'),'效果1','效果2','●裡側變成表側守備','●表側變成裡側守備','','','','','','','','','','','','');
INSERT INTO texts VALUES(42940335,'迷擬寶箱鬼 王座',unistr('等級1「迷擬寶箱鬼」怪獸×2\u000a這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：去除此卡的1個超量素材可以發動。從手牌、牌組、墓地將1隻「迷擬寶箱鬼 領主」特殊召喚。\u000a②：我方、對手的主要階段，以我方場上1隻「迷擬寶箱鬼 領主」為對象可以發動。此卡當作攻擊力上升1000的裝備魔法卡給那隻怪獸裝備。那之後，最多到此卡原先持有的超量素材數量，可以讓場上的卡回到手牌。'),'特殊召喚','當作裝備魔法卡','是否讓場上的卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42940404,'機甲部隊結構體',unistr('①：此卡召喚成功時可以發動。從牌組將「機甲部隊結構體」以外的1隻「機甲部隊」怪獸加入手牌。\u000a②：1回合1次，可以從以下效果選擇1個發動。\u000a●以我方場上1隻機械族怪獸為對象，此卡當作裝備卡給那隻怪獸裝備。裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備的此卡特殊召喚。'),'N/A','N/A','效果1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42941100,'搗蛋小黃','據說能使盡一切手段搗亂的搗蛋三人組其中一員。據說三人到齊將會有什麼事情發生。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42945701,'火靈術-「紅」','①：解放我方場上1隻炎屬性怪獸可以發動。給予對手解放的怪獸的原攻擊力數值的傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42952160,'冥府的對照鏡',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手的攻擊、效果讓我方受到傷害時可以發動。依照受到的傷害種類適用以下效果。\u000a●戰鬥：從我方墓地將1隻攻擊力在那個數值以下的怪獸特殊召喚，那個傷害步驟結束後戰鬥階段結束。\u000a●效果：給予對手那個數值的2倍的傷害。'),'效果1','●戰鬥傷害','●效果傷害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42956963,'夢魘惡魔大軍','①：將我方場上1隻怪獸解放可以發動。在對手場上將3隻「夢魘惡魔衍生物」（惡魔族、闇、等級6、攻/守2000）攻擊表示特殊召喚。「夢魘惡魔衍生物」被破壞時，那個控制者受到每1隻800傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42956964,'夢魘惡魔衍生物','由「夢魘惡魔大軍」的效果特殊召喚。這個衍生物被破壞時，控制者受到800傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42969214,'鋼鐵指猴','1回合1次，在我方的主要階段時，可以讓此卡的攻擊力上升400。此效果發動的整回合中，此卡不能攻擊。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42994702,'迷惘的木乃伊','此卡1回合有1次可以變成裡側守備表示。那之後，將我方的主要怪獸區域的全部裡側守備表示怪獸洗牌，以裡側守備表示放回。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43002864,'爬蟲妖 守衛者','我方場上的此卡破壞送去墓地時，從牌組將1隻「爬蟲妖」怪獸加入手牌。','牌組檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43004235,'海造賊-祝宴',unistr('這個卡名的①效果1回合只能使用1次，②效果在決鬥中只能使用1次。\u000a①：我方場上有「海造賊」怪獸存在的場合可以發動此卡。我方從牌組抽我方場上的裝備卡的數量+1張卡，那之後手牌選我方場上的裝備卡的數量回到牌組。\u000a②：此卡在墓地存在，我方從額外牌組將「海造賊」怪獸特殊召喚的場合可以發動。此卡給其中1隻怪獸當作攻擊力上升500的裝備卡裝備。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43011492,'慘禍的咒眼',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「咒眼」怪獸存在的場合，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。我方的魔法與陷阱區域有「塞勒涅的咒眼」存在的場合，此效果破壞的卡不去墓地而是除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43014054,'惡狂戰士','此卡作為同步召喚的素材送去墓地的場合，給予那個玩家2000傷害。此外，以此卡為同步素材的同步怪獸的攻擊力直到這個回合結束時上升2000。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43017476,'氘魔獸',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段將此卡從手牌捨棄可以發動。從牌組將1張「鍵結」魔法、陷阱卡加入手牌。\u000a②：此卡召喚、特殊召喚成功的場合，以我方墓地的「氫魔獸」「氧魔獸」「氘魔獸」其中1隻為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43034264,'機殼的要塞',unistr('①：只要此卡在場地區域存在，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻「機殼」怪獸。\u000a②：只要此卡在場地區域存在，「機殼」怪獸的召喚不會被無效化。'),'召喚（機殼的要塞）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43040603,'怪獸門','①：解放我方場上的1隻怪獸可以發動。從我方牌組上方翻開卡片，直到可以通常召喚的怪獸出現為止，那隻怪獸特殊召喚。剩下的翻開的卡全部送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43047672,'RR-最終要塞獵鷹',unistr('等級12怪獸×3\u000a①：持有「RR-」超量怪獸作為超量素材的此卡不受其他卡的效果影響。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。被除外的我方的「RR-」怪獸全部回到墓地。\u000a③：此卡的攻擊破壞怪獸時，將我方墓地的1隻「RR-」超量怪獸除外可以發動。此卡可以繼續攻擊。這個效果1回合可以使用最多2次。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43061293,'火焰飛鏢','我方的手牌是0張的場合可以發動。擲3次骰子，給予對手那個合計數值×100傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43066927,'迷擬寶箱鬼 妖精',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。此卡從手牌往對手場上裡側守備表示特殊召喚。我方場上有「迷擬寶箱鬼」怪獸存在的場合，也能改成在我方場上表側表示特殊召喚。\u000a②：此卡在主要階段反轉的場合發動。以下效果各自適用。\u000a●這個回合，我方不能發動從自身的手牌特殊召喚的怪獸的效果。\u000a●此卡的控制權轉移給對手。'),'反轉效果','從手牌特殊召喚','在我方場上特殊召喚','在對手場上特殊召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(43096270,'紫翠玉龍','許多沙皇遺失的珍寶都能在這稀世之龍的龍鱗上找到。它的創造者及這些帝國財寶如何被獲取仍都是個謎。但不論是否知曉，得到這條龍都已是中獎…','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43114901,'寶石騎士 紅縞',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●此卡戰鬥破壞對手怪獸送去墓地的場合，可以從我方牌組將1張「寶石騎士」卡片加入手牌。'),'牌組檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43129357,'蕾禍之武者髑髏',unistr('包含昆蟲族、植物族、爬蟲類族怪獸的怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次，這些效果發動的整回合中，我方除了昆蟲族、植物族、爬蟲類族怪獸以外不能特殊召喚。\u000a①：以我方墓地1隻「蕾禍」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a②：此卡在墓地存在的場合，以我方場上1隻昆蟲族、植物族、爬蟲類族怪獸為對象可以發動。那隻怪獸回到牌組最下方，此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43138260,'超量短印魚',unistr('①：此卡可以去除我方場上的2個超量素材，從手牌特殊召喚。\u000a②：此卡的①方法特殊召喚成功時，以我方墓地2隻魚族、等級4怪獸為對象可以發動。那些魚族怪獸守備表示特殊召喚。此效果特殊召喚的怪獸不能攻擊，效果無效化，也不能變更表示形式。將此效果特殊召喚的怪獸作為超量召喚的素材的場合，除了水屬性怪獸的超量召喚以外不能使用。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43140791,'蠕蟲餌',unistr('此卡發動的整回合中，我方不能將等級3、4的怪獸召喚、特殊召喚。\u000a①：我方場上有昆蟲族怪獸存在的場合可以發動。在我方場上將2隻「蠕蟲衍生物」（昆蟲族、地、等級1、攻/守0）特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43140792,'蠕蟲衍生物','由「蠕蟲餌」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43143567,'黃金鄉的墮天像',unistr('「黃金卿 埃爾德里奇」+不死族怪獸\u000a「黃金鄉的墮天像」1回合1次，只能用融合召喚或以下方法特殊召喚。\u000a●我方的場上或墓地有「黃金卿 埃爾德里奇」存在的狀態，將我方場上1隻不死族、光屬性怪獸解放可以從額外牌組特殊召喚。\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡從場上送去墓地的場合可以發動。從我方的牌組、額外牌組、墓地將1隻「埃爾德里奇」怪獸特殊召喚。'),'','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43147039,'光子驅逐者',unistr('此卡不能通常召喚。我方場上有「光子」怪獸或「銀河」怪獸存在的場合可以特殊召喚。我方1回合只能特殊召喚1次「光子驅逐者」。\u000a①：此卡特殊召喚的場合可以發動。從牌組將1隻「銀河眼光子龍」加入手牌。\u000a②：此卡在特殊召喚的回合不能攻擊。\u000a③：用場上的此卡為素材超量召喚的怪獸得到以下效果。\u000a●此卡戰鬥破壞的怪獸不去墓地而是除外。'),'效果1','「光子驅逐者」的效果3適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43150717,'超量疊光',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：裝備怪獸的攻擊力上升場上的超量素材數量×200。\u000a②：1回合1次，可以依照裝備怪獸的種類發動以下效果。\u000a●超量怪獸：去除我方場上的2個超量素材可以發動。從牌組將1張「超量」魔法、陷阱卡在我方場上覆蓋。\u000a●除此以外：從手牌將1隻等級和裝備怪獸的等級相同的怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'','●超量','●其他','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43175027,'極冰獸 暴風雪狼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方或對手的怪獸的攻擊宣言時可以發動。那次攻擊無效，從手牌將「極冰獸 暴風雪狼」以外的1隻等級4以下的水屬性怪獸特殊召喚。\u000a②：此卡在墓地存在，我方場上沒有怪獸存在的場合，對手的戰鬥階段開始時可以發動。此卡攻擊表示特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43175858,'卡通王國',unistr('①：作為此卡的發動時的效果處理，從我方牌組上方將3張卡裡側表示除外。\u000a②：只要此卡在場地區域存在，卡名當作「卡通世界」。\u000a③：只要此卡在場地區域存在，我方場上的卡通怪獸不會成為對手的效果的對象。\u000a④：我方場上的卡通怪獸被戰鬥、效果破壞的場合，可以依照被破壞的怪獸每1隻1張卡，從我方牌組上方將卡片裡側表示除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43191636,'龍影魚 布隆多魟',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●此卡的原攻擊力變成2300。此卡攻擊的場合，在戰鬥階段結束時變成守備表示。直到下個我方回合結束時，此卡不能變更表示形式。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43202238,'邪龍星-睚眥',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：場上的此卡不會成為對手的效果的對象。\u000a②：以我方場上1隻「龍星」怪獸和對手場上1張卡為對象可以發動。那些卡破壞。\u000a③：我方場上的此卡被戰鬥、效果破壞送去墓地時可以發動。從牌組將1隻幻龍族怪獸守備表示特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43210483,'音響戰士 吉他手',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：以此卡以外的我方場上1張「音響戰士」卡片為對象可以發動。那張卡和此卡回到持有者的手牌。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：我方的場地區域有「擴大機」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合，以我方的靈擺區域1張卡為對象可以發動。那張卡回到持有者的手牌。'),'靈擺效果1','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43215738,'冥銘途 碎骨舞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「冥銘途」怪獸存在的場合，以場上1張卡為對象可以發動。那張卡破壞。那之後，我方場上有「冥骸合龍-冥銘途拉爾・泰庫特利卡」存在的場合，可以將場上1張卡破壞。\u000a②：我方的「冥銘途」怪獸和對手怪獸進行戰鬥的攻擊宣言時，將墓地的此卡除外可以發動。對手場上的全部怪獸的攻擊力直到回合結束時下降1000。'),'效果1','效果2','是否將場上1張卡破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43218406,'機巧辰-高闇御津羽靇',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：從額外牌組特殊召喚的怪獸在場上有2隻以上存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：支付1500生命值可以發動。從額外牌組特殊召喚的場上的怪獸全部破壞。這個回合，我方只能用1隻怪獸攻擊。\u000a③：此卡被對手送去墓地的場合可以發動。選對手墓地1隻怪獸除外。那之後，我方的生命值回復那個攻擊力的數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43219114,'白之龍的威光',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：挑選我方的手牌、場上（表側表示）、墓地的最多3隻「青眼白龍」給雙方確認。那之後，將確認數量的對手場上的卡破壞。\u000a②：將墓地的此卡除外可以發動。解放我方的手牌、場上的「青眼白龍」，直到等級合計變成和儀式召喚的怪獸相同為止，從手牌儀式召喚1隻儀式怪獸。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43225434,'決鬥融合-戰鬥結合',unistr('「決鬥融合-戰鬥結合」在1回合只能發動1張。\u000a①：我方場上的融合怪獸和對手怪獸進行戰鬥的攻擊宣言時可以發動。直到傷害步驟結束時，那隻我方怪獸的攻擊力上升進行戰鬥的對手怪獸的攻擊力數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43228023,'青眼究極亞龍',unistr('「青眼白龍」+「青眼白龍」+「青眼白龍」\u000a①：場上的此卡不會成為對手的效果的對象，不會被對手的效果破壞。\u000a②：1回合1次，以對手場上1張卡為對象可以發動。那張卡破壞。此卡用原卡名是「青眼亞白龍」的怪獸為素材融合召喚的場合，此效果的對象可以變成2張或3張。此效果發動的整回合中，此卡不能攻擊。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43230671,'古代的蜥蜴戰士','遠古的保持著昔日姿態的蜥蜴戰士，意外的強悍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43236494,'Fairy Tale 序章 啟程的曉光',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在場地區域存在，雙方受到的戰鬥傷害變成一半。\u000a②：我方場上有獸族、光屬性怪獸或等級7、8的龍族同步怪獸存在的場合可以發動。我方抽1張卡。\u000a③：我方準備階段，將場地區域的此卡送去墓地可以發動。從我方的手牌、牌組將「Fairy Tale 序章 啟程的曉光」以外的1張場地魔法卡在我方的場地區域表側表示放置。'),'','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43237273,'新空間俠 漆黑獵豹','①：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。此卡直到結束階段得到和那隻怪獸的原本的卡名、效果相同的卡名、效果。','效果1','解除複製效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43241495,'娛樂夥伴 蹦床猞猁',unistr('【靈擺效果】\u000a「娛樂夥伴 蹦床猞猁」的靈擺效果1回合只能使用1次。\u000a①：我方靈擺召喚成功時，以我方或對手的靈擺區域1張卡為對象可以發動。那張卡回到持有者的手牌。\u000a【怪獸效果】\u000a①：此卡召喚成功時，以我方或對手的靈擺區域1張卡為對象可以發動。那張卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43250041,'吸收屏障','①：對手怪獸的攻擊宣言時，以1隻攻擊怪獸為對象可以發動。那隻攻擊怪獸的攻擊無效，我方回復那隻怪獸的攻擊力數值的生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43256007,'冰結界的隨身',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡解放可以發動。從手牌將1隻等級5以上的「冰結界」怪獸特殊召喚。\u000a②：不是在這個回合送去墓地的此卡在墓地存在的場合，以我方場上1隻等級3以上的水屬性怪獸為對象可以發動。那隻怪獸的等級下降2，此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43262273,'紅蓮的指名者','①：支付2000生命值，向對手展示全部手牌可以發動。確認對手的手牌，從其中選1張直到下個對手結束階段除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43266605,'PSY骨架多線人',unistr('「PSY骨架多線人」的③效果1回合只能使用1次。\u000a①：只要此卡在手牌、墓地存在，此卡當作「PSY骨架驅動者」。\u000a②：我方場上的「PSY骨架」卡片被戰鬥、效果破壞的場合，可以將手牌的此卡捨棄作為代替。\u000a③：此卡在墓地存在，我方場上有「PSY骨架」協調特殊召喚的場合可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43268675,'幻奏的音女 歐佩拉',unistr('①：此卡在召喚、反轉的回合不能攻擊。\u000a②：此卡成為融合召喚的素材送去墓地的場合可以發動。這個回合，我方場上的「幻奏」怪獸不會被戰鬥、效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43270827,'獸帶鬥神交叉',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「獸帶鬥神」怪獸存在，對手發動怪獸的效果時，可以從以下效果選擇1個發動（我方墓地有「無盡機關 阿爾銀洛系統」存在的場合，可以兩者都選擇）。\u000a●那個發動的效果無效。\u000a●那隻怪獸除外。'),'效果1','●那個發動的效果無效','●那隻怪獸除外','兩者都選','','','','','','','','','','','','');
INSERT INTO texts VALUES(43316238,'未界域的大腳怪',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。對手從我方的全部手牌中隨機選1張，我方捨棄那張卡。那是「未界域的大腳怪」以外的場合，隨後從手牌將1隻「未界域的大腳怪」特殊召喚，我方抽1張卡。\u000a②：此卡從手牌捨棄的場合，以對手場上1張表側表示卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43316239,'未界域的大腳怪',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。對手從我方的全部手牌中隨機選1張，我方捨棄那張卡。那是「未界域的大腳怪」以外的場合，隨後從手牌將1隻「未界域的大腳怪」特殊召喚，我方抽1張卡。\u000a②：此卡從手牌捨棄的場合，以對手場上1張表側表示卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43318266,'雲魔物-捲層雲',unistr('此卡不會被戰鬥破壞。\u000a此卡在場上表側守備表示存在的場合，此卡破壞。\u000a此卡召喚成功時，給此卡放置場上的「雲魔物」怪獸數量的霧計數器。\u000a藉由去除此卡的2個霧計數器，選擇場上1隻怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43321985,'上古妖精生命龍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡同步召喚的場合可以發動。我方抽1張卡。場上有「精靈的世界」存在的場合，改成從牌組將1隻光屬性的獸族、植物族、天使族怪獸或1張「永恆日光」加入手牌。\u000a②：我方的「上古妖精龍」以及記載那個卡名的怪獸可以在表側守備表示的狀態攻擊（用守備力當作攻擊力進行傷害計算）。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43331750,'結合複製',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方或對手的墓地1張「融合」通常、速攻魔法卡或「結合」通常、速攻魔法卡為對象可以發動。那張魔法卡除外。那之後，那張魔法卡發動時的效果適用。\u000a\u000a※融合複製'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43332022,'朱羅紀似雞龍','①：此卡被戰鬥破壞送去墓地的場合發動。對手可以選1張手牌捨棄讓此效果無效。不捨棄的場合，將破壞此卡的怪獸破壞。','破壞','是否捨棄1張手牌讓「朱羅紀似雞龍」的效果1無效？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43338320,'冥骸府-冥銘途蘭',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方的「冥銘途」怪獸進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a②：我方場上的怪獸被戰鬥、效果破壞的場合，以其中的1隻為對象可以發動。從我方的手牌、墓地將1隻等級低於那隻怪獸的「冥銘途」怪獸特殊召喚。\u000a③：我方結束階段，以我方墓地1張「冥銘途」魔法、陷阱卡為對象可以發動。那張卡在我方場上覆蓋。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43340443,'反衝','怪獸的召喚、反轉召喚無效。那隻怪獸回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43341600,'芙蕾雅的蘋果',unistr('①：最多到我方場上的「華爾裘蓮」怪獸數量，以對手墓地的卡為對象可以發動。那些卡除外。\u000a②：覆蓋的此卡因對手的效果從場上離開，被送去墓地的場合或被除外的場合可以發動。我方從牌組抽我方場上的「華爾裘蓮」怪獸數量+1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43352213,'貓女郎','用敏捷的動作躲避攻擊，用銳利的鉤爪襲擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43355214,'不死的大軍團',unistr('等級7怪獸×2\u000a「不死的大軍團」1回合1次也能重疊在我方場上的不死族、階級6的超量怪獸上方來超量召喚。\u000a這個卡名的①效果1回合只能使用1次。\u000a①：對手主要階段，去除此卡的2個超量素材，以對手場上1隻攻擊表示怪獸或對手墓地1隻怪獸為對象可以發動（此卡的超量素材只有超量怪獸的場合，去除的超量素材數量可以變成1個）。那隻怪獸作為此卡的超量素材。'),'是否重疊在階級6不死族超量怪獸上方來超量召喚？','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43359262,'電鍍軍曹',unistr('①：1回合1次，以對手的魔法與陷阱區域覆蓋的1張卡為對象可以發動。此卡得到以下效果。\u000a●只要此卡在怪獸區域存在，作為對象的覆蓋的卡不能發動。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43363035,'地下牢的徊神',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡從牌組送去墓地的場合發動（應對此效果的發動，雙方不能發動怪獸的效果）。我方場上的卡全部送去墓地，此卡特殊召喚。那之後，最多到此效果送去墓地的卡片數量，將對手場上的卡送去墓地。\u000a②：此卡從牌組以外送去墓地的場合，將1張手牌送去墓地可以發動。場上1張卡送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43366227,'七劍戰士',unistr('協調+協調以外的怪獸1隻以上\u000a1回合1次，此卡被裝備裝備卡時，給予對手800傷害。\u000a1回合1次，可以將此卡裝備的1張裝備卡送去墓地。\u000a此卡裝備的裝備卡送去墓地時，可以選擇對手場上的1隻表側表示怪獸破壞。'),'傷害','裝備送墓','破壞','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43378048,'混沌幻魔 阿米泰爾',unistr('「神炎皇 烏利亞」+「降雷皇 哈蒙」+「幻魔皇 拉比艾爾」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚（不需要「融合」）。\u000a①：此卡的攻擊力在我方回合中上升10000。\u000a②：此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43378076,'羅剎',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡召喚、反轉時，向對手展示手牌的1隻「羅剎」以外的靈魂怪獸可以發動。選擇對手場上表側攻擊表示存在的1隻怪獸回到持有者的手牌。此效果發動的整回合中，我方不能將怪獸特殊召喚。'),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43383478,'升階魔法-猛禽之力','①：我方場上的「RR-」超量怪獸被破壞送去墓地的回合，以我方墓地的1隻「RR-」超量怪獸為對象可以發動。那隻怪獸特殊召喚，將1隻階級比那隻怪獸高1階的「RR-」怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43385557,'魔力仿生機人',unistr('協調+協調以外的怪獸1隻以上\u000a我方的結束階段時，我方的生命值回復場上表側表示存在的超能族怪獸數量×600。'),'回復LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43387895,'霸王眷龍 飢餓毒液',unistr('闇屬性靈擺怪獸×2\u000a此卡只能用融合召喚或以下方法特殊召喚。\u000a●將我方場上的上述卡解放，可以從額外牌組特殊召喚。\u000a①：1回合1次，以此卡以外的我方或對手的場上、墓地1隻怪獸為對象可以發動。此卡直到結束階段得到和那隻怪獸的原本的卡名、效果相同的卡名、效果。這個回合，我方怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'效果1','解除複製效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43405287,'D-鎖鏈',unistr('①：以我方場上1隻「D-HERO」怪獸為對象可以發動此卡。此卡當作攻擊力上升500的裝備卡給那隻我方怪獸裝備。\u000a②：裝備怪獸以戰鬥破壞對手怪獸送去墓地的場合發動。給予對手500傷害。'),'給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43411769,'守護龍 加爾米德',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：通常怪獸被送去我方墓地的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡在墓地存在的場合，從手牌將1隻龍族怪獸送去墓地可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43413875,'花札衛－芒上月－',unistr('此卡不能通常召喚。將「花札衛－芒上月－」以外的我方場上1隻等級8的「花札衛」怪獸解放可以特殊召喚。\u000a①：此卡特殊召喚成功的場合發動。我方從牌組抽1張卡，給雙方確認。那是「花札衛」怪獸的場合，可以將那隻怪獸特殊召喚。不是的場合，那張卡送去墓地。\u000a②：1回合1次，此卡戰鬥破壞對手怪獸時可以發動。我方從牌組抽1張卡。'),'抽1張卡並給雙方確認','是否特殊召喚抽到的怪獸？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43417563,'舞蹈的誘發','「舞蹈士兵」的降臨所必需。必須從我方的手牌、場上解放怪獸直到等級合計為6以上為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43422537,'二重召喚','①：這個回合，我方可以進行通常召喚最多2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43426903,'爬蟲妖 戈爾貢','此卡攻擊的傷害計算後，與此卡進行戰鬥的怪獸的攻擊力變成0，表示形式不能變更。','攻擊力變成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43434803,'過淺的墓穴','雙方玩家選擇各自的墓地的1隻怪獸，在各自的場上裡側守備表示覆蓋。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43436049,'廢品破壞者','①：此卡召喚成功的回合的我方主要階段，解放此卡可以發動。場上的表側表示怪獸的效果直到回合結束時無效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43450363,'R.B.終戰屹立',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方的牌組、額外牌組、墓地將同名卡不在我方場上存在的1隻「R.B.」怪獸特殊召喚。此卡的發動後，直到回合結束時我方除了攻擊力1500以下的機械族怪獸以外不能從額外牌組特殊召喚。\u000a②：對手發動以我方場上的「R.B.」怪獸為對象的魔法、陷阱、怪獸的效果時，將墓地的此卡除外可以發動。那個效果無效。'),'特殊召喚','效果無效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43452193,'異次元隧道鏡子門','以我方場上表側表示存在的「E.HERO」怪獸作為攻擊對象的對手怪獸的攻擊宣言時可以發動。對手的攻擊怪獸和成為攻擊對象的我方怪獸的控制權交換進行傷害計算。直到這個回合的結束階段時，得到控制權交換的怪獸的控制權。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43455065,'魔力之泉',unistr('「魔力之泉」在1回合只能發動1張。\u000a①：我方依照對手場上的表側表示的魔法、陷阱卡數量從牌組抽牌。那之後，從我方的手牌挑選我方場上的表側表示的魔法、陷阱卡數量的卡捨棄。此卡的發動後，直到下個對手回合結束時對手場上的魔法、陷阱卡不會被破壞，發動和效果不會被無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43464884,'妖海的巨魔歹徒',unistr('這個卡名的①②效果1回合各能使用1次，這些效果發動的整回合中，我方除了獸戰士族怪獸以外不能特殊召喚。\u000a①：此卡召喚、特殊召喚成功的場合，以我方墓地1隻獸戰士族怪獸為對象可以發動。此卡的屬性、等級直到回合結束時變成和那隻怪獸相同。\u000a②：我方主要階段可以發動。從手牌將1隻持有和此卡相同屬性、等級的獸戰士族怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43471513,'捲尺騎士',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，場上有機械族怪獸存在的場合可以發動。此卡守備表示特殊召喚。那之後，可以將此卡的等級變成和場上1隻機械族怪獸的等級、階級的數值相同。\u000a②：我方主要階段可以發動。從牌組將1隻機械族、地屬性怪獸送去墓地。那之後，此卡的攻擊力直到回合結束時上升送去墓地的怪獸的等級×100。'),'效果1','效果2','是否改變等級？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43476205,'升階魔法-革命之力',unistr('①：依照發動回合可以發動以下效果。\u000a●我方回合：以我方場上1隻「RR-」超量怪獸為對象可以發動。將1隻階級高1階的「RR-」怪獸重疊在作為對象的我方怪獸上方，當作超量召喚從額外牌組特殊召喚。\u000a●對手回合：以對手場上1隻沒有超量素材的超量怪獸為對象可以發動。得到那隻超量怪獸的控制權。那之後，將1隻階級高1階的「RR-」怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43487744,'白空洞','對手發動「黑洞」時可以發動。我方場上的怪獸不會被那張「黑洞」的效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43490025,'FNo.0 未來皇霍普-未來斬',unistr('「No.」怪獸以外的相同階級的超量怪獸×2\u000a規則上此卡的階級當作1。此卡也能重疊在我方場上的「希望皇霍普」怪獸或「FNo.0 未來皇霍普」上方來超量召喚。\u000a①：此卡的攻擊力上升雙方墓地的「No.」超量怪獸數量×500。\u000a②：此卡不會被戰鬥破壞。\u000a③：1回合1次，去除此卡的1個超量素材可以發動。這個回合，此卡在1次戰鬥階段中可以攻擊2次。'),'效果3','是否重疊在我方場上的超量怪獸上方超量召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43500484,'魔界的荊棘','棲息在魔界的有刺灌木，將硬闖的人牢牢纏住。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43502497,'靈擺魔女',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：此卡在靈擺區域存在的狀態，我方場上的表側表示的融合、同步、超量怪獸被戰鬥或對手的效果破壞的場合可以發動。從牌組將1隻原種族和其中1隻相同的靈擺怪獸表側加入額外牌組。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、靈擺召喚的場合，以我方的靈擺區域1張卡為對象可以發動。那張卡和此卡破壞，從牌組將1隻等級4以下的靈擺怪獸加入手牌。\u000a②：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','請選擇要加入額外牌組的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(43509019,'卡通防禦','①：對手怪獸向我方的等級4以下的卡通怪獸攻擊宣言時可以發動此效果。那隻對手怪獸的攻擊變成對我方的直接攻擊。','變成直接攻擊','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43513897,'巨蟹星聖 柳宿增三','此卡召喚、特殊召喚成功時，我方場上的全部「星聖」怪獸的攻擊力上升500。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43527730,'御巫的展翅水舞',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：裝備怪獸不會被效果破壞。\u000a②：我方主要階段可以發動。從手牌、牌組將和裝備怪獸原卡名不同的1隻「御巫」怪獸特殊召喚，此卡給那隻怪獸裝備。那之後，此卡裝備過的怪獸回到手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43528009,'星星金幣',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：選2張我方的手牌加入對手的手牌。那之後，我方從牌組抽2張卡。'),'請選擇加入對手的手牌的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43530283,'勇氣的沙漏','此卡召喚、反轉召喚成功時，此卡的原本的攻擊力、守備力直到下個我方回合結束時變成一半。在那之後，此卡的原本的攻擊力、守備力變成2倍。','攻守減半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43534808,'衍生物收集者',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在，衍生物特殊召喚的場合可以發動。此卡特殊召喚。\u000a②：此卡特殊召喚成功的場合發動。場上的衍生物全部破壞，此卡的攻擊力上升破壞的衍生物數量×400。\u000a③：只要此卡在怪獸區域存在，雙方不能將衍生物特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43543777,'伊奘波',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡召喚、反轉時，可以藉由捨棄1張手牌，將我方墓地的1隻靈魂怪獸加入手牌。'),'回到手牌','把自己墓地存在的1隻靈魂怪獸加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43573231,'幻蝶刺客 閃蝶','對手場上的怪獸表示形式變更時，選擇那1隻怪獸可以發動。選擇怪獸的攻擊力、守備力下降1000。這個效果1回合只能使用1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43575579,'餘暉',unistr('這個卡名的卡在決鬥中只能發動1張。\u000a①：從我方的手牌、牌組、墓地以及我方場上的表側表示的卡之中，將包含此卡的「餘暉」全部除外。那之後，從被除外的我方的卡之中選1張「餘暉」加入牌組。下個我方抽牌階段，通常抽牌的卡給雙方確認。那是「餘暉」的場合，給予對手4000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43577607,'龍星的氣脈',unistr('①：依照我方墓地的「龍星」怪獸的屬性種類的數量得到以下效果。\u000a●2種以上：我方場上的「龍星」怪獸的攻擊力上升500。\u000a●3種以上：我方場上的「龍星」怪獸被戰鬥、效果破壞的場合，可以將此卡送去墓地作為代替。\u000a●4種以上：對手不能覆蓋怪獸，對手場上的表側表示怪獸全部變成攻擊表示。\u000a●5種以上：將此卡送去墓地可以發動。場上的卡全部破壞。'),'●5種以上','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43580269,'無限真理','①：此卡戰鬥破壞對手怪獸送去墓地的場合發動。此卡的攻擊力上升700。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43582229,'冰結界的晶壁',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：此卡發動時，可以選擇我方墓地1隻等級4以下的「冰結界」怪獸為對象。那個場合，那隻怪獸特殊召喚。\u000a②：只要此卡在魔法與陷阱區域存在，且我方場上有3隻以上「冰結界」怪獸存在，我方場上的「冰結界」怪獸不受從額外牌組特殊召喚的對手怪獸發動的效果影響。'),'是否從墓地特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43583400,'反鋸齒星人',unistr('①：1回合1次，此卡和怪獸進行戰鬥的我方、對手的戰鬥階段可以發動。從手牌將1隻電子界族怪獸召喚。\u000a②：表側表示的此卡因對手的效果從場上離開的場合發動。我方從牌組抽1張卡。'),'怪獸召喚','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43586926,'多爾多拉',unistr('這個卡名的效果在決鬥中只能使用1次。\u000a①：場上的此卡被破壞送去墓地的回合的結束階段可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡的攻擊力、守備力變成1000。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43598843,'奇巧人偶-恐怖嬰兒',unistr('①：此卡召喚成功時，以「奇巧人偶-恐怖嬰兒」以外的我方墓地1隻「奇巧人偶」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a②：將墓地的此卡除外可以發動。這個回合，應對我方的「奇巧人偶」怪獸的效果的發動，對手不能發動魔法、陷阱、怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43618262,'初買','①：從對手牌組上方翻開5張卡，我方從其中選1張並宣言100的倍數（最多3000）。對手可以回復那個數值的生命值。回復的場合，我方失去那個數值的生命值，挑選的卡加入我方的手牌，剩下的卡以原本的順序回到牌組上方。沒有回復的場合，翻開的卡以原本的順序回到牌組上方。','是否回復生命值讓對手將卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43633088,'緊急顯形','①：以我方的墓地、除外狀態的1隻等級5以下的超能族怪獸為對象可以發動。那隻怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43641473,'善變的裁縫師','選擇給怪獸裝備的1張裝備卡，選擇其他的1隻作為正確對象的怪獸，轉移到那隻怪獸。','請選擇1張裝備卡','請選擇要轉移裝備的對象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43642620,'猛獁象殭屍',unistr('我方墓地沒有不死族怪獸存在的場合，此卡破壞。\u000a場上表側表示存在的此卡被破壞的場合，給予那時的控制者此卡的原攻擊力數值的傷害。'),'受到傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43644025,'幼繭復活','藉由解放我方場上表側表示存在的1隻「繭狀體」怪獸，從墓地選擇1隻那張卡記載的「新空間俠」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43658697,'U.A. 王牌轉隊',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻「U.A.」怪獸特殊召喚。此效果特殊召喚的怪獸不能作為同步、超量召喚的素材，效果無效化。那之後，我方失去那隻怪獸的等級×300生命值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43661068,'向星星許願','選擇我方場上表側表示存在的1隻怪獸可以發動。我方場上的持有和選擇怪獸相同攻擊力或相同守備力的怪獸的等級，直到回合結束時變成和選擇的怪獸相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43664494,'調皮小子搗亂記',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌捨棄1張「調皮小子」卡片可以發動。在我方場上將1隻「調皮小子衍生物」（炎族、炎、等級1、攻/守0）特殊召喚。這個衍生物不能解放。\u000a②：我方結束階段，以「調皮小子搗亂記」以外的我方墓地3張「調皮小子」卡片為對象可以發動。那3張卡加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43664495,'調皮小子衍生物','由「調皮小子搗亂記」的效果特殊召喚。這個衍生物不能解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43685562,'淨龐克 危險口裂',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。我方場上有「龐克」怪獸存在的場合，隨後我方的生命值回復對象怪獸的原攻擊力數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43694075,'法律的祈禱','「法律守護者」的降臨所必需。必須從我方的手牌、場上解放怪獸直到等級合計為7以上為止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43694481,'暴風雪獵鷹','此卡的攻擊力高於原攻擊力的場合可以發動。給予對手1500傷害。這個效果於此卡在場上表側表示存在期間只能使用1次，「暴風雪獵鷹」的效果1回合只能使用1次。','給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43694650,'未界域的加卡洛普',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。對手從我方的全部手牌中隨機選1張，我方捨棄那張卡。那是「未界域的加卡洛普」以外的場合，隨後從手牌將1隻「未界域的加卡洛普」特殊召喚，我方從牌組抽1張卡。\u000a②：此卡從手牌捨棄的場合可以發動。從牌組將「未界域的加卡洛普」以外的1隻「未界域」怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43697559,'噴射機人','此卡被選擇成為對手怪獸的攻擊對象時，此卡的控制者可以從手牌發動陷阱卡。','適用「噴射機人」的效果來發動','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43698897,'魔玩具工廠',unistr('「魔玩具工廠」的①②效果1回合各能使用1次。\u000a①：從我方墓地將1張「融合」魔法卡或「結合」魔法卡除外可以發動此效果。從我方的手牌、場上將「魔玩具」融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a②：此卡被送去墓地的場合，以被除外的1張我方的「魔玩具結合」為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43708041,'陽炎光輪',unistr('只要此卡在場上存在，我方將「陽炎獸」怪獸召喚的場合需要的解放可以減少1隻。\u000a此外，可以藉由將場上表側表示存在的此卡送去墓地，從我方墓地選擇「陽炎光輪」以外的1張「陽炎」卡片加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43708640,'牛馬薩梯神',unistr('此卡不能特殊召喚。\u000a藉由將此卡解放，從我方牌組將2隻獸戰士族、等級4通常怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43709490,'實驗體突變魔 GB-88',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的場地區域有「突變魔進化研究所」存在的場合，對手主要階段可以發動。此卡從手牌特殊召喚。\u000a②：對手回合，此卡特殊召喚成功的場合，將此卡解放，將1張手牌或我方場上的表側表示的卡除外可以發動。從我方墓地的怪獸以及被除外的我方怪獸之中，選1隻等級8的「突變魔」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43711255,'禁止令',unistr('宣言1個卡名可以發動此卡。\u000a①：只要此卡在魔法與陷阱區域存在，雙方的原卡名是宣言的卡名的卡適用以下效果（這個效果適用前已經在場上存在的卡不適用）。\u000a●不能出到場上。\u000a●不能進行卡片的發動以及效果的發動和適用。\u000a●不能通常召喚、反轉召喚、特殊召喚。\u000a●不能攻擊或變更表示形式。\u000a●不能作為需要素材的特殊召喚使用的素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43714890,'投人的巨魔','藉由解放我方場上1隻通常怪獸（衍生物以外），給予對手800傷害。','給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43716289,'劇毒木乃伊','反轉：給予對手500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43722862,'WW-冰鈴',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上沒有怪獸存在的場合可以發動。此卡從手牌特殊召喚。那之後，可以從牌組將1隻「WW-」怪獸特殊召喚。此效果從牌組特殊召喚的怪獸不能解放，此效果發動的整回合中，我方除了等級5以上的風屬性怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。給予對手500傷害。'),'效果1','是否從牌組特殊召喚1隻「WW-」怪獸？','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43730887,'拘束臂',unistr('①：此卡召喚、特殊召喚成功的場合，以對手場上1隻表側表示怪獸為對象發動。這隻怪獸表側表示存在期間，作為對象的表側表示怪獸不能攻擊，效果無效化。\u000a②：只要此卡的①效果的對象怪獸在場上存在，此卡不會被戰鬥、效果破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43735670,'海晶少女 藍蛞蝓',unistr('等級4以下的「海晶少女」怪獸1隻\u000a我方1回合只能連結召喚1次「海晶少女 藍蛞蝓」。\u000a①：此卡連結召喚成功的場合，以「海晶少女 藍蛞蝓」以外的我方墓地1隻「海晶少女」怪獸為對象可以發動。那隻怪獸加入手牌。此效果的發動後，直到回合結束時我方除了水屬性怪獸以外不能特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43739056,'天孔邪鬼',unistr('①：只要此卡在怪獸區域存在，除了此卡以外，我方不能發動和此卡屬性相同的特殊召喚的怪獸的效果。\u000a②：1回合1次，我方、對手的主要階段可以發動。此卡的控制權轉移給對手。那之後，可以將此卡的屬性直到下個回合結束時變成任意屬性。此效果只能在此卡的原持有者的回合發動。'),'是否改變屬性？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43748308,'微炎星-龍進',unistr('1回合1次，我方發動「炎舞」魔法、陷阱卡的場合，可以從牌組選1張「炎舞」陷阱卡在我方場上覆蓋。\u000a此外，1回合1次，將我方場上表側表示存在2張「炎舞」魔法、陷阱卡送去墓地可以發動。從我方墓地選擇「微炎星-龍進」以外的1隻「炎星」怪獸特殊召喚。'),'覆蓋','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43751755,'繭狀體 小黑豹','場上有「新宇空間」存在時，藉由解放此卡，從手牌或牌組將1隻「新空間俠 漆黑獵豹」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43785278,'傅科魔砲石',unistr('【靈擺效果】\u000a①：此卡發動的回合的結束階段，以場上1張表側表示的魔法、陷阱卡為對象可以發動。那張卡破壞。\u000a【怪獸敘述】\u000a是徬徨於幻想空間的機關生命體，本應是如此。最大的謎團是，過去的記錄卻幾乎...留下來。那理由...呢，....干涉...它在...拒..？...消去...'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43791861,'鳳王獸 蓋爾達','此卡向對手怪獸攻擊的場合，傷害步驟期間攻擊力上升300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43793530,'巨大咖咖吉哥','為了面對強大的邪惡，進行了各式肉體改造從而得到了可怕的能力，而作為代價失去了正義的心。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43797906,'亞特蘭提斯的戰士','①：將此卡從手牌捨棄到墓地可以發動。從牌組將1張「傳說之都 亞特蘭提斯」加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43803845,'假威鴨',unistr('①：只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a②：可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●此卡不會成為效果的對象，不會被效果破壞。\u000a●只要此卡在怪獸區域存在，對手怪獸的攻擊全部變成直接攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43813459,'反射光子流','我方場上的龍族、光屬性怪獸被選擇作為攻擊對象時可以發動。那隻攻擊對象怪獸的攻擊力直到傷害步驟結束時上升攻擊怪獸的攻擊力數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43834302,'同步同伴',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將以下怪獸各1隻加入手牌。那之後，選1張我方的手牌捨棄。\u000a●「廢品同步者」\u000a●記載「廢品戰士」「星塵龍」其中任何卡名的怪獸\u000a②：將墓地的此卡除外，以我方場上1隻同步怪獸為對象可以發動。那隻怪獸的等級下降1。那之後在這個回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻「同步者」怪獸。'),'效果1','效果2','召喚（同步同伴）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43839002,'電腦網後門',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻電子界族怪獸為對象可以發動。那隻怪獸除外，從牌組將1隻攻擊力低於那隻怪獸的原攻擊力的電子界族怪獸加入手牌。此效果除外的怪獸在下個我方準備階段回到場上，在那個回合可以直接攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43841694,'魔導書的奇蹟','選擇我方墓地的1隻魔法使族超量怪獸和被除外的最多2張我方的「魔導書」魔法卡可以發動。選擇的怪獸特殊召喚，選擇的「魔導書」魔法卡重疊在那隻怪獸下方作為超量素材。「魔導書的奇蹟」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43845801,'究極爆風彈','①：以我方場上1隻融合召喚的「青眼究極龍」為對象可以發動。這個回合，那隻怪獸在1次戰鬥階段中可以攻擊3次，那隻怪獸攻擊的場合，直到傷害步驟結束時對手不能發動魔法、陷阱、怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43857222,'天秤座的魔法秤',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：宣言1～6的任意等級，以我方場上2隻表側表示怪獸為對象可以發動。直到回合結束時，作為對象的1隻怪獸的等級下降宣言的等級數值，另1隻怪獸的等級上升宣言的等級數值。\u000a【怪獸敘述】\u000a擁有意識的天秤，雖然保持世界上的均衡，但是每次都會放錯用來秤重的星星。'),'改變等級','請選擇等級下降的怪獸','請選擇等級上升的怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43863925,'驅魔修女 斯特拉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將1隻「驅魔修女」怪獸特殊召喚。那之後，我方場上有「驅魔修女 埃莉絲」存在的場合，我方回復800生命值。\u000a②：對手讓我方或對手的卡從墓地離開的場合可以發動。將1隻「驅魔修女」超量怪獸重疊在我方場上的此卡上方當作超量召喚從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43871165,'獄神影機-宙格黎多',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方主要階段可以發動。此卡和我方的手牌、場上（表側表示）1隻「獄神」怪獸或「終刻」怪獸破壞。那之後，可以將場上1張卡破壞。\u000a【怪獸效果】\u000a這個卡名在規則上也當作「終刻」卡片。這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：從牌組上方將3張卡裡側除外可以發動。此卡破壞，從額外牌組將1隻「壞獄神 朱庇特」當作超量召喚特殊召喚。那之後，可以選1張我方的手牌作為那個超量素材。\u000a②：此卡表側加入額外牌組的場合可以發動。從牌組將1張「獄神」魔法、陷阱卡或「終刻」魔法、陷阱卡加入手牌。'),'靈擺效果1','效果1','效果2','是否破壞？','是否將手牌作為超量素材？','','','','','','','','','','','');
INSERT INTO texts VALUES(43886072,'調皮小子 汪汪狗',unistr('「調皮小子」怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡指向的「調皮小子」怪獸的攻擊力上升1000。\u000a②：對手回合解放此卡，以連結怪獸以外的我方墓地2張「調皮小子」卡片為對象可以發動（同名卡最多1張）。那些卡加入手牌。此外，這個回合我方場上的「調皮小子」怪獸不會被對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43889633,'忘卻的海底神殿',unistr('只要此卡在場上存在，此卡的卡名當作「海」。\u000a1回合1次，可以選擇我方場上1隻等級4以下的魚族、海龍族、水族怪獸除外。\u000a我方的結束階段，此效果除外的怪獸特殊召喚。'),'N/A','除外','特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43892408,'龍騎士 黑魔導女孩',unistr('「黑魔導女孩」+龍族怪獸\u000a此卡只能用以上述卡為融合素材的融合召喚或「迪馬歐斯之眼」的效果特殊召喚。\u000a①：我方、對手回合1次，將1張手牌送去墓地，以場上1張表側表示卡為對象可以發動。那張表側表示卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43892409,'龍騎士 黑魔導女孩',unistr('「黑魔導女孩」+龍族怪獸\u000a此卡只能用以上述卡為融合素材的融合召喚或「迪馬歐斯之眼」的效果特殊召喚。\u000a①：我方、對手回合1次，將1張手牌送去墓地，以場上1張表側表示卡為對象可以發動。那張表側表示卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43898403,'雙龍捲','①：捨棄1張手牌，以場上最多2張魔法、陷阱卡為對象可以發動。那些卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43904702,'殺手旋律 酷莉普',unistr('場上的此卡作為素材同步召喚的場合，手牌的1隻協調也能作為同步素材。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，對手主要階段可以發動。此卡特殊召喚。那之後，可以進行1隻同步怪獸協調的同步召喚。\u000a②：此卡作為同步素材送去墓地的場合可以發動。對手的額外牌組的裡側的卡隨機選1張除外。'),'效果1','效果2','是否進行同步召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43905751,'魔人銃','從口中發射子彈攻擊的生物兵器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43906884,'BF-地雷','覆蓋的此卡被對手的效果破壞時，我方場上有「BF」怪獸表側表示存在的場合，給予對手1000傷害，我方從牌組抽1張卡。','給予1000傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43912676,'異層空間',unistr('①：場上的幻龍族怪獸的攻擊力、守備力上升300。\u000a②：1回合1次，將我方墓地的3隻幻龍族怪獸除外，以場上的1張卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43925870,'風廠次世代',unistr('「次世代控制者」+協調以外的風屬性怪獸1隻以上\u000a①：此卡的攻擊力上升場上的裡側表示的魔法、陷阱卡數量×300。\u000a②：將1張手牌送去墓地，以場上1張裡側表示的魔法、陷阱卡為對象可以發動。那張裡側表示卡破壞。'),'破壞裡側表示卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43930492,'吸收魔術師',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a②：此卡的等級上升此卡的魔力計數器的數量。\u000a③：去除此卡的3個魔力計數器，以我方墓地1張速攻魔法卡為對象可以發動。那張卡在我方的魔法與陷阱區域覆蓋。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43932352,'百臂無形引導手',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：將我方場上的1隻「百臂無形」怪獸或原持有者是對手的怪獸解放可以發動。得到對手場上1隻怪獸的控制權。\u000a②：我方結束階段發動。我方場上1張卡送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43932460,'大植然玄武',unistr('地屬性協調+協調以外的地屬性怪獸1隻以上\u000a只要此卡在場上表側表示存在，可以藉由將手牌的1張魔法卡送去墓地，將怪獸的效果發動無效並破壞。'),'效果怪獸的效果發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43940008,'決鬥塔 阿爾卡特拉斯',unistr('①：我方、對手的戰鬥階段開始時發動。雙方各自可以從自身牌組挑選1隻攻擊力?以外的怪獸。挑選的怪獸給雙方確認，裡側表示除外。挑選攻擊力最高的怪獸的玩家可以從手牌將1隻怪獸特殊召喚。此效果特殊召喚的怪獸可以直接攻擊。\u000a②：我方、對手的結束階段可以發動。下個我方回合的結束階段此卡在場上存在的場合，場上的卡全部破壞。'),'效果1','效果2','是否從手牌特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43944080,'妮夢雷莉婭的守夢者-庫艾特',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方的額外牌組有表側表示的靈擺怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：我方的額外牌組有表側表示的「眠夢中的妮夢雷莉婭」存在，對手發動以我方場上的「妮夢雷莉婭」卡片為對象的效果時，從額外牌組將1張裡側表示的卡裡側表示除外可以發動。那個發動無效。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43959432,'變形黏土要塞',unistr('①：以我方場上1隻等級4以上的怪獸為對象可以發動。此卡發動後變成效果怪獸（岩石族、地、等級4、攻/守1000）在怪獸區域特殊召喚。那之後，對象的表側表示怪獸當作裝備卡給此卡裝備。此卡也當作陷阱卡。\u000a②：此卡的效果特殊召喚的此卡的攻擊力、守備力上升用此卡的效果裝備的怪獸的攻擊力數值，此卡在攻擊過的傷害步驟結束時變成守備表示。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43973174,'喚龍笛','①：從手牌將最多2隻龍族怪獸特殊召喚。此效果在場上有「龍之主宰-龍的支配者」存在的場合可以發動和處理。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43986064,'巨星墜落',unistr('應對此卡的發動，不能發動不持有等級的怪獸的效果。\u000a①：以場上1隻不持有等級的表側表示怪獸為對象可以發動。直到回合結束時，那隻表側表示怪獸的攻擊力變成0，不能發動效果，不會被戰鬥破壞。這個回合，那隻表側表示怪獸的戰鬥產生給雙方的戰鬥傷害變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43989315,'召喚獸 索拉特',unistr('「阿萊斯特」怪獸+炎、風屬性怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，以我方或對手的墓地1隻等級6以下的怪獸為對象可以發動。那隻怪獸在我方場上守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。\u000a②：此卡在墓地存在的場合可以發動。包含墓地的此卡的我方的場上、墓地的怪獸作為融合素材除外，將1隻「召喚獸」融合怪獸融合召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43994202,'迅疾三分利',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的怪獸只有衍生物以外的同名怪獸3隻的場合可以發動。從牌組將3隻同名怪獸加入手牌。此卡的發動後，直到回合結束時我方不能將此效果加入手牌的怪獸以及那些同名怪獸通常召喚、特殊召喚，那些怪獸不能發動效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44001993,'黑色混沌的魔術師 黑混沌',unistr('藉由「光與闇的儀式」降臨\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從我方墓地將1張魔法卡加入手牌。\u000a②：只要此卡在怪獸區域存在，我方場上的魔法、陷阱卡不會被對手的效果破壞，不能被對手的效果除外，除了以此卡為對象的效果以外，此卡不受對手發動的效果影響。\u000a③：以對手場上1張卡為對象可以發動。那張卡裡側除外。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44001994,'黑色混沌的魔術師 黑混沌',unistr('藉由「光與闇的儀式」降臨\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從我方墓地將1張魔法卡加入手牌。\u000a②：只要此卡在怪獸區域存在，我方場上的魔法、陷阱卡不會被對手的效果破壞，不能被對手的效果除外，除了以此卡為對象的效果以外，此卡不受對手發動的效果影響。\u000a③：以對手場上1張卡為對象可以發動。那張卡裡側除外。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44009443,'影星軌道兵器 著陸九頭蛇',unistr('此卡不能通常召喚。只能在我方墓地有5隻以上怪獸存在，且那些怪獸的卡名全部不同的場合特殊召喚。\u000a①：1回合1次，從我方牌組上方將3張卡送去墓地可以發動。我方墓地的怪獸的卡名全部不同的場合，選場上1張卡破壞。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44026393,'幻獸機 雷電貂',unistr('①：捨棄1張手牌可以發動。在我方場上將1隻「幻獸機衍生物」（機械族、風、等級3、攻/守0）特殊召喚。此效果的發動後，直到回合結束時我方只能用「幻獸機」怪獸作為融合、同步、超量、連結召喚的素材。\u000a②：此卡的等級上升我方場上的「幻獸機衍生物」的等級的合計數值。\u000a③：只要我方場上有衍生物存在，此卡不會被戰鬥、效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44026394,'幻獸機衍生物','由「幻獸機」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44028461,'黑色回歸','我方回合可以發動。選擇我方墓地1隻攻擊力2000以下的「BF」怪獸特殊召喚。此卡發動的整回合中，我方不能將怪獸通常召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44035031,'重力戰士',unistr('協調+協調以外的怪獸1隻以上\u000a此卡同步召喚成功時，此卡的攻擊力上升對手場上表側表示存在的怪獸數量×300。\u000a1回合1次，在對手的戰鬥階段時選擇對手場上守備表示存在的1隻怪獸可以發動。選擇的怪獸變成表側攻擊表示。這個回合那隻怪獸可以攻擊的場合必須攻擊。'),'攻擊力上升','改變表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44046281,'次元之門',unistr('此卡發動時，選擇我方場上的1隻怪獸，以表側表示除外。\u000a此外，對手怪獸的直接攻擊宣言時，可以將場上表側表示存在的此卡送去墓地。\u000a此卡被送去墓地的場合，可以將此卡的效果除外的怪獸特殊召喚。'),'送去墓地','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44052074,'古代機械齒輪射出機',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上沒有怪獸存在的場合，以我方場上1張表側表示卡為對象可以發動。那張卡破壞，從牌組將1隻「古代機械齒輪」怪獸無視召喚條件特殊召喚。\u000a②：將墓地的此卡除外，以我方場上1張表側表示卡為對象可以發動。那張卡破壞，在我方場上將1隻「古代機械齒輪衍生物」（機械族、地、等級1、攻/守0）特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44052075,'古代機械齒輪衍生物','由「古代機械齒輪射出機」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44072894,'物資調達員','反轉：可以選擇2隻用「融合」送去我方墓地的融合素材怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44073668,'水魚鰭龍','身上長有鰭，在水中自由活動的海龍的伙伴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44088292,'進化合獸 二氧鬼神',unistr('①：只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a②：可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●只要此卡在怪獸區域存在，二重怪獸的召喚不會被無效化。\u000a●1回合1次，將我方墓地1隻二重怪獸除外，以對手場上1張卡為對象可以發動。那張卡破壞。'),'破壞對手場上的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44092304,'夢迷枕 異睡貘',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手結束階段可以發動。裝備怪獸破壞。\u000a②：裝備怪獸被破壞送去墓地讓此卡被送去墓地的場合可以發動。將1隻持有此卡裝備過的怪獸的原本的種族、屬性、攻擊力的「異睡衍生物」（等級1、攻?/守0）在我方場上特殊召喚。那之後，此卡給那個衍生物裝備。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44092305,'異睡衍生物','由「夢迷枕 異睡貘」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44094981,'地縛戒隸 地畫獅鷲',unistr('闇屬性協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合可以發動。從我方墓地將「地縛戒隸 地畫獅鷲」以外的1隻「地縛」怪獸守備表示特殊召喚。這個回合，我方除了融合、同步怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡被對手破壞的場合可以發動。場上1張卡破壞。那之後，給予對手相當於我方的場上、墓地的「地縛」怪獸種類×300傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44095762,'神聖防護罩 －反射鏡力－','①：對手怪獸的攻擊宣言時可以發動。對手場上的攻擊表示怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44097050,'幻獸機 曙光女神百頭龍',unistr('機械族怪獸2隻以上\u000a①：此卡連結召喚成功的場合可以發動。在我方場上將3隻「幻獸機衍生物」（機械族、風、等級3、攻/守0）特殊召喚。這個回合，我方不能連結召喚。\u000a②：1回合1次，將我方場上最多3隻怪獸解放可以發動。依照解放的怪獸數量適用以下效果。\u000a●1隻：選場上1張卡破壞。\u000a●2隻：從牌組將1隻「幻獸機」怪獸特殊召喚。\u000a●3隻：從我方墓地選1張陷阱卡加入手牌。'),'效果1','效果2','●1隻：選場上1張卡破壞','●2隻：從牌組把1隻「幻獸機」怪獸特殊召喚','●3隻：從我方墓地選1張陷阱卡加入手牌','','','','','','','','','','','');
INSERT INTO texts VALUES(44097051,'幻獸機衍生物','由「幻獸機」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44125452,'薔薇的妖精','此卡因魔法、陷阱、效果怪獸的效果從我方牌組加入手牌的場合，此卡可以在我方場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44133040,'塞勒涅的咒眼',unistr('只能給「咒眼」怪獸裝備。這個卡名的③效果1回合只能使用1次。\u000a①：裝備怪獸不會被戰鬥以及對手的效果破壞，不會成為對手的效果的對象。\u000a②：每次我方發動裝備怪獸的效果或此卡以外的「咒眼」魔法、陷阱卡就發動。裝備怪獸的攻擊力上升500，我方失去500生命值。\u000a③：支付1000生命值，從我方墓地將「塞勒涅的咒眼」以外的1張「咒眼」魔法、陷阱卡除外可以發動。墓地的此卡在我方場上覆蓋。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44139064,'巨型機人都市',unistr('這個卡名的①②效果1回合各能使用1次，這些效果發動的整回合中，我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a①：以此卡以外的我方場上1張卡為對象可以發動。那張卡破壞，從牌組將1張「機人」卡片加入手牌。\u000a②：我方的「機人」怪獸進行戰鬥的傷害計算時，從牌組將1隻「機人」怪獸送去墓地可以發動。那隻進行戰鬥的我方怪獸只在那次傷害計算時原攻擊力和原守備力交換。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44146295,'冰劍龍 幻冰',unistr('「阿不思的落胤」+融合、同步、超量、連結怪獸\u000a①：「冰劍龍 幻冰」在我方場上只能有1張表側表示存在。\u000a②：我方、對手回合1次，從額外牌組將1隻需以「阿不思的落胤」為融合素材的融合怪獸送去墓地可以發動。場上1隻怪獸除外。下個回合，此卡不能使用這個效果。\u000a③：融合召喚的此卡因對手從場上離開的場合可以發動。這個回合的結束階段，對手場上的怪獸全部破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44146296,'冰劍龍 幻冰',unistr('「阿不思的落胤」+融合、同步、超量、連結怪獸\u000a①：「冰劍龍 幻冰」在我方場上只能有1張表側表示存在。\u000a②：我方、對手回合1次，從額外牌組將1隻需以「阿不思的落胤」為融合素材的融合怪獸送去墓地可以發動。場上1隻怪獸除外。下個回合，此卡不能使用這個效果。\u000a③：融合召喚的此卡因對手從場上離開的場合可以發動。這個回合的結束階段，對手場上的怪獸全部破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44155002,'魔轟神獸 獨角獸',unistr('「魔轟神」協調+協調以外的怪獸1隻以上\u000a①：只要此卡在怪獸區域存在，且雙方的手牌張數相同，對手發動的魔法、陷阱、怪獸的效果無效化並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44161893,'轉生炎獸 雜交斑馬機人X',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在墓地存在，我方的「轉生炎獸」連結怪獸因對手的效果從場上離開的場合可以發動。從我方墓地選包含此卡的2隻等級4「轉生炎獸」怪獸效果無效特殊召喚，只用那2隻為素材將1隻「轉生炎獸」怪獸超量召喚。\u000a②：用場上的此卡為素材超量召喚的怪獸得到以下效果。\u000a●此卡的攻擊力上升此卡的超量素材數量×300。'),'效果1','「轉生炎獸 雜交斑馬機人X」的效果2適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44163252,'華爾裘蓮 六女',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從牌組將「華爾裘蓮 六女」以外的1隻「華爾裘蓮」怪獸特殊召喚。\u000a②：我方主要階段可以發動。從對手牌組上方將2張卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44175358,'分裂的渦蟲',unistr('這個卡名的效果1回合只能使用1次。\u000a①：將場上的此卡除外可以發動。從牌組將2隻同名的昆蟲族、等級3怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化，在結束階段除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44178886,'光道武僧 艾琳',unistr('①：此卡向守備表示怪獸攻擊的傷害計算前發動。那隻怪獸回到持有者的牌組。\u000a②：我方結束階段發動。從我方牌組上方將3張卡送去墓地。'),'回到牌組','牌組3張卡送入墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44179224,'魔界劇團 啟幕人',unistr('【靈擺效果】\u000a這個卡名的靈擺效果在決鬥中只能使用1次。\u000a①：我方場上沒有怪獸存在的場合可以發動。靈擺區域的此卡特殊召喚。\u000a【怪獸效果】\u000a①：我方場上沒有此卡以外的怪獸存在的場合，此卡的攻擊力上升1100。\u000a②：1回合1次，從牌組將1張「魔界台本」魔法卡送去墓地可以發動。從我方的額外牌組將1隻表側表示的「魔界劇團」靈擺怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44182827,'輪迴轉生','儀式召喚解放的怪獸不去墓地而是回到持有者的牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44186624,'DDD制霸王 皇帝',unistr('①：此卡靈擺召喚成功的場合發動。對手場上的表側表示的卡的效果直到回合結束時無效。\u000a②：此卡靈擺召喚成功的回合的主要階段1次，以我方的魔法與陷阱區域最多2張卡為對象可以發動。那些卡破壞。這個回合，除了通常攻擊以外，此卡在1次戰鬥階段中可以攻擊的次數為此效果破壞的卡片數量。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44190146,'德梅特爺爺',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：去除我方的「珂瓏公主」的1個超量素材可以發動。從我方墓地選最多2隻攻擊力或守備力是0的通常怪獸，當作闇屬性、等級8怪獸守備表示特殊召喚。\u000a②：我方的超量怪獸去除作為超量素材的通常怪獸來發動效果的場合，以那1隻超量怪獸和對手場上1隻怪獸為對象可以發動。那隻對手怪獸破壞，給予對手作為對象的超量怪獸的階級×300傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44201739,'米樂與燐寸之仔',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合可以發動。從手牌、牌組向對手展示3張同名卡在對手墓地存在的卡（同名卡最多1張），此卡特殊召喚。\u000a②：對手發動魔法、陷阱、怪獸的效果時，將此卡的①效果特殊召喚的此卡送去墓地可以發動。從牌組、額外牌組將1張對手發動的那張卡的同名卡送去墓地，那個發動無效。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44203504,'機械軍曹','侍從機械王的機械族的司令官。統率機械部隊的攻擊性用兵而很有名。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44209392,'城壁','選擇場上1隻表側表示怪獸可以發動。那隻怪獸的守備力直到回合結束時上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44221928,'褒譽的吹息',unistr('風屬性的儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計和儀式召喚的怪獸相同為止，從手牌儀式召喚1隻風屬性的儀式怪獸。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44223284,'深海王 魔鬼鯊','此卡1回合只有1次不會被非指定對象的效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44227727,'海造賊-進水式',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：從我方的手牌、場上將惡魔族融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a②：將墓地的此卡除外，以我方場上1隻「海造賊」怪獸為對象可以發動。那隻我方怪獸從牌組將1張「海造賊-象徵」裝備或從牌組將1隻「海造賊」怪獸當作裝備卡裝備。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44236692,'死靈連接者','將此卡解放，選擇我方墓地的1隻「同步者」協調可以發動。選擇的怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能作為同步素材。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44241999,'哥布林百鬼羅剎 格里亞雷三傑',unistr('等級3怪獸×2隻以上\u000a①：場上的超量素材是3個以上的場合，我方的「哥布林」怪獸可以直接攻擊。\u000a②：1回合1次，此卡在怪獸區域存在的狀態，怪獸召喚、特殊召喚的場合，以其中1隻為對象可以發動。去除場上的1個超量素材，對象怪獸的表示形式變更。\u000a③：1回合1次，對手怪獸的攻擊宣言時可以發動。去除場上的1個超量素材，那次攻擊無效。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44250812,'我我我書記','①：我方場上有「我我我書記」以外的「我我我」怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44256816,'獨奏第一樂章',unistr('「獨奏第一樂章」在1回合只能發動1張，此卡發動的整回合中，我方除了「幻奏」怪獸以外不能特殊召喚。\u000a①：我方場上沒有怪獸存在的場合可以發動。從手牌、牌組將1隻等級4以下的「幻奏」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44265115,'大腦控制者',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「洗腦-精神控制」加入手牌。\u000a②：我方支付生命值的場合，以場上1隻表側表示怪獸為對象，宣言1～8的任意等級可以發動。那隻怪獸的等級變成宣言的等級。\u000a③：此卡作為同步素材送去墓地的場合可以發動。此卡效果無效在對手場上守備表示特殊召喚。'),'效果1','','','請選擇要改變的等級','','','','','','','','','','','','');
INSERT INTO texts VALUES(44273680,'光天使 書','1回合1次，將手牌的1張魔法卡送去墓地可以發動。從手牌將1隻「光天使」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44287299,'傳說的劍豪 MASAKI','據說是完成了百人斬的傳說中的劍豪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44293356,'巨石遺物 阿特拉普爾隆',unistr('藉由「巨石遺物」卡片降臨\u000a此卡只能用只使用儀式怪獸的儀式召喚來特殊召喚。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡可以發動。這個回合，應對我方的「巨石遺物」儀式怪獸的效果的發動，對手不能發動效果。\u000a②：對手發動卡的效果時可以發動。那個發動無效並破壞。此效果將以場上的卡為對象的效果的發動無效的場合，隨後可以將對手場上1隻怪獸解放。'),'效果1','效果2','是否將1隻怪獸解放？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44297127,'奇蹟的穿孔',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻等級4以下的岩石族怪獸送去墓地。我方墓地有「化石融合-化石結合」存在的場合，隨後我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44308317,'冰結界的依巫',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上有「冰結界」怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：只要我方場上有其他的「冰結界」怪獸存在，對手場上的守備表示怪獸不能變更表示形式。\u000a③：我方場上有「冰結界」怪獸存在的場合，將墓地的此卡除外可以發動。在我方場上將1隻「冰結界衍生物」（水族、水、等級1、攻/守0）特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44308318,'冰結界衍生物','由「冰結界的依巫」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44311445,'魔法甜點 布丁公主 巧克力風味',unistr('地屬性等級5怪獸×2\u000a此卡也能重疊在我方場上的階級4以下的「魔法甜點」超量怪獸上方來超量召喚。\u000a①：1回合1次，以我方墓地1張「魔法甜點」卡片為對象可以發動。那張卡回到牌組。\u000a②：此卡有「魔法甜點 布丁公主」作為超量素材的狀態，我方墓地的「魔法甜點」卡片回到牌組時，去除此卡的1個超量素材可以發動。從牌組將1隻「魔法甜點」怪獸以表側攻擊表示或裡側守備表示特殊召喚。'),'是否重疊在「魔法甜點」超量怪獸上超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44330098,'冥府的使者格斯',unistr('我方場上沒有卡存在的場合，因對手控制的卡受到傷害時，可以將此卡從手牌特殊召喚。\u000a這個方法特殊召喚成功時，依照受到傷害的種類發動以下效果。\u000a●戰鬥傷害的場合，在我方場上將1隻「冥府的使者凱茵衍生物」（天使族、光、等級7、攻/守?）特殊召喚。這個衍生物的攻擊力、守備力變成和這時受到的戰鬥傷害相同的數值。\u000a●卡的效果傷害的場合，給予對手和受到的傷害相同數值的傷害。'),'從手牌特殊召喚','特殊召喚衍生物','給予傷害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44330099,'冥府的使者凱茵衍生物','由「冥府的使者格斯」的效果特殊召喚。這個衍生物的攻擊力、守備力變成和特殊召喚時受到的戰鬥傷害相同的數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44330100,'冥府的使者格斯',unistr('我方場上沒有卡存在的場合，因對手控制的卡受到傷害時，可以將此卡從手牌特殊召喚。\u000a這個方法特殊召喚成功時，依照受到傷害的種類發動以下效果。\u000a●戰鬥傷害的場合，在我方場上將1隻「冥府的使者凱茵衍生物」（天使族、光、等級7、攻/守?）特殊召喚。這個衍生物的攻擊力、守備力變成和這時受到的戰鬥傷害相同的數值。\u000a●卡的效果傷害的場合，給予對手和受到的傷害相同數值的傷害。'),'從手牌特殊召喚','特殊召喚衍生物','給予傷害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44335251,'食魂竊蛋龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組選1隻恐龍族怪獸加入手牌或送去墓地。\u000a②：以此卡以外的場上1隻等級4以下的恐龍族怪獸為對象可以發動。那隻怪獸破壞。那之後，從我方墓地選1隻恐龍族怪獸守備表示特殊召喚。'),'效果1','效果2','請選擇要加入手牌或送去墓地的卡','是否加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(44341034,'黑暗異蟲','此卡召喚成功時，選擇我方墓地存在1隻等級3的協調怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸的效果無效化。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44352516,'電子黑暗業火',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的已裝備裝備卡的「電子暗黑」效果怪獸不會成為對手的效果的對象，不會被對手的效果破壞。\u000a②：以我方場上1隻「電子暗黑」怪獸為對象可以發動。那隻怪獸回到持有者的手牌，那之後可以將1隻「電子暗黑」怪獸召喚。\u000a③：場上的此卡被對手的效果破壞的場合可以發動。從牌組將1張「融合」魔法卡或「結合」魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44362883,'烙印融合',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a①：我方的手牌、牌組、場上的2隻怪獸作為融合素材，將1隻需以「阿不思的落胤」為融合素材的融合怪獸融合召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44364077,'娛樂夥伴 士兵虎',unistr('「娛樂夥伴 士兵虎」的效果1回合只能使用1次。\u000a①：此卡戰鬥破壞對手怪獸送去墓地時可以發動。從牌組將1隻「娛樂夥伴」靈擺怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44364207,'翡翠騎士',unistr('只要此卡在場上表側攻擊表示存在，我方場上的攻擊力1200以下的機械族怪獸不會被陷阱卡的效果破壞。\u000a場上表側表示存在的此卡被戰鬥破壞送去墓地時，可以從牌組將1隻機械族、光屬性、等級4的怪獸加入手牌。'),'從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44373896,'破壞之龍',unistr('此卡只能用「克力迪斯之牙」的效果將我方的手牌、場上的「破壞輪」送去墓地來特殊召喚。\u000a①：1回合1次，以對手場上1張卡為對象可以發動。那張卡破壞。那之後，破壞的卡是怪獸卡的場合，給予對手那個原攻擊力數值的傷害。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44376395,'ASHLAN-U1000型',unistr('種族和屬性不同的怪獸2隻\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：此卡指向的儀式怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：向對手展示手牌的1張儀式怪獸可以發動。從牌組將1隻種族和屬性與展示的怪獸不同的儀式怪獸加入手牌。\u000a③：我方將怪獸儀式召喚的場合，以對手場上1張表側表示卡為對象可以發動。那張卡回到手牌。'),'','檢索','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44394295,'影依結合',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的手牌、場上的怪獸作為融合素材，將1隻「影依」融合怪獸融合召喚。從額外牌組特殊召喚的怪獸在對手場上存在的場合，我方牌組的怪獸也能作為融合素材。\u000a\u000a※影依融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44397496,'真紅眼精神','①：以我方墓地1隻「真紅眼」怪獸為對象可以發動。那隻怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44405066,'真紅眼鋼炎龍',unistr('等級7怪獸×2\u000a①：持有超量素材的此卡不會被效果破壞。\u000a②：只要持有超量素材的此卡在怪獸區域存在，每次對手發動魔法、陷阱、怪獸的效果，給予對手500傷害。\u000a③：1回合1次，去除此卡的1個超量素材，以我方墓地1隻「真紅眼」通常怪獸為對象可以發動。那隻怪獸特殊召喚。此效果在對手回合也能發動。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44413654,'變形鬥士 衝擊回歸',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以對手場上最多2張魔法、陷阱卡為對象可以發動。從手牌讓1隻「變形鬥士」怪獸回到牌組，對象卡片回到持有者的牌組。\u000a②：將墓地的此卡除外，從我方墓地的怪獸以及被除外的我方怪獸之中，以1隻「變形鬥士」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44424095,'變形鬥士 速度裝備','手牌的1隻「變形鬥士」怪獸回到牌組。那之後，選擇場上的1張卡破壞，從牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44430454,'六武眾的侍從','暗地裡支持著六武眾的充滿謎團的人物。雖然現在已經不再參加戰鬥，刻在身上的無數傷痕仍受到種種猜測。他的過去無人知曉。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44436472,'雙價體','①：闇屬性怪獸上級召喚的場合，此卡可以當作2隻解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44440058,'星義拱心石',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以「星義拱心石」以外的被除外的1隻我方怪獸為對象可以發動。此卡從手牌特殊召喚，對象怪獸回到牌組。\u000a②：此卡被除外的回合的結束階段可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44451698,'妖精弓士 因古納爾',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡用植物族怪獸的效果特殊召喚成功的場合，以我方墓地1隻等級6以上的植物族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果的發動後，直到回合結束時我方除了植物族怪獸以外不能特殊召喚。\u000a②：此卡在特殊召喚的回合不能攻擊。'),'效果1','不能特殊召喚植物族怪獸以外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44455560,'炎王妃 神鴞不死鳥',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。此卡以外的我方的手牌、場上（表側表示）1隻炎屬性怪獸破壞，從牌組將「炎王妃 神鴞不死鳥」以外的1隻獸族、獸戰士族、鳥獸族的炎屬性怪獸加入手牌。那之後，可以將此卡的等級變成和此效果加入手牌的怪獸相同。\u000a②：此卡被破壞送去墓地的場合可以發動。從牌組將1隻「炎王神獸 迦樓羅不死鳥」守備表示特殊召喚。'),'是否變成相同等級？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44459942,'合損為新',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方墓地將1隻機械族、闇屬性怪獸除外可以發動。從我方的手牌、牌組、墓地將1隻記載「馬達衍生物」的衍生物名的怪獸特殊召喚。\u000a②：此卡在墓地存在的狀態，我方場上的表側表示的機械族、闇屬性怪獸因戰鬥以外被送去墓地的場合，將此卡除外可以發動。在我方場上將1隻「馬達衍生物」（機械族、地、等級1、攻/守200）攻擊表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44459943,'馬達衍生物','由「合損為新」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44466810,'時空銀河的霸主',unistr('這個卡名的卡在1回合只能發動1張。我方場上有「銀河眼時空龍」怪獸存在的場合，此卡也能從手牌發動。\u000a①：我方、對手的戰鬥階段，去除我方場上的「銀河眼」超量怪獸的1個超量素材可以發動（我方場上有「CNo.」怪獸存在的場合，此卡的發動和效果不會被無效化）。這個回合召喚、特殊召喚的對手場上的怪獸全部回到牌組。'),'效果1','適用「時空銀河的霸主」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44472639,'太陽光線','給予對手相當於我方場上表側表示存在的光屬性怪獸數量×600傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44478599,'聖天樹的灰樹精',unistr('包含連結怪獸的植物族怪獸2隻以上\u000a①：此卡連結召喚成功的場合可以發動。從我方墓地選1隻「聖種的地靈」特殊召喚。\u000a②：此卡不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。\u000a③：1回合1次，以此卡指向的1隻我方的「聖蔓」連結怪獸為對象可以發動。這個回合，那隻怪獸可以攻擊多次，次數上限為我方場上的「聖天樹」連結怪獸數量。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44481227,'娛樂夥伴 下降駱駝',unistr('【靈擺效果】\u000a①：1回合1次，以我方場上1隻表側表示怪獸為對象可以發動。對手場上的全部怪獸的守備力直到回合結束時下降800，這個回合對象怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a【怪獸效果】\u000a①：此卡被戰鬥破壞的場合可以發動。破壞此卡的怪獸的攻擊力下降800。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44482554,'星宿龍 潘',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡作為融合召喚的素材送去墓地的場合可以發動。從牌組將1張「星宿」魔法、陷阱卡在我方場上覆蓋。那之後，可以將場上1隻怪獸破壞。\u000a②：此卡在墓地存在的狀態，我方場上的表側表示的融合怪獸被對手的效果破壞的場合可以發動。此卡回到牌組最下方，從我方墓地將融合怪獸以外的1隻「星宿」怪獸特殊召喚。'),'覆蓋魔陷','特殊召喚','是否將1隻怪獸破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44487250,'超量阻擋','①：對手發動怪獸的效果時，去除我方場上的1個超量素材可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44505297,'甲蟲裝機 艾克薩甲蟲',unistr('等級6怪獸×2\u000a此卡超量召喚成功時，可以選擇我方或對手的墓地1隻怪獸，當作裝備卡給此卡裝備。\u000a此卡的攻擊力、守備力上升此效果裝備的怪獸對應數值的一半。\u000a此外，1回合1次，藉由去除此卡的1個超量素材，選擇我方以及對手場上表側表示存在的卡各1張送去墓地。'),'裝備','送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508094,'星塵龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：要讓場上的卡破壞的魔法、陷阱、怪獸的效果發動時，將此卡解放可以發動。那個發動無效並破壞。\u000a②：此卡的①效果適用的回合的結束階段可以發動。為了發動那個效果而解放的此卡從墓地特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508095,'星塵龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：要讓場上的卡破壞的魔法、陷阱、怪獸的效果發動時，將此卡解放可以發動。那個發動無效並破壞。\u000a②：此卡的①效果適用的回合的結束階段可以發動。為了發動那個效果而解放的此卡從墓地特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508096,'星塵龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：要讓場上的卡破壞的魔法、陷阱、怪獸的效果發動時，將此卡解放可以發動。那個發動無效並破壞。\u000a②：此卡的①效果適用的回合的結束階段可以發動。為了發動那個效果而解放的此卡從墓地特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508097,'星塵龍',unistr('協調+協調以外的怪獸1隻以上\u000a①：要讓場上的卡破壞的魔法、陷阱、怪獸的效果發動時，將此卡解放可以發動。那個發動無效並破壞。\u000a②：此卡的①效果適用的回合的結束階段可以發動。為了發動那個效果而解放的此卡從墓地特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44509529,'調皮小子 氣象機',unistr('「調皮小子」怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：我方的「調皮小子」怪獸攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱、怪獸的效果。\u000a②：對手回合解放此卡，以融合怪獸以外的我方墓地2隻「調皮小子」怪獸為對象可以發動（同名卡最多1張）。那些怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不會被戰鬥破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44509898,'精準防禦','①：對手怪獸的攻擊宣言時，以我方墓地1隻等級4以下的怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸在這個回合不會被戰鬥、效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44519536,'被封印者的左腳','被封印的左腳。封印解開的話能夠得到無限的力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44536921,'捕食計劃',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻「捕食植物」怪獸送去墓地可以發動。給場上的全部表側表示怪獸各放置1個捕食計數器。已放置捕食計數器的等級2以上的怪獸的等級變成1。\u000a②：此卡在墓地存在的狀態，我方將闇屬性怪獸融合召喚的場合，將墓地的此卡除外，以場上1張卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44553392,'識無邊世壞','①：場上有「維舍斯-阿修特羅德」存在的場合，以場上1張卡為對象可以發動。那張卡破壞。那之後，如果破壞的卡的原卡名是「維舍斯-阿修特羅德」，可以選被除外的1隻我方的「維薩斯-星霜」特殊召喚。如果是「維舍斯-阿修特羅德」以外，可以選我方場上1隻「維舍斯-阿修特羅德」，那個攻擊力上升1500。','是否選被除外的怪獸特殊召喚？','是否選1隻怪獸攻擊力上升？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44573911,'R.B.鋼天貫樁機',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上的表側表示怪獸，不存在的場合或只有「R.B.」怪獸的場合，此卡可以從手牌特殊召喚。\u000a②：指向此卡的「R.B.野蠻藍調」和對手怪獸進行戰鬥的攻擊宣言時，支付1500生命值可以發動。此卡和對手場上的卡全部破壞。'),'','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44584775,'傷害=爬蟲','1回合1次，爬蟲類族怪獸的戰鬥讓我方受到戰鬥傷害時可以發動。從牌組將1隻攻擊力在那時受到的傷害數值以下的爬蟲類族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44586426,'太陽能電池人',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1隻雷族怪獸送去墓地。\u000a②：此卡已在怪獸區域存在的狀態，雷族怪獸召喚、特殊召喚的場合發動。在我方場上將1隻「電池人衍生物」（雷族、光、等級1、攻/守0）特殊召喚。\u000a③：以我方的場上、墓地1隻「電池人」效果怪獸為對象可以發動。直到結束階段，此卡當作其同名卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44586427,'電池人衍生物','由「太陽能電池人」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44595286,'裁決之光',unistr('①：場上有「天空的聖域」存在的場合，從手牌將1隻光屬性怪獸捨棄到墓地可以發動。從以下效果挑選1個適用。\u000a●確認對手的手牌，從其中選1張卡送去墓地。\u000a●選對手場上的1張卡送去墓地。'),'●對手場上的卡送去墓地','●確認對手的手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44612603,'生存境界',unistr('①：場上的通常怪獸全部破壞，從牌組將最多到破壞數量的等級4以下的恐龍族怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。\u000a②：將墓地的此卡除外，以我方場上1隻恐龍族怪獸和對手場上1張卡為對象可以發動。那些卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44632120,'栗子巴',unistr('這個卡名在規則上也當作「栗子球」卡片。這個卡名的①效果1回合只能使用1次。\u000a①：此卡或我方的「栗子球」怪獸被戰鬥破壞時可以發動。從牌組將「栗子巴」以外的1隻攻擊力300/守備力200的怪獸特殊召喚。\u000a②：將場上的此卡和我方的手牌、場上的「栗子比」「栗子卜」「栗子貝」「栗子球」各1隻解放可以發動。從我方的手牌、牌組、墓地選1隻「栗子巴比倫」特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44635489,'寶瓶星聖 羽林軍二十六',unistr('對手場上有怪獸存在，我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a1回合1次，選擇我方的場上、墓地1隻「星聖」怪獸可以發動。此卡變成和選擇的怪獸相同等級。\u000a將場上的此卡作為超量素材的場合，除了「星聖」怪獸的超量召喚以外不能使用。'),'改變等級','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44640691,'安迪米翁的盜賊',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合發動。給此卡放置1個魔力計數器。\u000a②：去除此卡的1個魔力計數器，從手牌捨棄1隻魔法使族怪獸可以發動。從牌組選1張永續魔法卡在我方的魔法與陷阱區域覆蓋。這個回合，我方不能發動此效果覆蓋的卡以及那些同名卡的效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44644529,'雙天的轉身',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「雙天」怪獸為對象可以發動。那隻怪獸破壞，從牌組、額外牌組選比那隻怪獸的原等級高等級1或原等級低等級1的1隻「雙天」怪獸特殊召喚。\u000a②：我方主要階段將墓地的此卡除外，以我方墓地1隻「雙天」怪獸為對象可以發動。那隻怪獸加入手牌。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44649322,'傳承的大御巫',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1隻「御巫」怪獸無視召喚條件特殊召喚。此效果特殊召喚的怪獸在對手結束階段回到手牌。\u000a②：我方主要階段將墓地的此卡除外可以發動。從牌組將「傳承的大御巫」以外的1張「御巫」卡片送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44654994,'神藝厚塗－奪還－',unistr('這個卡名的在1回合只能發動1張。我方場上有「神藝」怪獸存在的場合，此卡在覆蓋的回合也能發動。\u000a①：對手發動怪獸的效果時可以發動。我方場上1隻融合怪獸直到結束階段除外，那個發動無效並破壞。那之後，我方場上的怪獸的種族是3種以上的場合，可以讓對手場上的魔法、陷阱卡全部回到手牌。'),'效果1','是否讓魔法、陷阱卡全部回到手牌？','適用「神藝厚塗－奪還－」的效果來發動','直到結束階段除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(44656450,'失樂的魔女',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚成功時可以發動。從牌組將1張「禁忌的」速攻魔法卡加入手牌。\u000a②：對手主要階段，將此卡解放可以發動。從牌組將「失樂的魔女」以外的1隻天使族、等級4怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44656491,'和平的使者',unistr('此卡的控制者在每次我方準備階段支付100生命值，或不支付讓此卡破壞。\u000a場上的攻擊力1500以上的怪獸不能攻擊宣言。'),'是否支付100生命值維持「和平的使者」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44663232,'異怪的妖精 艾爾弗比亞','①：1回合1次，向對手展示手牌的1隻風屬性怪獸可以發動。直到下個對手主要階段1結束時，雙方不能發動等級高於展示怪獸的怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44665365,'神光的宣告者',unistr('藉由「宣告者的預言」降臨。\u000a①：對手發動怪獸的效果、魔法、陷阱卡時，從手牌將1隻天使族怪獸送去墓地可以發動。那個發動無效並破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44676200,'英雄防護罩','這個回合，我方場上有表側表示的「E.HERO」怪獸存在的場合，對手怪獸的攻擊只有1次無效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44680819,'亂流龍',unistr('①：「亂流龍」在我方場上只能有1張表側表示存在。\u000a②：我方場上有魔法使族怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a③：此卡被戰鬥、效果破壞送去墓地的場合，除了「亂流龍」以外，以我方墓地1隻攻擊力1500/守備力200的怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44682448,'垃圾王',unistr('此卡可以支付2000生命值，從手牌特殊召喚。\u000a將此卡作為超量素材的場合，除了闇屬性怪獸的超量召喚以外不能使用。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44686185,'影六武眾-初芽',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：從我方墓地以及我方場上的表側表示怪獸之中將2隻「六武眾」怪獸除外，以「影六武眾-初芽」以外的我方墓地1隻「六武眾」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：只有我方場上的1隻「六武眾」怪獸被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44689688,'朱羅紀棘龍','此卡戰鬥破壞對手怪獸送去墓地時，在對手場上將1隻「棘龍衍生物」（恐龍族、炎、等級1、攻300/守0）攻擊表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44689689,'棘龍衍生物','由「朱羅紀棘龍」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44694191,'假形幻臉師',unistr('這個卡名的①效果1回合只能使用1次，③效果在決鬥中只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻惡魔族、幻想魔族、魔法使族怪獸送去墓地。那之後，可以將此卡的種族變成和此效果送去墓地的怪獸的原種族相同。\u000a②：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a③：此卡在墓地存在的場合，從我方墓地將1張魔法卡除外可以發動。此卡特殊召喚。'),'效果1','效果3','是否改變種族？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44698398,'神影金龍 膠子光龍',unistr('等級8怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡從額外牌組特殊召喚的場合可以發動。從牌組將1張「銀河」卡片或「時空」卡片加入手牌。\u000a②：去除此卡的2個超量素材可以發動。將1隻攻擊力3000的龍族、階級8的超量怪獸重疊在我方場上的此卡上方，當作超量召喚從額外牌組特殊召喚。那之後，可以從額外牌組將1隻「銀河」怪獸作為那個超量素材。'),'效果1','效果2','是否從額外牌組將1隻「銀河」怪獸作為超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44702857,'拜駝隆','此卡攻擊守備表示怪獸時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44708154,'浮龐克 驚龍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡同步召喚的場合，最多到我方的場上、墓地的超能族、等級3怪獸種類的數量，以對手場上的卡為對象可以發動。那些卡回到手牌。\u000a②：以「浮龐克 驚龍」以外的我方墓地1隻「龐克」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44710391,'地縛地上繪',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要場上有等級10怪獸存在，此卡不會被效果破壞，雙方不能將此卡作為效果的對象。\u000a②：只要此卡在場地區域存在，我方上級召喚「地縛神」怪獸的場合，同步怪獸可以當作2隻解放。\u000a③：同步怪獸特殊召喚的場合可以發動。從牌組將1張「地縛神」魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44716748,'糾罪巧γ''-欺瞞「exapatisIA」',unistr('【靈擺效果】\u000a這個卡名的②靈擺效果1回合只能使用1次。\u000a①：每次怪獸反轉，給此卡放置1個糾罪計數器。\u000a②：支付900生命值可以發動。從牌組將3張「糾罪巧」卡片向對手展示，對手從其中隨機選1張。那1張加入我方的手牌，其餘回到牌組。\u000a【怪獸效果】\u000a①：向對手展示手牌的此卡可以發動（此效果發動的整回合中，我方只能用裡側守備表示將怪獸特殊召喚）。從手牌將1隻怪獸裡側守備表示特殊召喚。\u000a②：對手發動包含將卡覆蓋的效果的卡的效果時，將裡側表示的此卡變成表側守備表示可以發動。從牌組將1張「糾罪巧」卡片加入手牌。\u000a③：此卡反轉的場合發動。對手場上1張魔法、陷阱卡破壞，從手牌將1隻怪獸裡側守備表示特殊召喚。'),'靈擺效果2','效果1','效果2','效果3','','','','','','','','','','','','');
INSERT INTO texts VALUES(44716890,'通行增稅','①：雙方玩家必須將1張手牌送去墓地才能攻擊宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44717069,'海星','1回合1次，我方的主要階段時可以發動。我方場上的全部「海星」的等級上升1。','等級上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44728989,'再生之海',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方墓地1隻攻擊力1000以下的水屬性怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44729197,'火車機人','①：此卡向對手怪獸攻擊的傷害步驟期間，攻擊力上升500。此卡被對手怪獸攻擊的傷害步驟期間，攻擊力下降500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44760562,'末那圓頂 溫順',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：我方場上有「維薩斯-星霜」或攻擊力1500/守備力2100的怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡被戰鬥、效果破壞的場合可以發動。從牌組將1隻「末那圓頂 溫順」特殊召喚。那之後，可以讓此效果特殊召喚的怪獸的等級上升2。'),'效果1','效果2','是否讓等級上升？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44762290,'光學迷彩鎧甲',unistr('只能給等級1怪獸裝備。\u000a裝備怪獸可以直接攻擊對手玩家。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44763025,'愛惡作劇的雙子魔鬼','支付1000生命值可以發動。對手隨機選1張手牌捨棄，再選擇1張捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44763696,'Sin Tune',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的表側表示的「Sin」怪獸被戰鬥或對手的效果破壞的場合可以發動。我方從牌組抽2張卡。\u000a②：此卡在墓地存在的狀態，我方場上的表側表示的「Sin」怪獸被戰鬥以外破壞的場合，將墓地的此卡除外可以發動。從牌組將1隻「Sin」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44771289,'旅人的結彼岸',unistr('①：從我方的手牌、場上將「彼岸」融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a②：我方主要階段，將墓地的此卡除外，以場上的1隻「彼岸」怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到下個對手回合結束時上升800。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44789585,'大植然豆',unistr('此卡1回合只有1次不會被戰鬥破壞。\u000a場上表側表示存在的此卡被選擇作為攻擊對象時，給予對手500傷害。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44790889,'重槌突擊豹鑣',unistr('對手場上有卡存在，我方場上沒有卡存在的場合，此卡可以不用解放來召喚。\u000a我方場上沒有魔法、陷阱卡存在，此卡攻擊對手怪獸的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44792253,'D.D.毀滅者','場上的此卡除外時，可以選擇對手場上的1張表側表示的卡破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44800181,'連擊大師','只要此卡在我方場上表側表示存在，我方回合的主要階段1有連鎖發生的場合，這個回合此卡在1次戰鬥階段中可以攻擊2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44811425,'蠕蟲 連結體','反轉：此卡在場上表側表示存在的場合，每次雙方的結束階段時，我方從牌組抽1張卡。','抽1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44822037,'碑像的天使-亞茲盧恩',unistr('①：此卡發動後變成效果怪獸（天使族、光、等級4、攻/守1800）在怪獸區域特殊召喚（也當作陷阱卡）。\u000a②：如果此卡已被此卡的效果特殊召喚，1回合1次，對手將怪獸特殊召喚之際，將從魔法與陷阱區域特殊召喚的我方的怪獸區域1張永續陷阱卡送去墓地可以發動。那次特殊召喚無效，那些怪獸破壞。\u000a③：此卡被戰鬥破壞時可以發動。將破壞此卡的怪獸破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44839512,'超電導戰士 線性磁砲王±',unistr('此卡不能通常召喚。「超電導戰士 線性磁砲王±」1回合1次從我方的手牌、牌組、場上（表側表示）將2隻原等級是4以下的「磁石戰士」怪獸送去墓地可以特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：以場上1隻其他的地屬性怪獸為對象可以發動。此卡的攻擊力直到回合結束時上升那個攻擊力的一半數值。\u000a②：此卡被破壞送去墓地的場合發動。此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44843954,'妮夢雷莉婭的寐夢',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻「妮夢雷莉婭」怪獸加入手牌。我方的額外牌組有表側表示的「眠夢中的妮夢雷莉婭」存在的場合，隨後在這個回合中，「妮夢雷莉婭」怪獸召喚、特殊召喚成功時對手不能發動魔法、陷阱、怪獸的效果。\u000a②：讓墓地的此卡回到牌組最下方，以我方場上1張「眠夢中的妮夢雷莉婭」為對象可以發動。那張卡表側表示加入持有者的額外牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44852429,'DDD咒血王 賽弗里德',unistr('協調+協調以外的「DD」怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手回合，以場上1張表側表示的魔法、陷阱卡為對象可以發動。那張卡的效果直到下個準備階段無效。\u000a②：此卡被戰鬥、效果破壞送去墓地的場合發動。我方回復我方場上的「契約書」卡片數量×1000生命值。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44857722,'月輪鏡',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：每次怪獸被戰鬥、效果破壞，每有1隻給此卡放置1個月輪計數器。\u000a②：可以去除此卡的以下數量的月輪計數器，發動那個效果。\u000a●1個：從我方的手牌、墓地將1隻等級6以下的惡魔族、天使族怪獸特殊召喚。\u000a●3個：從牌組將1隻闇屬性、等級10怪獸加入手牌。\u000a●5個：從我方的手牌、墓地將1隻等級10怪獸特殊召喚。'),'效果2','●1個：','●3個：','●5個：','','','','','','','','','','','','');
INSERT INTO texts VALUES(44860890,'捷炎星-鴉清',unistr('此卡從場上送去墓地的場合，可以從牌組選1張「炎舞」魔法卡在我方場上覆蓋。\u000a此外，只要此卡在場上表側表示存在，我方場上的「炎舞」魔法、陷阱卡不會被對手的卡片效果破壞。'),'覆蓋','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44865098,'機械兵隊','護衛機械王的兵隊。圓圓的身體到處轉動著進行巡邏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44874522,'古代機械齒輪 熱核反應機龍',unistr('①：解放「古代機械齒輪」怪獸來上級召喚的此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：解放「小工具」怪獸來上級召喚的此卡在1次戰鬥階段中可以攻擊2次。\u000a③：此卡攻擊的場合，對手直到傷害步驟結束時不能發動怪獸的效果、魔法、陷阱卡。\u000a④：此卡攻擊的傷害步驟結束時可以發動。選場上1張魔法、陷阱卡破壞。'),'效果4','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44877690,'冰結界的神精靈',unistr('此卡不能特殊召喚。\u000a①：此卡召喚、反轉的回合的結束階段發動。此卡回到手牌。我方場上有其他的「冰結界」怪獸存在的場合，改成發動以下效果。\u000a●此卡召喚、反轉的回合的結束階段，以對手場上1隻怪獸為對象發動。那隻對手怪獸回到手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44883600,'雙重防禦者','我方場上有2隻以上表側守備表示怪獸存在的場合，對手怪獸的攻擊宣言時可以發動。選擇那1隻對手怪獸的攻擊無效。這個效果1回合只能使用1次。','攻擊無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44883830,'死之合唱','我方場上有3隻「死亡青蛙」表側表示存在時可以發動。對手場上的卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44886582,'超逸融合',unistr('這個卡名的卡在1回合只能發動1張，應對此卡的發動，不能發動卡的效果。\u000a①：支付2000生命值，以場上1隻效果怪獸為對象可以發動。從額外牌組將1隻和那隻怪獸等級不同，種族、屬性相同的怪獸效果無效特殊召喚。那之後，從以下效果挑選1個適用。\u000a●此效果特殊召喚的怪獸和對象怪獸作為融合素材，將1隻融合怪獸融合召喚。\u000a●此效果特殊召喚的怪獸送去墓地。'),'效果1','●融合召喚','●送去墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44887817,'增草劑','①：1回合1次，以我方墓地1隻植物族怪獸為對象可以發動。那隻植物族怪獸特殊召喚。此效果將怪獸特殊召喚的整回合中，我方不能通常召喚。此效果特殊召喚的怪獸從場上離開時，此卡破壞。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44889144,'書靈師介入',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手發動魔法、陷阱、怪獸的效果時，以我方場上1隻「書靈師」儀式怪獸為對象可以發動。那隻怪獸回到持有者的手牌，那個發動的效果無效。那之後，可以從我方的手牌、墓地選1隻「書靈師」怪獸特殊召喚。'),'效果1','是否選1隻怪獸特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44891812,'超重武者 御助-K',unistr('①：我方墓地沒有魔法、陷阱卡存在的場合，我方的守備表示怪獸和對手怪獸進行戰鬥的傷害計算時，將此卡從手牌捨棄，以進行戰鬥的怪獸以外的我方場上1隻「超重武者」怪獸為對象可以發動。那隻進行戰鬥的我方怪獸的守備力只在那次傷害計算時上升對象怪獸的守備力數值。\u000a②：對手怪獸的直接攻擊宣言時，將墓地的此卡除外，以我方墓地1隻「超重武者」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44901281,'軍刀空洞','①：我方場上有「X-軍刀」怪獸存在，我方或對手將怪獸召喚、反轉召喚、特殊召喚之際可以發動。使其無效，那些怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44910027,'勝利龍','此卡不能特殊召喚。必須解放我方場上的3隻龍族怪獸來上級召喚。此卡的直接攻擊使對手的生命值變成0的場合，此卡的控制者獲得比賽勝利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44913552,'時間侵蝕物','此卡戰鬥破壞對手怪獸的場合，跳過下個對手回合的主要階段1。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44920699,'炎舞-「天璇」',unistr('此卡發動時，選擇我方場上的1隻獸戰士族怪獸。那隻怪獸的攻擊力直到回合結束時上升700。\u000a此外，只要此卡在場上存在，我方場上的獸戰士族怪獸的攻擊力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44928016,'胡蘿蔔人',unistr('「胡蘿蔔人」的效果1回合只能使用1次。\u000a①：此卡在墓地存在的場合，從手牌以及我方場上的表側表示怪獸之中將「胡蘿蔔人」以外的1隻植物族怪獸送去墓地可以發動。此卡從墓地特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44932065,'捕食植物 腺毛草胡蜂',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡被送去墓地的場合可以發動。從牌組將「捕食植物 腺毛草胡蜂」以外的1隻「捕食植物」怪獸加入手牌。\u000a②：此卡在墓地存在，場上的怪獸已放置捕食計數器的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44935634,'左起子',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。此卡的等級直到回合結束時變成3。\u000a②：將墓地的此卡除外可以發動。從牌組將1隻「右起子」加入手牌。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44944304,'娛樂夥伴 逗樂家',unistr('【靈擺效果】\u000a①：1回合1次，對手場上有攻擊力高於原攻擊力的怪獸存在的場合可以發動。我方回復1000生命值。\u000a【怪獸效果】\u000a「娛樂夥伴 逗樂家」的①②怪獸效果1回合只有1次能使用其中1個。\u000a①：此卡的攻擊宣言時可以發動。直到戰鬥階段結束時，此卡的攻擊力上升此卡和對手場上的怪獸之中攻擊力高於原攻擊力的怪獸數量×1000。\u000a②：攻擊力高於原攻擊力的此卡被戰鬥、效果破壞的場合，以我方墓地1隻怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44947065,'強者的苦痛','①：對手場上的怪獸的攻擊力下降那隻怪獸的等級×100。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44954628,'巨大戰艦 泰特朗',unistr('此卡召喚時，給此卡放置3個計數器。\u000a此卡不會被戰鬥破壞。\u000a此卡進行戰鬥的傷害步驟結束時，去除此卡的1個計數器。不能去除的場合，此卡破壞。\u000a1回合1次，藉由去除此卡的1個計數器，選擇場上的1張魔法、陷阱卡破壞。'),'放置計數器','N/A','N/A','破壞魔法、陷阱卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(44956694,'ROM 雲端雌羊',unistr('①：此卡召喚成功時，以「ROM 雲端雌羊」以外的我方墓地1隻電子界族怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：此卡被戰鬥、效果破壞的場合可以發動。從牌組將「ROM 雲端雌羊」以外的1隻等級4以下的電子界族怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44968459,'沉默燃燒',unistr('①：我方場上有「沉默魔術師」怪獸存在，我方的手牌比對手多的場合，我方、對手的戰鬥階段可以發動（此卡的發動和效果不會被無效化）。雙方玩家各自抽牌直到手牌變成6張為止。\u000a②：我方主要階段將墓地的此卡除外可以發動。從牌組將1隻「沉默魔術師」怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44968687,'傳說的漁夫三世',unistr('此卡不能通常召喚。只能將我方場上的1隻「傳說的漁夫」解放來特殊召喚。\u000a①：此卡特殊召喚成功時可以發動。對手場上的怪獸全部除外。這個回合，此卡不能攻擊。\u000a②：場上的此卡不會被戰鬥、效果破壞，不受魔法、陷阱卡的效果影響。\u000a③：1回合1次，我方主要階段可以發動。除外的對手的卡全部回到墓地，這個回合，對手受到的戰鬥、效果傷害只有1次變成2倍。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44994712,'捕食植物 長葉狸藻新婦蛛',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將「捕食植物 長葉狸藻新婦蛛」以外的1張「捕食」卡片加入手牌。\u000a②：可以將墓地的此卡除外，從以下效果選擇1個發動。\u000a●給場上1隻表側表示怪獸放置1個捕食計數器。已放置捕食計數器的等級2以上的怪獸的等級變成1。\u000a●我方的墓地、除外狀態的1張「融合」在我方場上覆蓋。'),'效果1','效果2','●放置捕食計數器','●覆蓋「融合」','','','','','','','','','','','','');
INSERT INTO texts VALUES(45001322,'書靈師 熾火點燃俠',unistr('藉由「書靈師」卡片降臨。\u000a①：使用場上的怪獸儀式召喚的此卡不會被效果破壞，不能被效果除外。\u000a②：只要攻擊力未滿3000的此卡在怪獸區域存在，每次對手發動卡的效果，此卡的攻擊力、守備力上升200。'),'效果1適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45002991,'大君主聖像騎士',unistr('包含連結怪獸的效果怪獸2隻以上\u000a①：此卡的攻擊力上升此卡指向的怪獸的原攻擊力數值。\u000a②：此卡指向的怪獸不能攻擊。\u000a③：1回合1次，將此卡指向的我方的1隻「聖像騎士」怪獸或「星遺物」怪獸解放，以對手場上1張表側表示的卡為對象可以發動。那張卡的效果直到回合結束時無效。此效果在對手回合也能發動。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45005708,'深淵獸 阿盧緋爾',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「阿不思的落胤」。\u000a②：此卡召喚、特殊召喚的場合，可以捨棄1張手牌，以對手的場上、墓地1隻龍族怪獸為對象，從以下效果選擇1個發動。\u000a●此卡送去墓地，直到結束階段得到作為對象的場上的怪獸的控制權。\u000a●此卡送去墓地，作為對象的墓地的怪獸在我方場上特殊召喚。'),'●得到場上的怪獸的控制權','●特殊召喚墓地的怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45010690,'機器花','①：此卡被送去墓地的場合發動。我方從牌組抽1張卡。那之後，將1張手牌回到持有者的牌組最上方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45014450,'霸王紫龍 異色眼毒液龍',unistr('【靈擺效果】\u000a①：1回合1次，以我方場上1隻融合怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升對手場上的怪獸數量×1000。\u000a【怪獸效果】\u000a「飢餓毒液」怪獸+「異色眼」怪獸\u000a此卡只能用融合召喚或靈擺召喚來特殊召喚。\u000a①：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。直到結束階段，此卡的攻擊力上升那隻怪獸的攻擊力數值，此卡得到和那隻怪獸相同的原本的卡名、效果。\u000a②：怪獸區域的此卡被破壞的場合可以發動。選我方的靈擺區域1張卡特殊召喚，此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','解除複製效果','效果2','','','','','','','','','','','','');
INSERT INTO texts VALUES(45016904,'陰陽師 道道',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a②：我方因戰鬥、效果受到傷害的場合可以發動。從我方的手牌、墓地將1隻等級3以上的幻想魔族怪獸特殊召喚。受到的傷害是2000以上的場合，特殊召喚的怪獸也能從牌組、額外牌組挑選。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45023678,'閃電制裁者','如果同一連鎖上沒有多次同名卡的效果發動，連鎖累積到3以上的場合發動。選擇對手場上的1張卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45025640,'拒絕綿羊',unistr('①：此卡的戰鬥產生給對手的戰鬥傷害由我方代為承受。\u000a②：此卡的戰鬥沒有將此卡破壞，使我方受到戰鬥傷害的場合發動。此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45033006,'正義盟軍 捕敵者','此卡召喚成功時，可以選擇對手場上的1隻裡側守備表示怪獸，直到結束階段時得到控制權。','獲得控制權','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45037489,'鮮花的騎士',unistr('「花之同步者」+協調以外的怪獸1隻以上\u000a①：1回合1次，我方回合中對手發動魔法、陷阱卡時可以發動。那個發動無效並破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45041488,'核成守護者',unistr('此卡的控制者在每次我方結束階段，從手牌將1張「核成的鋼核」送去墓地，或向對手展示手牌的1隻岩石族怪獸，或都不做讓此卡破壞。\u000a效果怪獸的效果發動時，解放此卡可以發動。那個發動無效並破壞。'),'「核成的鋼核」送去墓地','展示岩石族怪獸','破壞','發動無效並破壞','','','','','','','','','','','','');
INSERT INTO texts VALUES(45042329,'地雷獸','強大的電磁波不停的向周圍發射。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45045866,'海洋衛士',unistr('此卡向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a此卡被戰鬥破壞的場合，從我方牌組將1隻「千眼魚」或「母腦魚」加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45064756,'輪迴獨斷','①：1回合1次，宣言1個種族可以發動。這個回合，雙方墓地的怪獸變成宣言的種族。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45065541,'末那圓頂摘心',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻怪獸為對象可以發動。那隻怪獸破壞，從牌組將1張「伍世壞-佳樂里姆」加入手牌。我方場上有「伍世壞-佳樂里姆」存在的場合，也能改成將「末那圓頂摘心」以外的1張「末那圓頂」魔法、陷阱卡加入手牌。\u000a②：將墓地的此卡除外可以發動。從手牌將1隻「維薩斯-星霜」或攻擊力1500/守備力2100的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45072394,'鐵籠子',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，我方場上的1隻怪獸送去墓地。場地區域有「斯特朗堡的黃金城」存在的場合，也能改成對手場上的怪獸送去墓地。\u000a②：我方準備階段，以此卡的①效果送去我方或對手的墓地的1隻怪獸為對象可以發動。此卡破壞，那隻怪獸在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45078193,'電子暗黑砲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。從牌組將1隻機械族的「電子暗黑」怪獸加入手牌。\u000a②：已裝備此卡的怪獸進行戰鬥的傷害計算時可以發動。從牌組將1隻怪獸送去墓地。\u000a③：給怪獸裝備的此卡被送去墓地的場合可以發動。我方從牌組抽1張卡。'),'效果3','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45082499,'ZW-雷神猛虎劍',unistr('①：「ZW-雷神猛虎劍」在我方場上只能有1張表側表示存在。\u000a②：以我方場上1隻「希望皇霍普」怪獸為對象可以發動。從我方的手牌、場上將此卡當作攻擊力上升1200的裝備卡給那隻我方的「希望皇霍普」怪獸裝備。\u000a③：此卡裝備中的場合，我方場上的「ZW」卡片不會被對手的效果破壞。\u000a④：裝備怪獸被效果破壞的場合，將此卡破壞作為代替。'),'裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45103815,'召喚師 萊茲貝特',unistr('【靈擺效果】\u000a①：1回合1次，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的等級上升1。\u000a【怪獸敘述】\u000a非常關心愛護妹妹塞姆貝爾，溫和親切的哥哥萊茲貝特。剛過中午的午後他跟妹妹一起讀魔術書的時間是每日慣例，見到那兩人和睦的情景讓周圍的人們也自然而然地被治癒心靈。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45112597,'世海龍 西蘭提斯',unistr('效果怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：「世海龍 西蘭提斯」在我方場上只能有1張表側表示存在。\u000a②：我方主要階段可以發動。場上的怪獸全部除外。那之後，此效果除外的怪獸盡可能在原持有者的場上以表側表示或裡側守備表示特殊召喚。\u000a③：我方、對手的戰鬥階段可以發動。最多到場上的互相連結狀態的怪獸數量，將場上的卡破壞。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45115956,'戰華史略-矯詔之叛',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將1隻「戰華」怪獸特殊召喚，我方受到那隻怪獸的等級×100傷害。\u000a②：將魔法與陷阱區域的表側表示的此卡送去墓地，以場上1隻「戰華」怪獸為對象可以發動。那隻怪獸的屬性變更為任意屬性。以對手場上的怪獸為對象發動的場合，隨後可以得到那隻怪獸的控制權。'),'效果1','效果2','是否取得控制權？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45116390,'重裝騎士 巴別雙層列車',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：此卡可以不用解放來召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從手牌將1隻機械族、地屬性怪獸特殊召喚。\u000a③：對手已發動卡的效果的回合的我方主要階段可以發動。將1隻機械族、地屬性、階級10的超量怪獸重疊在我方場上的此卡上方當作超量召喚從額外牌組特殊召喚。'),'不解放的召喚','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45118716,'魔法回收員','對手怪獸的攻擊宣言時，將墓地的此卡除外，選擇我方墓地的1張魔法卡可以發動。我方牌組最上方的卡送去墓地，選擇的卡回到牌組最下方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45121025,'陰影的鬼王','被陰影附體的魔鬼。用驚人的速度突擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45133463,'死神的呼聲','從我方墓地將怪獸特殊召喚時可以發動。選擇我方墓地的1隻「蘇帕伊」或「赤蟻 阿斯卡托爾」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45141013,'大熱波','①：我方主要階段1開始時可以發動。直到下個我方抽牌階段，雙方不能將效果怪獸召喚、特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45141844,'執著的老魔術師','①：此卡反轉的場合，以對手場上1隻怪獸為對象發動。那隻對手怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45148985,'幻化執行者',unistr('此卡不能通常召喚。只能從我方墓地以及我方場上的表側表示的卡之中將5種「幻化」卡片各1張除外來特殊召喚。\u000a①：場上的此卡不會被效果破壞，不能被效果除外。\u000a②：對手場上的卡片數量比我方場上的卡片多的場合，1回合1次，以被除外的1隻我方的「幻化」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在下個回合的結束階段除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45154513,'巨食屍鬼 馬傑拉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的不死族怪獸被戰鬥、效果破壞的場合，可以將手牌、墓地的此卡除外作為代替。\u000a②：此卡從手牌、墓地除外的場合可以發動。此卡守備表示特殊召喚。那之後，可以讓此卡的等級下降1。'),'是否讓此卡的等級下降1？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45159319,'摩艾像迎擊砲','我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。','變成裡側守備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45170821,'V.HERO 至高之王',unistr('「HERO」怪獸×2\u000a①：1回合1次，以對手場上1隻表側表示怪獸和此卡以外的我方場上1隻「HERO」怪獸為對象可以發動。那隻對手怪獸的攻擊力、守備力直到回合結束時下降那隻我方怪獸的攻擊力數值。'),'攻守下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45171524,'巳劍勸請',unistr('這個卡名的卡在1回合只能發動1張。此卡也能將我方的手牌、場上1隻爬蟲類族怪獸解放來發動。\u000a①：從以下效果挑選1個適用。將怪獸解放來發動此卡的場合，可以兩者都適用。\u000a●從牌組將1隻「巳劍」怪獸加入手牌。\u000a●我方受到800傷害。那之後，可以從我方的手牌、墓地將1隻「巳劍」怪獸特殊召喚。此效果特殊召喚的怪獸不能直接攻擊。'),'效果1','是否解放怪獸來發動？','是否從牌組加入手牌？','是否受到800傷害？','是否特殊召喚？','','','','','','','','','','','');
INSERT INTO texts VALUES(45178472,'葫蘆','選擇此卡以外的場上表側表示存在的2張魔法、陷阱卡和覆蓋的3張魔法、陷阱可以發動。選擇的卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45184165,'RR-骷髏鷹',unistr('「RR-骷髏鷹」的①效果1回合只能使用1次。\u000a①：超量素材的此卡為了發動超量怪獸的效果而被去除送去墓地的場合，將墓地的此卡除外，以我方墓地1張「RR-」卡片為對象可以發動。那張卡加入手牌。\u000a②：用場上的此卡為素材超量召喚的怪獸得到以下效果。\u000a●這次超量召喚成功的場合發動。此卡的攻擊力上升300。'),'●攻擊力上升300（RR-骷髏鷹）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45195443,'E.HERO 固態人',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚成功時可以發動。從手牌將1隻等級4以下的「HERO」怪獸特殊召喚。\u000a②：此卡被魔法卡的效果從怪獸區域送去墓地的場合，以「E.HERO 固態人」以外的我方墓地1隻「HERO」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45206713,'DD螺渦史萊姆',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合可以發動。包含此卡的手牌的怪獸作為融合素材，將1隻「DDD」融合怪獸融合召喚。\u000a②：將墓地的此卡除外可以發動。從手牌將1隻「DD」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45215225,'絨毛動物天使',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：以我方墓地1隻「絨毛動物」怪獸或「鋒利小鬼」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了融合怪獸以外不能從額外牌組特殊召喚。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：解放此卡，以我方墓地1隻「魔玩具」融合怪獸為對象可以發動。捨棄1張手牌，對象怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45215453,'大日神械德爾塔',unistr('協調+協調以外的光屬性怪獸1隻以上\u000a此卡表側守備表示存在的場合，我方的結束階段時可以從我方牌組選1張裝備魔法卡加入手牌。'),'檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45221020,'尋寶貓熊','①：從我方墓地將最多3張魔法、陷阱卡裡側表示除外可以發動。從牌組將1隻和除外的卡片數量相同等級的通常怪獸特殊召喚。','效果1','請選擇要特殊召喚的怪獸等級','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45222299,'禁咒法 幽靈海怪',unistr('藉由「咒法」儀式魔法卡降臨。\u000a①：此卡儀式召喚成功的場合發動。對手的手牌隨機選最多2張確認，選其中1張回到牌組。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45223540,'沼地的魔道王',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡在手牌存在的場合可以發動。向對手展示額外牌組的1隻融合怪獸，從牌組將1隻在那隻怪獸有記載卡名的融合素材怪獸除外。那之後，此卡特殊召喚。這個回合，此效果特殊召喚的此卡作為融合素材的場合，可以當作此效果除外的怪獸的同名卡。'),'效果1','效果1適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45231177,'炎之劍士','「炎之操縱者」+「傳說的劍豪 MASAKI」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45231178,'炎之劍士','「炎之操縱者」+「傳說的劍豪 MASAKI」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45236142,'高等寶玉獸 藍鈷鷹',unistr('①：場地區域沒有「高等黑暗」存在的場合，這隻怪獸送去墓地。\u000a②：將手牌、場上的此卡送去墓地可以發動。從牌組將1張「高等黑暗」加入手牌。\u000a③：1回合1次，以我方場上1張「高等寶玉獸」卡片為對象可以發動。那張卡回到持有者的手牌或牌組最上方。\u000a④：表側表示的此卡在怪獸區域被破壞的場合，可以不送去墓地當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。'),'效果2','效果3','回到手牌','回到牌組最上方','','','','','','','','','','','','');
INSERT INTO texts VALUES(45247637,'薔薇的刻印',unistr('從我方墓地將1隻植物族怪獸除外，以對手場上1隻表側表示怪獸為對象可以發動此卡。\u000a①：得到裝備怪獸的控制權。\u000a②：我方結束階段發動。此卡的①效果直到下個我方準備階段無效。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45282603,'召喚師 塞姆貝爾','我方主要階段時，可以從手牌將1隻和此卡等級相同的怪獸特殊召喚。這個效果於此卡在場上表側表示存在期間只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45283341,'永恆之絆',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地的「光子」怪獸任意數量為對象可以發動。那些怪獸效果無效特殊召喚。\u000a②：我方主要階段將墓地的此卡除外，以對手場上1隻「光子」怪獸為對象可以發動。得到那隻怪獸的控制權。這個回合，我方不用那隻怪獸不能攻擊宣言，那隻怪獸的攻擊力變成我方場上的「光子」怪獸的原攻擊力合計數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45286019,'齒輪齒輪人 Mk-III','此卡被「齒輪齒輪」卡片的效果特殊召喚成功時，可以從我方的手牌、墓地選「齒輪齒輪人 Mk-III」以外的1隻「齒輪齒輪」怪獸表側守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。「齒輪齒輪人 Mk-III」的效果1回合只能使用1次。此效果發動的整回合中，我方除了「齒輪齒輪」怪獸以外不能特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45298492,'傷痕戰士',unistr('協調+協調以外的怪獸1隻以上\u000a只要此卡在場上表側表示存在，對手不能選擇表側表示存在的其他戰士族怪獸作為攻擊對象。\u000a此外，此卡1回合只有1次不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45305419,'繼承之印','我方墓地有3隻同名怪獸存在時可以發動。選擇其中1隻怪獸在我方場上特殊召喚，並裝備此卡。此卡被破壞時，裝備怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45311864,'盜賊哥布林','①：給予對手500傷害。我方回復500生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45313724,'煉獄之釜',unistr('①：我方場上的「無限地獄」怪獸或龍族、闇屬性、等級8的同步怪獸被對手的效果破壞的場合，可以將我方墓地1張「無限地獄」卡片除外作為代替。\u000a②：我方的手牌不是0張的場合，此卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45313993,'紅蓮狼','①：我方將「共鳴體」怪獸召喚時可以發動。此卡從手牌特殊召喚。此效果特殊召喚的此卡的攻擊力變成一半。','從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45337544,'英豪使者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻「英豪」怪獸加入手牌。\u000a②：我方的生命值是500以下的場合，將墓地的此卡除外，以我方墓地1張「英豪」卡片為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45349196,'凶魔龍 黑惡魔龍',unistr('等級6「惡魔」通常怪獸+「真紅眼」通常怪獸\u000a我方1回合只能特殊召喚1次「凶魔龍 黑惡魔龍」。\u000a①：此卡進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法、陷阱、怪獸的效果。\u000a②：融合召喚的此卡進行戰鬥的戰鬥階段結束時，以我方墓地的1隻「真紅眼」通常怪獸為對象可以發動。依照墓地的那隻怪獸的原攻擊力數值給予對手傷害。那之後，那隻怪獸回到牌組。'),'傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45354718,'LL-鳥鳴呼喚',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻「LL-」怪獸加入手牌或送去墓地。那之後，可以從手牌將1隻和那隻怪獸卡名不同的「LL-」怪獸特殊召喚。'),'效果1','是否從手牌特殊召喚1隻怪獸？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45358284,'鏡子瓢蟲',unistr('我方場上有1隻以上表側表示怪獸存在，我方墓地沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a這個效果特殊召喚成功時，此卡的等級變成此卡以外的我方場上的怪獸的等級合計的等級。\u000a此外，場上表側表示存在的此卡的等級超過12的場合，此卡破壞。'),'改變等級','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45379225,'念力治療師',unistr('協調+協調以外的怪獸1隻以上\u000a1回合1次，將我方墓地的1隻超能族怪獸除外可以發動。我方回復1200生命值。'),'生命值回復1200','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45383307,'古代遺跡巡航機',unistr('「古代遺跡巡航機」的③效果1回合只能使用1次。\u000a①：只要此卡在場地區域存在，每次岩石族怪獸召喚，我方回復500生命值。\u000a②：場上有「古代遺跡」怪獸召喚的場合可以發動。我方從牌組抽1張卡，那之後選1張手牌捨棄。\u000a③：場地區域的表側表示的此卡被送去墓地的場合可以發動。從牌組將1隻「古代遺跡」怪獸加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45409943,'宵闇的路徹',unistr('我方墓地的惡魔族、天使族怪獸×3\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，我方的左端、右端的主要怪獸區域的怪獸不會被效果破壞。\u000a②：以對手場上1張卡為對象可以發動。從牌組將1隻惡魔族、天使族怪獸送去墓地，對象卡片破壞。\u000a③：我方場上的其他卡被效果破壞的場合，以場上1張卡為對象可以發動。那張卡破壞。'),'','從牌組送去墓地','場上的卡破壞','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45410988,'真紅眼轉生',unistr('「真紅之王」的降臨所必需。\u000a①：從我方的手牌、場上解放怪獸直到等級合計為8以上為止，或是從我方墓地將「真紅眼」怪獸除外來代替解放，從手牌儀式召喚「真紅之王」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45420955,'迅雷的暴君 格羅扎',unistr('協調+協調以外的惡魔族怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：對手主要階段，以場上1隻效果怪獸為對象可以發動。從手牌選1隻怪獸捨棄，對象怪獸的效果直到回合結束時無效。\u000a②：惡魔族怪獸從手牌送去我方墓地的場合可以發動。從以下效果挑選1個，此卡直到回合結束時適用那個效果。\u000a●不會被戰鬥破壞。\u000a●不會被對手的效果破壞。\u000a●不會成為對手的效果的對象。'),'效果1','效果2','●不會被戰鬥破壞','●不會被對手的效果破壞','●不會成為對手的效果的對象','','','','','','','','','','','');
INSERT INTO texts VALUES(45425051,'妖精王 奧伯龍','①：只要此卡在怪獸區域以守備表示存在，我方場上的植物族怪獸的攻擊力、守備力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45439263,'熔岩羽蛇','我方墓地有3種以上「熔岩」怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45445571,'死靈公爵',unistr('惡魔族、不死族怪獸×2\u000a此卡的控制者在每次我方準備階段，支付500生命值或將此卡破壞。這個卡名的②③效果1回合各能使用1次。\u000a①：此卡不會被戰鬥破壞。\u000a②：我方主要階段可以發動。進行1隻怪獸的召喚。\u000a③：將墓地的此卡除外，以我方墓地1隻等級4以上的惡魔族、不死族怪獸為對象可以發動。那隻怪獸加入手牌。'),'是否支付500生命值維持此卡？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45450218,'正義盟軍 致命武器','此卡戰鬥破壞光屬性怪獸送去墓地時，從牌組抽1張卡。那之後，此效果抽到的卡是等級4以下的闇屬性怪獸的場合，可以向對手展示那張卡並特殊召喚。','抽卡','是否將抽到的卡特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45452224,'金華貓',unistr('此卡不能特殊召喚。\u000a①：此卡召喚、反轉時，以我方墓地1隻等級1怪獸為對象可以發動。那隻怪獸特殊召喚。此卡從場上離開時那隻怪獸除外。\u000a②：此卡召喚、反轉的回合的結束階段發動。此卡回到持有者的手牌。'),'返回手牌','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45458027,'上弦式神',unistr('此卡不能通常召喚。我方墓地的怪獸只有機械族的場合可以特殊召喚。\u000a①：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時變成0。'),'攻擊力變成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45462149,'碼語者反相',unistr('電子界族怪獸2隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。從手牌將1隻電子界族怪獸在此卡指向的我方場上特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45462306,'X-軍刀 布魯諾',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，從我方的手牌、場上（表側表示）、墓地將此卡以外的1隻地屬性怪獸除外可以發動。此卡特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從我方的牌組、墓地將1張「軍刀」魔法、陷阱卡加入手牌。\u000a③：1回合1次，對手的主要階段以及戰鬥階段可以發動。只用包含此卡的我方場上的地屬性怪獸為素材進行同步召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45462639,'闇紅的魔導師',unistr('此卡召喚成功時，給此卡放置2個魔力計數器。\u000a只要此卡在場上表側表示存在，每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a此卡的攻擊力上升此卡的魔力計數器的數量×300。\u000a1回合1次，藉由去除此卡放置的2個魔力計數器，對手的手牌隨機選1張捨棄。'),'放置魔力計數器','手牌捨棄','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45464587,'黃金榮耀-滅殺者',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：對手回合，以場上1隻融合、同步、超量、連結怪獸為對象可以發動（我方的生命值低於對手的場合，此效果的對象可以變成2隻）。那些怪獸破壞。\u000a②：此卡的①效果發動過的回合的結束階段發動。此卡回到額外牌組，從我方的牌組、墓地將1隻「黃金榮耀-暗殺者」特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45467446,'白之靈龍',unistr('這個卡名在規則上也當作「青眼」卡片。\u000a①：此卡只要在手牌、墓地存在，當作通常怪獸。\u000a②：此卡召喚、特殊召喚時，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡除外。\u000a③：我方、對手回合，對手場上有怪獸存在的場合，將此卡解放可以發動。從手牌將1隻「青眼白龍」特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45483489,'深海的哨兵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡為了發動水屬性怪獸的效果而被送去墓地的場合可以發動。對手選1張手牌直到結束階段以表側表示除外。\u000a②：此卡特殊召喚成功的場合，從我方牌組上方將2張卡送去墓地，以「深海的哨兵」以外的我方墓地1隻等級4以下的水屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45484331,'守寶妖精 姬特',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：需以「阿不思的落胤」為融合素材的融合怪獸在我方的場上、墓地存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。我方的牌組、墓地、除外狀態的1張「烙印」魔法、陷阱卡加入手牌。那之後，選1張我方的手牌回到牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45488703,'NT8000-SIRIUS',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：連結狀態的此卡不會被戰鬥破壞。\u000a②：連結怪獸的效果發動過的我方、對手回合，以我方以及對手場上的表側表示卡各1張為對象可以發動。那2張卡破壞。\u000a③：此卡從場上以外送去墓地的場合，如果我方場上有闇屬性連結怪獸存在可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45496268,'SD機器人 象鬥士',unistr('此卡召喚成功時，可以從手牌將1隻「SD機器人」怪獸或「軌道7」特殊召喚。\u000a1回合1次，選擇我方場上的1隻「SD機器人」怪獸或「軌道7」可以發動。選擇的怪獸的等級直到回合結束時變成8。\u000a將此卡作為超量召喚的素材的場合，除了機械族怪獸的超量召喚以外不能使用。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45500495,'地獄刺藤',unistr('協調+協調以外的植物族怪獸1隻以上\u000a只要此卡在場上表側表示存在，雙方為了從手牌將植物族以外的怪獸召喚、特殊召喚，每有1隻就必須支付1000生命值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45508030,'憑依共鳴',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以場上1隻表側表示怪獸為對象可以發動。從我方的手牌、牌組、墓地將1隻屬性和那隻怪獸相同的「靈使」怪獸或「憑依裝著」怪獸以表側攻擊表示或裡側守備表示特殊召喚。那之後，可以將對象怪獸變成裡側守備表示。\u000a②：將墓地的此卡除外，以我方場上1隻怪獸為對象可以發動。那隻怪獸的表示形式變更。'),'效果1','效果2','是否將對象怪獸變成裡側守備表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45531624,'精靈聖劍士',unistr('此卡在規則上也當作「精靈劍士」卡片。\u000a①：我方有手牌的場合，此卡不能攻擊。\u000a②：1回合1次，我方主要階段可以發動。從手牌將1隻「精靈劍士」怪獸特殊召喚。\u000a③：此卡的攻擊給予對手戰鬥傷害時可以發動。我方依照我方場上的「精靈劍士」怪獸數量從牌組抽牌。'),'從手牌特殊召喚','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45533023,'RR-烈焰獵鷹',unistr('鳥獸族等級5怪獸×3\u000a①：持有超量素材的此卡可以直接攻擊。\u000a②：此卡給予對手戰鬥傷害時，以對手場上的1隻怪獸為對象可以發動。那隻怪獸破壞。\u000a③：1回合1次，去除此卡的1個超量素材可以發動。對手場上的特殊召喚的怪獸全部破壞，給予對手破壞的數量×500傷害。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45536531,'滑稽的黑暗兔寶寶',unistr('①：此卡召喚、特殊召喚時適用。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻記載「卡通世界」的卡名的怪獸。\u000a②：只要場上有「卡通世界」存在，此卡當作卡通怪獸。\u000a③：1回合1次，我方主要階段可以發動。從牌組選1張「卡通」場地、永續魔法卡加入手牌或在我方場上表側表示放置。'),'','召喚（滑稽的黑暗兔寶寶）','效果3','表側表示放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(45538320,'精靈術的使魔',unistr('這個卡名在規則上也當作「憑依裝著」卡片。這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「憑依」魔法、陷阱卡或「大靈術-「一輪」」加入手牌。\u000a②：宣言種族和屬性各1個可以發動。此卡直到回合結束時變成宣言的種族、屬性。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從我方的牌組、墓地將1隻守備力1500的魔法使族怪獸特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45547649,'鳥面人','此卡被戰鬥破壞送去墓地時，可以從我方的牌組將1張「神鷹女郎」加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45584727,'華爾裘蓮的擁抱',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了「華爾裘蓮」怪獸以外不能特殊召喚。\u000a①：我方場上的怪獸只有「華爾裘蓮」怪獸的場合，以我方場上1隻攻擊表示的「華爾裘蓮」怪獸和對手場上1隻表側表示怪獸為對象可以發動。那隻我方怪獸變成守備表示，那隻對手怪獸除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45586855,'正義盟軍 氣旋製造者','1回合1次，捨棄1張手牌可以發動。依照場上的協調數量，選場上的魔法、陷阱卡回到手牌。','回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45591967,'娛樂夥伴 額外射手',unistr('【靈擺效果】\u000a「娛樂夥伴 額外射手」的靈擺效果1回合只能使用1次，此效果發動的整回合中，我方不能靈擺召喚。\u000a①：我方主要階段可以發動。給予對手我方的額外牌組中表側表示的靈擺怪獸數量×300傷害。\u000a【怪獸效果】\u000a①：1回合1次，從我方的額外牌組將1隻怪獸除外，以我方或對手的靈擺區域1張卡為對象可以發動。那張卡破壞，給予對手300傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45593005,'變形鬥士 I型磁鐵',unistr('此卡依照表示形式得到以下效果。\u000a●攻擊表示：我方場上有此卡以外的2隻怪獸表側攻擊表示存在的場合，1回合1次，可以讓此卡的攻擊力直到回合結束時上升那些怪獸的攻擊力的合計數值。此效果發動的整回合中，其他怪獸不能攻擊。\u000a●守備表示：只要此卡在場上表側表示存在，我方場上的怪獸不能攻擊。'),'●攻擊表示：','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45593826,'彼岸的惡鬼 德拉格尼爾',unistr('「彼岸的惡鬼 德拉格尼爾」的①③效果1回合只有1次能使用其中1個。\u000a①：我方場上沒有魔法、陷阱卡存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方場上有「彼岸」怪獸以外的怪獸存在的場合，此卡破壞。\u000a③：此卡被送去墓地的場合可以發動。從牌組選1張「彼岸」卡片放置在牌組最上方。'),'從手牌特殊召喚','放到牌組最上方','請選擇放到牌組最上方的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45620686,'騷騷蟲','將此卡從手牌捨棄到墓地可以發動。選擇場上的1隻怪獸的等級直到回合結束時上升1。','等級上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45627618,'霸王黑龍 異色眼反叛龍',unistr('【靈擺效果】\u000a①：1回合1次，另一邊的我方的靈擺區域沒有卡存在的場合可以發動。從牌組將1隻靈擺怪獸在我方的靈擺區域放置。\u000a【怪獸效果】\u000a龍族等級7怪獸×2\u000a等級7可以靈擺召喚的場合，在額外牌組的表側的此卡可以靈擺召喚。\u000a①：此卡用超量怪獸為素材超量召喚的場合發動。對手場上的等級7以下的怪獸全部破壞，給予對手破壞數量×1000傷害。這個回合，此卡在1次戰鬥階段中可以攻擊3次。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。我方的靈擺區域的卡全部破壞，此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45627619,'霸王黑龍 異色眼反叛龍',unistr('【靈擺效果】\u000a①：1回合1次，另一邊的我方的靈擺區域沒有卡存在的場合可以發動。從牌組將1隻靈擺怪獸在我方的靈擺區域放置。\u000a【怪獸效果】\u000a龍族等級7怪獸×2\u000a等級7可以靈擺召喚的場合，在額外牌組的表側的此卡可以靈擺召喚。\u000a①：此卡用超量怪獸為素材超量召喚的場合發動。對手場上的等級7以下的怪獸全部破壞，給予對手破壞數量×1000傷害。這個回合，此卡在1次戰鬥階段中可以攻擊3次。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。我方的靈擺區域的卡全部破壞，此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45644898,'青之眼祭司',unistr('「青之眼祭司」的②效果1回合只能使用1次。\u000a①：此卡召喚成功時，以我方墓地1隻光屬性、等級1協調為對象可以發動。那隻怪獸加入手牌。\u000a②：讓墓地的此卡回到牌組，以我方場上1隻效果怪獸為對象可以發動。那隻怪獸送去墓地，從我方墓地選那隻怪獸以外的1隻「青眼」怪獸特殊召喚。'),'從牌組加入手牌','從墓地特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45651298,'似耳怪','對手場上有怪獸存在，我方場上有等級3怪獸存在的場合，此卡可以從手牌特殊召喚。這個方法的「似耳怪」的特殊召喚1回合只能有1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45653036,'暴風雨',unistr('選擇我方場上表側表示存在的1隻「雲魔物」怪獸可以發動。選擇的怪獸的攻擊力下降，適用以下效果。\u000a●下降1000：對手場上的1張魔法、陷阱卡破壞。\u000a●下降2000：對手場上的2張卡破壞。'),'●下降1000','●下降2000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45655875,'魔鍵召獸-安希亞拉波斯',unistr('「魔鍵」怪獸+衍生物以外的通常怪獸\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡融合召喚成功的場合可以發動。從我方墓地選1張「魔鍵-馬夫提亞」加入手牌。\u000a②：1回合1次，以對手的1隻持有與我方墓地的任何通常怪獸或「魔鍵」怪獸相同屬性的攻擊表示怪獸為對象可以發動。那隻怪獸變成守備表示，那個守備力下降1000。\u000a③：此卡戰鬥破壞的怪獸不去墓地而是除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45659520,'E-HERO 凶兆死靈',unistr('這個卡名的效果1回合只能使用1次。\u000a①：將墓地的此卡除外可以發動。從手牌、牌組將「E-HERO 凶兆死靈」以外的1隻「E-HERO」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45662855,'寶石騎士 菫青石',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●1回合1次，可以從我方墓地將1隻「寶石」怪獸從遊戲中除外，選擇我方墓地的1隻「寶石騎士」卡片加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45663742,'蛇眼橡樹靈',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，以我方的墓地、除外狀態的1隻炎屬性、等級1怪獸為對象可以發動。那隻怪獸加入手牌或特殊召喚。\u000a②：將包含此卡的我方場上2張表側表示卡送去墓地可以發動。從手牌、牌組將「蛇眼橡樹靈」以外的1隻「蛇眼」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45666710,'星義的執行者',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方墓地的怪獸以及被除外的我方怪獸之中以1隻「星義」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的原等級為11以上的怪獸在這個回合不能發動效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45667991,'降龍的魔術師',unistr('【靈擺效果】\u000a①：1回合1次，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的種族直到對手回合結束時變成龍族。\u000a【怪獸效果】\u000a①：1回合1次，我方主要階段可以發動。此卡的種族直到回合結束時變成龍族。\u000a②：用場上的此卡為素材融合、同步、超量召喚的怪獸得到以下效果。\u000a●此卡和龍族怪獸進行戰鬥的傷害步驟期間，此卡的攻擊力變成原攻擊力的2倍。'),'靈擺效果1','效果1','「降龍的魔術師」的效果2適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45674286,'機甲部隊未分類備用兵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用抽牌以外的方法加入手牌的場合可以發動。此卡特殊召喚。此效果的發動後，直到回合結束時我方除了機械族怪獸以外不能特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從牌組將「機甲部隊未分類備用兵」以外的1隻「機甲部隊」怪獸送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45675980,'烙印的即凶劇',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手回合可以發動。用包含龍族怪獸的我方場上的怪獸為素材進行同步召喚。\u000a②：只要我方場上有「淵獸」怪獸存在，為了對手的儀式召喚而被解放送去對手墓地的怪獸，以及成為對手的融合、同步、連結召喚的素材送去對手墓地的怪獸不去墓地而是除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45688586,'機偶蜘蛛','此卡攻擊闇屬性怪獸的傷害計算後，那隻怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45702014,'元素軍刀 幽暮',unistr('①：1回合1次，從手牌將1隻「元素軍刀」怪獸送去墓地，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。此效果在對手回合也能發動。\u000a②：此卡在墓地存在的場合，1回合1次，宣言1個屬性可以發動。墓地的此卡直到回合結束時變成宣言的屬性。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45702357,'雙面可逆甲蟲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合發動。此卡以及和此卡相同縱列的怪獸全部變成裡側守備表示。\u000a②：此卡反轉的場合發動。此卡以及和此卡相同縱列的表側表示怪獸全部回到持有者的牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45705025,'紋章獸 獨角獸','將墓地的此卡除外，以我方墓地1隻超能族超量怪獸可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。「紋章獸 獨角獸」的效果1回合只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45710945,'銀河眼時空源龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，場上有龍族超量怪獸存在的場合可以發動。此卡從手牌往我方或對手的場上特殊召喚。\u000a②：此卡召喚、特殊召喚的場合發動。此卡的原持有者從自身牌組將1張「時空」魔法、陷阱卡加入手牌。\u000a③：我方或對手的龍族超量怪獸的攻擊宣言時發動。將場上的此卡作為那隻怪獸的超量素材。'),'效果1','效果2','效果3','往我方場上特殊召喚','往對手場上特殊召喚','','','','','','','','','','','');
INSERT INTO texts VALUES(45711266,'朱羅紀翼龍','此卡被攻擊的傷害計算後，攻擊怪獸回到持有者的手牌。此卡的守備力上升以此效果回到手牌的怪獸的等級×100。','回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45716579,'地縛戒隸 地畫烏賊',unistr('「地縛」怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從我方的牌組、墓地將1張場地魔法卡加入手牌。\u000a②：怪獸從對手的額外牌組特殊召喚的場合可以發動。這個回合特殊召喚的對手場上的怪獸全部破壞，給予對手破壞的怪獸數量×800傷害。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45725480,'七星寶刀',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌以及我方場上的表側表示怪獸之中將1隻等級7怪獸除外可以發動。我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45730592,'魔救共振擊','①：我方場上有「魔救」同步怪獸存在，怪獸的效果發動時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45742626,'巡死神 收割者',unistr('等級6怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡的攻擊力、守備力上升雙方墓地的闇屬性怪獸數量×200。\u000a②：去除此卡的1個超量素材可以發動。從雙方的牌組上方將5張卡送去墓地。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45778242,'克萊因客戶端蟻',unistr('①：只要通常召喚的此卡在怪獸區域存在，我方場上的電子界族怪獸的攻擊力、守備力在我方回合中上升500。\u000a②：場上的此卡被戰鬥、效果破壞的場合，可以將我方的手牌、場上的1隻電子界族怪獸破壞作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45778932,'沙漠風暴','場上的風屬性怪獸的攻擊力上升500，守備力下降400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45792753,'游魊鏈',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻表側表示的魚族怪獸除外可以發動。將1隻和為了發動此卡而除外的怪獸原卡名不同的「游魊」怪獸從我方的手牌、牌組、墓地、除外狀態特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45796834,'光天的摩訶毗盧',unistr('①：此卡得到此卡的裝備卡數量的以下效果。\u000a●1張以上：此卡的攻擊力上升此卡的裝備卡數量×1000。\u000a●2張以上：對手在戰鬥階段中不能發動怪獸的效果。\u000a●3張以上：以此卡為對象的對手的效果發動時，將我方場上1張裝備卡送去墓地可以發動。那個效果無效。\u000a●4張以上：對手在戰鬥階段中不能發動卡的效果。\u000a●5張以上：此卡給予對手的戰鬥傷害變成2倍。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45801022,'電力狐猴','此卡由於對手而破壞的場合，下個對手回合，對手不能進行戰鬥階段。','對手不能進行戰鬥階段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45803070,'蒂歐的蟲惑魔',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚時，以我方墓地1隻「蟲惑魔」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a②：此卡特殊召喚時，以我方墓地1張「空洞」通常陷阱卡或「落穴」通常陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡在下個我方回合的結束階段除外。\u000a③：此卡不受「空洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影響。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45809008,'命運抽牌','①：從手牌捨棄1張「D-HERO」卡片可以發動。我方從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45812361,'卡片車D',unistr('此卡不能特殊召喚。此卡的效果發動的整回合中，我方不能將怪獸特殊召喚。\u000a①：此卡召喚的我方主要階段1，將此卡解放可以發動。我方抽2張卡。那之後，變成這個回合的結束階段。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45815891,'廢鐵死亡惡魔','協調+協調以外的怪獸1隻以上','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45819647,'神聖魔皇后 塞勒涅',unistr('包含魔法使族怪獸的怪獸2隻以上\u000a①：此卡連結召喚的場合發動。給此卡放置雙方的場上、墓地的魔法卡數量的魔力計數器。\u000a②：只要場上有「安迪米翁」卡片存在，對手怪獸不能選擇此卡作為攻擊對象。\u000a③：1回合1次，我方、對手的主要階段，去除我方場上的3個魔力計數器可以發動。從我方的手牌、墓地選1隻魔法使族怪獸，在此卡指向的我方場上守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45836982,'地縛超神官',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方的場上、墓地都有同步怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方主要階段可以發動。從我方的牌組、墓地將1隻「地縛神」怪獸加入手牌。\u000a③：此卡已在怪獸區域存在的狀態，「地縛神」怪獸召喚的場合可以發動。對手的生命值變成3000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45852939,'蝕之雙子',unistr('等級4怪獸×2\u000a此卡超量召喚的場合，我方場上的階級4怪獸可以當作等級4怪獸作為素材。這個卡名的②效果1回合只能使用1次。\u000a①：去除此卡的1個超量素材可以發動。這個回合，此卡在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a②：此卡被送去墓地的場合，以我方墓地2隻其他的階級4以下的超量怪獸為對象可以發動。那2隻之中的1隻特殊召喚，另1隻作為那個超量素材。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45869829,'速攻魔力增幅器','從我方墓地選擇「速攻魔力增幅器」以外的1張速攻魔法卡回到牌組。此外，場上的此卡被對手破壞送去墓地的場合，可以從牌組將1張「速攻魔力增幅器」以外的速攻魔法卡加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45871897,'失落的守護者','此卡的原守備力變成我方被除外的岩石族怪獸數量×700。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45877457,'魔鍵砲-加雷斯維特',unistr('藉由「魔鍵-馬夫提亞」降臨。這個卡名的②③效果1回合各能使用1次。\u000a①：此卡的攻擊力上升我方墓地的怪獸的屬性種類×300。\u000a②：此卡的儀式召喚使用的怪獸的屬性是2種以上的場合，對手發動持有與我方墓地的任何怪獸相同屬性的怪獸的效果時可以發動。那個發動無效並破壞。\u000a③：儀式召喚的此卡被送去墓地的場合可以發動。從牌組將1隻「魔鍵」怪獸加入手牌。'),'效果2','效果3','效果2適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45883110,'引導的聖女 奎姆',unistr('這個卡名在規則上也當作「教導」卡片、「死獄鄉」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻「阿不思的落胤」或1張記載那個卡名的卡送去墓地。\u000a②：我方、對手的卡從額外牌組離開的場合，除了「引導的聖女 奎姆」以外，以我方墓地1隻「阿不思的落胤」或記載那個卡名的怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45885288,'新皇帝滑翔龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將此卡和1隻怪獸捨棄，以我方墓地1隻龍族通常怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。對手場上的全部怪獸的攻擊力直到回合結束時下降500。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45894482,'俊足的迅猛龍',unistr('①：此卡可以從手牌特殊召喚。\u000a②：此卡的①方法特殊召喚成功的場合發動。對手可以選自身墓地的1隻怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45895206,'消除黑暗的光','對手場上裡側表示存在的怪獸全部變成表側表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45898858,'鍵結-H2O','①：將我方場上2隻「氫魔獸」和1隻「氧魔獸」可以發動。從我方的手牌、牌組、墓地將1隻「水魔龍」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45906428,'奇蹟結合',unistr('①：我方的場上、墓地的怪獸作為融合素材除外，將1隻「E.HERO」融合怪獸融合召喚。\u000a\u000a※奇蹟融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45909477,'月之使者','侍奉月之女神的戰士。使用像新月一樣的戈進行攻擊！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45935145,'死祖的隸龍 沃洛',unistr('等級6怪獸×2隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的怪獸的攻擊力、守備力上升對手墓地的卡片數量×100。\u000a②：我方、對手回合，可以選擇對手墓地1張卡為對象，去除此卡的以下數量的超量素材，發動那個效果。\u000a●1個：對象卡片回到牌組。\u000a●2個：如果對象卡片是怪獸，將其在我方場上以表側表示或裡側守備表示特殊召喚。如果不是，將其在我方場上覆蓋。'),'●去除1個素材','●去除2個素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45939611,'小妖精','我方的主要階段時，將1張手牌送去墓地可以發動。此卡的等級上升1。這個效果1回合可以使用最多2次。','等級上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45939841,'龍捲','支付500生命值可以發動。選擇場上的1張表側表示的魔法、陷阱卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45943123,'空中魚雷',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上1隻水屬性超量怪獸為對象可以發動。去除那隻怪獸的1個超量素材，給予對手相當於我方的手牌數量×400傷害。那隻怪獸的攻擊力直到回合結束時上升此效果給予的傷害數值。\u000a②：從我方墓地將此卡和1隻水屬性超量怪獸除外可以發動。我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45943516,'戰吼者之岩',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1隻「戰吼者」怪獸加入手牌。\u000a②：我方場上的怪獸，不存在的場合或只有戰士族怪獸的場合，戰鬥階段開始時可以發動。從手牌將同名卡不在我方場上存在的1隻「戰吼者」怪獸特殊召喚。\u000a③：我方的戰士族怪獸被戰鬥破壞的場合，可以將此卡送去墓地作為代替。'),'是否從牌組把1隻「戰吼者」怪獸加入手牌？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45945685,'單車機人','眾多交通工具機人中，和人最親近而深受喜愛的交通工具機人。還可以裝備輔助輪喔！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45948430,'超戰士的萌芽',unistr('「混沌士兵」儀式怪獸的降臨所必需。「超戰士的萌芽」在1回合只能發動1張。\u000a①：等級合計為8的以下其中1個組合的怪獸送去墓地，從我方的手牌、墓地將1隻「混沌士兵」儀式怪獸儀式召喚。\u000a●手牌的1隻光屬性怪獸和牌組的1隻闇屬性怪獸\u000a●手牌的1隻闇屬性怪獸和牌組的1隻光屬性怪獸'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45950291,'升階魔法-星光之力',unistr('①：以我方場上1隻階級最高的超量怪獸為對象可以發動。將1隻和那隻我方怪獸種族、屬性相同且階級高2階的超量怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。\u000a②：此卡在墓地存在的場合，我方抽牌階段的抽牌前可以發動。墓地的此卡加入手牌。此效果發動的整回合中，我方不能通常抽牌，不能用「升階魔法-星光之力」的效果以外將怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45951104,'殭屍牧人',unistr('①：以對手場上1隻裡側守備表示怪獸或原持有者是我方的表側表示怪獸為對象可以發動。對象怪獸不存在的場合，或對象怪獸的原持有者是我方的場合（裡側表示卡則翻開確認），以下效果各自適用。\u000a●給予對手200傷害。\u000a●除了對象怪獸以外，得到對手場上的全部怪獸的控制權。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45955628,'咒眼的眷屬 卡托布萊帕斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1張「咒眼」魔法、陷阱卡為對象可以發動。直到下個回合結束時，那張卡有1次不會被對手的效果破壞。\u000a②：此卡在墓地存在，我方場上有「咒眼的眷屬 卡托布萊帕斯」以外的「咒眼」怪獸存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45960523,'幻化戴達羅斯',unistr('①：此卡用「幻化」怪獸的效果特殊召喚成功的場合可以發動。此卡以外的場上的特殊召喚的表側表示怪獸全部除外。\u000a②：此卡被除外的場合，下個回合的準備階段，讓被除外的此卡回到牌組可以發動。從牌組將「幻化戴達羅斯」以外的1張「幻化」卡片除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45974017,'闇魔界的契約書',unistr('「闇魔界的契約書」的①效果1回合只能使用1次。\u000a①：從以下效果選擇1個，可以發動此效果。\u000a●以我方墓地1隻「DD」靈擺怪獸為對象可以發動。那隻怪獸在我方的靈擺區域放置。\u000a●從我方的額外牌組將1隻表側表示的「DD」靈擺怪獸在我方的靈擺區域放置。\u000a②：我方準備階段發動。我方受到1000傷害。'),'放置在靈擺區域','●從墓地選擇','●從額外牌組選擇','受到1000點傷害','','','','','','','','','','','','');
INSERT INTO texts VALUES(45985838,'日珥龍',unistr('我方場上有此卡以外的炎族怪獸存在的場合，對手不能攻擊此卡。\u000a我方回合的結束階段時，此卡給予對手500傷害。'),'給予對手500傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45986603,'強奪',unistr('可以給對手場上的怪獸裝備。\u000a①：得到裝備怪獸的控制權。\u000a②：對手準備階段發動。對手回復1000生命值。'),'對手回復生命值','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46001505,'王者的鼓動',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：可以從以下效果選擇1個發動。\u000a●對手戰鬥階段可以發動。對手回復1000生命值。那之後，戰鬥階段結束。\u000a●對手場上的卡片數量比我方場上的卡片多，對手發動怪獸的效果時可以發動。從我方的額外牌組、墓地將1隻「暗紅惡魔龍」或「琰魔龍 暗紅惡魔」特殊召喚，那個發動的效果無效並破壞。'),'效果1','●戰鬥階段結束','●特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46005939,'靈擺超量',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方的靈擺區域的2張卡為對象可以發動。那2張卡效果無效特殊召喚，只用那2隻怪獸為素材將1隻超量怪獸超量召喚。此時作為超量素材的1隻怪獸的等級可以當作與另1隻怪獸的等級相同。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46008667,'聖劍 斷鋼劍',unistr('只能給「聖騎士」怪獸裝備。「聖劍 斷鋼劍」的②效果1回合只能使用1次。\u000a①：裝備怪獸不會成為對手的效果的對象。\u000a②：在我方主要階段將墓地的此卡除外，以我方場上的1隻「聖騎士」超量怪獸為對象可以發動。將1隻和那隻我方怪獸卡名不同的「聖騎士」超量怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46009906,'猛獸之齒',unistr('只能給獸族怪獸裝備。\u000a裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46014517,'哥布林百鬼羅剎唯我獨尊',unistr('等級6怪獸×2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：最多到我方場上的「哥布林」怪獸數量，以對手場上的表側表示怪獸為對象可以發動。去除我方場上的1個超量素材，對象怪獸作為此卡的超量素材。\u000a②：對手回合，最多到我方場上的「哥布林」超量怪獸數量，以對手場上的卡為對象可以發動。去除我方場上的3個超量素材，對象卡片送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46031686,'傷害偏光鏡','持有給予傷害的效果的怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效，雙方玩家抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46033517,'機甲部隊毀滅武力',unistr('此卡不能通常召喚。只能將我方墓地的機械族怪獸除外直到等級合計為12以上，從墓地特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：戰鬥階段對手發動效果時，支付一半生命值可以發動。那個發動無效，對手的生命值變成一半。\u000a②：此卡被戰鬥、效果破壞的場合可以發動。等級合計為12以下，選被除外的最多3隻我方的「機甲部隊」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46035545,'DD魔導賢者 尼古拉',unistr('【靈擺效果】\u000a①：我方除了「DD」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a②：1回合1次，從手牌捨棄1隻「DDD」怪獸，以我方場上1隻等級6以下的「DD」怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到回合結束時上升2000。\u000a【怪獸效果】\u000a「DD魔導賢者 尼古拉」的怪獸效果1回合只能使用1次。\u000a①：此卡在靈擺區域被破壞的場合，以我方場上1隻「DDD」怪獸為對象可以發動。那隻怪獸回到持有者的手牌，從我方的額外牌組選最多2隻表側表示的「DD」靈擺怪獸在我方的靈擺區域放置。那些卡的靈擺效果在這個回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46037213,'守護者 特萊斯',unistr('我方場上沒有「閃光的雙劍-特萊斯」的場合，此卡不能召喚、反轉召喚、特殊召喚。\u000a此卡被破壞送去墓地時，墓地存在的此卡的上級召喚解放的怪獸在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46037983,'游魊之燈 佩西斯',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：將場上的此卡除外可以發動。從手牌將「游魊之燈 佩西斯」以外的1隻魚族怪獸特殊召喚。\u000a②：此卡被除外的下個回合的準備階段可以發動。被除外的此卡特殊召喚。\u000a③：此卡特殊召喚的對手回合的主要階段可以發動。用包含此卡的我方場上的怪獸為素材進行1隻魚族同步怪獸的同步召喚。'),'從手牌特殊召喚','此卡特殊召喚','同步召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46044841,'薰風隼','場上表側表示存在的此卡因戰鬥以外被送去墓地時，可以從牌組將1隻「薰風」怪獸裡側守備表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46052429,'高等儀式術','①：從牌組將通常怪獸送去墓地，直到等級合計和儀式召喚的怪獸相同為止，從手牌儀式召喚1隻儀式怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46057733,'燐迴的三弦貓',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：對手主要階段可以發動。用包含此卡的我方場上的怪獸為素材進行同步召喚。\u000a②：此卡在墓地存在的場合，以我方墓地1隻其他的同步怪獸為對象可以發動。那隻怪獸回到額外牌組，此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46060017,'十二獸的會局',unistr('「十二獸的會局」的①效果1回合只能使用1次。\u000a①：以我方場上1張表側表示的卡為對象可以發動此效果。那張卡破壞，從牌組將1隻「十二獸」怪獸特殊召喚。\u000a②：此卡被效果破壞送去墓地的場合，以我方場上1隻「十二獸」超量怪獸為對象可以發動。墓地的此卡重疊在那隻超量怪獸下方作為超量素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46066477,'娛樂樂團颶風',unistr('「娛樂樂團颶風」在1回合只能發動1張。\u000a①：最多到我方場上的「娛樂夥伴」怪獸數量，以對手場上的卡為對象可以發動。那些卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46072770,'魅影騎士團 凋零披風',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，向對手展示手牌1張其他的「魅影騎士團」卡片可以發動。此卡特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻「魅影騎士團」怪獸加入手牌。\u000a③：將墓地的此卡除外，以我方場上1隻超量怪獸為對象可以發動。那隻超量怪獸在這個回合可以作為和自身的階級相同數值的等級的怪獸成為超量召喚的素材。'),'效果1','效果2','效果3','「魅影騎士團 凋零披風」的效果3適用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(46083111,'機怪蟲 樹突',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡反轉的場合可以發動。從牌組將1隻怪獸送去墓地。\u000a②：表側表示的此卡因對手的效果從場上離開的場合可以發動。從牌組將「機怪蟲 樹突」以外的2隻「機怪蟲」怪獸裡側守備表示特殊召喚（同名卡最多1張）。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46083380,'攻通規制','對手場上有3隻以上怪獸存在的場合，對手不能攻擊宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46089249,'核殺輪','向對手展示手牌的1張「核成的鋼核」可以發動。選擇場上表側表示存在的1隻怪獸破壞，雙方受到1000傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46104361,'電子界白帽駭客',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：我方場上有2隻以上相同種族的怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡作為連結素材送去墓地的場合可以發動。對手場上的全部怪獸的攻擊力直到回合結束時下降1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46123974,'書靈師 極客少年',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的1隻儀式怪獸可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚成功的場合可以發動。從牌組將1張「書靈師」魔法卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46128076,'黑之魔導師 古蘭','我方的準備階段時，給予對手相當於對手場上的怪獸數量×300傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46130346,'火球','①：給予對手500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46132282,'甲化鎧骨骼',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡同步召喚成功的場合發動。這個回合，此卡不會被戰鬥、效果破壞，我方受到的全部傷害變成0。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46136942,'娛樂夥伴 異色眼溶解者',unistr('【靈擺效果】\u000a①：1回合1次，我方主要階段可以發動。從我方的手牌、場上將龍族融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：我方的靈擺怪獸和對手怪獸進行戰鬥的傷害步驟開始時可以發動。此卡從手牌特殊召喚，那隻我方怪獸不會被那次戰鬥破壞。\u000a②：我方主要階段可以發動。融合怪獸卡決定的包含此卡的融合素材怪獸從我方場上送去墓地，從額外牌組融合召喚那1隻融合怪獸。此時我方的靈擺區域存在的融合素材怪獸也能作為融合素材。'),'靈擺效果1','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46145256,'閃光的結界像','①：只要此卡在怪獸區域存在，雙方除了光屬性怪獸以外不能特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46148485,'轉輪的斯芬克斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：怪獸的表示形式變更的場合，從我方墓地將1張魔法卡除外可以發動。此卡從手牌、墓地特殊召喚。\u000a②：我方主要階段可以發動。從我方的牌組、墓地將「太陽之書」和「月之書」各最多1張在我方的魔法與陷阱區域覆蓋。\u000a③：1回合1次，場上的其他怪獸的表示形式變更的場合，以場上1張卡為對象可以發動。那張卡回到手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46159582,'咒法的儀水鏡',unistr('「咒法」儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計和儀式召喚的怪獸相同為止，從手牌儀式召喚1隻「咒法」儀式怪獸。\u000a②：讓墓地的此卡回到牌組，以我方墓地1隻「咒法」儀式怪獸為對象可以發動。那隻怪獸加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46169154,'戰吼者 奧比斯',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的怪獸，不存在的場合或只有戰士族怪獸的場合，此卡可以不用解放來召喚。\u000a②：我方的戰士族、地屬性怪獸進行戰鬥的傷害計算後可以發動。從牌組將「戰吼者 奧比斯」以外的1隻戰士族、地屬性怪獸送去墓地，那之後，我方場上的全部「戰吼者」怪獸的攻擊力直到對手回合結束時上升200。'),'不解放的召喚','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46173679,'終焉之焰',unistr('此卡發動的整回合中，我方不能用此卡的效果以外將怪獸召喚、反轉召喚、特殊召喚。\u000a①：在我方場上將2隻「黑焰衍生物」（惡魔族、闇、等級1、攻/守0）守備表示特殊召喚。這個衍生物不能為了闇屬性以外的怪獸的上級召喚而解放。'),'特殊召喚Token','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46173680,'黑焰衍生物','由「終焉之焰」的效果特殊召喚。這個衍生物不能為了闇屬性以外的怪獸的上級召喚而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46173681,'黑焰衍生物','由「終焉之焰」的效果特殊召喚。這個衍生物不能為了闇屬性以外的怪獸的上級召喚而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46174776,'殺戮聖徒 摩爾蕾吉娜',unistr('幻想魔族怪獸+等級6以上的惡魔族怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：以「殺戮聖徒 摩爾蕾吉娜」以外的我方墓地1隻幻想魔族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：「殺戮聖徒 摩爾蕾吉娜」以外的「聖徒」卡片或「罪寶」卡片的效果發動時，以場上最多2張卡為對象可以發動。那些卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46181000,'前線基地','1回合1次，在我方的主要階段，可以從手牌將1隻等級4以下的聯合怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46186135,'神光之龍',unistr('「裁決之龍」+「懲戒之龍」\u000a只能從我方的場上以及墓地各將1隻上述卡除外來特殊召喚。\u000a①：我方、對手回合1次，支付2000生命值可以發動。此卡以外的雙方的場上、墓地的卡全部除外。\u000a②：我方結束階段發動。從我方牌組上方將4張卡送去墓地。\u000a③：此卡被對手破壞的場合可以發動。我方的除外狀態的「裁決之龍」「懲戒之龍」各1隻加入手牌。那之後，可以將那2隻無視召喚條件特殊召喚。'),'效果1','效果2','效果3','是否無視召喚條件特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(46195773,'渦輪戰士',unistr('「渦輪同步者」+協調以外的怪獸1隻以上\u000a等級6以上的同步怪獸為攻擊對象的此卡的攻擊宣言時，攻擊對象怪獸的攻擊力直到傷害步驟結束時變成一半。\u000a場上的此卡不會成為等級6以下的效果怪獸的效果的對象。'),'攻擊對象的攻擊力變成一半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46221535,'鑽頭武裝龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將此卡和1隻風屬性怪獸送去墓地可以發動。這個回合中，我方場上的龍族、風屬性怪獸的攻擊力上升300。\u000a②：從我方墓地將任意數量的風屬性或等級7以上的龍族怪獸除外可以發動。從牌組將「鑽頭武裝龍」以外的1隻等級和除外的怪獸數量相同的龍族怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46232525,'海爾摩斯之爪',unistr('此卡的卡名在規則上也當作「傳說之龍 海爾摩斯」。「海爾摩斯之爪」在1回合只能發動1張。\u000a①：只能用「海爾摩斯之爪」的效果特殊召喚的融合怪獸卡記載的種族的1隻怪獸從我方的手牌、場上送去墓地（如果那張卡被覆蓋在場上，則翻開確認）。那之後，從額外牌組特殊召喚那1隻融合怪獸。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46237548,'紅蓮魔鬥士',unistr('①：此卡可以在我方墓地的通常怪獸是3隻的場合，將其中2隻除外，從手牌特殊召喚。\u000a②：1回合1次，以我方墓地1隻等級4以下的通常怪獸為對象可以發動。那隻怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46239604,'魔知青蛙',unistr('①：只要此卡在怪獸區域存在，卡名當作「死亡青蛙」。\u000a②：只要此卡在怪獸區域存在，對手不能選擇其他怪獸作為攻擊對象。\u000a③：此卡從場上送去墓地時可以發動。從我方的牌組、墓地選「魔知青蛙」以外的1隻「青蛙」怪獸加入手牌。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46241344,'炎星仙-鷲真人',unistr('獸戰士族怪獸2隻\u000a我方1回合只能特殊召喚1次「炎星仙-鷲真人」，那個②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方發動「炎星」怪獸的效果的場合，可以不用將我方的手牌、場上的「炎星」卡片以及「炎舞」卡片送去墓地來發動。\u000a②：以我方的場上、墓地1張「炎舞」魔法、陷阱卡為對象可以發動。那張卡回到持有者的手牌。那之後，從牌組將1隻「炎星」怪獸送去墓地。'),'是否不將卡片送去墓地來發動效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46247282,'鐵騎龍 創世母神機',unistr('此卡不能通常召喚，只能用此卡的①效果特殊召喚。這個卡名的①效果1回合只能使用1次。\u000a①：3張以上的卡在相同縱列存在的場合可以發動。此卡從手牌特殊召喚。此效果在對手回合也能發動。\u000a②：此卡特殊召喚成功的場合發動。和此卡相同縱列的其他卡全部破壞。\u000a③：只要此卡在怪獸區域存在，和此卡相同縱列的沒有使用的區域不能使用。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46247516,'陰陽師 道','侵蝕陰與陽的力量，產生出邪惡力量的魔道師。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46253216,'友方誤射','①：對手的魔法、陷阱、怪獸的效果發動時，以那張卡以外的場上1張卡為對象可以發動。對象卡片破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46259438,'契約洗淨','①：我方的魔法與陷阱區域的「契約書」卡片全部破壞。我方從牌組抽被破壞的數量的卡。那之後，我方回復抽牌數量×1000生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46261704,'星河栗子球',unistr('這個卡名在規則上也當作「銀河」卡片。\u000a①：對手怪獸的攻擊宣言時，將此卡從手牌捨棄可以發動。從手牌、牌組將1隻「銀河眼光子龍」特殊召喚。那之後，攻擊對象轉移到那隻怪獸。那之後，可以選我方或對手場上1隻超量怪獸，將墓地的此卡重疊在那隻怪獸下方作為超量素材。\u000a②：我方場上的「光子」怪獸或「銀河」怪獸被戰鬥或對手的效果破壞的場合，可以將墓地的此卡除外作為代替。'),'效果1','N/A','是否將此卡重疊在超量怪獸下方作為超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46263076,'地縛神 Ccapac Apu',unistr('「地縛神」怪獸在場上只能有1隻表側表示存在。\u000a沒有場地魔法卡表側表示存在的場合，此卡破壞。\u000a對手不能選擇此卡作為攻擊對象。\u000a此卡可以直接攻擊。\u000a此卡戰鬥破壞對手怪獸時，給予對手破壞的怪獸其原攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46271408,'閃刀術式-剪式交錯','①：我方的主要怪獸區域沒有怪獸存在的場合，以我方墓地1隻等級4的「閃刀姬」怪獸為對象可以發動。那隻怪獸加入手牌。我方墓地有3張以上魔法卡存在的場合，可以不加入手牌而是特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46272804,'長槍鱗蟲','①：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46290741,'城塞鯨魚',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在的場合，將我方場上2隻水屬性怪獸解放可以發動。此卡特殊召喚。\u000a②：此卡特殊召喚成功的場合可以發動。從牌組選1張「潛海奇襲」在我方場上覆蓋。\u000a③：1回合1次，對手發動只以我方場上的1隻水屬性怪獸為對象的魔法、陷阱、怪獸的效果時可以發動。那個發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46291010,'超能獸','①：此卡召喚成功時可以發動。從牌組將1隻超能族怪獸除外。此卡的等級變成和此效果除外的怪獸的等級相同。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46294982,'女巫特露德',unistr('①：場地區域有「斯特朗堡的黃金城」存在的場合，此卡可以不用解放來召喚。\u000a②：1回合1次，場地區域有「斯特朗堡的黃金城」存在的場合，以場上1張卡為對象可以發動。那張卡破壞，這個回合此卡在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a③：此卡戰鬥破壞對手怪獸時，以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力上升400。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46303688,'輪盤爆彈','1回合1次，我方主要階段可以發動。擲2次骰子。選擇1個擲出點數，選擇場上1隻等級和那個數值相同的表側表示怪獸破壞。','擲骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46337945,'儀水鏡的冥想術','向對手展示手牌的1張儀式魔法卡，選擇我方墓地的2隻「咒法」怪獸可以發動。選擇的墓地的怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46354113,'火箭海爾摩斯砲',unistr('此卡只能用「海爾摩斯之爪」的效果將我方的手牌、場上的戰士族怪獸送去墓地來特殊召喚。\u000a①：此卡特殊召喚成功的場合，以此卡以外的場上1隻怪獸為對象發動。此卡當作裝備卡給那隻怪獸裝備。\u000a②：用此卡的效果裝備此卡的怪獸在1次戰鬥階段中可以攻擊2次，向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46358784,'高等寶玉獸 翡翠龜',unistr('①：場地區域沒有「高等黑暗」存在的場合，這隻怪獸送去墓地。\u000a②：1回合1次，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的表示形式變更。此效果在對手回合也能發動。\u000a③：表側表示的此卡在怪獸區域被破壞的場合，可以不送去墓地當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46363422,'熟練的白魔導師',unistr('只要此卡在場上表側表示存在，每次我方或對手發動魔法卡，給此卡放置1個魔力計數器（最多3個）。\u000a將已放置3個魔力計數器的此卡解放可以發動。從我方的手牌、牌組、墓地選1隻「爆裂劍士」特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46372010,'地獄門的契約書',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方主要階段可以發動。從牌組將1隻「DD」怪獸加入手牌。\u000a②：我方準備階段發動。我方受到1000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46382143,'源數創造',unistr('這個卡名在規則上也當作「銀河眼」卡片。這個卡名的效果1回合只能適用1次。\u000a①：原攻擊力是3000以上的龍族、光屬性怪獸在場上有3隻以上存在的場合可以發動。從額外牌組將1隻龍族的「No.」超量怪獸特殊召喚。那之後，場上的此卡重疊在那隻怪獸下方作為超量素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46384403,'迅捷蝠魟','場上的此卡被效果送去墓地時，可以從牌組將任意數量的「迅捷蝠魟」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46384672,'武裝龍 LV5',unistr('①：從手牌將1隻怪獸送去墓地，以對手場上1隻表側表示怪獸為對象可以發動。持有為了發動此效果而送去墓地的怪獸的攻擊力以下的攻擊力的那隻對手怪獸破壞。\u000a②：此卡戰鬥破壞怪獸的回合的結束階段，將場上的此卡送去墓地可以發動。從手牌、牌組將1隻「武裝龍 LV7」特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46396218,'背信聖徒 雷亞西爾維亞',unistr('幻想魔族怪獸+魔法使族、光屬性怪獸\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：「背信聖徒 雷亞西爾維亞」以外的我方的「聖徒」怪獸給予對手的戰鬥傷害變成2倍。\u000a②：對手發動魔法、陷阱、怪獸的效果時，將此卡解放可以發動。那個效果無效。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從牌組將1張「罪寶」陷阱卡加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46404281,'熔岩岩漿砲兵','從手牌將1隻炎屬性怪獸送去墓地可以發動。給予對手500傷害。這個效果1回合可以使用最多2次。','給予對手500傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46411259,'突然變異','①：將我方場上1隻怪獸解放可以發動。從額外牌組將1隻等級和那隻怪獸相同的融合怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46412900,'火山性皇帝',unistr('此卡不能通常召喚。只能從我方的場上（表側表示）、墓地將3隻炎族怪獸或1張「烈焰加農砲」卡片除外從手牌、墓地特殊召喚。我方1回合只能特殊召喚1次「火山性皇帝」。\u000a①：這個方法讓此卡特殊召喚時可以發動。給予對手相當於除外狀態的炎族怪獸數量×500傷害。那之後，可以從牌組將1張「火山性」陷阱卡在我方場上覆蓋。\u000a②：每次對手將怪獸特殊召喚，給予對手500傷害。'),'效果1','效果2','是否將1張「火山性」陷阱卡在我方場上覆蓋？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46425662,'元素軍刀 波濤',unistr('①：1回合1次，從手牌將1隻「元素軍刀」怪獸送去墓地，以我方墓地1隻「元素軍刀 波濤」以外的「元素軍刀」怪獸或「靈神」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：此卡在墓地存在的場合，1回合1次，宣言1個屬性可以發動。墓地的此卡直到回合結束時變成宣言的屬性。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46427957,'破滅之女神 茹茵',unistr('藉由「世界終滅」降臨。\u000a①：此卡的攻擊破壞對手怪獸時可以發動。此卡只有1次可以繼續攻擊。'),'連續攻擊','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46435376,'無限地獄賢者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。我方的手牌全部捨棄。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1隻「無限地獄」怪獸送去墓地。此效果在我方的手牌是0張的場合可以發動和處理。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46448938,'魔導書的神判',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：此卡發動的回合的結束階段，最多到此卡的發動後我方或對手發動的魔法卡數量，從牌組將「魔導書的神判」以外的「魔導書」魔法卡加入手牌。那之後，可以將1隻等級在此效果加入手牌的卡片數量以下的魔法使族怪獸從牌組特殊召喚。'),'N/A','是否從牌組特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46457856,'死黨恐龍','雖然體型小，性格卻很兇暴。常與同伴爭鬥。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46461247,'陷阱大師','反轉：以場上1張表側表示的陷阱卡或場上覆蓋的1張魔法、陷阱卡為對象發動。那張陷阱卡破壞（如果那張卡被覆蓋在場上，則翻開確認）。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46474915,'魔法幽靈','向對手施展法術，使敵人陷入混亂和恐懼，從而胡亂攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46480475,'不協和音',unistr('此卡發動後，在第3次的我方結束階段送去墓地。\u000a雙方玩家不能同步召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46485778,'新式魔廚的魚料理天使',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方場上有儀式怪獸存在的場合，以場上1隻怪獸為對象可以發動。此卡特殊召喚。那之後，對象怪獸的表示形式變更。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合，可以從以下效果選擇1個發動。\u000a●從牌組將1隻等級1儀式怪獸或1張「食譜」卡片加入手牌。\u000a●從我方墓地將任意數量的「食譜」卡片除外，從手牌將1隻等級和那個數量相同的「新式魔廚」儀式怪獸特殊召喚。\u000a②：場上的此卡被解放以表側加入額外牌組的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','●從牌組加入手牌','●從手牌特殊召喚','','','','','','','','','','','');
INSERT INTO texts VALUES(46497537,'噸豚咚咚',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力、守備力、等級之中，比原本數值高的數值變成原本數值。那之後，支付100的倍數的生命值（最多1000）。\u000a②：此卡在墓地存在，我方的生命值和對手相同的場合，我方主要階段可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46500985,'鍊成陣 構成',unistr('①：我方場上的「鍊裝」怪獸的攻擊力、守備力上升300。\u000a②：只要我方的靈擺區域有「鍊裝」卡片存在，效果怪獸以外的我方場上的「鍊裝」怪獸不受對手的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46502013,'嚇阻陷阱 －妖精之輪－','我方場上有2隻以上攻擊表示怪獸存在的場合，對手不能選擇攻擊力最低的怪獸為攻擊對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46502744,'應戰的G',unistr('①：對手發動包含將怪獸特殊召喚效果的魔法卡時可以發動。此卡從手牌特殊召喚。\u000a②：只要此卡的①效果特殊召喚的此卡在怪獸區域存在，送去墓地的卡不去墓地而是除外。\u000a③：此卡從場上送去墓地的場合可以發動。除了「應戰的G」以外，從牌組將1隻攻擊力1500以下的昆蟲族、地屬性怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46508640,'龍脈棲息者','①：此卡的攻擊力上升我方的魔法與陷阱區域的永續魔法卡數量×300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46518210,'溟界神-涅斐爾邃淵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在墓地存在的狀態，從我方或對手的手牌、牌組有怪獸被送去墓地的場合可以發動。此卡特殊召喚。此效果的發動後，直到下個回合結束時我方除了爬蟲類族怪獸以外不能特殊召喚。\u000a②：如果此卡已被從墓地特殊召喚，以「溟界神-涅斐爾邃淵」以外的我方墓地1隻怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46533533,'皮蒂','據說會給契約者帶來幸運，住在玻璃瓶中的可愛小傢伙。那個蓋子絕對不能打開。不管發生什麼事都絕對…。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46534755,'火焰烏賊','在水裡仍然被火焰熊熊包圍著的章魚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46552140,'魔救的勒皮他晶石',unistr('①：我方場上的岩石族怪獸的攻擊力、守備力上升500。\u000a②：1回合1次，我方主要階段可以發動。從牌組選最多5張「魔救」卡片以喜歡的順序放置在牌組最上方。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46565218,'撒旦老人',unistr('①：此卡可以將對手場上的1隻怪獸解放，從手牌表側守備表示特殊召喚到對手場上。\u000a②：此卡用此卡的①方法特殊召喚的回合的結束階段可以發動。我方抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46570372,'鎮魂的決鬥',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：雙方可以從自身墓地選1隻這個回合被戰鬥破壞的怪獸攻擊表示特殊召喚。此效果讓我方特殊召喚的怪獸是「E.HERO 新宇俠」的場合，這個回合，那隻怪獸和對手怪獸進行戰鬥的傷害步驟期間，那隻怪獸的攻擊力變成2倍。'),'是否從墓地將1隻怪獸攻擊表示特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46571052,'血蘭','此卡召喚成功時，可以從手牌將1隻「死亡石斛」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46572756,'真次世代終極人','①：場上的表側表示的此卡被破壞送去墓地時，以我方墓地2隻「次世代」怪獸為對象可以發動。那些怪獸回到牌組。','回到牌組','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46576366,'LL-天青石鶺鴒',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從牌組將1張「LL-」魔法、陷阱卡加入手牌。\u000a②：此卡在墓地存在的場合，以我方場上1隻「LL-」超量怪獸為對象可以發動。此卡重疊在那隻怪獸下方作為超量素材。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46589034,'RR-痛苦伯勞',unistr('這個卡名的效果1回合只能使用1次，將此卡作為超量召喚的素材的場合，除了鳥獸族怪獸的超量召喚以外不能使用。\u000a①：此卡在手牌存在的場合，以我方場上1隻「RR-」怪獸為對象可以發動。我方受到那隻怪獸的攻擊力或守備力之中較低數值的傷害，此卡從手牌特殊召喚。此效果特殊召喚的此卡的等級變成和對象怪獸的等級相同。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46593546,'DDD赦俿王 死亡降神',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：另一邊的我方的靈擺區域有卡存在的場合，以我方的場上、墓地1隻靈擺怪獸為對象可以發動。另一邊的我方的靈擺區域的卡特殊召喚，作為對象的靈擺怪獸在我方的靈擺區域放置。\u000a【怪獸效果】\u000a惡魔族等級10怪獸×2\u000a此卡也能重疊在我方場上的「DDD」怪獸上方來超量召喚。\u000a①：「DDD赦俿王 死亡降神」在我方的怪獸區域只能有1隻表側表示存在。\u000a②：對手場上的怪獸卡的效果發動時可以發動（同一連鎖上最多1次）。去除此卡的2個超量素材或將我方場上1張「契約書」卡片破壞，那張對手的卡作為此卡的超量素材。\u000a③：我方準備階段可以發動。此卡在我方的靈擺區域放置。'),'是否重疊在「DDD」怪獸上方來超量召喚？','靈擺效果1','效果2','效果3','請選擇要放置在靈擺區域的卡','去除此卡的2個超量素材','我方場上1張「契約書」卡片破壞','','','','','','','','','');
INSERT INTO texts VALUES(46606977,'星義傘護獸',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以「星義傘護獸」以外的被除外的1隻我方怪獸為對象可以發動。此卡從手牌特殊召喚，對象怪獸回到牌組。\u000a②：以「星義傘護獸」以外的我方墓地1隻「星義」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46609443,'混沌終結王','此卡戰鬥破壞對手怪獸送去墓地時，可以從牌組將1隻等級5以上攻擊力1600以下的怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46613515,'清淨栗子球',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：對手發動給予傷害的怪獸的效果時，將此卡從手牌捨棄可以發動。那個發動無效。\u000a②：對手怪獸的直接攻擊宣言時，將墓地的此卡除外可以發動。我方從牌組抽1張卡。那張抽到的卡是怪獸的場合，隨後可以將那隻怪獸特殊召喚。那之後，攻擊對象轉移到那隻怪獸。'),'發動無效','抽1張牌','是否特殊召喚抽到的怪獸？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46640168,'刻魔 落淚之日',unistr('惡魔族、光屬性怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡融合召喚的場合，以我方的墓地、除外狀態的1隻惡魔族、光屬性怪獸為對象可以發動。那隻怪獸加入手牌或特殊召喚。\u000a②：只要此卡在怪獸區域存在，對手場上的怪獸的攻擊力下降600。\u000a③：此卡被送去墓地的場合，從我方墓地讓1隻其他的惡魔族、光屬性怪獸回到牌組、額外牌組可以發動。給予對手1200傷害。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46647144,'星遺物-『星槍』',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：包含連結怪獸的怪獸之間進行戰鬥的傷害計算時，將此卡從手牌捨棄可以發動。那隻進行戰鬥的對手怪獸的攻擊力下降3000。\u000a②：只要此卡在怪獸區域存在，對手不能攻擊其他的「星遺物」怪獸。\u000a③：怪獸從額外牌組特殊召喚的場合發動。在雙方場上將「星遺物衍生物」（機械族、闇、等級1、攻/守0）各1隻守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46647145,'星遺物衍生物','由「星遺物-『星槍』」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46652477,'轉生的預言','①：以雙方墓地的卡合計2張為對象可以發動。那些卡回到持有者的牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46656406,'咒言之鏡','對手從牌組將怪獸特殊召喚時可以發動。那些怪獸破壞，我方從牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46657337,'姆卡姆卡','此卡的攻擊力和守備力上升我方的手牌的數量×300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46659709,'銀河戰士',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：從手牌將1隻其他的光屬性怪獸送去墓地可以發動。此卡從手牌守備表示特殊召喚。\u000a②：此卡特殊召喚時可以發動。從牌組將1隻「銀河」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46660187,'戰吼者重擊',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方、對手主要階段，我方場上的表側表示的「戰吼者」怪獸因對手的效果從場上離開的場合可以發動。選對手場上最多2張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46668237,'森之番人 綠狒狒','①：此卡在手牌、墓地存在，我方場上的表側表示的獸族怪獸被效果破壞送去墓地時，支付1000生命值可以發動。此卡特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46696593,'紅陽鳥','「聖鳥」+「天空獵人」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46700124,'機械王','場上表側表示存在的機械族怪獸每有1隻，此卡的攻擊力上升100。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46701379,'華爾裘蓮 五女',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的「華爾裘蓮」怪獸的攻擊力上升被除外的對手怪獸數量×200。\u000a②：我方場上有「華爾裘蓮 五女」以外的「華爾裘蓮」怪獸存在的場合可以發動。從牌組將1張魔法、陷阱卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46708514,'凝視蒼穹的黑暗',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡在墓地存在的狀態，對手發動的怪獸的效果從牌組或額外牌組將怪獸特殊召喚的場合可以發動。此卡特殊召喚。\u000a②：包含將怪獸特殊召喚效果的怪獸的效果發動時，從我方的手牌、場上將1張卡除外可以發動。那個效果無效並破壞。\u000a③：此卡被除外的回合的結束階段可以發動。我方的除外狀態的1隻其他怪獸回到墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46710683,'BF-銀盾之密斯特拉爾','場上的此卡被破壞送去墓地的場合，這個回合我方受到的戰鬥傷害只有1次變成0。','戰鬥傷害變成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46718686,'海星葵','因被汙染的水而兇暴化的海星。從口中吐出溶解液。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46724542,'電子龍勝者',unistr('包含「電子龍」的機械族怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「電子龍」。\u000a②：此卡沒有攻擊宣言的我方、對手的戰鬥階段，以我方場上1隻攻擊力2100以上的機械族怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到回合結束時上升2100。此效果的發動後，直到回合結束時此卡的戰鬥給予雙方的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46759931,'V.HERO 三重人',unistr('「HERO」怪獸×3\u000a①：此卡不能直接攻擊。\u000a②：此卡融合召喚時適用。此卡的攻擊力直到回合結束時變成原攻擊力的2倍。\u000a③：融合召喚的此卡在1次戰鬥階段中可以攻擊3次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46772449,'勵輝士 入魔蠅王',unistr('等級4怪獸×2\u000a①：我方主要階段以及對手戰鬥階段，對手的手牌、場上的卡片數量比我方的手牌、場上的卡片數量多的場合，去除此卡的1個超量素材可以發動（同一連鎖上最多1次）。場上的其他卡全部破壞。此效果的發動後，直到回合結束時對手受到的全部傷害變成0。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46789706,'機雷化的栗子球',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，場上有「栗子球」怪獸卡存在的場合可以發動。此卡特殊召喚。\u000a②：對手場上的怪獸的效果發動時可以發動。我方場上的此卡當作持有以下效果的裝備魔法卡給那隻對手怪獸裝備。\u000a●裝備怪獸的效果無效化。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46796664,'DD魔導賢者 哥白尼',unistr('【靈擺效果】\u000a①：我方除了「DD」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a②：此卡在靈擺區域存在期間只有1次，給予我方傷害的魔法卡的效果的處理時，可以讓那個效果無效。那之後，此卡破壞。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。除了「DD魔導賢者 哥白尼」以外，從牌組將1張「DD」卡片或「契約書」卡片送去墓地。'),'送去墓地','是否用「DD魔導賢者 哥白尼」的靈擺效果將魔法卡無效？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46804536,'燃燒拳手 王者鄧普西',unistr('等級4怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合可以發動。從牌組選1隻等級4以下的戰士族、炎屬性怪獸或1張「燃燒拳擊」魔法、陷阱卡，加入手牌或是送去墓地。\u000a②：我方、對手回合可以發動。去除我方場上的1個超量素材，適用以下效果。\u000a●這個回合中，對手不能將我方場上的「燃燒拳手」怪獸作為效果的對象。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46809548,'機巧牙-御神尊真神',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：被除外的我方的卡是6張以上的場合，此卡可以不用解放來召喚。\u000a②：此卡召喚、特殊召喚成功的場合，從手牌捨棄1隻怪獸可以發動。從牌組將「機巧牙-御神尊真神」以外的1隻攻擊力和守備力數值相同的怪獸加入手牌。\u000a③：怪獸區域的此卡被破壞的場合可以發動。選被除外的6張我方的卡回到牌組。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46815301,'游魊之雙角 阿斯坎',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合，以我方場上1隻魚族怪獸和對手場上1張卡為對象可以發動。那些卡除外。\u000a②：此卡被除外的場合，從我方墓地將1隻魚族怪獸除外可以發動。此卡特殊召喚。'),'場上的卡除外','此卡特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46820049,'地獄將軍 梅菲斯特',unistr('此卡攻擊守備表示怪獸時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a此卡給予對手戰鬥傷害時，對手的手牌隨機選1張捨棄。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46821314,'擬人史萊姆','身體中組合了人類的遺傳因子。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46833854,'魔轟神 多比','①：我方的手牌比對手少2張以上的場合，向對手展示手牌的1隻「魔轟神」怪獸，將此卡解放，以對手場上2張魔法、陷阱卡為對象可以發動。那些對手的卡破壞。','破壞魔法陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46848859,'船艦機人','對手以我方場上的魔法、陷阱卡為對象將持有「將場上的魔法、陷阱卡破壞」效果的卡片發動時，可以藉由捨棄1張手牌，那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46864967,'岩之戰士','岩石戰士。揮舞著非常重的石頭劍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46871387,'No.55 隆隆隆歌利亞',unistr('等級4怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方場上的怪獸的守備力上升800。\u000a②：去除此卡的1個超量素材，以我方墓地1隻岩石族、地屬性、等級4怪獸為對象可以發動。那隻岩石族、地屬性怪獸加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46874015,'六武眾推參！','選擇我方墓地1隻「六武眾」怪獸可以發動。那隻怪獸從墓地特殊召喚。此效果特殊召喚的怪獸在這個回合的結束階段時破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46877100,'恐懼爪牙 高處恐懼獸',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：此卡可以從手牌往與我方場上的「恐懼爪牙」怪獸相鄰或相同縱列的我方的主要怪獸區域特殊召喚。\u000a②：只要此卡在怪獸區域存在，額外怪獸區域的我方的「恐懼爪牙」怪獸的攻擊力上升我方場上的守備表示怪獸數量×300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46895036,'鬼計無頭騎士',unistr('等級1怪獸×2\u000a①：此卡的攻擊力上升我方場上的「鬼計」卡片數量×200。\u000a②：1回合1次，去除此卡的1個超量素材，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時變成一半。此效果在對手回合也能發動。\u000a③：此卡被送去墓地的場合，以此卡以外的我方墓地1張「鬼計」卡片為對象可以發動。那張卡加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46897277,'電力狐狸','此卡被對手破壞的場合，這個回合對手不能將怪獸特殊召喚，也不能發動魔法、陷阱、效果怪獸的效果。','對手不能特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46898368,'逆卷之炎的寶牌',unistr('這個卡名在規則上也當作「轉生炎獸」卡片。這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了炎屬性怪獸以外不能召喚、特殊召喚。\u000a①：對手場上的卡片數量比我方場上的卡片多的場合，以對手場上1隻連結怪獸為對象可以發動。我方抽那隻怪獸的連結標記數量的卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46910446,'地獄聯盟','場上每存在1隻表側表示、與裝備怪獸同名的怪獸，裝備怪獸的攻擊力上升800。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46918794,'火炎地獄','給予對手1000傷害，我方受到500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46924949,'領地恐龍',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在主要怪獸區域存在，額外怪獸區域的怪獸的效果無效化。\u000a②：此卡被戰鬥破壞時可以發動。從牌組將1隻「領地恐龍」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46925518,'鬼計的形代',unistr('只能在我方場上有「鬼計」怪獸存在的場合將此卡表側表示召喚。\u000a①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉的場合發動。這個回合的結束階段，場上的表側表示怪獸全部變成裡側守備表示。那之後，可以從牌組將1隻等級在這個效果變成裡側守備表示的怪獸數量以下的「鬼計」怪獸裡側守備表示特殊召喚。'),'效果1','是否從牌組特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46935289,'虛光的宣告者',unistr('衍生物以外的相同種族、屬性的怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：魔法、陷阱卡的效果發動時，從手牌將1隻天使族怪獸送去墓地可以發動。那個發動無效並破壞。\u000a②：此卡被對手送去墓地的場合可以發動。從我方墓地的儀式怪獸以及儀式魔法卡之中選合計最多2張加入手牌（同名卡最多1張）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46939151,'地縛囚人 土地看守者',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。除了「地縛囚人 土地看守者」以外的1隻等級5以下的「地縛」怪獸從我方的牌組、墓地特殊召喚。此效果的發動後，直到回合結束時我方除了融合、同步怪獸以外不能從額外牌組特殊召喚。\u000a②：只要場地區域有卡存在，我方場上的「地縛」怪獸不會被戰鬥、效果破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46947713,'轉碼語者',unistr('效果怪獸2隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡是互相連結狀態的場合，此卡以及此卡互相連結的怪獸的攻擊力上升500，對手不能將其作為效果的對象。\u000a②：以「轉碼語者」以外的我方墓地1隻連結3以下的電子界族連結怪獸為對象可以發動（此效果發動的整回合中，我方除了電子界族怪獸以外不能特殊召喚）。那隻怪獸在此卡指向的我方場上特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46955132,'童話動物 小兔好朋友',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：對手將怪獸召喚、特殊召喚的場合可以發動。此卡從手牌特殊召喚。那之後，可以將我方的手牌、場上的怪獸作為融合素材，將1隻「童話動物」融合怪獸融合召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻「童話動物」怪獸加入手牌。此效果將通常怪獸加入手牌的場合，隨後可以從手牌將任意數量的獸族怪獸特殊召喚。'),'效果1','效果2','是否融合召喚？','是否特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(46955770,'守墓的異端者','①：只要此卡在怪獸區域存在，且場上有「王家長眠之谷-死亡谷」存在，此卡不受此卡以外的效果影響。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46956301,'白鬥氣砂滑',unistr('水屬性協調+協調以外的怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡同步召喚的場合可以發動。從我方的手牌、墓地將1隻等級4以下的魚族怪獸守備表示特殊召喚。那之後，可以將1隻其同名怪獸從我方墓地特殊召喚。\u000a②：此卡被對手破壞送去墓地的場合，從我方墓地將1隻其他的水屬性怪獸除外可以發動。此卡當作協調特殊召喚。'),'','','是否再將1隻同名怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46961802,'交叉攻擊','選擇我方場上表側攻擊表示的2隻攻擊力相同的怪獸可以發動。這個回合，選擇的1隻怪獸可以向對手玩家直接攻擊。另1隻怪獸不能攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46967601,'詛咒之符','裝備怪獸被破壞讓此卡被送去墓地時，給予裝備怪獸的控制者送去墓地的裝備怪獸的原守備力數值的傷害。','效果傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46984349,'救魔的奇石',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻表側表示怪獸或我方墓地1隻怪獸除外可以發動此卡。此卡發動後變成等級和除外的怪獸的原等級相同的通常怪獸（魔法使族、光、攻/守0）在怪獸區域特殊召喚。此卡也當作陷阱卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46985799,'黑薔薇龍/爆裂',unistr('此卡不能通常召喚，只能用「爆裂模式」的效果特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡可以發動。此卡回到牌組，場上1隻怪獸的攻擊力變成0。\u000a②：此卡特殊召喚的場合，或對手場上有怪獸特殊召喚的場合可以發動。場上的卡全部破壞。\u000a③：此卡被破壞的場合可以發動。從我方墓地將1隻「黑薔薇龍」特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46986414,'黑魔導','在魔法使中，攻擊力、守備力都是最高等級。','','','','','','','','','','','','','','','','');
