INSERT INTO texts VALUES(89642993,'No.63 飯勺戰士',unistr('等級1怪獸×2\u000a這個卡名的效果1回合只能使用1次。\u000a①：可以去除此卡的1個超量素材，從以下效果選擇1個發動。\u000a●下個對手準備階段開始時，雙方玩家從牌組抽1張卡。\u000a●雙方玩家回復1000生命值。'),'啟動效果','●準備階段開始時抽1張卡','●回復1000生命值','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89662401,'轉生炎獸 孔雀',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上有「轉生炎獸 孔雀」以外的「轉生炎獸」怪獸召喚、特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：從手牌以及我方場上的表側表示的卡之中將1張「轉生炎獸」卡片送去墓地，以對手場上覆蓋的1張魔法、陷阱卡為對象可以發動。這個回合，那張覆蓋的魔法、陷阱卡不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89662736,'武尊神器-八咫','我方場上的獸戰士族的「武尊神」怪獸被對手怪獸選擇為攻擊對象時，將此卡從手牌送去墓地可以發動。攻擊怪獸的攻擊無效，給予對手那隻怪獸的攻擊力一半的傷害。「武尊神器-八咫」的效果1回合只能使用1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89693655,'亞空間戰鬥',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以下效果適用3次。\u000a●雙方各自從自身牌組挑選1隻攻擊力？以外的怪獸給雙方確認。攻擊力較高的怪獸加入挑選的玩家的手牌。攻擊力較低的怪獸破壞，挑選的玩家受到500傷害。攻擊力相同的場合，挑選的怪獸回到牌組。這個回合，雙方不能發動此效果讓自身挑選的怪獸以及那些同名怪獸的怪獸效果。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89698120,'華麗的潛入工作員','在此卡召喚成功時，陷阱卡不能發動。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89707961,'王家的守護者 斯芬克斯',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉召喚成功的場合發動。對手場上的怪獸全部回到持有者的牌組。\u000a③：場上的此卡被對手破壞的場合可以發動。從手牌、牌組將1隻岩石族、等級5怪獸裡側守備表示特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89718302,'凶暴牛鬼','投擲1次硬幣並猜正反面。如果猜對，給予對手1000傷害。如果猜錯，給予我方1000傷害。這個效果1回合只能在我方主要階段使用1次。','猜硬幣','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89719143,'決戰融合-最終結合','①：我方場上的融合怪獸和對手場上的融合怪獸進行戰鬥的戰鬥步驟，以那2隻融合怪獸為對象可以發動。那次攻擊無效，雙方玩家受到那2隻融合怪獸的攻擊力合計數值的傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89731911,'親善騎士','①：此卡被戰鬥破壞送去墓地的場合發動。雙方玩家可以從手牌將1隻等級4怪獸特殊召喚。','效果1','是否從手牌特殊召喚1隻等級4的怪獸？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89732524,'魔界通往冥界的巴士','①：此卡反轉的場合發動。從牌組將1隻光、闇屬性以外的惡魔族怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89739383,'奧義的魔導書',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將「奧義的魔導書」以外的1張「魔導書」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89743495,'斬機 除法',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將額外怪獸區域1隻我方的電子界族怪獸解放可以發動。從手牌以及我方墓地各選最多1隻電子界族、等級4怪獸特殊召喚。\u000a②：此卡被送去墓地的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89753095,'神鳴',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻雷族怪獸加入手牌。此卡的發動後，直到下個回合結束時，我方不能將此效果加入手牌的怪獸以及那些同名怪獸通常召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89770167,'炎熱刀 日珥','1回合1次，將我方墓地的1隻「熔岩」怪獸除外可以發動。此卡的攻擊力直到回合結束時上升300。此效果在對手回合也能發動。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89771220,'北極天熊龍輝巧極',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：從我方的手牌、場上將「北極天熊 大舀取號」和「龍輝巧-扶筐增二」各1張除外，從額外牌組將1隻「天極輝艦-熊斗龍巧」特殊召喚。場上有「北極天熊-勾陳一」或「龍輝巧-右樞α」存在的場合，也能將除外的卡其中1張從牌組除外。\u000a②：我方為了發動「北極天熊」、「龍輝巧」怪獸的效果而將怪獸解放的場合，可以將墓地的此卡除外作為代替。\u000a\u000a※天斗輝巧極'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89774530,'英豪挑戰者 雙長槍兵',unistr('此卡召喚成功時，可以從我方的手牌、墓地選1隻「英豪挑戰者 雙長槍兵」表側守備表示特殊召喚。\u000a此卡不能作為同步素材。將此卡作為超量素材的場合，除了戰士族怪獸的超量召喚以外不能使用。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89776023,'進化蟲 稜角鱗鱷',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從我方的手牌、墓地將1隻「進化蟲」怪獸裡側守備表示特殊召喚。\u000a②：我方主要階段可以發動。從牌組將1張「強制進化」或「突然進化」在我方場上覆蓋。\u000a③：我方場上的怪獸被戰鬥、效果破壞的場合，可以將我方場上1隻爬蟲類族、恐龍族怪獸解放作為代替。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89785779,'千年眼幻像師',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄，以對手場上1隻效果怪獸為對象可以發動。挑選我方場上1隻「眼納祭」融合怪獸或「納祭」，將作為對象的對手的效果怪獸當作來自那個效果的裝備卡來裝備。此效果在對手回合也能發動。\u000a②：場上有「眼納祭」融合怪獸或「納祭」特殊召喚的場合發動。墓地的此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89789152,'時空銀河螺旋',unistr('這個卡名的卡在1回合只能發動1張。我方場上有「銀河眼時空龍」怪獸存在的場合，此卡也能從手牌發動。\u000a①：以我方場上1隻龍族的「銀河」怪獸為對象可以發動。那隻表側表示怪獸直到回合結束時不會被戰鬥破壞，不受自身以外的卡的效果影響。'),'適用「時空銀河螺旋」的效果來發動','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89792713,'極星寶 雷瓦汀','選擇在這個回合以戰鬥破壞怪獸的場上表側表示存在的1隻怪獸可以發動。那隻怪獸破壞。應對此卡的發動，不能發動魔法、陷阱、效果怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89801755,'深淵的指名者','支付1000生命值，宣言種族和屬性各1個可以發動。對手從手牌或牌組將1張和宣言的種族、屬性相同的怪獸送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89809665,'焰聖騎士-杜平',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有已裝備裝備卡的怪獸存在的場合可以發動。此卡從手牌、墓地特殊召喚。此效果從墓地特殊召喚的此卡從場上離開的場合被除外。\u000a②：此卡在墓地存在的場合，以我方場上1隻戰士族怪獸為對象可以發動。此卡當作裝備魔法卡給那隻我方怪獸裝備。\u000a③：將裝備怪獸作為同步素材的場合，可以當作協調。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89810518,'爬蟲妖 梅杜莎','將1張手牌送去墓地，選擇對手場上1隻表側表示怪獸可以發動。那隻怪獸的攻擊力變成0，不能變更表示形式。','攻擊力變成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89812483,'金屬化強化反射裝甲',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻表側表示怪獸解放可以發動此卡。從我方的手牌、牌組、墓地將1隻記載「金屬化強化反射裝甲」的卡名的不能通常召喚的怪獸特殊召喚。那之後，可以將此卡當作持有以下效果的裝備卡給那隻怪獸裝備。\u000a●裝備怪獸的攻擊力、守備力上升400，不會被魔法、怪獸的效果破壞，對手不能將裝備怪獸作為魔法、怪獸的效果的對象。'),'N/A','N/A','是否裝備？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89818984,'花札衛－柳間小野道風－',unistr('此卡不能通常召喚。將「花札衛－柳間小野道風－」以外的我方場上1隻等級11的「花札衛」怪獸解放可以特殊召喚。\u000a①：此卡特殊召喚成功的場合發動。我方從牌組抽1張卡，給雙方確認。那是「花札衛」怪獸的場合，可以將那隻怪獸特殊召喚。不是的場合，那張卡送去墓地。\u000a②：將場上的此卡作為同步素材的場合，可以將包含此卡的全部同步素材怪獸當作等級2怪獸。'),'抽1張卡並給雙方確認','是否特殊召喚抽到的怪獸？','是否把所有同步素材怪獸當作等級2？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89824842,'蕾禍大輪首狩舞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：最多到我方場上的昆蟲族、植物族、爬蟲類族連結怪獸的種族種類的數量，以對手場上的卡為對象可以發動。那些卡破壞。\u000a②：不是在這個回合送去墓地的此卡在墓地存在的狀態，我方場上的表側表示的昆蟲族、植物族、爬蟲類族怪獸被戰鬥、效果破壞的場合，將此卡除外，以對手場上1隻怪獸為對象可以發動。那隻怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89832901,'密林的黑龍王','棲息在密林深處的漆黑龍王。咯吱咯吱的只知道啃食樹木。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89839552,'人偶兵卒',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：此卡可以直接攻擊。\u000a②：此卡給予對手戰鬥傷害時可以發動。從牌組將1張「升變」加入手牌。\u000a③：將墓地的此卡除外可以發動。從牌組將「人偶兵卒」以外的1隻戰士族、地屬性怪獸加入手牌。那之後，對手可以從自身牌組將1隻怪獸加入手牌。'),'效果1','效果2','是否從自身牌組將1隻怪獸加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89851827,'聖秘的龍騎士',unistr('龍族怪獸+魔法使族怪獸\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡的攻擊力下降我方的除外狀態的卡片數量×100。\u000a②：只要融合召喚的此卡在怪獸區域存在，對手場上的特殊召喚的龍族、魔法使族怪獸不能發動效果。\u000a③：以我方墓地的龍族和魔法使族怪獸各1隻為對象可以發動。其中1隻特殊召喚，另1隻回到牌組最下方。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89856523,'罡炎星-麟俊義',unistr('炎屬性協調+協調以外的「炎星」怪獸1隻以上\u000a此卡同步召喚成功時，可以從牌組選1張「炎舞」魔法、陷阱卡在我方場上覆蓋。\u000a只要此卡在場上表側表示存在，對手場上的怪獸的攻擊力下降我方場上表側表示存在的魔法、陷阱卡數量×100。'),'覆蓋','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89870349,'M.HERO 暴風',unistr('此卡只能用「假面變身」的效果特殊召喚。\u000a①：此卡特殊召喚的場合，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力變成一半。\u000a②：我方、對手回合1次，支付500生命值，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡回到手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89875646,'三重槍管旋轉',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●從我方墓地讓1隻龍族怪獸回到牌組。那之後，可以從牌組將和回去的怪獸卡名不同的1隻「槍彈」怪獸特殊召喚。\u000a●從我方墓地讓2隻龍族怪獸回到牌組。那之後，從我方墓地將1張場地魔法卡加入手牌。\u000a●從我方墓地讓3隻龍族怪獸回到牌組。那之後，從對手墓地讓最多3隻怪獸回到牌組。'),'效果1','●1隻回到牌組','●2隻回到牌組','●3隻回到牌組','是否特殊召喚？','','','','','','','','','','','');
INSERT INTO texts VALUES(89875647,'三重槍管旋轉',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●從我方墓地讓1隻龍族怪獸回到牌組。那之後，可以從牌組將和回去的怪獸卡名不同的1隻「槍彈」怪獸特殊召喚。\u000a●從我方墓地讓2隻龍族怪獸回到牌組。那之後，從我方墓地將1張場地魔法卡加入手牌。\u000a●從我方墓地讓3隻龍族怪獸回到牌組。那之後，從對手墓地讓最多3隻怪獸回到牌組。'),'效果1','●1隻回到牌組','●2隻回到牌組','●3隻回到牌組','是否特殊召喚？','','','','','','','','','','','');
INSERT INTO texts VALUES(89882100,'夜間攝擊','①：以對手場上覆蓋的1張魔法、陷阱卡為對象可以發動。覆蓋的那張卡破壞。應對此卡的發動，對手不能發動對象卡片。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89883517,'冤獄',unistr('「冤獄」在1回合只能發動1張。\u000a①：對手的手牌、場上的卡的合計數量比我方的手牌、場上的卡的合計數量多的場合，以場上1張表側表示的卡為對象可以發動。除了那張表側表示的卡以外，雙方玩家在這次決鬥中不能發動對象卡片的同名卡的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89893715,'熔岩炎舵輪','此卡被戰鬥破壞送去墓地時，可以從牌組將2隻「熔岩」怪獸送去墓地。','送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89899996,'D-精神','我方場上沒有「D-HERO」怪獸表側表示存在的場合，可以從手牌將1隻等級4以下的「D-HERO」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89904598,'恐龍人','人形的恐龍。雖然智慧很高，但攻擊力卻不怎麼強勁。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89907227,'白鬥氣雙頭神龍',unistr('同步怪獸協調+協調以外的怪獸1隻以上\u000a①：我方回合中此卡同步召喚成功時可以發動。在我方場上將1隻「神龍衍生物」（魚族、水、等級10、攻3300/守3000）守備表示特殊召喚。\u000a②：對手回合1次，我方場上沒有衍生物的場合可以發動。在我方場上將1隻「神龍衍生物」特殊召喚。\u000a③：此卡被對手的效果破壞送去墓地的場合，如果我方場上有「神龍衍生物」存在可以發動。此卡守備表示特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89907228,'神龍衍生物','由「白鬥氣雙頭神龍」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89914395,'妙爾尼爾的魔鎚','選擇我方場上1隻「極神」怪獸可以發動。這個回合，那隻怪獸在1次戰鬥階段中可以攻擊2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89928517,'通販賣員',unistr('①：1回合1次，我方主要階段可以發動。雙方玩家各自向對手展示1張手牌。展示的卡是相同種類的場合，依照那個種類適用以下效果。\u000a●怪獸：雙方玩家各自可以將展示的怪獸特殊召喚。\u000a●魔法：雙方玩家各自從牌組抽2張卡。\u000a●陷阱：雙方玩家各自從牌組選2張卡送去墓地。'),'N/A','是否特殊召喚展示的怪獸？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89932017,'同步獨徑',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方的牌組、墓地選1隻等級1協調加入手牌或特殊召喚。\u000a②：此卡在墓地存在，「廢品戰士」或記載那個卡名的怪獸在我方場上存在的場合可以發動。此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943723,'E.HERO 新宇俠','來自新宇空間的新E.HERO。與新宇俠接觸融合，發揮出未知的力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943724,'E.HERO 新宇俠','來自新宇空間的新E.HERO。與新宇俠接觸融合，發揮出未知的力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943725,'E.HERO 新宇俠','來自新宇空間的新E.HERO。與新宇俠接觸融合，發揮出未知的力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943726,'E.HERO 新宇俠','來自新宇空間的新E.HERO。與新宇俠接觸融合，發揮出未知的力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89948817,'朱羅紀火山',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方主要階段可以發動。我方場上1隻恐龍族怪獸破壞，從牌組將1隻「朱羅紀」怪獸特殊召喚。\u000a②：對手將怪獸特殊召喚的場合，如果這個回合對手已發動4次以上怪獸的效果可以發動。從額外牌組將1隻「朱羅紀隕星龍」當作同步召喚特殊召喚。\u000a③：我方場上的「朱羅紀」怪獸被效果破壞的場合，可以將我方墓地1隻恐龍族怪獸除外作為代替。'),'','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89959682,'王家的保衛者','守護王家數千年的兵士的木乃伊。其靈魂現在也決不饒恕任何入侵者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89974735,'魔法妖精 勃艮第',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在怪獸區域存在的狀態，對手的手牌被效果捨棄的場合可以發動。給予對手那個張數×400傷害。\u000a②：此卡被戰鬥破壞送去墓地時可以發動。對手的手牌隨機選1張捨棄。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89974904,'同步呼喚','①：以我方墓地1隻怪獸為對象可以發動。那隻怪獸效果無效特殊召喚，只用包含那隻怪獸的我方場上的怪獸為素材同步召喚1隻龍族、惡魔族的闇屬性同步怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89987208,'東方的英雄','傳說來自遙遠的東方國度的武士。手持的刀相當的銳利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89997728,'卡通目錄','①：從牌組將1張「卡通」卡片加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90000652,'R-ACE 消防戰車',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「R-ACE 消防戰車」以外的「R-ACE」怪獸召喚、特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：對手場上有怪獸特殊召喚的場合可以發動。從我方的手牌、牌組、墓地將1隻等級4以下的「R-ACE」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90011152,'搗蛋王國',unistr('1回合1次，藉由從手牌將1張「搗蛋」卡片送去墓地，選擇我方墓地的1隻「搗蛋」怪獸特殊召喚。\u000a只要我方場上有「搗蛋」怪獸表側表示存在，場上表側表示存在的全部怪獸的原本的攻擊力、守備力交換。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90011273,'後膛槍管龍',unistr('包含「槍彈」怪獸的龍族、闇屬性怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組將1張「槍管」魔法、陷阱卡加入手牌。\u000a②：我方、對手回合，以我方場上1隻闇屬性怪獸為對象可以發動。那隻怪獸的攻擊力上升500。對象怪獸不存在的場合，可以改成從牌組將1隻「槍彈」怪獸守備表示特殊召喚。'),'效果1','效果2','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90019393,'寶石騎士 紫翠石','①：解放此卡可以發動。從牌組將1隻「寶石騎士」通常怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90020065,'時間炸彈','反轉：我方準備階段，將此卡解放發動。我方場上的怪獸全部破壞，給予對手那個攻擊力的合計數值一半的傷害。','反轉效果','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90020780,'忍屍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡已在怪獸區域存在的狀態，從我方墓地有此卡以外的不死族怪獸特殊召喚的場合可以發動。我方從牌組抽1張卡。那之後，選1張手牌捨棄。\u000a②：墓地的此卡為了發動效果而被除外的場合，或被效果除外的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90027012,'兆手佛',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚成功的場合可以發動。從牌組將1隻儀式怪獸和1張儀式魔法卡加入手牌。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90036274,'清透翼疾速龍',unistr('【靈擺效果】\u000a「清透翼疾速龍」的靈擺效果1回合只能使用1次。\u000a①：將等級合計為7的我方場上的表側表示的1隻「疾行機人」協調和1隻協調以外的怪獸送去墓地可以發動。靈擺區域的此卡特殊召喚。\u000a【怪獸效果】\u000a協調+協調以外的風屬性怪獸1隻以上\u000a「清透翼疾速龍」的①怪獸效果1回合只能使用1次。\u000a①：以對手場上1隻從額外牌組特殊召喚的表側表示怪獸為對象可以發動。直到回合結束時，那隻怪獸的攻擊力變成0，效果無效化。此效果在對手回合也能發動。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90050480,'E.HERO 秩序新宇俠',unistr('「E.HERO 新宇俠」+屬性不同的「新空間俠」怪獸×3\u000a只能讓我方場上的上述卡回到牌組，從額外牌組特殊召喚（不需要「融合」）。\u000a①：此卡從額外牌組特殊召喚成功的場合可以發動。這個回合對手不能發動在場上發動的效果。應對此效果的發動，對手不能發動魔法、陷阱、怪獸的效果。\u000a②：結束階段發動。此卡回到額外牌組，對手場上的卡全部破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90075978,'W星雲隕石','場上裡側表示存在的怪獸全部變成表側守備表示。這個回合的結束階段，我方場上表側表示存在的爬蟲類族、光屬性怪獸全部變成裡側守備表示。那之後，我方從牌組抽那個數量的卡。那之後，可以從我方牌組將1隻等級7以上的爬蟲類族、光屬性怪獸特殊召喚。','是否特殊召喚1隻爬蟲類族怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90091224,'四天之龍 黑暗反叛超量龍',unistr('闇屬性等級4怪獸×2\u000a這個卡名在規則上也當作「魅影騎士團」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方以及對手場上的卡各自相同數量為對象可以發動。那些卡破壞。\u000a②：對手發動效果時，去除此卡的1個超量素材可以發動。將1隻闇屬性、階級4的超量怪獸重疊在我方場上的此卡上方當作超量召喚從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90091225,'四天之龍 黑暗反叛超量龍',unistr('闇屬性等級4怪獸×2\u000a這個卡名在規則上也當作「魅影騎士團」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方以及對手場上的卡各自相同數量為對象可以發動。那些卡破壞。\u000a②：對手發動效果時，去除此卡的1個超量素材可以發動。將1隻闇屬性、階級4的超量怪獸重疊在我方場上的此卡上方當作超量召喚從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90098780,'鍵魔人 囁囁哼唱',unistr('等級3怪獸×2\u000a①：此卡特殊召喚成功時，以我方墓地的1隻「魔人」超量怪獸為對象可以發動。那隻怪獸特殊召喚。那之後，可以將最多2張手牌重疊在那隻怪獸下方作為超量素材。\u000a②：1回合1次，去除此卡的1個超量素材，以我方場上的1隻「魔人」超量怪獸為對象可以發動。這個回合，那隻怪獸可以直接攻擊對手。'),'效果1','效果2','是否要選擇手牌成為超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90122655,'天魔大帝','①：只要此卡在怪獸區域存在，應對通常召喚的怪獸的效果的發動，對手不能發動魔法、陷阱、怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90126061,'No.5 亡朧龍 死亡客邁拉龍',unistr('等級5怪獸×2隻以上\u000a①：此卡的攻擊力上升此卡的超量素材數量×1000。\u000a②：持有超量素材的此卡可以向全部對手怪獸各攻擊1次。\u000a③：此卡進行戰鬥的戰鬥階段結束時，可以從以下效果選擇1個發動。\u000a●以我方墓地1隻怪獸為對象可以發動。那隻怪獸重疊在此卡下方作為超量素材。\u000a●以對手墓地1張卡為對象可以發動。那張卡回到對手的牌組最上方。'),'●選擇我方墓地的怪獸','●選擇對手墓地的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90135989,'雲魔物的驟雨','我方的準備階段時，給場上表側表示存在的全部怪獸各放置1個霧計數器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90140980,'搗蛋王',unistr('「搗蛋小綠」+「搗蛋小黃」+「搗蛋小黑」\u000a只要此卡在場上表側表示存在，對手的怪獸區域最多3格不能使用。'),'是否繼續選擇格子？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90147755,'炎之女暗殺者','反轉：從我方牌組上方將3張卡除外發動。給予對手800傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90156158,'星聖的超新生','選擇我方墓地的2隻「星聖」怪獸加入手牌。此卡發動的整回合中，我方不能進行戰鬥階段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90161770,'蜂軍-急射之鋼弩',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚成功時，以我方墓地1隻等級3以下的昆蟲族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a②：此卡被對手破壞的場合可以發動。從手牌、牌組將1隻「蜂軍」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90162951,'No.35 貪食捕鳥蛛',unistr('等級10怪獸×2\u000a①：只要此卡在怪獸區域存在，我方場上的怪獸的攻擊力、守備力上升我方和對手的生命值的差額。\u000a②：只要持有超量素材的此卡在怪獸區域存在，每次對手將怪獸特殊召喚，給予對手600傷害。\u000a③：1回合1次，去除此卡的1個超量素材可以發動。對手場上的攻擊力在此卡的攻擊力以下的怪獸全部破壞。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90164606,'黃金榮耀-旗鼓相當',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻「黃金榮耀」怪獸，或「黃金榮耀-旗鼓相當」以外的我方墓地1張「黃金榮耀」卡片為對象可以發動。那張卡回到手牌。\u000a②：攻擊力高於我方的生命值數值的怪獸在對手場上存在的場合，從我方墓地將此卡和1隻「黃金榮耀」怪獸除外可以發動。從額外牌組將1隻記載除外的怪獸的卡名的「黃金榮耀」怪獸特殊召喚。'),'回到手牌','從額外牌組特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90173539,'世界恐龍摔角',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上有「恐龍摔角手」怪獸存在的場合，雙方玩家在戰鬥階段只能用1隻怪獸攻擊。\u000a②：我方的「恐龍摔角手」怪獸的攻擊力只在向對手怪獸攻擊的傷害計算時上升200。\u000a③：對手場上的怪獸數量比我方場上的怪獸多的場合，將墓地的此卡除外可以發動。從牌組將1隻「恐龍摔角手」怪獸特殊召喚。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90176467,'夢魔鏡的逆徒-涅洛伊',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1隻「夢魔鏡的使徒-涅洛伊」加入手牌。那之後，可以將此卡變成光屬性。\u000a②：將我方場上1隻其他的「夢魔鏡」怪獸解放可以發動。從牌組挑選1隻等級與其不同的「夢魔鏡」怪獸，從牌組將1張在挑選的怪獸有記載卡名的「聖光的夢魔鏡」或「闇黑的夢魔鏡」加入手牌，挑選的怪獸守備表示特殊召喚。'),'效果1','效果2','是否將此卡變成光屬性？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90179822,'喜劇的死獄鄉演員',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：對手發動以我方場上的表側表示的「死獄鄉」卡片為對象的魔法、陷阱、怪獸的效果時，將此卡從手牌捨棄可以發動。那個效果無效。\u000a②：我方、對手回合，此卡在墓地存在的場合，將我方場上1隻融合怪獸解放可以發動。此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90200789,'忍法 超變化之術','選擇我方場上的1隻「忍者」怪獸和對手場上的1隻表側表示怪獸可以發動。選擇的怪獸送去墓地，從我方牌組將1隻等級在那個等級的總和以下的龍族、恐龍族、海龍族怪獸特殊召喚。此卡從場上離開時，那隻怪獸除外。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90207654,'極星天 古爾薇格',unistr('等級5以下的「極星」怪獸1隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。選我方的手牌、場上最多3張卡除外，將那個數量的「極星」怪獸從牌組守備表示特殊召喚。此效果發動過的回合，我方不能通常召喚，除了「極神」怪獸以外不能特殊召喚。\u000a②：只要此卡指向的區域有「極神」怪獸存在，對手不能將那隻怪獸作為效果的對象，不能選擇此卡作為攻擊對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90219263,'萬華鏡－華麗的分身－','①：場上有「神鷹女郎」存在的場合可以發動。從手牌、牌組將1隻「神鷹女郎」或「神鷹女郎三姊妹」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90238142,'神鷹通靈師',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「神鷹女郎」。\u000a②：只要我方場上有龍族怪獸存在，此卡的等級變成7。\u000a③：從手牌捨棄1張「神鷹」卡片可以發動。從牌組將「神鷹通靈師」以外的1隻「神鷹」怪獸守備表示特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90239723,'變形鬥士 修復裝備',unistr('①：從手牌將1隻「變形鬥士」怪獸送去墓地，以我方墓地1隻「變形鬥士」怪獸為對象可以發動此卡。對象怪獸特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸破壞。\u000a②：裝備怪獸不能變更表示形式。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90241276,'蛇眼炎燐',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡用抽牌以外的方法加入手牌的場合可以發動。此卡特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「蛇眼」魔法、陷阱卡加入手牌。\u000a③：此卡被送去墓地的場合，以我方墓地1隻炎屬性怪獸為對象可以發動。那隻怪獸當作永續魔法卡在原持有者的魔法與陷阱區域表側表示放置。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90243945,'白骨公主',unistr('①：只要此卡在墓地存在，卡名當作「白骨」。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1隻「白骨皇子」送去墓地。\u000a③：將我方的手牌、場上的此卡送去墓地可以發動。場上的全部怪獸的攻擊力、守備力直到回合結束時下降其等級或階級×300。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90246973,'力量鶴嘴鋤','1回合1次，可以選擇對手墓地的1隻等級在裝備怪獸的等級以下的怪獸除外，裝備怪獸的攻擊力直到回合結束時上升500。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90247311,'黃龍忍者',unistr('此卡只能用「忍者」怪獸或「忍法」卡片的效果特殊召喚。\u000a①：1回合1次，從手牌以及我方場上的表側表示的卡之中，將1隻「忍者」怪獸和1張「忍法」卡片送去墓地，以場上最多2張魔法、陷阱卡為對象可以發動。那些卡破壞。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90263923,'閃光吸收','選擇對手場上1隻表側表示的光屬性怪獸可以發動。我方場上的全部表側攻擊表示怪獸的攻擊力直到回合結束時上升選擇的怪獸的攻擊力數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90276649,'幻奏的歌姬 庫普萊',unistr('【靈擺效果】\u000a這個卡名的②靈擺效果1回合只能使用1次。\u000a①：我方除了光屬性怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a②：我方場上沒有「幻奏」怪獸以外的表側表示怪獸存在的場合可以發動。從牌組將1張「幻奏」魔法、陷阱卡加入手牌。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：此卡用通常抽牌以外的方法加入手牌的場合，向對手展示此卡可以發動。從我方的手牌、墓地將1隻等級4以下的「幻奏」怪獸特殊召喚。\u000a②：此卡在額外牌組表側存在的狀態，我方場上有「幻奏」融合怪獸特殊召喚的場合可以發動。此卡在我方的靈擺區域放置。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90290572,'代行者的近衛 月球',unistr('天使族怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合可以發動。從牌組將1張「天空的聖域」或記載那個卡名的卡送去墓地。場上或墓地有「天空的聖域」存在的場合，可以改成從我方的牌組、墓地選1隻「神秘的代行者 地球」加入手牌。\u000a②：將我方場上1隻天使族怪獸解放，以對手場上1張卡為對象可以發動。那張卡破壞。'),'從牌組送去墓地','破壞對手場上的卡','是否改成將「神秘的代行者 地球」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90299015,'吸血鬼的幽鬼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚成功的場合，從手牌以及我方場上的表側表示的卡之中，將此卡以外的1張「吸血鬼」卡片送去墓地可以發動。從牌組將1隻等級4以上的「吸血鬼」怪獸加入手牌，從牌組將1隻等級2以下的「吸血鬼」怪獸送去墓地。\u000a②：我方、對手的主要階段，將墓地的此卡除外，支付500生命值可以發動。將1隻「吸血鬼」怪獸召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90303176,'寂靜鮟鱇','①：我方場上有水屬性怪獸存在的場合，此卡可以從手牌特殊召喚。這個方法特殊召喚過的回合，我方不能從手牌將怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90303227,'K9-EX “狼人”',unistr('等級9怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：持有超量素材的此卡在1次戰鬥階段中可以攻擊多次，次數上限為那個數量。\u000a②：對手發動效果時，可以去除此卡的1個超量素材，依照發動回合適用以下效果。\u000a●我方回合：對手的場上以及墓地的卡各最多1張除外。\u000a●對手回合：確認對手的手牌，挑選其中1張直到結束階段表側除外。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90307498,'E.HERO 新宇智者',unistr('「E.HERO 新宇俠」+「尤貝爾」\u000a此卡只能用融合召喚來特殊召喚。這個卡名的②效果1回合只能使用1次。\u000a①：此卡和對手怪獸進行戰鬥的傷害計算前可以發動。給予對手那隻對手怪獸的攻擊力數值的傷害。\u000a②：表側表示的此卡因對手的效果從場上離開的場合，或被戰鬥破壞的場合可以發動。從手牌、牌組將1隻「新宇賢者」無視召喚條件特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90307777,'影靈衣的術士 修利特',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：儀式召喚1隻「影靈衣」儀式怪獸的場合，可以使用1張此卡作為儀式召喚所需等級數值的解放。\u000a②：此卡被效果解放的場合可以發動。從牌組將1隻戰士族的「影靈衣」儀式怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90311614,'冰結界的水影','①：我方場上的表側表示怪獸只有等級2以下的怪獸的場合，此卡可以直接攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90312154,'失落的聖域',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的③效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，從牌組選1張「天空的聖域」或記載那個卡名的魔法、陷阱卡在我方場上覆蓋。\u000a②：只要此卡在場上、墓地存在，卡名當作「天空的聖域」。\u000a③：從我方墓地將1隻天使族怪獸除外，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90315086,'噴射機鯊',unistr('這個卡名的②③效果1回合只有1次能使用其中1個。\u000a①：場上有水屬性超量怪獸存在的場合，此卡可以從手牌特殊召喚。這個方法特殊召喚過的回合，我方不能將「噴射機鯊」特殊召喚。\u000a②：我方主要階段可以發動。從牌組將1隻魚族的「鯊」怪獸或1張「超量」魔法、陷阱卡送去墓地。\u000a③：將此卡從墓地除外可以發動。從我方的牌組、墓地將1張「水波噴射機」卡片加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90330453,'魔女狩獵','場上表側表示存在的魔法使族怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90330454,'魔女狩獵','場上表側表示存在的魔法使族怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90337190,'魚雷魚','只要場上有「海」存在，此卡不受魔法卡的效果影響。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90351981,'自鳴天琴巴別塔',unistr('①：只要此卡在場地區域存在，原卡名包含「自鳴天琴」的我方場上的連結怪獸以及我方墓地的怪獸發動的效果，變成在對手回合也能發動的效果。\u000a②：不是在這個回合送去墓地的此卡在墓地存在的場合，將1張手牌送去墓地可以發動。此卡加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90357090,'銀牙','閃爍著銀光的狼，看起來雖美麗，但性格卻十分兇暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90359458,'業界龍頭',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組選1張卡，給雙方確認並放置在牌組最上方。那之後，對手從自身牌組選1張卡，給雙方確認並放置在自身牌組最上方。'),'請選擇要放在牌組最上方的卡','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90361010,'超重武者裝留 岩通',unistr('①：我方主要階段以我方場上1隻「超重武者」怪獸為對象可以發動。從我方的手牌、場上將這隻怪獸當作裝備卡給那隻我方怪獸裝備。\u000a②：用此卡的效果裝備此卡的怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將「超重武者裝留 岩通」以外的1隻「超重武者」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90361289,'機巧狐-宇迦之御魂稻荷',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：怪獸從牌組特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合，以對手場上1隻表側表示怪獸為對象可以發動。從手牌、牌組將1隻攻擊力和守備力數值相同且和對象怪獸屬性相同的怪獸特殊召喚。\u000a③：每次對手將怪獸召喚、特殊召喚成功發動。給予對手300傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90365482,'河伯',unistr('此卡不能特殊召喚。\u000a①：此卡召喚、反轉的場合，以場上1隻表側表示怪獸為對象可以發動。那隻表側表示怪獸當作靈魂怪獸，在結束階段回到持有者的手牌。\u000a②：此卡召喚、反轉的回合的結束階段發動。此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90374791,'武裝變換',unistr('從我方的手牌將1張裝備魔法卡送去墓地可以發動此卡。\u000a裝備怪獸戰鬥破壞怪獸的場合，裝備卡的控制者可以從我方墓地選擇1隻攻擊力在裝備怪獸的攻擊力以下的怪獸加入手牌。'),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90384300,'極超辰醒',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌以及我方場上的表側表示怪獸之中將2隻不能通常召喚的怪獸裡側表示除外可以發動。我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90386276,'無罪的罪寶',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：可以從以下效果選擇1個發動。\u000a●以我方的墓地、除外狀態的1隻「迪亞貝爾」怪獸為對象可以發動。選1張我方的手牌捨棄，對象怪獸特殊召喚。\u000a●以我方的魔法與陷阱區域的1張表側表示的怪獸卡為對象可以發動。那張卡特殊召喚。'),'●選擇墓地、除外狀態的怪獸','●選擇魔法與陷阱區域的怪獸卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90397998,'六武眾-火門',unistr('我方場上有「六武眾-火門」以外的「六武眾」怪獸存在的場合，1回合1次，可以選擇場上表側表示存在的1張魔法、陷阱卡破壞。此效果發動的整回合中，此卡不能攻擊宣言。\u000a場上表側表示存在的此卡被戰鬥、效果破壞的場合，可以將此卡以外的我方場上表側表示存在的1隻「六武眾」怪獸破壞作為代替。'),'破壞表側魔法陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90407382,'踢人魔','此卡特殊召喚成功時，可以將我方墓地的1張裝備魔法卡給此卡裝備。','裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90411554,'巖征龍-鏽蝕',unistr('這個卡名的①～④效果1回合只有1次能使用其中1個。\u000a①：從手牌將此卡和1隻地屬性怪獸捨棄到墓地，以我方墓地1隻怪獸為對象可以發動。那隻特殊召喚。\u000a②：從我方的手牌、墓地將2隻龍族或地屬性的怪獸除外可以發動。此卡從手牌、墓地特殊召喚。\u000a③：如果此卡已被特殊召喚，對手結束階段發動。此卡回到手牌。\u000a④：此卡被除外的場合可以發動。從牌組將1隻龍族、地屬性怪獸加入手牌。'),'此卡特殊召喚','返回手牌','墓地的怪獸特殊召喚','加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(90432163,'魅影騎士團 沾塵袍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在場上攻擊表示存在的場合，以場上1隻闇屬性怪獸為對象可以發動。此卡變成守備表示，對象怪獸的攻擊力、守備力直到對手回合結束時上升800。\u000a②：將墓地的此卡除外可以發動。從牌組將「魅影騎士團 沾塵袍」以外的1張「魅影騎士團」卡片加入手牌。'),'攻擊力、守備力上升','從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90434657,'死亡谷的王墓','場上有「守墓」怪獸以及「王家長眠之谷-死亡谷」存在的場合可以發動。效果怪獸的效果、魔法、陷阱卡的發動無效並破壞。「死亡谷的王墓」在1回合只能發動1張。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90434926,'漆黑的帷幕','在我方的抽牌階段抽到的卡是闇屬性怪獸時，可以藉由向對手展示那些卡，將那些卡送去墓地。那之後，可以從我方牌組抽1張卡。','送去墓地','是否抽1張牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90440725,'電子陰影守衛者',unistr('在對手主要階段可以發動。此卡發動後變成怪獸卡（機械族、地、等級4、攻/守?）在我方的怪獸區域特殊召喚。此卡也當作陷阱卡。\u000a以此卡為攻擊對象的對手怪獸的攻擊宣言時，此卡的攻擊力、守備力變成和對手的攻擊怪獸相同的數值。\u000a對手結束階段時，此卡在魔法與陷阱區域覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90444325,'巨石遺物 海基思',unistr('藉由「巨石遺物」卡片降臨。這個卡名的②效果1回合只能使用1次。\u000a①：此卡儀式召喚成功的場合可以發動。從牌組將1張「巨石遺物」魔法、陷阱卡加入手牌。\u000a②：我方主要階段可以發動。解放包含場上的此卡的我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻儀式怪獸。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448279,'天霆號 阿宙斯',unistr('等級12怪獸×2\u000a「天霆號 阿宙斯」在超量怪獸進行過戰鬥的回合有1次也能重疊在我方場上的超量怪獸上方來超量召喚。\u000a①：我方、對手回合，去除此卡的2個超量素材可以發動。場上的其他卡全部送去墓地。\u000a②：1回合1次，我方場上的其他卡被戰鬥或對手的效果破壞的場合可以發動。從手牌、牌組、額外牌組將1張卡作為此卡的超量素材。'),'是否重疊在超量怪獸上方來超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448280,'天霆號 阿宙斯',unistr('等級12怪獸×2\u000a「天霆號 阿宙斯」在超量怪獸進行過戰鬥的回合有1次也能重疊在我方場上的超量怪獸上方來超量召喚。\u000a①：我方、對手回合，去除此卡的2個超量素材可以發動。場上的其他卡全部送去墓地。\u000a②：1回合1次，我方場上的其他卡被戰鬥或對手的效果破壞的場合可以發動。從手牌、牌組、額外牌組將1張卡作為此卡的超量素材。'),'是否重疊在超量怪獸上方來超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448281,'天霆號 阿宙斯',unistr('等級12怪獸×2\u000a「天霆號 阿宙斯」在超量怪獸進行過戰鬥的回合有1次也能重疊在我方場上的超量怪獸上方來超量召喚。\u000a①：我方、對手回合，去除此卡的2個超量素材可以發動。場上的其他卡全部送去墓地。\u000a②：1回合1次，我方場上的其他卡被戰鬥或對手的效果破壞的場合可以發動。從手牌、牌組、額外牌組將1張卡作為此卡的超量素材。'),'是否重疊在超量怪獸上方來超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448282,'天霆號 阿宙斯',unistr('等級12怪獸×2\u000a「天霆號 阿宙斯」在超量怪獸進行過戰鬥的回合有1次也能重疊在我方場上的超量怪獸上方來超量召喚。\u000a①：我方、對手回合，去除此卡的2個超量素材可以發動。場上的其他卡全部送去墓地。\u000a②：1回合1次，我方場上的其他卡被戰鬥或對手的效果破壞的場合可以發動。從手牌、牌組、額外牌組將1張卡作為此卡的超量素材。'),'是否重疊在超量怪獸上方來超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90452877,'Kozmo-能術',unistr('「Kozmo-能術」在1回合只能發動1張。\u000a①：以我方場上1隻「Kozmo」怪獸為對象可以發動。那隻怪獸破壞，選對手的場上、墓地1張卡除外。'),'選擇對手場上的卡','選擇對手墓地的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90464188,'黑曜岩龍','只要此卡在場上表側表示存在，以我方場上的1隻闇屬性怪獸為對象的魔法、陷阱卡的效果無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90465153,'末那圓頂 普萊姆哈特',unistr('協調1隻以上+光屬性怪獸1隻\u000a①：同步召喚的此卡在1次戰鬥階段中可以攻擊多次，次數上限為那些作為同步素材的協調數量。\u000a②：對手不能將用「末那圓頂」協調為素材同步召喚的此卡作為效果的對象。\u000a③：同步召喚的表側表示的此卡因對手從場上離開的場合可以發動。我方的墓地、除外狀態的1隻「維薩斯-星霜」或攻擊力1500/守備力2100的怪獸特殊召喚。'),'效果2適用中','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90470931,'鬼神的連擊','選擇我方場上表側表示存在的1隻超量怪獸，將那些超量素材全部去除可以發動。這個回合，選擇的怪獸在1次戰鬥階段中可以攻擊2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90488465,'混沌創世神',unistr('此卡不能通常召喚。從我方墓地將光屬性和闇屬性的怪獸各1隻除外可以特殊召喚。這個卡名的效果1回合只能使用1次。\u000a①：從手牌特殊召喚的此卡存在的場合，從被除外的我方以及對手的怪獸之中以合計3隻為對象可以發動（同名卡最多1張）。其中1隻在我方場上特殊召喚，其餘以喜歡的順序回到持有者的牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90500169,'等級下降？','選擇場上1隻「LV」怪獸可以發動。選擇的怪獸回到持有者的牌組，從持有者的墓地選1隻包含那隻怪獸的卡名且「LV」更低的怪獸，無視召喚條件在持有者的場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90502999,'地盤沉下',unistr('指定2格沒有使用的主要怪獸區域可以發動。\u000a①：只要此卡在魔法與陷阱區域存在，指定的區域不能使用。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90506641,'魂之開封','①：對手場上有怪獸存在，我方場上有通常怪獸存在的場合可以發動。從牌組選5隻通常怪獸。其中1隻加入手牌，剩下的卡除外。','請選擇要加入手牌或除外的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90508760,'X-軍刀 艾爾貝倫','①：此卡直接攻擊給予對手戰鬥傷害的場合發動。對手的手牌隨機選1張捨棄。','捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90512490,'巨大蒼蠅',unistr('風屬性怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：場上的風屬性怪獸的攻擊力、守備力上升500，地屬性怪獸的攻擊力、守備力下降400。\u000a②：此卡被戰鬥、效果破壞的場合，以我方墓地1隻風屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90519313,'檢疫','①：我方、對手的結束階段以對手場上覆蓋的1張魔法、陷阱卡為對象可以發動此效果。確認那張卡，並回復原狀。','確認','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90555947,'大植然蓋亞星獅',unistr('地屬性同步怪獸×2\u000a①：只以場上1張卡為對象的魔法、陷阱、怪獸的效果發動時，將1張手牌送去墓地可以發動。那發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90557975,'上昇氣流','去除場上的全部霧計數器可以發動。給予對手去除的霧計數器的數量×300傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90576781,'爬蟲妖劇毒','我方場上有「爬蟲妖」怪獸表側表示存在的場合可以發動。選擇對手場上的1隻守備表示怪獸變成表側攻擊表示，那隻怪獸的攻擊力變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90579153,'D-HERO 敵托邦小子',unistr('「D-HERO」怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方墓地1隻等級4以下的「D-HERO」怪獸為對象可以發動。給予對手那隻怪獸的攻擊力數值的傷害。\u000a②：我方、對手回合，此卡的攻擊力和原攻擊力不同的場合，以場上1張卡為對象可以發動（傷害步驟不能發動）。那張卡破壞，此卡的攻擊力變成原本數值。'),'給予傷害','場上的1張卡破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90582719,'劍鬥獸 獨眼鬥士','以高攻擊力追上敵人的獨眼戰熊。被以恐怖的速度與重量為傲的得意拳法擊中之後還不倒下的傢伙是不存在的。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90583279,'八雷天神',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡可以將我方墓地1隻等級或階級是8的怪獸除外，從手牌特殊召喚。\u000a②：以我方墓地1隻等級或階級是8的儀式、融合、同步、超量怪獸為對象可以發動。那隻怪獸回到牌組。那之後，依照回去的怪獸種類適用以下效果。\u000a●儀式、融合：我方從牌組抽1張卡。\u000a●同步、超量：此卡的攻擊力上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90587641,'超重神將 遮那王-O',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。此卡特殊召喚。我方墓地沒有魔法、陷阱卡存在的場合，隨後讓那隻對手怪獸攻擊力變成0，效果無效化。\u000a【怪獸效果】\u000a協調+協調以外的怪獸1隻以上\u000a這個卡名在規則上也當作「超重武者」卡片。\u000a①：此卡可以在表側守備表示的狀態攻擊。那個場合，此卡用守備力當作攻擊力進行傷害計算。\u000a②：如果此卡已被同步召喚，1回合1次，我方、對手的戰鬥階段可以發動。從我方墓地以及我方的魔法與陷阱區域的表側表示的卡之中，選1張「超重武者」怪獸卡特殊召喚。那之後，可以將此卡在我方的靈擺區域放置。'),'靈擺效果1','效果2','是否將此卡在靈擺區域放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90590303,'No.41 泥睡魔獸 睡夢貘',unistr('等級4怪獸×2\u000a此卡的控制者在每次我方準備階段去除此卡的1個超量素材（不能去除的場合，此卡破壞）。\u000a①：只要此卡在怪獸區域攻擊表示存在，此卡不會被對手的效果破壞，對手不能將此卡作為效果的對象。\u000a②：只要此卡在怪獸區域守備表示存在，場上的表側表示怪獸變成守備表示，守備表示怪獸發動的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90590304,'No.41 泥睡魔獸 睡夢貘',unistr('等級4怪獸×2\u000a此卡的控制者在每次我方準備階段去除此卡的1個超量素材（不能去除的場合，此卡破壞）。\u000a①：只要此卡在怪獸區域攻擊表示存在，此卡不會被對手的效果破壞，對手不能將此卡作為效果的對象。\u000a②：只要此卡在怪獸區域守備表示存在，場上的表側表示怪獸變成守備表示，守備表示怪獸發動的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90592429,'大日神械細絲',unistr('只能給「大日神械」怪獸裝備。\u000a裝備怪獸攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a場上表側表示存在的此卡被送去墓地的場合，可以從我方牌組將1張「大日神械」魔法卡加入手牌。'),'檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90615639,'時間次元空洞',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方牌組洗牌。那之後，翻開我方牌組最上方的卡。翻開的卡是可以通常召喚的怪獸的場合，那隻怪獸特殊召喚。不是的場合，或不能特殊召喚的場合，翻開的卡回到牌組最上方或最下方。'),'','回到牌組最上方','回到牌組最下方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90616316,'魔轟神獸 天馬',unistr('此卡從手牌捨棄到墓地時，可以將此卡從墓地裡側守備表示特殊召喚。\u000a此卡反轉時，向對手展示手牌的1隻「魔轟神」怪獸可以發動。從牌組將1隻「魔轟神」怪獸送去墓地。'),'在我方場上覆蓋','送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90640901,'反轉爆破者',unistr('此卡只能向裡側守備表示怪獸攻擊。\u000a此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a此卡向裡側守備表示怪獸攻擊的場合，可以不進行傷害計算，那隻裡側守備表示怪獸破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90642597,'未來侍',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●1回合1次，將我方墓地的1隻怪獸除外可以發動。選擇場上的1隻表側表示怪獸破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90654356,'暗黑翼龍','此卡因戰鬥破壞以外的方法從場上送去墓地時，此卡回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90659259,'變形鬥士 變換裝備',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻機械族怪獸為對象可以發動。依照那隻怪獸的表示形式適用以下效果。\u000a●攻擊表示：從牌組將1隻和對象怪獸卡名不同的「變形鬥士」怪獸特殊召喚。那之後，對象怪獸回到持有者的牌組最上方。\u000a●守備表示：對象怪獸變成攻擊表示，從手牌將1隻等級4以下的機械族怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90660762,'隕星黑龍','「隕星龍」+「真紅眼黑龍」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90664684,'龍華襲焉',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：對手不能將我方場上的「龍華」怪獸作為效果的對象。\u000a②：我方的額外牌組（表側）或場上有「龍華」靈擺怪獸存在的場合，讓我方的手牌、墓地、除外狀態的2隻「龍華」怪獸回到牌組，以場上1隻怪獸為對象可以發動。那隻怪獸破壞。\u000a③：此卡被破壞的場合可以發動。永續陷阱卡以外的我方的牌組、墓地、除外狀態的1張「龍華」陷阱卡在我方場上覆蓋。'),'','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90664857,'電腦堺甲-甲甲',unistr('等級3怪獸×2隻以上\u000a①：1回合1次，去除此卡的1個超量素材，以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸直到對手回合結束時不會被戰鬥破壞。\u000a②：1回合1次，原本的種族、屬性相同的怪獸在我方墓地有2隻以上存在，此卡和對手怪獸進行戰鬥的傷害計算後可以發動。那隻對手怪獸除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90669991,'鳳梨型爆彈','我方將怪獸召喚成功時可以發動。對手場上的怪獸數量比我方場上的怪獸多的場合，將對手怪獸破壞直到變成相同數量為止。破壞的卡由對手挑選。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90673288,'閃刀姬-雫',unistr('水屬性以外的「閃刀姬」怪獸1隻\u000a我方1回合只能特殊召喚1次「閃刀姬-雫」。\u000a①：對手場上的怪獸的攻擊力、守備力下降我方墓地的魔法卡數量×100。\u000a②：此卡特殊召喚的回合的結束階段可以發動。從牌組將同名卡不在我方墓地存在的1張「閃刀」魔法卡加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90673289,'閃刀姬-雫',unistr('水屬性以外的「閃刀姬」怪獸1隻\u000a我方1回合只能特殊召喚1次「閃刀姬-雫」。\u000a①：對手場上的怪獸的攻擊力、守備力下降我方墓地的魔法卡數量×100。\u000a②：此卡特殊召喚的回合的結束階段可以發動。從牌組將同名卡不在我方墓地存在的1張「閃刀」魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90673413,'我我我復仇',unistr('①：以我方墓地1隻「我我我」怪獸為對象可以發動此卡。那隻怪獸特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸破壞。\u000a②：裝備怪獸變成超量素材讓此卡被送去墓地的場合發動。我方場上的全部超量怪獸的攻擊力上升300。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90681088,'真炎王 鳳凰不死鳥',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：原屬性是炎屬性的我方怪獸被戰鬥、效果破壞的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「炎王」魔法、陷阱卡加入手牌。\u000a③：此卡被破壞送去墓地的場合，下個準備階段發動。墓地的此卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90711610,'哥布林百鬼羅剎大參上',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻「哥布林」怪獸加入手牌。那之後，可以適用以下效果。\u000a●去除場上的1個超量素材，從手牌將1隻等級4以下的「哥布林」怪獸特殊召喚。\u000a②：將墓地的此卡除外可以發動。去除場上的1個超量素材。那之後，可以從我方墓地將1隻「哥布林」怪獸加入手牌。'),'','','是否從手牌特殊召喚？','是否從我方墓地將1隻怪獸加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(90724272,'闇薔薇的妖精',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：協調特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡在墓地存在的場合，將我方的手牌、場上1張卡送去墓地可以發動。此卡回到牌組最上方或最下方。'),'特殊召喚','回到牌組','牌組最上面','牌組最下面','','','','','','','','','','','','');
INSERT INTO texts VALUES(90726340,'龍魔人 龍騎士女王',unistr('等級4怪獸×2\u000a只要此卡在場上表側表示存在，「龍魔人 龍騎士女王」以外的我方的龍族怪獸不會被戰鬥破壞。\u000a此外，1回合1次，藉由去除此卡的1個超量素材，選擇我方墓地1隻等級5以上的龍族怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化，這個回合那隻怪獸不能攻擊。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90727556,'侵入魔的斥候',unistr('我方場上沒有魔法、陷阱卡存在的場合，在我方的主要階段1開始時可以發動。此卡從墓地特殊召喚。此效果發動的整回合中，我方不能將怪獸特殊召喚。\u000a只要此卡在場上表側表示存在，此卡不能為了「侵入魔」怪獸的上級召喚以外而解放，也不能作為同步素材。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90740329,'挑釁','對手回合的主要階段1，選擇我方場上1隻怪獸可以發動。只要那隻怪獸在場上存在，這個回合對手怪獸攻擊的場合，必須選擇那隻怪獸作為攻擊對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90740330,'挑釁','對手回合的主要階段1，選擇我方場上1隻怪獸可以發動。只要那隻怪獸在場上存在，這個回合對手怪獸攻擊的場合，必須選擇那隻怪獸作為攻擊對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90743290,'預言魔導老士 艾爾米特','只要此卡在場上表側表示存在，每次「魔導書」魔法卡發動，此卡的等級上升2，攻擊力上升300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90764871,'惡魔的盤上遊戲',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：額外怪獸區域的惡魔族怪獸的攻擊力上升1000。\u000a②：可以從以下效果選擇1個發動。\u000a●從我方的手牌、墓地將1隻惡魔族怪獸或1張「惡魔」卡片除外可以發動。從牌組將場地魔法卡以外的1張「惡魔」卡片加入手牌。\u000a●從牌組將1隻「惡魔」靈擺怪獸表側加入額外牌組。'),'●從牌組加入手牌','●加入額外牌組','請選擇要加入額外牌組的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90764875,'蛇頭食屍鬼','我方場上有「蛇頭食屍鬼」存在的場合，支付300生命值可以發動。此卡從手牌特殊召喚。「蛇頭食屍鬼」的效果1回合可以使用最多2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90788081,'百歲龍',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，我方主要階段可以發動。直到回合結束時，此卡的等級上升我方場上的卡片數量，此卡的攻擊力上升所升數值×100。\u000a②：此卡被送去墓地的場合，以我方場上1隻從額外牌組特殊召喚的表側表示怪獸為對象可以發動。那隻怪獸在場上表側表示存在期間只有1次不會被戰鬥、效果破壞。\u000a\u000a※百年龍'),'效果1','效果2','不會被戰鬥、效果破壞（百歲龍）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90790253,'羽神戰士','我方的結束階段時，可以讓此卡的表示形式變更。','變更表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90807199,'未界域的雷鳥',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。對手從我方的全部手牌中隨機選1張，我方捨棄那張卡。那是「未界域的雷鳥」以外的場合，隨後從手牌將1隻「未界域的雷鳥」特殊召喚，我方從牌組抽1張卡。\u000a②：此卡從手牌捨棄的場合，以對手場上覆蓋的1張卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90809975,'餅蛙',unistr('水族等級2怪獸×2\u000a①：雙方的準備階段，去除此卡的1個超量素材可以發動。從牌組將1隻「青蛙」怪獸特殊召喚。\u000a②：1回合1次，對手發動怪獸的效果、魔法、陷阱卡時，從我方的手牌、場上（表側表示）將1隻水族怪獸送去墓地可以發動。那個發動無效並破壞。那之後，可以將破壞的卡在我方場上覆蓋。\u000a③：此卡被送去墓地的場合，以我方墓地1隻水屬性怪獸為對象可以發動。將其加入手牌。'),'效果1','效果2','效果3','是否將破壞的卡在我方場上特殊召喚？','是否將破壞的卡在我方場上覆蓋？','','','','','','','','','','','');
INSERT INTO texts VALUES(90810762,'逆卷炎之精靈','此卡可以直接攻擊對手玩家。此卡的直接攻擊給予對手玩家戰鬥傷害時，此卡的攻擊力上升1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90812044,'連鎖召喚','①：我方場上有2隻以上超量怪獸存在的場合，以其中1隻階級最低的超量怪獸為對象可以發動。從額外牌組選1隻階級低於那隻怪獸的超量怪獸特殊召喚。此效果特殊召喚的怪獸不能直接攻擊，在結束階段回到額外牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90814668,'暴君種植場',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻效果怪獸解放可以發動。從我方墓地選1隻原本的種族、屬性和那隻怪獸相同的效果怪獸以外的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90829280,'尤貝爾的精靈',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合可以發動。從牌組選1張記載「尤貝爾」的卡名的魔法、陷阱卡加入手牌或在我方場上覆蓋。\u000a③：此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a④：此卡被破壞的場合可以發動。我方的手牌、牌組、墓地、除外狀態的1隻「尤貝爾」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90835938,'聖夜輝煌之龍',unistr('①：此卡從手牌的召喚、特殊召喚成功的場合，以場上1張卡為對象可以發動。那張卡破壞。\u000a②：場上的此卡不會被和闇屬性怪獸的戰鬥破壞，不會被闇屬性怪獸的效果破壞。\u000a③：1回合1次，此卡向對手怪獸攻擊的傷害步驟開始時可以發動。那隻對手怪獸直到結束階段除外。此效果發動的場合，此卡只有1次可以繼續攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90844184,'六劍獸','藉由「六劍獸的宣誓」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90846359,'群雄割據','①：只要此卡在魔法與陷阱區域存在，雙方場上各自只能有1種的種族的怪獸表側表示存在。雙方玩家在自身場上的表側表示怪獸的種族有2種以上的場合，必須送去墓地直到變成1種為止。','請決定保留哪個種族的怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90861137,'『焰聖劍-咎瓦尤斯』',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡裝備中的場合，以我方墓地1隻戰士族、炎屬性怪獸為對象可以發動。那隻怪獸加入手牌。那之後，此卡破壞。\u000a②：裝備怪獸被送去墓地讓此卡被送去墓地的場合可以發動。從手牌將1隻戰士族、炎屬性怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90873992,'戰士抹殺','場上表側表示存在的戰士族怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90876561,'傑克騎士','精通一切劍術的戰士。正義感非常強烈，為守護弱者而戰。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90880453,'耀聖～再邂的三重奏～',unistr('①：對手不能將我方的中央的主要怪獸區域的怪獸作為效果的對象。\u000a②：依照我方的中央的主要怪獸區域的怪獸的屬性，此卡得到以下效果。\u000a●炎、地：我方的同步怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a●水、風：我方場上的其他表側表示的魔法、陷阱卡不會被對手的效果破壞。\u000a●光、闇：我方受到的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90884403,'究極幻神 奧特美特爾・比希巴爾金',unistr('規則上此卡的等級當作12。此卡不能同步召喚，只能將我方場上的等級8以上且相同等級的協調和協調以外的怪獸各1隻送去墓地來特殊召喚。\u000a①：此卡不會被效果破壞，攻擊力上升場上的怪獸數量×1000。\u000a②：1回合1次，我方、對手的主要階段可以發動。在雙方場上將相同數量的「邪眼神衍生物」（惡魔族、闇、等級1、攻/守0）盡可能守備表示特殊召喚。這個回合此卡不能攻擊。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90884404,'邪眼神衍生物','由「究極幻神 奧特美特爾・比希巴爾金」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90885155,'機殼殼層 拒絕',unistr('【靈擺效果】\u000a①：我方除了「機殼」怪獸以外不能特殊召喚。這個效果不會被無效化。\u000a②：對手場上的怪獸的攻擊力下降300。\u000a【怪獸效果】\u000a①：此卡可以不用解放來召喚。\u000a②：特殊召喚或不解放來召喚的此卡的等級變成4，原攻擊力變成1800。\u000a③：通常召喚的此卡不受原本的等級或階級低於此卡的等級的怪獸發動的效果影響。\u000a④：解放「機殼」怪獸表側表示上級召喚成功的場合，此卡在1次戰鬥階段中可以攻擊2次，向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90887783,'龍之交感','向對手展示手牌的1隻龍族怪獸，從牌組將1隻和展示的怪獸等級相同的龍族怪獸加入手牌。那之後，展示的怪獸回到牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90908427,'鐵腕石魔','用鋼鐵做成的機械魔像，擁有恐怖的怪力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90925163,'跳舞妖精','只要此卡在我方場上表側守備表示存在，每次我方準備階段，我方回復1000生命值。','回復1000生命值','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90928333,'闇之量產工廠','①：以我方墓地2隻通常怪獸為對象可以發動。那些怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90934570,'侵略的侵蝕崩壞','選擇我方場上的1隻「入魔」怪獸除外，選擇對手場上的2張卡回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90939874,'六武式真傳天魔六段衝',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有3種以上「六武眾」同步怪獸存在的場合可以發動（為了發動此卡而必要的怪獸種類，我方場上的武士道計數器每有6個就減少1種）。對手場上的卡全部破壞。\u000a②：覆蓋的此卡被對手的發動的效果破壞的場合或除外的場合可以發動。從牌組、額外牌組將1隻「六武眾」怪獸或1隻「紫炎」效果怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90946420,'哥布林百鬼羅剎大重疊',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻超量怪獸為對象可以發動。將1隻「哥布林」超量怪獸重疊在作為對象的我方的超量怪獸上方，當作超量召喚從額外牌組特殊召喚，將此卡作為那個超量素材。\u000a②：將墓地的此卡除外，以我方場上1隻「哥布林」超量怪獸和我方或對手的墓地1張卡為對象可以發動。作為對象的墓地的卡成為作為對象的場上的怪獸的超量素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90951921,'先史遺產技術','選擇我方墓地1隻「先史遺產」怪獸可以發動。選擇的怪獸從遊戲中除外。那之後，確認我方牌組上方2張卡，從其中選1張加入手牌，剩下的卡送去墓地。「先史遺產技術」在1回合只能發動1張，此卡發動的整回合中，我方除了「先史遺產」怪獸以外不能特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90953320,'T.G. 高能司書',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡在怪獸區域存在的狀態，我方或對手將同步怪獸同步召喚的場合發動。此卡在場上表側表示存在的場合，我方抽1張卡。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90957527,'劍鬥獸 喬治',unistr('「劍鬥獸 斯巴達克斯」+「劍鬥獸」怪獸\u000a只能讓我方場上的上述卡回到牌組，從融合牌組特殊召喚（不需要「融合」）。\u000a此卡戰鬥破壞怪獸送去墓地時，給予對手破壞的怪獸的守備力數值的傷害。\u000a此卡進行戰鬥的戰鬥階段結束時，可以藉由讓此卡回到融合牌組，從牌組將「劍鬥獸 斯巴達克斯」以外的2隻「劍鬥獸」怪獸在我方場上特殊召喚。'),'傷害','特殊召喚','請選擇1隻「劍鬥獸 斯巴達克斯」','請選擇1隻「劍鬥獸」怪獸','','','','','','','','','','','','');
INSERT INTO texts VALUES(90960358,'卡通黑魔導女孩',unistr('此卡不能通常召喚。我方場上有「卡通世界」存在的狀態，解放我方場上的1隻怪獸可以特殊召喚。\u000a①：此卡的攻擊力上升雙方墓地的「黑魔導」「黑混沌之魔導」的數量×300。\u000a②：此卡在對手場上沒有卡通怪獸存在的場合，可以直接攻擊。存在的場合，只能選擇卡通怪獸作為攻擊對象。\u000a③：場上的「卡通世界」被破壞時，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90960359,'卡通黑魔導女孩',unistr('此卡不能通常召喚。我方場上有「卡通世界」存在的狀態，解放我方場上的1隻怪獸可以特殊召喚。\u000a①：此卡的攻擊力上升雙方墓地的「黑魔導」「黑混沌之魔導」的數量×300。\u000a②：此卡在對手場上沒有卡通怪獸存在的場合，可以直接攻擊。存在的場合，只能選擇卡通怪獸作為攻擊對象。\u000a③：場上的「卡通世界」被破壞時，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90963488,'睡眠之子','孩子被夢魘所操控永遠沉睡不再醒來。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90965652,'二量合成',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：可以從以下效果選擇1個發動。\u000a●從牌組將1張「化合電界」加入手牌。\u000a●從牌組將1張「完全燃燒」和1隻「化合獸」怪獸加入手牌。\u000a②：將墓地的此卡除外，以包含再次召喚狀態的二重怪獸的我方場上2隻表側表示怪獸為對象可以發動。直到回合結束時，作為對象的1隻怪獸的攻擊力變成0，另1隻怪獸的攻擊力上升那個原攻擊力數值。'),'效果1','●「化合電界」加入手牌','●「完全燃燒」和「化合獸」怪獸加入手牌','效果2','請選擇攻擊力變成0的怪獸','','','','','','','','','','','');
INSERT INTO texts VALUES(90969892,'部落衝鋒',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的怪獸的種族是3種以上的場合可以發動。向對手展示3隻和我方場上的怪獸種族相同的牌組的怪獸（相同種族最多1隻），對手從其中隨機選1隻。我方將那1隻怪獸加入手牌或特殊召喚。剩下的怪獸以喜歡的順序回到牌組下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90980792,'黑暗膠質機人','此卡召喚、反轉召喚、特殊召喚成功時，選擇場上1隻表側表示怪獸。只要那隻怪獸在場上表側表示存在，攻擊力下降800。','攻擊力下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91002901,'決鬥進化-爆裂區域',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的③效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從我方的牌組、墓地將1隻記載「爆裂模式」的卡名的怪獸加入手牌。\u000a②：「/爆裂」怪獸在特殊召喚的回合不會被戰鬥以及對手的效果破壞。\u000a③：支付2000生命值可以發動。這個回合只有1次，我方為了發動「爆裂模式」而解放的同步怪獸可以從額外牌組挑選。'),'效果1','效果3','是否將1張卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91011603,'極星工 伊瓦爾迪',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「極神」怪獸或「極星」怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「極星寶」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91019775,'廢鐵車庫',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的表側表示的機械族怪獸被戰鬥、效果破壞的場合，以我方墓地最多3隻機械族、闇屬性怪獸為對象可以發動。那些怪獸特殊召喚。此效果特殊召喚的怪獸的攻擊力、守備力變成0。\u000a②：將墓地的此卡除外，以我方場上1隻機械族怪獸為對象可以發動。那隻怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91020571,'地征龍-侵蝕',unistr('這個卡名的效果1回合只能使用1次。\u000a①：將1隻龍族或地屬性的怪獸和此卡從手牌捨棄可以發動。從牌組將1隻「巖征龍-鏽蝕」特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91025875,'K9-∅∅號 天狼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手已發動手牌、墓地的怪獸的效果的，我方、對手回合的主要階段可以發動。此卡從手牌、墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：對手回合可以發動。用包含此卡的我方場上的怪獸為素材進行超量召喚。\u000a③：持有此卡作為超量素材的超量怪獸得到以下效果。\u000a●對手不能將此卡作為效果的對象。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91027843,'海晶少女的鬥海',unistr('①：我方場上的「海晶少女」怪獸的攻擊力上升200，且上升裝備的「海晶少女」卡片數量×600。\u000a②：用「海晶少女 水晶之心」為素材連結召喚的額外怪獸區域的我方怪獸不受對手的效果影響。\u000a③：我方在額外怪獸區域將「海晶少女」連結怪獸連結召喚時可以發動。從我方墓地選最多3隻「海晶少女」連結怪獸，當作裝備卡給那隻連結召喚的怪獸裝備（同名卡最多1張）。'),'用「海晶少女 水晶之心」為素材','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91034681,'魔玩具 冒失鬼',unistr('「鋒利小鬼」怪獸+「絨毛動物」怪獸\u000a「魔玩具 冒失鬼」的②效果1回合只能使用1次。\u000a①：此卡戰鬥破壞對手怪獸時可以發動。給予對手1000傷害。\u000a②：表側表示的此卡因對手的效果從場上離開的場合，或被戰鬥破壞的場合可以發動。給予對手我方墓地的「魔玩具」怪獸數量×500傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91070115,'心電感應外星人',unistr('1回合1次，去除對手場上的怪獸放置的1個A計數器可以發動。選擇場上的1張魔法、陷阱卡破壞。\u000a只要此卡在場上表側表示存在，放置A計數器的怪獸和「外星人」怪獸進行戰鬥的場合，其攻擊力、守備力只在傷害計算時下降A計數器的數量×300。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91073013,'征服鬥魂 龍帝瓦利烏斯',unistr('這個卡名的①②效果1回合各能使用1次，不能在同一連鎖上發動。\u000a①：我方、對手的主要階段，以龍族以外的我方場上1隻「征服鬥魂」怪獸為對象可以發動。那隻怪獸回到手牌，此卡從手牌特殊召喚。\u000a②：我方、對手回合，可以從以下選擇1個，向對手展示那些屬性的手牌的怪獸各1隻發動。\u000a●地：這個回合，表側表示的此卡不受對手發動的效果影響。\u000a●地、炎、闇：選場上1張其他卡破壞。'),'效果1','●地','●地、炎、闇','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91078716,'花粉症',unistr('可以將我方場上的1隻植物族怪獸解放發動以下效果。\u000a●魔法、陷阱卡發動時可以發動。那個發動無效並破壞。\u000a●我方或對手將怪獸召喚、特殊召喚之際可以發動。使其無效，那些怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91098230,'古代機械齒輪戰車兵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從手牌將「古代機械齒輪戰車兵」以外的1隻「古代機械齒輪」怪獸無視召喚條件特殊召喚。對手場上有怪獸存在的場合，也能改成從我方墓地挑選。\u000a②：以我方場上1張表側表示卡為對象可以發動。那張卡破壞。這個回合中，我方場上的「古代機械齒輪巨人」以及記載那個卡名的怪獸的攻擊力上升600。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91107093,'電磁防護罩','我方場上表側守備表示存在的等級3以下的雷族怪獸不會被戰鬥破壞。我方場上有怪獸表側攻擊表示存在的場合，此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91110378,'光天使 座',unistr('將此卡作為超量召喚的素材的場合，除了以3隻以上怪獸為素材的超量召喚以外不能使用。\u000a①：我方將「光天使」怪獸召喚、特殊召喚成功的場合可以發動。此卡從手牌特殊召喚，我方從牌組抽1張卡。抽到的那張卡是「光天使」怪獸的場合，可以將那隻怪獸特殊召喚。'),'從手牌特召','是否特殊召喚抽到的怪獸？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91123920,'力之代行者 火星',unistr('①：場上的此卡不受魔法卡的效果影響。\u000a②：我方場上有「天空的聖域」存在，我方的生命值高於對手的場合，此卡的攻擊力、守備力上升那個差額。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91133740,'雪人吞食者','此卡反轉時，選擇場上表側表示存在的1隻怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91135480,'時間潛行者 雙條盒驅動員',unistr('等級4怪獸×2\u000a這個卡名的效果1回合只能使用1次。\u000a①：對手發動效果時可以發動。去除此卡的超量素材最多3種（怪獸、魔法、陷阱）。那之後，適用以下效果。\u000a●怪獸：此卡的攻擊力上升400。\u000a●魔法：選對手場上1隻表側表示怪獸，直到結束階段得到控制權。這個回合，那隻怪獸不能攻擊宣言，不能發動效果。\u000a●陷阱：選場上1隻效果怪獸，那個效果直到回合結束時無效。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91140491,'熾天蝶',unistr('卡名不同的怪獸2隻以上\u000a這個卡名的①③效果1回合只有1次能使用其中1個。\u000a①：此卡連結召喚成功的場合發動。依照作為此卡的連結素材的昆蟲族怪獸數量，給此卡放置計數器。\u000a②：此卡的攻擊力上升此卡的計數器數量×200。\u000a③：去除此卡的1個計數器可以發動。從我方墓地選1隻等級4以下的昆蟲族怪獸守備表示特殊召喚。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91148083,'諸神的黃昏','選擇我方場上1隻表側表示的「極神」怪獸可以發動。那隻怪獸的控制權轉移給對手。下個對手的結束階段時，那隻怪獸破壞，對手場上的卡全部除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152256,'精靈劍士','學習劍術的精靈。以快速的攻擊翻弄敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152257,'精靈劍士','學習劍術的精靈。以快速的攻擊翻弄敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152258,'精靈劍士','學習劍術的精靈。以快速的攻擊翻弄敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152455,'金屬化鋼炎裝甲',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻記載「金屬化強化反射裝甲」的卡名的表側表示怪獸解放可以發動此卡。從牌組將1隻記載「金屬化強化反射裝甲」的卡名的不能通常召喚的怪獸無視召喚條件特殊召喚。那之後，可以將此卡當作持有以下效果的裝備卡給那隻怪獸裝備。\u000a●裝備怪獸被戰鬥、效果破壞的場合，可以將此卡送去墓地作為代替。'),'效果1','是否當作裝備卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91182675,'魔導獸 胡狼',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：另一邊的我方的靈擺區域沒有卡存在的場合，以我方場上1張可以放置魔力計數器的卡為對象可以發動。此卡破壞，給那張卡放置1個魔力計數器。\u000a【怪獸效果】\u000a①：只要此卡在怪獸區域存在，每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a②：去除我方場上的3個魔力計數器，將此卡解放可以發動。從牌組將「魔導獸 胡狼」以外的1隻「魔導獸」效果怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91188343,'神秘的代行者 地球','①：此卡召喚成功時可以發動。從牌組將「神秘的代行者 地球」以外的1隻「代行者」怪獸加入手牌。場上有「天空的聖域」存在的場合，可以將加入手牌的怪獸改成1隻「主宰者 赫貝里翁」。','從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91215724,'廢品鎧甲',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：此卡用抽牌以外的方法加入手牌的場合可以發動。此卡特殊召喚。\u000a②：只要此卡在怪獸區域存在，對手不能將原卡名包含「戰士」或「星塵」的我方場上的同步怪獸作為效果的對象。\u000a③：將此卡解放可以發動。從牌組將「廢品鎧甲」以外的1隻「廢品」怪獸或「同步者」怪獸守備表示特殊召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91222209,'R-ACE 水砲滅火者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「R-ACE」陷阱卡加入手牌。\u000a②：對手發動場上的怪獸的效果時，將手牌、場上的此卡解放，以「R-ACE 水砲滅火者」以外的我方墓地1隻「R-ACE」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91228233,'迷花之森',unistr('①：已裝備「星空蝶」的我方怪獸不受對手發動的效果影響。\u000a②：1回合1次，我方的「勇者衍生物」戰鬥破壞怪獸時可以發動。我方從牌組抽1張卡。\u000a③：此卡的②效果發動的回合的我方主要階段可以發動1次。從我方的牌組、墓地選「迷花之森」以外的記載「勇者衍生物」的衍生物名的1張場地魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91231901,'「A」細胞轉殖裝置',unistr('①：以場上1隻表側表示怪獸為對象可以發動。從牌組將1隻「外星人」怪獸送去墓地，依照送去墓地的怪獸的等級數值，給對象怪獸放置A計數器。\u000a②：我方主要階段將墓地的此卡除外可以發動。從牌組將1隻「外星人」怪獸加入手牌。此效果在此卡送去墓地的回合不能發動。'),'從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91237821,'小丑戲幫 德比魯茲',unistr('等級3怪獸×2\u000a①：我方場上的上級召喚的怪獸的攻擊力上升1000。\u000a②：此卡被解放的場合，可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●雙方的場上、墓地的超量怪獸全部回到額外牌組。\u000a●從牌組將1張「小丑戲幫」魔法卡在我方場上覆蓋。'),'效果2','●超量怪獸回到牌組','●覆蓋魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91250514,'卷舌獸','上級召喚的此卡從場上送去墓地時，從我方牌組抽2張卡。那之後，將此卡除外。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91258852,'SPYRAL-高雅女士',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，我方主要階段可以發動。從牌組將1張「SPYRAL MISSION」卡片加入手牌。\u000a②：此卡從場上送去墓地的場合可以發動。從牌組將「SPYRAL-高雅女士」以外的1隻「SPYRAL」怪獸和1張「SPYRAL RESORT」加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91262474,'星塵亞龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌、墓地存在，我方場上有等級8以上的龍族同步怪獸存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：將此卡解放可以發動。從我方的手牌、墓地選「星塵亞龍」以外的最多2隻龍族、光屬性、等級1怪獸特殊召喚。此效果特殊召喚的怪獸不能發動效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91269402,'電子界信標',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：戰鬥或對手的效果讓我方受到傷害的回合可以發動。從牌組將1隻等級4以下的電子界族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91272072,'花樣明星樂團 吉他手歐白英',unistr('「花樣明星」連結怪獸+「花樣明星」怪獸\u000a①：和此卡連結狀態的我方的「花樣明星」連結怪獸的效果給予對手的傷害變成2倍。\u000a②：每次「花樣明星」怪獸的效果讓對手受到傷害發動。此卡的攻擊力上升那次傷害的數值。\u000a③：此卡攻擊過的回合的結束階段發動。此卡的②效果上升的數值回到0。那之後，可以從我方墓地選1隻「花樣明星」怪獸加入手牌。'),'效果2','效果3','是否從我方墓地選擇1隻「花樣明星」怪獸加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91279700,'入魔娥菲翁',unistr('等級4「入魔」怪獸×2\u000a①：只要持有超量素材的此卡在怪獸區域存在，雙方不能將等級5以上的怪獸特殊召喚。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。從牌組將1張「侵略的」魔法、陷阱卡加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91283212,'蜂軍-追擊之飛鏢',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的「蜂軍」怪獸戰鬥破壞原持有者是對手的怪獸時，將此卡從手牌捨棄可以發動。給予對手那隻怪獸的原攻擊力數值的傷害。\u000a②：以此卡以外的我方場上1隻昆蟲族怪獸為對象可以發動。這個回合，那隻怪獸當作協調。此效果的發動後，直到回合結束時我方除了昆蟲族怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91284003,'阿爾戈☆群星-飛燕的卡帕涅',unistr('①：只要此卡在魔法與陷阱區域存在，我方場上的戰士族怪獸不會被戰鬥破壞。\u000a②：1回合1次，怪獸區域有永續陷阱卡存在的場合可以發動。此卡當作持有以下效果的效果怪獸（戰士族、光、等級4、攻/守1800）在怪獸區域特殊召喚（也當作陷阱卡）。我方的「阿爾戈☆群星」怪獸已被除外的場合，隨後我方回復500生命值。\u000a●我方、對手回合1次，可以發動。此卡在我方的魔法與陷阱區域表側表示放置。'),'效果2','●在魔法與陷阱區域表側表示放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91286284,'黃金榮耀-神出鬼沒',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、墓地將1隻「黃金榮耀」怪獸特殊召喚。那之後，對手可以從自身的手牌、墓地將1隻怪獸效果無效在自身場上特殊召喚。'),'特殊召喚','是否從自身的手牌、墓地特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91299846,'雷天氣 薑黃',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：將我方場上1張表側表示的永續魔法、永續陷阱卡送去墓地可以發動。從牌組選1張「天氣」魔法、陷阱卡在我方的魔法與陷阱區域表側表示放置。\u000a②：場上的此卡為了發動「天氣」卡片的效果而被除外的場合，下個回合的準備階段可以發動。被除外的此卡特殊召喚。'),'效果1','被除外的此卡特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91300233,'騎甲蟲 殘酷撒旦',unistr('「騎甲蟲」怪獸+昆蟲族怪獸\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從牌組將1張「騎甲蟲」卡片加入手牌。\u000a②：只要此卡在怪獸區域存在，我方除了昆蟲族怪獸以外不能特殊召喚。\u000a③：昆蟲族怪獸被表側表示除外的場合，以被除外的1隻我方的「騎甲蟲」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91323605,'奇異界開',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的怪獸被對手的攻擊、效果破壞的場合可以發動。從牌組將同名卡不在場地區域存在的1張場地魔法卡在我方的場地區域表側表示放置。那之後，從牌組將5隻卡名不同的怪獸向對手展示，對手從其中隨機選1隻。那1隻怪獸在我方場上特殊召喚，其餘回到牌組。'),'放置場地魔法卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91336701,'魔導耀士 破曉者',unistr('魔法使族怪獸2隻\u000a這個卡名的②④效果1回合各能使用1次。\u000a①：此卡連結召喚的場合發動。給此卡放置1個魔力計數器。\u000a②：此卡指向的區域有魔法使族怪獸特殊召喚的場合發動。給此卡放置1個魔力計數器。\u000a③：此卡的攻擊力上升此卡的魔力計數器的數量×300。\u000a④：去除此卡的2個魔力計數器，以場上1張卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91337277,'巨大膨脹龍','①：此卡召喚的場合，從我方牌組上方將50張卡裡側除外可以發動。此卡的攻擊力直到回合結束時變成10000。','改變攻擊力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91345518,'裁決的代行者 土星','①：將此卡解放可以發動。我方的生命值高於對手的場合，給予對手那個差額的傷害。此效果在我方場上有「天空的聖域」存在的場合可以發動和處理。此效果發動的整回合中，我方不能進行戰鬥階段。','給予對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91349449,'光芒使者 巫師',unistr('此卡不能通常召喚。只能在被除外的我方的光屬性怪獸有3隻以上的場合特殊召喚。\u000a1回合1次，可以選擇被除外的1隻我方的光屬性怪獸回到牌組，選擇場上的1隻表側表示怪獸除外。此效果發動的整回合中，此卡不能攻擊。'),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91350799,'魔法甜點 鬆餅貓頭鷹',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方墓地1隻怪獸為對象可以發動。那隻怪獸除外，從牌組將「魔法甜點 鬆餅貓頭鷹」以外的1隻「魔法甜點」怪獸特殊召喚。\u000a②：此卡被對手破壞送去墓地的場合發動。此卡回到牌組。'),'返回牌組','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91351370,'黑旋風','①：我方場上有「BF」怪獸召喚時可以發動。從牌組將1隻攻擊力低於那隻怪獸的「BF」怪獸加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91392974,'出幻',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上的表側表示的「HERO」怪獸被戰鬥、效果破壞的場合可以發動。從牌組將1隻等級4以下的「V.HERO」怪獸特殊召喚。那之後，可以挑選對手場上1隻怪獸，那個原本的攻擊力、守備力變成一半。'),'特殊召喚','是否挑選1隻怪獸原本的攻擊力、守備力減半？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91397409,'企鵝勇者',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡同步召喚成功的場合可以發動。從牌組將1隻「企鵝」怪獸裡側守備表示特殊召喚。\u000a②：只要此卡在怪獸區域存在，我方場上的裡側守備表示怪獸不會成為對手的效果的對象。\u000a③：對手發動怪獸的效果時可以發動。選我方場上1隻裡側守備表示的水屬性怪獸變成表側守備表示。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91405870,'烈風的空牙團',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻「空牙團」怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91407982,'命運視界',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，可以從牌組將1張「命運女郎」卡片加入手牌。\u000a②：1回合1次，我方場上的卡被效果除外的場合可以發動。這個回合，我方場上的怪獸不會被效果破壞。\u000a③：1回合1次，對手場上的卡被效果除外的場合可以發動。這個回合，我方受到的戰鬥傷害只有1次變成0。'),'是否從牌組把1張「命運女郎」卡片加入手牌？','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91420202,'降誕疾仇屍者 救世主',unistr('不死族怪獸2隻\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，卡名當作「復仇屍者 屠戮者」。\u000a②：以我方墓地1張「仇屍」卡片為對象可以發動。那張卡加入手牌。\u000a③：此卡和對手怪獸進行戰鬥的傷害計算時，從牌組將1隻不死族怪獸送去墓地可以發動。那隻對手怪獸的攻擊力直到回合結束時下降送去墓地的怪獸的等級×200。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91420254,'妖仙獸 右鐮神柱',unistr('【靈擺效果】\u000a①：1回合1次，另一邊的我方的靈擺區域有「妖仙獸」卡片存在的場合可以發動。此卡的靈擺刻度直到回合結束時變成11。此效果的發動後，直到回合結束時我方除了「妖仙獸」怪獸以外不能特殊召喚。\u000a【怪獸效果】\u000a①：此卡召喚成功的場合發動。此卡變成守備表示。\u000a②：只要此卡在怪獸區域存在，對手不能將其他的「妖仙獸」怪獸作為攻擊對象。'),'靈擺效果1','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91422370,'螺旋式彈簧',unistr('將我方場上1隻攻擊力1500以上的「發條」怪獸解放可以發動。從手牌將1隻「發條」怪獸特殊召喚。那之後，可以從牌組將1隻和此效果特殊召喚的怪獸攻擊力相同的「發條」怪獸特殊召喚。\u000a\u000a※螺旋式發條'),'是否從牌組特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91434208,'白之輪迴',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，從牌組將1隻持有將自身當作協調的效果的魚族怪獸加入手牌。\u000a②：1回合1次，我方的「白鬥氣」怪獸攻擊的傷害步驟結束時可以發動。那隻攻擊怪獸只有1次可以繼續攻擊。\u000a③：1回合1次，從我方墓地有等級8以上的魚族同步怪獸特殊召喚的場合可以發動（傷害步驟也能發動）。對手場上的怪獸全部破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91434602,'權威者 赫貝里翁',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：此卡可以將我方的手牌、場上、墓地1隻「代行者」怪獸除外，從手牌、墓地特殊召喚。\u000a②：我方的天使族怪獸的戰鬥產生給我方的戰鬥傷害對手也要承受。\u000a③：1回合1次，從我方的手牌、墓地將1隻天使族怪獸除外，以我方或對手的墓地1張卡為對象可以發動。那張卡除外。場上或墓地有「天空的聖域」存在的場合，這個效果1回合可以使用最多2次。'),'墓地的卡除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91438674,'阿爾戈☆群星-榮冠的阿德菈',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：對手回合，我方場上有永續陷阱卡存在的場合，將此卡從手牌除外可以發動。場上1隻怪獸的攻擊力直到回合結束時變成0。\u000a②：此卡召喚的場合發動。這個回合，應對我方的永續陷阱卡的效果的發動，對手不能發動效果。\u000a③：將場上的此卡除外可以發動。從手牌、牌組將最多2張「阿爾戈☆群星」永續陷阱卡在我方的魔法與陷阱區域表側表示放置（同名卡最多1張）。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91438994,'盟軍次世代獄炎',unistr('①：每次從我方場上有怪獸送去墓地，給此卡放置1個次世代計數器。\u000a②：每次從對手墓地有卡除外，給此卡放置2個次世代計數器。\u000a③：此卡的攻擊力上升場上的次世代計數器的數量×100。\u000a④：此卡被戰鬥破壞送去墓地的場合發動。給予對手此卡放置的次世代計數器的數量×300傷害。'),'給予效果傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91449144,'薰風的靜寂 加姆','1回合1次，讓我方墓地的2隻「薰風」怪獸回到牌組可以發動。從牌組抽1張卡。','抽卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91449532,'娛樂夥伴 掩護河馬',unistr('①：此卡召喚成功時可以發動。從手牌將1隻「娛樂夥伴」怪獸特殊召喚。此效果特殊召喚的怪獸的效果直到回合結束時無效化。\u000a②：1回合1次，我方主要階段可以發動。我方場上的怪獸全部變成守備表示。'),'從手牌特殊召喚','變成守備表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91468551,'太陽的祭壇','只要此卡在場上表側表示存在，我方場上從墓地特殊召喚的表側表示怪獸的攻擊力上升300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91479482,'紅戀的麗傑-布拉達曼特',unistr('這個卡名在規則上也當作「焰聖騎士」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄，以我方場上1隻戰士族怪獸為對象可以發動。從牌組選1張那隻怪獸可以裝備的裝備魔法卡，給那隻怪獸裝備。\u000a②：沒有裝備裝備卡的此卡被對手怪獸戰鬥破壞送去墓地時可以發動。此卡特殊召喚，那隻對手場上的怪獸當作裝備卡給此卡裝備。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91482773,'閘道龍',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：對手場上有連結怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：1回合1次，我方主要階段可以發動。從手牌將1隻等級4以下的龍族、闇屬性怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91499077,'我我我武士',unistr('等級4怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以我方場上1隻「我我我」怪獸為對象可以發動。這個回合，那隻怪獸在1次戰鬥階段中可以攻擊2次。\u000a②：此卡以外的我方怪獸被選擇作為攻擊對象時可以發動。此卡變成表側守備表示，攻擊對象轉移到此卡進行傷害計算。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91500017,'卡通書籤',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：除了「卡通書籤」以外，從牌組將1張「卡通世界」或記載那個卡名的卡加入手牌。\u000a②：我方場上的「卡通世界」被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91501248,'禁忌之壺',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡反轉的場合，可以從以下效果選擇1個發動。\u000a●我方抽2張卡。\u000a●場上的魔法、陷阱卡全部回到手牌。\u000a●對手場上的怪獸全部破壞。\u000a●確認對手的手牌，挑選其中1張回到牌組。'),'●從牌組抽2張牌','●魔法陷阱卡回到持有者的手牌','●對手怪獸全部破壞','●確認對手的手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(91505214,'花樣明星 娜珥姬絲',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：對手受到效果傷害的場合可以發動。此卡從手牌特殊召喚。\u000a②：只要此卡在怪獸區域存在，每次對手發動手牌、墓地的怪獸的效果，給予對手200傷害。'),'此卡從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91509824,'A.i.-搭檔',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上的原攻擊力是2300的電子界族怪獸數量的對手場上的表側表示卡為對象可以發動。那些卡的效果直到回合結束時無效。\u000a②：將墓地的此卡除外，以我方的除外狀態的1隻電子界族怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91512835,'昆蟲女王',unistr('①：此卡的攻擊力上升場上的昆蟲族怪獸數量×200。\u000a②：此卡的攻擊宣言之際，我方必須將我方場上1隻其他怪獸解放。\u000a③：此卡戰鬥破壞對手怪獸的回合的結束階段發動。在我方場上將1隻「昆蟲怪獸衍生物」（昆蟲族、地、等級1、攻/守100）攻擊表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91512836,'昆蟲怪獸衍生物','由「昆蟲女王」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91530236,'精靈術的操控者',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：捨棄1張手牌可以發動。「靈使」怪獸、「憑依裝著」怪獸、「憑依」魔法、陷阱卡之中，從牌組選2張（同名卡最多1張）。其中1張加入手牌，另1張在我方場上覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91530237,'精靈術的操控者',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：捨棄1張手牌可以發動。「靈使」怪獸、「憑依裝著」怪獸、「憑依」魔法、陷阱卡之中，從牌組選2張（同名卡最多1張）。其中1張加入手牌，另1張在我方場上覆蓋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91534476,'一接一',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、場上將1隻怪獸送去墓地，從我方墓地的怪獸以及被除外的我方怪獸之中，以送去墓地的怪獸以外的1隻等級1怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91554542,'新炎獄劍士',unistr('對手墓地的卡是4張以下的場合，此卡的攻擊力上升600。\u000a對手墓地的卡是8張以上的場合，此卡的攻擊力下降300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91557476,'聖蔓的劍士',unistr('植物族通常怪獸1隻\u000a①：我方場上的「聖天樹」連結怪獸因效果從場上離開的場合發動。此卡破壞。\u000a②：此卡特殊召喚成功的場合，以場上1隻「聖天樹」連結怪獸為對象可以發動。此卡的攻擊力上升那個連結標記數量×800。\u000a③：此卡戰鬥破壞對手怪獸送去墓地時可以發動。那隻怪獸在連結怪獸指向的我方場上效果無效特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91559748,'棘之妖精',unistr('只要此卡在場上表側表示存在，對手不能攻擊昆蟲族怪獸。\u000a此卡和怪獸進行戰鬥的傷害步驟結束時，那隻怪獸變成守備表示。'),'變成守備表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91575236,'不滅之龍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從牌組將1隻不死族怪獸送去墓地，此卡的等級變成那隻怪獸和此卡的原等級的差額。\u000a②：此卡在墓地存在的狀態，我方的不死族怪獸被戰鬥破壞時可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91580102,'爬蟲妖狂怒',unistr('裝備怪獸變成爬蟲類族，攻擊力上升800。\u000a此外，此卡被破壞送去墓地時，選擇對手場上表側表示存在的1隻怪獸發動。那隻怪獸的攻擊力下降800。'),'攻擊力下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91584698,'娛樂夥伴 撲克魔女',unistr('【靈擺效果】\u000a①：1回合1次，我方主要階段可以發動。從我方場上將融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。\u000a【怪獸效果】\u000a①：解放此卡可以發動。從我方的牌組、墓地選1張「融合」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91588074,'創星神 提耶拉',unistr('此卡不能通常召喚。只能讓此卡以外的我方的手牌、場上的10種卡片回到持有者的牌組、額外牌組來特殊召喚。\u000a①：此卡的特殊召喚不會被無效化。\u000a②：此卡特殊召喚成功的場合發動。此卡以外的雙方的手牌、場上、墓地的卡以及額外牌組的表側表示的靈擺怪獸全部回到持有者的牌組。應對此效果的發動，不能發動魔法、陷阱、怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91592030,'威迫礦石-召喚晶石',unistr('①：以我方墓地3隻怪獸為對象可以發動。我方從那3隻之中挑選1隻。那之後，對手從以下效果挑選1個，我方適用那個效果。\u000a●挑選的怪獸特殊召喚。\u000a●挑選的怪獸以外的對象怪獸盡可能特殊召喚。'),'●選擇的怪獸特殊召喚','●其他的對象怪獸盡可能特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91595718,'秘術之書',unistr('只能給魔法使族怪獸裝備。\u000a裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91596726,'黑暗十字軍','從手牌將闇屬性怪獸1隻送去墓地，此卡的攻擊力上升400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91597389,'騎乘！','選擇我方墓地的1隻聯合怪獸，給我方場上的可以裝備的怪獸裝備。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91598270,'SoDoReMi和弦 格蕾西亞',unistr('【靈擺效果】\u000a①：在我方的「DoReMi和弦」靈擺怪獸的靈擺召喚成功時，對手不能發動怪獸的效果、魔法、陷阱卡。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「DoReMi和弦」魔法、陷阱卡加入手牌。\u000a②：我方的靈擺區域有偶數的靈擺刻度存在，我方的「DoReMi和弦」靈擺怪獸攻擊的場合，對手直到傷害步驟結束時不能發動怪獸的效果。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91607976,'變形鬥士 時鐘',unistr('此卡依照表示形式得到以下效果。\u000a●攻擊表示：此卡放置的變形鬥士計數器每有1個，此卡的攻擊力上升500。\u000a●守備表示：1回合1次，可以給此卡放置1個變形鬥士計數器。藉由解放此卡，給予對手此卡放置的變形鬥士計數器的數量×1000傷害。'),'放置計數器','給對手效果傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91623717,'連鎖爆擊','同一連鎖上沒有多次同名卡的效果發動的場合，連鎖2以後可以發動。給予對手此卡發動時累積的連鎖數量×400傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91642007,'海造賊-黑翼的水先人',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以「海造賊-黑翼的水先人」以外的我方墓地1隻「海造賊」怪獸為對象可以發動。此卡從手牌特殊召喚，對象怪獸加入手牌。這個回合，我方除了「海造賊」怪獸以外不能特殊召喚。\u000a②：此卡從手牌、怪獸區域送去墓地的場合，以我方的魔法與陷阱區域1張「海造賊」怪獸卡為對象可以發動。那張卡守備表示特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91646304,'神樹之聖像騎士',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：此卡可以從手牌往連結怪獸指向的我方場上守備表示特殊召喚。\u000a②：我方場上的「聖像騎士」怪獸被戰鬥、效果破壞的場合，可以將場上、墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91650245,'森羅的恩惠','選1張手牌回到持有者的牌組最上方或最下方，從我方的手牌、墓地選1隻「森羅」怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不受此卡以外的卡片效果影響，在結束階段回到持有者的牌組最上方或最下方。','回到牌組最上方','回到牌組最下方','特召','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91654806,'和宇宙的交信',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將原持有者是對手的我方場上1隻怪獸送去墓地可以發動。從我方的手牌、墓地選1隻機械族怪獸特殊召喚。\u000a②：我方場上有「人造人-念力震懾者」存在，對手抽牌階段中對手通常抽牌時，宣言卡的種類（怪獸、魔法、陷阱）可以發動。抽到的卡給雙方確認，那是宣言的種類的場合，此卡送去墓地，我方從牌組抽1張卡。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91662792,'薰風鷹','此卡被戰鬥破壞送去墓地時，可以從牌組將1隻協調以外的等級4以下的「薰風」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91663373,'電子超能者','只要此卡在我方場上表側攻擊表示存在，對手抽牌時，可以確認那些卡。','確認抽到的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91665064,'安全阻擋','①：以場上1隻電子界族怪獸為對象可以發動。這個回合，那隻怪獸不會被戰鬥破壞，雙方受到的全部戰鬥傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91668078,'踩著雪鞋印 順著足跡追呀追 一個接一個','①：「踩著雪鞋印 順著足跡追呀追 一個接一個」以外的卡被送去墓地的場合可以發動。我方墓地的最多5張卡裡側除外。那之後，我方的除外狀態的裡側的卡有7張以上存在的場合，對手盡可能挑選自身墓地的最多5張卡裡側除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91668401,'電子天使－伊舍那－',unistr('藉由「機械天使的儀式」降臨。\u000a①：此卡儀式召喚成功的場合可以發動。對手必須將自身場上1張魔法、陷阱卡送去墓地。\u000a②：此卡的攻擊破壞對手怪獸送去墓地時可以發動。此卡只有1次可以繼續向對手怪獸攻擊。\u000a③：1回合1次，以我方場上的「電子天使」儀式怪獸為對象的對手的效果發動時可以發動。選我方墓地1隻儀式怪獸回到牌組，選對手場上1張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91677585,'勇往翔前挑戰','①：我方戰鬥階段，以這個回合進行過攻擊的1隻超量怪獸為對象可以發動。這次戰鬥階段中，那隻怪獸只有1次可以再度攻擊。此效果讓那隻怪獸攻擊的場合，直到傷害步驟結束時對手不能發動魔法、陷阱、怪獸的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91691605,'D-HERO 鑽頭小子',unistr('「D-HERO 鑽頭小子」的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從手牌將攻擊力在此卡的攻擊力以下的1隻「D-HERO」怪獸特殊召喚。\u000a②：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91697229,'極星邪狼 芬里爾',unistr('此卡不能通常召喚。我方主要階段2，場上有「極神」怪獸存在的場合，可以從手牌守備表示特殊召喚到對手場上。\u000a①：場上沒有「極神」怪獸存在的場合，此卡破壞。\u000a②：我方戰鬥階段開始時發動。我方場上的守備表示怪獸全部變成表側攻擊表示。\u000a③：此卡的戰鬥產生的戰鬥傷害由雙方玩家承受。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91703676,'炎王神天燒',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方場上的「炎王」怪獸和對手場上的卡各選相同數量為對象可以發動。那些卡破壞。\u000a②：我方場上的「炎王」卡片被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91706817,'藍淚的天使',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的控制者所見的對手受到自身的手牌數量×200傷害。那之後，對象怪獸的效果直到回合結束時無效。\u000a②：我方或對手受到效果傷害的場合，將墓地的此卡除外可以發動。從手牌、牌組將1張通常陷阱卡在我方場上覆蓋。從手牌覆蓋的場合，那張卡在覆蓋的回合也能發動。'),'效果1','效果2','適用「藍淚的天使」的效果來發動','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91711547,'炎獄魔鬼','此卡給對手的生命值戰鬥傷害時，我方墓地存在的炎族怪獸數量×200給對手的生命值傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91712985,'時械神 卡米恩',unistr('此卡不能從牌組特殊召喚。\u000a①：我方場上沒有怪獸存在的場合，此卡可以不用解放來召喚。\u000a②：此卡不會被戰鬥、效果破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：此卡進行戰鬥的戰鬥階段結束時發動。選對手場上1張卡回到持有者的牌組，給予對手500傷害。應對此效果的發動，不能發動卡的效果。\u000a④：我方準備階段發動。此卡回到持有者的牌組。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91714772,'銀河防衛機器人 軌道 7',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌、場上的此卡解放可以發動。從牌組選1隻「光子」怪獸和1隻「銀河」怪獸，其中1隻加入手牌，另1隻送去墓地。這個回合，我方除了光屬性怪獸以外不能特殊召喚。\u000a②：我方場上有「銀河眼」怪獸特殊召喚的場合可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91714773,'銀河防衛機器人 軌道 7',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌、場上的此卡解放可以發動。從牌組選1隻「光子」怪獸和1隻「銀河」怪獸，其中1隻加入手牌，另1隻送去墓地。這個回合，我方除了光屬性怪獸以外不能特殊召喚。\u000a②：我方場上有「銀河眼」怪獸特殊召喚的場合可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91718579,'隆隆隆左手&右手',unistr('①：只要此卡和此卡以外的「隆隆隆」怪獸在怪獸區域存在，對手不能選擇「隆隆隆」怪獸作為攻擊對象，也不能作為效果的對象。\u000a②：只用包含此卡的「隆隆隆」怪獸為素材的超量怪獸得到以下效果。\u000a●這次超量成功時，以對手場上1隻表側攻擊表示怪獸為對象可以發動。那隻怪獸變成守備表示且守備力變成0。'),'變成守備表示（隆隆隆左手&右手）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91731841,'寶石騎士 紅榴石','被紅榴石之力寄宿的寶石騎士的戰士。用火焰的鐵拳粉碎敵人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91740879,'隱居者的大釜',unistr('①：作為此卡的發動時的效果處理，給此卡放置1個計數器。\u000a②：我方準備階段發動。給此卡放置1個計數器。\u000a③：1回合1次，可以從以下效果選擇1個發動。\u000a●我方回復此卡的計數器數量×500生命值。\u000a●給予對手此卡的計數器數量×300傷害。'),'效果2','●我方回復生命值','●給予對手傷害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91742238,'不死族的骸旋',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：選場上1隻不死族怪獸除外。那之後，從那個控制者的墓地選1隻不死族怪獸在持有者的場上守備表示特殊召喚。\u000a②：此卡在墓地存在的場合可以發動。選被除外的1隻我方的不死族怪獸回到牌組，此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91749600,'王戰之咒 伐拉',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：「王戰之咒 伐拉」在我方場上只能有1隻表側表示存在。\u000a②：此卡在手牌、墓地存在的場合，從手牌將1張其他的「王戰」卡片送去墓地可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a③：此卡特殊召喚成功的場合可以發動。從我方的手牌、墓地選「王戰之咒 伐拉」以外的1隻「王戰」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91754175,'人犬獸','①：1回合1次，此卡和對手怪獸進行戰鬥的傷害計算時可以發動。從手牌、牌組將1隻獸族、獸戰士族、鳥獸族怪獸送去墓地，此卡的攻擊力直到戰鬥階段結束時上升送去墓地的那隻怪獸的等級×100。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91781484,'DDD獵頭',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「DDD」怪獸存在的場合，以對手場上1隻表側表示怪獸為對象可以發動。直到下個回合的結束階段，得到那隻怪獸的控制權。此效果得到控制權的怪獸的效果無效化，不能攻擊宣言。此效果得到控制權的怪獸是從額外牌組特殊召喚的怪獸的場合，那隻怪獸也當作「DDD」怪獸。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91781589,'霸者的獨攬','對手準備階段可以發動。這個回合，對手不能進行戰鬥階段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91782219,'蟹龜','藉由「龜的誓言」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91798373,'二重蠍子','此卡召喚、特殊召喚成功時，可以從手牌將1隻等級4以下的二重怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91800273,'次元吸引者','①：我方、對手回合，我方墓地沒有卡存在的場合，將此卡從手牌送去墓地可以發動。直到下個回合結束時，送去墓地的卡不去墓地而是除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91800274,'次元吸引者','①：我方、對手回合，我方墓地沒有卡存在的場合，將此卡從手牌送去墓地可以發動。直到下個回合結束時，送去墓地的卡不去墓地而是除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91810826,'天盃龍 中龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有龍族、炎屬性怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：怪獸進行戰鬥的傷害步驟開始時可以發動。從牌組將「天盃龍 中龍」以外的1隻等級4以下的龍族、炎屬性怪獸特殊召喚。\u000a③：1回合1次，我方、對手的戰鬥階段可以發動。用包含此卡的我方場上的怪獸為素材進行同步召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91812341,'特莉恩的蟲惑魔',unistr('①：此卡召喚時可以發動。從牌組將1張「空洞」通常陷阱卡或「落穴」通常陷阱卡加入手牌。\u000a②：此卡特殊召喚成功的場合，以對手場上1張魔法、陷阱卡為對象發動。那張對手的卡破壞。\u000a③：此卡只要在怪獸區域存在，不受「空洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影響。'),'加入手牌','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91818544,'威咖杯！摩卡',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以場上1隻裡側守備表示怪獸為對象可以發動。此卡從手牌特殊召喚，對象怪獸變成表側攻擊表示。\u000a②：此卡反轉的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸攻擊力上升1000，在結束階段送去墓地。\u000a③：我方結束階段可以發動。此卡變成裡側守備表示。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91819979,'魔法爆破',unistr('①：給予對手相當於我方場上的魔法使族怪獸數量×200傷害。\u000a②：此卡在墓地存在的場合，我方抽牌階段的抽牌前可以發動。作為這個回合進行通常抽牌的代替，此卡加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91822647,'薰風的旋風','我方場上沒有怪獸存在的場合可以發動。選擇我方墓地的2隻「薰風」怪獸回到牌組。那之後，從我方牌組將1隻守備力1000以下的「薰風」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91831066,'水族館照明',unistr('①：「水族館照明」在我方場上只能有1張表側表示存在。\u000a②：我方場上的「水伶女」怪獸與對手怪獸進行戰鬥的傷害計算時發動。那隻我方怪獸的攻擊力、守備力只在傷害計算時變成2倍。\u000a③：此卡從場上送去墓地的場合，以我方墓地1隻水族怪獸為對象可以發動。那隻怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了水族怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91842653,'卡通惡魔',unistr('此卡不能通常召喚。我方場上有「卡通世界」存在的狀態，解放我方場上的1隻怪獸可以特殊召喚。\u000a①：此卡在特殊召喚的回合不能攻擊。\u000a②：此卡的攻擊宣言之際，我方必須支付500生命值。\u000a③：此卡在對手場上沒有卡通怪獸存在的場合，可以直接攻擊。存在的場合，只能選擇卡通怪獸作為攻擊對象。\u000a④：場上的「卡通世界」被破壞時，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91862578,'激昂的姆卡姆卡','我方每有1張手牌，此卡的攻擊力和守備力就上升400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91864689,'S-Force 拔刃者',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從手牌將「S-Force 拔刃者」以外的1隻「S-Force」怪獸攻擊表示特殊召喚。\u000a②：只要此卡在怪獸區域存在，我方的「S-Force」怪獸的正前方的對手怪獸不能作為連結3以上的怪獸的連結素材。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91869203,'亞馬遜的射手','①：將我方場上2隻怪獸解放可以發動。給予對手1200傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91870448,'念力電子巨人',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：對手場上的魔法、陷阱卡數量比我方場上的魔法、陷阱卡多的場合，此卡可以從手牌特殊召喚。\u000a②：我方場上有「人造人-念力震懾者」存在，此卡向對手的效果怪獸攻擊宣言時，解放此卡可以發動。那隻對手怪獸當作永續陷阱卡以表側表示放置在對手的魔法與陷阱區域。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91880660,'九死必有一生路',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：雙方玩家在自己的主要階段可以發動。最多到對手場上的卡片數量，從我方牌組上方翻開卡片，從其中選1張加入手牌。那之後，剩下的卡以及1張我方的手牌以喜歡的順序回到牌組下方。\u000a②：此卡的①效果1次翻開9張以上的玩家在那個回合的結束階段可以發動。對手的場上、墓地的卡全部回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91895091,'銀嶺的巨神',unistr('地屬性等級3怪獸×2\u000a1回合1次，去除此卡的1個超量素材，選擇對手的魔法與陷阱區域覆蓋的1張卡可以發動。只要此卡在場上表側表示存在，選擇的卡不能發動。\u000a此外，持有超量素材的此卡戰鬥破壞對手怪獸的場合，可以選擇我方墓地1隻地屬性怪獸表側守備表示特殊召喚。'),'禁止發動','從墓地特殊召喚','選擇對手的魔法與陷阱區域覆蓋的1張卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91903221,'進化蟲 埃爾金螈','場上的此卡被解放送去墓地時，從牌組抽1張卡。那之後，可以讓手牌的1隻恐龍族怪獸回到牌組，從牌組將1隻「進化蟲」怪獸加入手牌。','抽牌','是否將1隻「進化蟲」怪獸加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91907707,'機殼檔案 色慾',unistr('【靈擺效果】\u000a①：我方除了「機殼」怪獸以外不能特殊召喚。這個效果不會被無效化。\u000a②：我方場上的「機殼」怪獸的攻擊力上升300。\u000a【怪獸效果】\u000a①：此卡可以不用解放來召喚。\u000a②：特殊召喚或不解放來召喚的此卡的等級變成4，原攻擊力變成1800。\u000a③：通常召喚的此卡不受原本的等級或階級低於此卡的等級的怪獸發動的效果影響。\u000a④：此卡被解放的場合，以場上1隻怪獸為對象可以發動。那隻怪獸回到持有者的手牌。'),'不解放的召喚','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91932350,'神鷹女郎1',unistr('此卡的卡名在規則上當作「神鷹女郎」。\u000a只要此卡在場上表側表示存在，風屬性怪獸的攻擊力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91939608,'神聖玩偶','操縱神聖力量的玩偶。在黑暗之中攻擊力很強。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91946859,'應身的機械天使',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在魔法與陷阱區域存在，我方的「電子天使」儀式怪獸不會被戰鬥破壞。\u000a②：戰鬥或對手的效果讓我方受到傷害時，將我方的手牌、場上1隻「電子天使」儀式怪獸解放可以發動。從手牌將1隻「電子天使」儀式怪獸當作儀式召喚特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91949988,'迅雷的騎士 蓋亞龍騎兵',unistr('等級7怪獸×2\u000a此卡也能重疊在我方場上的階級5、6的超量怪獸上方來超量召喚。\u000a①：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'是否疊在階級5或6的超量怪獸上超量召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91951471,'征服鬥魂 螺旋流辻風',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻「征服鬥魂」怪獸為對象可以發動。那隻怪獸的表示形式變更。那之後，最多到我方場上的「征服鬥魂」怪獸種類的數量，可以選對手場上的表側表示怪獸變成裡側守備表示。'),'N/A','是否選對手怪獸變成裡側守備表示？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91953000,'海晶少女 藍倒吊',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將「海晶少女 藍倒吊」以外的1隻「海晶少女」怪獸送去墓地。\u000a②：此卡作為水屬性連結怪獸的連結素材送去墓地的場合可以發動。翻開我方牌組上方的3張卡。可以從其中選1張「海晶少女」卡片加入手牌，剩下的卡回到牌組。'),'','','是否選1張卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91957038,'妖精的傳姬',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：向對手展示手牌的1隻同名怪獸不在我方場上存在的攻擊力1850的魔法使族怪獸可以發動。進行那隻怪獸的通常召喚。\u000a②：我方場上有原攻擊力是1850的魔法使族怪獸存在，我方因戰鬥、效果受到傷害的場合，1回合只有1次讓那次傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91969909,'女神烏爾德的裁斷',unistr('①：我方場上的「華爾裘蓮」怪獸不會成為對手的效果的對象，不會被對手的效果破壞。\u000a②：1回合1次，宣言1個卡名，以對手場上覆蓋的1張卡為對象可以發動。那張覆蓋的卡給雙方確認，如果是宣言的卡，那張卡除外。如果不是，選我方場上1張卡除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91985515,'核成初始化','解放我方場上的1隻「核成」怪獸可以發動。從我方的牌組、墓地將1張「核成的鋼核」加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91989718,'攻擊反射裝置','解放我方場上1隻「電子龍」可以發動。從我方的手牌、牌組將1隻「電子障壁龍」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91996584,'鞭尾石像鬼','使用如同鞭子一樣長的尾巴，從空中發動攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998119,'XYZ-神龍加農砲',unistr('「X-首領加農」+「Y-龍形首領」+「Z-金屬履帶」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。此卡不能從墓地特殊召喚。\u000a①：捨棄1張手牌，以對手場上1張卡為對象可以發動。那張對手的卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998120,'XYZ-神龍加農砲',unistr('「X-首領加農」+「Y-龍形首領」+「Z-金屬履帶」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。此卡不能從墓地特殊召喚。\u000a①：捨棄1張手牌，以對手場上1張卡為對象可以發動。那張對手的卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998121,'XYZ-神龍加農砲',unistr('「X-首領加農」+「Y-龍形首領」+「Z-金屬履帶」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。此卡不能從墓地特殊召喚。\u000a①：捨棄1張手牌，以對手場上1張卡為對象可以發動。那張對手的卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998122,'XYZ-神龍加農砲',unistr('「X-首領加農」+「Y-龍形首領」+「Z-金屬履帶」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。此卡不能從墓地特殊召喚。\u000a①：捨棄1張手牌，以對手場上1張卡為對象可以發動。那張對手的卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92001300,'古代機械齒輪城',unistr('①：場上的「古代機械齒輪」怪獸的攻擊力上升300。\u000a②：只要此卡在魔法與陷阱區域存在，每次怪獸通常召喚，給此卡放置1個計數器。\u000a③：我方將「古代機械齒輪」怪獸表側表示上級召喚的場合，可以解放已放置需要解放的數量以上的計數器的此卡作為代替來上級召喚。'),'解放「古代機械齒輪城」','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92003832,'黃金榮耀-滾球手',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的生命值低於對手的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方、對手的主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「黃金榮耀」融合怪獸融合召喚。'),'從手牌特殊召喚','融合召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92015800,'No.76 諧調光師 漸變天樂鬥士',unistr('等級7怪獸×2\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡的屬性也當作此卡作為超量素材持有的怪獸的每個屬性。\u000a②：此卡不會被和此卡屬性相同的怪獸戰鬥破壞，不會被和此卡屬性相同的對手怪獸發動的效果破壞。\u000a③：以對手墓地1隻怪獸為對象可以發動。去除此卡的1個超量素材，將對象怪獸重疊在此卡下方作為超量素材。此效果在對手回合也能發動。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92034192,'超級量子士 黑層',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：對手發動怪獸的效果時可以發動。從我方的手牌選1張其他卡捨棄，此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合可以發動。將1隻「超級量子機獸」超量怪獸重疊在我方場上的此卡上方當作超量召喚從額外牌組特殊召喚，從我方墓地將1隻「超級量子」怪獸作為那個超量素材。\u000a③：此卡被送去墓地的場合可以發動。從牌組將1張「超級量子」魔法卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92035412,'大日神械元素','我方場上表側表示存在的「大日神械」裝備卡被破壞時，可以從我方牌組將最多到破壞數量的「大日神械」協調在我方場上特殊召喚。將此效果特殊召喚的怪獸作為同步素材的場合，除了「大日神械」怪獸的同步召喚以外不能使用。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92039899,'惡魔的騎兵','①：場上的此卡被效果破壞送去墓地的場合，以「惡魔的騎兵」以外的我方墓地1隻「惡魔」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92043888,'DoReMi和弦正裝',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的靈擺區域有「DoReMi和弦」卡片存在，對手發動怪獸的效果、魔法、陷阱卡時可以發動。從我方的額外牌組讓1隻表側表示的靈擺怪獸回到牌組。那之後，適用以下效果。\u000a●我方場上的靈擺怪獸不受那個對手的效果影響。\u000a●我方的靈擺區域的卡不會被那個對手的效果破壞。\u000a●我方的靈擺區域的卡不能被那個對手的效果除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92053608,'水伶女 金龍魚','①：1回合1次，我方主要階段可以發動。從牌組將1隻「水伶女」怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92058902,'未來融合-永望結合新星',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，包含「電子龍」的我方牌組的怪獸作為融合素材，將1隻機械族、光屬性融合怪獸融合召喚。此卡從場上離開時，那隻怪獸破壞。那隻怪獸被破壞時，此卡破壞。此卡的發動後，直到回合結束時我方除了機械族怪獸以外不能特殊召喚，除了用此效果特殊召喚的怪獸以外不能攻擊宣言。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92058903,'未來融合-永望結合新星',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，包含「電子龍」的我方牌組的怪獸作為融合素材，將1隻機械族、光屬性融合怪獸融合召喚。此卡從場上離開時，那隻怪獸破壞。那隻怪獸被破壞時，此卡破壞。此卡的發動後，直到回合結束時我方除了機械族怪獸以外不能特殊召喚，除了用此效果特殊召喚的怪獸以外不能攻擊宣言。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92065772,'住在冰結界的魔醉蟲',unistr('①：此卡召喚的場合，指定1格沒有使用的主要怪獸區域發動。此卡得到以下效果。\u000a●只要此卡在怪獸區域存在，指定的區域不能使用。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92067220,'小丑順子',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：選1張我方的手牌捨棄，從牌組將1隻「皇后騎士」特殊召喚，從牌組將「國王騎士」或「傑克騎士」其中1隻加入手牌。那之後，可以將1隻怪獸召喚。此效果的發動後，我方除了戰士族、光屬性怪獸以外不能從額外牌組特殊召喚。\u000a②：我方、對手的結束階段，以我方墓地1隻戰士族、光屬性怪獸為對象可以發動。那隻怪獸回到牌組，墓地的此卡加入手牌。'),'效果1','是否將1隻怪獸召喚？','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92079625,'影依的炎核 虛空',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡反轉的場合，以對手場上1隻表側表示怪獸為對象可以發動。從我方的額外牌組將1隻屬性和那隻怪獸相同的「影依」怪獸送去墓地，對象怪獸除外。\u000a②：此卡被效果送去墓地的場合可以發動。依照場上的怪獸的原屬性種類的數量，從我方牌組上方將卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92080692,'看破的極意','①：對手發動和對手墓地的卡同名的怪獸的效果、魔法、陷阱卡時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92084010,'鬚嘴鮟','水屬性怪獸上級召喚的場合，此卡可以當作2隻解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92092092,'調星的直線競速士',unistr('①：此卡發動後變成效果怪獸（機械族、協調、炎、等級1、攻0/守1800）在怪獸區域特殊召喚。此卡也當作陷阱卡。\u000a②：只要此卡的效果特殊召喚的此卡在怪獸區域存在，此卡以外的我方場上的協調不會被戰鬥以及對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92099232,'變形妖姊妹',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：此卡發動後變成通常怪獸（惡魔族、協調、地、等級2、攻/守0）在怪獸區域特殊召喚。此卡也當作陷阱卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92107604,'神碑之泉',unistr('①：只要此卡在場地區域存在，我方在對手回合可以從手牌發動「神碑」速攻魔法卡。\u000a②：1回合1次，我方發動「神碑」速攻魔法卡的場合，以我方墓地最多3張「神碑」速攻魔法卡為對象可以發動。那些卡以喜歡的順序回到牌組下方。那之後，我方依照回去的數量從牌組抽牌。'),'效果2','適用「神碑之泉」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92110878,'三色小工具',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「光之黃金櫃」或記載那個卡名的魔法、陷阱卡加入手牌。\u000a②：此卡被戰鬥、效果破壞的場合可以發動。從牌組將1張「隱匿城 堅實堡壘」在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92125819,'聖騎士 阿爾托利斯',unistr('屬於聖騎士團的聰明青年騎士。彷彿就像受到引導，闖入森林之中的他，終於抵達命運的所在。隨後，青年邁出了那一大步。\u000a——這是一切的開端，一段偉大的史詩。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92133240,'恐啡肽狂龍 鐮刀龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組選1張「恐啡肽狂龍」陷阱卡在我方的魔法與陷阱區域覆蓋。我方的生命值是2000以下的場合，隨後此卡的攻擊力上升500。\u000a②：此卡被戰鬥、效果破壞的場合，從我方墓地將1張陷阱卡除外可以發動。從我方墓地選「恐啡肽狂龍 鐮刀龍」以外的1隻等級4以下的「恐啡肽狂龍」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92142169,'大食蟲',unistr('對手場上有超量怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a這個方法特殊召喚成功時，選擇對手場上的1隻怪獸發動。選擇的怪獸的攻擊力下降300。'),'攻擊力下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92170894,'娛樂夥伴 電話長角牛',unistr('「娛樂夥伴 電話長角牛」的效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從牌組將靈擺怪獸以外的1隻「娛樂夥伴」怪獸加入手牌。'),'從牌組加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92171126,'糾罪巧β''-傲慢「alazoneIA」',unistr('【靈擺效果】\u000a這個卡名的②靈擺效果1回合只能使用1次。\u000a①：每次怪獸反轉，給此卡放置1個糾罪計數器。\u000a②：支付900生命值可以發動。從牌組將3張「糾罪巧」卡片向對手展示，對手從其中隨機選1張。那1張加入我方的手牌，其餘回到牌組。\u000a【怪獸效果】\u000a①：向對手展示手牌的此卡可以發動（此效果發動的整回合中，我方只能用裡側守備表示將怪獸特殊召喚）。從手牌將1隻怪獸裡側守備表示特殊召喚。\u000a②：對手發動包含從牌組將卡加入手牌的效果的卡的效果時，將裡側表示的此卡變成表側守備表示可以發動。從牌組將1張「糾罪巧」卡片加入手牌。\u000a③：此卡反轉的場合發動。對手的手牌隨機選1張直到結束階段表側除外。'),'靈擺效果2','效果1','效果2','效果3','','','','','','','','','','','','');
INSERT INTO texts VALUES(92176681,'抑制對撞員','與網路世界的大惡交戰的熟練鬥士。凡是被其鐵鎚壓縮的數據，誰都不能復原。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92182447,'時間女神的惡作劇',unistr('此卡不能連鎖發動，應對此卡的發動，不能發動魔法、陷阱、怪獸的效果。\u000a①：我方場上的怪獸只有「華爾裘蓮」怪獸的場合，我方戰鬥階段結束時可以發動。此卡送去墓地。跳過回合到下個我方回合的戰鬥階段開始時。直到那個回合結束時，我方不能發動「時間女神的惡作劇」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92200612,'靈魂鳥-傳鳩',unistr('此卡不能特殊召喚。\u000a①：1回合1次，以此卡以外的場上1隻靈魂怪獸為對象可以發動。那隻怪獸回到持有者的手牌。\u000a②：此卡召喚、反轉的回合的結束階段發動。此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92204263,'紺碧之機界騎士',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：相同縱列有2張以上的卡存在的場合，此卡可以在那個縱列的我方場上特殊召喚。\u000a②：1回合1次，以我方場上1隻「機界騎士」怪獸為對象可以發動。那隻我方怪獸的位置向其他的我方的主要怪獸區域移動。此效果在對手回合也能發動。'),'移動位置','請選擇要移動位置的「機界騎士」怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92219931,'二者一兩損','雙方各自將自己的牌組最上方的卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92221402,'混沌元素',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的牌組、墓地將1隻等級5以上的光、闇屬性的炎族、水族怪獸加入手牌。那之後，我方墓地有3隻以上炎族、水族怪獸存在的場合，可以將場上1張卡破壞。\u000a②：對手場上有光、闇屬性的炎族、水族怪獸存在的場合，將墓地的此卡除外，以對手場上1隻怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。'),'效果1','效果2','是否破壞1張卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92223430,'西摩格的靈峰 厄爾布爾士',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：場上的鳥獸族、風屬性怪獸的攻擊力、守備力上升300。\u000a②：向對手展示手牌的等級5以上的鳥獸族、風屬性怪獸可以發動。這個回合，我方將鳥獸族怪獸召喚的場合需要的解放可以減少1隻。\u000a③：我方場上有鳥獸族、風屬性怪獸存在的場合可以發動。將1隻鳥獸族怪獸召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92223641,'天空之泉','光屬性怪獸被戰鬥破壞送去我方墓地時，可以藉由將那隻怪獸除外，我方的生命值回復那隻怪獸的攻擊力數值。','回復生命值','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92246806,'妖仙獸 鐮弍太刀',unistr('①：此卡召喚成功的場合可以發動。從手牌將「妖仙獸 鐮弍太刀」以外的1隻「妖仙獸」怪獸召喚。\u000a②：此卡可以直接攻擊。那次戰鬥給予對手的戰鬥傷害變成一半。\u000a③：此卡召喚的回合的結束階段發動。此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92248362,'K9-17號 飯綱',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：對手的手牌是2張以上的場合，此卡可以不用解放來召喚。\u000a②：對手已發動手牌、墓地的怪獸的效果的，我方、對手回合的主要階段可以發動。此卡從手牌特殊召喚。\u000a③：此卡召喚、特殊召喚的場合可以發動。從牌組將「K9-17號 飯綱」以外的1張「K9」卡片送去墓地。'),'不解放的召喚','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92266279,'濕潤之風',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：支付1000生命值可以發動。從牌組將1隻「芬芳」怪獸加入手牌。\u000a②：我方的生命值低於對手的場合可以發動。我方回復500生命值。'),'N/A','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92269002,'鐵獸的擊鐵',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下的效果1回合各能選擇1次）。\u000a●從牌組將「鐵獸的擊鐵」以外的1張「鐵獸」魔法、陷阱卡加入手牌。\u000a●從我方墓地將任意數量的「鐵獸」卡片除外可以發動。從額外牌組將1隻連結標記數量和除外數量相同的「鐵獸」連結怪獸無視召喚條件特殊召喚。這個回合，我方除了獸族、獸戰士族、鳥獸族怪獸以外不能從額外牌組特殊召喚。'),'效果1','●從牌組加入手牌','●從額外牌組特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92300891,'機偶桶 真九六',unistr('此卡可以攻擊的場合必須攻擊。\u000a場上表側攻擊表示的此卡被選擇作為攻擊對象時，此卡的表示形式變成守備表示。\u000a此卡1回合只有1次不會被戰鬥破壞。'),'變成守備表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92327802,'缺陷編譯器',unistr('①：1回合1次，對手的效果讓我方受到傷害的場合，給此卡放置1個缺陷計數器（最多1個）作為代替。\u000a②：1回合1次，去除此卡的1個缺陷計數器，以我方場上1隻電子界族怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升800。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92332424,'龍劍士 威風天馬',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：另一邊的我方的靈擺區域有「龍劍士」卡片或「威風妖怪」卡片存在的場合可以發動。從牌組將1隻原卡名和那張卡不同的「龍劍士」靈擺怪獸加入手牌。那之後，可以將我方的靈擺區域1張卡破壞。\u000a【怪獸效果】\u000a這個卡名在規則上也當作「威風妖怪」卡片。這個卡名的②怪獸效果1回合只能使用1次。\u000a①：我方、對手回合，將此卡從手牌捨棄可以發動。這個回合中，我方場上的「龍劍士」怪獸不會被對手的效果破壞，對手不能將其作為效果的對象。\u000a②：此卡用靈擺召喚或「龍劍士」卡片的效果特殊召喚的場合可以發動。從牌組將1張場地魔法卡加入手牌。那之後，選1張我方的手牌捨棄。'),'靈擺效果1','是否選我方的靈擺區域的1張卡破壞？','效果1','效果2','','','','','','','','','','','','');
INSERT INTO texts VALUES(92341815,'星空蝶',unistr('只能給我方場上的怪獸裝備。這個卡名的③效果1回合只能使用1次。\u000a①：「星空蝶」在我方場上只能有1張表側表示存在。\u000a②：對手場上的怪獸的攻擊力下降我方場上的記載「勇者衍生物」的衍生物名的怪獸種類×500。\u000a③：此卡被送去墓地的場合，以我方場上1隻「勇者衍生物」為對象可以發動。那隻我方怪獸將此卡裝備。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92345028,'熾焰狂怒',unistr('這個卡名在規則上也當作「轉生炎獸」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、墓地選最多2隻「轉生炎獸」怪獸守備表示特殊召喚（同名卡最多1張）。此效果特殊召喚的怪獸的效果無效化。此卡的發動後，直到回合結束時我方只能有1次從額外牌組將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92346415,'念力之劍',unistr('只能給超能族怪獸裝備。\u000a我方的生命值低於對手的場合，裝備怪獸的攻擊力上升那個數值（最多2000）。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92353449,'真紅眼洞悉',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從手牌、牌組將1隻「真紅眼」怪獸送去墓地可以發動。從牌組將「真紅眼洞悉」以外的1張「真紅眼」魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92359409,'超弩級砲塔列車 古斯塔夫火箭砲',unistr('等級10怪獸×3\u000a「超弩級砲塔列車 古斯塔夫火箭砲」1回合1次也能捨棄1張手牌，重疊在我方場上的「超弩級砲塔列車 古斯塔夫極大砲」上方來超量召喚。\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡持有超量素材，對手發動怪獸的效果時可以發動。那個效果無效並破壞。那之後，給予對手1000傷害。\u000a②：我方結束階段發動。去除此卡的1個超量素材，或此卡破壞。'),'是否重疊在「超弩級砲塔列車 古斯塔夫極大砲」上方來超量召喚？','效果1','效果2','是否去除超量素材？','','','','','','','','','','','','');
INSERT INTO texts VALUES(92361635,'原子廢鐵龍',unistr('「廢鐵」協調+協調以外的怪獸2隻以上\u000a1回合1次，選擇我方場上的1張卡和對手墓地的最多3張卡可以發動。選擇的我方的卡破壞，選擇的對手的卡回到牌組。\u000a此卡被對手破壞送去墓地時，選擇同步怪獸以外的我方墓地的1隻「廢鐵」怪獸特殊召喚。'),'破壞和返回牌組','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92362073,'銀河衛龍',unistr('龍族怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的戰鬥階段，將場上、墓地的此卡除外，以我方場上1隻原本的種族、屬性是龍族、光屬性的「No.」超量怪獸為對象可以發動。直到戰鬥階段結束時，對手受到的戰鬥傷害變成一半，對象怪獸的攻擊力變成那隻怪獸持有的「No.」數值×100。\u000a②：對手結束階段可以發動。從牌組選1張卡放置在牌組最上方。'),'效果1','效果2','請選擇要放置在牌組最上方的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92365601,'升階魔法-限制型巴利安之力','選擇我方場上1隻階級4的超量怪獸可以發動。將1隻階級比選擇的怪獸高1階的「CNo.」怪獸重疊在選擇的我方怪獸上方，當作超量召喚從額外牌組特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92373006,'奴隸虎',unistr('①：我方場上有「劍鬥獸」怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：將此卡解放，以我方場上1隻「劍鬥獸」怪獸為對象可以發動。那隻我方的「劍鬥獸」怪獸回到持有者的牌組，從牌組將1隻「劍鬥獸」怪獸特殊召喚。此效果特殊召喚的怪獸當作用「劍鬥獸」怪獸的效果特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92377303,'黑衣大賢者',unistr('此卡不能通常召喚。\u000a我方的「時間魔術師」的投擲硬幣猜對時，可以藉由將我方場上的1隻「黑魔導」解放，此卡從手牌或牌組特殊召喚。\u000a這個方法特殊召喚成功時，從我方牌組將1張魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92379223,'黃金的征服王',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「埃爾德里奇」怪獸存在的場合，可以從以下效果選擇1個發動。\u000a●選被除外的我方的「黃金國靈藥」魔法、陷阱卡3種各1張回到牌組，場上的卡全部破壞。\u000a●選被除外的我方的「黃金鄉」魔法、陷阱卡3種各1張回到牌組，對手的生命值變成一半。那之後，我方的生命值回復對手的生命值數值。'),'●場上的卡全部破壞','●對手生命值變成一半','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92385016,'神碑之翼 霧尼',unistr('「神碑」怪獸×2\u000a①：此卡從額外牌組特殊召喚成功的場合，捨棄1張手牌可以發動。從牌組將1張「神碑」永續魔法卡加入手牌。\u000a②：對手發動以我方場上的「神碑」卡片或覆蓋的卡為對象的魔法、陷阱、怪獸的效果時，將場上的此卡除外可以發動。那個發動無效並破壞。\u000a③：我方、對手的結束階段發動。我方回復1000生命值。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92391084,'威爾米','相當兇暴的兔子。以銳利的鉤爪血祭對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92394653,'靈魂的引誘',unistr('此卡的控制者在每次我方準備階段支付500生命值，或不支付讓此卡破壞。\u000a場上表側表示存在的靈魂怪獸回到我方的手牌時，對手選對手場上的1隻怪獸回到持有者的手牌。'),'回到手牌','是否支付500生命值維持「靈魂的引誘」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92408984,'龍的寶珠','只以場上的1隻龍族怪獸為對象的陷阱卡發動時，可以藉由捨棄1張手牌，那個效果無效並破壞。','效果無效並破壞','是否現在發動此卡的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92409659,'白海豚','頭上有角的白色海豚。引起大浪攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92411493,'雨天氣 湛藍',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從手牌選1張「天氣」魔法、陷阱卡在我方的魔法與陷阱區域表側表示放置。\u000a②：場上的此卡為了發動「天氣」卡片的效果而被除外的場合，下個回合的準備階段可以發動。被除外的此卡特殊召喚。'),'效果1','被除外的此卡特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92418590,'奇巧人偶-死靈玩偶',unistr('這個卡名的效果1回合只能使用1次，將此卡作為超量召喚的素材的場合，除了「奇巧人偶」怪獸的超量召喚以外不能使用。\u000a①：此卡在墓地存在的場合，從我方墓地將此卡以外的1隻「奇巧人偶」怪獸除外可以發動。此卡特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92421852,'稀有金屬女士','全身覆蓋著金屬裝甲的女戰士。與「稀有金屬士兵」融合將提升力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92422871,'電子界無效亞龍',unistr('電子界族的儀式、融合、同步、超量、連結怪獸+電子界族怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將1隻電子界族怪獸特殊召喚。那之後，可以將此卡的等級變成和此效果特殊召喚的怪獸相同。\u000a②：我方場上有連結4以上的電子界族怪獸存在，對手發動魔法、陷阱卡的效果時，將場上、墓地的此卡除外可以發動。那個發動無效。'),'效果1','效果2','是否改變此卡的等級？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92428405,'霸王龍之魂',unistr('①：支付一半生命值可以發動。從額外牌組將1隻「霸王龍 札克」無視召喚條件，效果無效特殊召喚。那隻怪獸在下個回合的結束階段回到持有者的額外牌組。\u000a②：對手發動魔法卡的效果時，將墓地的此卡和我方場上1隻「霸王龍 札克」除外可以發動。從我方的手牌、牌組、額外牌組、墓地選「靈擺龍」「超量龍」「同步龍」「結合龍」怪獸各最多1隻特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92435533,'時械神 拉結恩',unistr('此卡不能從牌組特殊召喚。\u000a①：我方場上沒有怪獸存在的場合，此卡可以不用解放來召喚。\u000a②：此卡不會被戰鬥、效果破壞，此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：此卡進行戰鬥的戰鬥階段結束時發動。對手墓地的卡全部回到牌組。\u000a④：1回合1次，對手抽牌的場合發動。給予對手1000傷害。\u000a⑤：我方準備階段發動。此卡回到持有者的牌組。'),'不解放的召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92447211,'尾長黑馬',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合，向對手展示手牌的1隻不死族怪獸，從牌組將1隻不死族、地屬性怪獸送去墓地可以發動。展示的怪獸送去墓地，此卡的攻擊力直到回合結束時上升500。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92450185,'限制破除','①：此卡被送去墓地的場合發動。從我方的手牌、牌組、墓地選1隻「高速戰士」特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92472273,'終刻龍機XII-德拉斯提亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1張「終刻」卡片為對象可以發動。那張卡破壞，此卡從手牌特殊召喚。那之後，可以從牌組將1張裝備卡給此卡裝備。\u000a②：我方、對手回合，此卡已裝備裝備卡的場合可以發動。從額外牌組將1隻階級和此卡的等級數值相同的機械族、風屬性超量怪獸當作超量召喚特殊召喚，此卡以及此卡的裝備卡全部作為那個超量素材。'),'效果1','效果2','是否裝備1張裝備卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92481084,'心眼的祭殿','①：只要此卡在場地區域存在，我方或對手受到戰鬥傷害的場合，那個數值變成1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92487128,'創星龍華-光巴',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方主要階段可以發動。從牌組將靈擺怪獸以外的1張「龍華」卡片加入手牌。那之後，此卡破壞。\u000a【怪獸效果】\u000a藉由「創星龍華-光巴」降臨\u000a此卡只能用此卡的效果特殊召喚。我方1回合只能特殊召喚1次「創星龍華-光巴」。\u000a①：此卡在額外牌組存在的狀態，場上的怪獸被戰鬥、效果破壞的場合可以發動。我方場上1隻等級10的「龍華」怪獸解放，此卡當作儀式召喚特殊召喚。那之後，以下可以適用。\u000a●我方場上最多2張卡破壞，最多到那個數量，從牌組將「龍華」永續魔法卡在我方場上表側表示放置。'),'靈擺效果1','效果1','是否將我方場上的卡破壞？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92501449,'原石的鳴獰',unistr('①：支付2000生命值，宣言1個通常怪獸的卡名可以發動。直到對手回合結束時，我方的宣言的通常怪獸以及我方的「原石」怪獸不會被戰鬥破壞。我方場上沒有怪獸存在的場合，隨後可以從牌組將1隻宣言的通常怪獸守備表示特殊召喚。\u000a②：對手將怪獸召喚的場合，將墓地的此卡除外，以我方的場上、墓地1隻通常怪獸為對象可以發動。場上1隻攻擊力低於那隻怪獸的怪獸除外。'),'是否將1隻宣言的通常怪獸特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92510265,'聖戰士 混沌士兵',unistr('「聖戰士 混沌士兵」的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功時，以被除外的1隻我方的光屬性或闇屬性的怪獸和對手場上的1張卡為對象可以發動。那張我方的卡回到墓地，那張對手的卡除外。\u000a②：此卡戰鬥破壞對手怪獸時，以我方墓地的1隻等級7以下的戰士族怪獸為對象可以發動。那隻怪獸加入手牌。'),'除外的卡回到墓地','墓地的怪獸加入手牌','請選擇要回到墓地的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92512625,'神的忠告',unistr('①：我方的魔法與陷阱區域覆蓋的卡只有此卡的場合，支付3000生命值可以發動。\u000a●怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並破壞。\u000a●我方或對手將怪獸召喚、反轉召喚、特殊召喚之際可以發動。使其無效，那些怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92517928,'銀河眼反物質龍',unistr('等級9怪獸×2\u000a「銀河眼反物質龍」1回合1次也能重疊在持有3個以上超量素材的我方的超量怪獸上方來超量召喚。\u000a①：持有超量素材的此卡給予對手的戰鬥傷害變成一半。\u000a②：去除此卡的1個超量素材可以發動。這個回合，此卡在1次戰鬥階段中可以向怪獸攻擊最多2次。去除的超量素材是怪獸的場合，隨後可以從牌組將1隻和那隻怪獸種族相同的怪獸送去墓地。'),'是否重疊在超量怪獸上方超量召喚？','效果2','是否將怪獸送去墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92518817,'盛燃希塔','藉由解放此卡以外的我方場上1隻炎屬性怪獸，從手牌將1隻炎屬性怪獸特殊召喚。這個效果1回合只能使用1次。此效果特殊召喚的怪獸在「盛燃希塔」從我方場上離開的場合破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92519087,'電腦堺狐-仙仙',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：從場上送去墓地的卡不去墓地而是除外。\u000a②：我方怪獸的攻擊宣言時可以發動。選除外的1隻我方或對手的怪獸回到墓地。\u000a③：從我方墓地將此卡以外的2隻原本的種族、屬性不同的怪獸除外可以發動。此卡從墓地特殊召喚。此效果在此卡送去墓地的回合不能發動。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92530005,'娛樂法師 騎球手',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方主要階段可以發動。從我方的額外牌組（表側）將1隻「娛樂法師」靈擺怪獸送去墓地。那之後，可以讓此卡的靈擺刻度上升送去墓地的怪獸的靈擺刻度數值。\u000a【怪獸效果】\u000a這個卡名的①②③怪獸效果1回合各能使用1次。\u000a①：我方場上有「娛樂法師」怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合，可以從以下效果選擇1個發動。\u000a●從牌組將1隻「娛樂法師」靈擺怪獸表側加入額外牌組。\u000a●我方場上1張「娛樂法師」怪獸卡破壞。\u000a③：特殊召喚的對手怪獸的直接攻擊宣言時可以發動。此卡從墓地特殊召喚。'),'靈擺效果1','效果1','效果2','效果3','選擇1個效果','●加入額外牌組','●場上1張怪獸卡破壞','請選擇要加入額外牌組的卡','是否讓靈擺刻度上升？','','','','','','','');
INSERT INTO texts VALUES(92534075,'魔彈-魔鬼交易',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：只要此卡在魔法與陷阱區域存在，我方場上的「魔彈」怪獸不會被效果破壞。\u000a②：此卡被對手的效果送去墓地的場合可以發動。從我方的牌組、墓地選「魔彈-魔鬼交易」以外的1張「魔彈」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92536468,'DDD反骨王 列奧尼達',unistr('【靈擺效果】\u000a①：我方受到效果傷害時可以發動。此卡破壞，這個回合，給予生命值傷害的效果變成讓生命值回復的效果。\u000a【怪獸效果】\u000a①：我方受到效果傷害時可以發動。此卡從手牌特殊召喚，我方的生命值回復受到的傷害的數值。\u000a②：只要此卡在怪獸區域存在，我方受到的效果傷害變成0。'),'靈擺效果1','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92559258,'安迪米翁的僕從',unistr('【靈擺效果】\u000a①：每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a②：去除此卡的3個魔力計數器可以發動。牌組的1隻可以放置魔力計數器的攻擊力1000以上的怪獸和靈擺區域的此卡特殊召喚，給那2隻各放置1個魔力計數器。\u000a【怪獸效果】\u000a我方1回合只能特殊召喚1次「安迪米翁的僕從」。\u000a①：已放置魔力計數器的此卡可以直接攻擊。\u000a②：對手回合1次，捨棄1張手牌可以發動。給此卡以及我方場上的可以放置魔力計數器的全部卡各放置1個魔力計數器。\u000a③：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。那之後，給此卡放置此卡放置過的數量的魔力計數器。'),'靈擺效果2','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92562411,'星遺物引導的前路',unistr('①：「星遺物引導的前路」在我方場上只能有1張表側表示存在。\u000a②：每次場上的等級5以上的表側表示怪獸被送去墓地，每有1隻給此卡放置1個計數器（最多7個）。\u000a③：將已放置7個計數器的此卡送去墓地可以發動。從額外牌組將1隻電子界族連結怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92565383,'玉米田蛇神',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。從牌組將「玉米田蛇神」以外的1隻記載「客邁拉結合」的卡名的怪獸加入手牌。\u000a②：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a③：我方場上有「有翼幻獸 客邁拉」存在，對手發動以我方場上的卡為對象的效果時，將場上、墓地的此卡除外可以發動。那個效果無效並破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92572371,'殺炎星-牛逵','此卡在墓地存在的場合，將手牌或我方場上表側表示存在的「炎星」卡片或「炎舞」卡片合計2張送去墓地可以發動。此卡從墓地特殊召喚。「殺炎星-牛逵」的效果1回合只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92586237,'武尊神-目一箇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1張其他的「武尊神」卡片送去墓地可以發動。此卡從手牌特殊召喚。\u000a②：可以從以下效果選擇1個發動。\u000a●從手牌將1隻「武尊神」怪獸送去墓地可以發動。從我方墓地選和那隻怪獸卡名不同的1隻「武尊神」怪獸加入手牌。\u000a●從我方墓地將1隻「武尊神」怪獸除外可以發動。和那隻怪獸卡名不同的1隻「武尊神」怪獸從牌組送去墓地。'),'效果1','●從墓地加入手牌','●從牌組送去墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92595545,'電漿球','此卡可以向對手玩家直接攻擊。此卡由於直接攻擊給予對手的生命值戰鬥傷害時，此卡破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92595643,'罰則金','我方選2張手牌捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92595825,'夜薔薇的黑騎士',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從我方墓地將1隻「黑薔薇龍」或等級4以下的植物族怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。\u000a②：只要我方場上有同步怪獸存在，我方場上的植物族怪獸的攻擊力上升1000。\u000a③：以我方場上1隻其他的植物族怪獸為對象可以發動。那隻怪獸的等級上升或下降1。'),'效果1','效果2','等級上升','等級下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(92597893,'惡作劇風的費德蘭',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，以我方場上1隻表側表示怪獸為對象可以發動。這個回合，那隻怪獸向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：對手回合，以此卡以外的場上1隻表側表示怪獸為對象可以發動。那隻怪獸的表示形式變更。那之後，此卡回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92607427,'玩具遊行',unistr('這個卡名在規則上也當作「魔玩具」卡片。這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以從額外牌組特殊召喚的1隻我方的闇屬性怪獸為對象可以發動。這個回合，我方除了用那隻怪獸以外不能攻擊宣言，那隻怪獸每次戰鬥破壞怪獸送去墓地可以繼續攻擊。\u000a②：我方場上有天使族怪獸存在的場合，將墓地的此卡除外可以發動。從我方墓地選1隻等級4以下的闇屬性怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92609670,'英豪挑戰者 伏擊兵',unistr('我方的準備階段時，將場上的此卡解放可以發動。從我方的手牌、墓地選「英豪挑戰者 伏擊兵」以外的最多2隻「英豪挑戰者」怪獸特殊召喚。「英豪挑戰者 伏擊兵」的這個效果1回合只能使用1次。\u000a此效果特殊召喚成功時，可以藉由將墓地的此卡除外，我方場上的全部「英豪挑戰者」怪獸的等級變成1。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92610868,'ReDoReMi和弦 德莉米亞',unistr('【靈擺效果】\u000a①：我方的「DoReMi和弦」靈擺怪獸的靈擺召喚不會被無效化。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：我方的靈擺區域有「DoReMi和弦」卡片存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方的靈擺區域有奇數的靈擺刻度存在，我方場上的「DoReMi和弦」靈擺怪獸卡被對手的效果破壞的場合，可以將此卡破壞作為其中1張被破壞的卡的代替。'),'效果1','請選擇要代替的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92644052,'娛樂夥伴 稀代的決鬥者',unistr('【靈擺效果】\u000a①：1回合1次，怪獸之間進行戰鬥的傷害步驟開始時可以發動。此卡回到持有者的手牌，從牌組將1張魔法卡除外。我方怪獸不會被那次戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成一半。\u000a【怪獸效果】\u000a①：此卡給予對手戰鬥傷害時可以發動。從牌組將1隻「霸王眷龍」怪獸或「霸王門」怪獸或1張「霸王龍之魂」加入手牌。\u000a②：我方、對手的準備階段發動。雙方各自可以從自身牌組將1張魔法卡除外。\u000a③：1回合1次，我方或對手的怪獸的攻擊宣言時發動。被攻擊的玩家可以適用以下效果。\u000a●選被除外的1張自身的魔法卡加入手牌。那之後，那張卡捨棄，那次攻擊無效。'),'靈擺效果1','效果1','效果2','效果3','是否從牌組將1張魔法卡除外？','是否捨棄魔法卡將攻擊無效？','','','','','','','','','','');
INSERT INTO texts VALUES(92650018,'驚奇遊樂設施 恐怖鬼屋',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以1隻我方場上的「驚樂園」怪獸或對手場上的表側表示怪獸為對象可以發動此卡。此卡當作裝備卡給那隻怪獸裝備。\u000a②：可以依照裝備怪獸的控制者，發動以下效果。\u000a●我方：以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。\u000a●對手：裝備怪獸變成裡側守備表示。'),'●我方','●對手','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92650749,'成熟編年史',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：每次「尤貝爾」怪獸或記載「尤貝爾」的卡名的怪獸特殊召喚，給此卡放置1個編年史計數器。\u000a②：可以去除我方場上的以下數量的編年史計數器，發動那個效果。\u000a●1：從我方墓地將1隻「尤貝爾」特殊召喚。\u000a●2：我方的除外狀態的1張卡加入手牌。\u000a●3：從牌組選1張卡除外。\u000a●4：場上1張卡破壞。\u000a●5：從牌組將1張「超融合」加入手牌。'),'●1個','●2個','●3個','●4個','●5個','','','','','','','','','','','');
INSERT INTO texts VALUES(92652813,'憑依覺醒-大稻荷火',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：此卡可以將我方場上的表側表示的1隻魔法使族怪獸和1隻等級4以下的炎屬性怪獸送去墓地，從手牌、牌組特殊召喚。\u000a②：此卡的①方法特殊召喚時可以發動。給予對手相當於對手場上1隻怪獸的原攻擊力數值的傷害。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將1張「火靈術」卡片或「憑依」魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92661479,'光子奔豹鑣',unistr('等級6怪獸×2\u000a在對手場上有效果怪獸的效果發動時，去除此卡的1個超量素材可以發動。那個效果無效，給予對手1000傷害。這個效果1回合只能使用1次。'),'效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92667214,'死亡馬戲團殭屍','使用黑暗力量重生的小丑，利用搖晃的舞蹈將對手引向死亡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92676637,'調和支援者',unistr('①：將場上的此卡作為同步素材的場合，可以將此卡當作等級2怪獸。\u000a②：此卡作為同步素材送去墓地的場合發動。我方從牌組抽1張卡。'),'抽卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92693205,'齒輪齒輪拋錨人',unistr('①：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a②：此卡反轉的場合可以發動。最多到此卡以外的我方場上的「齒輪齒輪」怪獸數量，挑選場上的怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92714517,'歡迎大駕光臨拉比麗斯',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方的手牌、牌組、墓地將1隻「拉比麗斯」怪獸特殊召喚。那之後，我方場上1隻怪獸回到手牌。\u000a②：將墓地的此卡除外，以我方場上1隻惡魔族怪獸為對象可以發動（我方場上有等級8以上的惡魔族怪獸存在的場合，也能改成以對手場上1張卡為對象）。那張卡回到手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92719314,'黑暗創世神',unistr('此卡不能通常召喚。我方墓地有5隻以上闇屬性怪獸存在，我方場上沒有怪獸存在的場合可以特殊召喚。\u000a1回合1次，藉由將我方墓地1隻闇屬性怪獸除外，選擇我方墓地1隻闇屬性怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92720564,'變形鬥士 音響',unistr('此卡依照表示形式得到以下效果。\u000a●攻擊表示：此卡在1次戰鬥階段中可以攻擊2次。\u000a●守備表示：1回合1次，我方場上的表側表示的「變形鬥士」怪獸被選擇作為攻擊對象時，可以使那次攻擊無效。'),'●守備表示：','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92723496,'龍宮的雙使者',unistr('「龍宮的雙使者」的效果1回合只能使用1次。\u000a①：將手牌的1隻怪獸捨棄可以發動。從牌組將1隻等級4以下的幻龍族怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92729410,'子狸彭彭','此卡召喚成功時，可以從牌組將「子狸彭彭」以外的1隻獸族、等級2怪獸裡側守備表示特殊召喚。此效果發動的整回合中，我方不能將獸族以外的怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92731385,'珠淚哀歌 琪多卡洛斯',unistr('「珠淚哀歌」怪獸+水族怪獸\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從牌組選1張「珠淚哀歌」卡片加入手牌或送去墓地。\u000a②：以我方場上1隻怪獸為對象可以發動。從我方的手牌、墓地選1隻「珠淚哀歌」怪獸特殊召喚，對象怪獸送去墓地。\u000a③：此卡被效果送去墓地的場合可以發動。從我方牌組上方將5張卡送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92731455,'磁體戰士2號','擅長互相搭配的戰士。塗有電磁的鎧甲非常堅固。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92736188,'偉大神靈',unistr('我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a此卡反轉召喚成功時，以場上的1隻地屬性怪獸為對象可以發動。那隻地屬性怪獸的原攻擊力和原守備力直到回合結束時交換。'),'變為裡側守備表示','數值交換','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92744676,'電磁蝦',unistr('協調+協調以外的怪獸1隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚的場合，從我方的手牌、場上將此卡以外的1張卡送去墓地，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。\u000a②：對手主要階段可以發動（同一連鎖上最多1次）。用包含此卡的我方場上的怪獸為素材進行同步召喚。'),'破壞','進行同步召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92746535,'龍劍士 光柵行者靈擺',unistr('【靈擺效果】\u000a①：1回合1次，另一邊的我方的靈擺區域有卡存在的場合可以發動。那張卡破壞，從牌組將1張那個同名卡加入手牌。\u000a【怪獸效果】\u000a不能用此卡為素材將「龍劍士」怪獸以外的融合、同步、超量怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92755808,'元素恐龍',unistr('依照場上的怪獸屬性，此卡得到以下效果。\u000a●炎屬性：此卡的攻擊力上升500。\u000a●地屬性：此卡戰鬥破壞的效果怪獸的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92767273,'娛樂夥伴 兇猛薔薇',unistr('【靈擺效果】\u000a①：1回合1次，我方的「娛樂夥伴」怪獸和對手怪獸進行戰鬥的傷害計算前可以發動。那隻對手怪獸的攻擊力下降和那個原攻擊力的差額。\u000a【怪獸效果】\u000a「娛樂夥伴 兇猛薔薇」的怪獸效果1回合只能使用1次。\u000a①：以攻擊力和原攻擊力不同的1隻「娛樂夥伴」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升和那個原攻擊力的差額。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92770064,'聖天樹的大母神',unistr('連結怪獸2隻以上\u000a①：此卡連結召喚成功的場合可以發動。從牌組將1張「聖天樹」魔法、陷阱卡加入手牌。\u000a②：此卡不會被對手的效果破壞，不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。\u000a③：1回合1次，解放此卡指向的1隻我方的連結怪獸可以發動。選對手場上最多到那個連結標記數量的卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92773018,'人工腦秘密技術','對手怪獸的攻擊宣言時，將我方場上的1隻「電子龍」或「電子龍」作為融合素材記載的融合怪獸送去墓地可以發動。選擇那1隻攻擊怪獸破壞。','攻擊怪獸破壞','是否現在發動此卡的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92781606,'超機怪蟲 方舟感質',unistr('「機怪蟲」怪獸2隻\u000a①：依照我方場上的「機怪蟲」怪獸數量適用以下效果。\u000a●2隻以上：我方場上的怪獸的攻擊力、守備力上升300。\u000a●4隻以上：對手在戰鬥階段中不能發動效果。\u000a●6隻以上：我方怪獸可以直接攻擊。\u000a②：表側表示的此卡因對手的效果從場上離開的場合，或被戰鬥破壞的場合，以我方墓地2隻「機怪蟲」怪獸為對象可以發動（同名卡最多1張）。那些怪獸裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92784374,'咒法艾莉亞爾','反轉：可以從我方牌組將1隻「咒法」怪獸加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92798873,'恐啡肽狂龍 狂飆暴龍',unistr('「恐啡肽狂龍」融合怪獸+「恐啡肽狂龍」怪獸\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：對手場上的攻擊力在我方的生命值數值以上的怪獸不能發動效果。\u000a②：我方、對手回合，支付一半生命值可以發動。對手場上的全部怪獸的攻擊力直到回合結束時變成和我方的生命值數值相同。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從我方墓地選1隻等級6以下的「恐啡肽狂龍」怪獸特殊召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92807548,'墮天使 烏科巴克',unistr('「墮天使 烏科巴克」的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組將1張「墮天使」卡片送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92812851,'超升靈擺・奇蹟的魔劍士',unistr('包含靈擺怪獸的效果怪獸2隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從我方的額外牌組（表側）將1隻靈擺怪獸加入手牌。\u000a②：此卡的攻擊力上升我方場上的靈擺怪獸卡數量×100。\u000a③：我方、對手的主要階段可以發動。將等級在我方的靈擺區域的2張卡的靈擺刻度可以靈擺召喚的範圍內的1隻靈擺怪獸從我方的手牌、墓地守備表示特殊召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92821268,'奇巧人偶-午夜小丑','我方場上的「奇巧人偶」怪獸被戰鬥破壞送去我方墓地時，將那隻怪獸從遊戲中除外可以發動。此卡從手牌特殊召喚。「奇巧人偶-午夜小丑」的效果1回合只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92826944,'馬頭鬼','①：將墓地的此卡除外，以我方墓地1隻不死族怪獸為對象可以發動。那隻不死族怪獸特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92841002,'幻水龍','我方場上有地屬性怪獸存在的場合，此卡可以從手牌特殊召喚。「幻水龍」這個方法的特殊召喚1回合只能有1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92854392,'攔路的強敵','對手的攻擊宣言時可以發動。選擇我方場上1隻表側表示怪獸。發動回合對手不能將選擇的怪獸以外的怪獸作為攻擊對象，全部表側攻擊表示怪獸必須攻擊選擇的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92868896,'龍盟-元老院鳥',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：從手牌捨棄1張「龍盟」卡片可以發動。從牌組選1隻「龍盟」協調當作裝備卡給此卡裝備。此效果的發動後，直到回合結束時我方除了龍族怪獸以外不能從額外牌組特殊召喚。\u000a②：我方場上的「龍盟」卡片被戰鬥、效果破壞的場合，可以將給此卡裝備的1張「龍盟」卡片破壞作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92870717,'魔裝戰士 龍夜',unistr('【靈擺效果】\u000a①：對手怪獸的攻擊宣言時可以發動。此卡破壞，那之後那次戰鬥階段結束。\u000a【怪獸效果】\u000a①：1回合1次，捨棄1張手牌，以我方墓地1隻攻擊力2000以下的戰士族或魔法使族怪獸為對象可以發動。那隻怪獸裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92881099,'魅惑的千層鏡',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的「神鷹女郎」或「神鷹女郎三姊妹」被戰鬥破壞時可以發動。從牌組將1隻原卡名和那隻怪獸不同的「神鷹」怪獸特殊召喚。\u000a②：場上的此卡被對手的效果或我方的「神鷹」卡片的效果破壞的場合，以我方墓地1隻「神鷹」怪獸為對象發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92887027,'流浪者傭兵部隊','此卡戰鬥破壞對手怪獸送去墓地時，解放此卡可以發動。選擇對手場上的1隻裡側守備表示怪獸破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92890308,'變形','我方場上表側表示存在的「變形鬥士」怪獸被選擇作為攻擊對象時可以發動。選擇那1隻攻擊怪獸的攻擊無效，選擇成為攻擊對象的那1隻「變形鬥士」怪獸變更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92892239,'槍管上膛暴怒龍',unistr('龍族、闇屬性怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，以我方場上1隻怪獸和對手場上1張卡為對象可以發動。那些卡破壞。\u000a②：將墓地的此卡除外，以我方墓地1隻闇屬性連結怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能發動效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92895501,'征服鬥魂 重型博格',unistr('這個卡名的①②效果1回合各能使用1次，不能在同一連鎖上發動。\u000a①：我方、對手的主要階段，以機械族以外的我方場上1隻「征服鬥魂」怪獸為對象可以發動。那隻怪獸回到手牌，此卡從手牌特殊召喚。\u000a②：我方、對手回合，可以從以下選擇1個，向對手展示那些屬性的手牌的怪獸各1隻發動。\u000a●闇：我方從牌組抽1張卡。\u000a●地、炎：給予對手1500傷害。'),'效果1','●闇','●地、炎','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92901944,'廢鐵搜索鳥',unistr('此卡在墓地存在，我方場上的「廢鐵搜索鳥」以外的「廢鐵」怪獸被破壞送去墓地時，此卡可以從墓地特殊召喚。\u000a此卡特殊召喚成功時，「廢鐵」怪獸以外的我方場上的表側表示怪獸全部破壞。'),'特殊召喚','破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92907248,'覺醒吧百夫長！',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的魔法與陷阱區域有表側表示怪獸卡存在的場合，宣言等級4或8可以發動。持有宣言的等級的1隻「百夫長衍生物」（炎族、闇、攻/守0）在我方場上特殊召喚。這個衍生物不能作為融合、連結素材。\u000a②：我方主要階段將墓地的此卡除外可以發動。從牌組將「覺醒吧百夫長！」以外的1張「百夫長」卡片送去墓地。'),'效果1','效果2','請宣言1個等級','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92907249,'百夫長衍生物','由「覺醒吧百夫長！」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92918648,'魔導法皇 亥隆',unistr('魔法使族等級7怪獸×2\u000a1回合1次，去除此卡的1個超量素材可以發動。最多到我方墓地的「魔導書」魔法卡數量，選對手場上的魔法、陷阱卡破壞。'),'破壞魔法、陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92919429,'宣告者的神巫',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從牌組、額外牌組將1隻天使族怪獸送去墓地。此卡的等級直到回合結束時上升那隻怪獸的等級數值。\u000a②：此卡被解放的場合可以發動。從手牌、牌組將「宣告者的神巫」以外的1隻等級2以下的天使族怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92924317,'甦醒之魂','①：以我方墓地1隻通常怪獸為對象可以發動此卡。那隻怪獸守備表示特殊召喚。此卡從場上離開時那隻怪獸破壞。那隻怪獸被破壞時此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92932860,'娛樂夥伴 誘導女導演',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：只要我方場上有「異色眼」怪獸存在，對手不能選擇此卡作為攻擊對象。\u000a②：只要此卡在怪獸區域守備表示存在，我方的「異色眼」怪獸不會被戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。\u000a③：以我方墓地1隻等級1怪獸為對象可以發動。那隻怪獸效果無效特殊召喚，只用那隻怪獸和此卡為素材同步召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92933195,'霞之谷的風使','1回合1次，雙方的手牌是5張以上的場合可以發動。雙方玩家將手牌送去墓地直到手牌變成4張。','手牌調整','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92936364,'暗紅惡魔鎖鏈',unistr('這個卡名的卡在1回合只能發動1張。此卡也能向對手展示額外牌組的1隻「暗紅惡魔龍」，在覆蓋的回合發動。\u000a①：向對手展示手牌任意數量的怪獸，依照其中的協調數量+1隻，以對手場上的效果怪獸為對象可以發動此卡。只要此卡在魔法與陷阱區域存在，對象怪獸的攻擊力下降從手牌展示的數量×100，效果無效化。對象怪獸不在場上存在的場合，此卡破壞。'),'效果1','適用「暗紅惡魔鎖鏈」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92936365,'暗紅惡魔鎖鏈',unistr('這個卡名的卡在1回合只能發動1張。此卡也能向對手展示額外牌組的1隻「暗紅惡魔龍」，在覆蓋的回合發動。\u000a①：向對手展示手牌任意數量的怪獸，依照其中的協調數量+1隻，以對手場上的效果怪獸為對象可以發動此卡。只要此卡在魔法與陷阱區域存在，對象怪獸的攻擊力下降從手牌展示的數量×100，效果無效化。對象怪獸不在場上存在的場合，此卡破壞。'),'效果1','適用「暗紅惡魔鎖鏈」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92944626,'邪炎之翼','赤黑的燃燒之翼。從全身噴出火焰攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92958307,'娛樂夥伴表演尾聲','①：最多到我方場上的表側表示的魔法卡數量，以對手場上的表側表示怪獸為對象可以發動。那些怪獸變成裡側守備表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92962242,'重之忍者-磁翁',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚、反轉的場合，以場上最多2隻表側表示怪獸為對象可以發動。那些怪獸變成裡側守備表示。以此效果變成裡側守備表示的對手場上的怪獸不能變更表示形式。\u000a②：此卡已在怪獸區域表側表示存在的狀態，場上的怪獸反轉的場合，以對手場上1張卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92964816,'成長花朵',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡被送去墓地的場合，將墓地的此卡除外可以發動。從牌組將1隻等級5以上的不死族怪獸加入手牌。場地區域有「不死世界」存在的場合，也能不加入手牌而是特殊召喚。此效果的發動後，直到回合結束時我方除了不死族怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92970404,'地中族邪界獸 巴利灰谷主',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上的表側表示怪獸變成裡側表示時，我方場上沒有表側表示怪獸存在的場合可以發動。此卡從手牌守備表示特殊召喚。\u000a②：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a③：此卡反轉的場合可以發動。此卡以外的場上的表側表示怪獸全部變成裡側守備表示。'),'效果3','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92998610,'孤高除獸',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚時，從手牌將1隻怪獸除外可以發動。從牌組將1隻種族和除外的怪獸相同的怪獸除外。\u000a②：此卡被戰鬥或對手的效果破壞的場合，以我方的除外狀態的1隻怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93013676,'摩訶毗盧','①：此卡的攻擊力上升此卡裝備的裝備卡數量×500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93014827,'零日衝擊波','①：解放我方場上1隻闇屬性連結怪獸，以那個連結標記數量的場上的卡為對象可以發動。那些卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93016201,'王宮的彈壓',unistr('雙方玩家可以支付800生命值發動以下效果。\u000a●包含將怪獸特殊召喚效果的魔法、陷阱、怪獸的效果發動時可以發動。那個效果無效並破壞。\u000a●我方或對手將怪獸特殊召喚之際可以發動。那次特殊召喚無效，那些怪獸破壞。'),'無效並破壞','是否現在使用此卡的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93018428,'童話動物 小貓',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手將怪獸召喚、特殊召喚的場合，或此卡被選擇作為對手怪獸的攻擊對象的場合可以發動。此卡回到手牌。那之後，可以從牌組將「童話動物 小貓」以外的1隻獸族怪獸加入手牌。\u000a②：我方結束階段可以發動。此卡從手牌特殊召喚。'),'效果1','效果2','是否從牌組把卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93020401,'燈影之機界騎士',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：相同縱列有2張以上的卡存在的場合，此卡可以在那個縱列的我方場上特殊召喚。\u000a②：和此卡相同縱列的對手的卡從場上離開的場合，或被戰鬥破壞的場合可以發動。從手牌將1隻「機界騎士」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93023136,'墮入黑暗的天使',unistr('這個卡名在規則上也當作「墮天使」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、場上（表側表示）將1隻天使族怪獸送去墓地可以發動。我方的手牌、牌組、除外狀態的1隻「墮天使」怪獸無視召喚條件特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93023479,'守墓的召喚師','此卡從我方場上送去墓地時，從我方牌組將1隻守備力1500以下的「守墓」怪獸加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93031067,'海造賊-據點',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：我方場上的「海造賊」怪獸的攻擊力上升我方的魔法與陷阱區域的「海造賊」卡片數量×500。\u000a②：我方主要階段，捨棄1張手牌可以發動。從牌組將「海造賊-據點」以外的1張「海造賊」卡片加入手牌。\u000a③：此卡在墓地存在的場合，以我方的魔法與陷阱區域1張「海造賊」卡片為對象可以發動。此卡在我方場上覆蓋，對象卡片回到持有者的手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93039339,'災厄之星 提豐',unistr('等級12怪獸×2\u000a對手從額外牌組將2隻以上的怪獸特殊召喚的回合以及下個回合，此卡也能重疊在我方場上的攻擊力最高的怪獸上方來超量召喚。這個方法特殊召喚過的回合，我方不能將怪獸召喚、特殊召喚。\u000a①：只要超量召喚的此卡在怪獸區域存在，雙方不能發動攻擊力3000以上的怪獸的效果。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。場上1隻怪獸回到手牌。'),'是否重疊在攻擊力最高的怪獸上方來超量召喚？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93039340,'災厄之星 提豐',unistr('等級12怪獸×2\u000a對手從額外牌組將2隻以上的怪獸特殊召喚的回合以及下個回合，此卡也能重疊在我方場上的攻擊力最高的怪獸上方來超量召喚。這個方法特殊召喚過的回合，我方不能將怪獸召喚、特殊召喚。\u000a①：只要超量召喚的此卡在怪獸區域存在，雙方不能發動攻擊力3000以上的怪獸的效果。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。場上1隻怪獸回到手牌。'),'是否重疊在攻擊力最高的怪獸上方來超量召喚？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93053159,'白之樞機龍 阿爾白系統教導',unistr('「阿不思的落胤」+我方墓地的卡名不同的怪獸×6\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：此卡可以向全部對手怪獸各攻擊1次。\u000a②：此卡的攻擊宣言之際，我方必須將額外牌組的1張卡送去墓地。\u000a③：1回合1次，融合召喚的此卡在怪獸區域存在，我方墓地有6種以上需以「阿不思的落胤」為融合素材的融合怪獸存在的場合可以發動。雙方的額外牌組的卡全部送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93078761,'賽挑戰',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：擲1次骰子，出現1、6的場合，從牌組將1張持有擲骰子效果的卡加入手牌。出現1、6以外的場合，再擲1次骰子，依照擲出點數適用以下效果。\u000a●1、6：場上的此卡回到持有者的手牌。\u000a●2～5：場上的此卡回到持有者的牌組最上方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93084621,'破械神 阿羅魃',unistr('包含「破械神」怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：以對手場上1隻表側表示怪獸為對象可以發動。只用那隻對手怪獸和我方場上的此卡為素材進行「破械神 阿羅魃」以外的1隻闇屬性連結怪獸的連結召喚。\u000a②：場上的此卡被戰鬥、效果破壞的場合，以「破械神 阿羅魃」以外的我方墓地1隻惡魔族怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93085839,'聖騎士 艾克特・德・馬利斯',unistr('「聖騎士 艾克特・德・馬利斯」的①效果1回合只能使用1次。\u000a①：將我方墓地的2隻「聖騎士」怪獸除外可以發動。此卡從手牌、墓地特殊召喚。\u000a②：用此卡作為素材的「聖騎士」怪獸的同步召喚、超量召喚不會被無效化，那次特殊召喚成功時對手不能發動魔法、陷阱、怪獸的效果。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93087299,'炎之護封劍',unistr('我方場上沒有怪獸存在的場合，對手場上的怪獸不能攻擊宣言。\u000a我方場上有怪獸存在的場合，或對手的手牌是5張以上的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93104632,'一次性密碼',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：在我方場上將1隻「安全令牌衍生物」（電子界族、光、等級4、攻/守2000）守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93104633,'安全令牌衍生物','由「一次性密碼」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93107608,'共鳴蟲','此卡被戰鬥破壞送去墓地時，可以從牌組將1隻攻擊力1500以下的昆蟲族怪獸特殊召喚到我方場上。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93108297,'液體怪獸','粘粘糊糊的融化，能在水裡自由移動的液態生命體。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93108433,'怪獸回收','選擇我方場上的1隻原持有者為我方的怪獸可以發動。選擇的怪獸和我方的手牌全部加入牌組洗牌。那之後，依照原本的手牌數量從牌組抽牌。我方的手牌有原持有者是對手的卡的場合，此卡不能發動。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93108839,'No.58 炎壓鬼 燃燒拷問',unistr('等級4怪獸×2\u000a①：1回合1次，可以從以下效果選擇1個發動。\u000a●以我方場上1隻超量怪獸為對象，此卡當作裝備卡給那隻怪獸裝備。\u000a●裝備的此卡攻擊表示特殊召喚。\u000a②：裝備怪獸可以直接攻擊對手。\u000a③：裝備怪獸給予對手戰鬥傷害時，捨棄1張手牌可以發動。給予對手500傷害。'),'●裝備','●解除裝備','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93124273,'雷普提爾的武者騎兵',unistr('【靈擺效果】\u000a【怪獸效果】\u000a①：此卡攻擊靈擺怪獸以外的對手的表側表示怪獸的傷害步驟開始時可以發動。那隻怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93125329,'金雲獸-馬龍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：此卡特殊召喚的場合可以發動。此卡的等級上升或下降1。\u000a②：此卡被送去墓地的場合，以對手場上1張表側表示卡為對象可以發動。那張卡回到手牌。'),'改變等級','回到手牌','等級上升','等級下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(93130021,'勝利蛇 XX03',unistr('①：此卡戰鬥破壞對手怪獸的場合，從以下效果選擇1個發動。\u000a●此卡的攻擊力上升400。\u000a●以場上1張表側表示的魔法、陷阱卡為對象發動。那張表側表示卡破壞。\u000a●將種族、屬性、等級、攻擊力、守備力和此卡維持相同的1隻「子機衍生物」在我方場上特殊召喚。此卡不在怪獸區域表側表示存在時，這個衍生物破壞。'),'效果1','●攻擊力上升400','●破壞1張表側的魔法、陷阱卡','●特殊召喚1隻「子機衍生物」','','','','','','','','','','','','');
INSERT INTO texts VALUES(93130022,'子機衍生物','由「勝利蛇 XX03」特殊召喚。這個衍生物的種族、屬性、等級、攻擊力、守備力和那張卡維持相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93138457,'戰鬥無力化音速','①：對手怪獸的攻擊宣言時可以發動。那次攻擊無效。那之後，可以從手牌、牌組將1隻「T.G.」怪獸或等級4以下的協調特殊召喚。','是否從手牌、牌組把1隻怪獸特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93149655,'異色眼魅影龍',unistr('【靈擺效果】\u000a①：1回合1次，另一邊的我方的靈擺區域有「異色眼」卡片存在的場合，我方的表側表示怪獸和對手怪獸進行戰鬥的攻擊宣言時可以發動。直到戰鬥階段結束時，那隻我方怪獸的攻擊力上升1200。\u000a【怪獸效果】\u000a「異色眼魅影龍」的怪獸效果1回合只能使用1次。\u000a①：靈擺召喚的此卡的攻擊給予對手戰鬥傷害時可以發動。給予對手我方的靈擺區域的「異色眼」卡片數量×1200傷害。'),'攻擊力上升1200','效果傷害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93151201,'電流金剛','此卡給予對手的生命值戰鬥傷害時，依我方場上表側表示存在的光屬性怪獸數量從對手牌組上將卡送去墓地。','牌組上的卡送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93156774,'征服鬥魂 神聖蘇',unistr('這個卡名的①②效果1回合各能使用1次，不能在同一連鎖上發動。\u000a①：我方、對手的主要階段，向對手展示手牌的1隻其他的「征服鬥魂」怪獸可以發動。此卡從手牌特殊召喚。\u000a②：我方、對手回合，可以從以下選擇1個，向對手展示那些屬性的手牌的怪獸各1隻發動。\u000a●地、闇：直到結束階段得到對手場上的攻擊力最低的1隻怪獸的控制權。\u000a●炎、闇：從牌組將超能族以外的1隻「征服鬥魂」怪獸特殊召喚。'),'效果1','●地、闇','●炎、闇','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93157004,'大日神械奧米加',unistr('協調2隻+協調以外的「大日神械」怪獸1隻\u000a此卡同步召喚成功時，場上表側表示存在的通常召喚的怪獸全部破壞。\u000a1回合1次，可以選擇我方墓地的1隻「大日神械」怪獸當作裝備卡給此卡裝備。\u000a效果怪獸的效果發動時，可以藉由將此卡裝備的1張裝備卡送去墓地，那個發動無效並破壞。'),'通常召喚的怪獸全部破壞','裝備','發動無效並破壞','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93169863,'水晶女孩',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。這個回合的結束階段，從牌組將1隻等級5以上的水屬性怪獸加入手牌。\u000a②：此卡在墓地存在的場合，我方場上有等級5以上的水屬性怪獸存在可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93170499,'朱羅紀斑龍',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方場上有恐龍族怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方主要階段可以發動。從手牌選包含「朱羅紀」卡片的2張卡捨棄。那之後，我方抽2張卡。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從牌組、額外牌組將「朱羅紀斑龍」以外的1隻「朱羅紀」怪獸送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93172951,'小丑戲幫 梅特歐',unistr('協調+協調以外的怪獸1隻以上\u000a①：我方怪獸的上級召喚成功時，對手不能發動魔法、陷阱、怪獸的效果。\u000a②：此卡被解放的場合，可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●雙方的場上、墓地的同步怪獸全部回到額外牌組。\u000a●以「小丑戲幫 梅特歐」以外的我方墓地1張「小丑戲幫」卡片為對象可以發動。那張卡加入手牌。'),'效果2','●同步怪獸回到牌組','●加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93187568,'魔法打擊者',unistr('①：此卡可以將我方墓地1張魔法卡除外，從手牌特殊召喚。\u000a②：此卡可以直接攻擊。\u000a③：此卡的戰鬥產生給我方的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93191801,'黃金鄉的盜墓者',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡發動後變成通常怪獸（不死族、光、等級5、攻1800/守1500）在怪獸區域特殊召喚（也當作陷阱卡）。我方場上有「黃金卿 埃爾德里奇」存在的場合，隨後可以從我方或對手的墓地將1張卡除外。\u000a②：我方、對手的結束階段，將墓地的此卡除外可以發動。從牌組將1張「黃金國靈藥」魔法、陷阱卡在我方場上覆蓋。'),'效果1','效果2','是否將墓地的1張卡除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93192592,'棒棒喵★黯蜜味',unistr('協調+協調以外的怪獸1隻\u000a此卡同步召喚的場合，可以將我方場上1隻連結1怪獸當作等級1協調。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從我方墓地將2隻「黯蜜」怪獸效果無效特殊召喚。\u000a②：對手發動魔法、陷阱、怪獸的效果時，讓此卡回到額外牌組可以發動。從我方墓地將最多2隻「黯蜜」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93211810,'超音速波','我方回合，選擇場上1隻「幻獸機」怪獸可以發動。選擇的怪獸在這個回合，攻擊力變成原攻擊力的2倍，不受此卡以外的魔法、陷阱卡的效果影響，向守備表示怪獸攻擊時，若攻擊力超過那個守備力，給予對手那個數值的戰鬥傷害。那之後，這個回合的結束階段時，我方場上的機械族怪獸全部破壞。此卡發動的整回合中，選擇的怪獸以外的怪獸不能攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93211836,'軍隊次世代','①：此卡解放「次世代」怪獸上級召喚時，以對手場上1張卡為對象可以發動。那張對手的卡破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93217231,'毒蛇的供物','①：以我方場上1隻爬蟲類族怪獸和對手場上2張卡為對象可以發動。那1隻我方的爬蟲類族怪獸和那2張對手的卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93220472,'克蘭特龍',unistr('我方場上有怪獸存在的場合，此卡不能召喚。\u000a我方場上沒有此卡以外的龍族怪獸存在的場合，此卡不能攻擊宣言。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93221206,'古代精靈','活了數千年的妖精。能夠操縱精靈發動攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93224848,'幻魔的殉教者','①：此卡以外的我方的手牌是2張以上，我方場上有「神炎皇 烏利亞」或「降雷皇 哈蒙」存在的場合，將手牌全部送去墓地可以發動。在我方場上將3隻「幻魔的殉教者衍生物」（惡魔族、闇、等級1、攻/守0）攻擊表示特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93224849,'幻魔的殉教者衍生物','由「幻魔的殉教者」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93229151,'憤怒風暴的神碑',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：可以從以下效果選擇1個發動。此卡的發動後，跳過下個我方戰鬥階段。\u000a●最多到對手場上的卡片數量，從對手牌組上方將卡片除外。\u000a●從額外牌組將1隻「神碑」怪獸在額外怪獸區域特殊召喚。'),'●對手牌組上方的卡除外','●從額外牌組特殊召喚','請選擇除外的數量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93236220,'圍繞星遺物的戰鬥','①：將我方場上1隻表側表示怪獸直到結束階段除外，以對手場上1隻表側表示怪獸為對象可以發動。那隻對手怪獸的攻擊力、守備力下降為了發動此卡而除外的怪獸對應的原本數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93238626,'千尊的玉座',unistr('「千尊的玉座」在我方場上只能有1張表側表示存在。\u000a對手的結束階段時，我方回復那個回合受到戰鬥傷害的次數×500生命值。\u000a我方場上的「CNo.」以外的「No.」怪獸被選擇為攻擊對象時，可以藉由將此卡送去墓地，那次攻擊無效。那之後，將1隻持有和那隻我方怪獸相同「No.」數字的「CNo.」怪獸重疊在那隻怪獸上方，當作超量召喚從額外牌組特殊召喚。'),'回復生命值','攻擊無效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93260132,'魔法效果之箭','①：對手場上的表側表示的魔法卡全部破壞，給予對手破壞數量×500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93294363,'百臂無形誘惑手',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「百臂無形」怪獸存在，對手發動怪獸的效果時可以發動。那個發動無效並破壞。那之後，可以將破壞的怪獸在我方場上特殊召喚。'),'','是否特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93294869,'傷炎星-狼松','此卡反轉的場合，可以從牌組選1張「炎舞」陷阱卡在我方場上覆蓋。用反轉召喚而反轉的場合，隨後可以從牌組選1張「炎舞」魔法卡在我方場上覆蓋。','檢索','是否選擇1張「炎舞」魔法卡覆蓋在我方場上？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93298460,'魔裝戰士 風之青龍',unistr('①：此卡可以直接攻擊。\u000a②：此卡從場上送去墓地的場合，以我方墓地1隻龍族、戰士族、魔法使族的通常怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93302695,'Kozmo-達克蘿絲',unistr('「Kozmo-達克蘿絲」的①效果1回合只能使用1次。\u000a①：將場上的此卡除外可以發動。從手牌將1隻等級5以上的「Kozmo」怪獸特殊召喚。此效果在對手回合也能發動。\u000a②：1回合1次，支付1000生命值可以發動。這個回合，此卡不會被戰鬥、效果破壞。此效果在對手回合也能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93317313,'DD防衛士兵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：可以從以下效果選擇1個發動。\u000a●以我方的靈擺區域1張「DD」卡片為對象可以發動。那張卡特殊召喚。\u000a●從我方墓地將1隻「DD」怪獸除外可以發動。這個回合，我方的「DDD」怪獸攻擊的場合，對手直到傷害步驟結束時不能發動卡的效果。\u000a②：將墓地的此卡除外可以發動。從我方的額外牌組（表側）、墓地將1隻「DD」靈擺怪獸加入手牌。'),'●特殊召喚','●對手不能發動效果','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93332803,'怒炎壞獸 多哥蘭',unistr('①：此卡可以將對手場上的1隻怪獸解放，從手牌攻擊表示特殊召喚到對手場上。\u000a②：對手場上有「壞獸」怪獸存在的場合，此卡可以從手牌攻擊表示特殊召喚。\u000a③：「壞獸」怪獸在我方場上只能有1隻表側表示存在。\u000a④：1回合1次，去除我方、對手場上的3個壞獸計數器可以發動（此效果發動的整回合中，此卡不能攻擊）。對手場上的怪獸全部破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93343894,'水之魔導師','用水包圍對手，發動包抄攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93346024,'洞穴的潛龍','洞穴的巨大潛龍的巨龍。平時很溫順，但是生氣就很恐怖。據說是在守著巨大的財富。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93347961,'E.HERO 火焰翼人-火焰射擊',unistr('屬性不同的「E.HERO」怪獸×2\u000a此卡只能用融合召喚來特殊召喚。這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。從我方的牌組、墓地選1張「至愛」卡片加入手牌。\u000a②：將用通常怪獸為素材融合召喚的此卡解放可以發動。從牌組、額外牌組將1隻等級7以下的不能通常召喚的「E.HERO」怪獸無視召喚條件特殊召喚。'),'效果1','效果2','用通常怪獸為素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93353691,'不退的荒武者',unistr('戰士族協調+協調以外的戰士族怪獸1隻以上\u000a此卡被攻擊力高於此卡的攻擊力的怪獸攻擊的場合，此卡不會被戰鬥破壞。\u000a那次傷害計算後，進行戰鬥的對手怪獸破壞。'),'進行戰鬥的怪獸破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93356623,'魔彈-交叉統治者',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「魔彈」怪獸存在的場合，以場上1隻表側表示怪獸為對象可以發動。直到回合結束時，那隻怪獸的攻擊力、守備力變成0，效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93360904,'黯蜜遊樂★巨可口',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方將獸族、光屬性同步怪獸同步召喚的場合，以對手場上1張卡為對象可以發動。那張卡破壞。\u000a②：我方場上的表側表示怪獸因對手的效果從場上離開的場合可以發動。從牌組將1隻「黯蜜」怪獸特殊召喚。\u000a③：此卡在墓地存在的場合，以我方的墓地、除外狀態的2隻「黯蜜」怪獸為對象可以發動。那些怪獸和此卡以喜歡的順序回到牌組下方。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93368494,'魔之妖仙獸 大刃禍是',unistr('【靈擺效果】\u000a①：我方場上的「妖仙獸」怪獸的攻擊宣言時可以發動。那隻攻擊怪獸的攻擊力直到戰鬥階段結束時上升300。\u000a【怪獸效果】\u000a此卡只能以靈擺召喚來特殊召喚。\u000a①：此卡的靈擺召喚不會被無效化。\u000a②：此卡召喚、特殊召喚成功的場合，以場上最多2張卡為對象可以發動。那些卡回到持有者的手牌。\u000a③：此卡特殊召喚的回合的結束階段發動。此卡回到持有者的手牌。'),'靈擺效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93369354,'生化魚-槍手',unistr('我方場上有等級3以下的水屬性怪獸存在的場合，捨棄1張手牌可以發動。此卡從墓地特殊召喚。\u000a將此卡作為同步素材的場合，其他的同步素材怪獸必須全部都是水屬性怪獸。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93377803,'孤毒之劍',unistr('只能給我方場上的怪獸裝備。\u000a①：「孤毒之劍」在我方場上只能有1張表側表示存在。\u000a②：裝備怪獸的原本的攻擊力、守備力只在和對手怪獸進行戰鬥的傷害計算時變成2倍。\u000a③：我方場上有裝備怪獸以外的怪獸存在的場合，此卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93379652,'寶石騎士 彩稜柱',unistr('「寶石騎士」怪獸+雷族怪獸\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：1回合1次，從手牌將1張「寶石騎士」卡片送去墓地，以場上1張表側表示卡為對象可以發動。那張表側表示卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93382620,'生命之繩','我方的怪獸因戰鬥送去墓地時，捨棄全部手牌可以發動。對象怪獸的攻擊力上升800，在場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93394164,'平行裝甲車砲',unistr('只能給連結怪獸裝備。這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，我方主要階段可以發動。裝備怪獸的位置向那隻怪獸指向的主要怪獸區域移動（不能向從那隻怪獸所見的對手場上移動）。\u000a②：將裝備的此卡送去墓地可以發動。選和此卡裝備過的場上的怪獸相同縱列的1張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93396832,'角笛粉碎','要讓怪獸的召喚、特殊召喚無效的怪獸的效果、陷阱卡發動時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93413793,'宇迦御狐之魂搖',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，我方場上有獸族、植物族、天使族且等級4以下的光屬性怪獸存在的場合可以發動。此卡特殊召喚。\u000a②：以此卡為素材同步召喚的怪獸得到以下效果。\u000a●此卡的守備力上升500。\u000a●只要此卡在怪獸區域守備表示存在，對手不能將此卡作為效果的對象。'),'效果1','','「宇迦御狐之魂搖」的效果2適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93431518,'連接暗黑界的結界通路',unistr('此卡發動的整回合中，我方不能用此卡的效果以外將怪獸召喚、反轉召喚、特殊召喚。\u000a①：以我方墓地1隻「暗黑界」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93431862,'D-HERO 扣擊小子','藉由從手牌將1張「D-HERO」卡片送去墓地，給予對手500傷害。','給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93437091,'賓果機GO！GO！',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組選以下的卡合計3張向對手展示，對手從其中隨機選1張。那1張卡加入我方的手牌，剩下的卡回到牌組。\u000a●「青眼」怪獸\u000a●除了「賓果機GO！GO！」以外，記載「青眼白龍」「青眼究極龍」其中任何卡名的魔法、陷阱卡'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93445074,'灰籃眼鏡蛇',unistr('①：我方的怪獸區域的此卡被戰鬥或陷阱卡的效果破壞送去墓地的場合，以對手場上1隻表側表示怪獸為對象可以發動。此卡當作裝備卡給那隻對手怪獸裝備。\u000a②：此卡的效果讓此卡裝備中的場合，得到裝備怪獸的控制權。此卡從場上離開時裝備怪獸破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93449450,'F.A. 馬赫側掛車手',unistr('①：此卡的攻擊力上升此卡的等級×300，不受原本的等級或階級低於此卡的等級的對手怪獸發動的效果影響。\u000a②：「F.A.」魔法、陷阱卡的效果發動的場合可以發動（傷害步驟也能發動）。此卡的等級上升1。\u000a③：此卡的等級是7以上的場合，送去對手墓地的卡不去墓地而是除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93451636,'發條蜜蜂','此卡被戰鬥破壞送去墓地時，可以從牌組將1隻等級4以下的「發條」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93453053,'碼麗絲鏡中奇緣',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以對手場上1隻表側表示怪獸為對象可以發動。從我方的手牌、場上（表側表示）將1隻「碼麗絲」怪獸除外，對象怪獸的效果直到回合結束時無效。\u000a②：此卡被除外的場合，以我方墓地1張「碼麗絲」卡片為對象可以發動。那張卡除外，從牌組將1張和除外的卡相同種類（怪獸、魔法、陷阱）的「碼麗絲」卡片加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93454062,'大植然螻蛄',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，將此卡解放可以發動。從牌組將1隻「大植然」怪獸特殊召喚。攻擊力最高的怪獸在對手場上存在的場合，此效果特殊召喚的數量可以變成2隻。\u000a②：此卡在墓地存在的狀態，對手從額外牌組將怪獸特殊召喚的場合，或我方從額外牌組將「大植然」怪獸特殊召喚的場合可以發動。此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93469007,'爆裂爆破','解放我方場上的1隻「/爆裂」怪獸可以發動。給予雙方那隻怪獸的等級×200傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93473606,'驚奇遊樂設施 神奇摩天輪',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以1隻我方場上的「驚樂園」怪獸或對手場上的表側表示怪獸為對象可以發動此卡。此卡當作裝備卡給那隻怪獸裝備。\u000a②：可以依照裝備怪獸的控制者，發動以下效果。\u000a●我方：雙方的主要階段可以發動。選1張手牌回到牌組最下方。那之後，我方從牌組抽1張卡。\u000a●對手：裝備怪獸的攻擊力、守備力直到回合結束時交換。'),'●我方','●對手','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93481594,'DoReMi和弦 幸福多重奏',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●選1張我方的手牌捨棄，從牌組將靈擺刻度不同的2隻「DoReMi和弦」靈擺怪獸加入手牌。那之後，最多到對手場上的怪獸數量+1隻，可以從手牌將「DoReMi和弦」靈擺怪獸特殊召喚。\u000a●這個回合，我方在通常的靈擺召喚之外只有1次，可以在我方主要階段將「DoReMi和弦」怪獸靈擺召喚。\u000a●我方的靈擺區域2張「DoReMi和弦」卡片特殊召喚。'),'效果1','●從牌組加入手牌','●增加1次靈擺召喚','●特殊召喚','是否特殊召喚？','靈擺召喚（DoReMi和弦 幸福多重奏）','','','','','','','','','','');
INSERT INTO texts VALUES(93483212,'極神聖帝 奧丁',unistr('「極星天」協調+協調以外的怪獸2隻以上\u000a①：1回合1次，我方主要階段可以發動。此卡直到回合結束時不受魔法、陷阱卡的效果影響。\u000a②：場上的表側表示的此卡被對手破壞送去墓地的回合的結束階段，從我方墓地將1隻「極星天」協調除外可以發動。此卡從墓地特殊召喚。\u000a③：此卡的②效果特殊召喚成功時可以發動。我方從牌組抽1張卡。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93490856,'相劍軍師-龍淵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將手牌的其他的1張「相劍」卡片或1隻幻龍族怪獸捨棄可以發動。此卡從手牌特殊召喚。那之後，可以在我方場上將1隻「相劍衍生物」（幻龍族、協調、水、等級4、攻/守0）特殊召喚。只要此效果特殊召喚的衍生物存在，我方除了同步怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡作為同步素材送去墓地的場合可以發動。給予對手1200傷害。'),'效果1','效果2','是否特殊召喚衍生物？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93490857,'相劍衍生物','由「相劍」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93503294,'幻變騷靈 隱私王班西',unistr('「幻變騷靈」怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，將此卡以外的我方場上1隻「幻變騷靈」怪獸解放可以發動。從牌組將1隻「幻變騷靈」怪獸在此卡指向的我方場上特殊召喚。\u000a②：此卡從場上送去墓地的場合，以我方墓地1張「幻變騷靈」卡片為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93504463,'邁向進化的吊橋','我方場上的怪獸被選擇作為攻擊對象時可以發動。選擇我方墓地1隻「進化蟲」怪獸特殊召喚，攻擊對象轉移到那隻怪獸進行傷害計算。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93506862,'咒法虛無','我方的主要階段時，將此卡從手牌捨棄可以發動。這個回合，應對「咒法」儀式魔法卡的發動，對手不能發動魔法、陷阱、效果怪獸的效果，「咒法」儀式怪獸儀式召喚成功時，對手不能發動魔法、陷阱、效果怪獸的效果。','發動限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93507434,'恐龍摔角手 卡帕撲翼龍',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：對手場上的怪獸數量比我方場上的怪獸多的場合，以對手場上1隻怪獸為對象可以發動。那隻怪獸送去墓地。\u000a②：此卡作為「恐龍摔角手」連結怪獸的連結素材送去墓地的場合可以發動。那隻連結怪獸的攻擊力直到回合結束時上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93509766,'恐巄龍華-㟴巴',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：讓此卡從手牌回到牌組可以發動。從牌組將1張「登龍華恐巄門」加入手牌。\u000a②：2張以上的卡被破壞的回合的我方、對手的主要階段可以發動。此卡從手牌特殊召喚。\u000a③：讓我方場上1張表側表示的「登龍華恐巄門」回到牌組最下方，最多到場上的種族種類的數量，以場上的其他卡為對象可以發動。那些卡破壞。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93542102,'變形鬥士 手機',unistr('①：此卡依照表示形式得到以下效果。\u000a●攻擊表示：1回合1次，我方主要階段可以發動。擲1次骰子，從我方牌組上方翻開擲出點數的數量的卡。從其中選1隻等級4以下的「變形鬥士」怪獸無視召喚條件特殊召喚，其餘回到牌組。\u000a●守備表示：1回合1次，我方主要階段可以發動。擲1次骰子，從我方牌組上方確認擲出點數的數量的卡。'),'●攻擊表示：','●守備表示：','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93543806,'先史遺產 太陽石碑柱','1回合1次，選擇我方場上1隻「先史遺產」怪獸可以發動。那隻怪獸的等級變成6。此效果發動的整回合中，我方除了「先史遺產」怪獸以外不能特殊召喚。','等級變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93553943,'食人花','吃人的人面花。用帶毒的觸手攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93554166,'暗黑界之雷','①：以場上覆蓋的1張卡為對象可以發動。那張覆蓋的卡破壞。那之後，選1張我方的手牌捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93568288,'No.80 狂裝霸王 狂想戰曲',unistr('等級4怪獸×2\u000a這個卡名的①效果1回合可以使用最多2次。\u000a①：去除此卡的1個超量素材，以對手墓地1張卡為對象可以發動。那張卡除外。\u000a②：以我方場上1隻超量怪獸為對象可以發動。我方場上的此卡當作攻擊力上升1200的裝備卡給那隻我方怪獸裝備。'),'效果2','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93581434,'剛鬼 地獄教練',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上沒有怪獸存在的場合，向對手展示手牌的此卡，以我方墓地1隻「剛鬼」連結怪獸為對象可以發動。此卡從手牌特殊召喚。那之後，對象怪獸特殊召喚。此效果特殊召喚的連結怪獸攻擊力下降500。\u000a②：只要我方場上有「剛鬼」連結怪獸存在，此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93595154,'烙印的裁決',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以我方場上1隻等級8以上的融合怪獸為對象可以發動。對手場上的攻擊力在那隻怪獸的攻擊力以上的怪獸全部破壞。\u000a②：此卡為了發動「阿不思的落胤」的效果而被送去墓地的回合的結束階段可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93599951,'沉默的邪惡靈',unistr('對手怪獸攻擊的戰鬥步驟，以那1隻攻擊怪獸和對手場上的1隻其他的表側表示怪獸為對象可以發動。那次攻擊無效，那隻對手的表側表示怪獸（守備表示的場合變成攻擊表示）和相同的攻擊對象戰鬥並進行傷害計算。\u000a[按照判例修正]'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93600443,'假面變身二式',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：捨棄1張手牌，以我方場上1隻表側表示怪獸為對象可以發動。確認那隻怪獸的屬性，送去墓地。此效果讓那隻怪獸從場上離開的場合，隨後將1隻等級高於那隻怪獸且持有相同屬性的「M.HERO」怪獸當作「假面變身」的效果從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93612434,'雙持手槍龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡解放，以我方墓地2隻卡名不同的「槍彈」怪獸為對象可以發動。那些怪獸守備表示特殊召喚。\u000a②：將墓地的此卡除外可以發動。從我方的牌組、墓地選1張「速射扳機」或「重型扳機」加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93655221,'盾牌管理器','①：要讓場上的怪獸破壞的魔法、陷阱、怪獸的效果發動時，以我方以及對手場上的連結怪獸各1隻為對象可以發動此卡。作為對象的對手怪獸的效果無效，此卡當作裝備卡給作為對象的我方怪獸裝備。裝備怪獸不會被效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93657021,'D-HERO 暮托邦小子',unistr('「D-HERO」融合怪獸+「D-HERO」怪獸\u000a①：此卡融合召喚的場合可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻融合怪獸融合召喚。\u000a②：我方、對手回合1次，以場上1隻怪獸為對象可以發動。這個回合，那隻怪獸不會被戰鬥、效果破壞，那隻怪獸的戰鬥產生給雙方的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93662626,'點火騎士 烏茲',unistr('【靈擺效果】\u000a①：另一邊的我方的靈擺區域有「點火騎士」卡片存在的場合可以發動。我方的靈擺區域的卡全部破壞，從我方的牌組、墓地選1隻戰士族、炎屬性怪獸加入手牌。\u000a【怪獸敘述】\u000a「德林格」的監督官兼親衛隊隊長。總是被魯莽行事的她牽著鼻子走，經常跟唯一的知己「點五零」吐露苦水。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93665266,'水晶機巧-量子白晶',unistr('「水晶機巧-量子白晶」的效果1回合只能使用1次。\u000a①：對手的主要階段以及戰鬥階段可以發動。從手牌將1隻協調以外的怪獸效果無效特殊召喚，只用那隻怪獸和此卡為素材同步召喚1隻機械族同步怪獸。'),'同步召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93671934,'士氣高揚',unistr('裝備魔法卡給怪獸裝備時，裝備魔法卡的控制者回復1000生命值。\u000a裝備魔法卡從場上離開時，裝備魔法卡的控制者受到1000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93672138,'Evil★Twin''s 麻煩桑妮',unistr('包含「Evil★Twin」怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，將此卡解放可以發動。從我方墓地將「姬絲吉爾」怪獸和「璃拉」怪獸各最多1隻特殊召喚。\u000a②：將墓地的此卡除外，從我方的手牌、牌組、場上（表側表示）將1隻「Evil★Twin」怪獸送去墓地可以發動。場上1張卡送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93683815,'聖龍瓦盧米娜像',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：我方的陷阱卡的效果將怪獸特殊召喚的場合，以場上1張卡為對象可以發動。那張卡回到手牌。那之後，可以將此卡特殊召喚。\u000a【怪獸效果】\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。場上的此卡在我方的靈擺區域放置，那隻對手怪獸回到手牌。\u000a②：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區放置。'),'效果1','效果2','靈擺效果1','是否將此卡特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(93684009,'劍鬥排斥波',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的「劍鬥獸」怪獸在戰鬥階段以外不會成為對手的效果的對象。\u000a②：從我方牌組有「劍鬥獸」怪獸特殊召喚的場合可以發動。從牌組選1隻相同種族的怪獸不在我方場上存在的「劍鬥獸」怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93708824,'十六夜薔薇龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將「十六夜薔薇龍」以外的1張記載「黑薔薇龍」的卡名的卡加入手牌。\u000a②：此卡在墓地存在，我方場上的表側表示的「薔薇龍」怪獸或植物族同步怪獸被戰鬥或對手的效果破壞的場合可以發動。此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93709215,'暗冥破壞神',unistr('此卡不能特殊召喚。\u000a此卡攻擊守備怪獸時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a此卡在1次戰鬥階段中可以攻擊2次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93713837,'No.24 龍血鬼 德拉古勒斯',unistr('等級6怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以從額外牌組特殊召喚的1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。此效果在對手回合也能發動。\u000a②：表側表示的此卡因對手的效果從場上離開，被送去墓地的場合或被除外的場合可以發動。此卡裡側守備表示特殊召喚。\u000a③：此卡反轉的場合發動。選場上1張卡送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93715853,'魔神 大神機','①：此卡給予對手戰鬥傷害時可以發動。從我方的手牌、墓地選1隻通常怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93717133,'銀河眼光子龍',unistr('①：此卡可以將我方場上2隻攻擊力2000以上的怪獸解放，從手牌特殊召喚。\u000a②：此卡和對手怪獸進行戰鬥的戰鬥步驟，以那1隻對手怪獸為對象可以發動。那隻對手怪獸和場上的此卡除外。此效果除外的怪獸在戰鬥階段結束時回到場上，此效果將超量怪獸除外的場合，此卡的攻擊力上升那隻超量怪獸除外時的超量素材數量×500。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93717134,'銀河眼光子龍',unistr('①：此卡可以將我方場上2隻攻擊力2000以上的怪獸解放，從手牌特殊召喚。\u000a②：此卡和對手怪獸進行戰鬥的戰鬥步驟，以那1隻對手怪獸為對象可以發動。那隻對手怪獸和場上的此卡除外。此效果除外的怪獸在戰鬥階段結束時回到場上，此效果將超量怪獸除外的場合，此卡的攻擊力上升那隻超量怪獸除外時的超量素材數量×500。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93717135,'銀河眼光子龍',unistr('①：此卡可以將我方場上2隻攻擊力2000以上的怪獸解放，從手牌特殊召喚。\u000a②：此卡和對手怪獸進行戰鬥的戰鬥步驟，以那1隻對手怪獸為對象可以發動。那隻對手怪獸和場上的此卡除外。此效果除外的怪獸在戰鬥階段結束時回到場上，此效果將超量怪獸除外的場合，此卡的攻擊力上升那隻超量怪獸除外時的超量素材數量×500。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93723936,'白森林的魔鬼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻同步怪獸解放，以場上1張表側表示卡為對象可以發動。那張卡的效果直到回合結束時無效。將「白森林」同步怪獸解放發動的場合，隨後可以從我方墓地將1隻幻想魔族怪獸特殊召喚。\u000a②：此卡為了發動怪獸的效果而被送去墓地的場合可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93724592,'機偶忍者 三三九',unistr('此卡可以攻擊的場合必須攻擊。\u000a場上表側攻擊表示的此卡被選擇作為攻擊對象時，此卡的表示形式變成守備表示。\u000a此卡反轉時，選擇場上表側表示存在的1隻怪獸送去墓地。\u000a此卡反轉的回合，此卡可以直接攻擊對手玩家。'),'變為守備表示','送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93729065,'飢餓仇毒龍',unistr('【靈擺效果】\u000a①：每次場上的卡被送去墓地，每有1張給此卡放置1個仇毒計數器。\u000a②：龍族、闇屬性怪獸以外的場上的怪獸的攻擊力下降場上的仇毒計數器的數量×200。\u000a③：1回合1次，可以將戰鬥產生給我方的戰鬥傷害變成0。\u000a【怪獸效果】\u000a闇屬性怪獸+靈擺怪獸\u000a這個卡名的①怪獸效果1回合只能使用1次。\u000a①：以對手場上1隻表側表示怪獸為對象可以發動。直到結束階段，此卡和那隻怪獸當作同名卡，得到相同效果。那之後，對象怪獸的攻擊力、守備力下降500，效果無效化，給予對手500傷害。\u000a②：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果3','效果1','效果2','是否將戰鬥產生給我方的戰鬥傷害變成0？','解除複製效果','','','','','','','','','','','');
INSERT INTO texts VALUES(93729896,'夢魘王座',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：作為此卡的發動時的效果處理，可以適用以下效果。\u000a●從牌組選1隻攻擊力和守備力是0的惡魔族怪獸加入手牌或破壞。\u000a②：1回合1次，我方場上的表側表示的「尤貝爾」怪獸因效果從場上離開的場合可以發動。原等級比其中1隻高1級或低1級的1隻「尤貝爾」怪獸從我方的牌組、墓地、除外狀態加入手牌。那之後，可以將那隻怪獸無視召喚條件特殊召喚。'),'是否選牌組的惡魔族怪獸？','效果2','是否將那隻怪獸破壞？','是否特殊召喚？','','','','','','','','','','','','');
INSERT INTO texts VALUES(93730230,'先史遺產 水晶外星生命',unistr('等級3怪獸×2\u000a1回合1次，此卡被選擇作為攻擊對象時，去除此卡的1個超量素材可以發動。這個回合此卡不會被戰鬥以及效果破壞，此卡的戰鬥產生給我方的戰鬥傷害由對手代為承受。'),'不會被戰鬥以及卡片效果破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93730409,'真空鐮鼬','①：此卡反轉的場合發動。這個回合，對手不能發動魔法、陷阱卡。','發動限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93738004,'空牙團的孤高 莎吉塔',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。給予對手「空牙團的孤高 莎吉塔」以外的我方場上的「空牙團」怪獸種類×500傷害。\u000a②：只要此卡在怪獸區域存在，對手不能將此卡以外的我方場上的「空牙團」怪獸作為效果的對象。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93747864,'沙漠之光','我方場上的怪獸全部變成表側守備表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93749093,'棉花糖馬卡龍',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡被戰鬥、效果破壞的場合可以發動。從我方的手牌、牌組、墓地選此卡以外最多2隻「棉花糖馬卡龍」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93751476,'猛炎星-馴鹿明',unistr('此卡被效果破壞送去墓地的回合的結束階段時，可以從牌組將「猛炎星-馴鹿明」以外的1隻等級4的「炎星」怪獸特殊召喚。\u000a此卡被「炎星」同步怪獸的同步召喚使用送去墓地的場合，可以從牌組選1張「炎舞」魔法卡在我方場上覆蓋。'),'從牌組特殊召喚','從牌組覆蓋','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93754402,'炎舞-「洞明」',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以適用以下效果。\u000a●解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻獸戰士族儀式怪獸。\u000a②：魔法與陷阱區域的表側表示的此卡被送去墓地的場合，以我方墓地1隻「炎星」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果2','是否儀式召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93775296,'反轉再利用','①：以我方墓地最多2隻反轉怪獸為對象可以發動。那些怪獸表側守備表示或裡側守備表示在對手場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93777634,'No.39 希望皇霍普昇華',unistr('等級4怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以「No.39 希望皇霍普昇華」以外的我方墓地1隻「No.」超量怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。那之後，可以將此卡的超量素材全部作為那隻怪獸的超量素材。\u000a②：我方將怪獸超量召喚的場合可以發動。此卡從墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','是否轉移超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93788854,'徬徨的亡者','不能成佛而到處遊蕩的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93816465,'零式守衛者','解放此卡可以發動。這個回合，我方的怪獸不會被戰鬥破壞，和對手怪獸的戰鬥產生給我方的戰鬥傷害變成0。此效果在對手回合也能發動。','防止戰鬥破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93830681,'殺手皺鰓鮫','我方場上的魚族、海龍族、水族怪獸被選擇作為攻擊對象時，將墓地的此卡除外，選擇1隻攻擊怪獸可以發動。選擇的怪獸的攻擊無效，那個攻擊力直到下個我方回合結束時下降500。「殺手皺鰓鮫」的效果1回合只能使用1次。','攻擊無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93850652,'空牙團的劍士 彼特',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將「空牙團的劍士 彼特」以外的1隻「空牙團」怪獸特殊召喚。\u000a②：此卡已在怪獸區域存在的狀態，我方場上有此卡以外的「空牙團」怪獸特殊召喚的場合可以發動。從牌組將「空牙團的劍士 彼特」以外的1隻「空牙團」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93850690,'大靈峰相劍門',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方墓地1隻「相劍」怪獸為對象可以發動（我方場上有同步怪獸存在的場合，也能改成以1隻幻龍族怪獸為對象）。那隻怪獸特殊召喚。\u000a②：此卡被除外的場合，以我方場上1隻「相劍」怪獸或幻龍族怪獸為對象可以發動。那隻怪獸的等級直到回合結束時上升或下降1。'),'效果1','效果2','等級上升','等級下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(93854893,'宵星的自鳴天琴 丁吉爾蘇',unistr('等級8怪獸×2\u000a我方1回合只能特殊召喚1次「宵星的自鳴天琴 丁吉爾蘇」，此卡也能重疊在我方場上的「自鳴天琴」連結怪獸上方來超量召喚。\u000a①：此卡特殊召喚成功的場合，可以從以下效果選擇1個發動。\u000a●對手場上1張卡送去墓地。\u000a●我方的除外狀態的1隻機械族怪獸作為此卡的超量素材。\u000a②：我方場上的卡被戰鬥、效果破壞的場合，可以去除此卡的1個超量素材作為代替。'),'是否重疊在「自鳴天琴」連結怪獸上方來超量召喚？','●對手場上的卡送去墓地','●補充超量素材','請選擇要作為超量素材的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(93854894,'宵星的自鳴天琴 丁吉爾蘇',unistr('等級8怪獸×2\u000a我方1回合只能特殊召喚1次「宵星的自鳴天琴 丁吉爾蘇」，此卡也能重疊在我方場上的「自鳴天琴」連結怪獸上方來超量召喚。\u000a①：此卡特殊召喚成功的場合，可以從以下效果選擇1個發動。\u000a●對手場上1張卡送去墓地。\u000a●我方的除外狀態的1隻機械族怪獸作為此卡的超量素材。\u000a②：我方場上的卡被戰鬥、效果破壞的場合，可以去除此卡的1個超量素材作為代替。'),'是否重疊在「自鳴天琴」連結怪獸上方來超量召喚？','●對手場上的卡送去墓地','●補充超量素材','請選擇要作為超量素材的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(93860227,'優麗的靈鏡姬',unistr('已裝備怪獸卡的怪獸+惡魔族怪獸卡\u000a只能將我方的手牌、場上的上述卡送去墓地來特殊召喚。\u000a這個卡名的②效果1回合只能使用1次。\u000a①：「優麗的靈鏡姬」在我方場上只能有1張表側表示存在。\u000a②：怪獸為了發動卡的效果而從手牌被送去墓地的場合，可以從以下效果選擇1個發動。\u000a●其中1隻當作攻擊力上升500的裝備魔法卡給此卡裝備。\u000a●我方抽1張卡。'),'效果2','●當作裝備魔法卡','●抽1張卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93871599,'龍引導的呼笛',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：場上有魔法使族怪獸存在的場合可以發動。從牌組將1隻等級5以上的龍族怪獸特殊召喚。對手場上有2隻以上怪獸存在的場合，隨後可以將特殊召喚的怪獸的1隻同名怪獸從牌組特殊召喚。這個回合，我方除了龍族、魔法使族怪獸以外不能特殊召喚。\u000a②：我方主要階段2，將這個回合送去墓地的此卡除外可以發動。我方抽1張卡。'),'效果1','效果2','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93871600,'龍引導的呼笛',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：場上有魔法使族怪獸存在的場合可以發動。從牌組將1隻等級5以上的龍族怪獸特殊召喚。對手場上有2隻以上怪獸存在的場合，隨後可以將特殊召喚的怪獸的1隻同名怪獸從牌組特殊召喚。這個回合，我方除了龍族、魔法使族怪獸以外不能特殊召喚。\u000a②：我方主要階段2，將這個回合送去墓地的此卡除外可以發動。我方抽1張卡。'),'效果1','效果2','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93877990,'富炎星-應天鵝',unistr('獸戰士族怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚成功的場合可以發動。給予對手我方場上的「炎舞」魔法、陷阱卡數量×200傷害。\u000a②：我方、對手的戰鬥階段，將我方場上1張表側表示的「炎舞」魔法、陷阱卡送去墓地，以對手場上1張卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93880808,'天位凱旋騎士小丑',unistr('①：此卡在手牌、墓地存在的場合，從手牌以及我方場上的表側表示怪獸之中，將「皇后騎士」「傑克騎士」「國王騎士」各1隻送去墓地可以發動。此卡特殊召喚。\u000a②：此卡的攻擊力上升雙方的手牌數量×500。\u000a③：捨棄1張手牌可以發動。和捨棄的卡相同種類（怪獸、魔法、陷阱）的對手場上的表側表示的卡全部破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93882364,'次世代工人','①：將此卡解放可以發動。從手牌將1隻「次世代」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93889755,'殺人小丑','場上守備表示的此卡變成攻擊表示時，選擇對手場上的1隻怪獸回到持有者的手牌。','回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93892436,'娛樂夥伴 鞦韆眼鏡蛇',unistr('【靈擺效果】\u000a①：1回合1次，我方怪獸給予對手戰鬥傷害時可以發動。對手牌組最上方的卡送去墓地。\u000a【怪獸效果】\u000a①：此卡可以直接攻擊。\u000a②：此卡攻擊的場合，在戰鬥階段結束時變成守備表示。'),'對手牌組上面的卡送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93895605,'仇恨炸彈','①：我方的惡魔族怪獸被選擇作為攻擊對象時，以1隻攻擊怪獸和那1隻攻擊對象怪獸為對象可以發動。那個攻擊怪獸和那個攻擊對象怪獸共2隻破壞，依照破壞的攻擊怪獸的原攻擊力數值給予對手傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93896655,'聖天樹的幼精',unistr('等級4以下的植物族怪獸1隻\u000a①：此卡用「聖種的地靈」為素材在額外怪獸區域連結召喚的場合可以發動。從牌組將1張「聖蔓」魔法、陷阱卡加入手牌。\u000a②：此卡不會成為攻擊對象（我方場上只有適用此效果的怪獸存在的狀態，對手可以向我方直接攻擊）。\u000a③：1回合1次，我方因戰鬥、效果受到傷害的場合可以發動。我方的生命值回復那個數值，從額外牌組將1隻「聖蔓」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93898740,'破械習合',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以包含我方場上的「破械神」連結怪獸的，我方、對手場上2隻表側表示怪獸為對象可以發動。只用那2隻怪獸為素材進行1隻惡魔族連結怪獸的連結召喚。\u000a②：覆蓋的此卡被效果破壞的場合可以發動。從牌組將1隻「破械」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93900406,'蘑菇怪人',unistr('每次我方的準備階段，給予控制者300傷害。\u000a我方的結束階段時，可以藉由支付500生命值，此卡的控制權轉移給對手。'),'給予控制者傷害','轉移控制權','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93912845,'復活禮物','選擇我方墓地1隻協調特殊召喚。此效果特殊召喚的怪獸的效果無效化。在對手場上將2隻「禮物魔衍生物」（惡魔族、闇、等級3、攻/守1500）特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93912846,'禮物魔衍生物','由「復活禮物」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93918159,'超越天翔',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從雙方墓地的怪獸以及被除外的怪獸之中，以1隻恐龍族怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93920420,'星遺物-『星杖』',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：通常召喚的此卡不會被從額外牌組特殊召喚的怪獸戰鬥破壞。\u000a②：此卡被送去墓地的場合可以發動。從手牌將1隻「星遺物」怪獸特殊召喚。\u000a③：將墓地的此卡除外，以我方的除外狀態的1隻「自鳴天琴」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了闇屬性怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93920745,'企鵝士兵','①：此卡反轉的場合，以場上最多2隻怪獸為對象可以發動。那些怪獸回到持有者的手牌。','回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93927067,'血腥斧獸人皇帝',unistr('①：我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡戰鬥破壞對手怪獸的場合發動。此卡的攻擊力上升500。\u000a③：此卡被戰鬥破壞的場合發動。破壞此卡的怪獸的攻擊力下降500。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93946239,'無之煉獄','我方的手牌是3張以上的場合可以發動。從我方牌組抽1張卡，這個回合的結束階段時，我方的手牌全部捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93953933,'著陸九頭蛇 軌道分機',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方墓地有4隻以上怪獸存在，且那些卡名全部不同的場合，將此卡解放可以發動。依照我方墓地的怪獸數量，從我方牌組上方翻開卡片。翻開2隻以上怪獸，且那些卡名全部不同的場合，將其中1隻加入手牌。剩下的卡以喜歡的順序回到牌組上方。\u000a②：將墓地的此卡除外，以我方墓地1隻怪獸為對象可以發動。那隻怪獸回到牌組最下方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93966624,'魔法進擊者','①：此卡在手牌存在的場合，以我方和對手場上各1張表側表示的魔法卡為對象可以發動。那些卡除外，此卡從手牌特殊召喚。','從手牌特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93969023,'黑鋼龍',unistr('①：以我方場上1張「真紅眼」怪獸為對象可以發動。從我方的手牌、場上將此卡當作攻擊力上升600的裝備魔法卡給那隻我方怪獸裝備。\u000a②：此卡從場上送去墓地的場合可以發動。從牌組將1張「真紅眼」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93983867,'戲法箱','①：我方場上的「娛樂法師」怪獸被戰鬥、效果破壞並送去墓地的場合，以對手場上1隻怪獸為對象可以發動。直到結束階段，我方得到那隻怪獸的控制權。那之後，從我方墓地選1隻「娛樂法師」怪獸在對手場上特殊召喚。這個回合的結束階段，此效果特殊召喚的怪獸的控制權回歸原持有者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94004268,'亞馬遜的劍士','①：此卡的戰鬥產生給我方的戰鬥傷害由對手代為承受。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94014327,'破械焰魔天 閻魔',unistr('包含「破械神」怪獸的怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方結束階段，以這個回合被破壞的我方墓地最多2隻惡魔族怪獸為對象可以發動。那些怪獸特殊召喚。只要此效果特殊召喚的怪獸在我方場上表側表示存在，我方除了惡魔族怪獸以外不能特殊召喚。\u000a②：場上的此卡被戰鬥、效果破壞的場合，可以將我方或對手場上1張表側表示卡破壞作為代替。'),'效果1','','「破械焰魔天 閻魔」的效果特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94016752,'深淵的宣告者',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手場上有表側表示怪獸存在的場合，支付1500生命值，宣言種族和屬性各1個可以發動。宣言的種族、屬性的怪獸在對手場上表側表示存在的場合，對手必須將其中1隻送去墓地。這個回合，對手不能發動那隻怪獸以及那些同名怪獸的怪獸效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94022093,'大肚海蛇','樣子很怪的海蛇。特徵是大口和大牙。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94042337,'驟雨','突然降下傾盆大雨的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94046012,'自鳴天琴 大砲卡農曲',unistr('這個卡名的效果1回合只能使用1次。\u000a①：將墓地的此卡除外可以發動。從手牌將「自鳴天琴 大砲卡農曲」以外的1隻「自鳴天琴」怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了闇屬性怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94068856,'時間通道','選擇我方場上的1隻「命運女郎」怪獸，那個等級直到回合結束時上升3。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94073244,'空牙團的擊手 砰帕',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌將「空牙團的擊手 砰帕」以外的1隻「空牙團」怪獸特殊召喚。\u000a②：此卡在怪獸區域存在的狀態，我方場上有「空牙團」怪獸特殊召喚的場合，以場上1張表側表示卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94076521,'水界的秘石 加特林',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻地、水屬性怪獸。\u000a②：此卡在墓地存在，我方場上有地屬性怪獸以及水屬性怪獸存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','召喚（水界的秘石 加特林）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94079037,'礦場鼴鼠','此卡1回合1次不會被戰鬥破壞。此卡作為獸族同步怪獸的素材送去墓地的場合，從我方牌組抽1張卡。此卡因對手的卡片效果從場上離開的場合，從遊戲中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94081496,'黑光的G','對手場上只有同步怪獸1隻特殊召喚時，將墓地的此卡除外可以發動。選擇那隻同步怪獸破壞。此效果在對手回合也能發動。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94092230,'侵入魔 威角',unistr('此卡不能特殊召喚。通常召喚此卡的場合，必須解放我方場上3隻「侵入魔」怪獸來召喚。\u000a1回合1次，可以藉由支付一半生命值，此卡以外的場上的卡全部破壞。'),'解放3隻怪獸','場上的卡全部破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94096018,'SPYGAL-霧美人',unistr('①：此卡召喚、特殊召喚成功的場合，宣言卡的種類（怪獸、魔法、陷阱）可以發動。對手牌組最上方的卡給雙方確認，如果是宣言的種類的卡，我方從牌組抽1張卡。\u000a②：1回合1次，以我方場上1隻「SPYRAL-花花公子」和對手場上1隻怪獸為對象可以發動。那2隻怪獸回到持有者的手牌。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94096616,'武尊神器-大蛇','在我方的主要階段1將此卡從手牌送去墓地，選擇我方場上1隻「武尊神」怪獸可以發動。這個回合，選擇的怪獸可以直接攻擊對手玩家。','直接攻擊','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94103142,'絢嵐之顯現',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●從牌組將1隻「絢嵐」怪獸送去墓地。\u000a●從我方的牌組、墓地將1張「氣旋」加入手牌。\u000a②：此卡被「氣旋」的效果破壞的場合可以發動。此卡在我方的魔法與陷阱區域覆蓋。'),'效果1','效果2','●「絢嵐」怪獸送去墓地','●「氣旋」加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(94113093,'塗鴉本-擋路',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的恐龍族怪獸被選擇作為攻擊對象時可以發動。那次攻擊無效。那之後，可以從我方墓地選1隻「塗鴉獸」怪獸特殊召喚。此效果特殊召喚的怪獸不會被戰鬥破壞，在結束階段破壞。\u000a②：將墓地的此卡除外可以發動。從牌組將1隻等級5以上的恐龍族怪獸加入手牌。此效果在此卡送去墓地的回合不能發動。'),'是否從墓地特殊召喚？','N/A','「塗鴉本-擋路」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94119480,'終焉的保衛者 阿德琉斯',unistr('等級5怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以對手場上1張表側表示卡為對象可以發動。那張卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94119974,'雙頭恐龍王','恐龍族中的強力卡。用2個頭同時攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94130731,'超越恐龍 凍雪龍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡不會被戰鬥破壞。\u000a②：只要此卡在怪獸區域存在，我方場上的從墓地特殊召喚的恐龍族怪獸不會成為對手的效果的對象，不會被對手的效果破壞。\u000a③：此卡被破壞的場合可以發動。從我方墓地選1隻通常怪獸回到牌組。那之後，可以將此卡特殊召喚。'),'效果3','是否將此卡特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94136469,'校驗和龍',unistr('①：對手怪獸的攻擊宣言時可以發動。此卡從手牌特殊召喚。那之後，我方的生命值回復此卡的守備力一半的數值。\u000a②：攻擊表示的此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94141712,'武裝龍閃電 LV7',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在場上、墓地存在，卡名當作「武裝龍 LV7」。\u000a②：從手牌將1隻怪獸送去墓地可以發動。場上的此卡送去墓地，從手牌、牌組將1隻等級10以下的「武裝龍」怪獸特殊召喚。\u000a③：此卡為了發動龍族怪獸的效果而被送去墓地的場合可以發動。從牌組將1張「武裝龍」卡片加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94142993,'廷達三角 侵入者',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡反轉的場合可以發動。從牌組將1張「廷達三角」卡片加入手牌。\u000a②：此卡召喚成功時可以發動。從牌組將1張「廷達三角」卡片送去墓地。\u000a③：此卡在墓地存在，我方場上有怪獸裡側守備表示特殊召喚的場合發動。此卡從墓地裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94145021,'小丑與鎖鳥','①：我方、對手回合，對手在抽牌階段以外從牌組將卡加入手牌的場合，將此卡從手牌送去墓地可以發動。這個回合，雙方不能從牌組將卡加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94145022,'小丑與鎖鳥','①：我方、對手回合，對手在抽牌階段以外從牌組將卡加入手牌的場合，將此卡從手牌送去墓地可以發動。這個回合，雙方不能從牌組將卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94145683,'燕巢','①：解放我方場上1隻表側表示的鳥獸族怪獸可以發動。從牌組將1隻和解放的怪獸等級相同的鳥獸族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94151981,'超量裝甲 魚雷',unistr('等級3怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：沒有超量素材的此卡不能攻擊。\u000a②：去除此卡的2個超量素材可以發動。我方抽1張卡。\u000a③：只要此卡裝備中，適用以下效果。\u000a●裝備怪獸進行戰鬥的場合，直到傷害步驟結束時，對手不能發動卡的效果，對手場上的表側表示怪獸的效果無效化。\u000a●裝備怪獸是超量怪獸的場合，對手不能將裝備怪獸作為效果的對象。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94156050,'逆眼鏡','場上的全部怪獸的攻擊力直到回合結束時變成一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94160895,'真龍凰 馬利亞姆內',unistr('「真龍凰 馬利亞姆內」的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從此卡以外的手牌和我方場上的表側表示怪獸之中將包含風屬性怪獸的2隻怪獸破壞，此卡從手牌特殊召喚，將2隻風屬性怪獸破壞的場合，可以從對手牌組上方將4張卡除外。\u000a②：此卡被效果破壞的場合可以發動。從牌組將1隻風屬性以外的幻龍族怪獸加入手牌。'),'從手牌特殊召喚','從牌組加入手牌','是否把對手牌組上面的4張卡除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94163677,'無限的手牌','只要此卡在場上表側表示存在，雙方的玩家沒有手牌上限。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94183877,'王戰之影 洛普特',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：「王戰之影 洛普特」在我方場上只能有1隻表側表示存在。\u000a②：我方場上的「王戰」怪獸的攻擊力、守備力在對手回合中上升1000。\u000a③：我方、對手的主要階段，將我方場上1隻「王戰」怪獸解放可以發動。從牌組將1隻和那隻怪獸卡名不同的等級9的「王戰」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94185340,'納祭升階',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻超量怪獸為對象可以發動。那隻怪獸的2個超量素材除外，從額外牌組將1隻階級比那隻怪獸高1階的超量怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。'),'「納祭升階」的效果1適用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94187078,'極超的龍輝巧',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了不能通常召喚的怪獸以外不能特殊召喚。\u000a①：從牌組將1隻「龍輝巧」怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94192409,'強制脫出裝置','①：以場上1隻怪獸為對象可以發動。那隻怪獸回到手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94192410,'強制脫出裝置','①：以場上1隻怪獸為對象可以發動。那隻怪獸回到手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94203886,'我我我小子',unistr('我方場上有「我我我小子」以外的「我我我」怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a用這個方法特殊召喚成功時，可以選擇我方場上的1隻「我我我」怪獸，此卡的等級變成和選擇的怪獸相同。此效果發動的整回合中，我方不能進行戰鬥階段。'),'等級變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94207108,'海晶少女 奇幻之心',unistr('水屬性怪獸2隻以上\u000a①：此卡和怪獸進行戰鬥的傷害計算時可以發動1次。選給此卡裝備的1張我方的「海晶少女」怪獸卡特殊召喚。此卡不會被那次戰鬥破壞，那次戰鬥產生給我方的戰鬥傷害變成0。此效果特殊召喚的怪獸在結束階段當作裝備卡給此卡裝備。\u000a②：此卡被對手破壞的場合可以發動。從我方墓地選1隻連結3以下的「海晶少女」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94212438,'威加盤',unistr('此卡和4種「死亡訊息」卡片在我方場上湊齊時，我方獲得決鬥勝利。\u000a①：對手結束階段發動此效果。從手牌、牌組將1張「死亡訊息」卡片以「E」「A」「T」「H」的順序出到我方的魔法與陷阱區域。\u000a②：我方場上的「威加盤」或「死亡訊息」卡片從場上離開時，我方場上的「威加盤」以及「死亡訊息」卡片全部送去墓地。'),'效果1','請選擇進入魔法與陷阱區域的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94215860,'夜叉',unistr('此卡不能特殊召喚。\u000a此卡召喚、反轉的回合的結束階段，此卡回到持有者的手牌。\u000a此卡召喚、反轉時，可以選擇對手場上的1張魔法、陷阱卡回到持有者的手牌。'),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94220427,'升階魔法-銀白混沌之力',unistr('這個卡名的②效果在決鬥中只能使用1次。\u000a①：以我方場上1隻階級5以上的超量怪獸為對象可以發動。將1隻階級比那隻我方怪獸高1階的「CNo.」超量怪獸或「混沌超量」超量怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。\u000a②：此卡在墓地存在的狀態，我方場上有階級5以上的超量怪獸特殊召喚時可以發動。此卡加入手牌。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94224458,'白色宿命的黃金國靈藥',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方的手牌、墓地將1隻不死族怪獸特殊召喚。我方場上沒有「埃爾德里奇」怪獸存在的場合，此效果只能將「埃爾德里奇」怪獸特殊召喚。此卡的發動後，直到回合結束時我方除了不死族怪獸以外不能特殊召喚。\u000a②：我方主要階段將墓地的此卡除外可以發動。從牌組將1張「黃金鄉」魔法、陷阱卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94230224,'針球','反轉：可以藉由支付2000生命值，給予對手1000傷害。','反轉','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94243005,'混沌空間',unistr('①：每次有怪獸被表側表示除外，每有1隻給此卡放置1個混沌計數器。\u000a②：1回合1次，去除我方場上的4個以上混沌計數器，以被除外的1隻等級和去除數量相同的我方或對手怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。\u000a③：場上的此卡被對手的效果送去墓地時可以發動。從牌組將1隻等級在此卡放置的混沌計數器的數量以下的光、闇屬性怪獸加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94253609,'元素吸收器','此卡發動時，將手牌的1張怪獸卡除外。只要此卡在場上存在，和被此效果除外的怪獸屬性相同的對手怪獸不能攻擊宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94253655,'海造賊-豪速的烈火號',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的其他的惡魔族怪獸的攻擊力上升500。\u000a②：從手牌捨棄1張「海造賊」卡片，以對手場上1張魔法、陷阱卡為對象可以發動。那張卡除外。那之後，可以從牌組將1隻「海造賊」怪獸加入手牌。此卡有「海造賊」卡片裝備的場合，此效果在對手回合也能發動。'),'效果2','是否從牌組把1隻「海造賊」怪獸加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94256039,'巴別塔',unistr('只要此卡在場上存在，每次我方或對手發動魔法卡，給此卡放置1個魔力計數器。\u000a此卡放置第4個魔力計數器時，此卡破壞，那時發動魔法卡的玩家受到3000傷害。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94259633,'納祭阿尼瑪',unistr('衍生物以外的等級1怪獸1隻\u000a這個卡名的①效果1回合只能使用1次。\u000a①：以此卡指向的1隻表側表示怪獸為對象可以發動。那隻表側表示怪獸當作裝備魔法卡給此卡裝備（只能裝備1隻）。\u000a②：此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力數值。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94283662,'傳送惡魔',unistr('①：1回合1次，我方主要階段可以發動。從手牌捨棄1隻惡魔族怪獸，此卡的攻擊力直到回合結束時上升500。\u000a②：我方場上的此卡被破壞送去墓地時，以被除外的1隻我方的闇屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'攻擊力上升','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94292987,'魔轟神 加繆基',unistr('「魔轟神」協調+協調以外的怪獸1隻以上\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從手牌、牌組將1隻「魔轟神」怪獸特殊召喚。\u000a②：只要此卡在怪獸區域存在，對手不能將我方場上的其他「魔轟神」同步怪獸作為效果的對象。\u000a③：此卡被送去墓地的場合可以發動。我方依照我方場上的「魔轟神」同步怪獸數量抽牌。那之後，選1張我方的手牌捨棄。'),'效果1','','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94303232,'妨礙之星',unistr('我方場上表側攻擊表示存在的怪獸的表示形式變成表側守備表示的回合，只能給那隻怪獸裝備。\u000a此卡發動時，也選擇對手場上的1隻怪獸。那隻怪獸不能攻擊，也不能變更表示形式。\u000a裝備怪獸被破壞讓此卡被送去墓地時，選擇的對手怪獸除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94317736,'極東秘泉鄉',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：雙方玩家1回合1次，自己的主要階段2可以發動。自己回復500生命值，這個回合中，適用以下效果。\u000a●自己的怪獸的召喚、特殊召喚不會被無效化。\u000a●自己發動包含將怪獸特殊召喚效果的怪獸的效果、魔法、陷阱卡的場合，那個發動不會被無效化。\u000a●自己的場上覆蓋的魔法、陷阱卡不會成為對手的效果的對象，不會被對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94326720,'破滅的預幻視',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方的墓地、除外狀態的1隻「無垢者 梅迪烏斯」為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方主要階段將墓地的此卡除外，以我方場上1隻表側表示怪獸為對象，宣言1～10的任意等級可以發動。那隻怪獸的等級直到回合結束時變成宣言的等級。'),'效果1','效果2','請選擇要改變的等級','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94331452,'音響戰士 爵士鼓',unistr('1回合1次，宣言1個屬性，選擇場上表側表示存在的1隻「音響戰士」怪獸可以發動。選擇的怪獸變成宣言的屬性。\u000a此外，宣言1個屬性，藉由將我方墓地的此卡除外，選擇我方場上表側表示存在的1隻「音響戰士」怪獸變成宣言的屬性。'),'改變屬性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94344242,'數位光蟲-焊料蜘蛛網',unistr('將此卡作為超量召喚的素材的場合，除了昆蟲族怪獸的超量召喚以外不能使用。\u000a①：1回合1次，以我方場上1隻表側攻擊表示怪獸為對象可以發動。那隻怪獸變成守備表示，從手牌將1隻昆蟲族等級3怪獸守備表示特殊召喚。\u000a②：用場上的此卡為素材超量召喚的怪獸得到以下效果。\u000a●這次超量召喚成功的場合發動。對手場上的全部表側表示怪獸守備力變成0，變成守備表示。'),'效果1','●守備力變成0（數位光蟲-焊料蜘蛛網）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94350039,'T.G. 齒輪殭屍',unistr('這個卡名的效果1回合只能使用1次。\u000a①：以我方場上1隻「T.G.」怪獸為對象可以發動。此卡從手牌特殊召喚。那之後，對象怪獸的攻擊力下降1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94365540,'廷達三角 底邊守衛者',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：我方場上有裡側守備表示怪獸存在的場合，此卡可以從手牌守備表示特殊召喚。\u000a②：此卡已在怪獸區域存在的狀態，對手的連結怪獸指向的區域有怪獸召喚、特殊召喚的場合，將此卡解放可以發動。從手牌、牌組將1隻「廷達三角」怪獸表側攻擊表示或裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94374859,'強迫推銷殭屍','我方場上的怪獸給予對手戰鬥傷害時，選擇對手墓地的1張卡回到持有者的牌組最下方。','回到牌組','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94377247,'假面魔獸的儀式',unistr('「假面魔獸 鬼面修道士」的降臨所必需。\u000a①：從我方的手牌、場上解放怪獸直到等級合計為8以上為止，從手牌儀式召喚「假面魔獸 鬼面修道士」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94380860,'No.103 神葬零孃 諸神零',unistr('等級4怪獸×2\u000a①：我方、對手回合1次，去除此卡的1個超量素材，以對手場上1隻攻擊力和原攻擊力不同的攻擊表示怪獸為對象可以發動。那隻怪獸破壞，我方抽1張卡。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94381039,'光道天使 柯魯貝姆','解放「光道」怪獸上級召喚成功時，從我方牌組上方將4張卡送去墓地可以發動。選擇對手場上最多2張卡破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94384774,'海老須神鮮祭',unistr('①：效果怪獸特殊召喚的場合，以其中1隻為對象可以發動（同一連鎖上最多1次）。在那隻怪獸的控制者所見的對手場上將1隻「神鮮衍生物」（水族、水、等級3、攻/守0）守備表示特殊召喚。\u000a②：我方、對手的戰鬥階段開始時1次，可以發動。此卡和場上的衍生物全部破壞，在我方場上將1隻「海老須衍生物」（天使族、水、等級7、攻/守？）特殊召喚。這個衍生物的攻擊力、守備力上升此效果破壞的衍生物的數量×700。'),'N/A','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94384775,'神鮮衍生物','由「海老須神鮮祭」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94384776,'海老須衍生物','由「海老須神鮮祭」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94388754,'花札衛－萩間豬－',unistr('此卡不能通常召喚。將「花札衛－萩間豬－」以外的我方場上1隻「花札衛」怪獸解放可以特殊召喚。\u000a①：此卡特殊召喚成功的場合發動。我方從牌組抽1張卡，給雙方確認。那是「花札衛」怪獸的場合，可以選對手場上的1隻怪獸破壞。不是的場合，那張卡送去墓地。'),'抽牌','是否選對手場上的1隻怪獸破壞？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94392192,'剎帝利怒威 食人魔',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：我方主要階段可以發動。從牌組將1張「剎帝利怒威」陷阱卡加入手牌。\u000a③：此卡的攻擊宣言時，或對手發動怪獸的效果的場合可以發動。從對手牌組上方翻開最多5張卡，從其中選1張裡側表示除外。剩下的卡以原本的順序回到牌組上方。'),'特殊召喚（效果1）','效果2','效果3','請選擇要翻開的卡片數量','','','','','','','','','','','','');
INSERT INTO texts VALUES(94395649,'超重禽屬 雞蛇礦',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌、墓地存在的場合，將我方場上1隻獸族、獸戰士族、鳥獸族怪獸解放可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：從牌組將1隻等級4以下的獸族、獸戰士族、鳥獸族怪獸除外可以發動。直到結束階段，此卡和除外的怪獸當作同名卡，變成相同種族、屬性、等級。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94410955,'百臂無形神 攝挪',unistr('「百臂無形」怪獸×3\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：我方、對手的主要階段可以發動。隨機確認對手的額外牌組2張裡側的卡。可以從其中選1隻在我方場上特殊召喚。\u000a②：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a③：融合召喚的此卡被對手的效果破壞的場合可以發動。挑選對手場上任意數量的怪獸，得到其控制權。'),'效果1','效果3','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94412545,'變色龍','變換身體顏色可以隱藏在任何地方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94415058,'星讀的魔術師',unistr('【靈擺效果】\u000a①：我方的靈擺怪獸進行戰鬥的場合，對手直到傷害步驟結束時不能發動魔法卡。\u000a②：另一邊的我方的靈擺區域沒有「魔術師」卡片或是「異色眼」卡片存在的場合，此卡的靈擺刻度變成4。\u000a【怪獸效果】\u000a①：1回合1次，只有我方場上的靈擺怪獸1隻因對手的效果回到我方的手牌時可以發動。從手牌將1隻其同名怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94418111,'魔彈射手 野蠻比爾',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方、對手回合我方可以從手牌發動「魔彈」魔法、陷阱卡。\u000a②：和此卡相同縱列有魔法、陷阱卡發動的場合，以我方墓地3張「魔彈」卡片為對象可以發動。那3張卡加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'效果2','適用「魔彈射手 野蠻比爾」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94423983,'同契惡魔',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：這個回合，雙方不能將和自身場上的怪獸相同種類（儀式、融合、同步、超量、連結）的怪獸特殊召喚。我方場上的儀式、融合、同步、超量、連結怪獸其中任何種類都沒有2隻以上存在的場合，我方場上的全部儀式、融合、同步、超量、連結怪獸的攻擊力上升500。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94425169,'元素之泉','場上的怪獸回到持有者的手牌時，我方回復500生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94431029,'精準奪取',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：雙方各自選自身的額外牌組1張裡側表示的卡。那些卡給雙方確認，如果是相同種類（融合、同步、超量、連結），對手選的卡送去墓地，我方選的卡特殊召喚。原本的種族、屬性相同的場合，隨後對手失去自身選的卡的攻擊力數值的生命值。如果是不同種類，我方選的卡送去墓地，對手將自身選的卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94432298,'殼醒的煉獄',unistr('①：1回合1次，我方準備階段可以發動。從牌組將最多2隻「獄火機」怪獸送去墓地。\u000a②：我方場上有「獄火機」怪獸以外的怪獸存在的場合，此卡送去墓地。'),'N/A','發動效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94445733,'破壞的神碑',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：可以從以下效果選擇1個發動。此卡的發動後，跳過下個我方戰鬥階段。\u000a●以對手場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。那之後，從對手牌組上方將4張卡除外。\u000a●從額外牌組將1隻「神碑」怪獸在額外怪獸區域特殊召喚。'),'●破壞魔法、陷阱卡','●從額外牌組特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94446564,'情侶裝','①：雙方確認雙方牌組最上方的卡，如果那些卡是相同種類（怪獸、魔法、陷阱），雙方將那些卡加入手牌。如果不是，雙方將那些卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94454495,'Kozmo-魔鞋騎手',unistr('①：此卡召喚、特殊召喚成功的場合，以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。\u000a②：此卡被戰鬥、效果破壞送去墓地的場合，將墓地的此卡除外可以發動。從牌組將1隻等級4以下的「Kozmo」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94463200,'血的刻印','選擇我方場上1隻「惡魔」怪獸可以發動。選擇的怪獸在準備階段支付生命值時，對手也要支付。此卡從場上離開時，選擇的怪獸破壞。選擇的怪獸從場上離開的場合，此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94467314,'惡鵺死之雨',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有攻擊力2000以上的水族怪獸存在的場合可以發動。除了水族怪獸以外，場上的怪獸全部送去墓地。\u000a②：覆蓋的此卡被效果破壞的場合可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94484482,'擺脫召喚','對手將怪獸召喚、反轉召喚、特殊召喚成功時可以發動。從手牌將1隻等級4以下的怪獸表側守備表示特殊召喚。此效果特殊召喚的怪獸在結束階段回到手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94503794,'漆梏的食獸 刻耳西卜斯',unistr('等級7怪獸×2隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡的攻擊力上升此卡的超量素材數量×700。\u000a②：通常、速攻魔法卡發動時可以發動（同一連鎖上最多1次）。場上的那張卡作為表側表示的此卡的超量素材，此卡不受那個發動的效果影響。\u000a③：我方、對手的結束階段可以發動。此卡作為超量素材持有的1張魔法卡在我方場上覆蓋。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94515289,'冰結的費茲杰拉爾德',unistr('闇屬性協調+協調以外的獸族怪獸1隻\u000a此卡攻擊的場合，對手直到傷害步驟結束時不能發動魔法、陷阱卡。\u000a此卡被戰鬥破壞送去墓地時，我方場上沒有怪獸存在的場合，可以藉由捨棄1張手牌，此卡從墓地守備表示特殊召喚。'),'從墓地特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94535485,'牽手魔人',unistr('①：只要此卡在怪獸區域存在，對手不能選擇其他怪獸作為攻擊對象。\u000a②：此卡的守備力上升此卡以外的我方場上的表側守備表示怪獸的原守備力的合計數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94538053,'極限戰士',unistr('此卡向對手怪獸攻擊的場合，傷害步驟期間此卡的攻擊力上升400。\u000a此卡戰鬥破壞對手怪獸的場合，直到下個我方準備階段時此卡的等級變成2，原本的攻擊力、守備力變成一半。'),'攻守減半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94553671,'魔女工坊的守護靈',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方的墓地、除外狀態的1隻魔法使族怪獸為對象可以發動。那隻怪獸回到牌組，從牌組將1張「魔女工坊」魔法卡加入手牌。\u000a②：將不是在這個回合送去墓地的此卡從墓地除外，以我方的除外狀態的任意數量的「魔女工坊」魔法卡為對象可以發動（同名卡最多1張）。那些卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94561645,'反擊之門','①：對手怪獸的直接攻擊宣言時可以發動。那次攻擊無效，我方從牌組抽1張卡。那張抽到的卡是怪獸的場合，可以將那隻怪獸表側攻擊表示通常召喚。','是否表側攻擊表示通常召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94566432,'皇帝龍','「護城翼龍」+「妖精龍」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94568601,'暴君龍',unistr('我方或對手將此卡用卡的效果從墓地特殊召喚之際，那個玩家必須將自身場上1隻龍族怪獸解放。\u000a①：只要對手場上有怪獸存在，此卡在1次戰鬥階段中可以攻擊2次。\u000a②：只要此卡在怪獸區域存在，以此卡為對象的陷阱卡的效果無效化並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94573223,'甲蟲裝機 巨大螳螂',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：以我方場上1隻「甲蟲裝機」怪獸為對象可以發動。此卡從手牌當作裝備卡給那隻我方的「甲蟲裝機」怪獸裝備。\u000a②：將此卡當作裝備卡來裝備的怪獸的原攻擊力變成2400。\u000a③：給怪獸裝備的此卡被送去墓地的場合，以「甲蟲裝機 巨大螳螂」以外的我方墓地1隻「甲蟲裝機」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94585852,'萬魔殿 －魔鬼的巢窟－',unistr('「惡魔」怪獸在準備階段時可以不用支付生命值。\u000a「惡魔」怪獸被戰鬥以外破壞送去墓地時，那個持有者可以從牌組將1隻等級低於那隻怪獸的「惡魔」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94599451,'魔導研究所',unistr('①：每次我方場上的表側表示的「魔導獸」靈擺怪獸卡被戰鬥、效果破壞，給此卡放置2個魔力計數器。\u000a②：1回合1次，去除我方場上任意數量的魔力計數器可以發動。從牌組的怪獸以及我方的額外牌組的表側表示的靈擺怪獸之中，選1隻等級和去除數量相同的可以放置魔力計數器的怪獸加入手牌。\u000a③：場上的此卡被效果破壞的場合，可以去除此卡的1個魔力計數器作為代替。'),'效果2','請選擇要去除的魔力計數器數量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94620082,'轉生炎獸 狐狸',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡召喚成功時可以發動。從我方牌組上方翻開3張卡。可以從其中選1張「轉生炎獸」卡片加入手牌。剩下的卡回到牌組。\u000a②：此卡在墓地存在，場上有表側表示的魔法、陷阱卡存在的場合，從手牌捨棄1張「轉生炎獸」卡片可以發動。此卡特殊召喚。那之後，可以選場上1張表側表示的魔法、陷阱卡破壞。'),'效果1','是否選1張「轉生炎獸」卡片加入手牌？','效果2','是否選1張魔法、陷阱卡破壞？','','','','','','','','','','','','');
INSERT INTO texts VALUES(94622638,'盟軍次世代充電者','①：只要此卡在怪獸區域存在，持有和此卡相同屬性的我方場上的其他怪獸的攻擊力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94626050,'魚雨','場上的表側表示的魚族、海龍族、水族怪獸被除外時可以發動。從手牌將1隻等級3以下的魚族、海龍族、水族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94626871,'花樣明星 箭根薯甜心',unistr('「花樣明星」怪獸2隻\u000a①：只要此卡在怪獸區域存在，每次此卡指向的怪獸被戰鬥、效果破壞送去墓地，給予對手200傷害。\u000a②：每次「花樣明星」怪獸的效果讓對手受到傷害發動。對手場上的全部表側表示怪獸的攻擊力直到回合結束時下降此卡指向的怪獸數量×200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94634433,'緊急同調','①：我方、對手的戰鬥階段可以發動。同步召喚1隻同步怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94641726,'嵐忌龍 迪斯托比姆',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：對手不能將場上的此卡作為效果的對象。\u000a②：從我方墓地將任意數量的不能通常召喚的闇屬性怪獸除外可以發動（對手場上的卡片數量比我方場上的卡多的場合，此效果在對手回合也能發動）。依照除外的數量將對手場上的卡除外。\u000a③：此卡被送去墓地的場合可以發動。我方的除外狀態的1隻龍族怪獸特殊召喚。'),'','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94655777,'闇征龍-星雲',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從手牌將1隻龍族或闇屬性怪獸和此卡捨棄，以「闇征龍-星雲」以外的我方的除外狀態的屬性不同的2隻「征龍」怪獸為對象可以發動。那些怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合不能攻擊。\u000a②：從我方墓地將1隻龍族或闇屬性怪獸和此卡除外，以我方墓地1隻「凶征龍-日蝕」為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94656263,'影子蜥蜴',unistr('此卡不能通常召喚，用此卡的效果可以特殊召喚。此卡不能作為同步素材。\u000a①：我方將等級4怪獸召喚成功時可以發動。此卡從手牌特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94661166,'迫近的機械',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：從我方的牌組、墓地將1隻記載「金屬化強化反射裝甲」的卡名的怪獸或1張「金屬化」陷阱卡加入手牌。\u000a②：我方場上有「金屬化」陷阱卡存在的場合，將墓地的此卡除外，以對手場上1隻守備表示怪獸為對象可以發動。那隻怪獸變成表側攻擊表示。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94662235,'命運彎曲','我方場上表側表示存在的怪獸只有「命運女郎」怪獸時可以發動。魔法、陷阱卡的發動、怪獸的召喚其中1個無效，並將那些卡除外。這個回合的結束階段時，此效果除外的卡回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94664694,'瘋狂惡魔',unistr('①：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：攻擊表示的此卡被選擇作為攻擊對象的場合發動。此卡變成守備表示。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94666032,'復仇屍者誕生',unistr('「仇屍」儀式怪獸的降臨所必需。\u000a①：解放我方的手牌、場上的怪獸，或是將我方墓地的不死族怪獸除外來代替解放，直到等級合計為儀式召喚的怪獸的等級以上為止，從我方的手牌、墓地儀式召喚1隻「仇屍」儀式怪獸。\u000a②：我方場上的「復仇屍者 屠戮者」被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94667532,'機械犬瑪隆',unistr('場上的此卡被戰鬥破壞送去墓地時，給予雙方1000傷害。\u000a場上的此卡因戰鬥以外被破壞送去墓地時，給予對手1000傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94670654,'獸之忍者-貘',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用抽牌以外的方法加入手牌的場合可以發動。此卡特殊召喚。\u000a②：此卡特殊召喚、反轉的場合，從我方墓地以及我方的魔法與陷阱區域的表側表示的卡之中，以「獸之忍者-貘」以外的1張「忍者」卡片或「忍法」卡片為對象可以發動。那張卡回到持有者的手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94675535,'拉瓦斯','行動速度飛快的鳥怪，用細長的手腕將敵人絞殺。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94677445,'星杯的神子 伊布',unistr('協調+協調以外的怪獸1隻以上\u000a此卡同步召喚的場合，可以將我方場上1隻「星杯」通常怪獸當作協調。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從牌組將1張「星遺物」卡片加入手牌。\u000a②：同步召喚的此卡被送去墓地的場合可以發動。從我方的牌組、墓地將「星杯的神子 伊布」以外的1隻「星杯」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94677446,'星杯的神子 伊布',unistr('協調+協調以外的怪獸1隻以上\u000a此卡同步召喚的場合，可以將我方場上1隻「星杯」通常怪獸當作協調。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡同步召喚的場合可以發動。從牌組將1張「星遺物」卡片加入手牌。\u000a②：同步召喚的此卡被送去墓地的場合可以發動。從我方的牌組、墓地將「星杯的神子 伊布」以外的1隻「星杯」怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94681654,'羽風攻擊','讓我方場上1隻表側表示的「BF」怪獸回到牌組可以發動。從我方牌組將1隻「BF」怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94689206,'積木龍',unistr('此卡不能通常召喚。只能將我方的手牌、墓地3隻地屬性怪獸除外，從手牌、墓地特殊召喚。這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方場上的岩石族怪獸不會被戰鬥以外破壞。\u000a②：此卡從場上送去墓地的場合可以發動。直到等級合計為8，從牌組將最多3隻岩石族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94689635,'紫光的宣告者','①：對手發動陷阱卡時，從手牌將此卡和1隻天使族怪獸送去墓地可以發動。那個發動無效並破壞。','發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94693857,'生化文具人001',unistr('①：此卡的攻擊力、守備力上升我方場上的機械族怪獸數量×500。\u000a②：此卡在墓地存在，場上有2隻以上機械族怪獸同時特殊召喚的場合可以發動。此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94703021,'叢集擁塞器',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上沒有連結怪獸存在，此卡召喚、特殊召喚成功的場合可以發動。在我方場上將1隻「擁塞器衍生物」（電子界族、闇、等級1、攻/守0）特殊召喚。\u000a②：我方的連結怪獸被攻擊的戰鬥步驟1次，將那隻連結怪獸和墓地的此卡除外可以發動。最多到對手場上的連結怪獸數量，將「擁塞器衍生物」在我方場上特殊召喚。'),'是否繼續特殊召喚？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94703022,'擁塞器衍生物','由「叢集擁塞器」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94716515,'尖刺神的殺蟲劑','場上的昆蟲族怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94722358,'碼麗絲＜序＞MTP-07',unistr('這個卡名的卡在1回合只能發動1張。此卡也能將我方場上1隻表側表示的「碼麗絲」怪獸除外，在覆蓋的回合發動。\u000a①：從牌組將1隻「碼麗絲」怪獸加入手牌。我方場上有「碼麗絲」連結怪獸存在的場合，隨後可以將場上1張卡除外。'),'','','適用此卡的效果來發動','是否將1張卡除外？','','','','','','','','','','','','');
INSERT INTO texts VALUES(94730900,'焰聖騎士-莫吉斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡被送去墓地的場合，從我方墓地的卡以及被除外的我方的卡之中讓此卡以外的戰士族、炎屬性怪獸或「聖劍」卡片合計3張回到牌組可以發動。我方從牌組抽1張卡。\u000a②：此卡在墓地存在的場合，以我方場上1隻戰士族怪獸為對象可以發動。此卡當作裝備卡給那隻我方怪獸裝備。\u000a③：此卡的裝備怪獸不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94739788,'洗腦解除','只要此卡在場上存在，雙方場上的全部怪獸的控制權回歸原持有者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94749594,'古代龜的詛咒',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、墓地將1隻不死族怪獸除外可以發動。從牌組將1隻不死族怪獸送去墓地。\u000a②：我方的不死族怪獸被戰鬥破壞時，將墓地的此卡除外可以發動。從牌組將1隻守備力2000以下的不死族怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94766498,'先史遺產 阿茲特克假面巨人','我方發動了「先史遺產」魔法卡的我方回合，此卡可以從手牌特殊召喚。「先史遺產 阿茲特克假面巨人」在我方場上只能有1隻表側表示存在。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94770493,'加倍機會','①：怪獸的攻擊無效時，以那1隻怪獸為對象可以發動。這次戰鬥階段中，那隻怪獸可以再度攻擊1次。此效果讓那隻怪獸攻擊的傷害步驟期間，那隻怪獸的攻擊力變成2倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94772232,'死亡訊息「T」','此卡只能用「威加盤」的效果出到場上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94773007,'地雷蜘蛛','此卡的攻擊宣言時，投擲1次硬幣並猜正反面。猜錯的場合，我方失去一半生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94784213,'威風妖怪 狐',unistr('【靈擺效果】\u000a【怪獸效果】\u000a「威風妖怪 狐」的①怪獸效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功時可以發動。從牌組將1張「威風妖怪」陷阱卡加入手牌。\u000a②：此卡只要在怪獸區域存在，不會成為對手的效果的對象，不會被對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94793422,'心眼之矛','裝備怪獸給予對手的戰鬥傷害數值變成1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94798725,'超弩級軍貫-海膽型二番艦',unistr('等級5怪獸×2\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡超量召喚成功的場合可以發動。依照作為超量召喚的素材的怪獸適用以下效果。\u000a●「舍利軍貫」：我方從牌組抽1張卡。\u000a●「海膽軍貫」：此卡可以直接攻擊。\u000a②：我方主要階段以及對手戰鬥階段1次，最多到從額外牌組特殊召喚的我方的「軍貫」怪獸數量，以對手場上的表側表示的卡為對象可以發動。那些卡的效果無效。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94801854,'不知火的隱者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻不死族怪獸解放可以發動。從牌組將1隻守備力0的不死族協調特殊召喚。\u000a②：此卡被除外的場合，以「不知火的隱者」以外的被除外的1隻我方的「不知火」怪獸為對象可以發動。那隻怪獸特殊召喚。場上有「不知火流 轉生之陣」存在的場合，此效果的對象可以變成2隻。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94804055,'火焰之壁',unistr('此卡的控制者在每次我方準備階段支付500生命值，或不支付讓此卡破壞。\u000a對手的直接攻擊宣言時，可以藉由將我方墓地的1隻炎族怪獸除外，將那隻怪獸的攻擊無效。'),'攻擊無效','是否現在發動此卡的效果？','是否支付500點維持「火焰之壁」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94807487,'霍普劍斬',unistr('只能給「希望皇霍普」怪獸裝備。\u000a①：裝備怪獸不會被效果破壞。\u000a②：只要此卡在魔法與陷阱區域存在，每次怪獸的攻擊被無效，給此卡放置1個霍普劍計數器。裝備怪獸的攻擊力上升此卡的霍普劍計數器的數量×500。\u000a③：我方場上的裝備怪獸要去除超量素材來發動效果的場合，可以將此卡當作1個要去除的超量素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94820406,'黑暗結合',unistr('①：我方的手牌、場上的怪獸作為融合素材，將1隻惡魔族融合怪獸融合召喚。這個回合，對手不能將此效果特殊召喚的怪獸作為效果的對象。\u000a\u000a※黑暗融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94821366,'驚樂園的管理者 ＜小丑＞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：陷阱卡發動的場合可以發動。此卡從手牌特殊召喚。\u000a②：對手將怪獸召喚、特殊召喚成功的場合，以那1隻對手怪獸為對象可以發動。從牌組選1張「遊樂設施」陷阱卡給那隻對手怪獸裝備。\u000a③：1回合1次，從我方墓地將「遊樂設施」陷阱卡任意數量除外，以那個數量的對手場上的卡為對象可以發動。那些卡破壞。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94845226,'魔轟神獸 路比拉達','我方場上表側表示存在的此卡被選擇作為攻擊對象時，可以藉由從手牌捨棄1隻「魔轟神」怪獸，那次攻擊無效。','攻擊無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94845588,'聖徒薊花',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：向對手展示額外牌組的1隻「聖徒」融合怪獸，那個等級每有4，就從我方的手牌、場上將1張「罪寶」卡片送去墓地（裡側表示卡則翻開確認）。那之後，展示的怪獸當作融合召喚特殊召喚。\u000a②：此卡在墓地存在的場合，以我方的場上、墓地1隻「聖徒」怪獸為對象可以發動。那隻怪獸回到牌組，此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94853057,'閃光的追放者','只要此卡在場上表側表示存在，送去墓地的卡不去墓地而是除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94861297,'檢問','①：對手怪獸的攻擊宣言時可以發動。確認對手的全部手牌，其中有怪獸卡的場合，那次攻擊無效。那之後，我方從對手的手牌選1隻怪獸捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94878265,'摩迦','此卡被戰鬥破壞送去墓地時，可以選擇我方墓地的1隻等級4的獸族怪獸加入手牌。','從墓地加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94886282,'光之援軍','①：從我方牌組上方將3張卡送去墓地可以發動。從牌組將1隻等級4以下的「光道」怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94905343,'牛頭半人馬','「牛頭人」+「半人馬」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94919024,'月光紅狐',unistr('①：此卡被效果送去墓地的場合，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時變成0。\u000a②：以我方場上的「月光」怪獸為對象的魔法、陷阱、怪獸的效果發動時，將墓地的此卡除外可以發動。那個發動無效，雙方玩家回復1000生命值。'),'攻擊力變成0','發動無效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94933468,'空虛-背叛的嘲笑',unistr('對手場上的超量怪獸攻擊宣言時，選擇那1隻怪獸可以發動。選擇的怪獸不能攻擊，效果無效化。選擇的怪獸從場上離開時，此卡破壞。\u000a只要選擇的怪獸在場上存在，每次對手結束階段，從對手牌組上方將3張卡送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94937430,'臨時收入',unistr('①：只要此卡在魔法與陷阱區域存在，每次卡片加入我方的額外牌組，給此卡放置1個魔力計數器（最多3個）。\u000a②：將已放置3個魔力計數器的此卡送去墓地可以發動。我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94940436,'磁石召喚圓 LV2','從手牌將1隻等級2以下的機械族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94942656,'隱形水母怪碟狀幼體',unistr('水屬性等級4怪獸×2\u000a①：1回合1次，我方、對手的主要階段可以發動。選對手場上1隻水屬性怪獸破壞。\u000a②：「No.」超量怪獸的效果特殊召喚的此卡被破壞的場合可以發動。最多到此卡原先持有的超量素材數量，從我方墓地選此卡以外的「隱形水母怪」怪獸特殊召喚。那之後，可以給那些特殊召喚的怪獸各從我方墓地選最多1隻水屬性怪獸作為超量素材。'),'效果1','效果2','是否給此卡補充超量素材？','「No.」超量怪獸的效果特殊召喚','','','','','','','','','','','','');
INSERT INTO texts VALUES(94944637,'魔族召喚師',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●1回合1次，在我方主要階段時可以發動。從手牌或我方、對手的墓地選1隻惡魔族怪獸特殊召喚。此卡從場上離開時，此效果特殊召喚的惡魔族怪獸全部破壞。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94950218,'反轉破壞者',unistr('只能給「希望皇霍普」怪獸裝備。\u000a裝備怪獸的攻擊宣言時，選擇對手場上的1張魔法、陷阱卡破壞。應對此效果的發動，對手不能發動魔法、陷阱卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94973028,'幻獸機 傾轉翼馬',unistr('①：我方場上有其他的「幻獸機」怪獸存在，此卡特殊召喚成功的場合發動。在我方場上將2隻「幻獸機衍生物」（機械族、風、等級3、攻/守0）特殊召喚。\u000a②：此卡的等級上升我方場上的「幻獸機衍生物」的等級的合計數值。\u000a③：只要我方場上有衍生物存在，此卡不會被戰鬥、效果破壞。\u000a④：1回合1次，將我方場上2隻衍生物解放，以對手場上1張卡為對象可以發動。那張對手的卡破壞並除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94973029,'幻獸機衍生物','由「幻獸機」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94977269,'神影依 米德拉什',unistr('「影依」怪獸+闇屬性怪獸\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：場上的此卡不會被對手的效果破壞。\u000a②：只要此卡在怪獸區域存在，那個期間雙方1回合只能將怪獸特殊召喚1次。\u000a③：此卡被送去墓地的場合，以我方墓地1張「影依」魔法、陷阱卡為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94977270,'神影依 米德拉什',unistr('「影依」怪獸+闇屬性怪獸\u000a此卡只能用融合召喚從額外牌組特殊召喚。\u000a①：場上的此卡不會被對手的效果破壞。\u000a②：只要此卡在怪獸區域存在，那個期間雙方1回合只能將怪獸特殊召喚1次。\u000a③：此卡被送去墓地的場合，以我方墓地1張「影依」魔法、陷阱卡為對象可以發動。那張卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94979322,'黑炎之劍士',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：從額外牌組將1隻「炎之劍士」或記載那個卡名的怪獸送去墓地可以發動。此卡從手牌特殊召喚。這個回合，我方除了用戰士族怪獸以外不能攻擊宣言。\u000a②：此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：我方、對手回合，將此卡解放可以發動。從牌組將等級6以外的1隻記載「炎之劍士」的卡名的怪獸特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94982447,'真龍騎將 德萊亞斯3世',unistr('此卡表側表示上級召喚的場合，可以解放我方場上的永續魔法、永續陷阱卡來代替怪獸。\u000a①：上級召喚的表側表示的此卡從場上離開的場合可以發動。從牌組將1隻「真龍」怪獸守備表示特殊召喚。\u000a②：只要此卡在怪獸區域存在，此卡以外的場上的「真龍」怪獸不會成為對手的效果的對象，不會被對手的效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94997874,'聖占術姬 塔羅蕾',unistr('藉由「聖占術的儀式」降臨。這個卡名的①②效果1回合只有1次能使用其中1個，對手回合也能發動。\u000a①：以場上1隻裡側表示怪獸為對象可以發動。那隻怪獸變成表側攻擊表示。\u000a②：以場上1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。\u000a③：我方結束階段可以發動。從我方的手牌、墓地選1隻反轉怪獸裡側守備表示特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95004025,'真龍導士 威風少女',unistr('此卡表側表示上級召喚的場合，可以解放我方場上的永續魔法、永續陷阱卡來代替怪獸。\u000a①：此卡已被上級召喚的場合，1回合1次，對手發動魔法、陷阱、怪獸的效果時可以發動。從牌組將1隻「真龍」怪獸加入手牌。'),'N/A','效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95026693,'火焰之魂','對手從牌組抽1張卡。從我方的牌組選1隻炎族怪獸除外，給予對手除外的怪獸的攻擊力一半數值的傷害。此卡發動的整回合中，我方不能攻擊宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95027497,'忍者大師 半藏',unistr('①：此卡召喚成功時可以發動。從牌組將1張「忍法」卡片加入手牌。\u000a②：此卡反轉召喚、特殊召喚成功時可以發動。從牌組將「忍者大師 半藏」以外的1隻「忍者」怪獸加入手牌。'),'檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95034141,'黃金鄉的七摩天',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從我方的手牌、場上將融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。此時融合素材怪獸必須全部都是不死族怪獸。\u000a②：卡的效果讓不死族怪獸特殊召喚的場合，以魔法與陷阱區域覆蓋的1張卡為對象可以發動。覆蓋的那張卡在這個回合不能發動。'),'效果1','效果2','請選擇要禁止發動的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95040215,'BF-星影之靈劍',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合發動。給予對手800傷害。那之後，對手場上1隻表側表示怪獸的攻擊力、守備力下降800。\u000a②：只要此卡在怪獸區域存在，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻「BF」怪獸。'),'召喚（BF-星影之靈劍）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95051344,'成佛','已裝備裝備卡的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95072744,'燼影依 看守水晶',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡反轉的場合，以岩石族以外的我方墓地1隻「影依」怪獸為對象可以發動。那隻怪獸的反轉的場合發動的效果適用。\u000a②：此卡被效果送去墓地的場合可以發動（此效果發動的整回合中，我方除了「影依」怪獸以外不能從額外牌組特殊召喚）。我方的手牌、場上、墓地的怪獸作為融合素材除外，將1隻「影依」融合怪獸融合召喚。\u000a\u000a※影雄之燼 看守水晶'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95081386,'三振障壁',unistr('①：對手場上的卡只有3張的場合，可以從以下效果選擇1個發動。\u000a●這個回合，我方怪獸不會被戰鬥破壞。\u000a●這個回合，我方受到的戰鬥傷害變成0。\u000a●這個回合，每次我方怪獸給予對手戰鬥傷害，我方的生命值回復那個數值。'),'●我方怪獸不會被戰鬥破壞','●我方受到的戰鬥傷害變成0','●我方的生命值回復戰鬥傷害數值','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95083785,'過早的歸還','①：將1張手牌除外，以被除外的1隻我方怪獸為對象可以發動。那隻怪獸裡側守備表示特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95084054,'電力加農砲','場上有等級4以下的雷族怪獸召喚、特殊召喚時，給予對手600傷害。這個效果1回合只能使用1次。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95090813,'核成戰鬥兵',unistr('此卡的控制者在每次我方結束階段，從手牌將1張「核成的鋼核」送去墓地，或向對手展示手牌的1隻戰士族怪獸，或都不做讓此卡破壞。\u000a1回合1次，可以選擇我方墓地的1隻等級3以下的戰士族怪獸，當作裝備卡給此卡裝備。\u000a此卡的攻擊力上升此卡的效果裝備的怪獸的攻擊力一半數值。此卡被戰鬥破壞的場合，將裝備怪獸破壞作為代替。'),'「核成的鋼核」送去墓地','展示戰士族怪獸','破壞','給此卡裝備','','','','','','','','','','','','');
INSERT INTO texts VALUES(95091919,'原型念力砲手',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。我方的手牌、除外狀態的1隻等級4以下的超能族怪獸特殊召喚。\u000a②：此卡在墓地存在的場合，支付1000生命值，從我方墓地將1隻其他的超能族怪獸除外可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95095116,'熾天的騎士 蓋亞日珥',unistr('「烈日的騎士 蓋亞烈焰」+我方場上的表側表示怪獸\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：對手發動手牌、墓地的怪獸的效果時，從手牌捨棄1隻怪獸可以發動。那個效果無效並破壞。\u000a②：此卡的攻擊破壞對手怪獸時，以我方墓地1隻炎屬性怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95096437,'義賊的極義書','選擇我方場上1隻通常怪獸可以發動。這個回合，選擇的怪獸給予對手戰鬥傷害時，對手的手牌隨機選2張捨棄。','捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95113856,'幻子力空母 企業號巨艦',unistr('等級9怪獸×2\u000a①：1回合1次，可以去除此卡的1個超量素材，從以下效果選擇1個發動。\u000a●選對手場上1張卡除外。\u000a●對手的手牌隨機選1張除外。\u000a●選對手墓地1張卡除外。\u000a●對手牌組最上方的卡除外。'),'效果1','●場上的卡除外','●手牌除外','●墓地的卡除外','●牌組最上方的卡除外','','','','','','','','','','','');
INSERT INTO texts VALUES(95132338,'水之合唱','①：在場上有同名怪獸存在的場上的怪獸的攻擊力、守備力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95132593,'百臂無形手 蓋伽撕',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：抽牌階段以外有卡加入對手的手牌的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方主要階段可以發動。從對手牌組上方翻開3張卡。可以從其中選1隻怪獸在我方場上特殊召喚。其餘回到牌組。\u000a③：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。'),'效果1','效果3','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95134948,'No.99 希望皇霍普龍騎',unistr('等級12怪獸×3隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，去除此卡的2個超量素材可以發動（此效果發動的整回合中，我方除了超量怪獸以外不能從額外牌組特殊召喚，其他的我方怪獸不能直接攻擊）。將1隻「No.1」～「No.100」的任何「No.」怪獸當作超量召喚從額外牌組特殊召喚。\u000a②：對手怪獸的攻擊宣言時可以發動。那隻對手怪獸的攻擊力變成0。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95134949,'No.99 希望皇霍普龍騎',unistr('等級12怪獸×3隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手回合，去除此卡的2個超量素材可以發動（此效果發動的整回合中，我方除了超量怪獸以外不能從額外牌組特殊召喚，其他的我方怪獸不能直接攻擊）。將1隻「No.1」～「No.100」的任何「No.」怪獸當作超量召喚從額外牌組特殊召喚。\u000a②：對手怪獸的攻擊宣言時可以發動。那隻對手怪獸的攻擊力變成0。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95136979,'破械式鬼 奢羅',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，將此卡從手牌捨棄可以發動。從手牌將1隻惡魔族怪獸特殊召喚。那之後，我方場上1張卡破壞。\u000a②：此卡在墓地存在的狀態，場上的卡被戰鬥或「破械式鬼 奢羅」以外的卡的效果破壞的場合可以發動。此卡加入手牌或特殊召喚。此效果特殊召喚的此卡從場上離開的場合回到牌組最下方。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95144193,'鍬形海克力士','「鍬甲阿爾法」+「海克力士甲蟲」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95166228,'稀有鎧甲',unistr('只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●此卡可以向對手場上的全部怪獸各攻擊1次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95169481,'恐牙狼 鑽石狼',unistr('等級4怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以我方場上1隻獸族、獸戰士族、鳥獸族怪獸和場上1張卡為對象可以發動。那些卡破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95174353,'阿米巴','場上表側表示存在的此卡的控制權轉移給對手時，對手受到2000傷害。這個效果於此卡在場上表側表示存在期間只能使用1次。','給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95178994,'巨大病毒','①：此卡被戰鬥破壞送去墓地的場合發動。給予對手500傷害。那之後，可以從牌組將任意數量的「巨大病毒」攻擊表示特殊召喚。','傷害','是否從牌組特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95192919,'烈風的霸者 西摩格',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：上級召喚的此卡不會成為對手的魔法、陷阱卡的效果的對象。\u000a②：魔法、陷阱卡的效果發動時，解放我方場上1隻鳥獸族、風屬性怪獸，以對手場上1張卡為對象可以發動。那張卡回到持有者的牌組。\u000a③：此卡在墓地存在，我方的鳥獸族怪獸被戰鬥破壞時可以發動。此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95194279,'次元歪斜','我方墓地沒有卡存在的場合可以發動。選擇被除外的1隻我方怪獸在我方場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95204084,'核成龍捲風','從手牌將1張「核成的鋼核」放回牌組最上方可以發動。對手場上的特殊召喚的怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95207988,'地縛共振',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從額外牌組特殊召喚的場上的怪獸被效果破壞的場合，以其中的1隻為對象可以發動。雙方受到那隻怪獸的攻擊力一半數值的傷害。\u000a②：從額外牌組特殊召喚的我方的闇屬性同步怪獸被選擇作為攻擊對象時，以場上1張卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95209656,'儀龍輝巧-降星：象限儀',unistr('藉由「龍輝巧降星」降臨。這個卡名的②③效果1回合各能使用1次。\u000a①：場上的此卡不會成為對手的魔法、陷阱卡的效果的對象。\u000a②：此卡的儀式召喚使用的怪獸的等級合計為2以下的場合可以發動。對手場上的魔法、陷阱卡全部破壞。\u000a③：儀式召喚的此卡被破壞的場合可以發動。從我方墓地選攻擊力合計為4000的「儀龍輝巧-降星：象限儀」以外的任意數量的「龍輝巧」怪獸特殊召喚。'),'效果2','效果3','效果2適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95214051,'翡翠的蟲笛','對手從牌組選1隻昆蟲族怪獸，在牌組洗牌後將那張卡放置在牌組最上方。','選1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95218695,'地中族邪界獸 阿爾褐簾骸',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上的表側表示怪獸變成裡側表示時，我方場上沒有表側表示怪獸存在的場合可以發動。此卡從手牌守備表示特殊召喚。\u000a②：我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a③：此卡反轉的場合可以發動。這個回合，我方場上的「地中族」卡片不會被對手的效果破壞。'),'效果3','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95220856,'怨靈的濕地帶','場上的怪獸在召喚、反轉召喚、特殊召喚的回合不能攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95231062,'失落之藍破壞者','場上有此卡以外的魚族、海龍族或水族怪獸表側表示存在的場合，將此卡解放可以發動。選擇1張場上的魔法、陷阱卡破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95238394,'雷龍結合',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的場上、墓地、除外狀態的怪獸作為融合素材回到牌組，將1隻雷族融合怪獸融合召喚。\u000a②：將不是在這個回合送去墓地的此卡從墓地除外可以發動。從牌組將1隻雷族怪獸加入手牌。\u000a\u000a※雷龍融合'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95239444,'森羅的鎮神 山精',unistr('等級7怪獸×2\u000a1回合1次，將我方的手牌、場上的1隻植物族怪獸送去墓地可以發動。確認我方牌組上方和那隻怪獸的等級相同數量的卡，以喜歡的順序回到牌組上方。\u000a此外，1回合1次，去除此卡的1個超量素材可以發動。從我方牌組上方翻開最多3張卡。如果其中包含植物族怪獸，那些怪獸全部送去墓地，從場上選此卡以外最多到那個數量的卡回到手牌。剩下的卡以喜歡的順序回到牌組最下方。'),'牌組上方排序','翻開牌組上方最多3張卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95243515,'電腦堺虎-虎虎',unistr('等級9怪獸×2隻以上\u000a①：此卡依照我方場上的「電腦堺門」卡片數量得到以下效果。\u000a●2張以上：此卡可以直接攻擊。\u000a●4張：此卡不受「電腦堺」卡片以外的卡發動的效果影響。\u000a②：1回合1次，去除此卡的1個超量素材，以我方場上1隻效果怪獸，以及與那隻怪獸種族和屬性不同的場上1隻效果怪獸為對象可以發動。那些怪獸的效果直到回合結束時無效。此效果在對手回合也能發動。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95245544,'魔女工坊 繪畫女巫皮特萊',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方、對手的主要階段，將此卡解放，從手牌捨棄1張魔法卡可以發動。從牌組將「魔女工坊 繪畫女巫皮特萊」以外的1隻「魔女工坊」怪獸特殊召喚。\u000a②：將墓地的此卡除外可以發動。我方抽1張卡。那之後，手牌有「魔女工坊」卡片存在的場合，挑選其中1張送去墓地。不存在的場合，我方的手牌全部除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95245571,'恐懼爪牙的雙牙',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1隻「恐懼爪牙」怪獸解放，以對手場上2張卡為對象可以發動。那些卡破壞。我方場上有「維薩斯-星霜」存在的場合，此效果破壞的卡不去墓地而是除外。\u000a②：場上有連結3以上的怪獸存在的場合，將墓地的此卡除外可以發動。這個回合，場上的連結怪獸不能發動效果。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95254840,'臨時取消','①：對手怪獸的攻擊宣言時可以發動。我方場上的怪獸全部變成守備表示。此卡的發動後，直到回合結束時被戰鬥、效果破壞的我方場上的表側表示的「娛樂夥伴」怪獸不去墓地而是回到持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95265975,'大食的食屍鬼','無論怎麼吃也不會飽的怪獸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95281259,'戰士生還','①：以我方墓地1隻戰士族怪獸為對象可以發動。那隻戰士族怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95283172,'黃金榮耀-陷入瘋狂',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：向對手展示手牌的1隻「黃金榮耀」怪獸可以發動。從牌組將1隻和展示的怪獸卡名不同的「黃金榮耀」怪獸加入手牌。那之後，可以適用以下效果。\u000a●從手牌將1隻「黃金榮耀」怪獸特殊召喚，我方失去那隻怪獸的原攻擊力數值的生命值。'),'效果1','是否從手牌將怪獸特殊召喚？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95286165,'融合解除','①：以場上1隻融合怪獸為對象可以發動。那隻融合怪獸回到持有者的額外牌組。那之後，如果回到額外牌組的那隻怪獸的融合召喚使用過的整組融合素材怪獸都在我方墓地，可以將那整組在我方場上特殊召喚。','是否特殊召喚整組融合素材？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95288024,'天空龍','有著4根羽毛和鳥的外形的龍，用刀刃羽毛攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95291684,'異次元的獨角戰士',unistr('此卡不能通常召喚，將此卡特殊召喚的整回合中，我方不能通常召喚。對手場上有怪獸存在，我方場上有協調表側表示存在的場合可以特殊召喚。\u000a這個方法特殊召喚成功時，可以選擇被除外的1隻我方的協調以外的等級3以下的怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95308449,'終焉的倒數計時','①：支付2000生命值可以發動。以發動的回合為第1回合計算的第20回合的回合結束時，我方獲得決鬥勝利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95326659,'寶玉的引導','①：從牌組將1隻「寶玉獸」怪獸特殊召喚。此效果在我方的魔法與陷阱區域有2張以上「寶玉獸」卡片存在的場合可以發動和處理。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95352218,'天下統一','雙方準備階段時，回合玩家從自己場上的怪獸的等級之中選1個，自己場上表側表示存在的等級和那個等級不同的怪獸全部送去墓地。','送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95360850,'護盾戰士','傷害計算時，將我方墓地的此卡除外可以發動。我方場上的怪獸不會被那次戰鬥破壞。','不會被戰鬥破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95362816,'E.HERO 炙炎女郎','我方回合的結束階段時，給予對手相當於我方場上表側表示存在的「E.HERO」怪獸數量×200傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95365081,'百臂無形手 伊卜揶爾',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：向對手展示手牌的此卡可以發動。此卡回到牌組。那之後，從牌組將「百臂無形手 伊卜揶爾」以外的1隻「百臂無形」怪獸守備表示特殊召喚。\u000a②：此卡和怪獸進行戰鬥的場合，那2隻不會被那次戰鬥破壞。\u000a③：此卡被送去墓地的場合，以「百臂無形手 伊卜揶爾」以外的我方墓地1隻「百臂無形」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95372220,'槍口焰龍',unistr('龍族怪獸2隻以上\u000a我方不能將怪獸出到此卡指向的區域。\u000a①：1回合1次，此卡指向的區域有怪獸召喚、特殊召喚的場合可以發動。選此卡指向的1隻怪獸破壞，給予對手500傷害。\u000a②：以此卡為對象的魔法、陷阱、怪獸的效果發動時，將我方場上1隻怪獸解放可以發動。那個發動無效。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95376428,'召喚限制-額外網',unistr('①：我方或對手從額外牌組將怪獸特殊召喚的場合發動此效果。將那些怪獸特殊召喚的玩家所見的對手可以適用以下效果。\u000a●從牌組抽1張卡。'),'是否適用「召喚限制-額外網」的效果抽1張卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95382988,'再世十誡',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：與我方場上的「再世」怪獸相同縱列的對手場上的全部卡適用以下效果。\u000a●表側表示卡：效果無效化。\u000a●裡側表示怪獸：不能變更表示形式。\u000a●裡側表示的魔法、陷阱卡：直到下個回合結束時不能發動。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95395761,'甲蟲裝機 螞蟻',unistr('1回合1次，可以從我方的手牌、墓地將1隻「甲蟲裝機」怪獸當作裝備卡給此卡裝備。\u000a此卡已當作裝備卡裝備的場合，裝備怪獸的等級上升3，攻擊力、守備力上升此卡的對應數值。裝備怪獸被破壞的場合，可以將此卡破壞作為代替。'),'裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95401059,'絆影依-神數原核',unistr('【靈擺效果】\u000a①：我方除了「影依」怪獸以及「神數」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：此卡靈擺召喚成功的場合，或此卡被送去墓地的場合，以「絆影依-神數原核」以外的我方的靈擺區域1張「神數」卡片為對象可以發動。那張卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95403418,'星塵妖',unistr('此卡不能通常召喚。只能將我方場上任意數量表側表示的「塵妖」怪獸送去墓地來特殊召喚。\u000a此卡的攻擊力、守備力變成送去墓地的怪獸數量×1000。\u000a只要此卡在場上表側表示存在，對手不能發動場上覆蓋的魔法、陷阱卡，不能將怪獸反轉召喚、特殊召喚。\u000a我方場上的怪獸數量比對手場上的怪獸多的場合，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95440946,'黃金卿 埃爾德里奇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將此卡和1張魔法、陷阱卡送去墓地，以場上1張卡為對象可以發動。那張卡送去墓地。\u000a②：此卡在墓地存在的場合，將我方場上1張魔法、陷阱卡送去墓地可以發動。此卡加入手牌。那之後，可以從手牌將1隻不死族怪獸特殊召喚。此效果特殊召喚的怪獸直到對手回合結束時攻擊力、守備力上升1000，不會被效果破壞。'),'效果1','效果2','是否從手牌把1隻不死族怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95440947,'黃金卿 埃爾德里奇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將此卡和1張魔法、陷阱卡送去墓地，以場上1張卡為對象可以發動。那張卡送去墓地。\u000a②：此卡在墓地存在的場合，將我方場上1張魔法、陷阱卡送去墓地可以發動。此卡加入手牌。那之後，可以從手牌將1隻不死族怪獸特殊召喚。此效果特殊召喚的怪獸直到對手回合結束時攻擊力、守備力上升1000，不會被效果破壞。'),'效果1','效果2','是否從手牌把1隻不死族怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95440948,'黃金卿 埃爾德里奇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將此卡和1張魔法、陷阱卡送去墓地，以場上1張卡為對象可以發動。那張卡送去墓地。\u000a②：此卡在墓地存在的場合，將我方場上1張魔法、陷阱卡送去墓地可以發動。此卡加入手牌。那之後，可以從手牌將1隻不死族怪獸特殊召喚。此效果特殊召喚的怪獸直到對手回合結束時攻擊力、守備力上升1000，不會被效果破壞。'),'效果1','效果2','是否從手牌把1隻不死族怪獸特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95442074,'No.31 亞伯魔鬼',unistr('等級1怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材可以發動。對手場上的全部怪獸變成表側攻擊表示，在這個回合可以攻擊的場合必須向此卡攻擊。此效果在對手回合也能發動。\u000a②：只要我方場上有「No.13 該隱魔鬼」存在，此卡得到以下效果。\u000a●持有超量素材的此卡不會被戰鬥、效果破壞。\u000a●向此卡攻擊產生給我方的戰鬥傷害由對手代為承受。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95443805,'霞之谷的祈禱師','1回合1次，讓此卡以外的我方場上1隻怪獸回到手牌可以發動。此卡的攻擊力直到回合結束時上升500。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95448372,'剛鬼鬥魂',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從手牌將1隻等級4以下且是戰士族、恐龍族、電子界族的地屬性怪獸守備表示特殊召喚。\u000a②：將我方場上1隻連結3以上的「剛鬼」怪獸解放可以發動。從牌組、額外牌組將1隻「恐龍摔角手」怪獸或「G石人」怪獸特殊召喚。'),'效果1','效果2','是否特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95448692,'傷害節食',unistr('這個回合，我方受到的全部傷害變成一半。\u000a此外，可以藉由將墓地的此卡除外，這個回合我方受到的效果傷害變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95451366,'魔力枯渴','將我方和對手場上的魔力計數器全部去除。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95453143,'百目龍',unistr('闇屬性協調+協調以外的惡魔族怪獸1隻以上\u000a①：1回合1次，從我方墓地將1隻等級6以下的闇屬性效果怪獸除外可以發動。此卡直到結束階段得到和那隻怪獸的原本的卡名、效果相同的卡名、效果。\u000a②：此卡被破壞送去墓地的場合發動。從牌組將1隻「地縛神」怪獸加入手牌。'),'效果1','效果2','解除複製效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95454996,'碼麗絲＜后＞白色綁縛',unistr('包含「碼麗絲」怪獸的怪獸2隻以上\u000a這個卡名的①②③效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方、對手的墓地的卡合計最多3張為對象可以發動。那些卡除外。\u000a②：我方主要階段可以發動。從我方的牌組、墓地將1張「碼麗絲」陷阱卡在我方場上覆蓋。\u000a③：此卡被除外的場合，支付900生命值可以發動。此卡特殊召喚。那之後，我方可以抽1張卡。'),'效果1','效果2','效果3','是否抽1張卡？','','','','','','','','','','','','');
INSERT INTO texts VALUES(95457011,'天帝從騎 伊迪亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將「天帝從騎 伊迪亞」以外的1隻攻擊力800/守備力1000的怪獸守備表示特殊召喚。此效果的發動後，直到回合結束時我方不能從額外牌組將怪獸特殊召喚。\u000a②：此卡被送去墓地的場合，以我方的除外狀態的1張「帝王」魔法、陷阱卡為對象可以發動。那張卡加入手牌。'),'從牌組特殊召喚','除外的卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95463814,'幻魔帝 特里洛吉克',unistr('等級10怪獸×3\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合，或此卡已在怪獸區域存在的狀態有此卡以外的怪獸從墓地往我方場上特殊召喚的場合，以對手場上1隻表側表示怪獸為對象可以發動。給予對手那隻怪獸的原攻擊力一半的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95466842,'水精鱗-邃淵肺魚兵',unistr('只要此卡在場上表側表示存在，對手不能選擇其他水屬性怪獸作為攻擊對象。\u000a此外，只要此卡在場上表側表示存在，我方場上的水屬性怪獸的攻擊力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95471006,'XYZ合體',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的機械族、光屬性聯合怪獸卡被除外的場合可以發動。從牌組將「X-首領加農」「Y-龍形首領」「Z-金屬履帶」其中1隻特殊召喚。\u000a②：讓我方場上1隻融合怪獸回到額外牌組可以發動。從除外的我方怪獸之中，選最多2隻「X-首領加農」「Y-龍形首領」「Z-金屬履帶」特殊召喚（同名卡最多1張）。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95472621,'大火葬','對手將以墓地的怪獸為對象的卡片發動時可以發動。雙方墓地的怪獸全部除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95474755,'No.89 電腦獸 系統破壞神',unistr('等級7怪獸×2\u000a這個卡名的③效果1回合只能使用1次。\u000a①：1回合1次，去除此卡的1個超量素材可以發動。確認對手的額外牌組，從其中選1張裡側表示除外。\u000a②：此卡戰鬥破壞怪獸的戰鬥階段結束時，以對手墓地1張卡為對象可以發動。那張卡裡側表示除外。\u000a③：對手的卡被裡側表示除外的場合可以發動。依照裡側表示除外的對手的卡片數量，將對手牌組上方的卡裡側表示除外。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95477924,'魔法師救出',unistr('這個卡名的卡在1回合只能發動1張，這個卡名的②效果1回合只能使用1次。\u000a①：作為此卡的發動時的效果處理，可以從牌組選1張「永遠之魂」在我方場上覆蓋。\u000a②：我方將「黑魔導」或「黑魔導女孩」召喚、特殊召喚的場合，以其中1隻為對象可以發動。從我方墓地挑選和那隻怪獸卡名不同的1隻「黑魔導」或「黑魔導女孩」特殊召喚。'),'是否從牌組選1張「永遠之魂」在我方場上覆蓋？','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95486586,'E.HERO 地核',unistr('「E.HERO」怪獸×3\u000a此卡只能用融合召喚來特殊召喚。\u000a①：1回合1次，此卡成為攻擊對象時可以發動。此卡的攻擊力直到那次傷害步驟結束時變成2倍。\u000a②：此卡進行戰鬥的戰鬥階段結束時，以場上1隻怪獸為對象可以發動。那隻怪獸破壞。\u000a③：此卡被戰鬥、效果破壞時，以我方墓地1隻等級8以下的「E.HERO」融合怪獸為對象可以發動。那隻怪獸無視召喚條件特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95492061,'萬手佛','①：此卡召喚、反轉召喚時可以發動。從牌組將1隻儀式怪獸或1張儀式魔法卡加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95493471,'真超級量子機神王 爆裂巨神',unistr('包含「超級量子」怪獸的效果怪獸2隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：連結召喚的此卡不會被對手的效果破壞。\u000a②：每次有同名卡不在我方場上存在的「超級量子」超量怪獸從額外牌組往此卡指向的區域特殊召喚發動。我方從牌組抽1張卡。\u000a③：此卡指向的超量怪獸被戰鬥或對手的效果破壞的場合可以發動。從牌組將1隻和那隻超量怪獸原屬性相同的「超級量子」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95500396,'超重武者裝留 仲裁',unistr('「超重武者裝留 仲裁」的③效果1回合只能使用1次。\u000a①：我方主要階段以我方場上1隻「超重武者」怪獸為對象可以發動。從我方的手牌、場上將這隻怪獸當作裝備卡給那隻我方怪獸裝備。\u000a②：此卡的效果讓此卡裝備中的場合，對手不能攻擊裝備怪獸以外的我方怪獸。\u000a③：將用此卡的效果裝備此卡的我方怪獸解放可以發動。從牌組將1隻「超重武者」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95503687,'光道召喚師 露米娜絲',unistr('①：1回合1次，捨棄1張手牌，以我方墓地1隻等級4以下的「光道」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方結束階段發動。從我方牌組上方將3張卡送去墓地。'),'特殊召喚','牌組3張卡片送入墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95504778,'扳機亞龍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡作為闇屬性連結怪獸的連結素材送去墓地的場合可以發動。墓地的此卡在那隻連結怪獸指向的我方場上攻擊表示特殊召喚。此效果特殊召喚的此卡不能作為連結素材。\u000a②：此卡被連結怪獸發動的效果破壞的場合或被除外的場合發動。我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95506252,'影裝騎士 黑傑克',unistr('協調+協調以外的怪獸1隻以上\u000a①：此卡不會被戰鬥破壞。\u000a②：每次對手的魔法與陷阱區域有卡放置發動。從我方牌組上方翻開卡片，直到怪獸出現為止，那隻怪獸當作裝備魔法卡給此卡裝備。其餘以喜歡的順序回到牌組下方。\u000a③：此卡的攻擊力、守備力上升此卡裝備的怪獸的等級總和×300。\u000a④：此卡裝備的怪獸的等級總和大於21的場合，此卡破壞。'),'','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95507060,'狂植物的氾濫','我方場上的全部植物族怪獸的攻擊力直到回合結束時上升我方墓地的植物族怪獸數量×300。這個回合的結束階段，我方場上的植物族怪獸全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95511642,'獲得星杯的巫女',unistr('向星神獻上鎮魂祈禱的巫女。手持之杖是世代繼承的祭器，將力量變成結界從機界騎士支配中守護著森林之民。\u000a雖然她的身上隱藏有足以馴服森林守護龍的神通之力，但平日所見的她卻有著珍愛哥哥及童年玩伴的親切少女一面。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515058,'剛鬼 利劍食人魔',unistr('「剛鬼」怪獸2隻以上\u000a①：此卡的攻擊力上升此卡指向的怪獸數量×300。\u000a②：1回合1次，將此卡指向的1隻我方或對手的怪獸解放可以發動。這個回合，此卡在1次戰鬥階段中可以攻擊2次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515060,'靜寂之杖-姬絲特',unistr('裝備怪獸的守備力上升500。\u000a以裝備怪獸為對象的此卡以外的魔法卡的效果無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515518,'月天氣 彩虹',unistr('「天氣」怪獸3隻\u000a①：此卡連結召喚成功的場合可以發動。選被除外的1隻我方的「天氣」怪獸特殊召喚。\u000a②：此卡指向的「天氣」效果怪獸得到以下效果。\u000a●我方、對手回合，將此卡除外，以對手場上1隻怪獸為對象可以發動。那隻怪獸直到下個回合的準備階段除外。\u000a③：連結召喚的此卡被破壞的場合可以發動。從額外牌組將1隻「虹天氣 彩虹」特殊召喚。'),'效果1','●對手怪獸除外（月天氣 彩虹）','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515789,'赫之聖女 卡爾特西亞',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方的場上或墓地有「阿不思的落胤」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方、對手的主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻等級8以上的融合怪獸融合召喚。\u000a③：這個回合有融合怪獸被送去我方墓地的場合，結束階段可以發動。墓地的此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515790,'赫之聖女 卡爾特西亞',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方的場上或墓地有「阿不思的落胤」存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方、對手的主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻等級8以上的融合怪獸融合召喚。\u000a③：這個回合有融合怪獸被送去我方墓地的場合，結束階段可以發動。墓地的此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95519486,'六武眾-斬侍',unistr('我方場上有「六武眾-斬侍」以外的「六武眾」怪獸存在的場合，此卡向怪獸攻擊的傷害步驟結束時，那隻怪獸破壞。\u000a場上的此卡被戰鬥、效果破壞的場合，可以將我方場上1隻「六武眾」怪獸破壞作為代替。'),'攻擊過的怪獸破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95526884,'高能念力砲手',unistr('協調+協調以外的超能族怪獸1隻以上\u000a此卡向守備表示怪獸攻擊時，如果攻擊力超過那個守備力，給予對手那個數值的戰鬥傷害。\u000a此卡向守備表示怪獸攻擊的傷害步驟結束時，如果攻擊力超過那個守備力，我方的生命值回復那個數值。'),'回復生命值','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95545183,'異譚的忍法帖',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手場上有卡存在的場合可以發動。從我方的牌組、墓地選「異譚的忍法帖」以外的「忍法」魔法、陷阱卡以及「忍者」怪獸各最多1張，在我方場上覆蓋（從牌組、墓地各自只能選最多1張覆蓋）。\u000a②：覆蓋的此卡被送去墓地的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95561146,'阿波畢斯的蛇神',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡發動後變成通常怪獸（爬蟲類族、地、等級4、攻1600/守1800）在怪獸區域特殊召喚（也當作陷阱卡）。那之後，可以從牌組將「阿波畢斯的蛇神」以外的1張「阿波畢斯」陷阱卡在我方場上覆蓋。此效果覆蓋的卡在覆蓋的回合也能發動。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1張「阿波畢斯的化神」加入手牌。'),'適用「阿波畢斯的蛇神」的效果來發動','是否將1張陷阱卡覆蓋？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95561280,'猛毒之風',unistr('只要此卡在場上存在，雙方不能將風屬性怪獸特殊召喚。\u000a場上的風屬性怪獸的攻擊力下降500。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95568112,'雨天虹娃',unistr('【靈擺效果】\u000a①：1回合1次，以我方場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升雙方的額外牌組的張數的差額×100。\u000a【怪獸效果】\u000a①：在我方回合中是攻擊力，在對手回合中是守備力，此卡的那個數值上升雙方的額外牌組的張數的差額×200。\u000a②：此卡攻擊的場合，在戰鬥階段結束時變成守備表示。\u000a③：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95589901,'大狼的惡作劇',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以下效果各自適用。\u000a●對手場上的全部怪獸的等級下降2。\u000a●我方場上的全部怪獸的等級上升2。\u000a②：此卡送去墓地的回合的我方主要階段，以我方場上1張表側表示卡為對象可以發動。那張卡破壞，此卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95600067,'寶玉獸 黃玉虎',unistr('①：此卡向對手怪獸攻擊的傷害步驟期間，此卡的攻擊力上升400。\u000a②：表側表示的此卡在怪獸區域被破壞的場合，可以不送去墓地當作永續魔法卡以表側表示放置在我方的魔法與陷阱區域。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95602345,'暗岩的利維坦',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：將我方場上1張表側表示的「海」送去墓地可以發動。從手牌、牌組將最多2隻記載「海」的卡名的怪獸或水屬性通常怪獸守備表示特殊召喚（同名卡最多1張）。對手場上有怪獸存在的場合，隨後可以從手牌、牌組將任意數量的等級6以下的水屬性通常怪獸特殊召喚。此卡的發動後，直到下個我方回合結束時我方除了水屬性怪獸以外不能特殊召喚。'),'是否繼續特殊召喚水屬性通常怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95612049,'世界逆轉',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：解放手牌的儀式怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌、牌組儀式召喚「破滅之女神 茹茵」或「終焉之王 帝滅斯」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95614612,'砲彈螺貝','只要場上有「海」存在，此卡不受魔法卡的效果影響。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95621257,'炎獄魔術師','只要我方場上有「正義盟軍」怪獸存在，此卡的攻擊力上升400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95626382,'終刻獄龍機XII-德拉斯特琉斯',unistr('等級8怪獸×3\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：此卡超量召喚的場合可以發動。場上1隻其他的表側表示怪獸當作裝備魔法卡給此卡裝備。\u000a②：此卡1回合只有1次不會被戰鬥、效果破壞。\u000a③：對手發動場上、墓地的怪獸的效果時，去除此卡的1個超量素材可以發動。那個效果無效。那之後，可以將對手場上1隻表側表示怪獸當作裝備魔法卡給此卡裝備。'),'效果1','效果3','是否將1隻對手怪獸裝備？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95637655,'備份戰士','此卡不能通常召喚。我方場上的怪獸只有守備表示怪獸2隻的場合可以特殊召喚。將此卡特殊召喚的整回合中，我方不能同步召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95638658,'流星之弓-西魯',unistr('裝備怪獸的攻擊力下降1000。\u000a裝備怪獸可以直接攻擊對手。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95642274,'謙虛的衛兵','將我方的手牌公開，從其中選1張回到牌組。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95658967,'祝福的教會-儀式教堂',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌捨棄1張魔法卡可以發動。從牌組將1隻光屬性儀式怪獸或1張儀式魔法卡加入手牌。\u000a②：讓我方墓地任意數量的魔法卡回到牌組，以我方墓地1隻等級和回去的數量相同的天使族、光屬性怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95664204,'ZEXAL彈射器',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1隻「ZW」怪獸或「ZS」怪獸特殊召喚。我方場上有「希望皇霍普」怪獸存在的場合，隨後可以將我方場上的全部怪獸的等級變成4或5。\u000a②：將1隻「ZW」怪獸或「ZS」怪獸和此卡從我方墓地除外，以對手場上1張卡為對象可以發動。那張卡破壞。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','是否改變等級？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95676943,'滅絕的定數','①：我方、對手的主要階段，支付2000生命值可以發動。此卡發動後的第3次戰鬥階段結束時，雙方玩家必須將各自場上的卡全部送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95679145,'教導的大神祇官',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方墓地將1隻融合、同步、超量、連結怪獸除外可以發動。此卡從手牌特殊召喚。\u000a②：我方主要階段可以發動。從我方的額外牌組將2隻卡名不同的怪獸送去墓地。對手從自身的額外牌組將2隻怪獸送去墓地。此效果的發動後，直到回合結束時我方不能從額外牌組將怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95685352,'黑暗反日龍',unistr('【靈擺效果】\u000a①：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸的原攻擊力直到回合結束時變成一半。\u000a【怪獸效果】\u000a等級7怪獸×2\u000a等級7可以靈擺召喚的場合，在額外牌組的表側表示的此卡可以靈擺召喚。\u000a①：1回合1次，去除此卡的1個超量素材，以對手場上1隻表側表示怪獸為對象可以發動。直到回合結束時，那隻怪獸的攻擊力變成一半，此卡的攻擊力上升那個數值。此效果在對手回合也能發動。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'靈擺效果1','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95697223,'龍的鬥志','①：以我方場上1隻這個回合特殊召喚的龍族怪獸為對象可以發動。這個回合，除了通常攻擊以外，那隻怪獸在1次戰鬥階段中可以攻擊的次數，相當於對手場上的在這個回合中特殊召喚的怪獸數量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95701283,'光神機-轟龍',unistr('此卡可以解放1隻怪獸來召喚。\u000a這個方法召喚的場合，結束階段時，此卡送去墓地。\u000a此卡向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。'),'解放1隻怪獸召喚','送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95714077,'發條量產','「發條」怪獸的效果發動的場合，可以從我方牌組將1隻「發條」等級4以下的怪獸加入手牌。這個效果1回合只能使用1次。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95718355,'再世荒惡魔神 貝米德巴爾',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②③效果1回合各能使用1次。\u000a①：此卡可以向對手展示手牌的1隻攻擊力或守備力是2500的其他怪獸，從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。「再世荒惡魔神 貝米德巴爾」以外的我方的牌組、除外狀態的1張「再世」卡片加入手牌。\u000a③：此卡被送去墓地的對手回合的結束階段可以發動。此卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95727991,'飛箭龜','1回合1次，解放我方場上1隻怪獸可以發動。給予對手解放的怪獸的攻擊力一半數值的傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95735217,'古代機械齒輪巨人-究極重拳',unistr('此卡不能特殊召喚。\u000a①：此卡向守備表示怪獸攻擊的場合，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：1回合最多2次，此卡的攻擊破壞怪獸時，從手牌捨棄1隻機械族怪獸可以發動。此卡可以繼續攻擊。\u000a③：場上的此卡被戰鬥、效果破壞的場合可以發動。從牌組將1張「融合」加入手牌，從我方墓地將1隻其他的「古代機械齒輪」怪獸加入手牌。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95744531,'咕哩咕嚕','場上表側表示存在的此卡的控制權轉移給對手時，我方回復3000生命值。這個效果於此卡在場上表側表示存在期間只能使用1次。','回復','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95750695,'超二重之力',unistr('只能給二重怪獸裝備。\u000a①：裝備怪獸當作再次召喚狀態。\u000a②：表側表示的此卡從場上送去墓地的場合，以我方墓地1隻通常怪獸為對象發動。那隻怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95772051,'魔聖騎士 蘭斯洛特',unistr('將我方場上表側表示存在的1隻光屬性通常怪獸送去墓地可以發動。此卡從手牌或墓地特殊召喚。\u000a將我方場上的1隻「聖騎士」怪獸解放可以發動。從牌組將1張「聖劍」卡片加入手牌。「魔聖騎士 蘭斯洛特」的這個效果1回合只能使用1次。\u000a「魔聖騎士 蘭斯洛特」在我方場上只能有1隻表側表示存在。'),'特殊召喚','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95784434,'蛻皮逃脫',unistr('只能給爬蟲類族怪獸裝備。\u000a裝備怪獸1回合只有1次不會被戰鬥破壞。此效果適用的傷害步驟結束時，裝備怪獸的攻擊力上升300。'),'攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95784714,'徬徨幽靈船 飛翔瑪麗號',unistr('不死族怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：以我方的墓地、除外狀態的1隻等級5以上的不死族怪獸為對象可以發動。此卡當作永續魔法卡在我方的魔法與陷阱區域表側表示放置，對象怪獸特殊召喚。\u000a②：此卡當作永續魔法卡的場合，以我方場上1隻等級5以上的不死族怪獸為對象可以發動。對手場上1隻攻擊力在那隻怪獸的攻擊力以下的怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95788410,'兔龍','在雷原棲息的龍的突變種。巨大的耳朵能夠聽到數公里外的聲音，驚人的跳躍力讓獵物無處可逃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95789089,'冠軍袋鼠','與此卡進行戰鬥的怪獸，在傷害計算後，變成守備表示。','變成守備表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95793022,'星杯的守護龍 阿爾瑪杜克',unistr('連結怪獸×3\u000a此卡只能用融合召喚或以下方法從額外牌組特殊召喚。\u000a●將我方場上的上述卡解放，可以從額外牌組特殊召喚（不需要「融合」）。\u000a①：此卡可以向全部對手怪獸各攻擊1次。\u000a②：此卡和對手的連結怪獸進行戰鬥的攻擊宣言時，從我方的場上、墓地將1隻連結標記數量和那隻對手怪獸相同的連結怪獸除外可以發動。那隻對手怪獸破壞，給予對手那個原攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95816395,'土偶',unistr('「土偶」的效果1回合只能使用1次。\u000a①：此卡被對手的效果送去墓地的回合的結束階段可以發動。從牌組將1隻不在我方的場上、墓地存在的等級的怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95824983,'電氣水母',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、牌組、場上（表側表示）將1張「海」送去墓地可以發動。從手牌將1隻水屬性怪獸特殊召喚。\u000a②：場上有「海」存在，對手發動魔法、怪獸的效果時可以發動。那個效果無效。那之後，可以讓此卡的攻擊力、守備力上升600。'),'效果1','效果2','是否讓此卡的攻擊力、守備力上升600？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95825679,'惡魔的降臨',unistr('藉由「與奈落的契約」降臨。\u000a①：只要此卡在怪獸區域存在，卡名當作「惡魔的召喚」。\u000a②：場上的此卡不會被儀式怪獸以外的怪獸戰鬥破壞，不會被儀式怪獸以外的怪獸效果破壞。\u000a③：儀式召喚的此卡被對手送去墓地的場合可以發動。從我方的手牌、牌組、墓地選1隻「惡魔的召喚」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95833645,'岩漿龍',unistr('「岩漿龍」的效果1回合只能使用1次，此效果發動的整回合中，我方除了幻龍族怪獸以外不能特殊召喚。\u000a①：此卡特殊召喚成功時，以「岩漿龍」以外的我方墓地1隻幻龍族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95841282,'貓耳族','對手回合中，與此卡戰鬥的對手怪獸的原攻擊力在傷害步驟中變成200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95856586,'ZEXAL場地',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：應對以我方場上的超量怪獸為對象的我方的卡的效果發動，對手不能發動魔法、陷阱、怪獸的效果。\u000a②：我方場上有超量怪獸特殊召喚的場合，以那1隻怪獸為對象可以發動。從我方的額外牌組、墓地選1隻超量怪獸重疊在對象怪獸下方作為超量素材。\u000a③：我方抽牌階段的抽牌前可以發動。從牌組選1張「閃光抽牌」放置在牌組最上方。'),'效果2','效果3','請選擇要放在牌組最上方的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95886782,'ZW-天風精靈翼',unistr('①：「ZW-天風精靈翼」在我方場上只能有1張表側表示存在。\u000a②：以我方場上1隻「希望皇霍普」怪獸為對象可以發動。從我方的手牌、場上將此卡當作攻擊力上升800的裝備卡給那隻怪獸裝備。\u000a③：1回合1次，對手發動的效果將怪獸特殊召喚的場合可以發動。裝備怪獸的攻擊力上升1600。\u000a④：裝備怪獸去除超量素材來發動效果的場合，可以將此卡送去墓地作為去除的1個超量素材的代替。'),'效果2','效果3','效果4','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95888876,'地獄凱撒龍',unistr('①：只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a②：可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合，此卡變成持有以下效果的效果怪獸。\u000a●此卡在1次戰鬥階段中可以攻擊2次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95905259,'預言僧 長蓮','①：1回合1次，宣言卡的種類（魔法、陷阱），以對手的魔法與陷阱區域覆蓋的1張卡為對象可以發動。那張覆蓋的卡給雙方確認，如果是宣言的種類，這個回合那張卡不能發動。','效果1','請選擇1張要確認的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95911373,'偉魔代蒙 絕火之瑣羅亞',unistr('魔法使族協調+協調以外的怪獸1隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡同步召喚成功的場合可以發動。從額外牌組將1隻「偉魔」怪獸當作裝備卡給此卡裝備。\u000a②：對手不能發動和我方的魔法與陷阱區域的「偉魔」怪獸卡相同種類（融合、同步、超量、連結）的怪獸的效果。\u000a③：以我方場上1張「偉魔」卡片為對象可以發動。那張卡破壞，此卡從墓地特殊召喚。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95915457,'反射鏡防護罩',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以我方場上1隻表側表示怪獸為對象可以發動此卡。此卡當作持有以下效果的裝備卡給那隻怪獸裝備。\u000a●裝備怪獸和對手怪獸進行戰鬥的戰鬥步驟1次，可以發動。那隻對手怪獸破壞。\u000a②：此卡被破壞的場合可以發動。從牌組將1張「武裝轉生」加入手牌。'),'效果1','效果2','●對手怪獸破壞（反射鏡防護罩）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95920682,'英豪贈禮',unistr('「英豪贈禮」在1回合只能發動1張。\u000a對手的生命值是2000以下的場合可以發動。對手的生命值變成8000，我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95923441,'古代遺跡獵人',unistr('①：場地魔法卡表側表示存在的場合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻岩石族怪獸。\u000a②：對手回合1次，以我方場上1張「古代遺跡」場地魔法卡為對象可以發動。那張卡送去墓地，從牌組發動卡名和那張卡不同的1張「古代遺跡」場地魔法卡。'),'效果2','召喚（古代遺跡獵人）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95929069,'冰凍手','①：此卡被對手破壞送去墓地時，以對手場上1張魔法、陷阱卡為對象可以發動。那張對手的魔法、陷阱卡破壞。那之後，可以從牌組將1隻「火焰手」特殊召喚。','效果1','是否特殊召喚「火焰手」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95937545,'金色魅惑的女王',unistr('魔法使族怪獸3隻\u000a①：此卡連結召喚的場合可以發動。從我方的牌組、墓地將1隻「魅惑的女王」怪獸特殊召喚，此卡的攻擊力直到下個回合結束時上升1500。\u000a②：原卡名包含「魅惑的女王」的我方怪獸持有的將怪獸給自身裝備的效果，變成在對手回合也能發動的效果。\u000a③：1回合1次，對手發動效果時可以發動。場上1張卡破壞。這個回合中，我方場上的「魅惑的女王」怪獸不會被效果破壞。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95943058,'E-HERO 地獄黑手',unistr('①：在我方主要階段1，將場上的此卡除外，以我方場上1隻惡魔族怪獸為對象可以發動。那隻我方的惡魔族怪獸只要在場上表側表示存在，在1次戰鬥階段中可以攻擊2次。\u000a②：此卡為了發動①效果而被除外的場合，第2次的我方準備階段發動。此卡攻擊表示特殊召喚。'),'賦予攻擊2次','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95952802,'花狼','「銀牙」+「魔界的荊棘」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95953557,'焰聖騎士-阿斯托爾福',unistr('這個卡名的①②效果在決鬥中各能使用1次。\u000a①：從我方的手牌、墓地將1隻戰士族、炎屬性怪獸除外可以發動。此卡從手牌特殊召喚。那之後，可以將此卡的等級變成和除外的怪獸相同。\u000a②：將墓地的此卡除外可以發動。發動後第2次的我方準備階段，除外的此卡特殊召喚。那之後，可以從我方墓地的怪獸以及被除外的我方怪獸之中選1隻戰士族、炎屬性怪獸特殊召喚。'),'效果1','效果2','是否改變等級？','是否特殊召喚另外1隻怪獸？','','','','','','','','','','','','');
INSERT INTO texts VALUES(95956346,'光輝天使','此卡被戰鬥破壞送去墓地時可以發動。從牌組將1隻攻擊力1500以下的光屬性怪獸攻擊表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95973569,'T.G. 長柄刀爆破砲手',unistr('同步怪獸協調+協調以外的同步怪獸2隻以上\u000a此卡只能用同步召喚來特殊召喚。\u000a①：我方、對手回合，以從額外牌組特殊召喚的場上1隻怪獸為對象可以發動（此效果在1回合中可以使用的次數是作為此卡的同步素材的協調以外的同步怪獸數量）。那隻怪獸除外。\u000a②：1回合1次，怪獸被表側除外的場合，以其中的1隻為對象可以發動。那隻怪獸無視召喚條件在我方場上特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95974848,'S-Force 孔口測量員',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，我方的「S-Force」怪獸的正前方的對手怪獸不會成為對手的效果的對象。\u000a②：對手場上的怪獸發動效果時，從手牌將1張「S-Force」卡片除外可以發動。那隻怪獸破壞。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95990456,'陰魔羅鬼',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡被對手的效果破壞送去墓地的場合，或從墓地特殊召喚成功的場合可以發動。我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95992081,'虛空海龍 利瓦耶爾',unistr('等級3怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材，以我方或對手的除外狀態的1隻等級4以下的怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95993388,'地帝家臣 蘭羅布',unistr('「地帝家臣 蘭羅布」的①②效果1回合各能使用1次。\u000a①：以對手場上1隻表側表示怪獸為對象可以發動。此卡從手牌特殊召喚，對象怪獸變成裡側守備表示。這個回合，我方不能從額外牌組將怪獸特殊召喚。\u000a②：此卡為了上級召喚而被解放的場合，以「地帝家臣 蘭羅布」以外的我方墓地1隻攻擊力800/守備力1000的怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96004535,'超量不破障壁',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有超量怪獸存在，怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效。那之後，可以去除我方場上的2個超量素材。那個場合，隨後將場上1張卡破壞。\u000a②：將墓地的此卡除外，以我方場上1隻超量怪獸為對象可以發動。從我方墓地將1隻光屬性的「霍普」超量怪獸作為對象怪獸的超量素材。'),'效果1','效果2','是否去除2個超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96005454,'獵龍','以尖牙殺死獵物的龍。動作迅捷敏銳地發出攻擊，不過沒有守備能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96008713,'魔術臂盾','①：對手場上有2隻以上表側表示怪獸存在，我方場上有怪獸存在的場合，對手怪獸的攻擊宣言時，以攻擊怪獸以外的對手場上1隻表側表示怪獸為對象可以發動。直到戰鬥階段結束時，得到那隻表側表示怪獸的控制權，攻擊對象轉移到那隻怪獸進行傷害計算。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96012004,'幸運機會！','投擲1次硬幣的怪獸的效果發動時，猜那個硬幣的正反面。如果猜對，從牌組抽1張卡。','猜硬幣','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96015976,'再轉','①：1回合1次，以場上1隻等級和原等級不同的怪獸為對象可以發動此效果。擲1次骰子。對象怪獸的等級變成和擲出點數相同。','改變等級','是否現在發動此卡的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96026108,'龍輝巧-上弼ζ',unistr('此卡不能通常召喚，只能用「龍輝巧」卡片的效果特殊召喚。這個卡名的效果1回合只能使用1次。\u000a①：將此卡以外的我方的手牌、場上1隻「龍輝巧」怪獸或儀式怪獸解放可以發動（此效果發動的整回合中，我方除了不能通常召喚的怪獸以外不能特殊召喚）。此卡從手牌、墓地守備表示特殊召喚。那之後，可以從牌組將1張儀式魔法卡加入手牌。'),'效果1','是否從牌組把1張儀式魔法卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96029570,'漆黑的太陽',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方場上的表側表示怪獸被戰鬥、效果破壞的場合可以發動。我方的生命值回復那些怪獸的原攻擊力的合計數值。\u000a②：從我方墓地有怪獸表側表示特殊召喚的場合，以其中的1隻為對象可以發動。那隻怪獸的攻擊力上升1000。\u000a③：魔法、陷阱卡從我方的手牌捨棄到我方墓地的場合，以其中1張為對象可以發動。那張卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96029574,'黑牛龍',unistr('協調+協調以外的二重怪獸1隻以上\u000a1回合1次，從手牌將1隻二重怪獸送去墓地可以發動。選擇對手場上的1張魔法、陷阱卡破壞。\u000a此卡被破壞送去墓地時，可以選擇我方墓地的1隻二重怪獸特殊召喚。此效果特殊召喚的二重怪獸當作再次召喚狀態。'),'破壞魔法、陷阱卡','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96030710,'百夫長龍騎士 阿特莉',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，若「徽紋」卡片和「百夫長」卡片都在我方墓地存在則能發動。我方抽1張卡。這個回合，我方不能將「百夫長龍騎士 阿特莉」特殊召喚。\u000a②：將我方場上的此卡作為同步素材的場合，可以將此卡當作協調以外的怪獸。\u000a③：此卡當作永續陷阱卡的場合，我方、對手的主要階段可以發動。此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96051150,'陽炎獸 蠍獅',unistr('只要此卡在場上表側表示存在，對手不能將此卡作為效果的對象。\u000a1回合1次，將手牌或我方場上表側表示存在的1隻炎屬性怪獸送去墓地可以發動。這個回合，此卡不會被效果破壞。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96055137,'獄火機 貝爾芬格',unistr('此卡不能通常召喚。只能在我方場上的效果怪獸的等級、階級的總和是8以下時，將我方的手牌、墓地2隻「獄火機」怪獸除外，從手牌、墓地特殊召喚。\u000a①：此卡的攻擊宣言時可以發動。對手從自身的額外牌組將1隻怪獸除外。\u000a②：我方、對手回合1次，將我方場上1隻怪獸解放，以對手墓地1張卡為對象可以發動。那張卡除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96073342,'神數的星戰',unistr('「神數的星戰」在1回合只能發動1張。我方的靈擺區域有2張「神數」卡片存在的場合，此卡也能從手牌發動。\u000a①：以我方場上1張「神數」卡片和對手場上1張卡為對象可以發動。那些卡破壞。'),'適用「神數的星戰」的效果來發動','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96084564,'艾樂隆',unistr('這個卡名在規則上也當作「閃刀」卡片。這個卡名的①③效果1回合只有1次能使用其中1個。\u000a①：我方、對手的主要階段，以我方場上1隻「閃刀姬」怪獸為對象可以發動。從我方的手牌、場上將此卡當作裝備魔法卡給那隻怪獸裝備。\u000a②：已裝備此卡的「閃刀姬」怪獸的攻擊力上升400。\u000a③：場上的此卡被破壞的場合可以發動。從牌組將1張「閃刀」魔法卡送去墓地。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96099959,'X-軍刀 帕隆洛','此卡在墓地存在，我方場上的「軍刀」怪獸被戰鬥破壞送去墓地時，可以藉由支付500生命值，此卡從墓地特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96100333,'古代遺跡的覺醒',unistr('①：1回合1次，可以從我方墓地將岩石族怪獸或場地魔法卡合計2張除外，從以下效果選擇1個發動。\u000a●以此卡以外的場上1張表側表示的卡為對象可以發動。那張卡破壞。\u000a●以我方墓地1隻岩石族怪獸為對象可以發動。那隻怪獸守備表示特殊召喚。\u000a●以我方墓地最多3張場地魔法卡為對象可以發動。那些卡加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'卡片的發動','●場上的卡破壞','●墓地的岩石族怪獸特殊召喚','●墓地的場地魔法卡加入牌組洗牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(96113307,'聖靈獸騎 風族',unistr('效果怪獸3隻以上\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：只要此卡在怪獸區域存在，雙方不能為了發動卡的效果而將卡解放。\u000a②：以我方的除外狀態的1張「靈獸」卡片為對象可以發動。那張卡回到手牌、額外牌組。那之後，可以進行手牌的1隻「靈獸」怪獸的召喚。\u000a③：對手回合，以我方場上1張「靈獸」卡片和對手場上1張卡為對象可以發動。那些卡除外。'),'效果2','效果3','是否召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96127902,'相當魅湧的接單水產',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以對手墓地1張卡為對象可以發動。那張卡除外。那之後，可以從牌組將1張那張卡的同名卡加入手牌。'),'效果1','是否將1張同名卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96142517,'升階魔法-千死蠻巧',unistr('「升階魔法-千死蠻巧」在1回合只能發動1張，此卡發動的整回合中，我方不能用此卡的效果以外將怪獸特殊召喚。\u000a①：以我方和對手墓地各1隻以上相同階級的超量怪獸為對象可以發動。從額外牌組將1隻階級比那些怪獸高1階的「CNo.」怪獸或「混沌超量」怪獸特殊召喚，將對象怪獸重疊在下方作為超量素材。'),'是否繼續選擇對象？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96146814,'AD轉換者','將墓地的此卡除外，選擇場上的1隻怪獸可以發動。那隻怪獸的表示形式變更。','改變表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96148285,'誘發召喚','對手場上有怪獸特殊召喚時可以發動。雙方可以從手牌將1隻等級4以下的怪獸特殊召喚到場上。','從手牌把1隻等級4以下的怪獸特殊召喚到場上','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96150936,'魔法甜點新人 水果塔修女',unistr('「魔法甜點」怪獸2隻\u000a①：只要此卡指向的區域有「魔法甜點」怪獸存在，我方場上的「魔法甜點」魔法、陷阱卡不會被效果破壞，雙方不能將那些卡作為效果的對象。\u000a②：場上的此卡被戰鬥、效果破壞的場合，可以讓我方墓地1隻「魔法甜點」怪獸回到牌組作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96156729,'WW-鈴音',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了風屬性怪獸以外不能特殊召喚。\u000a①：以我方場上1隻「WW-」怪獸為對象可以發動。從牌組將1隻和那隻怪獸卡名不同的「WW-」怪獸守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96157835,'RR-武庫獵鷹',unistr('等級7怪獸×2\u000a①：1回合1次，去除此卡的1個超量素材可以發動。從牌組將1隻鳥獸族、等級4怪獸特殊召喚。\u000a②：持有「RR-」怪獸作為超量素材的此卡在1次戰鬥階段中可以攻擊多次，次數上限為那個數量。\u000a③：持有「RR-」怪獸作為超量素材的此卡被送去墓地的場合可以發動。從額外牌組將「RR-武庫獵鷹」以外的1隻「RR-」超量怪獸特殊召喚，此卡作為那個超量素材。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96162588,'六花的風花',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方場上的「六花」怪獸被解放的場合可以發動。對手必須將自身場上1隻怪獸解放。\u000a②：對手結束階段，我方場上有植物族怪獸以外的表側表示怪獸存在的場合發動。此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96163807,'冥界騎士 崔斯坦',unistr('①：此卡召喚成功時，以我方墓地1隻守備力0的不死族怪獸為對象可以發動。那張卡加入手牌。\u000a②：我方場上有此卡以外的不死族怪獸存在的場合，此卡的攻擊力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96182448,'氮素同步者','此卡被「氮素」同步怪獸的同步召喚使用送去墓地的場合，從我方牌組抽1張卡。','抽1張卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96203584,'溟界的大蛟',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、場上將1隻怪獸送去墓地，以我方墓地1隻和那隻怪獸原屬性不同的爬蟲類族怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：我方、對手的主要階段，怪獸送去對手墓地的場合可以發動。從牌組將1隻爬蟲類族怪獸送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96214561,'招神鳥 西摩格',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚成功時可以發動。從牌組將「招神鳥 西摩格」以外的1張「西摩格」卡片加入手牌。\u000a②：此卡在墓地存在，對手的魔法與陷阱區域沒有卡存在的場合可以發動。此卡守備表示特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。此效果的發動後，直到回合結束時我方除了鳥獸族怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96216229,'劍鬥獸的戰車','①：我方場上有「劍鬥獸」怪獸存在，怪獸的效果發動時可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96218085,'中央突破','我方回合，選擇我方場上1隻「六武眾」怪獸可以發動。我方場上的「大將軍 紫炎」以及「六武眾」怪獸在這個回合中，選擇的怪獸戰鬥破壞對手怪獸的場合，可以直接攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96220350,'霸勝星 韋馱天',unistr('等級5以上的戰士族怪獸×2\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡融合召喚成功的場合可以發動。從牌組將1隻戰士族、等級5怪獸加入手牌。\u000a②：1回合1次，將任意數量的手牌捨棄可以發動。此卡的攻擊力上升捨棄張數×200。\u000a③：此卡和等級在此卡的等級以下的對手怪獸進行戰鬥的傷害計算時1次，可以發動。那隻對手怪獸的攻擊力只在那次傷害計算時變成0。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96223501,'光衛星騎士-神數右樞',unistr('【靈擺效果】\u000a①：我方除了「星騎士」怪獸以及「神數」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a【怪獸效果】\u000a「光衛星騎士-神數右樞」的怪獸效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、靈擺召喚成功的場合，以此卡以外的我方的怪獸區域、靈擺區域1張「星騎士」卡片或「神數」卡片，和對手場上1張表側表示的卡為對象可以發動。那些卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96227613,'霸王門 零',unistr('【靈擺效果】\u000a①：我方場上有「霸王龍 札克」存在的場合，我方受到的全部傷害變成0。\u000a②：1回合1次，另一邊的我方的靈擺區域有「霸王門 無限」存在的場合可以發動。我方的靈擺區域的2張卡破壞，從牌組將1張「融合」魔法卡或「結合」魔法卡加入手牌。\u000a【怪獸效果】\u000a①：1回合1次，以此卡以外的我方場上1張表側表示卡為對象可以發動。那張卡和此卡破壞，將1隻龍族融合怪獸或龍族同步怪獸從額外牌組特殊召喚。此效果特殊召喚的怪獸的攻擊力、守備力變成0，效果無效化，不能作為同步、超量召喚的素材。\u000a②：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96228804,'安迪米翁的皇太子 雷古勒斯',unistr('這個卡名的①②的效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，向對手展示手牌的1隻其他的魔法使族怪獸可以發動。我方失去展示的怪獸的等級×300，此卡特殊召喚。\u000a②：此卡特殊召喚的場合可以發動。從牌組將1張記載「安迪米翁的皇太子 雷古勒斯」的卡名的魔法卡加入手牌。\u000a③：此卡1回合只有1次不會被戰鬥破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96235275,'光道聖武士 簡',unistr('①：此卡向對手怪獸攻擊的傷害步驟期間，此卡的攻擊力上升300。\u000a②：我方結束階段發動。從我方牌組上方將2張卡送去墓地。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96235944,'煉獄的決界',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上的「獄火機」怪獸的攻擊力上升我方的除外狀態的「獄火機」怪獸數量×100。\u000a②：我方場上的怪獸，不存在的場合或只有惡魔族怪獸的場合，可以從以下效果選擇1個發動。\u000a●我方的除外狀態的1隻「獄火機」怪獸加入手牌。\u000a●從手牌將1隻「獄火機」怪獸無視召喚條件特殊召喚。'),'●除外狀態的怪獸加入手牌','●從手牌將怪獸特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96239878,'集束之力',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方使用「青眼白龍」或「黑魔導」儀式、融合召喚成功的場合，以對手的場上、墓地1張卡為對象可以發動。那張卡除外。\u000a②：將魔法與陷阱區域的表側表示的此卡送去墓地，以我方墓地1隻等級7以上的通常怪獸為對象可以發動。那隻怪獸加入手牌或回到牌組。'),'效果1','效果2','回到牌組','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96287685,'瓶龜','只要此卡在場上表側表示存在，每次「強欲之瓶」發動，從我方牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96300057,'W-飛翼彈射器',unistr('①：1回合1次，可以從以下效果選擇1個發動。\u000a●以我方場上1隻「V-虎式噴射機」為對象，此卡當作裝備卡給那隻怪獸裝備。裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備的此卡特殊召喚。\u000a②：裝備怪獸的攻擊力、守備力上升400。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96305350,'黃金榮耀-卡莉船長',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方的生命值低於對手的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「黃金榮耀」陷阱卡加入手牌。\u000a③：此卡被送去墓地的場合，以從額外牌組特殊召喚的我方場上1隻「黃金榮耀」怪獸為對象可以發動。從我方墓地將最多3張「黃金榮耀」卡片除外，那隻怪獸的攻擊力上升除外數量×500。'),'從手牌特殊召喚','從牌組加入手牌','攻擊力上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96316857,'回收','我方回合準備階段時，可以藉由支付300生命值，選擇我方墓地的1張怪獸以外的卡回到牌組最下方。','回到牌堆','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96331676,'寶玉的祈禱','將我方的魔法與陷阱區域的1張「寶玉獸」卡片送去墓地可以發動。選擇對手場上的1張卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96334243,'忒修斯的魔棲物','協調×2','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96345184,'無窮之三幻魔-幻魔皇 拉比艾爾',unistr('此卡不能通常召喚，只能用「三幻魔」卡片的效果特殊召喚。這個卡名的①效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。從牌組將「無窮之三幻魔-幻魔皇 拉比艾爾」以外的1隻「三幻魔」怪獸加入手牌。那之後，選1張我方的手牌捨棄。\u000a②：我方、對手回合1次，將我方場上2隻其他的「三幻魔」怪獸解放可以發動。對手場上的怪獸全部破壞，此卡的攻擊力上升破壞的數量×1000。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96345188,'RR-模擬伯勞',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的回合的我方主要階段可以發動1次。我方場上的全部「RR-」怪獸的等級上升1。\u000a②：此卡被送去墓地的回合的我方主要階段，將墓地的此卡除外可以發動。從牌組將「RR-模擬伯勞」以外的1張「RR-」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96352326,'太陽的魔術師 埃達',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、反轉的場合可以發動。從手牌、牌組將「太陽的魔術師 埃達」以外的1隻守備力1500的魔法使族怪獸裡側守備表示特殊召喚。\u000a②：對手主要階段可以發動。選我方場上1隻裡側表示的魔法使族怪獸變成表側攻擊表示或表側守備表示。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96352712,'誇大化',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：怪獸之間進行戰鬥的傷害步驟開始時，可以從以下效果選擇1個發動。\u000a●那隻攻擊怪獸變成守備表示。\u000a●那隻攻擊對象怪獸回到手牌。\u000a●那些進行戰鬥的2隻怪獸破壞。'),'效果1','●攻擊怪獸變成守備表示','●攻擊對象怪獸回到手牌','●進行戰鬥的2隻怪獸破壞','','','','','','','','','','','','');
INSERT INTO texts VALUES(96355986,'神聖標槍','回復對手攻擊怪獸的攻擊力數值的生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96363153,'調律','①：從牌組將1隻「同步者」協調加入手牌。那之後，我方牌組最上方的卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96363154,'調律','①：從牌組將1隻「同步者」協調加入手牌。那之後，我方牌組最上方的卡送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96367119,'黑色高潔',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：魔法、陷阱卡發動時，去除我方場上的1個黑羽計數器可以發動。那個發動無效並破壞。\u000a②：我方場上有「黑羽龍」存在的場合可以發動。墓地的此卡在我方場上覆蓋。此效果覆蓋的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96378317,'鐵獸的邂逅',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上任意數量的連結狀態的獸族、獸戰士族、鳥獸族怪獸為對象可以發動。那些怪獸的攻擊力直到回合結束時上升700。\u000a②：我方場上的連結狀態的獸族、獸戰士族、鳥獸族怪獸被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96380700,'對講槍兵',unistr('等級2以下的電子界族怪獸1隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：解放此卡以外的我方場上1隻電子界族怪獸，以我方墓地1隻和那隻怪獸原卡名不同的「碼語者」怪獸為對象可以發動。那隻怪獸在此卡指向的我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96381979,'魁炎星王-宋虎',unistr('獸戰士族等級4怪獸×2\u000a①：此卡超量召喚成功時可以發動。從牌組將1張「炎舞」魔法、陷阱卡覆蓋。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。獸戰士族以外的場上的全部效果怪獸的效果直到對手回合結束時無效化。\u000a③：此卡從場上送去墓地時，將我方場上3張表側表示的「炎舞」魔法、陷阱卡送去墓地可以發動。從牌組將2隻等級4以下且攻擊力相同的獸戰士族怪獸守備表示特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96383838,'三骨地帶','①：以我方墓地3隻等級2以下的通常怪獸為對象可以發動。那些怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96384007,'機甲部隊防衛兵','①：此卡反轉的場合發動。從牌組將1隻「督戰官 柯賓頓」加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96385345,'薔薇的聖武士',unistr('「薔薇的聖武士」的②效果1回合只能使用1次。\u000a①：此卡戰鬥破壞對手怪獸送去墓地時，解放此卡可以發動。從手牌、牌組將1隻植物族怪獸守備表示特殊召喚。\u000a②：將此卡從手牌送去墓地可以發動。從牌組將1隻等級7以上的植物族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96399967,'機巧鳥-常世宇受賣長鳴',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻攻擊力和守備力數值相同的機械族怪獸解放可以發動。從牌組將1隻攻擊力和守備力數值相同且等級低於解放的怪獸的機械族怪獸特殊召喚。\u000a②：將墓地的此卡除外可以發動。從被裡側表示除外的我方的卡之中，選1隻攻擊力和守備力數值相同的機械族怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96402918,'冰靈山的龍祖 矛槍龍',unistr('水屬性協調+協調以外的怪獸1隻以上\u000a這個卡名的①效果1回合可以使用最多2次。\u000a①：對手將怪獸特殊召喚的場合可以發動（同一連鎖上最多1次）。從我方的手牌、牌組、額外牌組、墓地將1隻「冰結界」怪獸特殊召喚。那之後，可以將對手場上1隻攻擊表示怪獸變成守備表示。\u000a②：同步召喚的表側表示的此卡因對手從場上離開的場合可以發動。從額外牌組將1隻「冰結界」同步怪獸當作同步召喚作特殊召喚。'),'效果1','效果2','是否將1隻對手怪獸變成守備表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96404912,'無償交換','①：對手發動怪獸的效果時可以發動。那個發動無效並破壞。對手從牌組抽1張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96420087,'與闇之支配者的契約',unistr('「闇之支配者-佐克」的降臨所必需。\u000a①：從我方的手牌、場上解放怪獸直到等級合計為8以上為止，從手牌儀式召喚「闇之支配者-佐克」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96427353,'機甲忍者 水','對手怪獸的直接攻擊宣言時，我方墓地有此卡以外的「忍者」怪獸存在的場合，將墓地的此卡除外可以發動。選擇那1隻攻擊怪獸的攻擊無效。','攻擊無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96428622,'人工腦獨眼巨人','我方的手牌是0張的場合，此卡的攻擊力上升1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96433300,'溟界之虛',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手的主要階段，將我方場上1隻爬蟲類族效果怪獸解放，以對手墓地1隻怪獸為對象可以發動。那隻怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸在結束階段送去墓地。\u000a②：魔法與陷阱區域的表側表示的此卡被送去墓地的場合發動。爬蟲類族怪獸以外的我方場上的表側表示怪獸全部送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96434581,'聖像騎士的晨曲',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻「聖像騎士」怪獸為對象可以發動。這個回合，那隻「聖像騎士」怪獸不受自身以外的卡的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96457619,'超量遮罩','只要此卡在場上存在，雙方玩家不能將場上表側表示存在的持有超量素材的超量怪獸作為效果的對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96458440,'傳說的黑帶',unistr('只能給我方場上的「格鬥鼠 邱助」「僧侶鬥士」「僧侶首領」裝備。\u000a裝備怪獸戰鬥破壞對手怪獸送去墓地時，給予對手破壞的怪獸的守備力數值的傷害。'),'給予對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96462121,'超接地展開',unistr('①：我方場上的機械族超量怪獸不會成為對手的效果的對象。\u000a②：1回合1次，以我方場上1隻「無限起動」超量怪獸為對象可以發動。將1隻階級比那隻我方怪獸高2階的機械族超量怪獸重疊在對象怪獸上方，當作超量召喚從額外牌組特殊召喚。此效果的發動後，直到回合結束時我方除了機械族、地屬性怪獸以外不能特殊召喚。'),'升階','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96470883,'凜天使 薔薇女王',unistr('此卡可以解放1隻植物族怪獸以表側攻擊表示上級召喚。\u000a我方的準備階段，場上表側表示存在的攻擊力最低的1隻怪獸破壞。'),'解放1隻植物族怪獸召喚','攻擊力最低的怪獸破壞','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96471335,'幻想黑之魔導師',unistr('等級7怪獸×2\u000a此卡也能重疊在我方場上的階級6的魔法使族超量怪獸上方來超量召喚。「幻想黑之魔導師」的②效果1回合只能使用1次。\u000a①：1回合1次，去除此卡的1個超量素材可以發動。從手牌、牌組將1隻魔法使族通常怪獸特殊召喚。\u000a②：魔法使族通常怪獸的攻擊宣言時，以對手場上1張卡為對象可以發動。那張卡除外。'),'是否重疊在階級6的魔法使族超量怪獸上方超量召喚？','效果1','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96474800,'魔法偏轉器','這個回合，場上的裝備、場地、永續、速攻魔法卡的效果無效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96501677,'木天蓼貓',unistr('我方場上有此卡以外的獸族怪獸存在的場合，不能攻擊此卡。\u000a選擇對手場上1隻怪獸的守備力直到回合結束時變成0。這個效果1回合只能使用1次。'),'守備變化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96540807,'再世原初戰神 貝凌席特',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②③效果1回合各能使用1次。\u000a①：場上有原攻擊力或原守備力是2500的怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：我方、對手回合，將此卡解放，以對手場上的1隻怪獸為對象可以發動。那隻怪獸回到手牌。\u000a③：此卡被送去墓地的對手回合的結束階段可以發動。此卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96546575,'大要塞鯨魚',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：場上有「海」存在的場合可以發動。這個回合，我方的水屬性怪獸可以直接攻擊。\u000a②：對手戰鬥階段，以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸破壞。\u000a③：場上的此卡被戰鬥、效果破壞的場合可以發動。從我方的牌組、墓地選1隻戰士族、水屬性怪獸加入手牌或特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96553688,'鳳凰種子','將我方場上表側表示存在的此卡送去墓地可以發動。從手牌將1隻「鳳凰石蒜」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96561011,'真紅眼闇龍',unistr('此卡不能通常召喚。只能解放我方場上的1隻「真紅眼黑龍」來特殊召喚。\u000a此卡的攻擊力上升我方墓地的龍族怪獸數量×300。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96565487,'暴風雪戰士','①：此卡戰鬥破壞對手怪獸的場合發動。確認對手牌組最上方的卡，回到牌組最上方或最下方。','確認','放回牌組最上方','放回牌組最下方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96570609,'天帝 埃忒耳',unistr('此卡可以解放1隻上級召喚的怪獸來上級召喚。\u000a①：此卡上級召喚的場合可以發動。從手牌、牌組將2種「帝王」魔法、陷阱卡各1張送去墓地，從牌組將1隻攻擊力2400以上且守備力1000的怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段回到手牌。\u000a②：此卡在手牌存在的場合，對手主要階段，將我方墓地1張「帝王」魔法、陷阱卡除外可以發動（同一連鎖上最多1次）。進行此卡的上級召喚。'),'解放1隻怪獸上級召喚','從牌組特殊召喚','此卡上級召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96576187,'光道惡魔 魏絲',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌讓1張其他的「光道」卡片回到牌組最上方可以發動。此卡從手牌特殊召喚。那之後，從我方牌組上方將2張卡送去墓地。\u000a②：此卡從牌組送去墓地的場合，以「光道惡魔 魏絲」以外的我方墓地1隻「光道」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96592102,'RR-火刃焚燒獵鷹',unistr('鳥獸族等級4怪獸×2\u000a①：我方的生命值比對手少3000以上，此卡超量召喚成功的場合可以發動。此卡的攻擊力上升3000。\u000a②：此卡戰鬥破壞對手怪獸時，去除此卡的任意數量的超量素材可以發動。依照去除的超量素材數量，選對手場上的怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96594609,'炎王獸 麒麟',unistr('①：我方場上的表側表示的「炎王」怪獸被效果破壞的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡被破壞送去墓地的場合可以發動。從牌組將1隻炎屬性怪獸送去墓地。'),'特殊召喚','送去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96598015,'金滿之壺',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方不能進行靈擺召喚以外的特殊召喚。\u000a①：從我方的額外牌組（表側）、墓地讓3隻靈擺怪獸回到牌組洗牌。那之後，我方抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96606246,'娛樂夥伴 助手驢','①：此卡召喚成功時可以發動。從我方的手牌、墓地選1隻等級4以下的「娛樂夥伴」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96622984,'捕食植物 蒼蠅地獄',unistr('①：1回合1次，以對手場上1隻表側表示怪獸為對象可以發動。在那隻怪獸放置1個捕食計數器。已放置捕食計數器的等級2以上怪獸的等級變成1。\u000a②：此卡和等級在此卡的等級以下的怪獸進行戰鬥的傷害步驟開始時可以發動。那隻怪獸破壞。那之後，此卡的等級上升被破壞的那隻怪獸的原等級數值。'),'放置捕食計數器','破壞怪獸','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96631852,'鐵壁的布陣','選擇我方場上的1隻怪獸可以發動此卡。我方場上有2隻以上怪獸存在且全部都是守備表示的場合，選擇的怪獸的守備力上升700。選擇的怪獸從場上離開時，此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96633955,'相劍大公-承影',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：依照除外狀態的卡片數量×100，此卡的攻擊力、守備力上升且對手場上的怪獸的攻擊力、守備力下降那個數值。\u000a②：此卡被效果破壞的場合，可以將我方墓地1張卡除外作為代替。\u000a③：卡被除外的場合可以發動。對手的場上以及墓地的卡各1張除外。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96637156,'席取-六雙丸',unistr('等級6怪獸×2\u000a①：對手戰鬥階段開始時發動。擲1次骰子。從此卡所見的順時針方向將雙方的主要怪獸區域定為1～6，主要怪獸區域的此卡向擲出點數的區域移動。移動目標有怪獸存在的場合，那隻怪獸重疊在此卡下方作為超量素材（如果那是持有超量素材的怪獸，那些卡也全部重疊）。這個超量素材超過6時，我方獲得決鬥勝利。不能移動的場合，或移動目標的怪獸不能作為超量素材的場合，此卡送去墓地。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96643568,'氣象精靈','操縱雨的精靈。召喚颱風吹飛各種東西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96653775,'大植然南瓜','對手場上有怪獸存在的場合此卡召喚成功時，可以從手牌將1隻「大植然」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96661780,'守護者的力量',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的生命值低於對手的場合，以我方場上1隻原卡名包含「門之守護者」的怪獸為對象可以發動。對手的生命值變成一半。那之後，對象怪獸的攻擊力上升對手的生命值數值。\u000a②：將墓地的此卡除外可以發動。我方的牌組、除外狀態的「雷魔神-桑卡」「風魔神-胡卡」「水魔神-斯卡」其中任何1隻加入手牌。'),'對手的生命值減半','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96676583,'碼麗絲＜兵＞柴郡貓',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方主要階段可以發動。從手牌選1張「碼麗絲」卡片除外。那之後，我方可以抽2張卡。\u000a②：指向此卡的「碼麗絲」連結怪獸戰鬥破壞的怪獸不去墓地而是除外。\u000a③：此卡被除外的場合，支付300生命值可以發動。此卡特殊召喚。這個回合，我方除了連結怪獸以外不能從額外牌組特殊召喚。'),'效果1','','效果3','是否抽2張卡？','','','','','','','','','','','','');
INSERT INTO texts VALUES(96677818,'魔導書整理','從我方牌組上方翻開3張卡，以喜歡的順序回到牌組上方。對手不能確認那些卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96682430,'水精鱗-邃淵希德','此卡被送去墓地的場合，可以從手牌將「水精鱗-邃淵希德」以外的1隻「水精鱗」怪獸特殊召喚。「水精鱗-邃淵希德」的效果1回合只能使用1次。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96687733,'神殿的守護神',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方的手牌、場上的怪獸作為融合素材，將1隻地屬性融合怪獸融合召喚。記載「王家的神殿」的卡名的我方場上的怪獸作為融合素材的場合，也能將對手場上的表側表示怪獸作為融合素材。\u000a②：我方場上有「王家的神殿」存在的場合，將墓地的此卡除外可以發動。從牌組將1張「神之怒」加入手牌。'),'','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96693371,'V.HERO 倍增小子',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方因戰鬥、效果受到傷害的場合可以發動。墓地的此卡當作永續陷阱卡在我方的魔法與陷阱區域表側表示放置。\u000a②：此卡當作永續陷阱卡的場合，雙方的主要階段，將我方場上1隻「HERO」怪獸解放可以發動。此卡特殊召喚。\u000a③：此卡從魔法與陷阱區域特殊召喚成功的場合可以發動。場上1隻怪獸的攻擊力上升800。'),'當作永續陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96699830,'來自天龍座的降誕',unistr('此卡發動的整回合中，我方不能用此卡的效果以外將怪獸特殊召喚。\u000a①：從我方墓地和我方場上的表側表示怪獸之中將機械族、光屬性怪獸全部除外可以發動。從手牌將1隻等級6以上的機械族、光屬性怪獸無視召喚條件特殊召喚。此效果特殊召喚的怪獸的攻擊力、守備力變成為了發動此卡而除外的怪獸數量×500，不受自身以外的卡的效果影響。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96700602,'波動障壁','對手怪獸的攻擊宣言時，將我方場上的1隻同步怪獸解放可以發動。對手場上的攻擊表示怪獸全部變成守備表示。那之後，給予對手攻擊宣言的怪獸的守備力數值的傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96704018,'紋章獸 伯納斯獵鷹','此卡召喚、反轉召喚、特殊召喚成功時可以發動。我方場上的全部等級5以上的怪獸的等級變成4。','等級變成4','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96704974,'詭樂陷阱',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：捨棄2張手牌，以我方墓地1張陷阱卡為對象可以發動。那張卡在我方場上覆蓋。此效果覆蓋的卡在覆蓋的回合也能發動。'),'適用「詭樂陷阱」的效果來發動','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96708940,'疾行機人 彈珠機器',unistr('【靈擺效果】\u000a①：1回合1次，我方的守備表示怪獸被選擇作為攻擊對象時可以發動。那隻怪獸變成表側攻擊表示。這個回合，那隻怪獸不會被戰鬥破壞。\u000a【怪獸效果】\u000a這個卡名的怪獸效果1回合只能使用1次。\u000a①：此卡召喚成功時可以發動。從牌組將1隻「疾行機人」怪獸加入手牌。此效果的發動後，直到回合結束時我方除了風屬性怪獸以外不能特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96729612,'儀式的準備','①：從牌組將1隻等級7以下的儀式怪獸加入手牌。那之後，可以從我方墓地將1張儀式魔法卡加入手牌。','是否從墓地選1張儀式魔法卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96733134,'霸王眷龍 異色眼',unistr('【靈擺效果】\u000a①：將我方場上1隻「霸王眷龍」怪獸解放可以發動。此卡破壞，從牌組將1隻攻擊力1500以下的靈擺怪獸加入手牌。\u000a【怪獸效果】\u000a①：將我方場上2隻「霸王眷龍」怪獸解放可以發動。此卡從手牌特殊召喚。\u000a②：我方的靈擺怪獸和對手怪獸進行戰鬥的場合，給予對手的戰鬥傷害變成2倍。\u000a③：我方、對手的戰鬥階段，將此卡解放可以發動。從我方的額外牌組（表側）將「霸王眷龍 異色眼」以外的「霸王眷龍」靈擺怪獸或「霸王門」靈擺怪獸合計最多2隻守備表示特殊召喚。'),'靈擺效果1','效果1','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96746083,'真龍皇 阿耆尼馬茲達V',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合可以發動。此卡以外的我方的手牌、場上（表側表示）的包含炎屬性怪獸的2隻怪獸破壞，此卡從手牌特殊召喚，將2隻炎屬性怪獸破壞的場合，可以從對手的場上、墓地將1隻怪獸除外。\u000a②：此卡被效果破壞的場合可以發動。從我方墓地將1隻炎屬性以外的幻龍族怪獸加入手牌。'),'是否從對手的場上、墓地選1隻怪獸除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96765646,'回憶的鞦韆','①：以我方墓地1隻通常怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸在這個回合的結束階段破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96782886,'心靈大師',unistr('這個卡名的效果1回合只能使用1次。\u000a①：支付800生命值，將我方場上1隻超能族怪獸解放可以發動。從牌組將1隻等級4以下的超能族怪獸攻擊表示特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96789758,'芬芳法師-茉莉',unistr('①：只要我方的生命值高於對手，且此卡在怪獸區域存在，我方在通常召喚之外只有1次，在我方主要階段可以召喚「芬芳法師-茉莉」以外的1隻植物族怪獸。\u000a②：1回合1次，我方的生命值回復的場合發動。從牌組抽1張卡。'),'召喚（芬芳法師-茉莉）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96795312,'武之賢者-阿卡絲',unistr('這個卡名在規則上也當作「閃刀」卡片。這個卡名的①②③效果1回合各能使用1次。\u000a①：從手牌捨棄1張魔法卡可以發動。此卡從手牌特殊召喚。\u000a②：我方場上的連結怪獸被戰鬥、效果破壞的場合，可以將我方墓地1張魔法卡除外作為代替。\u000a③：此卡被戰鬥、效果破壞送去墓地的場合，以被除外的1張我方的「閃刀」魔法卡為對象可以發動。那張卡加入手牌。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96802306,'點火騎士 點五零',unistr('【靈擺效果】\u000a①：另一邊的我方的靈擺區域有「點火騎士」卡片存在的場合可以發動。我方的靈擺區域的卡全部破壞，從我方的牌組、墓地選1隻戰士族、炎屬性怪獸加入手牌。\u000a【怪獸敘述】\u000a使精力太旺盛的點火騎士們團結起來的特攻隊長。老是被血氣方剛立刻腦子點火的部下們傷透腦筋。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96823189,'驕傲與靈魂之龍',unistr('此卡不能通常召喚。只能在對手墓地有25張以上卡存在的場合特殊召喚。\u000a①：只要我方墓地有25張以上卡存在，此卡的攻擊力、守備力上升2500。'),'此卡特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96851799,'刺焰球','一團熾熱的火球。會用其身體與對手正面相撞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96857854,'鑽石冰塵妖',unistr('①：場上的卡被戰鬥、效果破壞時可以發動。從牌組選那些破壞的卡數量的「塵妖」怪獸在我方、對手場上特殊召喚。\u000a②：此卡在墓地存在的場合只有1次，將我方墓地1隻「塵妖」怪獸除外可以發動。此卡變成通常怪獸（惡魔族、闇、等級1、攻0/守1000）在對手的怪獸區域守備表示特殊召喚（不當作陷阱卡）。此效果特殊召喚的此卡不能解放，也不能作為融合、同步、超量召喚的素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96864105,'CNo.73 激瀧瀑神 邃淵潮湧',unistr('等級6怪獸×3\u000a①：我方怪獸和對手怪獸進行戰鬥的傷害計算時1次，去除此卡的1個超量素材可以發動。那隻我方怪獸的攻擊力只在那次傷害計算時上升那隻對手怪獸的攻擊力數值。\u000a②：此卡有「No.73 激瀧神 邃淵波濤」作為超量素材的場合，得到以下效果。\u000a●此卡不會被效果破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96864811,'禁忌的聖衣','①：以場上1隻表側表示怪獸為對象可以發動。直到回合結束時，那隻怪獸攻擊力下降600，不會被效果破壞，雙方不能將那隻怪獸作為效果的對象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96872283,'進化護法 騎士',unistr('①：只要此卡在場上、墓地存在，此卡當作通常怪獸。\u000a②：可以將場上的當作通常怪獸的此卡作為通常召喚再次召喚。那個場合此卡變成當作效果怪獸並得到以下效果。\u000a●將我方場上1張表側表示的裝備卡送去墓地，以對手場上1張卡為對象可以發動。那張對手的卡破壞。'),'破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96875080,'大氣層外射擊','將我方場上的1隻「外星人」怪獸送去墓地可以發動。選擇場上的1張魔法、陷阱卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96890582,'秒殺的暗殺者','此卡的攻擊力、守備力下降我方的手牌數量×400。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96891787,'教導的鐵鎚 特奧',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：從額外牌組特殊召喚的怪獸在場上存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡不會被從額外牌組特殊召喚的怪獸戰鬥破壞。\u000a③：以從額外牌組特殊召喚的場上1隻表側表示怪獸為對象可以發動。直到回合結束時，此卡的攻擊力上升600，對象怪獸的攻擊力下降600。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96897184,'古生代化石騎士 骷髏國王',unistr('岩石族怪獸+等級7以上的怪獸\u000a此卡只能用「化石融合-化石結合」的效果從額外牌組特殊召喚。這個卡名的③效果1回合只能使用1次。\u000a①：此卡在1次戰鬥階段中可以攻擊2次。\u000a②：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a③：對手回合，以對手墓地1隻怪獸為對象可以發動。選1張我方的手牌捨棄，對象怪獸在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96907086,'地縛旋風','我方場上有「地縛神」怪獸存在的場合可以發動。對手場上的魔法、陷阱卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96914272,'虛榮的大猿',unistr('此卡不能通常召喚。從手牌將1隻獸族怪獸送去墓地可以特殊召喚。\u000a這個方法特殊召喚成功時，可以依照送去墓地的那隻獸族怪獸的等級，從以下效果選擇1個發動。\u000a●此卡的等級上升那個等級數值。\u000a●此卡的等級下降那個等級數值。'),'改變等級','●等級上升','●等級下降','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96915510,'魔神儀的創造主-創造祭台',unistr('藉由「魔神儀的祝誕」降臨。這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手的主要階段，向對手展示手牌的此卡可以發動。選1張手牌捨棄，那之後，直到等級合計為10為止，選我方墓地的「魔神儀」怪獸特殊召喚。此效果特殊召喚的怪獸在結束階段回到持有者的牌組。\u000a②：只要此卡在怪獸區域存在，儀式怪獸以外的我方場上的「魔神儀」怪獸的攻擊力上升2000，效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96930127,'鎖鏈狗',unistr('將此卡作為同步素材的場合，除了獸族怪獸的同步召喚以外不能使用。\u000a此卡在墓地存在的場合可以發動。此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。此效果在我方場上的獸族怪獸是2隻的場合可以發動和處理。\u000a[按照判例修正]'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96938777,'神機王 烏爾',unistr('①：此卡可以向全部對手怪獸各攻擊1次。\u000a②：此卡進行戰鬥的場合，對手受到的戰鬥傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96938986,'共振蟲',unistr('①：此卡從場上送去墓地的場合可以發動。從牌組將1隻等級5以上的昆蟲族怪獸加入手牌。\u000a②：此卡被除外的場合可以發動。從牌組將「共振蟲」以外的1隻昆蟲族怪獸送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96945958,'疾行機人 渦輪歌牌',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有風屬性怪獸存在的場合可以發動。此卡從手牌特殊召喚。此效果的發動後，直到回合結束時我方不能發動風屬性以外的怪獸的效果。\u000a②：從我方墓地將此卡和1隻「疾行機人」怪獸除外可以發動。我方場上的全部風屬性怪獸的攻擊力直到回合結束時上升800。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96947648,'打撈','①：以我方墓地2隻攻擊力1500以下的水屬性怪獸為對象可以發動。那些水屬性怪獸加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96965364,'孵化','①：解放我方場上1隻怪獸可以發動。從牌組將1隻等級比解放的怪獸高1級的昆蟲族怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96967123,'大砲達摩','在不倒翁裡裝著大砲，瞄準後絕不會打歪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96981563,'吃火焰的大龜','擁有赤色甲殼的烏龜，據說曾吞下了火焰。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97000273,'廢鐵金剛',unistr('此卡召喚成功時，此卡破壞。\u000a此卡被「廢鐵」卡片的效果破壞送去墓地的場合，可以選擇「廢鐵金剛」以外的我方墓地1隻「廢鐵」怪獸加入手牌。'),'此卡破壞','檢索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97001138,'黑暗上級',unistr('「黑暗上級」在1回合只能發動1張。\u000a①：我方、對手的主要階段以及戰鬥階段，以我方墓地的1隻攻擊力2400以上且守備力1000的怪獸為對象可以發動。那隻怪獸加入手牌。那之後，可以從手牌將1隻攻擊力2400以上且守備力1000的怪獸表側攻擊表示上級召喚。'),'是否從手牌上級召喚怪獸？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97007933,'高速疾行機人 魔劍玉',unistr('協調+協調以外的怪獸1隻以上\u000a「高速疾行機人 魔劍玉」的②③效果1回合各能使用1次。\u000a①：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：將我方墓地的1隻機械族怪獸除外可以發動。給予對手500傷害。\u000a③：此卡在墓地存在，我方場上沒有卡存在的場合，我方主要階段可以發動。此卡從墓地特殊召喚。此效果發動的整回合中，我方不能通常召喚。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97017120,'巨大老鼠','①：此卡被戰鬥破壞送去墓地時可以發動。從牌組將1隻攻擊力1500以下的地屬性怪獸攻擊表示特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97021916,'黑暗共鳴體','①：此卡1回合只有1次不會被戰鬥破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97023549,'冰刀滑雪者','冰上的舞姬是華麗的戰士。以必殺技阿克塞爾切裂華麗地將敵人怪獸切裂。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97024987,'點火騎士 德拉古諾夫',unistr('【靈擺效果】\u000a①：另一邊的我方的靈擺區域有「點火騎士」卡片存在的場合可以發動。我方的靈擺區域的卡全部破壞，從我方的牌組、墓地選1隻戰士族、炎屬性怪獸加入手牌。\u000a【怪獸敘述】\u000a直性子討厭邪門歪道的點火騎士老手戰士。也許是那個性格的緣故，近來他好像對手上拿的武器抱有疑問。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97036149,'天威龍-心輪',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上沒有效果怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：效果怪獸以外的我方的表側表示怪獸在和對手的表側表示怪獸進行戰鬥的攻擊宣言時，將手牌、墓地的此卡除外可以發動。那隻對手怪獸的攻擊力直到回合結束時下降1500。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97045737,'聖主王的粉碎',unistr('這個卡名的卡在1回合只能發動1張。對手場上有卡存在的場合，此卡也能從手牌發動。\u000a①：包含從牌組將卡加入手牌效果的魔法、陷阱、怪獸的效果發動時可以發動。那個效果無效。我方墓地有陷阱卡存在的場合，再將那張無效的卡破壞。此卡從手牌發動的場合，發動後，這次決鬥中我方不能發動闇、水、炎屬性怪獸的效果。\u000a\u000a※聖王的粉碎'),'N/A','適用「聖主王的粉碎」的效果來發動','「聖主王的粉碎」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97045738,'聖主王的粉碎',unistr('這個卡名的卡在1回合只能發動1張。對手場上有卡存在的場合，此卡也能從手牌發動。\u000a①：包含從牌組將卡加入手牌效果的魔法、陷阱、怪獸的效果發動時可以發動。那個效果無效。我方墓地有陷阱卡存在的場合，再將那張無效的卡破壞。此卡從手牌發動的場合，發動後，這次決鬥中我方不能發動闇、水、炎屬性怪獸的效果。\u000a\u000a※聖王的粉碎'),'N/A','適用「聖主王的粉碎」的效果來發動','「聖主王的粉碎」的效果1適用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97051536,'獄火機 邪惡',unistr('「獄火機」怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡融合召喚的場合，從我方墓地將1隻「獄火機」怪獸除外可以發動。從牌組將和那隻怪獸的等級相同張數的「獄火機」怪獸送去墓地（同名卡最多1張）。\u000a②：此卡被送去墓地的場合或被除外的場合可以發動。從牌組將1張「煉獄」魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97053215,'G石人 頑固立石',unistr('地屬性怪獸2隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡從墓地特殊召喚成功的場合，以我方墓地1隻可以通常召喚的地屬性怪獸為對象可以發動。那隻怪獸加入手牌或特殊召喚。此效果特殊召喚的怪獸的效果無效化，從場上離開的場合被除外。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97064649,'暗躍的德魯依 智者','此卡從場上送去墓地的場合，可以選擇我方墓地1張永續魔法卡在我方場上覆蓋。此效果覆蓋的卡在這個回合不能發動。「暗躍的德魯依 智者」的效果1回合只能使用1次。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97077563,'活死人的呼聲','①：以我方墓地1隻怪獸為對象可以發動此卡。那隻怪獸攻擊表示特殊召喚。此卡從場上離開時那隻怪獸破壞。那隻怪獸被破壞時此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97077564,'活死人的呼聲','①：以我方墓地1隻怪獸為對象可以發動此卡。那隻怪獸攻擊表示特殊召喚。此卡從場上離開時那隻怪獸破壞。那隻怪獸被破壞時此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97091969,'武裝龍的震霆',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：可以選擇我方場上1隻「武裝龍」怪獸為對象，從以下效果選擇1個發動。\u000a●那隻怪獸的攻擊力上升那隻怪獸的等級×100。\u000a●從我方墓地選1隻等級在那隻怪獸的等級以下的「武裝龍」怪獸加入手牌。\u000a②：我方場上的「武裝龍」怪獸被效果破壞的場合，可以將此卡送去墓地作為代替。'),'●攻擊力上升','●墓地的怪獸加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97093037,'創世者的化身','藉由解放此卡，從手牌將1隻「創世神」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97112505,'先史遺產 墨瓦臘地球儀',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡解放可以發動。從牌組將「先史遺產 墨瓦臘地球儀」以外的1隻「先史遺產」怪獸特殊召喚。\u000a②：此卡在墓地存在的場合，從我方墓地將「先史遺產 墨瓦臘地球儀」以外的1張「先史遺產」卡片除外可以發動。此卡加入手牌。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97120394,'封魔之箭',unistr('應對此卡的發動，不能發動魔法、陷阱、怪獸的效果。\u000a①：我方或對手的戰鬥階段開始時可以發動。此卡的發動後，直到回合結束時，雙方不能發動魔法、陷阱卡的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97127906,'外星人士兵','謎之生命體外星人的上級戰士。雖擁有較高的攻擊力，卻沒有掌握任何特殊能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97148796,'龍輝巧-右樞α',unistr('此卡不能通常召喚，只能用「龍輝巧」卡片的效果特殊召喚。這個卡名的效果1回合只能使用1次。\u000a①：將此卡以外的我方的手牌、場上1隻「龍輝巧」怪獸或儀式怪獸解放可以發動（此效果發動的整回合中，我方除了不能通常召喚的怪獸以外不能特殊召喚）。此卡從手牌、墓地守備表示特殊召喚。那之後，可以從牌組將1隻儀式怪獸加入手牌。'),'效果1','是否從牌組把1隻儀式怪獸加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97151365,'星之門',unistr('對手怪獸進行戰鬥的場合，那次傷害步驟結束時給此卡放置1個門計數器。\u000a我方主要階段，藉由將此卡送去墓地，從手牌將1隻等級在此卡放置的門計數器的數量以下的怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97165977,'月光舞豹姬',unistr('「月光舞貓姬」+「月光」怪獸\u000a此卡只能用以上述卡為融合素材的融合召喚從額外牌組特殊召喚。\u000a①：此卡不會被對手的效果破壞。\u000a②：1回合1次，我方主要階段1可以發動。這個回合，對手怪獸各有1次不會被戰鬥破壞，此卡可以向全部對手怪獸各攻擊2次。\u000a③：此卡戰鬥破壞對手怪獸時發動。此卡的攻擊力直到戰鬥階段結束時上升200。'),'多次攻擊','攻擊力上升200','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97168905,'奇蹟的軌跡','選擇我方場上表側攻擊表示存在的1隻怪獸可以發動。對手從牌組抽1張卡。直到這個回合結束時，那隻怪獸的攻擊力上升1000，在1次戰鬥階段中可以向怪獸攻擊2次。那隻怪獸進行戰鬥的場合，對手玩家受到的戰鬥傷害變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97169186,'地碎','①：對手場上的守備力最高的1隻怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97170107,'光輝精靈',unistr('等級2怪獸×2\u000a對手將怪獸召喚、特殊召喚成功時，去除此卡的1個超量素材可以發動。那些怪獸的攻擊力下降500。'),'攻擊力下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97173708,'衍生物誕生祭','解放我方場上的2隻以上等級相同的衍生物可以發動。最多到解放的衍生物數量，從我方墓地選擇和此卡發動時解放的衍生物等級相同的怪獸特殊召喚。此效果特殊召喚的怪獸的效果無效化，在結束階段時破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97182396,'驚奇遊樂設施 征服海盜船',unistr('①：以1隻我方場上的「驚樂園」怪獸或對手場上的表側表示怪獸為對象可以發動此卡。此卡當作裝備卡給那隻怪獸裝備。\u000a②：可以依照裝備怪獸的控制者，發動以下效果。\u000a●我方：1回合1次，對手怪獸的攻擊宣言時可以發動。那次攻擊無效，直到戰鬥階段結束時裝備怪獸的控制權變更。\u000a●對手：裝備怪獸發動效果時可以發動。裝備怪獸回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97204936,'大地的騎士 蓋亞騎士','協調+協調以外的怪獸1隻以上','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97211663,'影靈衣的返魂術',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：解放我方的手牌、場上的怪獸，直到等級合計和儀式召喚的怪獸相同為止，從我方的手牌、墓地儀式召喚1隻「影靈衣」儀式怪獸。\u000a②：我方場上沒有怪獸存在的場合，從我方墓地將1隻「影靈衣」怪獸和此卡除外可以發動。從牌組將1張「影靈衣」魔法卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97219708,'RR-殘存林鴞',unistr('「RR-殘存林鴞」的②效果1回合只能使用1次。\u000a①：我方的「RR-」怪獸進行戰鬥的傷害計算時可以發動。此卡從手牌特殊召喚。那之後，我方回復我方的場上、墓地的魔法、陷阱卡數量×100生命值。\u000a②：將此卡解放可以發動。從額外牌組將1隻「RR-」超量怪獸守備表示特殊召喚。此效果特殊召喚的怪獸的效果無效化，在結束階段回到額外牌組。這個回合對手受到的戰鬥傷害變成0。'),'從手牌特殊召喚','從額外牌組特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97223101,'BBS',unistr('①：每次「BBS」以外的卡的效果發動可以發動。給此卡放置1個訪客計數器（最多10個）。\u000a②：我方場上的怪獸的攻擊力上升此卡的訪客計數器的數量×100。\u000a③：此卡被放置訪客計數器，使得那些訪客計數器的數量變成10的場合可以發動。此卡回到手牌，從牌組將1張持有將自身作為怪獸特殊召喚效果的永續陷阱卡在我方場上覆蓋。此效果覆蓋的卡在覆蓋的回合也能發動。'),'效果1','效果3','適用「BBS」的效果3發動','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97227123,'決鬥者回歸',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：場上或我方、對手的墓地有超量怪獸存在的場合可以發動。從我方的牌組、墓地將1張裝備魔法卡加入手牌。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97232518,'深淵的電擊魟',unistr('①：此卡發動後變成效果怪獸（雷族、光、等級5、攻1900/守0）在怪獸區域特殊召喚。此卡也當作陷阱卡。\u000a②：此卡的效果特殊召喚的此卡不會被戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97234686,'劍鬥交替','我方場上有「劍鬥獸」怪獸特殊召喚時可以發動。對手選1張手牌捨棄。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97240270,'瘋狂龍蝦','作為被全世界的美食家怪獸們所喜愛的高級食材而聞名。可怕的味道據說很刺激。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97240499,'渾然的鬥牛詩-奧菲布爾',unistr('此卡不能通常召喚。只能從我方的手牌、墓地將此卡以外的光屬性怪獸和闇屬性怪獸各2隻除外來特殊召喚。\u000a①：這個方法特殊召喚的此卡的攻擊力上升從手牌除外的怪獸數量×1000，在1次戰鬥階段中可以向怪獸攻擊多次，次數上限為從墓地除外的怪獸數量。\u000a②：此卡戰鬥破壞對手怪獸的傷害計算後可以發動。那隻對手怪獸除外。'),'條件特殊召喚','戰鬥破壞的怪獸除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97254001,'夏',unistr('①：1回合1次，可以發動。依照沒有使用的對手的主要怪獸區域的數量，給此卡放置四季計數器。\u000a②：1回合1次，我方怪獸的攻擊宣言時可以發動。給予對手此卡的四季計數器的數量以及我方墓地的「春」的數量×400傷害。\u000a③：對手結束階段可以發動。從我方的手牌、牌組將可以放置四季計數器的1張場地魔法卡在我方場上表側表示放置（此卡的四季計數器轉移到那張卡）。那張卡的效果在這個回合不能發動。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97262307,'蕾禍之姬邪眼',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。從手牌將1隻昆蟲族、植物族、爬蟲類族怪獸特殊召喚。\u000a②：此卡從手牌、墓地被除外的場合可以發動。這個回合的結束階段，我方依照我方場上的昆蟲族、植物族、爬蟲類族怪獸的種族種類的數量抽牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97268402,'效果分隔士','①：對手主要階段，將此卡從手牌送去墓地，以對手場上1隻效果怪獸為對象可以發動。那隻對手怪獸的效果直到回合結束時無效。','效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97268403,'效果分隔士','①：對手主要階段，將此卡從手牌送去墓地，以對手場上1隻效果怪獸為對象可以發動。那隻對手怪獸的效果直到回合結束時無效。','效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97273514,'甲蟲裝機 皮可蛾',unistr('昆蟲族怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚成功的場合，捨棄1張手牌，以此卡以外的我方場上1隻昆蟲族怪獸為對象可以發動。從牌組選1隻昆蟲族怪獸當作攻擊力、守備力上升500的裝備卡給對象怪獸裝備。\u000a②：以我方墓地3隻昆蟲族怪獸為對象可以發動。那些怪獸回到牌組洗牌。那之後，我方從牌組抽1張卡。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97300502,'召喚獸 光體',unistr('「召喚師 阿萊斯特」+融合怪獸\u000a這個卡名的①效果1回合只能使用1次。\u000a①：此卡特殊召喚成功的場合，或對手場上有怪獸特殊召喚的場合，以對手場上1隻怪獸為對象可以發動。那隻怪獸破壞。\u000a②：1回合1次，從我方墓地將1隻融合怪獸除外可以發動。此卡的攻擊力直到對手回合結束時上升除外的怪獸的攻擊力數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97316367,'無限起動 削岩掘進機',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：解放我方場上1隻機械族、地屬性怪獸可以發動。此卡從手牌守備表示特殊召喚。\u000a②：將墓地的此卡除外，以我方墓地5隻機械族、地屬性怪獸為對象可以發動。那些怪獸回到牌組洗牌。那之後，我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97317530,'森之聖獸 月耳草兔','①：此卡用獸族怪獸的效果特殊召喚的場合，以場上1張卡為對象可以發動。那張卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97342942,'靈魂砲擊','雙方的結束階段發動。回合玩家選自身場上1隻表側表示怪獸，解放那隻怪獸，給予回合玩家所見的對手相當於解放的怪獸的原攻擊力一半的傷害。','解放並傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97345699,'宵星的閃光',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：對手場上的怪獸數量比我方場上的怪獸多2隻以上的場合可以發動。對手可以將自身場上任意數量的怪獸送去墓地。我方依照對手場上的怪獸數量適用以下效果。\u000a●0隻：我方的生命值變成一半。\u000a●1隻：對手回復2000生命值。\u000a●2隻：對手的手牌全部直到結束階段表側除外。\u000a●3隻以上：這個回合，對手不能發動怪獸的效果。'),'N/A','是否將自身場上的怪獸送去墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97360116,'惡的無名劍士','用敏捷的動作產生真空、切碎對手的戰士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97362768,'閃光槍',unistr('只能給「E.HERO 閃光人」裝備。\u000a我方主要階段時，可以選擇1隻表側表示怪獸的表示形式變更。此效果使用3次後，此卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97383507,'暗騎士@伊格尼斯者',unistr('卡名不同的怪獸3隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡指向的區域有怪獸特殊召喚的場合可以發動（傷害步驟也能發動）。從我方墓地將等級4以下的「@伊格尼斯者」怪獸盡可能在此卡指向的我方場上效果無效特殊召喚。\u000a②：此卡戰鬥破壞對手怪獸時可以發動。從我方墓地選1隻電子界族怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97385276,'等級戰士',unistr('場上沒有怪獸存在的場合，此卡可以當作等級2怪獸從手牌召喚。\u000a對手場上有怪獸存在，我方場上沒有怪獸存在的場合，此卡可以當作等級4怪獸從手牌特殊召喚。'),'召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97396380,'火舞太刀','①：此卡被破壞送去墓地的場合，以對手場上1隻表側表示怪獸為對象發動。那隻對手的表側表示怪獸破壞，給予對手500傷害。','破壞並傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97403510,'No.92 偽骸神龍 心地心龍',unistr('等級9怪獸×3\u000a①：此卡不會被戰鬥破壞，此卡的戰鬥產生給我方的戰鬥傷害由對手代為承受。\u000a②：對手結束階段，去除此卡的1個超量素材可以發動。這個回合召喚、特殊召喚、覆蓋的對手場上的卡全部除外。\u000a③：持有超量素材的此卡被破壞送去墓地的場合可以發動。此卡特殊召喚。\u000a④：此卡用自身的效果特殊召喚的場合發動。此卡的攻擊力上升被除外的卡片數量×1000。'),'效果2','效果3','效果4','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97417863,'DDDD超次元統皇 零之悖論',unistr('【靈擺效果】\u000a這個卡名的靈擺效果1回合只能使用1次。\u000a①：以對手的靈擺區域1張卡為對象可以發動。此卡特殊召喚，對象卡片在我方的靈擺區域放置。此效果放置的卡在下個回合的結束階段破壞。\u000a【怪獸效果】\u000a此卡不能通常召喚，只能用此卡的效果特殊召喚。\u000a①：我方將怪獸靈擺召喚時，如果我方的靈擺區域的靈擺刻度的總和超過靈擺召喚的怪獸的等級的總和可以發動。此卡從手牌特殊召喚，場上的其他卡全部破壞。那之後，可以將此卡在我方的靈擺區域放置。\u000a②：1回合1次，我方場上的其他的表側表示的「DDD」怪獸因魔法卡的效果從場上離開的場合發動。此卡的攻擊力變成6000。'),'效果1','是否將此卡在靈擺區域放置？','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97433739,'給未來的思念',unistr('此卡發動的整回合中，我方不能進行超量召喚以外的特殊召喚。\u000a以我方墓地的3隻等級不同的怪獸可以發動。作為對象的3隻怪獸特殊召喚。此效果特殊召喚的怪獸的攻擊力變成0，效果無效化。那之後，我方沒有進行超量召喚的場合，這個回合的結束階段時，我方失去4000生命值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97434754,'神藝學徒 莉特拉',unistr('這個卡名的①③效果1回合各能使用1次。\u000a①：我方場上有「神藝」卡片存在的場合可以發動。此卡從手牌特殊召喚。那之後可以從我方墓地將1張「神藝」卡片加入手牌。\u000a②：此卡的戰鬥產生給我方的戰鬥傷害變成0。\u000a③：對手主要階段可以發動。從我方的手牌、墓地將「神藝學徒 莉特拉」以外的1隻「神藝」怪獸特殊召喚。那之後，場上的此卡回到手牌。'),'效果1','效果2','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97439308,'混沌貪婪','被除外的我方的卡有4張以上，我方墓地沒有卡存在的場合可以發動。我方從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97439806,'魔轟神 庫夏諾','①：此卡在墓地存在的場合，從手牌將「魔轟神 庫夏諾」以外的1隻「魔轟神」怪獸捨棄到墓地可以發動。此卡加入手牌。','此卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97452817,'大秘儀之力XVIII-月亮',unistr('此卡召喚、反轉召喚、特殊召喚成功時，投擲1次硬幣並得到以下效果。\u000a●正：我方的準備階段時，可以在我方場上將1隻「月亮衍生物」（天使族、光、等級1、攻/守0）特殊召喚。\u000a●反：我方的結束階段時，選擇我方場上的1隻怪獸，那隻怪獸的控制權轉移給對手。'),'投擲硬幣','●正','●反','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97452818,'月亮衍生物','由「大秘儀之力XVIII-月亮」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97453744,'英豪勝利者 光輝之劍',unistr('戰士族等級4怪獸×2\u000a這個卡名的②③效果1回合各能使用1次。\u000a①：對手不能選擇其他怪獸作為攻擊對象。\u000a②：支付生命值直到變成500生命值可以發動。這個回合的戰鬥階段開始時，選我方場上1隻怪獸的攻擊力變成2倍。\u000a③：對手怪獸進行戰鬥的攻擊宣言時，去除此卡的1個超量素材，以對手場上1隻表側表示怪獸為對象可以發動。此卡的攻擊力直到回合結束時上升那隻怪獸的攻擊力數值。'),'效果2','效果3','請選擇要將攻擊力變成2倍的怪獸','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97462632,'栗球獸衛',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：我方、對手回合，可以將此卡從手牌捨棄，從以下效果選擇1個發動。\u000a●這個回合，我方受到的戰鬥、效果傷害只有1次變成0。\u000a●從牌組將1張記載「光與闇的儀式」的卡名的速攻魔法、陷阱卡在我方場上覆蓋。此效果覆蓋的卡在覆蓋的回合也能發動。\u000a②：等級8儀式怪獸1隻儀式召喚的場合，可以使用1張此卡作為儀式召喚所需的解放。'),'效果1','●傷害變成0','●覆蓋魔法、陷阱卡','適用「栗球獸衛」的效果來發動','','','','','','','','','','','','');
INSERT INTO texts VALUES(97466438,'橫條邪斑馬',unistr('【靈擺效果】\u000a①：此卡發動的回合的我方主要階段，指定1格沒有使用的主要怪獸區域或魔法與陷阱區域可以發動。此卡在靈擺區域存在期間，指定的區域不能使用。\u000a【怪獸效果】\u000a①：此卡召喚、特殊召喚成功的場合，指定1格沒有使用的主要怪獸區域或魔法與陷阱區域可以發動。這隻怪獸表側表示存在期間，指定的區域不能使用。'),'怪獸效果','靈擺效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97466712,'入侵蠕蟲','①：對手場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97474300,'決鬥者創世',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的場上或墓地有協調存在的場合可以發動。從牌組將1張「同步」魔法、陷阱卡加入手牌。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97476032,'寒冰塑偶',unistr('這個卡名的①②③效果1回合各能使用1次，這些效果發動的整回合中，我方除了水屬性怪獸以外不能特殊召喚。\u000a①：從手牌將1隻其他的水屬性怪獸捨棄可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。從牌組將1隻魔法使族、水屬性怪獸加入手牌。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將1張「寒冰塑偶之鏡」加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97489701,'緋暗紅新星龍',unistr('協調2隻+「暗紅惡魔龍」\u000a①：此卡的攻擊力上升我方墓地的協調數量×500。\u000a②：此卡不會被對手的效果破壞。\u000a③：對手怪獸的攻擊宣言時，以那1隻攻擊怪獸為對象可以發動。場上的此卡除外，那次攻擊無效。\u000a④：此卡的③效果除外的回合的結束階段發動。此卡特殊召喚。'),'攻擊無效','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97489702,'緋暗紅新星龍',unistr('協調2隻+「暗紅惡魔龍」\u000a①：此卡的攻擊力上升我方墓地的協調數量×500。\u000a②：此卡不會被對手的效果破壞。\u000a③：對手怪獸的攻擊宣言時，以那1隻攻擊怪獸為對象可以發動。場上的此卡除外，那次攻擊無效。\u000a④：此卡的③效果除外的回合的結束階段發動。此卡特殊召喚。'),'攻擊無效','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97518132,'影依的巫女 艾莉亞爾',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡反轉的場合，以我方的除外狀態的1隻「影依」怪獸為對象可以發動。那隻怪獸表側守備表示或裡側守備表示特殊召喚。\u000a②：此卡被效果送去墓地的場合，以我方、對手的墓地的卡合計最多3張為對象可以發動。那些卡除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97520532,'奇巧人偶-奇美拉人偶',unistr('機械族怪獸2隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：如果此卡已被連結召喚可以發動。從牌組選1隻「奇巧人偶」怪獸加入手牌或送去墓地。我方場上的怪獸只有「奇巧人偶」怪獸的場合，隨後可以從手牌將1隻「奇巧人偶」怪獸特殊召喚。此效果的發動後，直到回合結束時我方除了機械族超量怪獸以外不能從額外牌組特殊召喚。'),'效果1','請選擇要加入手牌或送去墓地的卡','是否從手牌特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97520701,'臨時行車時間表',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻攻擊力3000以上的機械族怪獸為對象可以發動。那隻機械族怪獸守備表示特殊召喚。\u000a②：覆蓋的此卡被送去墓地的場合，以我方墓地1隻機械族、等級10怪獸為對象可以發動。那隻機械族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97522863,'擁有刻印之人',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組選1張「王家的神殿」或記載那個卡名的魔法、陷阱卡加入手牌或送去墓地。\u000a②：只要我方場上有「王家的神殿」存在，此卡以及我方場上的「阿波畢斯」怪獸不會被戰鬥、效果破壞。\u000a③：只要此卡在怪獸區域存在，我方場上的「王家的神殿」不會被效果破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97526666,'行星探查車','①：解放此卡可以發動。從牌組將1張場地魔法卡加入手牌。','牌組檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97534104,'殺手馬鈴薯','①：場上的此卡被效果破壞送去墓地的場合可以發動。除了「殺手馬鈴薯」以外，從牌組將1隻攻擊力1500以下的闇屬性怪獸攻擊表示特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97556336,'無垢者 梅迪烏斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組選1隻「獄神」怪獸加入手牌或特殊召喚。\u000a②：此卡在墓地存在的場合可以發動。從我方的手牌、場上（表側表示）讓1隻怪獸回到牌組，此卡特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97565997,'溟界神-奧格多邃淵',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在墓地存在的場合，將我方場上3隻怪獸解放可以發動。此卡特殊召喚。\u000a②：只在此卡在場上表側表示存在可以發動1次。除了從墓地特殊召喚的表側表示怪獸以外，我方、對手場上的怪獸全部送去墓地。此效果在對手回合也能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97567736,'鋒利小鬼 戰斧',unistr('「鋒利小鬼 戰斧」的①②效果1回合各能使用1次。\u000a①：將手牌1隻「鋒利小鬼」怪獸送去墓地可以發動。給予對手800傷害。\u000a②：從牌組將「鋒利小鬼 戰斧」以外的1隻「鋒利小鬼」怪獸送去墓地可以發動。直到結束階段，此卡和送去墓地的怪獸當作同名卡。'),'效果1','效果2','解除複製效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97570038,'神拳猛擊','我方場上有「格鬥鼠 邱助」「僧侶鬥士」「僧侶首領」之中1隻以上存在的場合可以發動。這個回合和這些怪獸進行戰鬥的怪獸在傷害步驟結束時破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97574404,'大秘儀之力VI-戀人',unistr('此卡召喚、反轉召喚、特殊召喚成功時，投擲1次硬幣並得到以下效果。\u000a●正：「大秘儀之力」怪獸上級召喚的場合，此卡可以當作2隻解放。\u000a●反：「大秘儀之力」怪獸不能上級召喚。'),'投擲硬幣','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97584500,'鬼計木乃伊',unistr('只能在我方場上有「鬼計」怪獸存在的場合將此卡表側表示召喚。\u000a我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a只要此卡在場上表側表示存在，我方在通常召喚之外只有1次，可以召喚1隻「鬼計」怪獸。\u000a只要此卡在場上表側表示存在，我方不能將闇屬性以外的怪獸特殊召喚。'),'變成裡側守備','召喚（鬼計木乃伊）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97584719,'無限起動 大地撼動者',unistr('等級9怪獸×2\u000a這個卡名的①③效果1回合各能使用1次。\u000a①：去除此卡的任意數量的超量素材，以那個數量的場上的卡為對象可以發動。那些卡破壞。\u000a②：此卡戰鬥破壞對手怪獸時可以發動。那隻怪獸重疊在此卡下方作為超量素材。\u000a③：此卡在墓地存在的場合，解放我方場上1隻機械族連結怪獸可以發動。此卡守備表示特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97588916,'生化文具人007',unistr('【靈擺效果】\u000a①：我方除了「生化文具人」怪獸以外不能靈擺召喚。這個效果不會被無效化。\u000a【怪獸效果】\u000a①：此卡的攻擊力上升我方墓地的「生化文具人」卡片數量×500。\u000a②：只要此卡在怪獸區域存在，對手不能將其他的「生化文具人」怪獸作為攻擊對象。\u000a③：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97590747,'神燈的魔精 拉丁','聽從呼喚他的主人的任何要求及命令的燈之精靈。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97590748,'神燈的魔精 拉丁','聽從呼喚他的主人的任何要求及命令的燈之精靈。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97612389,'地獄的魔獸師','能自由自在地操縱怪獸攻擊的怪獸使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97616504,'閃刀機構-大力神基地',unistr('我方的主要怪獸區域沒有怪獸存在的場合可以發動此卡。\u000a①：裝備怪獸不能直接攻擊，在1次戰鬥階段中可以向怪獸攻擊最多2次。\u000a②：裝備怪獸的攻擊將怪獸破壞的場合，如果我方墓地有3張以上魔法卡存在則發動。我方從牌組抽1張卡。\u000a③：此卡被效果從場上送去墓地的場合，以「閃刀機構-大力神基地」以外的我方墓地最多3張「閃刀」卡片為對象可以發動。那些卡回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97617181,'銀河零式',unistr('「銀河零式」在1回合只能發動1張。\u000a①：以我方墓地的1隻「光子」怪獸或「銀河」怪獸為對象可以發動。那隻怪獸表側攻擊表示特殊召喚，並裝備此卡。裝備怪獸不能攻擊，也不能發動效果。\u000a②：裝備怪獸在戰鬥階段被戰鬥、效果破壞的場合，可以將此卡破壞作為代替。\u000a③：此卡從場上離開的場合發動。此卡裝備過的怪獸的攻擊力變成0。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97623219,'元素女武神',unistr('依照場上的怪獸屬性，此卡得到以下效果。\u000a●炎屬性：此卡的攻擊力上升500。\u000a●水屬性：此卡的控制權不能變更。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97631303,'魔術師的雙魂',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，可以從牌組將1隻等級6以上的魔法使族怪獸送去墓地，從以下效果選擇1個發動。\u000a●此卡特殊召喚。\u000a●此卡送去墓地。那之後，可以從我方墓地將1隻「黑魔導」或「黑魔導女孩」特殊召喚。\u000a②：從我方的手牌、場上將最多2張魔法、陷阱卡送去墓地可以發動。依照送去墓地的數量，我方抽牌。'),'●此卡特殊召喚','●此卡送去墓地','是否從墓地特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97637162,'讓步小快馬',unistr('①：此卡不能直接攻擊。\u000a②：此卡的攻擊力上升雙方的生命值的差額。\u000a③：我方的生命值高於對手的場合，此卡的攻擊產生給對手的戰鬥傷害由我方代為承受。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97639441,'光子跳躍者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手怪獸的攻擊宣言時可以發動。此卡從手牌特殊召喚。那之後，戰鬥階段結束。此效果發動的場合，跳過下個我方戰鬥階段。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1張「光子」魔法、陷阱卡或「銀河」魔法、陷阱卡加入手牌。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97642679,'闇之支配者-佐克',unistr('藉由「與闇之支配者的契約」降臨。\u000a①：1回合1次，我方主要階段可以發動。擲1次骰子，依照擲出點數適用以下效果。\u000a●1、2：對手場上的怪獸全部破壞。\u000a●3、4、5：選對手場上1隻怪獸破壞。\u000a●6：我方場上的怪獸全部破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97648103,'星遺物的加護',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地2隻卡名不同的「星杯」怪獸為對象可以發動。那些怪獸加入手牌。\u000a②：我方場上的連結狀態的連結怪獸被戰鬥破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97651498,'魔轟神 魯力','①：此卡從手牌捨棄到墓地的場合發動。此卡特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97651499,'魔轟神 魯力','①：此卡從手牌捨棄到墓地的場合發動。此卡特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97661969,'崔嵬的地靈使 奧絲',unistr('包含地屬性怪獸的怪獸2隻\u000a這個卡名在規則上也當作「憑依裝著」卡片。這個卡名的①②效果1回合各能使用1次。\u000a①：以對手墓地1隻地屬性怪獸為對象可以發動。那隻怪獸在此卡指向的我方場上特殊召喚。\u000a②：連結召喚的此卡被戰鬥或對手的效果破壞的場合可以發動。從牌組將1隻守備力1500以下的地屬性怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97662494,'紋章獸 斯塔德鯨',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合，捨棄1張手牌可以發動。從牌組將2張「徽章」魔法、陷阱卡加入手牌。\u000a②：將墓地的此卡除外，以我方墓地的2隻同名的「紋章獸」怪獸為對象可以發動。那些怪獸守備表示特殊召喚。此效果的發動後，直到回合結束時我方除了只用原卡名包含「紋章獸」或「No.」的怪獸作為素材的超量召喚以外，不能從額外牌組將怪獸特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97677329,'備份督導員',unistr('怪獸2隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：如果此卡已用「備份秘書」為素材連結召喚，此卡指向的我方怪獸和對手怪獸進行戰鬥的傷害步驟結束時可以發動。從手牌將1隻電子界族怪獸特殊召喚。\u000a②：此卡被戰鬥或對手的效果破壞的場合可以發動。從我方的手牌、牌組、墓地選1隻「備份秘書」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97682931,'革命同步者',unistr('這個卡名的①效果1回合只能使用1次，②效果在決鬥中只能使用1次。\u000a①：「動力工具」同步怪獸或等級7、8的龍族同步怪獸同步召喚的場合，手牌的此卡也能作為同步素材。\u000a②：此卡在墓地存在，我方場上有等級7以上的同步怪獸存在的場合可以發動。我方牌組最上方的卡送去墓地，此卡特殊召喚。此效果特殊召喚的此卡的等級變成1。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97687912,'隕星撞擊','裝備怪獸向守備表示怪獸攻擊時，給予對手攻擊力超過那個守備力的數值的戰鬥傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97688360,'剛鬼 固定眼鏡蛇',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：將我方場上1隻「剛鬼」怪獸解放，以我方場上1隻「剛鬼」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升解放的怪獸的原攻擊力數值。此效果在對手回合也能發動。\u000a②：此卡從場上送去墓地的場合可以發動。從牌組將「剛鬼 固定眼鏡蛇」以外的1張「剛鬼」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97692972,'亞馬遜的金鞭使',unistr('【靈擺效果】\u000a這個卡名的②靈擺效果1回合只能使用1次。\u000a①：我方場上的「亞馬遜」怪獸的攻擊力上升自身的等級×100。\u000a②：我方的「亞馬遜」怪獸進行戰鬥的攻擊宣言時，以場上1張魔法、陷阱卡為對象可以發動。那張卡破壞。\u000a【怪獸效果】\u000a這個卡名的①②怪獸效果1回合各能使用1次。\u000a①：怪獸區域的此卡被戰鬥、效果破壞的場合可以發動。此卡在我方的靈擺區域放置。\u000a②：此卡在墓地存在的狀態，我方場上有「亞馬遜」怪獸特殊召喚的場合可以發動。此卡在我方的靈擺區域放置。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97697447,'邃淵激流','將我方場上表側表示存在的「海」送去墓地可以發動。場上的魔法、陷阱卡全部送去墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97697678,'圓盤 姆斯基型','只要此卡在我方場上表側表示存在，我方的抽牌階段，可以作為進行通常抽牌的代替，從牌組將1張「外星人」卡片加入手牌。','檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97698279,'百夫長龍騎兵 卡戈爾II',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：將我方場上1張表側表示的「百夫長」卡片送去墓地可以發動。此卡從手牌特殊召喚。這個回合，我方不能特殊召喚「百夫長龍騎兵 卡戈爾II」。\u000a②：此卡作為同步素材送去墓地的場合可以發動。此卡加入手牌。\u000a③：此卡當作永續陷阱卡的場合，我方、對手的主要階段可以發動。此卡特殊召喚。那之後，可以讓此卡的等級下降4。'),'效果1','效果2','效果3','是否將等級下降？','','','','','','','','','','','','');
INSERT INTO texts VALUES(97705809,'超級充電','①：我方場上的怪獸只有機械族的「機人」怪獸的場合，對手怪獸的攻擊宣言時可以發動。我方從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97729135,'互瞪',unistr('①：我方在額外怪獸區域將怪獸特殊召喚時，以對手的主要怪獸區域1隻怪獸為對象可以發動。那隻對手怪獸向和那隻我方的額外怪獸區域的怪獸相同縱列的對手的主要怪獸區域移動。\u000a②：對手在額外怪獸區域將怪獸特殊召喚時，以我方的主要怪獸區域1隻怪獸為對象可以發動。那隻我方怪獸向和那隻對手的額外怪獸區域的怪獸相同縱列的我方的主要怪獸區域移動。'),'效果1','效果2','請選擇要移動的位置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97738431,'編號疊放推進','以我方場上1隻沒有超量素材的「No.」超量怪獸為對象可以發動。我方的手牌的2隻怪獸重疊在那隻超量怪獸下方作為超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97750534,'死之代行者 天王星',unistr('①：場上有「天空的聖域」存在的場合，此卡可以從手牌特殊召喚。\u000a②：1回合1次，我方主要階段可以發動。從牌組將1隻「代行者」怪獸送去墓地。此卡的等級變成和那隻怪獸的等級相同。'),'從牌組送去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97769122,'巴利安之混沌抽牌',unistr('①：在我方抽牌階段藉由將通常抽牌抽到的此卡持續公開，那個回合的主要階段1，可以從以下效果選擇1個發動。\u000a●從牌組將1張「七皇」通常魔法卡送去墓地可以發動。此效果變成和那張魔法卡發動時的效果相同。\u000a●從牌組將最多2隻怪獸效果無效特殊召喚，用包含那些怪獸全部在內的我方場上的怪獸為素材將1隻「No.」超量怪獸超量召喚。'),'是否要持續公開「巴利安之混沌抽牌」？','●複製「七皇」通常魔法卡','●從牌組特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97783338,'水雷魔神-門之守護者',unistr('「水魔神-斯卡」+「雷魔神-桑卡」\u000a只能將我方場上的上述卡除外來特殊召喚。這個卡名的①效果1回合可以使用最多2次。\u000a①：我方、對手回合，以對手場上1隻表側表示怪獸為對象可以發動（同一連鎖上最多1次）。那隻怪獸的攻擊力直到回合結束時變成0。\u000a②：特殊召喚的表側表示的此卡因對手從場上離開的場合可以發動。我方的除外狀態的1隻「水魔神-斯卡」或「雷魔神-桑卡」特殊召喚。'),'攻擊力變成0','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97783659,'吸血怪','此卡給予對手戰鬥傷害時，從對手的牌組上方將1張卡送去墓地。','牌堆最上方的牌送進墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97792247,'星塵強襲戰士',unistr('協調+協調以外的怪獸1隻以上\u000a「星塵強襲戰士」的①效果1回合只能使用1次。\u000a①：此卡同步召喚成功時，我方場上沒有其他怪獸存在的場合，以我方墓地的1隻「廢品」怪獸為對象可以發動。那隻怪獸特殊召喚。\u000a②：此卡攻擊守備表示怪獸時，給予攻擊力超過那個守備力的數值的戰鬥傷害。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97795930,'幻煌龍的天渦',unistr('場上有「海」存在的場合，此卡也能從手牌發動。\u000a①：以我方場上1隻「幻煌龍 螺旋」為對象可以發動。那隻怪獸在已裝備3種以上「幻煌龍」裝備魔法卡的狀態戰鬥破壞對手的3隻效果怪獸時，我方獲得決鬥勝利。\u000a②：我方場上的通常怪獸被戰鬥、效果破壞的場合，可以將墓地的此卡除外作為代替。'),'N/A','適用「幻煌龍的天渦」的效果來發動','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97800311,'聖神蛇 阿波畢斯',unistr('記載「王家的神殿」的卡名的怪獸\u0015×2\u000a此卡只能用融合召喚或以下方法特殊召喚。\u000a●將我方場上2隻「阿波畢斯」怪獸解放，可以從額外牌組特殊召喚。\u000a①：1回合1次，以我方墓地最多3張「阿波畢斯」陷阱卡為對象可以發動（同名卡最多1張）。那些卡在我方場上覆蓋。\u000a②：1回合1次，陷阱卡發動的場合，以對手場上1張卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97803170,'惡魔的呼聲',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：以我方墓地1隻等級5以上的惡魔族怪獸為對象可以發動。從手牌捨棄1隻惡魔族怪獸，對象怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97806240,'強引的安全協定','捨棄1張手牌可以發動。直到回合結束時，陷阱卡不能發動。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97809599,'舊神之印','①：支付1000生命值可以發動。確認對手場上覆蓋的卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97811903,'潔淨惡龍',unistr('①：只要此卡在怪獸區域存在，「潔淨世界」的效果對我方不適用。\u000a②：此卡的攻擊力只在向對手怪獸攻擊的傷害計算時變成那隻對手怪獸的攻擊力的2倍。\u000a③：場上的此卡被對手的效果破壞的場合，可以將1張我方的手牌捨棄作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97836203,'T.G. 戰戟砲手',unistr('同步怪獸協調+協調以外的同步怪獸2隻以上\u000a此卡只能用同步召喚來特殊召喚。\u000a①：1回合1次，我方或對手將怪獸召喚、反轉召喚、特殊召喚之際可以發動。此卡在場上表側表示存在的場合，使其無效，那些怪獸破壞。\u000a②：此卡從場上送去墓地時，以我方墓地1隻「T.G.」怪獸為對象可以發動。那隻怪獸特殊召喚。'),'效果1','效果1','效果1','效果2','','','','','','','','','','','','');
INSERT INTO texts VALUES(97843505,'風之番人 精','操縱風來產生龍捲風與暴風吹飛周圍的東西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97854941,'華爾裘蓮 希格露恩',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，以我方場上1張表側表示的魔法、陷阱卡為對象可以發動。那張卡送去墓地，此卡特殊召喚。\u000a②：此卡召喚、特殊召喚成功的場合可以發動。從我方的手牌、墓地選1隻等級8以下的「華爾裘蓮」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97864322,'查理大帝',unistr('已裝備裝備卡的等級9「焰聖騎士帝-查理」1隻\u000a①：此卡連結召喚的場合，以我方墓地1隻「焰聖騎士帝-查理」為對象可以發動。此卡和那張卡當作同名卡，得到相同效果。那之後，對象怪獸當作攻擊力上升500的裝備魔法卡給此卡裝備。\u000a②：1回合1次，魔法、陷阱卡的效果發動時，從我方的手牌、場上（表側表示）將1張裝備魔法卡送去墓地可以發動。那個發動無效並破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97870394,'亞馬遜靈術師',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌、墓地存在的場合，以「亞馬遜靈術師」以外的我方場上1張「亞馬遜」卡片為對象可以發動。那張卡回到持有者的手牌，此卡特殊召喚。此效果的發動後，直到回合結束時我方除了「亞馬遜」怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡特殊召喚成功的場合可以發動。從牌組將1張「融合」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97885363,'電力蜻蜓','此卡被對手破壞的場合，可以從牌組將1隻「電力」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97896503,'刷啦啦騎士','①：此卡向表側守備表示怪獸攻擊的傷害步驟開始時發動。那隻怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97904474,'手銬龍',unistr('此卡被對手怪獸的攻擊破壞送去墓地時，可以將此卡當作裝備卡給那隻怪獸裝備。\u000a裝備怪獸的攻擊力下降1800。\u000a裝備怪獸被破壞讓此卡被送去墓地時，此卡可以在我方場上特殊召喚。'),'裝備','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97922283,'野生的咆哮','我方場上的怪獸戰鬥破壞對手怪獸送去墓地時，我方場上的獸族怪獸每有1隻就給予對手300傷害。','給對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97923414,'大木人18','其原型是被砍倒的巨樹寄宿了邪惡靈魂的姿態。襲擊迷失在森林裡的旅人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97926515,'緊急救急救命救援',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的生命值比對手少的場合可以發動。從牌組將3隻攻擊力300/守備力100的獸族怪獸向對手展示，對手從其中選1隻。那1隻怪獸加入我方的手牌，其餘回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97940434,'混沌獵人',unistr('①：對手將怪獸特殊召喚成功時，將此卡以外的1張手牌捨棄可以發動。此卡從手牌特殊召喚。\u000a②：只要此卡在怪獸區域存在，對手不能將卡除外。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97946536,'蟲裝三輪車-紅黃',unistr('這個卡名在規則上也當作「甲蟲裝機」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：可以從手牌以及我方場上的表側表示的卡之中，將1張「甲蟲裝機」卡片送去墓地，從以下效果選擇1個發動。\u000a●從牌組選1隻「甲蟲裝機」怪獸特殊召喚或當作裝備卡給我方場上1隻「甲蟲裝機」怪獸裝備。\u000a●從牌組選1張「甲蟲裝機」裝備魔法卡給我方場上1隻「甲蟲裝機」怪獸裝備。'),'●選擇怪獸','●選擇裝備魔法','當作裝備卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97947705,'備份操作員',unistr('這個卡名的效果1回合只能使用1次。\u000a①：以我方的連結怪獸指向的1隻表側表示怪獸為對象可以發動。此卡從手牌特殊召喚，對象怪獸回到持有者的手牌。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97949165,'LL-綠松石樹鶯',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡從手牌特殊召喚成功的場合可以發動。從我方的手牌、墓地選1隻「LL-」怪獸特殊召喚。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97970833,'最後勝地','對手怪獸的攻擊宣言時可以發動。從我方牌組選1張「虹之古代都市-彩虹遺跡」發動。對手場上有場地魔法卡的場合，隨後對手玩家可以抽1張卡。','是否抽1張卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97973387,'司比克','嘴非常大，用大聲的鳴叫驚嚇弱者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97973962,'暴走召喚師 阿萊斯特',unistr('種族和屬性不同的怪獸2隻\u000a①：只要此卡在場上、墓地存在，卡名當作「召喚師 阿萊斯特」。\u000a②：此卡在怪獸區域存在的狀態，融合怪獸融合召喚的場合可以發動。選1張我方的手牌捨棄，從牌組將1張「召喚魔術」或「法之聖典」加入手牌。\u000a③：表側表示的此卡因對手的效果從場上離開的場合可以發動。從牌組將1張「魔法名-「大獸」」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97997309,'惡靈的魔導書',unistr('我方場上有魔法使族怪獸存在的場合，將我方墓地的最多3張「魔導書」魔法卡除外可以發動。依照為了發動此卡而除外的魔法卡數量適用以下效果。「惡靈的魔導書」在1回合只能發動1張。\u000a●1張：選場上覆蓋的1張魔法、陷阱卡回到持有者的手牌。\u000a●2張：選場上1隻怪獸變成裡側守備表示或表側攻擊表示。\u000a●3張：選對手場上1張卡除外。'),'●1張：','●2張：','●3張：','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98007437,'鎧騎士龍－騎士武裝龍－',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方將等級5以上的龍族怪獸特殊召喚的場合可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚的場合可以發動。此卡的屬性、等級變成和我方的除外狀態的1隻龍族怪獸相同。\u000a③：此卡被送去墓地的場合，以我方場上1隻龍族怪獸為對象可以發動（應對此效果的發動，雙方不能發動效果）。那隻怪獸的攻擊力上升1000。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98012938,'獸神 伏爾甘',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡同步召喚的場合，以我方以及對手場上的表側表示卡各1張為對象發動。那些我方以及對手的表側表示卡回到手牌。這個回合，我方不能發動此效果回到手牌的卡以及那些同名卡的效果。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98020526,'救世幻象',unistr('①：我方場上的表側表示的「星塵龍」或記載那個卡名的同步怪獸為了發動我方的卡的效果從場上離開的場合，或因我方的卡的效果從場上離開的場合可以發動。從以下效果挑選1個適用。這個回合，我方的「救世幻象」的效果不能適用相同效果。\u000a●挑選其中1隻怪獸特殊召喚。\u000a●從對手的場上、墓地選1隻怪獸除外。\u000a●這個回合，我方受到的全部傷害變成一半。'),'●挑選其中1隻怪獸特殊召喚','●從對手的場上、墓地選1隻怪獸除外','●這個回合，我方受到的全部傷害變成一半','發動但不使用效果','使用效果1','','','','','','','','','','','');
INSERT INTO texts VALUES(98022050,'珠玉獸-運算主龍',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。「珠玉獸-運算主龍」以外的我方的手牌、場上（表側表示）1隻恐龍族怪獸破壞。那之後，原等級和那隻破壞的怪獸相同的1隻爬蟲類族、海龍族、鳥獸族怪獸或1張「進化藥」魔法卡從牌組加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98024118,'白面波波',unistr('我方場上有協調表側表示存在的場合，此卡不會被戰鬥破壞。\u000a我方場上表側表示存在的協調被戰鬥破壞送去墓地時，給予對手500傷害。'),'給對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98045062,'敵人控制器',unistr('①：可以從以下效果選擇1個發動。\u000a●以對手場上1隻表側表示怪獸為對象可以發動。那隻對手的表側表示怪獸的表示形式變更。\u000a●將我方場上1隻怪獸解放，以對手場上1隻表側表示怪獸為對象可以發動。直到結束階段得到那隻表側表示怪獸的控制權。'),'●變更表示形式','●得到控制權','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98049038,'匿蹤機人','我方場上有此卡以外的「機人」怪獸存在的場合，此卡進行戰鬥的我方回合的戰鬥階段結束時，選擇場上1張魔法、陷阱卡破壞。','破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98049915,'魔法燈','此卡可以直接攻擊對手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98049934,'超純愛妖精 美麗妖精',unistr('等級2怪獸×2\u000a①：1回合1次，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。此卡有「純愛妖精 可愛回憶」作為超量素材的場合，此效果在對手回合也能發動。\u000a②：我方發動「純愛妖精」速攻魔法卡時可以發動。場上的那張卡重疊在此卡下方作為超量素材。那之後，可以選對手場上1隻怪獸的表示形式變更。這個效果1回合可以使用最多3次。'),'效果1','效果2','是否選1隻對手怪獸變更表示形式？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98069388,'昇天的角笛','①：我方或對手將怪獸召喚、反轉召喚、特殊召喚之際，將我方場上1隻怪獸解放可以發動。使其無效，那些怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98075147,'魔鬼蝸牛','用暗之力進化的蝸牛。能夠快速移動。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98076754,'神數的聖選士',unistr('①：依照我方的額外牌組的表側表示的「神數」怪獸種類得到以下效果。\u000a●3種以上：我方場上的怪獸的攻擊力上升雙方的額外牌組的表側表示的卡片數量×100。\u000a●5種以上：我方場上的怪獸不會被對手的效果破壞。\u000a●8種以上：我方場上的怪獸不會成為對手的效果的對象。\u000a●10種：將魔法與陷阱區域的表側表示的此卡送去墓地可以發動。對手的手牌、場上、墓地的卡全部回到持有者的牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98093548,'俊炎星-象清',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，將我方場上1張表側表示的「炎舞」魔法、陷阱卡送去墓地可以發動。從手牌將「俊炎星-象清」以外的1隻「炎星」怪獸特殊召喚。\u000a②：以我方墓地1張「炎舞」魔法、陷阱卡為對象可以發動。那張卡回到牌組。那之後，可以從牌組將1隻等級5以上的「炎星」怪獸加入手牌。'),'效果1','效果2','是否從牌組把1隻等級5以上的「炎星」怪獸加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98095162,'光道宰制者 基里奧斯',unistr('屬性相同且種族不同的怪獸3隻\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡連結召喚的場合可以發動。從牌組選1張卡送去墓地。\u000a②：我方牌組的卡被效果送去墓地的場合發動。從我方牌組上方將3張卡送去墓地。\u000a③：表側表示的此卡因對手的效果從場上離開的場合，或被戰鬥破壞的場合，以我方墓地1張卡為對象可以發動。那張卡加入手牌。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98126725,'紫炎的參謀','我方場上有「六武眾」怪獸存在的場合，此卡召喚成功時，宣言1個種族發動。只要此卡在場上表側表示存在，宣言的種族的怪獸不能攻擊宣言，雙方玩家不能將宣言的種族的怪獸特殊召喚。','攻擊限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98127546,'閉鎖世界的冥神',unistr('效果怪獸4隻以上\u000a此卡連結召喚的場合，對手場上1隻怪獸也能作為連結素材。\u000a①：此卡連結召喚的場合可以發動。對手場上的全部表側表示怪獸的效果無效化。\u000a②：除了以此卡為對象的效果以外，連結召喚的此卡不受對手發動的效果影響。\u000a③：1回合1次，對手發動包含從墓地將怪獸特殊召喚效果的魔法、陷阱、怪獸的效果時可以發動。那個發動無效。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98127547,'閉鎖世界的冥神',unistr('效果怪獸4隻以上\u000a此卡連結召喚的場合，對手場上1隻怪獸也能作為連結素材。\u000a①：此卡連結召喚的場合可以發動。對手場上的全部表側表示怪獸的效果無效化。\u000a②：除了以此卡為對象的效果以外，連結召喚的此卡不受對手發動的效果影響。\u000a③：1回合1次，對手發動包含從墓地將怪獸特殊召喚效果的魔法、陷阱、怪獸的效果時可以發動。那個發動無效。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98139712,'死靈的引誘','每次卡被送去墓地，那些卡的持有者受到那個數量×300傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98143165,'同步英雄','①：裝備怪獸的等級上升1，攻擊力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98147766,'基因女','1回合1次，支付1000生命值，選擇被除外的1隻我方的超能族怪獸可以發動。被除外的那隻怪獸加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98153934,'魅影死槍',unistr('①：只要此卡在魔法與陷阱區域存在，每次以我方場上的「魅影騎士團」怪獸為對象的對手的效果發動，給予對手500傷害。\u000a②：我方場上的闇屬性怪獸被戰鬥或對手的效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98154550,'原始蝴蝶',unistr('①：我方場上沒有怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：1回合1次，我方主要階段可以發動。我方場上的全部昆蟲族怪獸的等級上升1。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98159737,'天威龍-海底輪',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上沒有效果怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方場上有效果怪獸以外的表側表示怪獸存在的場合，將手牌、墓地的此卡除外，以此卡以外的被除外的1隻我方的幻龍族怪獸為對象可以發動。那隻怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98162021,'紫炎的荒武者',unistr('此卡召喚成功時，給此卡放置1個武士道計數器（最多1個）。\u000a此卡已放置武士道計數器的場合，此卡的攻擊力上升300。\u000a1回合1次，可以去除此卡放置的1個武士道計數器，選擇場上1張可以放置武士道計數器的表側表示的卡，放置1個武士道計數器。'),'放置武士道計數器','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98162242,'針蠍','此卡戰鬥破壞怪獸送去墓地時，給予對手破壞的怪獸的等級×500傷害。','給予對手傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98167225,'創神的異響鳴琴',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方場上有6個以上響鳴計數器存在，我方場上的「異響鳴琴」連結怪獸的攻擊力上升1200。\u000a②：對手將怪獸特殊召喚的場合可以發動。進行1隻「異響鳴琴」連結怪獸的連結召喚。\u000a③：此卡從手牌、場上送去墓地的場合可以發動。給可以放置響鳴計數器的我方的靈擺區域1張卡放置響鳴計數器直到變成3個為止。'),'效果2','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98169343,'花樣明星 卡羅貝恩',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上的怪獸，不存在的場合或只有「花樣明星」怪獸的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方的「花樣明星」怪獸和對手怪獸進行戰鬥的從傷害步驟開始時到傷害計算前，將此卡從手牌送去墓地可以發動。那隻我方怪獸的攻擊力直到回合結束時上升其原攻擊力數值。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98173209,'深紅地獄蓋亞',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：我方主要階段可以發動。除了「深紅地獄蓋亞」以外，從我方的牌組、墓地將1張「暗紅惡魔龍」或記載那個卡名的卡加入手牌。\u000a②：我方的「暗紅惡魔龍」的攻擊宣言時可以發動。對手場上的怪獸全部變成裡側守備表示。\u000a③：場上的怪獸被戰鬥、效果破壞的場合可以發動。從我方墓地將1隻「暗紅惡魔龍」特殊召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98204536,'先史遺產驚神殿-三巨石',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上的怪獸，不存在的場合或只有「先史遺產」怪獸的場合，支付500生命值可以發動。從手牌將1隻「先史遺產」怪獸召喚。\u000a②：我方的「先史遺產」超量怪獸或我方的「No.」超量怪獸去除超量素材來發動效果的場合，可以將此卡送去墓地作為去除的1個超量素材的代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98225108,'獅馬獸','①：此卡和通常怪獸以外的怪獸進行戰鬥的傷害步驟期間，此卡的攻擊力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98229575,'U.A. 四分衛球員',unistr('「U.A. 四分衛球員」的①方法的特殊召喚1回合只能有1次。\u000a①：此卡可以讓「U.A. 四分衛球員」以外的我方場上1隻「U.A.」怪獸回到手牌，從手牌特殊召喚。\u000a②：此卡以外的我方的「U.A.」怪獸的攻擊宣言時可以發動。此卡的攻擊力下降800，我方的攻擊怪獸的攻擊力上升800。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98234196,'魔鍵銃士-克萊維斯','每個人都充滿可能性。要走還是要停，上鎖還是解鎖，都是取決於自己。目眩神迷的世界有許多門扉。為其解鎖的是魔法鑰匙。2把鑰匙1扇大門。2個意志1個身姿。大門若是解鎖，世界就會相連，巨大的力量從中顯現。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98239899,'帶鎖鏈的炸彈',unistr('①：以我方場上1隻表側表示怪獸為對象可以發動此卡。此卡當作攻擊力上升500的裝備卡給那隻我方怪獸裝備。\u000a②：當作裝備卡的此卡被效果破壞的場合，以場上1張卡為對象發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98248208,'暗黑海龍-龍三角',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在，我方的場上、墓地、除外狀態的等級10怪獸是3隻以上的場合可以發動。此卡特殊召喚。\u000a②：此卡特殊召喚的場合，將我方牌組最上方的卡送去墓地可以發動。此卡的攻擊力上升500。那之後，送去墓地的卡是怪獸的場合，給予對手1000傷害。不是的場合，可以將我方牌組最上方的卡送去墓地。'),'效果1','效果2','是否將牌組最上方的卡送去墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98252586,'追尋之風',unistr('只能給鳥獸族怪獸裝備。\u000a裝備怪獸的攻擊力、守備力上升300。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98259197,'搗蛋肌肉','選擇場上表側表示存在的1隻「搗蛋王」可以發動。選擇的「搗蛋王」以外的「搗蛋」怪獸全部破壞。選擇的「搗蛋王」的攻擊力上升破壞的怪獸數量×1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98263709,'銀河魔鏡士',unistr('反轉：我方回復我方墓地的「銀河」怪獸數量×500生命值。\u000a此外，反轉過的此卡被破壞送去墓地時，可以從我方的牌組、墓地選1隻等級4以下的「銀河」怪獸裡側守備表示特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98266377,'E.HERO 炙熱','①：此卡的攻擊力上升我方場上的「E.HERO」怪獸數量×200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98273947,'天使聖生','從我方墓地選擇1隻等級2以下的怪獸，以攻擊表示特殊召喚。此卡從場上離開時，那隻怪獸破壞。那隻怪獸從場上離開時，此卡破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98280324,'絨毛動物綿羊',unistr('「絨毛動物綿羊」的②效果1回合只能使用1次。\u000a①：我方場上有「絨毛動物綿羊」以外的「絨毛動物」怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：讓此卡以外的我方場上1隻「絨毛動物」怪獸回到持有者的手牌可以發動。從我方的手牌、墓地選1隻「鋒利小鬼」怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98287529,'虛龍魔王 無形主載心靈',unistr('藉由「無形陣 假面」降臨。\u000a①：此卡儀式召喚成功的場合，跳過下個對手回合的主要階段1。\u000a②：只要此卡在怪獸區域存在，場上的表側表示的融合、同步、超量怪獸的效果無效化。\u000a③：此卡從場上送去墓地的場合可以發動。從牌組將「虛龍魔王 無形主載心靈」以外的1隻「龍魔王」怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98299011,'神聖精靈的祝福','①：我方回復場上的怪獸數量×300生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98301564,'解放的阿里阿德涅',unistr('【靈擺效果】\u000a①：只要此卡在靈擺區域存在，適用以下效果。\u000a●我方不用為了發動反擊陷阱卡而支付生命值。\u000a●我方不用為了發動反擊陷阱卡而捨棄手牌。\u000a【怪獸效果】\u000a①：此卡被戰鬥、效果破壞的場合可以發動。從牌組將3張反擊陷阱卡向對手展示，對手從其中選1張。那1張卡加入我方的手牌，剩下的卡回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98319530,'『焰聖劍-阿爾瑪斯』',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：此卡裝備中的場合可以發動。從我方的牌組、墓地選「『焰聖劍-阿爾瑪斯』」以外的1張「焰聖劍」裝備魔法卡給可以裝備那張卡的我方場上1隻怪獸裝備。那之後，此卡破壞。\u000a②：裝備怪獸被送去墓地讓此卡被送去墓地的場合，以我方的墓地、除外狀態的1隻戰士族、炎屬性怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98336111,'結融體殺手','和此卡進行戰鬥的融合怪獸的攻擊力在傷害步驟期間變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98338152,'閃刀機-黑寡婦錨','①：我方的主要怪獸區域沒有怪獸存在的場合，以場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。那之後，我方墓地有3張以上魔法卡存在的場合，可以直到結束階段得到那隻怪獸的控制權。','是否獲得控制權？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98349765,'第19層『襲來干涉！漆黑的超級量子士！！』',unistr('①：可以從以下效果選擇1個發動（這個卡名的以下效果1回合各能選擇1次）。\u000a●以場上1隻攻擊表示怪獸為對象可以發動。那隻怪獸變成守備表示。\u000a●我方場上有「超級量子」怪獸存在的場合可以發動。從牌組將原屬性相同的怪獸不在我方場上存在的1隻「超級量子」怪獸守備表示特殊召喚。\u000a●從牌組將1張「超級量子」陷阱卡在我方場上覆蓋。此效果覆蓋的卡在覆蓋的回合也能發動。'),'效果1','●改變表示形式','●從牌組特殊召喚','●從牌組覆蓋陷阱卡','適用「第19層『襲來干涉！漆黑的超級量子士！！』」的效果來發動','','','','','','','','','','','');
INSERT INTO texts VALUES(98358303,'靜寂的念力女巫',unistr('①：場上的此卡被破壞送去墓地時可以發動。從牌組將1隻攻擊力2000以下的超能族怪獸除外。\u000a②：此卡的①效果將怪獸除外的場合，下個準備階段在墓地發動。那隻除外狀態的怪獸特殊召喚。'),'除外','特殊召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98360333,'Evil★Twin挑戰',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻「姬絲吉爾」怪獸或「璃拉」怪獸為對象可以發動。那隻怪獸特殊召喚。那之後，可以適用以下效果。\u000a●進行1隻「Evil★Twin」連結怪獸的連結召喚。'),'是否適用以下效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98371278,'DMZ龍',unistr('①：1回合1次，以我方墓地1隻等級4以下的龍族怪獸和我方場上1隻龍族怪獸為對象可以發動。作為對象的墓地的怪獸當作攻擊力上升500的裝備卡給作為對象的場上的怪獸裝備。\u000a②：已裝備裝備卡的我方怪獸攻擊的傷害步驟結束時，將墓地的此卡除外可以發動。那隻我方怪獸的裝備卡全部破壞。破壞的場合，那隻怪獸只有1次可以繼續攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98374133,'覺醒',unistr('只能給地屬性怪獸裝備。\u000a裝備怪獸的攻擊力上升400，守備力下降200。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98380593,'至高的果實','此卡發動時，我方的生命值低於對手的場合，我方回復2000生命值。我方的生命值高於對手的場合，我方受到1000傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98385955,'白森林的西爾維',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的場合可以發動。從牌組將1張「白森林」魔法、陷阱卡加入手牌。\u000a②：我方、對手回合，此卡在墓地存在的場合，以我方的場上、墓地1隻「白森林」同步怪獸為對象可以發動。那隻怪獸回到額外牌組，此卡效果無效特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98396890,'視界共鳴體',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：場上有等級5以上的闇屬性怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1張記載「暗紅惡魔龍」的卡名的魔法、陷阱卡加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98414735,'伯吉斯異獸 加拿大蟲',unistr('①：以對手場上1隻表側表示怪獸為對象可以發動。那隻怪獸變成裡側守備表示。\u000a②：此卡在墓地存在，陷阱卡發動時可以發動（同一連鎖上最多1次）。此卡變成通常怪獸（水族、水、等級2、攻1200/守0）在怪獸區域特殊召喚（不當作陷阱卡）。此效果特殊召喚的此卡不受怪獸的效果影響，從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98416533,'童話動物 小袋鼠',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手將怪獸召喚、特殊召喚的場合，或此卡被選擇作為對手怪獸的攻擊對象的場合可以發動。此卡回到手牌。那之後，可以從牌組將「童話動物 小袋鼠」以外的2隻「童話動物」怪獸特殊召喚（同名卡最多1張）。\u000a②：我方結束階段可以發動。此卡從手牌特殊召喚。'),'效果1','效果2','是否從牌組特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98427577,'鐵屑稻草人','①：對手怪獸的攻擊宣言時，以那1隻攻擊怪獸為對象可以發動。那次攻擊無效。發動後此卡不送去墓地，直接覆蓋。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98431356,'魅影翼',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：以場上1隻表側表示怪獸為對象可以發動。那隻怪獸的攻擊力上升500，這個回合只有1次不會被戰鬥、效果破壞。\u000a②：將墓地的此卡除外，以我方墓地1隻「魅影騎士團」怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98434877,'水魔神-斯卡','①：此卡在場上表側表示存在期間只有1次，此卡被攻擊的傷害計算時，以1隻攻擊怪獸為對象可以發動。那隻攻擊怪獸的攻擊力變成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98437424,'大植然波斯菊甜菜','對手將怪獸通常召喚成功時，此卡可以從手牌特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98439949,'無限起動 蟹式起重機',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：解放我方場上1隻機械族、地屬性怪獸可以發動。此卡從手牌守備表示特殊召喚。\u000a②：從我方墓地將1隻機械族怪獸除外可以發動。從牌組將1張「超接地展開」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98444741,'積累的幸福','同一連鎖上沒有多次同名卡的效果發動的場合，連鎖4以後可以發動。從牌組抽2張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98446407,'奈芙蒂斯的引導者','①：解放我方場上1隻怪獸和此卡可以發動。從手牌、牌組將1隻「奈芙蒂斯的鳳凰神」特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98452268,'霸王黑龍 異色眼反叛龍-霸主',unistr('【靈擺效果】\u000a①：1回合1次，我方主要階段可以發動。此卡特殊召喚，將1隻「反叛」怪獸或「魅影騎士團」怪獸重疊在此卡上方，當作超量召喚從額外牌組特殊召喚。那之後，可以將我方的靈擺區域1張卡作為那隻怪獸的超量素材。\u000a【怪獸效果】\u000a等級7怪獸×2\u000a我方1回合只能特殊召喚1次「霸王黑龍 異色眼反叛龍-霸主」。此卡也能重疊在我方場上的「反叛」超量怪獸上方來超量召喚，等級7可以靈擺召喚的場合，在額外牌組的表側的此卡可以靈擺召喚。\u000a①：用階級7超量怪獸為素材超量召喚的此卡在1次戰鬥階段中可以攻擊3次。\u000a②：怪獸區域的此卡被破壞的場合可以發動。此卡在我方的靈擺區域放置。'),'是否重疊在「反叛」超量怪獸上方超量召喚？','靈擺效果1','效果2','是否選我方靈擺區域的1張卡作為超量素材？','效果1適用中','','','','','','','','','','','');
INSERT INTO texts VALUES(98456117,'骨海馬','在海中徬徨著，發現獵物後會將其水分吸乾。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98462037,'閃刀姬-阿澤莉亞',unistr('光、闇屬性怪獸2隻\u000a此卡只能用連結召喚來特殊召喚，我方1回合只能特殊召喚1次「閃刀姬-阿澤莉亞」。\u000a①：此卡特殊召喚的場合，以場上1張卡為對象可以發動。那張卡破壞。那之後，我方墓地的魔法卡是3張以下的場合，此卡送去墓地。\u000a②：1回合1次，此卡和對手怪獸進行戰鬥的傷害步驟開始時，從我方墓地將1張魔法卡除外可以發動。那隻對手怪獸破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98476659,'怠慢之壺','①：我方依照對手場上的卡片數量抽牌。抽2張以上的場合，隨後依照那個數量-1張，挑選我方的手牌以喜歡的順序回到牌組下方。此卡的發動後，直到回合結束時我方不能發動「怠慢之壺」。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98477480,'肅聲的結界',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：只要我方場上有「肅聲的祈禱者 法律」以及光屬性儀式怪獸存在，對手怪獸只能選擇儀式怪獸作為攻擊對象，對手不能將我方場上的光屬性怪獸作為效果的對象。\u000a②：我方主要階段可以發動。除了「肅聲的結界」以外，從牌組將1張「肅聲」卡片或1隻「法律守護者」儀式怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98494543,'魔法石的採掘','①：捨棄2張手牌，以我方墓地1張魔法卡為對象可以發動。那張卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98495314,'執念之劍',unistr('裝備怪獸的攻擊力、守備力上升500。\u000a此卡被送去墓地時，此卡回到牌組最上方。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502113,'超魔導劍士-黑色聖武士',unistr('「黑魔導」+「爆裂劍士」\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡的攻擊力上升雙方的場上、墓地的龍族怪獸數量×500。\u000a②：魔法卡發動時，捨棄1張手牌可以發動。此卡在怪獸區域表側表示存在的場合，那個發動無效並破壞。'),'發動無效並破壞','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502114,'超魔導劍士-黑色聖武士',unistr('「黑魔導」+「爆裂劍士」\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡的攻擊力上升雙方的場上、墓地的龍族怪獸數量×500。\u000a②：魔法卡發動時，捨棄1張手牌可以發動。此卡在怪獸區域表側表示存在的場合，那個發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502115,'超魔導劍士-黑色聖武士',unistr('「黑魔導」+「爆裂劍士」\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡的攻擊力上升雙方的場上、墓地的龍族怪獸數量×500。\u000a②：魔法卡發動時，捨棄1張手牌可以發動。此卡在怪獸區域表側表示存在的場合，那個發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502116,'超魔導劍士-黑色聖武士',unistr('「黑魔導」+「爆裂劍士」\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡的攻擊力上升雙方的場上、墓地的龍族怪獸數量×500。\u000a②：魔法卡發動時，捨棄1張手牌可以發動。此卡在怪獸區域表側表示存在的場合，那個發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502117,'超魔導劍士-黑色聖武士',unistr('「黑魔導」+「爆裂劍士」\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡的攻擊力上升雙方的場上、墓地的龍族怪獸數量×500。\u000a②：魔法卡發動時，捨棄1張手牌可以發動。此卡在怪獸區域表側表示存在的場合，那個發動無效並破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98506199,'風飛馬@伊格尼斯者',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。最多到我方場上的「@伊格尼斯者」怪獸數量，將對手場上的魔法、陷阱卡破壞。\u000a②：此卡在怪獸區域或墓地存在的狀態，此卡以外的我方場上的卡被戰鬥或對手的效果破壞的場合，將此卡除外，以對手場上1張卡為對象可以發動。那張卡回到牌組。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98520301,'金山螳螂',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：對手場上有等級6以下的怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：我方的手牌比對手多的場合可以發動。場上的全部怪獸的表示形式變更。場上的其他昆蟲族怪獸的屬性、等級變成和此卡相同。這個回合，我方除了昆蟲族怪獸以外不能特殊召喚。\u000a③：此卡被破壞的場合可以發動。從牌組將1隻等級8以上的昆蟲族怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98535702,'傷害疫苗ΩMAX','我方因戰鬥或效果受到傷害時可以發動。我方的生命值回復我方受到的傷害數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98552723,'再臨的帝王',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻攻擊力2400/守備力1000的怪獸或攻擊力2800/守備力1000的怪獸為對象可以發動此卡。那隻怪獸效果無效守備表示特殊召喚，並裝備此卡。此卡從場上離開時那隻怪獸破壞。\u000a②：怪獸上級召喚的場合，裝備怪獸可以當作2隻解放。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98555327,'銀河魔導師',unistr('①：1回合1次，我方主要階段可以發動。此卡的等級直到回合結束時上升4。\u000a②：將此卡解放可以發動。從牌組將「銀河魔導師」以外的1張「銀河」卡片加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98558751,'T.G. 奇妙魔術師',unistr('協調+協調以外的「T.G.」怪獸1隻以上\u000a①：此卡同步召喚的場合，以場上1張魔法、陷阱卡為對象發動。那張卡破壞。\u000a②：對手主要階段可以發動（同一連鎖上最多1次）。用包含此卡的我方場上的怪獸為素材進行同步召喚。\u000a③：場上的此卡被破壞的場合發動。我方抽1張卡。'),'效果1','效果3','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98567237,'刻魔的詠聖',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻惡魔族、光屬性怪獸加入手牌。那之後，選1張我方的手牌捨棄。\u000a②：將墓地的此卡除外可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻「刻魔」融合怪獸融合召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98570539,'混沌的夢魔鏡',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方場上將「夢魔鏡」融合怪獸卡決定的融合素材怪獸送去墓地，從額外牌組融合召喚那1隻融合怪獸。場地區域有「聖光的夢魔鏡」存在的場合，手牌的怪獸也能作為融合素材。場地區域有「闇黑的夢魔鏡」存在的場合，也能將我方墓地的怪獸除外作為融合素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98582704,'有著翅膀的雞蛋天使','被蛋殼包住的天使。用巨大翅膀守備攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98585345,'羽翼栗子球 LV10',unistr('此卡不能通常召喚。只能用「進化之翼」的效果特殊召喚。\u000a藉由解放我方場上表側表示存在的此卡，對手場上的攻擊表示怪獸全部破壞，給予對手破壞的怪獸的原攻擊力合計數值的傷害。此效果只能在對手的戰鬥階段中發動。'),'破壞攻擊表示怪獸','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98588427,'包烤蒸騎-BULLauncher','「BULLauncher」是在日漸改良「Coc-OS」與「BFS裝甲」的過程中受「馬德拉」之命反覆試錯最終開發的3架「Foil-Packer」之中，專為炮擊&白天戰鬥而特化的支援機。憑藉其換裝成「Beef-Rifle」等武裝而令「包烤蒸騎」應對中、遠距離作戰一事成為可能。此外，「BULLauncher」通過與專為高速&空中戰鬥而特化的「WINGear」和專為接近&強襲戰鬥而特化的「BOARms」進行“熟成合體”，還會讓熱量很高的「包烤獸神-BW」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98596596,'靈魂遊盪的墓場',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡已在魔法與陷阱區域存在的狀態，我方場上的怪獸被戰鬥破壞送去墓地的場合發動。在我方場上將1隻「火之玉衍生物」（炎族、炎、等級1、攻/守100）特殊召喚。\u000a②：此卡已在魔法與陷阱區域存在的狀態，我方的手牌、場上的怪獸被對手的效果送去墓地的場合發動。將最多到那些怪獸數量的「火之玉衍生物」盡可能在我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98596597,'火之玉衍生物','由「靈魂遊盪的墓場」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98630720,'槍管終結龍',unistr('效果怪獸3隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：場上的此卡不會被戰鬥、效果破壞，雙方不能將此卡作為怪獸的效果的對象。\u000a②：此卡可以向全部對手怪獸各攻擊1次。\u000a③：我方、對手回合，以場上1隻效果怪獸和我方墓地1隻「槍彈」怪獸為對象可以發動（應對這個發動，對手不能發動卡的效果）。那隻場上的怪獸的效果無效，那隻墓地的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98630721,'槍管終結龍',unistr('效果怪獸3隻以上\u000a這個卡名的③效果1回合只能使用1次。\u000a①：場上的此卡不會被戰鬥、效果破壞，雙方不能將此卡作為怪獸的效果的對象。\u000a②：此卡可以向全部對手怪獸各攻擊1次。\u000a③：我方、對手回合，以場上1隻效果怪獸和我方墓地1隻「槍彈」怪獸為對象可以發動（應對這個發動，對手不能發動卡的效果）。那隻場上的怪獸的效果無效，那隻墓地的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98637386,'御用捕食者',unistr('協調+協調以外的怪獸1隻以上\u000a「御用捕食者」的效果1回合只能使用1次。\u000a①：此卡戰鬥破壞對手怪獸送去墓地時可以發動。那隻怪獸在我方場上特殊召喚。此效果特殊召喚的怪獸給予玩家的戰鬥傷害變成一半。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98642179,'剛炎之劍士',unistr('卡名不同的怪獸2隻\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，場上的戰士族怪獸的攻擊力上升500。\u000a②：連結召喚的此卡被戰鬥或對手的效果破壞的場合，以連結怪獸以外的我方墓地1隻戰士族怪獸為對象可以發動。那隻怪獸特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98643358,'鑽石冰塵','場上的水屬性怪獸全部破壞。那之後，給予對手這個效果破壞送去墓地的水屬性怪獸數量×500傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98645731,'強欲而謙虛之壺',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方不能將怪獸特殊召喚。\u000a①：從我方牌組上方翻開3張卡，從其中選1張加入手牌。那之後，剩下的卡回到牌組。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98649372,'骷髏海怪',unistr('此卡召喚成功時，可以選擇對手場上1張表側表示的魔法卡破壞。\u000a1回合1次，可以讓此卡的表示形式變更。'),'魔法卡破壞','變更表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98666339,'反轉次元','原持有者為我方的怪獸被對手的效果除外時可以發動。選擇其中1隻怪獸在我方場上特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98672567,'貪欲而無欲之壺',unistr('此卡發動的整回合中，我方不能進行戰鬥階段。\u000a①：我方主要階段1開始時，以我方墓地3隻怪獸為對象可以發動（相同種族最多1隻）。那3隻怪獸回到牌組洗牌。那之後，我方從牌組抽2張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98684051,'白鰯',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：從牌組將1隻「白鰯」送去墓地可以發動。此卡從手牌特殊召喚。此效果的發動後，直到回合結束時我方除了水屬性怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡從墓地特殊召喚的場合可以發動。這個回合，此卡當作協調。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98684220,'超魔劍士 黑混沌',unistr('此卡不能通常召喚。「超魔劍士 黑混沌」1回合1次，只能從我方的手牌、墓地讓1隻魔法使族、戰士族儀式怪獸回到牌組來特殊召喚。\u000a①：將此卡從手牌捨棄可以發動。從我方的牌組、墓地將1張記載「光與闇的儀式」的卡名的永續陷阱卡在我方場上表側表示放置。\u000a②：只要我方墓地有儀式魔法卡存在，此卡不受對手發動的效果影響。\u000a③：1回合1次，我方主要階段可以發動。對手場上2張卡除外。'),'效果1','效果3','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98696958,'暗黑迴廊',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從牌組將1隻「暗黑界」怪獸加入手牌。那之後，選1張我方的手牌捨棄。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98700941,'花樣明星 莉莉貝兒',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡用抽牌以外的方法加入手牌的場合可以發動。此卡特殊召喚。\u000a②：此卡可以直接攻擊。\u000a③：此卡給予對手戰鬥傷害時，以我方墓地1隻「花樣明星」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98707192,'鬼計瑪麗',unistr('只能在我方場上有「鬼計」怪獸存在的場合將此卡表側表示召喚。\u000a我方主要階段可以發動。此卡變成裡側守備表示（1回合只有1次）。\u000a此外，戰鬥或效果使我方受到傷害時，將此卡從手牌捨棄可以發動。從牌組將1隻「鬼計」怪獸裡側守備表示特殊召喚。「鬼計瑪麗」的這個效果1回合只能使用1次。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98715423,'守墓的陷阱',unistr('這個卡名的②③效果1回合各能使用1次。\u000a①：只要我方墓地有「現世與冥界的逆轉」存在，對手不能發動墓地的卡的效果，不能將墓地的怪獸特殊召喚。\u000a②：雙方的主要階段，捨棄1張手牌可以發動。從牌組將1隻「守墓」怪獸或天使族、地屬性怪獸加入手牌。\u000a③：此卡表側表示存在的場合，對手抽牌階段的抽牌前，宣言1個卡名發動。確認通常抽牌的卡，如果是宣言的卡，將其送去墓地。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98719226,'戰士外星人',unistr('此卡被戰鬥破壞送去墓地時，給破壞此卡的怪獸放置2個A計數器。\u000a只要此卡在場上表側表示存在，放置A計數器的怪獸和「外星人」怪獸進行戰鬥的場合，其攻擊力、守備力只在傷害計算時下降A計數器的數量×300。'),'放置A計數器','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98745000,'胡狼聖戰士','此卡戰鬥破壞對手怪獸送去對手墓地時，可以讓那張卡回到對手牌組最上方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98753320,'幻變騷靈故障轉移',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡以外的我方場上的卡被對手的效果破壞的場合可以發動。從手牌將1隻「幻變騷靈」怪獸特殊召喚。\u000a②：將墓地的此卡除外，以我方墓地1隻「幻變騷靈」怪獸為對象可以發動。那隻怪獸加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98777036,'悲愴魔',unistr('①：我方受到戰鬥傷害時可以發動。此卡從手牌特殊召喚。\u000a②：此卡的攻擊力、守備力上升我方的手牌數量×600。\u000a③：1回合1次，從手牌將1隻怪獸送去墓地，以對手場上1隻等級和那個等級相同的表側表示怪獸為對象可以發動。得到那隻表側表示怪獸的控制權。\u000a④：1回合1次，以我方墓地1隻怪獸為對象可以發動。此卡的等級直到回合結束時變成和那隻怪獸相同。'),'效果1','效果3','效果4','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98780137,'食惡刀','此卡召喚成功時，可以從我方墓地選擇「食惡刀」以外的1隻「食惡」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98787535,'溟界的昏闇-阿雷特',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在墓地存在的場合，將我方場上1隻怪獸解放可以發動。此卡特殊召喚。那之後，對手可以從自身墓地選1隻怪獸加入手牌。\u000a②：此卡特殊召喚成功的場合，從除外的我方怪獸之中以包含爬蟲類族怪獸的2隻怪獸為對象可以發動。那些怪獸回到墓地。'),'效果1','效果2','是否從墓地選1隻怪獸加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98792570,'被繼承的力量','將我方場上的1隻怪獸送去墓地，選擇我方場上1隻怪獸可以發動。選擇的怪獸的攻擊力直到回合結束時上升送去墓地的怪獸的攻擊力數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98795934,'魔大砲','大砲的魔鬼。以飛快的速度發射眼球彈。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98804359,'利維坦的激昂',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1張「激流葬」加入手牌。\u000a②：我方場上的水屬性怪獸被效果破壞的場合，可以將墓地的此卡除外作為代替。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98806751,'執愛的化盧普',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，以我方的場上、墓地1隻同步怪獸為對象可以發動。那隻怪獸除外，此卡特殊召喚。\u000a②：此卡在墓地存在的場合，以我方的場上、墓地1隻同步怪獸為對象可以發動。那隻怪獸除外，此卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98818516,'殺手貓熊','經常手持一根粗大的竹子四處找碴，性格非常兇暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98827725,'魅影騎士團 陰影布面甲',unistr('這個卡名的卡在1回合只能發動1張。我方墓地沒有陷阱卡存在的場合，此卡在覆蓋的回合也能發動。\u000a①：此卡發動後變成通常怪獸（戰士族、闇、等級4、攻0/守300）在怪獸區域守備表示特殊召喚（不當作陷阱卡）。'),'適用「魅影騎士團 陰影布面甲」的效果來發動','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98828338,'灰滅的憤怒',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從牌組將1隻炎族、闇屬性怪獸送去墓地。那之後，可以從我方墓地將1隻等級5以上的炎族怪獸加入手牌。此卡的發動後，直到回合結束時我方除了炎族怪獸以外不能從額外牌組特殊召喚。\u000a②：將墓地的此卡除外可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻炎族融合怪獸融合召喚。'),'從牌組送去墓地','融合召喚','是否把1隻炎族怪獸加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98829635,'禁忌的聖冠',unistr('這個卡名的卡在1回合只能發動1張，應對此卡的發動，不能發動怪獸的效果。\u000a①：挑選場上1隻表側表示怪獸，直到回合結束時適用以下效果。\u000a●效果無效化。\u000a●不能攻擊。\u000a●不會被戰鬥、效果破壞。\u000a●不受自身以外的卡發動的效果影響。\u000a●不能解放。\u000a●不能作為融合、同步、超量、連結召喚的素材。'),'效果1','「禁忌的聖冠」的效果1適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98847704,'拘束解放波','選擇我方場上表側表示存在的1張裝備魔法卡為對象可以發動。選擇的裝備魔法卡和對手場上覆蓋的魔法、陷阱卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98850929,'聖蛇的吹息',unistr('我方場上有儀式、融合、同步、超量怪獸之中的2種以上存在的場合，可以依照那些怪獸的種類，從以下效果選擇1個以上發動。「聖蛇的吹息」在1回合只能發動1張。\u000a●2種以上：選擇我方墓地1隻怪獸或被除外的1隻我方怪獸加入手牌。\u000a●3種以上：選擇我方墓地1張陷阱卡加入手牌。\u000a●4種：選擇「聖蛇的吹息」以外的我方墓地1張魔法卡加入手牌。'),'●2種以上：','●3種以上：','●4種：','是否繼續選擇「聖蛇的吹息」的效果？','','','','','','','','','','','','');
INSERT INTO texts VALUES(98864751,'破空風暴',unistr('只能給機械族怪獸裝備。\u000a①：裝備怪獸的攻擊破壞對手怪獸時可以發動。這次戰鬥階段中，裝備怪獸只有1次可以再度攻擊。此效果發動的整回合中，裝備怪獸以外的我方怪獸不能攻擊。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98865920,'熱辣辣射手','此卡召喚、反轉召喚成功時，給予對手500傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98867329,'災厄的裝備品',unistr('裝備怪獸的攻擊力下降我方場上的怪獸數量×600。\u000a此卡從場上送去墓地時，可以選擇對手場上表側表示存在的1隻怪獸裝備此卡。'),'裝備','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98875863,'G石人 岩錘手',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡在手牌存在的場合，從手牌捨棄1隻其他的電子界族怪獸可以發動。這個回合，此卡的等級下降2。\u000a②：將此卡解放可以發動。在我方場上將3隻「G石人衍生物」（電子界族、地、星1、攻/守0）守備表示特殊召喚。此效果的發動後，直到回合結束時我方除了電子界族怪獸以外不能特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98875864,'G石人衍生物','由「G石人 岩錘手」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98881700,'水晶鯊',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：此卡在手牌、墓地存在的場合，以場上1隻水屬性怪獸為對象可以發動。此卡特殊召喚，對象怪獸的攻擊力變成一半。此效果特殊召喚的此卡從場上離開的場合被除外。此效果的發動後，直到回合結束時我方除了超量怪獸以外不能從額外牌組特殊召喚。\u000a②：此卡在「No.」怪獸的超量召喚使用的場合，可以將此卡的等級當作3或4。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98881931,'光子前行者',unistr('這個卡名的①方法的特殊召喚1回合只能有1次。\u000a①：場上有「光子」怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：場上有此卡以外的「光子」怪獸存在的場合，此卡的攻擊力上升1000。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98884569,'藍薔薇龍','①：場上的此卡被破壞送去墓地時，以我方墓地1隻「黑薔薇龍」或植物族怪獸為對象可以發動。那隻怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98888032,'妖精胞 孢子',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：此卡特殊召喚的場合可以發動。最多到我方場上的怪獸數量，此卡的等級上升那個數值。\u000a②：此卡在墓地存在，我方場上有「上古妖精龍」或獸族、植物族、天使族的光屬性怪獸其中任何種類存在的場合可以發動。此卡特殊召喚。此效果的發動後，直到回合結束時我方除了同步怪獸以外不能從額外牌組特殊召喚。'),'效果1','效果2','請選擇上升的數值','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98891840,'休息的劍鬥獸','從我方的手牌選2張「劍鬥獸」卡片回到牌組。那之後，從牌組抽3張卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98898163,'巨牙龍',unistr('這個卡名的效果1回合只能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合，以此卡以外的場上最多2張卡為對象可以發動。那些卡破壞，此卡的攻擊力上升破壞的數量×600。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98898173,'融化的赤影','溶化身體鑽入影子中，從敵人正下方攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98904974,'魔鍵錠－解－',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方場上有「魔鍵」儀式怪獸或從額外牌組特殊召喚的「魔鍵」怪獸存在，對手發動魔法、陷阱卡時可以發動。那個發動無效並破壞。那之後，可以宣言1個屬性。那個場合，直到回合結束時，對手場上的全部表側表示怪獸變成宣言的屬性。'),'是否宣言1個屬性？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98918572,'十二獸的相剋',unistr('「十二獸的相剋」的①效果1回合只能使用1次。\u000a①：只要此卡在魔法與陷阱區域存在，我方的「十二獸」超量怪獸去除超量素材發動效果的場合，去除的超量素材可以從我方場上的其他的超量怪獸去除。\u000a②：將墓地的此卡除外，以我方場上2隻「十二獸」超量怪獸為對象可以發動。對象怪獸的其中1隻重疊在另1隻下方作為超量素材。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98927491,'救援急救機人',unistr('「救援機人」+「急救機人」\u000a此卡只能用融合召喚來特殊召喚。\u000a1回合1次，我方場上的怪獸被戰鬥破壞送去墓地時，可以將那隻怪獸守備表示特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98931003,'娜娜娜','①：以我方場上1隻等級7或階級7的怪獸為對象可以發動。那隻怪獸的攻擊力、守備力直到回合結束時上升700。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98935722,'沉眠於星遺物的深層',unistr('①：此卡發動時，可以選擇我方墓地1隻等級5以上的怪獸為對象。那個場合，那隻怪獸特殊召喚。此卡從場上離開時那隻怪獸破壞。\u000a②：只要我方場上有「機界騎士」怪獸存在，和那些怪獸相同縱列發動的對手怪獸的效果無效化。'),'是否從我方墓地選擇1隻怪獸發動？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98937206,'槍彈引爆者',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：我方場上有龍族、闇屬性連結怪獸存在的場合，此卡可以從手牌特殊召喚。\u000a②：以我方的魔法與陷阱區域的1張龍族、闇屬性怪獸卡為對象可以發動。那張卡特殊召喚。此效果特殊召喚的怪獸不能攻擊，效果無效化。此效果的發動後，直到回合回合結束時我方除了闇屬性怪獸以外不能從額外牌組特殊召喚。'),'從手牌特殊召喚','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98954106,'貪欲之瓶',unistr('「貪欲之瓶」在1回合只能發動1張。\u000a①：以「貪欲之瓶」以外的我方墓地5張卡為對象可以發動。那5張卡加入牌組洗牌。那之後，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98954375,'無限地獄破壞神','此卡戰鬥破壞對手怪獸送去墓地時，給予對手1600傷害。此效果在我方的手牌是0張的場合發動和處理。','給予傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98956134,'破壞干擾','持有「將場上的怪獸破壞的效果」的怪獸的效果、魔法、陷阱卡發動時，捨棄1張手牌可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98978921,'連結蜘蛛',unistr('通常怪獸1隻\u000a①：1回合1次，我方主要階段可以發動。從手牌將1隻等級4以下的通常怪獸在此卡指向的區域特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98986900,'泰勒瑪科技 克拉特斯',unistr('等級8怪獸×2\u000a這個卡名的②效果1回合只能使用1次。\u000a①：每次對手發動魔法卡以外的卡的效果，給此卡放置1個魔力計數器（最多9個）。\u000a②：去除此卡的3個魔力計數器可以發動。從以下效果將1個適用。\u000a●從牌組將1張魔法卡或1隻魔法使族效果怪獸加入手牌。\u000a●從手牌、牌組將1隻魔法使族怪獸特殊召喚。\u000a③：此卡被破壞的場合，可以去除此卡的1個超量素材作為代替。'),'效果2','●從牌組加入手牌','●從手牌、牌組特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98999181,'奈芙蒂斯的祈禱者',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。選1張手牌破壞，從牌組將「奈芙蒂斯的祈禱者」以外的1隻「奈芙蒂斯」怪獸加入手牌。\u000a②：此卡被效果破壞送去墓地的場合，下個我方準備階段可以發動。從牌組將1張「奈芙蒂斯」魔法、陷阱卡加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99000107,'修禪僧 元道',unistr('①：只要此卡在怪獸區域存在，場上的表側攻擊表示怪獸不能發動效果。\u000a②：守備表示的此卡不會成為卡的效果的對象，不會被效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99000151,'死之花','①：此卡被效果破壞送去墓地的場合可以發動。從牌組將1隻「鮮花的魔女」特殊召喚。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99002135,'緊急合成','讓我方墓地的1張「核成的鋼核」回到牌組可以發動。我方的手牌或墓地的1隻等級4以下的「核成」怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99004583,'動作魔法-完全過彎',unistr('①：這個回合，怪獸之間產生給雙方的戰鬥傷害變成2倍。\u000a②：此卡在墓地存在的場合，我方主要階段從手牌捨棄1張魔法卡可以發動。此卡在我方的魔法與陷阱區域覆蓋。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99004752,'迷你膽識',unistr('將我方場上1隻怪獸解放，選擇對手場上表側表示存在的1隻怪獸可以發動。選擇的怪獸的攻擊力直到回合結束時變成0。\u000a這個回合，選擇的怪獸被戰鬥破壞送去對手墓地時，給予對手那隻怪獸的原攻擊力數值的傷害。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99011763,'魔界的警邏課 死亡警察',unistr('怪獸2隻\u000a①：用卡名不同的2隻闇屬性怪獸為素材連結召喚的此卡得到以下效果。\u000a●解放我方場上1隻怪獸，以場上1張表側表示的卡為對象可以發動。給那張卡放置1個警邏計數器。這個卡名的這個效果1回合只能使用1次。已放置警邏計數器的卡被戰鬥、效果破壞的場合，去除那張卡的1個警邏計數器作為代替。'),'效果1','效果1適用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99013397,'劍鬥獸的鬥器 長戟',unistr('只能給「劍鬥獸」怪獸裝備。\u000a裝備怪獸攻擊的傷害步驟結束時，選擇場上的1張魔法、陷阱卡破壞。\u000a裝備怪獸從我方場上回到牌組讓此卡被送去墓地時，此卡回到手牌。'),'破壞魔法、陷阱卡','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99030164,'快樂戀人','從頭部放出心型射線使敵人得到幸福的小小天使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99049589,'魔玩具修復',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：以我方墓地1隻「魔玩具」融合怪獸為對象可以發動。那隻怪獸回到額外牌組。那之後，可以從我方墓地選1隻「絨毛動物」怪獸或「鋒利小鬼」怪獸特殊召喚。\u000a②：將墓地的此卡除外可以發動。從手牌將1隻「絨毛動物」怪獸或「鋒利小鬼」怪獸特殊召喚。'),'效果1','效果2','是否從墓地特殊召喚？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99050989,'尖鑽獸','對手場上只有攻擊力1600以上的表側表示怪獸存在的場合，此卡可以直接攻擊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99054885,'破壞的代行者 金星',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：從我方墓地將1隻「創造的代行者 金星」除外可以發動。此卡從手牌特殊召喚。\u000a②：支付500的倍數的生命值，每支付500生命值有1隻，從我方墓地的怪獸以及被除外的我方怪獸之中，以「神聖球體」為對象可以發動。那些怪獸特殊召喚。此效果特殊召喚的怪獸從場上離開的場合，回到持有者的牌組最下方。'),'此卡特殊召喚','「神聖球體」特殊召喚','請選擇要特殊召喚的怪獸的數量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99064191,'超量誅罰','1回合1次，我方場上有超量怪獸存在，等級5以上的怪獸的效果發動時，可以藉由捨棄1張手牌，那個效果無效並破壞。','效果無效並破壞','是否現在發動此卡的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99070951,'念之女孩',unistr('被除外的此卡被特殊召喚成功時，將我方牌組最上方的卡裡側表示除外。\u000a此卡從場上送去墓地時，我方用此卡的效果除外的卡加入手牌。'),'除外','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99075257,'D-時刻','我方場上的「E.HERO」怪獸從場上離開時可以發動。將等級在那隻怪獸等級以下的1隻「D-HERO」怪獸從牌組加進手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99092624,'漆黑薔薇的開華',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：最多到雙方的場地區域的卡以及墓地的場地魔法卡的數量，將「薔薇衍生物」（植物族、闇、等級2、攻/守800）在我方、對手場上守備表示特殊召喚。\u000a②：此卡在墓地存在的場合，以我方場上1隻「黑薔薇龍」或植物族怪獸為對象可以發動。那隻怪獸除外，此卡回到牌組最下方。此效果除外的怪獸在下個準備階段回到場上。'),'是否繼續特殊召喚？','在我方場上特殊召喚','在對手場上特殊召喚','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99092625,'薔薇衍生物','由「漆黑薔薇的開華」的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99111753,'安全龍',unistr('怪獸2隻\u000a這個卡名的效果1回合只能使用1次。\u000a①：此卡在場上表側表示存在期間只有1次，此卡是互相連結狀態的場合，以對手場上1隻怪獸為對象可以發動。那隻怪獸回到持有者的手牌。'),'效果1','已發動效果1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99115354,'高能念力平衡者',unistr('協調+協調以外的怪獸1隻以上\u000a這個卡名的②效果1回合只能使用1次。\u000a①：只要此卡在怪獸區域存在，攻擊力低於此卡的攻擊力的怪獸不能攻擊，攻擊力高於此卡的攻擊力的場上的怪獸不能發動效果。\u000a②：此卡被對手破壞送去墓地的場合，以我方墓地的種族和屬性相同的1隻協調和1隻協調以外的怪獸為對象可以發動。那些怪獸加入手牌。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99137266,'憶念的相劍',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：卡被除外的場合可以發動。從我方的手牌、牌組、墓地以及我方、對手場上的表側表示卡之中，將1隻幻龍族同步怪獸或1張「相劍」卡片除外。\u000a②：此卡被除外的場合可以發動。在我方場上將1隻「相劍衍生物」（幻龍族、協調、水、等級4、攻/守0）特殊召喚。只要此效果特殊召喚的衍生物存在，我方除了同步怪獸以外不能從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99137267,'相劍衍生物','由「相劍」卡片的效果特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99150062,'大植然螞蟻顎','對手將怪獸特殊召喚成功時，可以從我方牌組將1隻等級3以下的「大植然」怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99153051,'蕾禍之毬首',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：此卡可以將手牌的1隻昆蟲族、植物族、爬蟲類族怪獸送去墓地，從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合可以發動。「蕾禍之毬首」以外的我方的牌組、除外狀態的最多2張「蕾禍」卡片加入手牌（同名卡最多1張）。那之後，選1張我方的手牌除外。這個回合，我方除了昆蟲族、植物族、爬蟲類族怪獸以外不能特殊召喚。'),'','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99157310,'廷達三角 德勞內三角化',unistr('①：我方墓地有3種以上「廷達三角」怪獸存在，對手怪獸的攻擊讓我方受到戰鬥傷害時可以發動。那隻攻擊怪獸破壞，從額外牌組將1隻「廷達三角 銳角刻耳柏洛斯」特殊召喚。\u000a②：額外怪獸區域沒有我方怪獸存在的場合，將墓地的此卡除外，以我方墓地3隻「廷達三角」怪獸為對象可以發動（同名卡最多1張）。那些怪獸裡側守備表示特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99161253,'原石融合',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：包含通常怪獸的我方的場上、墓地、除外狀態的怪獸作為融合素材回到牌組，將1隻龍族融合怪獸融合召喚。\u000a②：將墓地的此卡除外可以發動。從我方的牌組、墓地將1隻等級5以上的「原石」怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99162522,'EXTINGUISH！',unistr('這個卡名在規則上也當作「R-ACE」卡片。\u000a①：我方場上有「R-ACE」怪獸存在的場合，以對手場上1隻效果怪獸為對象可以發動。那隻怪獸破壞。我方場上有「R-ACE 消防栓」存在的場合，隨後在這個回合，對手不能發動此效果破壞的怪獸以及原卡名和那隻怪獸相同的怪獸的效果。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99162753,'六界召喚',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方的手牌、墓地以及我方場上的表側表示怪獸之中，選原種族相同的怪獸6種（儀式、融合、同步、超量、靈擺、連結）各1隻除外。那之後，從牌組、額外牌組選1隻和除外的怪獸原種族相同的怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99171160,'哥查基','奉獻一切研究魔界語言的兇猛魔鬼。由於工作過度而精神崩潰。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99173029,'靈子能量固定裝置',unistr('此卡的控制者在每次我方結束階段捨棄1張手牌，或不捨棄讓此卡破壞。\u000a只要此卡在場上存在，靈魂怪獸在結束階段回到手牌的效果不能發動。\u000a此卡從場上離開時，場上的表側表示的靈魂怪獸全部回到持有者的手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99176254,'藍淚的少女',unistr('這個卡名的①②效果1回合只有1次能使用其中1個。\u000a①：我方場上有連結怪獸存在，對手將怪獸特殊召喚的場合，以其中1隻為對象可以發動。那隻怪獸破壞，給予對手那個原攻擊力一半數值的傷害。\u000a②：此卡在墓地存在的狀態，我方或對手受到效果傷害的場合，將此卡除外，以我方的墓地、除外狀態的1張通常魔法卡為對象可以發動。那張卡在我方場上覆蓋。那張卡在這個回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99177923,'無限地獄惡魔',unistr('①：我方的手牌是0張的狀態，抽到此卡時，向對手展示此卡可以發動。此卡從手牌特殊召喚。\u000a②：此卡特殊召喚時可以發動（此效果在我方的手牌是0張的場合可以發動和處理）。從牌組將1張「無限地獄」卡片加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99185129,'輝劍的影靈衣',unistr('藉由「影靈衣」儀式魔法卡降臨\u000a此卡只能用儀式召喚來特殊召喚。\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。從牌組將1張「影靈衣」魔法、陷阱卡加入手牌。\u000a②：我方、對手回合，以從額外牌組特殊召喚的場上1隻表側表示怪獸為對象可以發動。直到回合結束時，那隻怪獸的攻擊力變成0，效果無效化。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99188141,'反大革命','①：會讓2張以上場上的卡被破壞的怪獸的效果、魔法、陷阱卡發動時可以發動。那個發動無效並除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99189322,'大秘儀呼喚','選擇我方場上的1隻表側表示的「大秘儀之力」怪獸，選擇雙方墓地的1隻「大秘儀之力」怪獸除外。直到結束階段時，那隻場上的怪獸投擲硬幣得到的效果，變成和那隻除外的怪獸投擲硬幣得到的效果相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99193444,'轟海皇 波塞德拉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的手牌、場上（表側表示）將1隻其他的水屬性怪獸送去墓地可以發動。此卡從手牌特殊召喚。\u000a②：此卡召喚、特殊召喚的場合，從牌組將1隻「海皇」怪獸或「水精鱗」怪獸送去墓地，以對手場上1張卡為對象可以發動。那張卡回到手牌。\u000a③：只要我方場上有「轟海皇 波塞德拉」以外的怪獸存在，對手怪獸不能選擇此卡作為攻擊對象。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99199231,'S-Force本源',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方的手牌、墓地、除外狀態的1隻「S-Force」怪獸特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。\u000a②：此卡在墓地存在的狀態，其他卡被除外的場合，將此卡除外可以發動。從牌組挑選「S-Force本源」以外的2張「S-Force」卡片，其中1張除外，另1張送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99212922,'白龍忍者',unistr('此卡特殊召喚的場合，只能用「忍法」卡片的效果特殊召喚。\u000a只要此卡在場上表側表示存在，我方場上的魔法、陷阱卡不會被效果破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99214782,'侵入魔的步哨','只要此卡在場上表側攻擊表示存在，場上的等級5以上的特殊召喚的怪獸不能發動效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99217226,'團結與牽絆的超魔導劍士',unistr('協調+協調以外的原攻擊力和原守備力是2500的怪獸1隻以上\u000a①：只要同步召喚的此卡在怪獸區域存在，此卡不會被對手的效果破壞，對手不能將此卡作為效果的對象。\u000a②：只要我方墓地有25張以上卡存在，同步召喚的此卡的攻擊力、守備力上升雙方的場上、墓地的卡片數量×100。\u000a③：1回合1次，對手墓地有25張以上卡存在，魔法卡發動時可以發動。那個發動無效並破壞。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99229085,'奇巧人偶-悲鳴牛',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：去除我方場上的1個超量素材可以發動。此卡從手牌、墓地特殊召喚。此效果特殊召喚的此卡從場上離開的場合被除外。\u000a②：持有此卡作為素材的「奇巧人偶」超量怪獸得到以下效果。\u000a●1回合1次，以對手墓地1隻怪獸為對象可以發動。那隻怪獸在對手場上守備表示特殊召喚。'),'效果1','●在對手場上特殊召喚（奇巧人偶-悲鳴牛）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99234526,'輝白龍 暴源翼龍',unistr('此卡不能通常召喚。只能從我方墓地將1隻闇屬性怪獸除外來特殊召喚。這個方法的「輝白龍 暴源翼龍」的特殊召喚1回合只能有1次。\u000a①：此卡從場上送去墓地的場合可以發動。從牌組將1隻「暗黑龍 坍縮星蛇」加入手牌。'),'檢索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99243014,'同步超車',unistr('這個卡名的卡在1回合只能發動1張，此卡發動的整回合中，我方除了同步怪獸以外不能從額外牌組特殊召喚。\u000a①：向對手展示額外牌組的1隻同步怪獸，從我方的牌組、墓地選1隻在那隻怪獸有記載卡名的同步素材怪獸加入手牌或特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99249638,'聯合駕駛員',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：1回合1次，可以發動1個以下效果。\u000a●以我方場上1隻表側表示怪獸為對象，此卡當作裝備卡給那隻怪獸裝備。裝備怪獸被戰鬥、效果破壞的場合，將此卡破壞作為代替。\u000a●裝備的此卡特殊召喚。\u000a②：將裝備的此卡除外可以發動。此卡裝備過的怪獸將可以裝備的1隻等級4以下的聯合怪獸當作來自那個效果的裝備魔法卡從牌組裝備。'),'N/A','N/A','效果2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99261403,'黑暗兔寶寶','美國漫畫世界的兔子。動作非常迅速，不停地跳來跳去。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99266988,'混沌領域',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌將1隻光、闇屬性的怪獸送去墓地可以發動。從牌組將1隻和那隻怪獸屬性不同，等級4～8的不能通常召喚的光、闇屬性怪獸加入手牌。\u000a②：將墓地的此卡除外，從被除外的我方怪獸之中，以1隻不能通常召喚的光、闇屬性怪獸為對象可以發動。那隻怪獸回到牌組最下方。那之後，我方從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99267150,'FGD 五頭神龍',unistr('龍族怪獸×5\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡不會被闇、地、水、炎、風屬性怪獸戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99267151,'FGD 五頭神龍',unistr('龍族怪獸×5\u000a此卡只能用融合召喚來特殊召喚。\u000a①：此卡不會被闇、地、水、炎、風屬性怪獸戰鬥破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99274184,'水晶機巧衝擊',unistr('①：以被除外的1隻我方的「水晶機巧」怪獸為對象可以發動。那隻怪獸特殊召喚，對手場上有表側表示怪獸存在的場合，那些對手怪獸的守備力變成0。\u000a②：以我方場上的「水晶機巧」怪獸為對象的魔法、陷阱、怪獸的效果發動時，將墓地的此卡除外可以發動。那個效果無效。此效果在此卡送去墓地的回合不能發動。'),'效果無效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99284890,'壺魔神','從手牌將1張「強欲之壺」送去墓地可以發動。從我方牌組抽3張卡。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99289828,'白森林的傳說',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有幻想魔族或魔法使族怪獸存在的場合可以發動。從牌組將1隻「白森林」怪獸加入手牌。\u000a②：此卡為了發動怪獸的效果而被送去墓地的場合可以發動。此卡在我方場上覆蓋。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99307040,'荷魯斯的黑炎神',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方場上有「荷魯斯」怪獸以及「王之棺」存在的場合，向對手展示手牌的此卡，將我方的手牌、場上1張卡送去墓地可以發動。場上1張卡送去墓地。\u000a②：「荷魯斯的黑炎神」以外的我方場上的表側表示的「荷魯斯」怪獸或「王之棺」因對手的效果從場上離開的場合可以發動。此卡從手牌特殊召喚。那之後，可以將場上的其他怪獸全部送去墓地。'),'','','是否將場上的其他怪獸全部送去墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99311109,'戰友的誓言','我方場上沒有從額外牌組特殊召喚的怪獸存在的場合，選擇對手場上的1隻從額外牌組特殊召喚的表側表示怪獸可以發動。直到結束階段時得到那隻怪獸的控制權。此卡發動的整回合中，我方不能將怪獸特殊召喚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99311889,'絕境獄神域-皮萊亞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從我方的額外牌組、場上（表側表示）、墓地挑選「創獄神 涅路瓦」「壞獄神 朱庇特」「調獄神 朱諾拉」各1隻給雙方確認，這個回合，應對我方的「獄神」怪獸的效果的發動，對手不能發動效果。\u000a②：為了發動我方場上的「獄神」怪獸的效果而從牌組上方將卡除外的場合，可以將墓地的此卡除外作為代替。'),'效果1','是否將「絕境獄神域-皮萊亞」除外作為代替？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99315585,'魅影騎士團 裂頭盔',unistr('「魅影騎士團 裂頭盔」的①②效果1回合各能使用1次。\u000a①：「魅影騎士團」卡片或「魅影」魔法、陷阱卡被送去我方墓地的場合發動。此卡的攻擊力上升500。\u000a②：將墓地的此卡除外可以發動。這個回合的結束階段，從我方墓地選1張「魅影騎士團」卡片或「魅影」魔法、陷阱卡加入手牌。'),'攻擊力上升','從牌組加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99328137,'冰騎士',unistr('①：此卡的攻擊力上升我方場上的水族怪獸數量×400。\u000a②：1回合1次，我方主要階段可以發動。這個回合，我方在通常召喚之外只有1次，在我方主要階段可以召喚1隻水屬性怪獸。此效果的發動後，直到回合結束時我方除了水屬性怪獸以外不能召喚、特殊召喚。'),'效果2','召喚水屬性怪獸（冰騎士）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99330325,'被妨礙的壞獸安眠',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：場上的怪獸全部破壞。那之後，從牌組將卡名不同的「壞獸」怪獸在我方、對手的場上各1隻攻擊表示特殊召喚。此效果特殊召喚的怪獸不能變更表示形式，可以攻擊的場合必須攻擊。\u000a②：將墓地的此卡除外可以發動。從牌組將1隻「壞獸」怪獸加入手牌。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','選擇在我方場上特殊召喚的怪獸','選擇在對手場上特殊召喚的怪獸','「被妨礙的壞獸安眠」的效果1適用中','','','','','','','','','','','');
INSERT INTO texts VALUES(99342953,'遠古遺跡 代號A',unistr('每次場上表側表示存在的「外星人」怪獸被破壞，給此卡放置1個A計數器。\u000a1回合1次，可以藉由去除場上的2個A計數器，選擇我方墓地的1隻「外星人」怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99348756,'女武神騎士',unistr('①：只要此卡在怪獸區域存在，對手不能選擇「女武神騎士」以外的戰士族怪獸作為攻擊對象。\u000a②：此卡被戰鬥破壞送去墓地時，從我方墓地將1隻戰士族怪獸和此卡除外，以我方墓地1隻等級5以上的戰士族怪獸為對象可以發動。那隻戰士族怪獸特殊召喚。'),'特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99351431,'盜賊的極意',unistr('主要階段1，選擇場上表側表示存在的1隻怪獸可以發動。\u000a這個回合，選擇的怪獸給予對手戰鬥傷害時，對手隨機選1張手牌捨棄。'),'捨棄手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99357565,'D3',unistr('「D3」的②③效果1回合各能使用1次。\u000a①：此卡召喚成功的場合發動。這隻怪獸在表側表示存在期間，也當作「D-HERO」怪獸。\u000a②：將最多2張手牌捨棄可以發動。從我方的手牌、牌組、墓地選捨棄數量的「D3」特殊召喚。此效果的發動後，直到回合結束時我方除了「D-HERO」怪獸以外不能召喚、特殊召喚。\u000a③：此卡被戰鬥、效果破壞的場合可以發動。從牌組將1隻「D-HERO」怪獸送去墓地。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99365553,'光脈衝星龍','此卡可以將我方墓地的光屬性與闇屬性怪獸各1隻從遊戲中除外來從手牌特殊召喚。此外，可以將手牌的光屬性與闇屬性怪獸各1隻送去墓地來讓此卡從我方墓地特殊召喚。此卡從場上送去墓地時，可以選擇我方墓地1隻龍族、闇屬性、等級5以上的怪獸特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99370594,'劫火的長眠姬 幽靈睡美人',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡被送去墓地的場合可以發動。從牌組將1張「幽合-幽靈結合」加入手牌。\u000a②：將墓地的此卡除外，捨棄1張手牌，以被除外的1隻我方的等級4以上的不死族怪獸為對象可以發動。那隻怪獸加入手牌。此效果在此卡送去墓地的回合不能發動。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99397762,'光波防輪','①：以我方場上1隻「銀河眼」超量怪獸或「光波」超量怪獸為對象可以發動。此卡重疊在那隻怪獸下方作為超量素材，那隻怪獸在這個回合有1次不會被戰鬥、效果破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99398682,'深紅地獄呼喚',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：從我方墓地將1隻等級4以下的惡魔族怪獸加入手牌。我方場上有「暗紅惡魔龍」或記載那個卡名的同步怪獸存在的場合，加入手牌的怪獸也能從牌組挑選。\u000a②：我方的「/爆裂」怪獸或「暗紅惡魔龍」攻擊的傷害步驟結束時，將墓地的此卡除外可以發動。那隻攻擊怪獸只有1次可以繼續攻擊。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99414168,'精靈術師 多莉雅德',unistr('藉由「多莉雅德的祈禱」降臨。\u000a此卡的屬性也當作「風」「水」「炎」「地」。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99414629,'恐啡肽狂龍殘虐',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：支付一半生命值可以發動。選我方場上1隻「恐啡肽狂龍」怪獸和對手場上1張卡破壞。\u000a②：我方的生命值是2000以下，對手發動魔法、陷阱、怪獸的效果時，將墓地的此卡除外可以發動。這個回合，對手的效果產生給我方的效果傷害變成0。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99423156,'不知火的宮司',unistr('「不知火的宮司」的②效果1回合只能使用1次。\u000a①：此卡召喚成功時可以發動。從我方的手牌、墓地選「不知火的宮司」以外的1隻「不知火」怪獸特殊召喚。此效果特殊召喚的怪獸從場上離開的場合被除外。\u000a②：此卡被除外的場合，以對手場上1張表側表示的卡為對象可以發動。那張卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99426088,'魔鍵-馬夫提亞','①：「魔鍵」融合怪獸卡決定的融合素材怪獸從我方的手牌、場上送去墓地，從額外牌組融合召喚那1隻融合怪獸。或者，解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌將1隻「魔鍵」儀式怪獸儀式召喚。我方場上有通常怪獸存在的場合，也能將牌組的1隻通常怪獸送去墓地作為融合素材怪獸或為了儀式召喚而解放的怪獸。','融合召喚','儀式召喚','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99426834,'沼地的魔獸王','手牌、場上、墓地的此卡可以代替在融合怪獸卡有記載卡名的1隻融合素材怪獸。此時其他的融合素材怪獸必須是正規的卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99427357,'電子天使－那沙帝彌－',unistr('藉由「機械天使的儀式」降臨。\u000a①：1回合1次，以我方場上1隻表側表示怪獸為對象可以發動。我方的生命值回復那隻怪獸的攻擊力的一半數值。\u000a②：我方的儀式怪獸被選擇作為攻擊對象時可以發動。那次攻擊無效。\u000a③：此卡在墓地存在的場合，從我方墓地將此卡以外的1隻「電子天使」怪獸除外，以對手場上1隻怪獸為對象可以發動。此卡從墓地特殊召喚，得到對象怪獸的控制權。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99429730,'森羅的番人 橡樹',unistr('1回合1次，我方主要階段可以發動。從我方牌組上方翻開最多3張卡。如果翻開的卡包含植物族怪獸，那些怪獸全部送去墓地。剩下的卡以喜歡的順序回到牌組最下方。\u000a此外，牌組的此卡被效果翻開送去墓地的場合，可以從我方墓地選擇此卡以外的1隻植物族怪獸回到牌組最上方。'),'翻開','請選擇翻開的數量','回到牌組最上方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99456344,'死獄鄉的大導劇神',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：融合、同步、超量、連結怪獸特殊召喚的場合，以場上1隻效果怪獸為對象可以發動。那隻怪獸的效果直到回合結束時無效。\u000a②：手牌、場上的此卡成為融合召喚的素材，被送去墓地的場合或被除外的場合可以發動。此卡特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99458769,'暗黑界的魔神 瑞恩',unistr('①：此卡被對手的效果從手牌捨棄到墓地的場合發動。此卡特殊召喚。\u000a②：此卡的①效果特殊召喚成功的場合發動。從以下效果挑選1個適用。\u000a●對手場上的怪獸全部破壞。\u000a●對手場上的魔法、陷阱卡全部破壞。'),'效果1','效果2','●對手場上的怪獸全部破壞。','●對手場上的魔法、陷阱卡全部破壞。','','','','','','','','','','','','');
INSERT INTO texts VALUES(99469936,'全裝甲-晶零槍兵',unistr('水屬性等級6怪獸×3\u000a此卡也能重疊在我方場上的階級5的水屬性超量怪獸上方來超量召喚。\u000a①：此卡的攻擊力上升此卡的超量素材數量×500。\u000a②：1回合1次，去除此卡的1個超量素材可以發動。對手場上的全部表側表示怪獸的效果直到回合結束時無效。\u000a③：場上的此卡被戰鬥、效果破壞的場合，可以去除此卡的1個超量素材作為代替。'),'是否重疊在階級5的超量怪獸上方超量召喚？','N/A','效果無效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99471856,'水晶機巧-三位玉晶',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：對手發動效果時可以發動。從牌組將「水晶機巧-三位玉晶」以外的1隻「水晶機巧」怪獸特殊召喚。那之後，用包含那隻的我方場上的怪獸為素材進行1隻機械族同步怪獸的同步召喚。\u000a②：將墓地的此卡除外可以發動。我方場上1隻同步怪獸破壞，從牌組將2隻「水晶機巧」怪獸特殊召喚。這個回合，我方除了機械族怪獸以外不能從額外牌組特殊召喚。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99510761,'神燈的魔人','從神燈裡出現的魔人，服從召喚者的意志。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99517131,'生命力吸收魔術','場上的全部裡側守備表示怪獸變成表側表示。此時，反轉怪獸的效果不發動。我方回復場上的效果怪獸數量×400生命值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99518961,'革命','給予對手相當於對手的手牌數量×200傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99523325,'守墓的石板','選擇我方墓地的2隻「守墓」怪獸加入手牌。此效果不受「王家長眠之谷-死亡谷」的效果影響。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99529628,'游魊之朧 基夫',unistr('這個卡名的①②③效果1回合各能使用1次。\u000a①：場上有魚族怪獸存在的場合可以發動。此卡從手牌特殊召喚。\u000a②：對手場上有怪獸特殊召喚的場合，以其中1隻怪獸和我方的除外狀態的1隻等級6以下的魚族怪獸為對象可以發動。作為對象的對手怪獸和此卡除外，作為對象的我方怪獸特殊召喚。\u000a③：此卡被除外的下個回合的準備階段可以發動。除外狀態的此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99531088,'侏羅紀力量',unistr('這個卡名的③效果1回合只能使用1次。\u000a①：我方場上的恐龍族怪獸的攻擊力上升300。\u000a②：我方將等級5以上的恐龍族怪獸召喚的場合可以不用解放。\u000a③：從我方的手牌、場上（表側表示）將1隻恐龍族怪獸送去墓地可以發動。從牌組將1隻守備力1200的恐龍族怪獸加入手牌。'),'不解放的召喚（侏羅紀力量）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99532708,'火星外星人','只要此卡在場上表側表示存在，「火星外星人」以外的場上的已放置A計數器的效果怪獸的效果無效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99543666,'烙印劇城 死獄鄉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：我方主要階段可以發動。我方的手牌、場上的怪獸作為融合素材，將1隻等級8以上的融合怪獸融合召喚。\u000a②：融合怪獸以外的我方場上的表側表示的天使族怪獸因對手的效果從場上離開的場合，或被戰鬥破壞的場合，以我方墓地1隻等級8以上的融合怪獸為對象可以發動。那隻怪獸特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99550630,'閃刀術式-後燃器','①：我方的主要怪獸區域沒有怪獸存在的場合，以場上1隻表側表示怪獸為對象可以發動。那隻怪獸破壞。那之後，我方墓地有3張以上魔法卡存在的場合，可以選場上1張魔法、陷阱卡破壞。','是否破壞1張魔法、陷阱卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99551425,'迷宮的魔戰車','「高科技狼」+「加農砲兵」','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99581584,'守衛企鵝','卡的效果讓我方受到傷害時可以發動。此卡從手牌特殊召喚，我方的生命值回復受到的傷害數值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99585850,'緋暗紅超新星龍',unistr('協調3隻+協調以外的同步怪獸1隻以上\u000a此卡只能用同步召喚從額外牌組特殊召喚。\u000a①：此卡的攻擊力上升我方墓地的協調數量×500。\u000a②：場上的此卡不會被對手的效果破壞。\u000a③：1回合1次，對手發動怪獸的效果時，或對手怪獸的攻擊宣言時可以發動。此卡以及對手場上的卡全部除外。\u000a④：此卡的③效果除外的場合，下個我方結束階段發動。除外狀態的此卡特殊召喚。'),'效果3','效果4','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99585851,'緋暗紅超新星龍',unistr('協調3隻+協調以外的同步怪獸1隻以上\u000a此卡只能用同步召喚從額外牌組特殊召喚。\u000a①：此卡的攻擊力上升我方墓地的協調數量×500。\u000a②：場上的此卡不會被對手的效果破壞。\u000a③：1回合1次，對手發動怪獸的效果時，或對手怪獸的攻擊宣言時可以發動。此卡以及對手場上的卡全部除外。\u000a④：此卡的③效果除外的場合，下個我方結束階段發動。除外狀態的此卡特殊召喚。'),'效果3','效果4','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99590524,'狡猾的落穴','①：我方墓地沒有陷阱卡存在的場合，以場上2隻怪獸為對象可以發動。那些怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99594764,'龍盟-蝠翼槍龍','①：將此卡當作裝備卡來裝備的怪獸戰鬥破壞對手怪獸時可以發動。從牌組將1隻種族、屬性和裝備怪獸相同的等級4以下的怪獸加入手牌。','效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99597615,'魔鬼的香吻',unistr('①：裝備怪獸的攻擊力上升700。\u000a②：此卡從場上送去墓地時，支付500生命值可以發動。此卡回到牌組最上方。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99599062,'地縛融合',unistr('這個卡名的②效果1回合只能使用1次。此卡在場地區域沒有卡存在的場合，只能在我方、對手的主要階段發動。\u000a①：我方的手牌、場上的怪獸作為融合素材，將1隻闇屬性融合怪獸融合召喚。\u000a②：場地區域有卡存在的場合，我方主要階段將墓地的此卡除外可以發動。從我方的手牌、墓地將1隻「地縛」怪獸特殊召喚。這個回合，我方除了融合、同步怪獸以外不能從額外牌組特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99628747,'巨石遺物 貝托爾',unistr('藉由「巨石遺物」卡片降臨。這個卡名的①②效果1回合各能使用1次。\u000a①：將此卡從手牌捨棄可以發動。解放我方的手牌、場上的怪獸，直到等級合計為儀式召喚的怪獸的等級以上為止，從手牌儀式召喚1隻「巨石遺物」儀式怪獸。\u000a②：此卡儀式召喚成功的場合，最多到我方墓地的儀式怪獸種類的數量，以對手場上的卡為對象可以發動。那些卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99634927,'魔界劇團-時髦諧星',unistr('【靈擺效果】\u000a①：1回合1次，解放我方場上1隻「魔界劇團」怪獸，以我方場上1隻「魔界劇團」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升解放的怪獸的原攻擊力數值。\u000a【怪獸效果】\u000a「魔界劇團-時髦諧星」的②怪獸效果1回合只能使用1次，發動的整回合中此卡不能攻擊。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。此卡的攻擊力直到回合結束時上升我方場上的「魔界劇團」怪獸數量×300。\u000a②：以此卡以外的我方場上1隻「魔界劇團」怪獸為對象可以發動。那隻怪獸的攻擊力直到回合結束時上升此卡的攻擊力數值。'),'攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99641328,'森羅的影孢子 傘菌',unistr('此卡反轉時，可以從我方牌組上方翻開最多5張卡。如果翻開的卡包含植物族怪獸，那些怪獸全部送去墓地。剩下的卡以喜歡的順序回到牌組最下方。\u000a此外，牌組的此卡被效果翻開送去墓地的場合，可以選擇場上的1張魔法、陷阱卡破壞。'),'翻開','請選擇翻開的數量','破壞','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99645428,'寶石騎士 小琉','經常關心伙伴們健康狀況的療癒系戰士。與小璃是非常要好的朋友。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99657399,'粗心大意','對手的生命值回復時可以發動。選擇對手場上存在的1隻怪獸破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99659159,'馭龍術',unistr('①：已裝備「龍盟」怪獸卡的我方場上的怪獸的攻擊力上升500。\u000a②：1回合1次，以我方場上1隻表側表示怪獸為對象可以發動。從手牌將1隻龍族的「龍盟」怪獸當作裝備卡給作為對象的我方怪獸裝備。'),'效果2','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99666430,'人造人-念力層疊者',unistr('等級6怪獸×2\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：去除此卡的1個超量素材，以對手場上1隻表側表示怪獸為對象可以發動。直到結束階段得到那隻怪獸的控制權。此效果得到控制權的怪獸不能發動效果，不能攻擊宣言。\u000a②：場上有陷阱卡存在的場合可以發動。將我方場上1隻怪獸解放，選場上1張表側表示的卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99668578,'衛星騎士 南河三',unistr('「衛星騎士 南河三」的效果1回合只能使用1次。\u000a①：此卡召喚、反轉召喚、特殊召喚成功的場合可以發動。從手牌將1隻「星騎士」怪獸送去墓地，從牌組抽1張卡。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99674361,'星遺物的繼承者',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻怪獸為對象可以發動。那隻怪獸在場上的連結怪獸指向的我方場上特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99675356,'紫炎的步兵','此卡戰鬥破壞送去墓地時，可以從牌組將1隻等級3以下的「六武眾」怪獸在我方場上特殊召喚。','特殊召喚','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99690140,'守墓的從者','此卡給予對手的戰鬥傷害當作效果傷害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99707692,'RR-漆黑伯勞',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚的回合的我方主要階段，以我方場上1隻「RR-」怪獸為對象可以發動。從牌組將1隻和那隻怪獸等級不同的「RR-」怪獸加入手牌。\u000a②：將墓地的此卡除外可以發動。我方場上的「RR-」怪獸的等級全部上升1或全部下降1。'),'','','等級上升1','等級下降1','','','','','','','','','','','','');
INSERT INTO texts VALUES(99721536,'骷髏機車手','藉由「骷髏機車手的復活」降臨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99724761,'XZ-履帶加農砲',unistr('「X-首領加農」+「Z-金屬履帶」\u000a只能將我方場上的上述卡除外，從額外牌組特殊召喚。此卡不能從墓地特殊召喚。\u000a①：捨棄1張手牌，以對手場上1張裡側表示的魔法、陷阱卡為對象可以發動。那張對手的裡側表示的卡破壞。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99726621,'鐵獸戰線 凶鳥的施萊格',unistr('獸族、獸戰士族、鳥獸族怪獸2隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，或我方場上有其他的獸族、獸戰士族、鳥獸族怪獸特殊召喚的場合可以發動。場上1張卡除外。\u000a②：此卡被送去墓地的場合可以發動。從牌組將1隻等級在我方的除外狀態的獸族、獸戰士族、鳥獸族怪獸數量以下的獸族、獸戰士族、鳥獸族怪獸加入手牌。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99733359,'盾航戰車 電子劍龍',unistr('「盾航戰車 電子劍龍」的效果1回合只能使用1次。\u000a①：此卡在墓地存在，對手怪獸攻擊的場合，那次傷害計算時，支付1000生命值可以發動。此卡從墓地特殊召喚，那次戰鬥產生給我方的戰鬥傷害變成0。此效果特殊召喚的此卡從場上離開的場合被除外。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99735427,'吸收黑暗的魔鏡','只要此卡在場上存在，在場上、墓地發動的闇屬性怪獸的效果無效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99742859,'救援刺蝟',unistr('這個卡名的效果1回合只能使用1次。\u000a①：將場上的此卡除外可以發動。從牌組將等級3以下且種族、屬性、等級相同的通常怪獸和效果怪獸各1隻特殊召喚。此效果特殊召喚的怪獸的效果無效化，在結束階段破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99745551,'未界域的野槌蛇',unistr('這個卡名的②效果1回合只能使用1次。\u000a①：向對手展示手牌的此卡可以發動。對手從我方的全部手牌中隨機選1張，我方捨棄那張卡。那是「未界域的野槌蛇」以外的場合，隨後從手牌將1隻「未界域的野槌蛇」特殊召喚，我方從牌組抽1張卡。\u000a②：此卡從手牌捨棄的場合可以發動。此卡特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99747800,'傳說的魔鬼','①：我方準備階段發動。此卡的攻擊力上升700。','攻擊力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99748883,'流星連打-白黑機人',unistr('這個卡名的①效果1回合只能使用1次。\u000a①：5次以上攻擊宣言的回合的戰鬥階段可以發動。此卡從手牌特殊召喚。此效果在對手回合也能發動。\u000a②：此卡進行戰鬥的傷害步驟期間，此卡的攻擊力上升這個回合中回合玩家攻擊宣言的次數×1000。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99785935,'磁石戰士α','湊齊α、β、γ3隻可以合體。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99788587,'爆導索','①：和此卡相同縱列全部都有卡存在的場合，可以發動覆蓋的此卡。那個縱列的卡全部破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99789342,'黑魔術的布幕',unistr('此卡發動的整回合中，我方不能用此卡的效果以外將怪獸召喚、反轉召喚、特殊召喚。\u000a①：支付一半生命值可以發動。從牌組將1隻「黑魔導」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99792080,'夢魔鏡的魔獸-方塔斯',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡用「夢魔鏡」怪獸的效果特殊召喚成功的場合可以發動。這個回合，此卡可以直接攻擊。\u000a②：場地區域有「聖光的夢魔鏡」存在的場合，我方、對手的主要階段以及戰鬥階段，解放此卡可以發動。從牌組將1隻「夢魔鏡的聖獸-方塔斯」特殊召喚。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99795159,'鬼計屋',unistr('①：只要此卡在場地區域存在，雙方的怪獸不能向裡側守備表示怪獸攻擊，可以在對手場上的怪獸只有裡側守備表示怪獸的場合向對手直接攻擊。\u000a②：只要此卡在場地區域存在，雙方受到的效果傷害變成一半，「鬼計」怪獸以外的怪獸給予玩家的戰鬥傷害變成一半。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99801464,'銀翼的斧配飾-莎莉',unistr('這個卡名的效果1回合只能使用1次。\u000a①：以場上1隻表側表示怪獸為對象可以發動。從我方的手牌、場上將此卡當作攻擊力、守備力上升100的裝備卡給那隻怪獸裝備。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99861526,'潛艇機人',unistr('此卡可以直接攻擊對手玩家。此時給予對手的戰鬥傷害為此卡的原攻擊力數值。\u000a此卡進行戰鬥的傷害步驟結束時可以發動。此卡變成守備表示。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99865167,'旋風結構體','風屬性通常怪獸上級召喚的場合，此卡可以當作2隻解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99877698,'守墓的火砲兵','將「守墓的火砲兵」以外的我方場上1隻「守墓」怪獸解放可以發動。給予對手700傷害。','傷害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99885917,'海晶少女 紫紅擬花鮨',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：此卡召喚、特殊召喚成功的場合可以發動。從手牌將「海晶少女 紫紅擬花鮨」以外的1隻「海晶少女」怪獸守備表示特殊召喚。\u000a②：將墓地的此卡除外，以我方墓地1張「海晶少女」魔法、陷阱卡為對象可以發動。那張卡加入手牌。此效果在此卡送去墓地的回合不能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99890852,'花樣明星花束',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：以我方場上1隻「花樣明星」怪獸和場上1隻表側表示怪獸為對象可以發動。那隻「花樣明星」怪獸回到持有者的手牌，另1隻作為對象的怪獸的攻擊力直到回合結束時上升回到手牌的怪獸的原攻擊力數值。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99899504,'骷髏火焰',unistr('1回合1次，可以從手牌將1隻「燃燒骷髏頭」特殊召喚。此效果發動的整回合中，我方不能進行戰鬥階段。\u000a我方的抽牌階段時，可以作為進行通常抽牌的代替，選擇我方墓地的1隻「燃燒骷髏頭」加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99902789,'小鬆獅犬','和對手怪獸進行戰鬥的我方怪獸的攻擊宣言時對手發動通常陷阱卡時，從手牌捨棄此卡可以發動。那個發動無效並破壞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99910751,'落單毛毛',unistr('①：只要此卡在場上、墓地存在，卡名當作「毛毛」，且當作通常怪獸。\u000a②：將此卡從手牌捨棄可以發動。從牌組將「落單毛毛」以外的1張「毛毛」卡片加入手牌。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99913726,'捕食植物 露松水螅龍',unistr('這個卡名的①方法的特殊召喚1回合只能有1次，②效果1回合只能使用1次。\u000a①：此卡可以解放我方或對手場上的1隻已放置捕食計數器的怪獸，從手牌、墓地特殊召喚。\u000a②：此卡在場上、墓地存在的場合，將此卡以外的我方墓地1隻「捕食植物」怪獸除外，以場上1隻怪獸為對象可以發動。那隻怪獸的攻擊力下降500。此效果在對手回合也能發動。'),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99916754,'大植然龍獸',unistr('「大植然獸」+「大植然龍」\u000a此卡的融合召喚只能使用上述卡進行。\u000a①：魔法、陷阱卡發動時，從我方墓地將1張卡除外，將牌組最上方的卡送去墓地可以發動。此卡在場上表側表示存在的場合，那個發動無效並破壞。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99927991,'魔救的奇緣','①：從我方牌組上方翻開我方場上的岩石族怪獸數量+5張卡。可以從其中選1隻等級在翻開的卡片張數以下的岩石族怪獸加入手牌。剩下的卡以喜歡的順序回到牌組最下方。此卡的發動後，直到回合結束時我方除了岩石族怪獸以外不能特殊召喚。','是否選1張卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99937011,'劍神官 姆多拉',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：從手牌捨棄1隻其他的天使族、地屬性怪獸可以發動。此卡從手牌特殊召喚。那之後，可以從牌組選1張「守墓的陷阱」在我方的魔法與陷阱區域表側表示放置。\u000a②：我方、對手回合，將場上、墓地的此卡除外，以我方、對手的墓地的卡合計最多3張為對象可以發動（我方的場上或墓地有「現世與冥界的逆轉」存在的場合，此效果的對象變成最多5張）。那些卡回到牌組。'),'是否從牌組選1張「守墓的陷阱」放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99937842,'T.G. 星之守護者',unistr('協調+協調以外的「T.G.」怪獸1隻以上\u000a這個卡名的①②效果1回合各能使用1次。\u000a①：此卡特殊召喚的場合，以我方墓地1隻「T.G.」怪獸為對象可以發動。那隻怪獸加入手牌。\u000a②：我方主要階段可以發動。從手牌將1隻「T.G.」怪獸特殊召喚。\u000a③：對手主要階段可以發動。用包含此卡的我方場上的怪獸為素材進行同步召喚。'),'效果1','效果2','效果3','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99940363,'帝王的凍氣',unistr('①：我方場上有攻擊力2400以上且守備力1000的怪獸存在的場合，以場上覆蓋的1張卡為對象可以發動。那張卡破壞。\u000a②：從我方墓地將此卡和1張「帝王」魔法、陷阱卡除外，以場上覆蓋的1張卡為對象可以發動。那張卡破壞。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99941223,'佚樂的墮天使',unistr('這個卡名的卡在1回合只能發動1張。\u000a①：我方的手牌、場上、墓地的怪獸作為融合素材除外，將1隻天使族、闇屬性的融合怪獸融合召喚。將「墮天使」融合怪獸融合召喚的場合，對手場上的「墮天使」怪獸也能作為融合素材。此效果特殊召喚的怪獸的攻擊力上升1000。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99946920,'魔龍星-饕餮',unistr('「魔龍星-饕餮」的①效果1回合只能使用1次。\u000a①：我方場上的此卡被戰鬥、效果破壞送去墓地時可以發動。從牌組將「魔龍星-饕餮」以外的1隻「龍星」怪獸守備表示特殊召喚。\u000a②：1回合1次，對手的主要階段以及戰鬥階段可以發動。只用我方場上的「龍星」怪獸為同步素材同步召喚。\u000a③：用此卡為同步素材的同步怪獸的控制權不能變更。'),'特殊召喚','控制權不能變更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99984170,'RESCUE！',unistr('這個卡名在規則上也當作「R-ACE」卡片。這個卡名的卡在1回合只能發動1張。\u000a①：以我方墓地1隻「R-ACE」怪獸為對象可以發動（我方場上有「R-ACE 消防栓」存在的場合，也能改成以對手墓地1隻怪獸為對象）。那隻怪獸在我方場上特殊召喚。'),'效果1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99989863,'刻魔的樂園',unistr('這個卡名的①②效果1回合各能使用1次。\u000a①：以我方場上1隻等級7以上的惡魔族、光屬性怪獸為對象可以發動。那隻怪獸以外的場上的卡全部送去墓地。\u000a②：此卡在墓地存在的狀態，對手將怪獸特殊召喚的場合，將此卡除外可以發動。從牌組、額外牌組將1隻「刻魔」怪獸送去墓地。'),'效果1','效果2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99991455,'霸雷星 雷神',unistr('等級5以上的戰士族、光屬性怪獸+戰士族、地屬性怪獸\u000a這個卡名的③效果1回合只能使用1次。\u000a①：此卡向守備表示怪獸攻擊的場合，給予攻擊力超過那個守備力的數值的戰鬥傷害。\u000a②：此卡和不持有等級的怪獸的戰鬥給予對手的戰鬥傷害變成2倍。\u000a③：此卡被戰鬥、效果破壞送去墓地的回合的結束階段，以我方墓地2隻等級7以下的戰士族怪獸為對象可以發動。那些怪獸特殊召喚。'),'效果3','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99995595,'電池回收','①：以我方墓地2隻攻擊力1500以下的雷族怪獸為對象可以發動。那些雷族怪獸加入手牌。','','','','','','','','','','','','','','','','');
